const LOCAL_DEV_CHAIN_IDS = new Set([31337, 1337]);
function resolveEthChainId(env) {
  const raw = env?.ETH_CHAIN_ID;
  if (raw === undefined || raw === null || raw === '') return ETH_CHAIN_ID;
  const n = Number(raw);
  return (Number.isInteger(n) && LOCAL_DEV_CHAIN_IDS.has(n)) ? n : ETH_CHAIN_ID;
}
