export function shouldAutoForceGasWait(wait, nowMs = Date.now()) {
  const firstSeenAt = Number(wait?.firstSeenAt);
  return Number.isFinite(firstSeenAt)
    && Number.isFinite(Number(nowMs))
    && Number(nowMs) - firstSeenAt >= GAS_AUTO_FORCE_AFTER_MS;
}
