/**
 * 旧形式の `summary.json` に入っている `claimed` を、新しく組み立てた旧形式 summary へ引き継ぐ。
 *
 * 書き込み競合の網羅調査（2026-07-31）§3 への対処。
 * schema v1/v2 で `claimed` を書くのは listen-worker（請求のたびに patch）だけだった。
 * schema v3 は行別状態を `games/block{N}/claim-status/group{G}.json` へ分離するため、この関数を
 * 呼ばない。旧ブロックの再公開互換だけに残す。
 *
 * 突き合わせは **同一グループ内の userId / depositId** ちょうど一致のみ。
 * 新 summary に無い相手（グループ構成が変わった等）は引き継がない。
 * 新 summary が既に `claimed` を持っている場合は**そちらを優先**する
 * （集計が D1 から読んだ値のほうが新しいため。listen-worker も D1 を権威にしている）。
 *
 * @param {Object} summary  - これから公開する新しい本文（この場で書き換える）
 * @param {Object} existing - R2 にある現在の本文
 * @returns {Object} summary（引き継ぎ後）
 */
export function applyClaimsFromExistingSummary(summary, existing) {
  const isSet = (v) => v !== undefined && v !== null && v !== 0 && v !== '0' && v !== '';

  const claimMap = {};
  for (const group of (existing?.groups || [])) {
    for (const m of (group.members || [])) {
      if (isSet(m.claimed)) claimMap[`player_${group.group_id}_${m.userId}`] = m.claimed;
    }
    for (const d of (group.depositor_results || [])) {
      if (isSet(d.claimed)) claimMap[`dep_${group.group_id}_${d.depositId}`] = d.claimed;
    }
  }
  if (Object.keys(claimMap).length === 0) return summary;

  for (const group of (summary?.groups || [])) {
    for (const m of (group.members || [])) {
      if (isSet(m.claimed)) continue;
      const v = claimMap[`player_${group.group_id}_${m.userId}`];
      if (v !== undefined) m.claimed = v;
    }
    for (const d of (group.depositor_results || [])) {
      if (isSet(d.claimed)) continue;
      const v = claimMap[`dep_${group.group_id}_${d.depositId}`];
      if (v !== undefined) d.claimed = v;
    }
  }
  return summary;
}

export class GameMasterDO {
  constructor(state, env) {
    this.state = state;
    this.env = env;
    this.storage = state.storage;
    if (!singleRpcWarningIssued && rpcProviderCount(rpcReadUrlsFromEnv(env)) === 1) {
      singleRpcWarningIssued = true;
      console.warn('[rpc-quorum] GM の RPC は1本です。本番は独立な RPC を2本以上設定してください');
    }
    this.observationWriteFailureCounter = createObservationWriteFailureCounter();
    this._blockLifecycleCache = new Map();
    // F12: alarm の fail-open 復活走査は止めず、同じ DO isolate の /status へ
    // 観測結果だけを載せる。追加 writer を作らない点は F10 の「読み出し底」と同じ。
    this._phaseTaskResurrectionObservation = { state: 'not_attempted', at: null };
    this.releaseTime = env.RELEASE_TIME ? Date.parse(env.RELEASE_TIME) : null;

    // フェーズ遷移タイミング（ミリ秒・v3.2: TERM1撤廃・GAME_PERIOD/SUBMIT_PERIOD改名）
    this.gamePeriodMs = env.GAME_PERIOD ? parseInt(env.GAME_PERIOD) : 86400000; // 24h
    this.submitPeriodMs = env.SUBMIT_PERIOD ? parseInt(env.SUBMIT_PERIOD) : 86400000; // 24h
  }

  // A3-a1: 本処理から独立したbest-effort観測。state.waitUntilへ渡すので、観測用の
  // storage I/Oを本来の処理のクリティカルパスへ足さない。書込み失敗は同じisolate内の
  // bounded fallbackへ残し、次の /group-status で「観測自体の失敗」として読める。
  deferGroupObservation(blockNum, patchOrFactory) {
    if (!Number.isSafeInteger(Number(blockNum)) || Number(blockNum) < 0) return;
    if (!this._groupObservationFallbacks) this._groupObservationFallbacks = new Map();
    const previous = this._groupObservationTail || Promise.resolve();
    const pending = previous.catch(() => {}).then(async () => {
      const patch = typeof patchOrFactory === 'function'
        ? await patchOrFactory()
        : patchOrFactory;
      if (!patch || typeof patch !== 'object') return;
      const key = `group_observation_block${Number(blockNum)}`;
      const current = await this.storage.get(key) || {
        schemaVersion: GROUP_OBSERVATION_VERSION,
        blockNum: Number(blockNum),
        groups: [],
      };
      const groupPatches = [
        ...(Array.isArray(patch.groupPatches) ? patch.groupPatches : []),
        ...(patch.group ? [patch.group] : []),
      ].slice(0, GROUP_OBSERVATION_GROUP_LIMIT);
      const topPatch = { ...patch };
      delete topPatch.group;
      delete topPatch.groupPatches;
      const merge = (left, right) => {
        const out = { ...(left || {}) };
        for (const [k, v] of Object.entries(right || {})) {
          if (v && typeof v === 'object' && !Array.isArray(v)) out[k] = merge(out[k], v);
          else out[k] = v;
        }
        return out;
      };
      let next = merge(current, topPatch);
      for (const groupPatch of groupPatches) {
        if (!groupPatch || !Number.isSafeInteger(Number(groupPatch.groupId))) continue;
        const groupId = Number(groupPatch.groupId);
        const groups = Array.isArray(next.groups) ? [...next.groups] : [];
        const index = groups.findIndex((g) => Number(g?.groupId) === groupId);
        if (index >= 0) groups[index] = merge(groups[index], { ...groupPatch, groupId });
        else if (groups.length < GROUP_OBSERVATION_GROUP_LIMIT) groups.push({ ...groupPatch, groupId });
        groups.sort((a, b) => Number(a.groupId) - Number(b.groupId));
        next.groups = groups;
      }
      next.schemaVersion = GROUP_OBSERVATION_VERSION;
      next.blockNum = Number(blockNum);
      next.updatedAt = Date.now();
      const pendingWriteFailure = this._groupObservationFallbacks.get(Number(blockNum));
      if (pendingWriteFailure) {
        next.observationWriteFailures = {
          count: Number(next.observationWriteFailures?.count || 0) + Number(pendingWriteFailure.count || 0),
          lastAt: pendingWriteFailure.lastAt,
          lastError: pendingWriteFailure.lastError,
        };
      }
      const bottomPending = captureObservationWriteFailures(
        this.observationWriteFailureCounter,
      );
      if (bottomPending.count > 0) {
        next.observationWriteFailureBottom = {
          count: Number(next.observationWriteFailureBottom?.count || 0) + bottomPending.count,
          lastAt: Date.now(),
          reason: bottomPending.reason,
        };
      }
      await this.storage.put(key, next);
      acknowledgeObservationWriteFailures(this.observationWriteFailureCounter, bottomPending);
      this._groupObservationFallbacks.delete(Number(blockNum));
    });
    this._groupObservationTail = pending.catch((error) => {
      const old = this._groupObservationFallbacks.get(Number(blockNum)) || { count: 0 };
      this._groupObservationFallbacks.set(Number(blockNum), {
        count: old.count + 1,
        lastAt: Date.now(),
        lastError: this.observationErrorText(error),
      });
      recordObservationWriteFailure(
        this.observationWriteFailureCounter,
        'group_observation_write_failed',
      );
      console.error(`[observation] group block ${blockNum} write failed:`, error?.message || error);
    });
    if (typeof this.state?.waitUntil === 'function') this.state.waitUntil(this._groupObservationTail);
  }

  async readGroupObservation(blockNum) {
    if (this._groupObservationTail) await this._groupObservationTail.catch(() => {});
    let persisted = null;
    try { persisted = await this.storage.get(`group_observation_block${Number(blockNum)}`) || null; }
    catch (error) {
      persisted = {
        schemaVersion: GROUP_OBSERVATION_VERSION,
        blockNum: Number(blockNum),
        readFailure: {
          state: 'failed', at: Date.now(),
          error: this.observationErrorText(error),
        },
        groups: [],
      };
    }
    const writeFailure = this._groupObservationFallbacks?.get(Number(blockNum)) || null;
    return {
      schemaVersion: GROUP_OBSERVATION_VERSION,
      blockNum: Number(blockNum),
      groups: [],
      ...(persisted || {}),
      writeFailure,
    };
  }

  observationResult(state, extra = {}) {
    return { state, at: Date.now(), ...extra };
  }

  observationErrorText(error) {
    return String(error?.message || error || 'unknown')
      .replace(/https?:\/\/[^\s,;)]+/gi, '[redacted-url]')
      .replace(/((?:api[_-]?key|token|secret|authorization)\s*[=:]\s*)[^\s,;)]+/gi, '$1[redacted]')
      .slice(0, GROUP_OBSERVATION_ERROR_MAX_CHARS);
  }

  observationFailure(error, extra = {}) {
    return this.observationResult('failed', {
      ...extra,
      error: this.observationErrorText(error),
    });
  }

  // チャット量キャップ（§2.1b）。ChatGameDO・calculator(applyChatCaps)と同一値。
  // 🔴 P-2026-0821（2026-08-07）: **`parseInt` をやめ fail-closed にした。**
  //    旧実装は `parseInt` の結果を一切検査しておらず、`GAME_MAX_MESSAGES` に
  //    全角数字・空白・単位付き文字列が入ると **NaN** がそのまま
  //      ・`applyChatCaps`（正典メッセージ集合の上限）
  //      ・`receiptMaxRefsPerReceipt` / `receiptBundleCap` / `messageBundleCap`（CPU 予算）
  //      ・manifest の `rules`（第三者へ公開される宣言値）
  //    へ流れた。NaN は比較を両方向とも false にするので、**上限が消える**。
  //    `Number` を使うことで `'1e2' → 100`（`parseInt` だと 1）という
  //    「宣言値と適用値のズレ」も同時に消える。
  //    ⚠️ 運用注意: 環境変数を1つ打ち間違えると **DO が起動しない**。
  //       これは意図した設計で、上限なしのチャット期間を1本走らせるより安全。
  getChatCaps() {
    // `normalizeChatCaps` を最後に通すのは B-4（宣言値 ≡ 適用値）のため。
    // 採点エンジンは受け取った caps を必ずこの関数に通すので、
    // manifest がここで作る宣言値と**同一の値**が適用されることが型ではなくコードで保証される。
    // requireIntEnv を通った時点で正の安全整数なので、この呼び出しは恒等写像になる。
    return normalizeChatCaps({
      maxChars: requireIntEnv('GAME_MAX_CHARS', this.env.GAME_MAX_CHARS, 10000),
      maxMessages: requireIntEnv('GAME_MAX_MESSAGES', this.env.GAME_MAX_MESSAGES, 100),
      maxMsgChars: requireIntEnv('GAME_MAX_MSG_CHARS', this.env.GAME_MAX_MSG_CHARS, 1000)
    });
  }

  // 適格条件（最低発言量）。採点（calcScoringUnit）と manifest の宣言値（rules）が
  // **同一のソース**から出ることを保証する唯一の入口（P-2026-0821 B-4）。
  // 🔴 旧実装は両方で `this.env.GAME_MIN_CHARS ? parseInt(...) : 500` を別々に書いており、
  //    NaN のとき manifest には `null`（JSON 化で NaN → null）が載る一方、
  //    採点側は比較が空振りして事実上「閾値なし」で走った＝宣言と適用が別物だった。
  getScoringMins() {
    return {
      minChars: requireIntEnv('GAME_MIN_CHARS', this.env.GAME_MIN_CHARS, 500, 0),
      minMessages: requireIntEnv('GAME_MIN_MESSAGES', this.env.GAME_MIN_MESSAGES, 20, 0)
    };
  }

  // ============================================================
  // Evidence 宣言タイムライン（オンチェーンが正・サーバーが従属・v3.2）
  //   entryEnd = START_TIME + (N+1)×BLOCK_TIME（応募終了＝予定基準時刻）
  //   grace    = Evidence.currentGrace(N)（未読取時は env RESULT_GRACE フォールバック。
  //              パイプライン＋開始待機カウントダウンを兼ねる・本番2h）
  //   chattingStart = entryEnd + grace（パイプラインが早く終わってもこの時刻まで待つ）
  //   チャット有効窓（契約）= [entryEnd, entryEnd+grace+GAME_PERIOD]
  //   オンチェーン提出窓    = [entryEnd+grace+GAME_PERIOD, +SUBMIT_PERIOD]
  //   completed（結果集計）= closeAt + CONFIRMATION_BLOCKS×12s + 30s
  // ============================================================

  // 宣言タイムライン（ms）を計算。graceSec はチェーン読取値（フォールバック env）。
  // 計算本体は lib/timeline-check.js（F-TL5 テストと共有する純関数）へ委譲。
  getDeclaredTimesMs(blockNum, graceSec) {
    const startTimeMs = this.env.START_TIME ? (Number(this.env.START_TIME) || Date.parse(this.env.START_TIME)) : NaN;
    const blockTimeMs = this.env.BLOCK_TIME ? parseInt(this.env.BLOCK_TIME) : NaN;
    const confirmations = this.env.CONFIRMATION_BLOCKS ? parseInt(this.env.CONFIRMATION_BLOCKS) : 64;
    return computeDeclaredTimesMs({
      startTimeMs, blockTimeMs,
      gamePeriodMs: this.gamePeriodMs, submitPeriodMs: this.submitPeriodMs,
      confirmations
    }, blockNum, graceSec);
  }

  // ============================================================
  // S3-008: 照合できない間の待機と、その終端（2026-07-29 ユーザー判断）
  // ============================================================
  // 方針:
  //   ・照合できるまで ChatGameDO を初期化しない（WS も P2P も始まらない＝発言が窓外に漏れない）
  //   ・30分ごとに再試行。運用側が RPC を追加するか env を直せば自動で再開する
  //   ・チェーンが読めている間は窓（chatCloseAt）を先送りして「開始できる権利」を保つ
  //   ・その権利が失われても、それだけではブロックを空結果にしない。安全ブロックで
  //     Evidence提出窓が閉じ、resultCount=0 と確認できた場合だけ専用 no-game schema で確定する

  // 照合待ちの再試行間隔（30分・ユーザー要望）
  static get TIMELINE_RETRY_MS() { return 30 * 60 * 1000; }
  static get TIMELINE_NO_GAME_CAUSES() { return TIMELINE_NO_GAME_CAUSES; }

  timelineNoGameCleanupKey(blockNum) {
    return `timeline_no_game_cleanup_block${blockNum}`;
  }

  publicTimelineNoGameCleanup(cleanup) {
    if (cleanup?.status !== 'completed') return null;
    return {
      schemaVersion: 1,
      status: 'completed',
      d1Status: TIMELINE_NO_GAME_INVALIDATED_STATUS,
      invalidatedGroupCount: Number(cleanup.invalidatedGroupCount || 0),
      chatDoResetCount: Number(cleanup.chatDoResetCount || 0),
      artifactsPreserved: true,
      completedAt: cleanup.completedAt,
    };
  }

  // timeline no-game の summary を権威化する前の fail-closed cleanup。
  // R2 の game_groups / roster / shard は第三者検証用にそのまま残し、D1 status と
  // DO storage の timeline_no_game_cleanup_block{N} で「公開済みだが無効」を表す。
  async cleanupTimelineNoGameBlock(blockNum) {
    const key = this.timelineNoGameCleanupKey(blockNum);
    const previous = await this.storage.get(key);
    if (previous?.status === 'completed') {
      await this.clearRosterGateTimelineWait(blockNum);
      return previous;
    }

    const attempt = Number(previous?.attempt || 0) + 1;
    const pending = {
      schemaVersion: 1,
      blockNum: Number(blockNum),
      reason: 'timeline_unverified',
      status: 'pending',
      d1Status: TIMELINE_NO_GAME_INVALIDATED_STATUS,
      artifactsPreserved: true,
      startedAt: previous?.startedAt || Date.now(),
      attempt,
      updatedAt: Date.now(),
    };
    await this.storage.put(key, pending);

    try {
      // 1. これから通常ゲームを進める task を先に止める。cleanup 自身が失敗した場合だけ、
      // 呼出し元が同じ grouping_watchdog を1本再登録する。
      const queue = await this.storage.get('phase_task_queue') || [];
      const filtered = queue.filter((task) => (
        Number(task?.blockNum) !== Number(blockNum)
        || !TIMELINE_NO_GAME_CANCELLED_TASK_TYPES.has(task?.type)
      ));
      await this.storage.put('phase_task_queue', filtered);
      const active = await this.storage.get('phase_task_active');
      if (Number(active?.blockNum) === Number(blockNum)
          && TIMELINE_NO_GAME_CANCELLED_TASK_TYPES.has(active?.type)) {
        // 自分自身（grouping_watchdog）以外の task が既に走っている最中なら、markerだけを
        // 消して確定してはいけない。そのtaskが marker を下ろすまで fail closed で待つ。
        if (active.type !== 'grouping_watchdog') {
          throw new Error(`timeline no-game cleanup waiting for active ${active.type} task`);
        }
        await this.storage.delete('phase_task_active');
      }
      const parked = await this.storage.list({
        prefix: `phase_task_parked:${blockNum}:`, limit: PUBLIC_STORAGE_LIST_LIMIT,
      });
      if (parked.size > 0) await this.storage.delete([...parked.keys()]);
      if (filtered.length > 0) await this.armEarliestQueuedTask(5000);
      else if (typeof this.state?.storage?.deleteAlarm === 'function') await this.state.storage.deleteAlarm();
      await this.storage.delete(`phase_block${blockNum}`);

      // 2. D1 と append-only registry の和集合を、RELEASE_TIME 非依存の専用入口で全件終端する。
      const db = this.env.BITCOINU_DATA;
      if (!db) throw new Error('BITCOINU_DATA binding not found');
      const { results: rows } = await db.prepare(
        'SELECT group_id, status FROM game_groups WHERE block_num = ? ORDER BY group_id'
      ).bind(blockNum).all();
      const registry = await this.storage.get(`chatdo_registry_block${blockNum}`) || [];
      const targetIds = [...new Set([
        ...(rows || []).map((row) => Number(row.group_id)),
        ...(Array.isArray(registry) ? registry : []).map(Number),
      ].filter(Number.isSafeInteger))].sort((a, b) => a - b);
      if (targetIds.length > 0 && !this.env.CHAT_GAME_DO) {
        throw new Error('CHAT_GAME_DO binding not found');
      }
      const invalidationOutcomes = await this.batchChatDoCalls(targetIds, async (groupId) => {
        try {
          const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${groupId}`);
          const response = await this.env.CHAT_GAME_DO.get(doId).fetch(
            this.chatDoRequest('/invalidate-no-game', { method: 'POST' }),
          );
          if (response.ok) return { groupId, ok: true };
          return { groupId, ok: false, error: `status ${response.status}` };
        } catch (error) {
          return { groupId, ok: false, error: this.observationErrorText(error) };
        }
      });
      const invalidationFailures = invalidationOutcomes.filter((outcome) => !outcome.ok);
      if (invalidationFailures.length > 0) {
        throw new Error(
          `timeline no-game ChatGameDO invalidation failed for ${invalidationFailures.length}/${targetIds.length} groups: `
          + invalidationFailures.slice(0, 5).map((item) => `${item.groupId}:${item.error}`).join(', ')
        );
      }

      // 3. 行は削除せず専用 status へ移し、全行がその値へ収束したことを再読して確かめる。
      const completedAt = new Date().toISOString();
      await db.prepare(
        'UPDATE game_groups SET status = ?, completed_at = ? WHERE block_num = ?'
      ).bind(TIMELINE_NO_GAME_INVALIDATED_STATUS, completedAt, blockNum).run();
      const { results: statusRows } = await db.prepare(
        'SELECT status, COUNT(*) AS cnt FROM game_groups WHERE block_num = ? GROUP BY status'
      ).bind(blockNum).all();
      const unexpected = (statusRows || []).filter((row) => row.status !== TIMELINE_NO_GAME_INVALIDATED_STATUS);
      if (unexpected.length > 0) {
        throw new Error(`timeline no-game D1 invalidation incomplete: ${JSON.stringify(unexpected)}`);
      }
      const invalidatedGroupCount = (statusRows || []).reduce((sum, row) => sum + Number(row.cnt || 0), 0);
      const completed = {
        ...pending,
        status: 'completed',
        invalidatedGroupCount,
        chatDoResetCount: invalidationOutcomes.length,
        cancelledTaskCount: queue.length - filtered.length,
        completedAt,
        updatedAt: Date.now(),
      };
      delete completed.lastError;
      await this.storage.put(key, completed);
      await this.clearRosterGateTimelineWait(blockNum);
      return completed;
    } catch (error) {
      await this.storage.put(key, {
        ...pending,
        lastError: this.observationErrorText(error),
        updatedAt: Date.now(),
      });
      throw error;
    }
  }

  async readTimelineNoGamePublicState(blockNum) {
    // Durable Object の実体では必ず storage がある。prototype 単体の純粋な表示試験や
    // 移行用の読取スタブでは無い場合があるため、そのときだけ従来どおり通常応答へ委ねる。
    if (!this.storage) return null;
    const key = this.timelineNoGameCleanupKey(blockNum);
    const [before, grouping] = await Promise.all([
      this.storage.get(key),
      this.storage.get(`grouping_block${blockNum}_progress`),
    ]);
    const isCleanupRecord = (value) => value && typeof value === 'object'
      && value.schemaVersion === 1
      && Number(value.blockNum) === Number(blockNum)
      && value.reason === 'timeline_unverified'
      && (value.status === 'pending' || value.status === 'completed');
    const cleanupBefore = isCleanupRecord(before) ? before : null;
    if (cleanupBefore?.status === 'pending') return { status: 'pending', cleanup: cleanupBefore };
    const legacyFinalized = grouping?.noGame === true
      && grouping?.noGameMeta?.reason === 'timeline_unverified';
    const finalizationInProgress = grouping?.timelineNoGameFinalization?.reason === 'timeline_unverified';
    if (this.env.R2_BUCKET && (cleanupBefore || legacyFinalized || finalizationInProgress)) {
      const finalized = await this.readFinalizedTimelineNoGame(blockNum);
      if (finalized) return { status: 'completed', cleanup: finalized.cleanup, finalized };
    }
    const after = await this.storage.get(key);
    return isCleanupRecord(after) ? { status: 'pending', cleanup: after } : null;
  }

  // 「ゲームなし・配分ゼロで確定」の共通処理。
  //
  // B4(2026-07-16) で 0名ブロック向けに作られた処理を、S3-008（照合不能のまま窓が閉じた）でも
  // 使えるよう関数化したもの。公開物までは応募0件と同じだが、timeline no-game は証明対象外になる:
  //   ・summary.json に noGame: true を公開（第三者が「配分ゼロで確定」と判別できる）
  //   ・空ツリーの標識ルート keccak256("bitcoinu:empty-merkle:{N}") を公開
  //     → proofRequired=true なら root は提出せず、false なら従来どおり手動fallbackだけを許す
  //   ・検証 manifest も公開
  // 標識ルートの提出は best-effort（RPC 障害中は失敗しうる）。失敗しても
  // /submit-merkle-root で後から再試行できる（従来と同じ）。
  async finalizeNoGameBlock(blockNum, meta = {}) {
    const timelineNoGame = meta.reason === 'timeline_unverified';
    if (timelineNoGame) {
      const f = meta.chainFinality;
      if (!TIMELINE_NO_GAME_CAUSES.includes(meta.cause) || !f || f.resultCount !== 0
          || !Number.isInteger(f.safeTimestamp) || !Number.isInteger(f.resultCloseAt)
          || !Number.isInteger(f.chatOpenAt) || !Number.isInteger(f.chatCloseAt)
          || f.safeTimestamp < f.resultCloseAt) {
        throw new Error(
          `[evidence] refusing timeline_unverified no-game for block ${blockNum}: `
          + 'a final safe-chain result window with resultCount=0 and an allowed cause is required'
        );
      }
      const progressKey = `grouping_block${blockNum}_progress`;
      const pendingProgress = await this.storage.get(progressKey) || { blockNum };
      pendingProgress.phase = 'no_game_finalizing';
      pendingProgress.timelineNoGameFinalization = meta;
      await this.storage.put(progressKey, pendingProgress);

      // summary / evidence-report を no-game の権威として公開するより先に、古いゲーム世界を止める。
      // 緊急固定一式のローカル再構築だけは live D1 / ChatGameDO を対象にしない。
      // 明示の厳密な true 以外（本番の全呼出し元を含む）は従来どおり fail-closed cleanup を通る。
      if (meta.offlineMaterialize !== true) {
        const cleanup = await this.cleanupTimelineNoGameBlock(blockNum);
        meta = { ...meta, cleanup };
      }
      const chatWindowMs = {
        startMs: f.chatOpenAt * 1000 - CHAT_WINDOW_CLOCK_SKEW_MS,
        endMs: f.chatCloseAt * 1000 + CHAT_WINDOW_CLOCK_SKEW_MS,
      };
      const evidenceReport = {
        contractAddress: f.evidenceContract,
        blockNum,
        resultCount: 0,
        window: { openAt: f.resultOpenAt, closeAt: f.resultCloseAt },
        chatWindow: {
          chatOpenAt: f.chatOpenAt,
          chatCloseAt: f.chatCloseAt,
          clockSkewAllowMs: CHAT_WINDOW_CLOCK_SKEW_MS,
        },
        safeBlock: f.safeBlockNumber,
        confirmations: f.confirmations,
        adopted: [],
        invalid: [],
      };
      await this.putR2ObjectOrThrow(`verification/block${blockNum}/evidence-report.json`, evidenceReport);
      await this.storage.put(`evidence_reconciled_block${blockNum}`, {
        resultCount: 0, adoptedCount: 0, chatWindowMs, at: Date.now(),
      });
    }
    const progressKey = `grouping_block${blockNum}_progress`;
    const progressData = await this.storage.get(progressKey) || { blockNum };
    progressData.phase = 'no_game_finalizing';
    try { await this.renewGroupingLease(blockNum, progressData); } catch { /* noop */ }

    const blockSummary = {
      schemaVersion: 3,
      blockNum,
      blockReward: getBlockRewardWei(blockNum).toString(),
      totalPlayers: timelineNoGame ? Number(meta.totalPlayers || 0) : 0,
      totalGroups: 0,
      noGame: true,
      majorLangs: [],
      groups: [],
      claimStatusKey: `games/block${blockNum}/claim-status.json`,
      claimLayout: 'group-overlays-v1',
    };
    // S3-008: なぜゲームなしになったかを公開データに残す（0名なら 'zero_entries'）
    if (meta.reason) blockSummary.noGameReason = meta.reason;
    if (meta.cause) blockSummary.noGameCause = meta.cause;
    if (timelineNoGame) {
      // V25-03: RPC不通というサーバー都合を「応募0件」と偽装しない。第三者が独立に
      // Evidence の提出窓・安全ブロック・0件を照合できる専用schemaとして固定する。
      blockSummary.noGameFinality = {
        schemaVersion: 1,
        evidenceContract: meta.chainFinality.evidenceContract,
        safeBlockNumber: meta.chainFinality.safeBlockNumber,
        safeTimestamp: meta.chainFinality.safeTimestamp,
        resultOpenAt: meta.chainFinality.resultOpenAt,
        resultCloseAt: meta.chainFinality.resultCloseAt,
        resultCount: 0,
      };
    }
    // 書き込み競合対策の対象外（2026-07-31・意図的）: ここは「このブロックはゲーム無し」を
    // 宣言する**権威的な新規作成**で、groups は空＝引き継ぐ `claimed` が存在しない。
    // リセット後の再実行で前ブロック世界の請求記録を引き継いでも困るので、無条件のままにする。
    await this.publishInitialClaimStatus(blockNum, {
      claimedCount: 0, totalCount: 0, claimedWei: '0', totalWei: '0',
    });
    await this.putR2ObjectOrThrow(`games/block${blockNum}/summary.json`, blockSummary);

    // S3-010: 通常集計と同じ順序（tree publish → manifest → root 提出）。
    // 葉が無い＝proof 生成は不要だが、**root 提出を最後**にする点は同じ。
    const pub = await this.publishMerkleTree(blockNum, blockSummary);
    await this.publishEmptyEvidenceSegmentArtifact(blockNum);
    const verification = await this.publishVerificationManifest(blockNum, []);
    // 🔴 C-1 / ラウンド19 判断不要-3 レッグ (d)（2026-08-08）: 旧実装は `pub?.ok` だけを見て
    //    標識ルートを提出していた。ゲーム無し／自動配布は **scoring 段を通らない**ので、
    //    `finalizeVerificationManifest` の `assertGuestPinnedRules` が
    //    「宣言値がゲスト焼き込み値と一致するか」の**唯一のゲート**になる（:5904-5910 が明記）。
    //    そこが `{ok:false}` でも root だけ出てブロックが `completed` になっていた。
    //    → 提出条件を `pub?.ok && verification?.ok` にし、失敗はマーカーに残して
    //      `collectLifecycleBlockers` から見えるようにする。
    if (!verification?.ok) {
      const wait = adminTxWaitOf(verification);
      if (wait) {
        // 管理txの保留はmanifest生成失敗ではないためcompletedへ倒さず、同じno-game確定段を
        // 保持する。正常な着地・確定待ちと凍結は予算非消費、不達は失敗予算を消費する。
        progressData.timelineNoGameFinalization = meta;
        await this.recordVerificationAdminTxWait(blockNum, verification, wait, 'no_game');
        const waitingProgress = await this.markGroupingAdminTxWait(blockNum, progressData, wait, {
          phase: 'no_game_finalizing', stage: 'manifest', timelineUnverified: timelineNoGame,
        });
        return {
          pending: true,
          stage: 'manifest',
          waitReason: wait.waitReason,
          retryInMs: wait.delay,
          resumable: waitingProgress.resumable,
          parked: waitingProgress.status === 'parked',
          verification,
          noGameReason: meta.reason || null,
        };
      }
      console.error(`[verification] ⚠️ block ${blockNum} (no-game): manifest not published/anchored `
        + `(${verification?.error || 'unknown'}) — merkle root submission SKIPPED. Re-run POST /submit-merkle-root after fixing.`);
      await this.clearVerificationAdminFreeze(blockNum);
      await this.recordVerificationPublishFailure(blockNum, verification);
    } else {
      // no-game は同じ呼出しの後段に adminCommit を持つ。再入時にその連続待機の起点を
      // manifest成功で消さず、root側の結果が出てから終端する。
      await this.clearVerificationPublishFailure(blockNum, { preservePendingPeriod: true });
      await this.clearVerificationAdminFreeze(blockNum);
    }
    const merkle = await this.finalizePublishedRootWithPipeline(blockNum, {
      merkle: pub,
      verification,
      groupCount: 0,
      totalPoints: '0',
      blockRewardWei: blockSummary.blockReward,
      adminTxFailureOwner: 'grouping',
    });
    const rootWait = adminTxWaitOf(merkle);
    if (rootWait) {
      progressData.timelineNoGameFinalization = meta;
      await this.recordVerificationAdminTxWait(blockNum, merkle, rootWait, 'no_game');
      const waitingProgress = await this.markGroupingAdminTxWait(blockNum, progressData, rootWait, {
        phase: 'no_game_finalizing', stage: rootWait.detail.stage || 'adminCommit',
        timelineUnverified: timelineNoGame,
      });
      return {
        pending: true,
        stage: rootWait.detail.stage || 'adminCommit',
        waitReason: rootWait.waitReason,
        retryInMs: rootWait.retryInMs,
        waitDetail: rootWait.detail,
        resumable: waitingProgress.resumable,
        parked: waitingProgress.status === 'parked',
        merkle,
        verification,
        noGameReason: meta.reason || null,
      };
    }
    // manifest が通った後のroot結果が管理tx待ちでなければ、成功・終端・別種待ちの
    // いずれでも管理tx印と期間を切る。manifest自体の通常失敗印は残す。
    if (verification?.ok) await this.clearVerificationAdminTxWait(blockNum);

    progressData.status = 'completed';
    progressData.phase = 'completed';
    progressData.completedAt = new Date().toISOString();
    progressData.noGame = true;
    progressData.noGameMeta = meta;
    progressData.totalGroups = 0;
    progressData.resumable = false;
    progressData.timelineUnverified = false;
    progressData.error = null;
    delete progressData.waitReason;
    delete progressData.waitUntil;
    delete progressData.waitDetail;
    delete progressData.adminTxWaitDeadline;
    delete progressData.timelineNoGameFinalization;
    await this.storage.put(progressKey, progressData);

    await this.clearRosterGateTimelineWait(blockNum);
    return { merkle, verification, noGameReason: meta.reason || null };
  }

  // V25-03: timeline照合失敗を no-game に確定してよい唯一のchain predicate。
  // RPCが読めない／安全ブロックで提出窓が閉じていない／Resultが1件でもある、のいずれも
  // terminal ではない。通常の再試行を続け、chainが戻ればselectionからgroupingを再構築する。
  async inspectTimelineNoGameFinality(blockNum) {
    const evidenceContract = this.env.EVIDENCE_CONTRACT_ADDRESS;
    const client = this.createReadOnlyClient();
    const quorumClients = this.createEvidenceReadClients();
    if (!evidenceContract || !client) return { ready: false, reason: 'rpc_unavailable' };
    const confirmations = this.env.CONFIRMATION_BLOCKS ? parseInt(this.env.CONFIRMATION_BLOCKS) : 64;
    try {
      let safeBlockNumber; let safeBlock;
      if (quorumClients) {
        safeBlock = await readMatchingFinalizedBlock(quorumClients);
        safeBlockNumber = safeBlock.number;
      } else {
        const latest = await client.getBlock();
        if (latest.number < BigInt(confirmations)) return { ready: false, reason: 'safe_block_unavailable' };
        safeBlockNumber = latest.number - BigInt(confirmations);
        safeBlock = await client.getBlock({ blockNumber: safeBlockNumber });
      }
      const abi = [
        { name: 'resultCount', type: 'function', stateMutability: 'view',
          inputs: [{ name: '', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] },
        { name: 'resultWindow', type: 'function', stateMutability: 'view',
          inputs: [{ name: 'blockNum', type: 'uint256' }],
          outputs: [{ name: 'openAt', type: 'uint256' }, { name: 'closeAt', type: 'uint256' }] },
      ];
      const chatAbi = [{ name: 'chatWindow', type: 'function', stateMutability: 'view',
        inputs: [{ name: 'blockNum', type: 'uint256' }],
        outputs: [{ name: 'chatOpenAt', type: 'uint256' }, { name: 'chatCloseAt', type: 'uint256' }] }];
      const at = (functionName, callAbi = abi) => quorumClients
        ? this.readEvidenceAtBlock(quorumClients, safeBlock, evidenceContract, callAbi, functionName, [BigInt(blockNum)])
        : client.readContract({ address: evidenceContract, abi: callAbi, functionName,
          args: [BigInt(blockNum)], blockNumber: safeBlockNumber });
      const [window, chat, count] = await Promise.all([
        at('resultWindow'), at('chatWindow', chatAbi), at('resultCount'),
      ]);
      if (quorumClients) await readMatchingFinalizedBlock(quorumClients, safeBlock);
      const resultOpenAt = Number(window[0]);
      const resultCloseAt = Number(window[1]);
      const chatOpenAt = Number(chat[0]);
      const chatCloseAt = Number(chat[1]);
      const safeTimestamp = Number(safeBlock.timestamp);
      const resultCount = Number(count);
      if (!Number.isSafeInteger(resultOpenAt) || !Number.isSafeInteger(resultCloseAt)
          || !Number.isSafeInteger(chatOpenAt) || !Number.isSafeInteger(chatCloseAt)
          || !Number.isSafeInteger(safeTimestamp) || !Number.isSafeInteger(resultCount)) {
        throw new Error('non-canonical Evidence window/count returned by RPC');
      }
      if (quorumClients) await this.storage.delete(`rpc_quorum_wait_block${blockNum}`);
      const finality = {
        evidenceContract: String(evidenceContract).toLowerCase(),
        safeBlockNumber: safeBlockNumber.toString(),
        confirmations,
        safeTimestamp, resultOpenAt, resultCloseAt, chatOpenAt, chatCloseAt, resultCount,
      };
      if (safeTimestamp < resultCloseAt) return { ready: false, reason: 'result_window_open', ...finality };
      if (resultCount !== 0) return { ready: false, reason: 'evidence_present', ...finality };
      return { ready: true, ...finality };
    } catch (error) {
      if (quorumClients && error?.code === 'rpc_quorum_unavailable') await this.noteRpcQuorumFailure(blockNum, error);
      return { ready: false, reason: 'rpc_unavailable', error: String(error?.message || error) };
    }
  }

  // 最後に読めたチェーン窓を保存する（RPC 全滅中に「いつまで開始できるか」を知るため）
  async rememberChainTimeline(blockNum, chainTL) {
    try {
      await this.storage.put(`evidence_tl_snapshot_block${blockNum}`, {
        graceSec: chainTL.graceSec,
        chatOpenAt: chainTL.chatOpenAt,
        chatCloseAt: chainTL.chatCloseAt,
        resultCloseAt: chainTL.resultCloseAt,
        readAt: Date.now(),
      });
    } catch (e) {
      console.error(`[evidence] snapshot memo failed for block ${blockNum}:`, e.message);
    }
  }

  // 「いつまでなら正当に開始できるか」（ms）。
  // GM-LATCH: 宣言があればその grace を使う。P2 の BLOCK_TIME 延長が着地して G4 の追従が
  // 済んだ後も、依存待ちの期限と blocker 表示を古い env RESULT_GRACE へ戻さない。
  // 宣言がまだ無ければ最後に読めたチェーン窓、どちらも無ければ env から推定する。
  async startWindowDeadlineMs(blockNum) {
    const declaration = await this.storage.get(`declared_grace_block${blockNum}`);
    if (Number.isSafeInteger(declaration?.graceSec) && declaration.graceSec >= 0) {
      const declared = this.getDeclaredTimesMs(blockNum, declaration.graceSec);
      if (declared && Number.isFinite(declared.submittingStart)) {
        return {
          deadlineMs: declared.submittingStart,
          source: declaration.source === 'intent' ? 'declared_intent' : 'declared_chain',
          readAt: declaration.updatedAt ?? null,
        };
      }
    }
    const memo = await this.storage.get(`evidence_tl_snapshot_block${blockNum}`);
    if (memo && Number.isFinite(memo.chatCloseAt)) {
      return { deadlineMs: memo.chatCloseAt * 1000, source: 'chain_snapshot', readAt: memo.readAt };
    }
    const graceSec = this.env.RESULT_GRACE ? parseInt(this.env.RESULT_GRACE) : 120;
    const declared = this.getDeclaredTimesMs(blockNum, graceSec);
    if (declared) return { deadlineMs: declared.submittingStart, source: 'env_estimate', readAt: null };
    return { deadlineMs: null, source: 'unknown', readAt: null };
  }

  // 「開始できる権利」を先送りする。チェーンが読めるときだけ意味を持つ。
  // 予防的に待たせるための延長ではない（既に待たされている状態で、窓が閉じて
  // 手遅れになるのを防ぐためだけの延長）。grace 上限に達したら何もできない。
  // extendOptions は extendGraceOnChain へそのまま渡す（C32F1: 渡すのは関門の roster_pipeline_late の枝だけ）。
  async shieldStartWindow(blockNum, reason, extendOptions = undefined) {
    try {
      const declared = this.getDeclaredTimesMs(blockNum, 0);
      if (!declared) return { extended: false, reason: 'no_env_timeline' };
      // 「今」を基準に、経過分＋バッファ（30分の再試行1周ぶん＋2分）を確保する。
      // 応募期間中に呼ばれた場合（now < 応募終了）は経過分を 0 に丸める
      //  — 丸めないと負値になり、extendGrace へ無意味な値を渡してしまう。
      const elapsedSec = Math.max(0, Math.ceil((Date.now() - declared.entryEndMs) / 1000));
      const envGraceSec = this.env.RESULT_GRACE ? parseInt(this.env.RESULT_GRACE) : 120;
      const blockTimeMs = Number.parseInt(this.env.BLOCK_TIME, 10);
      const maxGraceSec = Number.isSafeInteger(blockTimeMs) && blockTimeMs > 0
        ? Math.floor(blockTimeMs / 1000) : Infinity;
      const neededGraceSec = Math.min(maxGraceSec, Math.max(
        envGraceSec,
        elapsedSec + Math.ceil(GameMasterDO.TIMELINE_RETRY_MS / 1000) + 120
      ));
      if (!Number.isSafeInteger(neededGraceSec) || neededGraceSec <= 0) {
        return { extended: false, reason: 'block_time_unavailable' };
      }
      const res = await this.extendGraceOnChain(blockNum, neededGraceSec, extendOptions);
      // 便 C32F2（C32-B-01）: 上限（BLOCK_TIME）で頭打ちの目標は時刻が進んでも変わらないので、
      // その開始が 今−START_PAST_TOLERANCE 以下（start_in_past）なら再試行しても通らない。
      const capped = neededGraceSec === maxGraceSec;
      if (res.extended) {
        console.warn(`[evidence] block ${blockNum}: start window shielded (${reason}) — grace → ${neededGraceSec}s`);
      } else if (res.reason === 'start_in_past') {
        console.warn(`[evidence] block ${blockNum}: start window not shielded (${reason}): `
          + `new start ${res.newStartSec ?? '?'} is ≥ START_PAST_TOLERANCE in the past${capped ? ' (capped at BLOCK_TIME)' : ''}`);
      } else if (res.reason !== 'already_sufficient' && res.reason !== 'started_with_roster') {
        console.error(`[evidence] block ${blockNum}: could not shield start window (${reason}): ${res.reason}`);
      }
      return { ...res, requestedGraceSec: neededGraceSec, capped };
    } catch (e) {
      console.error(`[evidence] shieldStartWindow failed for block ${blockNum}:`, e.message);
      return { extended: false, reason: 'error' };
    }
  }

  // 前ブロック依存の30秒再試行では、開始窓が残り6時間を切った時だけ、現在までの
  // 経過分＋30分の再試行1周＋2分を覆うのに必要な分だけgraceを延長する。
  // 着地後も依存待ちなら、次に残り6時間を切った時点の必要量を新しい目標にする。
  // 未着地の目標は固定し、同じintentを5分おき（終端失敗後は次の再試行時）に送り直す。
  async shieldDependencyStartWindow(blockNum, reason) {
    const blockTimeMs = Number.parseInt(this.env.BLOCK_TIME, 10);
    if (!Number.isSafeInteger(blockTimeMs) || blockTimeMs <= 0) {
      return { extended: false, reason: 'block_time_unavailable' };
    }
    const maxGraceSec = Math.floor(blockTimeMs / 1000);
    if (maxGraceSec <= 0) return { extended: false, reason: 'block_time_unavailable' };
    const key = `grouping_dependency_shield_block${blockNum}`;
    const existing = await this.storage.get(key);
    // Q25 A3F4-02: grouping完了後の古いreconcile taskが、記録を作り直して
    // chatting中に未着地目標を再送しないよう、削除ではなく閉鎖markerで止める。
    if (existing?.closed === true) {
      return { extended: false, closed: true, reason: 'dependency_shield_closed' };
    }
    const baseTimeline = this.getDeclaredTimesMs(blockNum, 0);
    if (!baseTimeline) return { extended: false, reason: 'no_env_timeline' };
    const now = Date.now();
    const elapsedSec = Math.max(0, Math.ceil((now - baseTimeline.entryEndMs) / 1000));
    const configuredGraceSec = Number.parseInt(this.env.RESULT_GRACE, 10);
    const initialGraceSec = Number.isSafeInteger(configuredGraceSec) && configuredGraceSec >= 0
      ? configuredGraceSec : 120;
    const neededGraceSec = Math.min(maxGraceSec, Math.max(
      initialGraceSec,
      elapsedSec + Math.ceil(GameMasterDO.TIMELINE_RETRY_MS / 1000) + 120,
    ));
    // T2/T2b: 未着地中は時刻の進行で別intentへ乗り換えず、同じ目標を着地まで再送する。
    // 着地済みの値は床にして、時計の巻戻りやfallbackでも小さい目標を作らない。
    // 便 C32F2（C32-B-01）: 未着地の目標が送信の遅れで「開始が 今−START_PAST_TOLERANCE 以下」になった
    // （start_in_past）なら、同じ目標は二度と通らないので固定せず、今から取り直す。
    const pendingTargetGraceSec = existing?.landed !== true
      && existing?.lastResultReason !== 'start_in_past'
      && Number.isSafeInteger(existing?.targetGraceSec) && existing.targetGraceSec > 0
      ? existing.targetGraceSec : null;
    const landedFloorGraceSec = existing?.landed === true
      && Number.isSafeInteger(existing?.targetGraceSec) ? existing.targetGraceSec : 0;
    const targetGraceSec = pendingTargetGraceSec
      ?? Math.min(maxGraceSec, Math.max(landedFloorGraceSec, neededGraceSec));
    if (existing?.targetGraceSec === targetGraceSec && existing.landed === true) {
      return {
        extended: false,
        landed: true,
        reason: 'dependency_shield_already_landed',
        newGraceSec: targetGraceSec,
      };
    }

    let graceObservation = null;
    const readGraceForShield = async () => {
      try { return await this.readEvidenceGraceSecWithSource(blockNum); }
      catch (error) {
        console.warn(`[evidence] block ${blockNum}: dependency shield grace read waiting for quorum:`, error?.message || error);
        return null;
      }
    };
    if (existing?.targetGraceSec === targetGraceSec) {
      graceObservation = await readGraceForShield();
    }
    if (graceObservation && !graceObservation.fallback
      && graceObservation.graceSec >= targetGraceSec) {
      const landedAt = Date.now();
      await this.storage.put(key, {
        ...existing,
        blockNum,
        reason,
        targetGraceSec,
        pending: false,
        landed: true,
        landedAt,
        graceSource: graceObservation.source,
      });
      await this.adoptChainGraceDeclaration(blockNum, graceObservation.graceSec, {
        reschedule: true,
        reason: 'dependency_shield_landed',
      });
      return {
        extended: false,
        landed: true,
        reason: 'already_sufficient',
        currentGrace: graceObservation.graceSec,
        graceSource: graceObservation.source,
        graceFallback: false,
      };
    }

    const { deadlineMs, source } = await this.startWindowDeadlineMs(blockNum);
    if (!Number.isFinite(deadlineMs)) return { extended: false, reason: 'deadline_unknown' };
    const remainingMs = deadlineMs - now;
    if (remainingMs > GROUPING_DEPENDENCY_SHIELD_THRESHOLD_MS) {
      return { extended: false, reason: 'window_not_at_risk', remainingMs, deadlineSource: source };
    }

    if (!graceObservation) {
      graceObservation = await readGraceForShield();
      if (graceObservation && !graceObservation.fallback && graceObservation.graceSec >= targetGraceSec) {
        await this.storage.put(key, {
          blockNum,
          reason,
          targetGraceSec,
          pending: false,
          landed: true,
          landedAt: now,
          graceSource: graceObservation.source,
        });
        await this.adoptChainGraceDeclaration(blockNum, graceObservation.graceSec, {
          reschedule: true,
          reason: 'dependency_shield_landed',
        });
        return {
          extended: false,
          landed: true,
          reason: 'already_sufficient',
          currentGrace: graceObservation.graceSec,
          graceSource: graceObservation.source,
          graceFallback: false,
        };
      }
    }

    const lastRequestedAt = Number(existing?.lastRequestedAt ?? existing?.requestedAt);
    const retryDue = !Number.isFinite(lastRequestedAt)
      || now - lastRequestedAt >= GROUPING_DEPENDENCY_SHIELD_RETRY_MS
      || existing?.lastResultTerminal === true;
    if (existing?.targetGraceSec === targetGraceSec && !retryDue) {
      return {
        extended: false,
        pending: existing.pending === true,
        reason: 'dependency_shield_retry_not_due',
        newGraceSec: targetGraceSec,
        retryAt: lastRequestedAt + GROUPING_DEPENDENCY_SHIELD_RETRY_MS,
      };
    }

    const result = await this.extendGraceOnChain(blockNum, targetGraceSec);
    const resultReason = String(result?.reason || '');
    const lastResultTerminal = result?.status === 'failed' || result?.status === 'reverted'
      || ['reverted', 'deadline_expired', 'grace_exceeds_block_time', 'chat_window_closed',
        'gas_limit_exceeded', 'dropped_fee_cap_blocked', 'started_with_roster',
        'start_in_past'].includes(resultReason)
      || resultReason.endsWith('_max_attempts');
    await this.storage.put(key, {
      blockNum,
      reason,
      targetGraceSec,
      pending: result?.pending === true,
      landed: false,
      requestedAt: existing?.targetGraceSec === targetGraceSec
        ? existing?.requestedAt ?? now : now,
      lastRequestedAt: now,
      lastResultStatus: result?.status ?? null,
      lastResultReason: resultReason || null,
      lastResultTerminal,
    });
    if (result?.extended === true || result?.pending === true) {
      await this.enqueueGraceReconcileTask(blockNum, {
        reason: 'dependency_shield_pending',
        delayMs: GRACE_RECONCILE_RETRY_MS,
      });
    }
    return result;
  }

  // 照合待ちの状態を記録し、「まだ待てるか / もう手遅れか」を返す。
  async noteTimelineWait(blockNum, cause, rpcConfig, origin = 'grouping') {
    const key = `timeline_wait_block${blockNum}`;
    const prev = await this.storage.get(key) || {};
    const { deadlineMs, source, readAt } = await this.startWindowDeadlineMs(blockNum);
    const now = Date.now();
    const state = {
      blockNum,
      cause,                                   // 'chain_unreadable' | 'env_chain_mismatch'
      origin,
      firstSeenAt: prev.firstSeenAt || now,
      lastSeenAt: now,
      attempts: (origin === 'roster_gate'
        ? (prev.origin === 'roster_gate'
          && ['chain_unreadable', 'env_chain_mismatch', 'roster_gate_unreadable'].includes(prev.cause)
            ? prev.attempts || 0 : 0)
        : prev.attempts || 0) + 1,
      deadlineMs, deadlineSource: source, snapshotReadAt: readAt,
      rpcConfig: rpcConfig || describeRpcConfig(this.env),
      // S3-008（ユーザー要望・2026-07-29）: 通知は**トラブル1件につき1回**。
      // 30分ごとの再試行のたびに送るとメールが埋まるため、
      //   ・初回検出
      //   ・原因が変わったとき（RPC全滅 → 不一致 など＝別のトラブル）
      // だけを「新規」とみなす。
      isNew: !prev.cause || prev.cause !== cause,
      // 通知失敗時は次の30分周期でも再試行する。原因ごとのラッチは送信成功後だけ更新する。
      notifiedCause: prev.notifiedCause || null,
      shouldAlert: prev.notifiedCause !== cause,
    };
    state.expired = deadlineMs !== null && now >= deadlineMs;
    await this.storage.put(key, state);
    return state;
  }

  // S3-008: 介入が必要な照合待ちの原因別初回通知。**失敗してもパイプラインを止めない**。
  async alertTimelineWait(wait, error) {
    const rosterGate = wait.origin === 'roster_gate';
    const left = wait.deadlineMs ? Math.round((wait.deadlineMs - Date.now()) / 60000) : null;
    const causeJa = ({
      chain_unreadable: 'RPC が全滅してチェーンを読めない',
      env_chain_mismatch: 'env とチェーンのタイムラインが不一致',
      grouping_anchor_unreadable: '前ブロックのアンカーを照合できない',
      previous_block_not_ready: '前ブロックの結果が未確定',
      previous_block_anchor_pending: '前ブロックのmanifest/anchorが未確定',
      roster_gate_unreadable: '開始関門で名簿の確定履歴を読めない',
    })[wait.cause] || '原因不明の照合待ち';
    const subject = `[COINU] block ${wait.blockNum} 開始できません（${causeJa}）`;
    const body = [
      rosterGate
        ? `ブロック ${wait.blockNum} の開始関門が ${wait.cause} で止まっています。ChatGameDO は初期化済みですが、チャット開始を予約できていません。`
        : `ブロック ${wait.blockNum} のゲームを開始できていません。照合が通るまで ChatGameDO は初期化しません。`,
      ``,
      `原因            : ${wait.cause}（${causeJa}）`,
      `詳細            : ${String(error?.message || error).slice(0, 400)}`,
      `待機時間        : 約 ${Math.round((Date.now() - wait.firstSeenAt) / 60000)} 分（試行 ${wait.attempts} 回目）`,
      `再試行          : ${wait.retryMs ? `${wait.retryMs / 1000} 秒` : `${GameMasterDO.TIMELINE_RETRY_MS / 60000} 分`}ごとに自動`,
      `メール          : **このトラブルについての通知はこの1通だけです**（復旧・確定時の通知はありません）`,
      `開始できる期限  : ${wait.deadlineMs ? new Date(wait.deadlineMs).toISOString() : '不明'}`
        + `${left !== null ? `（あと約 ${left} 分）` : ''}`,
      `期限の根拠      : ${wait.deadlineSource}`,
      ``,
      ...(rosterGate
        ? [`⚠️ 開始窓が閉じても関門から timeline no-game へは移しません。`,
          `   RPC・名簿履歴を直し、開始窓が閉じる前に必要なら運営が grace を手動延長してください。`]
        : [`⚠️ 期限を過ぎると extendGrace は不可能になります。ただし期限経過だけで空結果にはせず、`,
          `   安全ブロックで Evidence 提出窓の終了と resultCount=0 を確認できるまで再試行します。`,
          `   Result が1件でもあれば、chain復旧後に通常のgrouping・採点・Merkle生成へ進みます。`]),
      ``,
      `対処:`,
      rosterGate
        ? `  ・名簿登録と RPC の読取を確認し、必要なら運営が期限内に grace を手動延長する（開始窓の終了だけで no-game にはしません）`
        : wait.cause === 'chain_unreadable'
        ? `  ・${RPC_LIST_ENV} に RPC を追加して game-master-do を再デプロイ（カンマ区切り・本数無制限）`
        : `  ・env の START_TIME / BLOCK_TIME / GAME_PERIOD / SUBMIT_PERIOD を契約値に合わせる`,
      `  ・現在の RPC 構成: ${wait.rpcConfig?.count ?? '?'} 本 (${(wait.rpcConfig?.hosts || []).join(', ')})`,
      `  ・状況確認: GET /calc-status（blockers に timeline_unverified が出ます）`,
    ].join('\n');
    const result = await sendAlertAndRecord(this.env, this.storage, { subject, body, kind: 'timeline_wait' });
    if (result.sent) {
      // sendAlert は失敗をthrowせず戻り値で返すため、sent=trueを見てからだけラッチを立てる。
      const key = `timeline_wait_block${wait.blockNum}`;
      const current = await this.storage.get(key);
      if (current?.cause === wait.cause) {
        await this.storage.put(key, {
          ...current,
          notifiedCause: wait.cause,
          notifiedAt: Date.now(),
          shouldAlert: false,
        });
      }
    }
    return result;
  }

  async clearTimelineWait(blockNum) {
    try { await this.storage.delete(`timeline_wait_block${blockNum}`); } catch { /* noop */ }
  }

  async clearGroupingTimelineWait(blockNum) {
    const wait = await this.storage.get(`timeline_wait_block${blockNum}`);
    // 出所の無い旧い待ちも組分け扱い。開始関門の回数・通知済み印は持ち主に任せる。
    if (wait?.origin !== 'roster_gate') await this.clearTimelineWait(blockNum);
  }

  async clearRosterGateTimelineWait(blockNum) {
    const wait = await this.storage.get(`timeline_wait_block${blockNum}`);
    if (wait?.origin === 'roster_gate') await this.clearTimelineWait(blockNum);
  }

  isRosterGateBlockedReason(reason) {
    return this.rosterGateBlockedReasons().includes(reason);
  }

  rosterGateBlockedReasons() {
    return ['groups_incomplete', 'canonical_roster_hash_mismatch', 'roster_anchor_missing_onchain',
      'roster_anchor_chain_unavailable', 'roster_confirmation_depth_invalid',
      'roster_chain_grace_unavailable', 'roster_chain_timeline_unavailable'];
  }

  async noteRosterGateNotReady(blockNum, reason, timeline) {
    // 例外後に通常の未準備へ移った場合、古い RPC 障害の案内を残さない。
    const waitKey = `timeline_wait_block${blockNum}`;
    const priorWait = await this.storage.get(waitKey);
    if (priorWait?.origin === 'roster_gate') {
      await this.storage.put(waitKey, { ...priorWait, cause: reason, attempts: 0, lastSeenAt: Date.now() });
    }
    if (this.isRosterGateBlockedReason(reason)) {
      const key = `roster_gate_blocked_block${blockNum}`;
      const prior = await this.storage.get(key);
      const alertKey = `roster_gate_blocked_alerted_block${blockNum}_${reason}`;
      const marker = {
        blockNum, reason, firstSeenAt: prior?.firstSeenAt || Date.now(),
        lastSeenAt: Date.now(), notified: (prior?.reason === reason && prior?.notified === true)
          || await this.storage.get(alertKey) === true,
        canStartUntil: timeline?.declared?.submittingStart ?? null,
      };
      await this.storage.put(key, marker);
      if (!marker.notified) {
        const sent = await sendAlertAndRecord(this.env, this.storage, {
          kind: 'roster_gate_blocked',
          subject: `[COINU] block ${blockNum} 名簿開始関門が停止（${reason}）`,
          body: reason === 'groups_incomplete'
            ? `block ${blockNum} の D1 組一覧が完了印または公開 game_groups.json と一致しません。` +
              `ChatGameDO 初期化・名簿登録・開始予約を止めました。D1 と公開一覧を照合し、正しい組集合を復旧してください。`
            : `block ${blockNum} の開始関門は ${reason} で止まっています。` +
            `チェーンの名簿鍵の最後の登録と R2 games/block${blockNum}/roster/manifest.json の keccak を照合してください。` +
            `GCPの保全物で確かめた正しい H を、開始前に test_hashStorage.js メニュー4 から名簿鍵の最後の登録として手送信します。` +
            `乗っ取りなら changeAdmin 後、新しい管理鍵を送信係へ渡す前（凍結中）に手元の Hardhat から送信し、鍵を渡した後なら静穏な nonce 窓で送信してください。` +
            `env 脱落なら修正して再配備し、宣言開始が迫れば BLOCK_TIME 以内で POST /extend-grace してください。`,
        }).catch((error) => {
          console.error('[roster-gate] blocked alert failed:', error?.message || error);
          return null;
        });
        if (sent?.sent) {
          await this.storage.put(key, { ...marker, notified: true });
          await this.storage.put(alertKey, true);
        }
      }
    } else {
      await this.storage.delete(`roster_gate_blocked_block${blockNum}`);
    }
    const gasKey = `roster_gate_gas_wait_block${blockNum}`;
    const gasReasons = ['grace_confirmation_pending', 'roster_pipeline_late', 'roster_anchor_or_manifest_missing'];
    if (gasReasons.includes(reason) && Date.now() >= Number(timeline?.declared?.chattingStart)) {
      const pending = await this.collectAdminTxPending();
      const ownGasItem = pending.items?.find((item) => Number(item.blockNum) === Number(blockNum)
        && ['setRosterManifestHash', 'extendGrace'].includes(item.label)
        && ['gas_price_above_cap', 'fee_cap_blocked'].includes(item.reason));
      const queued = pending.queuedIntents?.find((item) => Number(item.blockNum) === Number(blockNum)
        && ['setRosterManifestHash', 'extendGrace'].includes(item.operation));
      const priorGasItem = pending.items?.find((item) =>
        item.status !== 'failed'
        && ['gas_price_above_cap', 'fee_cap_blocked'].includes(item.reason));
      const gasItem = ownGasItem || (queued && priorGasItem && {
        label: queued.operation, reason: priorGasItem.reason,
      });
      if (gasItem) {
        const prior = await this.storage.get(gasKey);
        const marker = { blockNum, reason, operation: gasItem.label,
          gasReason: gasItem.reason, firstSeenAt: prior?.firstSeenAt || Date.now(),
          chatCloseAt: timeline?.declared?.submittingStart ?? null };
        await this.storage.put(gasKey, marker);
        const alertKey = `roster_gate_gas_alerted_block${blockNum}`;
        if (!await this.storage.get(alertKey)) {
          const sent = await sendAlertAndRecord(this.env, this.storage, {
            kind: 'roster_gate_gas_wait',
            subject: `[COINU] block ${blockNum} 名簿開始がガス上限で停止`,
            body: `block ${blockNum}: ${gasItem.label} が ${gasItem.reason} で未着地です。` +
              `名簿登録が確定してから、chatCloseAt の30分前の窓が` +
              `応募終了+BLOCK_TIME−(64確認+関門周期)より前にある間に` +
              `API_SECRET付き POST /extend-grace で grace=BLOCK_TIME を送ってください。` +
              `名簿確定前の遠い延長は送らないでください。`,
          }).catch((error) => {
            console.error('[roster-gate] gas alert failed:', error?.message || error);
            return null;
          });
          if (sent?.sent) await this.storage.put(alertKey, true);
        }
        return;
      }
    }
    if (await this.storage.get(gasKey)) {
      const pending = await this.collectAdminTxPending();
      if (pending.coordinator?.ok === false) return;
    }
    await this.storage.delete(gasKey);
  }

  async clearRosterGateAfterStart(blockNum) {
    await this.clearRosterGateTimelineWait(blockNum);
    for (const key of [`roster_gate_blocked_block${blockNum}`, `roster_gate_gas_wait_block${blockNum}`,
      `roster_gate_blocked_alerted_block${blockNum}`, `roster_gate_gas_alerted_block${blockNum}`,
      `roster_anchor_late_block${blockNum}`]) {
      await this.storage.delete(key);
    }
    for (const reason of this.rosterGateBlockedReasons()) {
      await this.storage.delete(`roster_gate_blocked_alerted_block${blockNum}_${reason}`);
    }
    const queue = await this.storage.get('phase_task_queue') || [];
    const remaining = queue.filter((task) => !(task.type === 'roster_anchor' && Number(task.blockNum) === Number(blockNum)));
    if (remaining.length !== queue.length) {
      await this.storage.put('phase_task_queue', remaining);
      await this.armEarliestQueuedTask();
    }
  }

  // Evidence.currentGrace(N) をチェーンから読む。manual phase 観測では、従来は区別できなかった
  // 「chain成功」と「env fallback」を phaseEndTimeSource として残す必要があるため、出所も返す。
  async readEvidenceGraceSecWithSource(blockNum) {
    const fallback = this.env.RESULT_GRACE ? parseInt(this.env.RESULT_GRACE) : 120;
    const contractAddress = this.env.EVIDENCE_CONTRACT_ADDRESS;
    if (!contractAddress) {
      return { graceSec: fallback, source: 'env_no_contract', fallback: true, error: null };
    }
    if (this.createEvidenceReadClients()) {
      const snapshot = await this.readEvidenceTimelineSnapshot(blockNum);
      if (!snapshot || !Number.isSafeInteger(snapshot.graceSec)) {
        const error = new Error(`[rpc-quorum] currentGrace unavailable for block ${blockNum}`);
        error.code = 'rpc_quorum_unavailable';
        throw error;
      }
      return { graceSec: snapshot.graceSec, source: 'chain_current_grace_quorum', fallback: false, error: null };
    }
    try {
      const publicClient = this.createReadOnlyClient();
      if (!publicClient) {
        return { graceSec: fallback, source: 'env_no_rpc', fallback: true, error: 'no_rpc' };
      }
      const g = await publicClient.readContract({
        address: contractAddress,
        abi: [{ name: 'currentGrace', type: 'function', stateMutability: 'view',
                inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] }],
        functionName: 'currentGrace',
        args: [BigInt(blockNum)]
      });
      return { graceSec: Number(g), source: 'chain_current_grace', fallback: false, error: null };
    } catch (e) {
      console.warn(`[evidence] currentGrace read failed (fallback ${fallback}s):`, e.shortMessage || e.message);
      return {
        graceSec: fallback,
        source: 'env_rpc_fallback',
        fallback: true,
        error: this.observationErrorText(e.shortMessage || e.message || e),
      };
    }
  }

  // 既存呼出しの値と挙動は不変（上の出所情報を捨てる互換入口）。
  async readEvidenceGraceSec(blockNum) {
    return (await this.readEvidenceGraceSecWithSource(blockNum)).graceSec;
  }

  // F-TL5: Evidence 契約のタイムライン関連値を「同一ブロック高に固定した」1回のスナップショットで読む。
  //   currentGrace ＋ chatWindow/resultWindow ＋ immutable 4パラメータ（START_TIME/BLOCK_TIME/GAME_PERIOD/SUBMIT_PERIOD）。
  //   高さ固定＝extendGrace 着地・手動 /extend-grace との読取レースなし。宣言タイムラインはこの graceSec で
  //   組む（＝env↔chain 照合の両辺が構成上同一 grace・grace 起因の偽陽性なし）。
  //   契約未設定・RPC 失敗は null を返す。
  //   ⚠️ S3-008（2026-07-29）で扱いが変わった: **null は「照合できない」＝ゲームを開始しない**。
  //   Evidence が設定されている構成では呼び出し元（resolveDeclaredTimeline）が throw し、
  //   30分ごとの再試行で待つ。以前の「env フォールバックで続行（可用性維持）」は廃止した。
  async readEvidenceTimelineSnapshot(blockNum) {
    const contractAddress = this.env.EVIDENCE_CONTRACT_ADDRESS;
    if (!contractAddress) return null;
    const quorumClients = this.createEvidenceReadClients();
    try {
      const publicClient = this.createReadOnlyClient();
      if (!publicClient) return null;
      const abi = [
        { name: 'currentGrace', type: 'function', stateMutability: 'view',
          inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] },
        { name: 'chatWindow', type: 'function', stateMutability: 'view',
          inputs: [{ name: 'blockNum', type: 'uint256' }],
          outputs: [{ name: 'chatOpenAt', type: 'uint256' }, { name: 'chatCloseAt', type: 'uint256' }] },
        { name: 'resultWindow', type: 'function', stateMutability: 'view',
          inputs: [{ name: 'blockNum', type: 'uint256' }],
          outputs: [{ name: 'openAt', type: 'uint256' }, { name: 'closeAt', type: 'uint256' }] },
        ...['START_TIME', 'BLOCK_TIME', 'GAME_PERIOD', 'SUBMIT_PERIOD'].map(name => (
          { name, type: 'function', stateMutability: 'view', inputs: [], outputs: [{ name: '', type: 'uint256' }] })),
      ];
      const quorumBlock = quorumClients ? await readMatchingFinalizedBlock(quorumClients) : null;
      const blockNumber = quorumBlock ? quorumBlock.number : await publicClient.getBlockNumber();
      const at = (functionName, args = []) => quorumBlock
        ? this.readEvidenceAtBlock(quorumClients, quorumBlock, contractAddress, abi, functionName, args)
        : publicClient.readContract({ address: contractAddress, abi, functionName, args, blockNumber });
      const [snapshotBlock, grace, chatWin, resultWin, startTime, blockTime, gamePeriod, submitPeriod] = await Promise.all([
        quorumBlock || publicClient.getBlock({ blockNumber }),
        at('currentGrace', [BigInt(blockNum)]),
        at('chatWindow', [BigInt(blockNum)]),
        at('resultWindow', [BigInt(blockNum)]),
        at('START_TIME'), at('BLOCK_TIME'), at('GAME_PERIOD'), at('SUBMIT_PERIOD'),
      ]);
      if (quorumBlock) {
        await readMatchingFinalizedBlock(quorumClients, quorumBlock);
      }
      const asNumber = (value, label) => {
        const number = Number(value);
        if (quorumBlock && (!Number.isSafeInteger(number) || number < 0)) {
          throw new Error(`[rpc-quorum] unsafe ${label} at finalized block`);
        }
        return number;
      };
      const observedAtMs = asNumber(snapshotBlock.timestamp, 'block timestamp') * 1000;
      if (quorumBlock && !Number.isSafeInteger(observedAtMs)) {
        throw new Error('[rpc-quorum] unsafe observedAtMs at finalized block');
      }
      const snapshot = {
        observedAtMs,
        blockNumber: asNumber(blockNumber, 'block number'),
        graceSec: asNumber(grace, 'currentGrace'),
        chatOpenAt: asNumber(chatWin[0], 'chatOpenAt'), chatCloseAt: asNumber(chatWin[1], 'chatCloseAt'),
        resultCloseAt: asNumber(resultWin[1], 'resultCloseAt'),
        params: { START_TIME: asNumber(startTime, 'START_TIME'), BLOCK_TIME: asNumber(blockTime, 'BLOCK_TIME'),
                  GAME_PERIOD: asNumber(gamePeriod, 'GAME_PERIOD'), SUBMIT_PERIOD: asNumber(submitPeriod, 'SUBMIT_PERIOD') },
      };
      if (quorumBlock) await this.storage.delete(`rpc_quorum_wait_block${blockNum}`);
      return snapshot;
    } catch (e) {
      if (quorumClients) await this.noteRpcQuorumFailure(blockNum, e);
      console.warn('[evidence] F-TL5 timeline snapshot unavailable:', e.shortMessage || e.message);
      return null;
    }
  }

  // 延長の送信判断専用。2本照合が落ちた場合だけ、生きた1本から期限を読む。
  // この値は宣言や着地判定には渡さず、契約の extendGrace 検査を通すための手掛かりに限る。
  async readExtensionDecisionSnapshot(blockNum) {
    const matched = await this.readEvidenceTimelineSnapshot(blockNum);
    if (matched) return { ...matched, provisional: false };
    const clients = this.createEvidenceReadClients();
    if (!clients) return null;
    const abi = [
      { name: 'currentGrace', type: 'function', stateMutability: 'view',
        inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] },
      { name: 'chatWindow', type: 'function', stateMutability: 'view',
        inputs: [{ name: 'blockNum', type: 'uint256' }],
        outputs: [{ name: 'chatOpenAt', type: 'uint256' }, { name: 'chatCloseAt', type: 'uint256' }] },
    ];
    try {
      return await Promise.any(clients.map(async (client) => {
        const block = await client.getBlock();
        const [grace, chat] = await Promise.all([
          client.readContract({ address: this.env.EVIDENCE_CONTRACT_ADDRESS, abi,
            functionName: 'currentGrace', args: [BigInt(blockNum)], blockNumber: block.number }),
          client.readContract({ address: this.env.EVIDENCE_CONTRACT_ADDRESS, abi,
            functionName: 'chatWindow', args: [BigInt(blockNum)], blockNumber: block.number }),
        ]);
        const row = { observedAtMs: Number(block.timestamp) * 1000, graceSec: Number(grace),
          chatOpenAt: Number(chat[0]), chatCloseAt: Number(chat[1]), provisional: true };
        if (![row.observedAtMs, row.graceSec, row.chatOpenAt, row.chatCloseAt]
          .every(Number.isSafeInteger)) throw new Error('invalid extension decision snapshot');
        return row;
      }));
    } catch { return null; }
  }

  // F-TL5: env（START_TIME/BLOCK_TIME/GAME_PERIOD/SUBMIT_PERIOD）と Evidence 契約のタイムライン一致検証。
  // 設定ミス（過去の頻出事故「START_TIME 誤設定」と同族）を、壊れた時刻表でゲームを開始する前に
  // fail-fast で顕在化させる。主検査＝生パラメータの直接比較（相殺ズレも検出・どの env 変数かを正確に指す）、
  // 副検査＝消費境界3点の照合（ワーカー転記式のドリフト検出用アサート。パラメータ一致⇒3点一致は
  // Lean check_sound で証明済み）。不一致 → error ログ＋storage 記録＋throw（呼び出し元の init が失敗として
  // 返る。D1 groups は 'formed' のまま＝env 修正後に /init-chat-games 再実行で復旧可能）。
  async verifyEnvChainTimeline(blockNum, declared, chainTL) {
    const startTimeMs = this.env.START_TIME ? (Number(this.env.START_TIME) || Date.parse(this.env.START_TIME)) : NaN;
    const blockTimeMs = this.env.BLOCK_TIME ? parseInt(this.env.BLOCK_TIME) : NaN;
    // Evidence.START_TIME は応募期間【開始】基準 = env START_TIME/1000（Evidence の START_TIME 宣言。
    // TokenMining.START_TIME も同じ基準で、Evidence の constructor が一致を強制する）。
    const envParams = {
      START_TIME: Math.round(startTimeMs / 1000),
      BLOCK_TIME: Math.round(blockTimeMs / 1000),
      GAME_PERIOD: Math.round(this.gamePeriodMs / 1000),
      SUBMIT_PERIOD: Math.round(this.submitPeriodMs / 1000),
    };
    // 🔴 P-2026-0817（2026-08-07）: **必須不変量①を env だけで先に検査する。**
    //   `GAME_PERIOD + SUBMIT_PERIOD + INITIAL_GRACE <= BLOCK_TIME`
    //   （`CLAUDE.md` の「必須不変量」①）。
    //   これまで強制していたのは **Evidence の constructor（＝デプロイ時1回だけ）**で、
    //   ワーカー側の env が契約と食い違っていても、この不変量そのものは誰も見ていなかった。
    //   実測（`timeline-strictness-test.mjs`）: BLOCK_TIME=100s / GAME_PERIOD=60s /
    //   SUBMIT_PERIOD=41s を env・チェーン**両方**に置くと `compareEnvParamsToChainParams` は
    //   「不一致なし」を返し、`closeAt=201000ms`（次ブロック境界 200000ms）で 1000ms 超過していても
    //   何も起きなかった。
    //   ⚠️ 渡してよいのは **初期 grace（env `RESULT_GRACE`）だけ**。
    //      `Evidence.currentGrace(N)` は障害時の延長で①を意図的に超えうる（設計どおり）。
    const invariantProblems = checkTimelineInvariant({
      blockTimeMs,
      gamePeriodMs: this.gamePeriodMs,
      submitPeriodMs: this.submitPeriodMs,
      initialGraceMs: (this.env.RESULT_GRACE ? parseInt(this.env.RESULT_GRACE) : 120) * 1000,
    });
    if (invariantProblems.length > 0) {
      const detail = invariantProblems.join('; ');
      console.error(`[evidence] timeline invariant #1 violated block=${blockNum}: ${detail}`);
      await this.storage.put(`evidence_timeline_mismatch_block${blockNum}`,
        { invariantProblems, at: Date.now() });
      throw new Error(
        `timeline invariant #1 violated for block ${blockNum} (${detail}) — ` +
        `fix the worker env vars (BLOCK_TIME / GAME_PERIOD / SUBMIT_PERIOD / RESULT_GRACE) ` +
        `so that a block finishes before the next one opens`
      );
    }

    const paramDiffs = compareEnvParamsToChainParams(envParams, chainTL.params);
    const boundaryDiffs = compareDeclaredToChainWindows(declared, chainTL);
    if (paramDiffs.length === 0 && boundaryDiffs.length === 0) return { checked: true, ok: true };
    const detail = [...paramDiffs, ...boundaryDiffs].join('; ');
    console.error(`[evidence] F-TL5 env/chain timeline mismatch block=${blockNum}: ${detail}`);
    await this.storage.put(`evidence_timeline_mismatch_block${blockNum}`, { paramDiffs, boundaryDiffs, at: Date.now() });
    throw new Error(`env/chain timeline mismatch for block ${blockNum} (${detail}) — fix the named workers env vars (START_TIME/BLOCK_TIME/GAME_PERIOD/SUBMIT_PERIOD, in ms) to match Evidence ${this.env.EVIDENCE_CONTRACT_ADDRESS}, or fix EVIDENCE_CONTRACT_ADDRESS if it points to a stale deployment`);
  }

  // GM-LATCH: 宣言 grace の正典状態。source='chain' は fallback でない currentGrace、
  // source='intent' は未終端の extendGrace intent の newGraceSec だけを表す。
  declaredGraceKey(blockNum) { return `declared_grace_block${blockNum}`; }

  async enqueueGraceReconcileTask(blockNum, { reason = 'declared_intent_pending', delayMs = GRACE_RECONCILE_RETRY_MS } = {}) {
    const executeAt = Date.now() + Math.max(1, Number(delayMs) || GRACE_RECONCILE_RETRY_MS);
    const queue = await this.storage.get('phase_task_queue') || [];
    const existing = queue.find((task) => task.type === 'grace_reconcile' && task.blockNum === blockNum);
    if (existing) {
      existing.executeAt = Math.min(Number(existing.executeAt) || executeAt, executeAt);
      existing.reason = reason;
    } else {
      queue.push({ type: 'grace_reconcile', blockNum, reason, attempts: 0, executeAt });
    }
    queue.sort((a, b) => a.executeAt - b.executeAt);
    await this.storage.put('phase_task_queue', queue);
    // 部分的な単体ハーネスは state を持たない。実DOでは必ず最早タスクへalarmを張る。
    if (this.state?.storage && typeof this.state.storage.setAlarm === 'function') {
      await this.armEarliestQueuedTask();
    }
    return { executeAt, reason };
  }

  async rememberDeclaredGrace(blockNum, graceSec, detail = {}) {
    if (!Number.isSafeInteger(graceSec) || graceSec < 0) {
      throw new Error(`invalid declared grace for block ${blockNum}: ${graceSec}`);
    }
    const state = {
      blockNum,
      graceSec,
      source: detail.source === 'intent' ? 'intent' : 'chain',
      intentId: detail.source === 'intent' ? detail.intentId : null,
      newGraceSec: detail.source === 'intent' ? graceSec : null,
      pending: detail.source === 'intent',
      terminalObserved: detail.terminalObserved === true,
      watchGraceSec: Number.isSafeInteger(detail.watchGraceSec) ? detail.watchGraceSec : null,
      watchIntentId: typeof detail.watchIntentId === 'string' ? detail.watchIntentId : null,
      watchStartedAt: Number.isSafeInteger(detail.watchStartedAt) ? detail.watchStartedAt : null,
      watchSubmittedHead: Number.isSafeInteger(detail.watchSubmittedHead) ? detail.watchSubmittedHead : null,
      watchSubmittedObserved: detail.watchSubmittedObserved === true,
      watchLastCheckedAt: Number.isSafeInteger(detail.watchLastCheckedAt) ? detail.watchLastCheckedAt : null,
      watchDeadlineAt: Number.isSafeInteger(detail.watchDeadlineAt) ? detail.watchDeadlineAt : null,
      alreadySubmittedHead: Number.isSafeInteger(detail.alreadySubmittedHead) ? detail.alreadySubmittedHead : null,
      alreadySubmittedObserved: detail.alreadySubmittedObserved === true,
      deadlineAt: Number.isSafeInteger(detail.deadlineAt) ? detail.deadlineAt : null,
      caller: detail.caller || null,
      lastRequestedAt: Number.isSafeInteger(detail.lastRequestedAt) ? detail.lastRequestedAt : null,
      reason: detail.reason || null,
      updatedAt: Date.now(),
    };
    await this.storage.put(this.declaredGraceKey(blockNum), state);
    return state;
  }

  async adoptChainGraceDeclaration(blockNum, graceSec, { reschedule = false, reason = 'chain_observed' } = {}) {
    const previous = await this.storage.get(this.declaredGraceKey(blockNum));
    const state = await this.rememberDeclaredGrace(blockNum, graceSec, { source: 'chain', reason });
    if (reschedule && (!previous || previous.graceSec !== graceSec || previous.source !== 'chain')) {
      await this.rescheduleRemainingPhaseTasks(blockNum, graceSec);
    }
    return { state, changed: !previous || previous.graceSec !== graceSec || previous.source !== 'chain' };
  }

  async adoptPendingGraceDeclaration(blockNum, newGraceSec, result, caller, { reschedule = false } = {}) {
    const intentId = result?.intentId || `extendGrace:${blockNum}:${newGraceSec}`;
    const state = await this.rememberDeclaredGrace(blockNum, newGraceSec, {
      source: 'intent', intentId, caller,
      deadlineAt: result?.deadlineAt,
      alreadySubmittedHead: result?.alreadySubmittedHead,
      alreadySubmittedObserved: result?.alreadySubmittedObserved,
      lastRequestedAt: Date.now(),
      reason: result?.reason || result?.status || 'pending',
    });
    if (reschedule) await this.rescheduleRemainingPhaseTasks(blockNum, newGraceSec);
    await this.enqueueGraceReconcileTask(blockNum, { reason: 'declared_intent_pending' });
    return state;
  }

  // extendGrace の応答を宣言へ写す唯一の入口。pending は intent と再送タスクを伴うときだけ
  // 採用し、着地/already_sufficient は必ず読み戻した actual currentGrace を採用する。
  async adoptGraceExtensionResult(blockNum, requestedGraceSec, result, caller, { reschedule = false } = {}) {
    const previous = await this.storage.get(this.declaredGraceKey(blockNum));
    if (result?.reason === 'stale_already_submitted'
        && Number.isSafeInteger(result.currentGrace)) {
      const generationKey = `grace_intent_generation_block${blockNum}_${requestedGraceSec}`;
      await this.storage.put(generationKey, Number(await this.storage.get(generationKey) || 0) + 1);
      if (previous?.source === 'intent' && previous.intentId !== result.intentId
          && previous.graceSec >= requestedGraceSec) {
        return { adopted: false, graceSec: previous.graceSec, source: 'intent', retryNeeded: false };
      }
      await this.adoptChainGraceDeclaration(blockNum, result.currentGrace, {
        reschedule, reason: 'stale_already_submitted',
      });
      return { adopted: false, rolledBack: true, graceSec: result.currentGrace, source: 'chain', retryNeeded: true };
    }
    // 応答が不明な間は Coordinator が同じ intent を受理済みかもしれない。
    // 再送の期限切れを終端扱いせず、既存の観測情報を保って再照会する。
    const coordinatorUnknown = result?.status === 'unavailable'
      && GRACE_COORDINATOR_UNKNOWN_REASONS.has(result.reason);
    if (coordinatorUnknown && previous?.source === 'intent'
        && previous.intentId === (result?.intentId || `extendGrace:${blockNum}:${requestedGraceSec}`)) {
      await this.rememberDeclaredGrace(blockNum, previous.graceSec, {
        ...previous, source: 'intent', terminalObserved: false,
        deadlineAt: Number.isSafeInteger(result?.deadlineAt) ? result.deadlineAt : previous.deadlineAt,
        lastRequestedAt: Date.now(), reason: result.reason,
      });
      await this.enqueueGraceReconcileTask(blockNum, { reason: 'coordinator_response_unavailable' });
      return { adopted: true, graceSec: previous.graceSec, source: 'intent', pending: true };
    }
    if (result?.pending === true || coordinatorUnknown) {
      if (previous?.source === 'intent' && previous.intentId !== result.intentId
          && previous.graceSec >= requestedGraceSec) {
        const keepWatch = Number(previous.watchGraceSec) > requestedGraceSec;
        const sameWatch = typeof result.intentId === 'string'
          && previous.watchIntentId === result.intentId;
        await this.rememberDeclaredGrace(blockNum, previous.graceSec, {
          ...previous, source: 'intent', watchGraceSec: Math.max(requestedGraceSec,
            Number(previous.watchGraceSec) || 0),
          watchIntentId: keepWatch ? previous.watchIntentId : result.intentId,
          watchStartedAt: keepWatch || sameWatch ? previous.watchStartedAt : Date.now(),
          watchSubmittedHead: keepWatch || sameWatch
            ? previous.watchSubmittedHead : result.alreadySubmittedHead,
          watchSubmittedObserved: keepWatch || sameWatch
            ? previous.watchSubmittedObserved : result.alreadySubmittedObserved,
          watchDeadlineAt: keepWatch || sameWatch ? previous.watchDeadlineAt : result.deadlineAt,
          reason: 'smaller_intent_pending',
        });
        await this.enqueueGraceReconcileTask(blockNum, { reason: 'smaller_intent_pending' });
        return { adopted: false, graceSec: previous.graceSec, source: 'intent', pending: true };
      }
      await this.adoptPendingGraceDeclaration(blockNum, requestedGraceSec, result, caller, { reschedule });
      return { adopted: true, graceSec: requestedGraceSec, source: 'intent', pending: true };
    }

    const actualGrace = Number(result?.currentGrace);
    if ((result?.landed === true || result?.reason === 'already_sufficient')
        && Number.isSafeInteger(actualGrace) && actualGrace >= 0 && result?.graceFallback !== true) {
      if (previous?.source === 'intent' && previous.intentId !== result.intentId
          && previous.graceSec > actualGrace) {
        return { adopted: false, graceSec: previous.graceSec, source: 'intent', pending: true };
      }
      await this.adoptChainGraceDeclaration(blockNum, actualGrace, {
        reschedule,
        reason: result.reason === 'already_sufficient' ? 'already_sufficient_readback' : 'extend_landed_readback',
      });
      return { adopted: true, graceSec: actualGrace, source: 'chain', landed: true };
    }

    // 既存ハーネスの同期成功スタブとの後方互換。実運用の extendGraceOnChain は landed と
    // actual currentGrace を必ず付けるため、ここへ入るのは Evidence 無効の単体経路だけ。
    if (result?.extended === true && result?.pending !== true && !this.env.EVIDENCE_CONTRACT_ADDRESS) {
      return { adopted: true, graceSec: requestedGraceSec, source: 'ephemeral', landed: true };
    }

    const sameIntent = previous?.source === 'intent'
      && previous.intentId === (result?.intentId || `extendGrace:${blockNum}:${requestedGraceSec}`);
    // G8: Coordinator が succeeded / already_sufficient を返しても、fresh readback が
    // 読めない／目標未満の landing_unverified は終端ではない。同じ intent の宣言と
    // phase task を維持し、期限までは着地観測を続ける。
    if (sameIntent && result?.reason === 'landing_unverified') {
      const lastRequestedAt = Date.now();
      await this.rememberDeclaredGrace(blockNum, previous.graceSec, {
        ...previous,
        source: 'intent',
        terminalObserved: false,
        alreadySubmittedHead: Number.isSafeInteger(result?.alreadySubmittedHead)
          ? result.alreadySubmittedHead : previous.alreadySubmittedHead,
        alreadySubmittedObserved: result?.alreadySubmittedObserved === true
          || previous.alreadySubmittedObserved === true,
        deadlineAt: Number.isSafeInteger(result?.deadlineAt) ? result.deadlineAt : previous.deadlineAt,
        lastRequestedAt,
        reason: 'landing_readback_pending',
      });
      await this.enqueueGraceReconcileTask(blockNum, { reason: 'landing_readback_pending' });
      return {
        adopted: true, graceSec: previous.graceSec, source: 'intent', pending: true,
        landingUnverified: true,
      };
    }
    if (sameIntent) {
      const chainTL = await this.readEvidenceTimelineSnapshot(blockNum);
      if (chainTL && Number.isSafeInteger(chainTL.graceSec)) {
        await this.adoptChainGraceDeclaration(blockNum, chainTL.graceSec, {
          reschedule: true,
          reason: `intent_terminal:${result?.reason || result?.status || 'unknown'}`,
        });
        if (Number.isSafeInteger(previous.watchGraceSec)
            && chainTL.graceSec < previous.watchGraceSec) {
          await this.rememberDeclaredGrace(blockNum, chainTL.graceSec, {
            source: 'chain', watchGraceSec: previous.watchGraceSec,
            watchIntentId: previous.watchIntentId, watchStartedAt: previous.watchStartedAt,
            watchSubmittedHead: previous.watchSubmittedHead,
            watchSubmittedObserved: previous.watchSubmittedObserved,
            watchDeadlineAt: previous.watchDeadlineAt,
            deadlineAt: previous.watchDeadlineAt ?? previous.deadlineAt,
            reason: 'landing_readback_pending',
          });
          await this.enqueueGraceReconcileTask(blockNum, { reason: 'landing_readback_pending' });
        }
        return { adopted: false, rolledBack: true, graceSec: chainTL.graceSec, source: 'chain' };
      }
      // fallback 中は宣言を動かさず、次の機会にチェーンを読み直してから巻き戻す。
      await this.rememberDeclaredGrace(blockNum, previous.graceSec, {
        ...previous,
        source: 'intent',
        terminalObserved: true,
        reason: result?.reason || result?.status || 'terminal_unreadable',
      });
      await this.enqueueGraceReconcileTask(blockNum, { reason: 'terminal_chain_read_retry' });
    } else if (result?.reason === 'landing_unverified') {
      // 別 intent の暫定値で、既存のより大きい宣言を巻き戻さない。
      const watchGraceSec = Math.max(requestedGraceSec, Number(previous?.watchGraceSec) || 0);
      const preserveWatch = Number(previous?.watchGraceSec) > requestedGraceSec;
      const sameWatch = typeof result.intentId === 'string'
        && previous?.watchIntentId === result.intentId;
      const watch = preserveWatch ? {
        watchIntentId: previous.watchIntentId, watchStartedAt: previous.watchStartedAt,
        watchSubmittedHead: previous.watchSubmittedHead,
        watchSubmittedObserved: previous.watchSubmittedObserved,
        watchDeadlineAt: previous.watchDeadlineAt,
        watchLastCheckedAt: previous.watchLastCheckedAt,
      } : {
        watchIntentId: result.intentId,
        watchStartedAt: sameWatch && Number.isSafeInteger(previous.watchStartedAt)
          ? previous.watchStartedAt : Date.now(),
        watchSubmittedHead: Number.isSafeInteger(result.alreadySubmittedHead)
          ? result.alreadySubmittedHead : (sameWatch ? previous.watchSubmittedHead : null),
        watchSubmittedObserved: result.alreadySubmittedObserved === true
          || (sameWatch && previous.watchSubmittedObserved === true),
        watchDeadlineAt: Number.isSafeInteger(result.deadlineAt)
          ? result.deadlineAt : (sameWatch ? previous.watchDeadlineAt : null),
        watchLastCheckedAt: sameWatch ? previous.watchLastCheckedAt : null,
      };
      const graceSec = Number.isSafeInteger(result?.currentGrace) ? result.currentGrace
        : (previous?.source === 'chain' && Number.isSafeInteger(previous.graceSec)
          ? previous.graceSec
          : (result?.graceFallback !== true && Number.isSafeInteger(result?.chainGraceBefore)
            ? result.chainGraceBefore : null));
      if (previous?.source === 'intent' && previous.graceSec >= requestedGraceSec) {
        await this.rememberDeclaredGrace(blockNum, previous.graceSec, {
          ...previous, source: 'intent', watchGraceSec, ...watch,
          reason: 'landing_readback_pending',
        });
      } else if ((previous?.source === 'intent' && previous.graceSec < requestedGraceSec)
          || (!previous && !Number.isSafeInteger(graceSec))) {
        await this.adoptPendingGraceDeclaration(blockNum, requestedGraceSec, {
          ...result, reason: 'landing_readback_pending',
        }, caller, { reschedule });
      } else if (Number.isSafeInteger(graceSec)) {
        await this.rememberDeclaredGrace(blockNum, graceSec, {
          source: 'chain', watchGraceSec, ...watch,
          deadlineAt: watch.watchDeadlineAt,
          reason: 'landing_readback_pending',
        });
        if (reschedule) await this.rescheduleRemainingPhaseTasks(blockNum, graceSec);
      }
      await this.enqueueGraceReconcileTask(blockNum, { reason: 'landing_readback_pending' });
    }
    return { adopted: false, graceSec: previous?.graceSec ?? null, source: previous?.source ?? null };
  }

  // 現在のチェーン値と宣言を収束させる。fallback は宣言を動かさない。intent が未着地なら
  // 5分ごとに同じ intentId を再送し、終端なら actual chain grace へ巻き戻す。
  async reconcileDeclaredGrace(blockNum, { chainTL = undefined, reschedule = true, forceRetry = false } = {}) {
    if (!this.env.EVIDENCE_CONTRACT_ADDRESS) return null;
    const observed = chainTL === undefined ? await this.readEvidenceTimelineSnapshot(blockNum) : chainTL;
    let previous = await this.storage.get(this.declaredGraceKey(blockNum));
    if (!observed || !Number.isSafeInteger(observed.graceSec)) {
      if (previous?.source === 'intent' || Number.isSafeInteger(previous?.watchGraceSec)) {
        await this.enqueueGraceReconcileTask(blockNum, { reason: 'chain_read_fallback' });
      }
      return previous ? { ...previous, fallback: true, retryNeeded: true } : { fallback: true, retryNeeded: false };
    }

    const chainGrace = observed.graceSec;
    if (previous?.source === 'intent' && Number.isSafeInteger(previous.watchGraceSec)
        && chainGrace < previous.watchGraceSec && previous.watchIntentId
        && Number.isSafeInteger(previous.watchStartedAt)
        && Date.now() - previous.watchStartedAt >= 20 * 60 * 1000
        && Date.now() - Number(previous.watchLastCheckedAt || 0) >= GRACE_RECONCILE_RETRY_MS
        && (!Number.isSafeInteger(previous.watchDeadlineAt)
          || Date.now() < previous.watchDeadlineAt)) {
      const checked = await this.extendGraceOnChain(blockNum, previous.watchGraceSec, {
        intentId: previous.watchIntentId, alreadySubmittedHead: previous.watchSubmittedHead,
          alreadySubmittedObserved: previous.watchSubmittedObserved,
          existingDeadlineAt: previous.watchDeadlineAt, queryCoordinatorRecord: true,
      });
      if (checked.reason === 'stale_already_submitted') {
        await this.adoptGraceExtensionResult(blockNum, previous.watchGraceSec, checked,
          'grace_watch', { reschedule });
        const retried = await this.extendGraceOnChain(blockNum, previous.watchGraceSec);
        await this.adoptGraceExtensionResult(blockNum, previous.watchGraceSec, retried,
          'grace_watch', { reschedule });
      } else {
        await this.rememberDeclaredGrace(blockNum, previous.graceSec, {
          ...previous, source: 'intent', watchLastCheckedAt: Date.now(),
          watchSubmittedHead: checked.alreadySubmittedHead ?? previous.watchSubmittedHead,
          watchSubmittedObserved: checked.alreadySubmittedObserved === true
            || previous.watchSubmittedObserved === true,
        });
      }
      previous = await this.storage.get(this.declaredGraceKey(blockNum));
    }
    if (previous?.source === 'intent' && chainGrace < previous.newGraceSec) {
      const deadlineExpired = Number.isSafeInteger(previous.deadlineAt)
        && Date.now() >= previous.deadlineAt;
      if (deadlineExpired && previous.terminalObserved !== true) {
        // deadlineはCoordinatorが送信可能だった場合の期限であり、鍵差し替え検出による
        // admin_freeze中に運営宣言を巻き戻す根拠にはしない。ここで同じintentを再送すると
        // 凍結判定だけのために管理txを1件増やすので、Coordinatorの読取状態だけで判定する。
        const freezeStatus = await this.readAdminTxFreezeStatus(previous.intentId);
        if (freezeStatus.frozen === true) {
          const frozen = {
            pending: true, accepted: true, status: 'blocked', reason: 'admin_freeze',
            intentId: previous.intentId, newGraceSec: previous.newGraceSec,
            deadlineAt: previous.deadlineAt,
          };
          const adopted = await this.adoptGraceExtensionResult(
            blockNum, previous.newGraceSec, frozen, previous.caller || 'grace_reconcile', { reschedule },
          );
          const current = await this.storage.get(this.declaredGraceKey(blockNum));
          return {
            ...(current || previous), result: frozen, adopted,
            fallback: false, retryNeeded: true, freezePreserved: true,
          };
        }
      }
      if (previous.terminalObserved === true || deadlineExpired) {
        const terminalReason = previous.terminalObserved === true ? (previous.reason || 'unknown') : 'deadline_expired';
        if (deadlineExpired && previous.terminalObserved !== true) {
          await this.storage.put(`evidence_grace_extend_failed_block${blockNum}`, {
            intentId: previous.intentId, newGraceSec: previous.newGraceSec,
            status: 'failed', reason: 'deadline_expired',
            error: 'not_confirmed: deadline_expired', txHash: null,
            deadlineAt: previous.deadlineAt,
            graceSource: 'chain_timeline_snapshot', graceFallback: false,
            at: Date.now(),
          });
        }
        await this.adoptChainGraceDeclaration(blockNum, chainGrace, {
          reschedule,
          reason: `intent_terminal:${terminalReason}`,
        });
        if (Number.isSafeInteger(previous.watchGraceSec)
            && chainGrace < previous.watchGraceSec) {
          await this.rememberDeclaredGrace(blockNum, chainGrace, {
            source: 'chain', watchGraceSec: previous.watchGraceSec,
            watchIntentId: previous.watchIntentId, watchStartedAt: previous.watchStartedAt,
            watchSubmittedHead: previous.watchSubmittedHead,
            watchSubmittedObserved: previous.watchSubmittedObserved,
            watchDeadlineAt: previous.watchDeadlineAt,
            deadlineAt: previous.watchDeadlineAt ?? previous.deadlineAt,
            reason: 'landing_readback_pending',
          });
          await this.enqueueGraceReconcileTask(blockNum, { reason: 'landing_readback_pending' });
        }
        return { graceSec: chainGrace, source: 'chain', rolledBack: true, fallback: false };
      }
      const retryAt = Number(previous.lastRequestedAt) + GRACE_RECONCILE_RETRY_MS;
      if (forceRetry || !Number.isSafeInteger(retryAt) || Date.now() >= retryAt) {
        const result = await this.extendGraceOnChain(blockNum, previous.newGraceSec, {
          intentId: previous.intentId, alreadySubmittedHead: previous.alreadySubmittedHead,
          alreadySubmittedObserved: previous.alreadySubmittedObserved,
          existingDeadlineAt: previous.deadlineAt,
        });
        const adopted = await this.adoptGraceExtensionResult(
          blockNum, previous.newGraceSec, result, previous.caller || 'grace_reconcile', { reschedule },
        );
        if (result?.reason === 'stale_already_submitted') {
          const retried = await this.extendGraceOnChain(blockNum, previous.newGraceSec);
          const retryAdoption = await this.adoptGraceExtensionResult(
            blockNum, previous.newGraceSec, retried, previous.caller || 'grace_reconcile', { reschedule },
          );
          return { result: retried, adopted: retryAdoption, fallback: false,
            retryNeeded: retryAdoption.pending === true };
        }
        const current = await this.storage.get(this.declaredGraceKey(blockNum));
        return { ...(current || {}), result, adopted, fallback: false, retryNeeded: current?.source === 'intent' };
      }
      await this.enqueueGraceReconcileTask(blockNum, {
        reason: 'declared_intent_pending', delayMs: Math.max(1, retryAt - Date.now()),
      });
      return { ...previous, fallback: false, retryNeeded: true };
    }

    // 別 intent（P2 など）がより大きい grace を着地させた場合も、開始済みかを問わず
    // actual chain grace へ合わせる。これは新しい延長ではないので split 防止の対象外。
    const changed = !previous || previous.graceSec !== chainGrace || previous.source !== 'chain';
    await this.adoptChainGraceDeclaration(blockNum, chainGrace, {
      reschedule: reschedule && changed,
      reason: chainGrace > Number(previous?.graceSec ?? -1) ? 'chain_grace_increased' : 'chain_observed',
    });
    const watchPending = Number.isSafeInteger(previous?.watchGraceSec) && chainGrace < previous.watchGraceSec
      && (!Number.isSafeInteger(previous.watchDeadlineAt ?? previous.deadlineAt)
        || Date.now() < (previous.watchDeadlineAt ?? previous.deadlineAt));
    if (watchPending) {
      await this.rememberDeclaredGrace(blockNum, chainGrace, {
        source: 'chain', watchGraceSec: previous.watchGraceSec,
        watchIntentId: previous.watchIntentId,
        watchStartedAt: previous.watchStartedAt,
        watchSubmittedHead: previous.watchSubmittedHead,
        watchSubmittedObserved: previous.watchSubmittedObserved,
        watchLastCheckedAt: previous.watchLastCheckedAt,
        watchDeadlineAt: previous.watchDeadlineAt,
        deadlineAt: previous.deadlineAt,
        reason: 'landing_readback_pending',
      });
      if (previous.watchIntentId && Number.isSafeInteger(previous.watchStartedAt)
          && Date.now() - previous.watchStartedAt >= 20 * 60 * 1000
          && Date.now() - Number(previous.watchLastCheckedAt || 0) >= GRACE_RECONCILE_RETRY_MS) {
        const checked = await this.extendGraceOnChain(blockNum, previous.watchGraceSec, {
          intentId: previous.watchIntentId, alreadySubmittedHead: previous.watchSubmittedHead,
          alreadySubmittedObserved: previous.watchSubmittedObserved,
          existingDeadlineAt: previous.watchDeadlineAt ?? previous.deadlineAt,
          queryCoordinatorRecord: true,
        });
        if (checked.reason === 'stale_already_submitted') {
          await this.adoptGraceExtensionResult(blockNum, previous.watchGraceSec, checked,
            'grace_watch', { reschedule });
          const retried = await this.extendGraceOnChain(blockNum, previous.watchGraceSec);
          const adopted = await this.adoptGraceExtensionResult(blockNum, previous.watchGraceSec,
            retried, 'grace_watch', { reschedule });
          return { result: retried, adopted, retryNeeded: adopted.pending === true, fallback: false };
        }
        await this.rememberDeclaredGrace(blockNum, chainGrace, {
          source: 'chain', watchGraceSec: previous.watchGraceSec,
          watchIntentId: previous.watchIntentId, watchStartedAt: previous.watchStartedAt,
          watchSubmittedHead: checked.alreadySubmittedHead ?? previous.watchSubmittedHead,
          watchSubmittedObserved: checked.alreadySubmittedObserved === true
            || previous.watchSubmittedObserved === true,
          watchLastCheckedAt: Date.now(), watchDeadlineAt: previous.watchDeadlineAt,
          deadlineAt: previous.deadlineAt,
          reason: 'landing_readback_pending',
        });
      }
      await this.enqueueGraceReconcileTask(blockNum, { reason: 'landing_readback_pending' });
    }
    return { graceSec: chainGrace, source: 'chain', changed, fallback: false, retryNeeded: watchPending };
  }

  async runGraceReconcileTask(blockNum) {
    const shieldKey = `grouping_dependency_shield_block${blockNum}`;
    let shield = await this.storage.get(shieldKey);
    if (shield?.targetGraceSec && shield.landed !== true) {
      // P2 固有の30秒依存待ちループは、周24どおり terminal の次回に同じ intent を再送する。
      // この5分監視タスク自身は terminal を重ねて再送せず、pending の着地照合だけを補助する。
      if (shield.closed !== true && shield.lastResultTerminal !== true) {
        await this.shieldDependencyStartWindow(blockNum, shield.reason || 'previous_block_not_ready');
        shield = await this.storage.get(shieldKey);
      }
    }
    const reconciled = await this.reconcileDeclaredGrace(blockNum, { reschedule: true, forceRetry: true });
    shield = await this.storage.get(shieldKey);
    const declaration = await this.storage.get(this.declaredGraceKey(blockNum));
    const shieldNeedsRetry = shield?.targetGraceSec && shield.closed !== true && shield.landed !== true
      && shield.lastResultTerminal !== true;
    const declarationNeedsRetry = declaration?.source === 'intent'
      || Number.isSafeInteger(declaration?.watchGraceSec);
    if (shieldNeedsRetry || declarationNeedsRetry || reconciled?.retryNeeded) {
      await this.enqueueGraceReconcileTask(blockNum, { reason: 'grace_reconcile_pending' });
    }
    return { shield, declaration, reconciled };
  }

  // Evidence.extendGrace(N, newGrace) を admin キーで送信（Merkle提出と同じキー）。
  // 失敗は記録して false（呼び出し側でフォールバック判断）。冪等: 既に十分なら送信しない。
  // 2026-07-25: 旧実装は receipt を待たず投げっぱなしだった＝未確定txを残したまま返るため、
  // 直後に走る collect-DO の registerHash や集計パイプラインの送信と nonce が衝突した。
  // 他経路と同じ sendAdminTx（nonce明示＋置き換え時の再送）に統一し、確定まで待つ。
  // 便 C32F2（C32-B-01）: Evidence.START_PAST_TOLERANCE（秒）。契約は新しい開始（応募終了＋newGrace）が
  // block.timestamp − これ 以下になる延長を "Start in past" で拒否する。immutable なので、読めた値は
  // 同じ Evidence のアドレスの間メモリに持つ。読めない（C32F2 以前の Evidence・RPC 失敗・安全な整数でない）
  // ときは null＝事前検査をしない（従来どおり送り、送信係の模擬実行の StartInPast を start_in_past として受ける）。
  async readStartPastToleranceSec() {
    const address = this.env.EVIDENCE_CONTRACT_ADDRESS;
    if (!address) return null;
    const cacheKey = String(address).toLowerCase();
    if (this.startPastToleranceCache?.address === cacheKey) return this.startPastToleranceCache.sec;
    try {
      const quorumClients = this.createEvidenceReadClients();
      const client = this.createReadOnlyClient();
      if (!client) return null;
      const raw = quorumClients
        ? await this.readEvidenceAtBlock(quorumClients,
          await readMatchingFinalizedBlock(quorumClients), address,
          EVIDENCE_START_PAST_TOLERANCE_ABI, 'START_PAST_TOLERANCE')
        : await client.readContract({
          address, abi: EVIDENCE_START_PAST_TOLERANCE_ABI, functionName: 'START_PAST_TOLERANCE',
        });
      const sec = Number(raw);
      if (!Number.isSafeInteger(sec) || sec < 0) return null;
      this.startPastToleranceCache = { address: cacheKey, sec };
      return sec;
    } catch {
      return null;
    }
  }

  // probeStartedWithRoster は関門の roster_pipeline_late の枝だけが付ける（C32F1・下の already_sufficient）。
  // 返り値の reason 'start_in_past'（便 C32F2）は、送る前の検査か送信係の模擬実行で「新しい開始が
  // 今−START_PAST_TOLERANCE 以下」と分かったもの。失敗の記録（evidence_grace_extend_failed）は書かない
  // （started_with_roster と同じく、延長しないことが正しい終端）。呼び手は今から目標を取り直すか、今の grace で進む。
  async extendGraceOnChain(blockNum, newGraceSec, {
    probeStartedWithRoster = false, intentId: existingIntentId = null,
    existingDeadlineAt = null, alreadySubmittedHead = null, alreadySubmittedObserved = false,
    queryCoordinatorRecord = false,
  } = {}) {
    const contractAddress = this.env.EVIDENCE_CONTRACT_ADDRESS;
    if (!contractAddress) return { extended: false, reason: 'not_configured' };
    const generation = Number(await this.storage.get(`grace_intent_generation_block${blockNum}_${newGraceSec}`) || 0);
    const intentId = existingIntentId || `extendGrace:${blockNum}:${newGraceSec}${generation ? `:retry${generation}` : ''}`;
    let graceObservation = null;
    let deadlineAt = null;
    const recordFailure = async (reason, sent = null, error = null) => {
      await this.storage.put(`evidence_grace_extend_failed_block${blockNum}`, {
        intentId, newGraceSec, status: sent?.status || null, reason,
        error: error || `not_confirmed: ${reason}`,
        txHash: sent?.txHash || null, deadlineAt,
        graceSource: graceObservation?.source ?? null,
        graceFallback: graceObservation?.fallback ?? null,
        at: Date.now(),
      });
    };
    try {
      if (!this.env.ADMIN_TX_COORDINATOR) {
        await recordFailure('coordinator_binding_missing');
        return { extended: false, accepted: false, intentId, reason: 'coordinator_binding_missing' };
      }
      // G2: Coordinator の priority 0 既定（enqueue+60分）を使わない。currentGrace と
      // chatCloseAt を同一の fresh chain snapshot で読み、現在の chatCloseAt を期限にする。
      // 既存 intent の照会は、新規送信の事前検査を通さない。窓が閉じた後でも
      // Coordinator の succeeded 記録を読めるようにする。
      const queryExisting = existingIntentId && Number.isSafeInteger(existingDeadlineAt)
        && (queryCoordinatorRecord || Number.isSafeInteger(alreadySubmittedHead)
          || alreadySubmittedObserved);
      const before = queryExisting
        ? { graceSec: 0, chatOpenAt: 0, chatCloseAt: Math.floor(existingDeadlineAt / 1000),
          observedAtMs: 0, provisional: true }
        : await this.readExtensionDecisionSnapshot(blockNum);
      if (!before || !Number.isSafeInteger(before.graceSec)
          || !Number.isSafeInteger(before.chatCloseAt)) {
        await recordFailure('grace_window_unavailable');
        return {
          extended: false, accepted: false, intentId, reason: 'grace_window_unavailable',
          graceFallback: true,
        };
      }
      if (!before.provisional) graceObservation = {
        graceSec: before.graceSec, source: 'chain_timeline_snapshot', fallback: false,
      };
      deadlineAt = before.chatCloseAt * 1000;
      const current = before.graceSec;
      if (!before.provisional && current >= newGraceSec) {
        const sufficient = {
          extended: false, landed: true, intentId, reason: 'already_sufficient', currentGrace: current,
          deadlineAt,
          graceSource: graceObservation.source, graceFallback: false,
        };
        // C32F1（C32-A-14）: grace が上限（BLOCK_TIME）で頭打ちだと shield の目標は今の grace に等しく、
        // 案 U の判定（下）より先にここへ来る。頼まれたときだけ、同じ読みで開始に達していて
        // [chatOpenAt, chatOpenAt+current) の最後の名簿が非ゼロなら already_sufficient のまま印を添える。
        // 読めなければ印を付けない（already_sufficient は変えず、失敗も記録しない）。
        const startMs = (before.chatOpenAt + current) * 1000;
        if (probeStartedWithRoster === true && this.env.HASH_STORAGE_CONTRACT_ADDRESS
            && before.observedAtMs >= startMs) {
          try {
            const quorumClients = this.createEvidenceReadClients();
            const row = quorumClients
              ? await this.readEvidenceAtBlock(quorumClients,
                await readMatchingFinalizedBlock(quorumClients), this.env.HASH_STORAGE_CONTRACT_ADDRESS,
                HASH_STORAGE_ABI, 'rosterLastIn',
                [BigInt(blockNum), BigInt(before.chatOpenAt), BigInt(before.chatOpenAt + current)])
              : await this.createReadOnlyClient().readContract({
                address: this.env.HASH_STORAGE_CONTRACT_ADDRESS, abi: HASH_STORAGE_ABI,
                functionName: 'rosterLastIn',
                args: [BigInt(blockNum), BigInt(before.chatOpenAt), BigInt(before.chatOpenAt + current)],
              });
            if (String(row[1]).toLowerCase() !== `0x${'0'.repeat(64)}`) {
              return { ...sufficient, startedWithRoster: true, chattingStart: startMs };
            }
          } catch (e) {
            console.warn(`[evidence] block ${blockNum}: started-with-roster probe unavailable:`, e.shortMessage || e.message);
          }
        }
        return sufficient;
      }
      // 案 U: チェーンの現在の開始に到達済みで、その窓に非ゼロの正典名簿が
      // あれば延長しない。遅れて着地した名簿は旧窓の外なのでここでは数えない。
      const currentStartMs = (before.chatOpenAt + current) * 1000;
      if (!queryExisting && before.observedAtMs >= currentStartMs
          && !this.env.HASH_STORAGE_CONTRACT_ADDRESS) {
        await recordFailure('roster_chain_unavailable');
        return { extended: false, accepted: false, intentId, reason: 'roster_chain_unavailable' };
      }
      if (!before.provisional && before.observedAtMs >= currentStartMs && this.env.HASH_STORAGE_CONTRACT_ADDRESS) {
        let row = null;
        try {
          const quorumClients = this.createEvidenceReadClients();
          row = quorumClients
            ? await this.readEvidenceAtBlock(quorumClients,
              await readMatchingFinalizedBlock(quorumClients), this.env.HASH_STORAGE_CONTRACT_ADDRESS,
              HASH_STORAGE_ABI, 'rosterLastIn',
              [BigInt(blockNum), BigInt(before.chatOpenAt), BigInt(before.chatOpenAt + current)])
            : await this.createReadOnlyClient().readContract({
              address: this.env.HASH_STORAGE_CONTRACT_ADDRESS, abi: HASH_STORAGE_ABI,
              functionName: 'rosterLastIn',
              args: [BigInt(blockNum), BigInt(before.chatOpenAt), BigInt(before.chatOpenAt + current)],
            });
        } catch (error) {
          if (!this.createEvidenceReadClients()) throw error;
          console.warn(`[evidence] block ${blockNum}: roster preflight unavailable; contract will check:`, error?.message || error);
        }
        if (row && String(row[1]).toLowerCase() !== `0x${'0'.repeat(64)}`) {
          // 遅れた開始の印（started_with_roster_late）は呼び手が「開始の延長を実際に見送った」
          // ときだけ書く（noteStartedWithRosterLate・C31-08）。ここでは書かない。
          return {
            extended: false, accepted: false, intentId, reason: 'started_with_roster',
            currentGrace: current, chattingStart: currentStartMs, deadlineAt,
          };
        }
      }
      // 便 C32F2（C32-B-01）: 案 U の判定の後で、新しい開始が 今−START_PAST_TOLERANCE 以下なら送らない
      // （契約が "Start in past" で拒否する）。着地は今より後なので、今で満たさないものは必ず落ちる。
      // 上限で頭打ちの shield・submitting の遅れの自動延長・手動の過去の値がここで止まる。未来を狙う延長は通る。
      const startPastToleranceSec = before.provisional ? null : await this.readStartPastToleranceSec();
      if (!before.provisional && Number.isSafeInteger(startPastToleranceSec)) {
        const newStartSec = before.chatOpenAt + newGraceSec;
        const nowSec = Math.floor(Math.max(before.observedAtMs, Date.now()) / 1000);
        if (newStartSec + startPastToleranceSec <= nowSec) {
          return {
            extended: false, accepted: false, intentId, reason: 'start_in_past',
            newStartSec, startPastToleranceSec, observedAtSec: nowSec,
            currentGrace: current, deadlineAt,
          };
        }
      }
      const sent = await this.sendAdminTx({
        intentId,
        operation: 'extendGrace',
        payload: { blockNum, newGraceSec },
        deadlineAt,
      });
      if (sent.alreadySubmitted && sent.status === 'succeeded') {
        const readback = await this.readEvidenceTimelineSnapshot(blockNum);
        if (readback && Number.isSafeInteger(readback.graceSec) && readback.graceSec >= newGraceSec) {
          return {
            extended: false, landed: true, intentId, reason: 'already_sufficient',
            currentGrace: readback.graceSec, deadlineAt,
            graceSource: 'chain_timeline_readback', graceFallback: false,
          };
        }
        const observedHead = alreadySubmittedHead ?? sent.observedHead ?? sent.observedHeadNumber;
        let head = observedHead == null ? null : Number(observedHead);
        if (!Number.isSafeInteger(head)) head = null;
        if (head === null) {
          try {
            const clients = this.createEvidenceReadClients();
            const latest = clients ? (await readMatchingHeadBlock(clients)).number : null;
            const candidate = Number(latest);
            if (latest != null && Number.isSafeInteger(candidate)) head = candidate;
          } catch { /* 一致 latest が読めなければ単一の latest を記録する。 */ }
          if (head === null) {
            try {
              const latest = await this.createReadOnlyClient()?.getBlockNumber();
              const candidate = Number(latest);
              if (latest != null && Number.isSafeInteger(candidate)) head = candidate;
            } catch { /* head を読めなければ次の照会で待つ。 */ }
          }
        }
        const quorumClients = this.createEvidenceReadClients();
        let finalized = quorumClients ? readback : null;
        if (!quorumClients) {
          try {
            const client = this.createReadOnlyClient();
            const block = await client.getBlock({ blockTag: 'finalized' });
            const grace = await client.readContract({
              address: contractAddress,
              abi: [{ name: 'currentGrace', type: 'function', stateMutability: 'view',
                inputs: [{ name: 'blockNum', type: 'uint256' }],
                outputs: [{ name: '', type: 'uint256' }] }],
              functionName: 'currentGrace', args: [BigInt(blockNum)], blockNumber: block.number,
            });
            finalized = { blockNumber: Number(block.number), graceSec: Number(grace) };
          } catch { /* finalized が読めない間は古い intent を終端と断定しない。 */ }
        }
        if (finalized && Number.isSafeInteger(finalized.blockNumber)
            && Number.isSafeInteger(finalized.graceSec)
            && finalized.graceSec < newGraceSec
            && head !== null) {
          const confirmations = this.env.CONFIRMATION_BLOCKS
            ? Number.parseInt(this.env.CONFIRMATION_BLOCKS, 10) : 64;
          if (Number.isSafeInteger(confirmations) && confirmations >= 0
              && Number.isSafeInteger(head + confirmations)
              && finalized.blockNumber > head + confirmations) {
            return {
              extended: false, intentId, reason: 'stale_already_submitted',
              currentGrace: finalized.graceSec, deadlineAt, alreadySubmittedHead: head,
              alreadySubmittedObserved: true,
            };
          }
        }
        return {
          extended: false, intentId, reason: 'landing_unverified', currentGrace: readback?.graceSec ?? null,
          ...(before.provisional ? {} : { chainGraceBefore: current }),
          alreadySubmittedHead: head, watchGraceSec: newGraceSec, deadlineAt,
          alreadySubmittedObserved: true,
          graceSource: readback ? 'chain_timeline_readback' : 'coordinator_preflight_readback_failed',
          graceFallback: !readback || before.provisional,
        };
      }
      // Coordinator は enqueue 応答内で broadcast まで進めるが receipt は後続alarmで確定する。
      // queued/allocating/waiting_*/blocked/in_flight は着地ではない。呼び手が宣言へ採用する場合は
      // adoptPendingGraceDeclaration が同一intentの5分再送を必ず同時に開始する。
      const pending = sent.accepted === true && GRACE_PENDING_STATUSES.has(sent.status);
      if (!sent.submitted && pending) {
        console.warn(`[evidence] extendGrace queued block=${blockNum} newGrace=${newGraceSec}s reason=${sent.reason} tx=${sent.txHash}`);
        return {
          extended: true, pending: true, accepted: true, intentId,
          status: sent.status, reason: sent.reason, deadlineAt,
          txHash: sent.txHash, newGraceSec,
          graceSource: graceObservation?.source ?? null,
          graceFallback: graceObservation?.fallback ?? null,
        };
      }
      if (!sent.submitted) {
        if (String(sent.reason || '').includes('StartedWithRoster')) {
          return {
            extended: false, accepted: false, intentId, reason: 'started_with_roster',
            currentGrace: current, chattingStart: currentStartMs, deadlineAt,
          };
        }
        // 便 C32F2: 事前検査の後、送信係の列や着地の遅れで開始が許容幅を越えて過去になった競合。
        if (String(sent.reason || '').includes('StartInPast')) {
          return {
            extended: false, accepted: false, intentId, reason: 'start_in_past',
            newStartSec: before.chatOpenAt + newGraceSec,
            startPastToleranceSec: startPastToleranceSec ?? null,
            currentGrace: current, deadlineAt, status: sent.status,
          };
        }
        if (sent.status === 'unavailable'
            && GRACE_COORDINATOR_UNKNOWN_REASONS.has(sent.reason)) {
          return {
            extended: false, pending: true, accepted: false, intentId,
            status: sent.status, reason: sent.reason, deadlineAt, txHash: sent.txHash,
            newGraceSec,
            graceSource: graceObservation?.source ?? null,
            graceFallback: graceObservation?.fallback ?? null,
          };
        }
        console.error(`[evidence] extendGrace NOT confirmed block=${blockNum} reason=${sent.reason} tx=${sent.txHash}`);
        await recordFailure(sent.reason || sent.status || 'not_confirmed', sent);
        return {
          extended: false, accepted: sent.accepted === true, intentId,
          status: sent.status, reason: sent.reason, deadlineAt, txHash: sent.txHash,
          graceSource: graceObservation?.source ?? null,
          graceFallback: graceObservation?.fallback ?? null,
        };
      }
      // Coordinator の succeeded/receipt だけを宣言の着地根拠にしない。fresh currentGrace が
      // 実際に目標へ達した読みだけを landed とする。
      const readback = await this.readEvidenceTimelineSnapshot(blockNum);
      if (!readback || !Number.isSafeInteger(readback.graceSec) || readback.graceSec < newGraceSec) {
        return {
          extended: false, accepted: true, intentId, status: sent.status,
          reason: 'landing_unverified', deadlineAt, txHash: sent.txHash,
          currentGrace: readback?.graceSec ?? null,
          ...(before.provisional ? {} : { chainGraceBefore: current }),
          watchGraceSec: newGraceSec,
          graceSource: readback ? 'chain_timeline_readback' : 'chain_readback_failed',
          graceFallback: !readback,
        };
      }
      console.log(`[evidence] extendGrace confirmed block=${blockNum} newGrace=${newGraceSec}s tx=${sent.txHash} attempts=${sent.attempts}`);
      await this.storage.put(`evidence_grace_extended_block${blockNum}`, {
        intentId, newGraceSec, currentGrace: readback.graceSec,
        txHash: sent.txHash, deadlineAt, at: Date.now(),
      });
      return {
        extended: true, landed: true, accepted: true, intentId,
        status: sent.status, reason: sent.reason, deadlineAt,
        txHash: sent.txHash, newGraceSec, currentGrace: readback.graceSec,
        graceSource: 'chain_timeline_readback', graceFallback: false,
      };
    } catch (e) {
      console.error(`[evidence] extendGrace failed block=${blockNum}:`, e.shortMessage || e.message);
      await recordFailure('tx_error', null, String(e.shortMessage || e.message));
      return {
        extended: false, accepted: false, intentId, reason: 'tx_error',
        error: e.shortMessage || e.message, deadlineAt,
        graceSource: graceObservation?.source ?? null,
        graceFallback: graceObservation?.fallback ?? null,
      };
    }
  }

  // 自動 grace 延長＋残タスクの組み直し（alarm 遅延 = DO障害からの復帰時）。
  // 注意: extendGrace はチャット窓終端（宣言 submitting 開始時刻）より前しか成功しない。
  // 'submitting' 遷移が窓終端を跨いで遅れた場合は延長不可（遡及再開の禁止＝文書化済み残存リスク）
  // — その場合は旧タイムラインのまま進める（失敗は evidence_grace_extend_failed に記録される）。
  // 便 C32F2（C32-B-01）: 'submitting' の遅れの延長は新しい開始が「今−GAME_PERIOD＋300秒」になるので、
  // 名簿なしのブロックでも START_PAST_TOLERANCE（本番3600／E2E 60 < GAME_PERIOD−300）以上過去になり、
  // extendGraceOnChain が送らずに start_in_past を返す（名簿つきは従来どおり started_with_roster）。
  // どちらも旧タイムラインのまま進める。'chatting' の遅れの延長は開始を「今＋300秒」に置くので通る。
  async autoExtendAndReschedule(currentTask, latenessMs, taskQueue) {
    const blockNum = currentTask.blockNum;
    void taskQueue;
    // P3 intent の終端が見えている場合も、この P4 実行を「次の機会」として即照合する。
    // ただし目標の床には、巻戻し前の宣言と、この task が作られた宣言の双方を残す。
    const declarationBeforeReconcile = await this.storage.get(this.declaredGraceKey(blockNum));
    const reconciled = await this.reconcileDeclaredGrace(blockNum, { reschedule: true, forceRetry: true });
    const savedDeclaration = await this.storage.get(this.declaredGraceKey(blockNum));
    const zeroGraceTimeline = this.getDeclaredTimesMs(blockNum, 0);
    const inferredGraceSec = zeroGraceTimeline && Number.isFinite(Number(currentTask.executeAt))
      ? Math.max(0, Math.round((Number(currentTask.executeAt) - (
          currentTask.targetPhase === 'submitting'
            ? zeroGraceTimeline.submittingStart
            : zeroGraceTimeline.chattingStart
        )) / 1000))
      : null;
    // G6: 遅れは宣言から作られた task.executeAt から測り、基準も currentGrace ではなく
    // 宣言 grace とする。旧taskに宣言stateが無い場合だけ task 自身から grace を逆算する。
    const graceFloors = [
      declarationBeforeReconcile?.graceSec,
      savedDeclaration?.graceSec,
      reconciled?.graceSec,
      inferredGraceSec,
    ].filter(Number.isSafeInteger);
    const declaredGraceSec = graceFloors.length > 0
      ? Math.max(...graceFloors)
      : (this.env.RESULT_GRACE ? parseInt(this.env.RESULT_GRACE) : 120);
    const declaredLatenessMs = Number.isFinite(Number(currentTask.executeAt))
      ? Math.max(0, Date.now() - Number(currentTask.executeAt))
      : Math.max(0, Number(latenessMs) || 0);
    const neededGraceSec = declaredGraceSec + Math.ceil(declaredLatenessMs / 1000) + 300;
    const res = await this.extendGraceOnChain(blockNum, neededGraceSec);
    if (res?.reason === 'started_with_roster') {
      // chatting の遅れだけが「遅れた開始」。submitting の遅れは開始と無関係なので印を書かない（C31-08）。
      if (currentTask.targetPhase === 'chatting') {
        await this.noteStartedWithRosterLate(blockNum, 'chatting_alarm_late', res);
      }
      return null;
    }
    const adoption = await this.adoptGraceExtensionResult(
      blockNum, neededGraceSec, res, 'auto_extend', { reschedule: false },
    );
    // P4 自身の延長が終端しても、直前の reconcile で P3 intent を chain へ巻き戻した／
    // 別 intent の大きい chain 値へ追従したなら、dequeue 済みの現在タスクにもその境界を返す。
    // 保存宣言すら無い（chain fallback）場合だけ、従来どおり現在タスクを動かさない。
    const effectiveDeclaration = await this.storage.get(this.declaredGraceKey(blockNum));
    const effectiveGraceSec = adoption.adopted
      ? adoption.graceSec
      : effectiveDeclaration?.graceSec;
    if (!Number.isSafeInteger(effectiveGraceSec)) return null;

    const declared = this.getDeclaredTimesMs(blockNum, effectiveGraceSec);
    if (!declared) return null;

    // 配信中のタイムラインも新graceへ追従（失敗してもリスケ本体は続行）
    try {
      await this.updateBlockSummaryTimeline(blockNum, declared, effectiveGraceSec);
    } catch (err) {
      console.error(`Error updating block summary timeline in R2 for block ${blockNum}:`, err);
    }

    // このブロックの残タスクを新しい宣言タイムラインへ更新。
    // 直前の extendGraceOnChain（オンチェーンtx）でDO入力ゲートが開くため、その間に
    // /extend-grace(rescheduleRemainingPhaseTasks) や新ブロックの schedulePhaseTransitions が
    // phase_task_queue を更新している可能性がある。引数の（古い）taskQueue を書き戻すと
    // それらを消してしまう（lost-update）ので、fresh を読み直して適用する。
    // get→同期変更→put の間に外部I/O awaitが無いのでこの区間はアトミック。
    const freshQueue = await this.storage.get('phase_task_queue') || [];
    let changed = false;
    for (const t of freshQueue) {
      if (t.type !== 'phase_transition' || t.blockNum !== blockNum) continue;
      if (t.targetPhase === 'submitting') {
        t.executeAt = declared.submittingStart; t.phaseEndTime = declared.closeAt; changed = true;
      } else if (t.targetPhase === 'completed') {
        t.executeAt = declared.completedAt; t.phaseEndTime = null; changed = true;
      }
    }
    // 現在実行中の遷移の宣言終了時刻
    const phaseEndTime = currentTask.targetPhase === 'chatting' ? declared.submittingStart
      : currentTask.targetPhase === 'submitting' ? declared.closeAt
      : null;
    const executeAt = currentTask.targetPhase === 'chatting' ? declared.chattingStart
      : currentTask.targetPhase === 'submitting' ? declared.submittingStart
      : currentTask.executeAt;

    // Block 19 実測（2026-09-03）: 旧実装は grace と R2 timeline を後ろへ動かした直後、
    // dequeue 済みの現在タスクだけをその場で実行した。そのため ChatGameDO は新しい
    // chattingStart より約5分早く chatting へ進み、runner が送った全actionが正典窓外に
    // なった。現在タスクも同じ fresh queue 書込みへ戻し、正典の開始時刻まで待たせる。
    // active marker はこの put 後まで残るため、直後に isolate が死んでも resurrection が
    // inQueue を検知して二重延長せず marker だけを片づけられる。
    let requeued = false;
    if (Number.isSafeInteger(executeAt) && executeAt > Date.now()) {
      const existingCurrent = freshQueue.find((t) =>
        t.type === 'phase_transition' && t.blockNum === blockNum
        && t.targetPhase === currentTask.targetPhase);
      const shiftedCurrent = {
        ...currentTask,
        executeAt,
        phaseEndTime,
        phaseEndTimeSource: 'scheduled_chain_rescheduled',
      };
      if (existingCurrent) Object.assign(existingCurrent, shiftedCurrent);
      else freshQueue.push(shiftedCurrent);
      changed = true;
      requeued = true;
    }
    if (changed) {
      freshQueue.sort((a, b) => a.executeAt - b.executeAt);
      await this.storage.put('phase_task_queue', freshQueue);
      console.log(`[evidence] rescheduled current/remaining tasks for block ${blockNum} (grace=${effectiveGraceSec}s)`);
    }

    return { executeAt, phaseEndTime, requeued };
  }

  // GM-LATCH 共通: phase_task_queue の残タスクを指定 grace の宣言タイムラインへ組み替え、
  // 最も早い未来タスクへ alarm を張り直す。未実行の chatting も含めて3本を揃える。
  // 開始済みの chatting task は既に dequeue 済みなので、実行中のチャットを後退させることはない。
  async rescheduleRemainingPhaseTasks(blockNum, graceSec) {
    const declared = this.getDeclaredTimesMs(blockNum, graceSec);
    if (!declared) return { rescheduled: false, reason: 'no_declared_times' };

    // 配信中のタイムラインも新graceへ追従（失敗してもリスケ本体は続行）
    try {
      await this.updateBlockSummaryTimeline(blockNum, declared, graceSec);
    } catch (err) {
      console.error(`Error updating block summary timeline in R2 for block ${blockNum}:`, err);
    }

    const taskQueue = await this.storage.get('phase_task_queue') || [];
    let changed = false;
    for (const t of taskQueue) {
      if (t.type !== 'phase_transition' || t.blockNum !== blockNum) continue;
      if (t.targetPhase === 'chatting') {
        t.executeAt = declared.chattingStart; t.phaseEndTime = declared.submittingStart; changed = true;
      } else if (t.targetPhase === 'submitting') {
        t.executeAt = declared.submittingStart; t.phaseEndTime = declared.closeAt; changed = true;
      } else if (t.targetPhase === 'completed') {
        t.executeAt = declared.completedAt; t.phaseEndTime = null; changed = true;
      }
    }
    if (changed) {
      taskQueue.sort((a, b) => a.executeAt - b.executeAt);
      await this.storage.put('phase_task_queue', taskQueue);
      if (this.state?.storage && typeof this.state.storage.setAlarm === 'function') {
        await this.armEarliestQueuedTask();
      }
      console.log(`[evidence] timeline reschedule block ${blockNum} (grace=${graceSec}s): chattingStart=${new Date(declared.chattingStart).toISOString()}, submittingStart=${new Date(declared.submittingStart).toISOString()}, closeAt=${new Date(declared.closeAt).toISOString()}`);
    }
    const times = taskQueue
      .filter(t => t.type === 'phase_transition' && t.blockNum === blockNum)
      .map(t => ({ phase: t.targetPhase, executeAt: new Date(t.executeAt).toISOString() }));
    return { rescheduled: changed, tasks: times };
  }

  // ============================================================
  // 🔴 P-2026-0813（2026-08-07）: 旧 reconcileEvidence（モノリス版）を**削除**した
  // ============================================================
  // 呼び出し元はゼロだった（/reconcile-evidence は calculateAndStoreResults を呼ぶ）。
  // 現行の calcEvidenceUnit と**規則が違う**まま置き去りになっていたのが危険だった:
  //   ・membersIndex を **ChatGameDO が返した members** から作っていた
  //     （現行は D1 game_groups が権威）。配線し直すとメンバーシップの権威が
  //     D1 から DO へ黙って移り、運営が名簿を差し替えられる状態に戻る
  //   ・INSERT OR REPLACE で evidence_events を書いていた（現行の世界整合ガードが無い）
  // 復活させたくなったら calcEvidenceUnit を直すこと。ここに旧版を戻してはならない。

  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (request.method === 'OPTIONS') {
      return createCORSResponse({}, 200);
    }
    if ((path === '/reset-admin-tx' && request.method === 'DELETE') || (path === '/admin-tx-status' && request.method === 'GET')) return this.handleAdminTxControl(request, path);
    // グループ分け開始
    if (path === '/start-grouping' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      const body = await request.json();
      const { block_num, recover_park } = body;

      if (block_num === undefined || block_num === null) {
        return createCORSResponse({ error: 'block_num is required' }, 400);
      }

      const result = await this.startGrouping(block_num, undefined, { recoverPark: recover_park === true });
      return createCORSResponse(result);
    }

    // 手動チャットゲーム初期化（管理者用）
    if (path === '/init-chat-games' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      const body = await request.json();
      const { block_num, force } = body;

      if (block_num === undefined || block_num === null) {
        return createCORSResponse({ error: 'block_num is required' }, 400);
      }

      // v3.2: 早着ガードは撤去（グループ分け完了後即init）。force は後方互換で受理するのみ
      const result = await this.initChatGames(block_num, { force: !!force, manual: true });
      return createCORSResponse(result);
    }

    // 手動フェーズ遷移（管理者用）
    if (path === '/advance-phase' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }
      if (!verifyLoadTestMutationContext(request, this.env)) {
        return createCORSResponse({ error: 'Test deployment context mismatch' }, 403);
      }

      const body = await request.json();
      const { block_num, phase } = body;

      if (block_num === undefined || block_num === null) {
        return createCORSResponse({ error: 'block_num is required' }, 400);
      }
      if (!phase) {
        return createCORSResponse({ error: 'phase is required' }, 400);
      }

      // S3-009（2026-07-29）: 手動遷移でも**フェーズ終了時刻は宣言タイムライン**を使う。
      // 旧実装は declaredEndTime を渡さないため `now + 期間` になり、手動で遷移させた瞬間から
      // 期間を測り直していた。オンチェーンの chat/result 窓とカウントダウンが食い違い、
      // 「画面の残り時間は残っているのにチェーンの窓は閉じている」状態を運営が作れてしまう。
      // ここは**読み取りのみ**（`resolveDeclaredTimeline` は遅延時に extendGrace tx を送るため使わない）。
      let declaredEndTime = null;
      let phaseTimingMeta = {
        phaseEndTimeSource: phase === 'completed' ? 'none_completed' : 'manual_duration_fallback',
        manualFallback: phase !== 'completed',
        graceSource: 'not_attempted',
        graceReadError: null,
      };
      try {
        const graceObservation = await this.readEvidenceGraceSecWithSource(block_num);
        phaseTimingMeta.graceSource = graceObservation.source;
        phaseTimingMeta.graceReadError = graceObservation.error;
        const declared = this.getDeclaredTimesMs(block_num, graceObservation.graceSec);
        if (declared) {
          if (phase === 'chatting') declaredEndTime = declared.submittingStart;
          else if (phase === 'submitting') declaredEndTime = declared.closeAt;
        }
        if (declaredEndTime != null) {
          phaseTimingMeta.phaseEndTimeSource = graceObservation.fallback
            ? `manual_declared_${graceObservation.source}`
            : 'manual_declared_chain';
          phaseTimingMeta.manualFallback = graceObservation.fallback;
        }
      } catch (e) {
        if (e?.code === 'rpc_quorum_unavailable') {
          return createCORSResponse({ error: 'Evidence RPC quorum unavailable; phase transition is waiting' }, 503);
        }
        phaseTimingMeta.graceSource = 'failed';
        phaseTimingMeta.graceReadError = this.observationErrorText(e);
        console.warn(`[phase] manual advance: declared timeline unavailable for block ${block_num}:`, e.message);
      }

      // advancePhase は呼出し直後（最初のawaitより前）にこの一回限りのメタを取り込む。
      // 既存の3引数呼出し契約は維持し、時刻の出所だけ観測面へ追加する。
      this._nextPhaseTimingMeta = phaseTimingMeta;
      const result = await this.advancePhase(block_num, phase, declaredEndTime);
      return createCORSResponse(result);
    }

    // グループ分け状況確認
    if (path === '/group-status' && request.method === 'GET') {
      const blockParam = url.searchParams.get('block');
      if (blockParam === null || blockParam.trim() === '') {
        return createCORSResponse({ error: 'block parameter is required' }, 400);
      }
      const blockNum = Number(blockParam);
      if (!Number.isSafeInteger(blockNum) || blockNum < 0 || blockNum > MAX_PUBLIC_BLOCK_NUMBER) {
        return createCORSResponse({ error: `block must be a safe integer between 0 and ${MAX_PUBLIC_BLOCK_NUMBER}` }, 400);
      }
      const deep = url.searchParams.get('deep') === '1';
      const lifecycle = url.searchParams.get('lifecycle') === '1'; // D-07: 開始の関門・延長と同じ運営の鍵つきRPC枠を読む
      if ((deep || lifecycle) && !this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      // 旧revisionが「前ブロック未確定」を通常failedとして永続化した場合も、既存の公開pollを
      // 復旧トリガーとして一度だけwatchdogへ戻す。対象は保存済みfailed＋厳密な依存待ち文言だけ。
      // 任意blockの新規groupingを起動する入口にはしない。
      try {
        await this.requeueLegacyGroupingDependency(blockNum);
      } catch (error) {
        // 復旧キュー投入の一過性失敗で、観測用のGET自体を500にしない。
        // 永続化したfailedは残るので、次のpollが同じ安全な再試行を行える。
        console.error(`[grouping] legacy dependency requeue failed for block ${blockNum}:`, error.message);
      }
      const status = await this.getGroupStatus(blockNum, { deep });
      // オンチェーン・ライフサイクル（提出→検証期間→請求期間）はRPCを叩くので lifecycle=1 のときだけ。D-07（2026-09-26 ユーザー決定）で deep と同じく API_SECRET 必須（無認証は上で401・チェーンを読まない）。
      if (lifecycle) {
        status.lifecycle = await this.readBlockLifecycle(blockNum);
      }
      return createCORSResponse(status);
    }

    // ゲーム結果取得
    if (path === '/game-results' && request.method === 'GET') {
      const blockParam = url.searchParams.get('block');
      const groupParam = url.searchParams.get('group');

      if (!blockParam || !groupParam) {
        return createCORSResponse({ error: 'block and group parameters are required' }, 400);
      }

      const blockNum = parseInt(blockParam);
      const groupId = parseInt(groupParam);

      const noGameState = await this.readTimelineNoGamePublicState(blockNum);
      if (noGameState?.status === 'completed') {
        return createCORSResponse({
          blockNum, groupId: null, results: [], noGame: true,
          noGameReason: 'timeline_unverified',
        });
      }
      if (noGameState?.status === 'pending') {
        return createCORSResponse({
          blockNum, groupId: null, results: [], noGame: false,
          reason: 'timeline_no_game_finalizing',
        }, 503);
      }

      const db = this.env.BITCOINU_DATA;
      if (!db) {
        return createCORSResponse({ error: 'BITCOINU_DATA binding not found' }, 500);
      }

      const { results } = await db.prepare(
        `SELECT userId, role, deposit_id, address, btcu_reward, deposit_to, claimed, created_at FROM game_results WHERE block_num = ? AND group_id = ?`
      ).bind(blockNum, groupId).all();

      // cleanup marker が失われた移行時にも、無効化済みgroupから結果を復活させない。
      const groupState = await db.prepare(
        'SELECT status FROM game_groups WHERE block_num = ? AND group_id = ?'
      ).bind(blockNum, groupId).first();
      if (groupState?.status === TIMELINE_NO_GAME_INVALIDATED_STATUS) {
        return createCORSResponse({
          blockNum, groupId: null, results: [], noGame: true,
          noGameReason: 'timeline_unverified',
        });
      }

      // game_groups.resultから詳細データをマージ（ポイント、投票、密告情報）
      let mergedResults = results || [];
      try {
        const groupRow = await db.prepare(
          `SELECT result FROM game_groups WHERE block_num = ? AND group_id = ?`
        ).bind(blockNum, groupId).first();
        if (groupRow?.result) {
          const resultJson = JSON.parse(groupRow.result);
          // P-2026-0823: **`Object.create(null)`**。素の `{}` だと
          //   ・uid=`__proto__` のメンバーの `memberMap[uid] = mr` が [[Prototype]] 設定に化け、
          //     索引が `mr` のフィールド名（`uid` / `totalPoints` / `btcuReward` …）を
          //     「メンバー」として持つようになる → uid がその名前の別メンバーで
          //     `if (detail)` が数値/真偽値を拾い、行の実値が undefined で塗り潰される
          //   ・memberResults に載っていない uid=`toString` 等でも同じく `if (detail)` が通る
          const memberMap = Object.create(null);
          for (const mr of (resultJson.memberResults || [])) {
            memberMap[mr.uid] = mr;
          }
          const depositorMap = {};
          for (const dr of (resultJson.depositorResults || [])) {
            const key = `${dr.depositorUid}_${dr.depositId}`;
            depositorMap[key] = dr;
          }
          mergedResults = mergedResults.map(r => {
            if (r.role === 'player' || !r.role) {
              const detail = memberMap[r.userId];
              if (detail) {
                return {
                  ...r,
                  deposit_points: detail.depositPoints,
                  bonus_points: detail.bonusPoints,
                  total_points: detail.totalPoints,
                  is_disqualified: detail.isDisqualified ? 1 : 0,
                  disqualify_reason: detail.disqualifyReason || null,
                  report_gain_points: detail.reportGainPoints || 0,
                  vote_target_uid: detail.voteTargetUid || null,
                  report_target_uids: detail.reportTargetUids || null,
                  voted_by_uids: detail.votedByUids || null
                };
              }
            }
            return r;
          });
        }
      } catch (e) {
        console.error('Error merging game_groups detail:', e);
      }

      return createCORSResponse({ blockNum, groupId, results: mergedResults });
    }

    // ユーザーのグループ検索
    if (path === '/my-group' && request.method === 'GET') {
      const blockParam = url.searchParams.get('block');
      const uid = url.searchParams.get('uid');

      if (!blockParam || !uid) {
        return createCORSResponse({ error: 'block and uid parameters are required' }, 400);
      }

      const blockNum = parseInt(blockParam);
      try {
        const noGameState = await this.readTimelineNoGamePublicState(blockNum);
        if (noGameState?.status === 'completed') {
          return createCORSResponse({
            blockNum, noGame: true, reason: 'timeline_unverified', groupId: null, phase: null,
            noGameReason: 'timeline_unverified',
            noGameCleanup: this.publicTimelineNoGameCleanup(noGameState.cleanup),
          });
        }
        if (noGameState?.status === 'pending') {
          return createCORSResponse({
            blockNum, noGame: false, reason: 'timeline_no_game_finalizing',
            groupId: null, phase: null,
          }, 503);
        }
      } catch (error) {
        return createCORSResponse({
          blockNum, noGame: false, reason: 'timeline_no_game_cleanup_pending',
          groupId: null, phase: null, error: this.observationErrorText(error),
        }, 503);
      }
      const db = this.env.BITCOINU_DATA;
      if (!db) {
        return createCORSResponse({ error: 'BITCOINU_DATA binding not found' }, 500);
      }

      // G2是正（2026-07-18）: 旧実装は全グループ行（2100人規模で525行）をD1から読み
      // 全メンバーJSONをパースして線形探索していた＝単一DOへのファンイン×全行走査。
      // グループ分け時に公開済みのroster索引（R2: uid→groupId）でグループを特定し、
      // D1は該当1行だけ読む。索引が無い場合（公開失敗・旧ブロック）は従来走査へフォールバック。
      const roster = await this.getR2Object(`games/block${blockNum}/roster/index.json`);
      if (roster) {
        if (!Object.prototype.hasOwnProperty.call(roster, String(uid))) {
          // C8-01: 索引ミスを即「非当選」と断定する前に、D1との世代ずれを1行で検出する。
          // 全行members走査へは落とさず、B6-01で閉じた無認証の重い経路を再開通させない。
          const countRow = await db.prepare(
            'SELECT COUNT(*) AS n FROM game_groups WHERE block_num = ?'
          ).bind(blockNum).first();
          const d1GroupCount = Number(countRow?.n);
          const rosterGroupCount = new Set(Object.values(roster).map(value => String(value))).size;
          if (!Number.isSafeInteger(d1GroupCount) || d1GroupCount < 0 || d1GroupCount !== rosterGroupCount) {
            return createCORSResponse({ blockNum, groupId: null, reason: 'roster_stale' }, 409);
          }
          return createCORSResponse({ blockNum, groupId: null, reason: 'not_in_roster' });
        }
        const row = await db.prepare(
          'SELECT group_id, lang, status, members FROM game_groups WHERE block_num = ? AND group_id = ?'
        ).bind(blockNum, roster[String(uid)]).first();
        if (row) {
          // cleanup marker の読取失敗・旧データ移行中でも、無効化済み行から
          // groupId / phase を復活させない最後の防壁。
          if (row.status === TIMELINE_NO_GAME_INVALIDATED_STATUS) {
            return createCORSResponse({
              blockNum, noGame: true, reason: 'timeline_unverified', groupId: null, phase: null,
              noGameReason: 'timeline_unverified',
            });
          }
          let members;
          try {
            members = JSON.parse(row.members);
          } catch {
            return createCORSResponse({ blockNum, groupId: null, reason: 'roster_stale' }, 409);
          }
          if (!Array.isArray(members) || !members.some(member => String(member?.uid) === String(uid))) {
            return createCORSResponse({ blockNum, groupId: null, reason: 'roster_stale' }, 409);
          }
          const phaseData = await this.storage.get(`phase_block${blockNum}`);
          return createCORSResponse({
            blockNum,
            groupId: row.group_id,
            phase: phaseData || row.status,
            lang: row.lang
          });
        }
        // C8-02: 索引ヒット先のD1行欠落も不整合。全行走査へは落とさない。
        return createCORSResponse({ blockNum, groupId: null, reason: 'roster_stale' }, 409);
      }

      const { results } = await db.prepare(
        'SELECT group_id, lang, members, status FROM game_groups WHERE block_num = ?'
      ).bind(blockNum).all();

      for (const row of results || []) {
        if (row.status === TIMELINE_NO_GAME_INVALIDATED_STATUS) continue;
        try {
          const members = JSON.parse(row.members);
          if (members.some(m => String(m.uid) === String(uid))) {
            const phaseData = await this.storage.get(`phase_block${blockNum}`);
            return createCORSResponse({
              blockNum,
              groupId: row.group_id,
              phase: phaseData || row.status,
              lang: row.lang
            });
          }
        } catch { /* skip malformed members */ }
      }

      return createCORSResponse({ blockNum, groupId: null, reason: 'not_ready' }, 503);
    }

    // ブロックのゲーム結果サマリー
    if (path === '/block-game-summary' && request.method === 'GET') {
      const blockParam = url.searchParams.get('block');

      if (!blockParam) {
        return createCORSResponse({ error: 'block parameter is required' }, 400);
      }

      const blockNum = parseInt(blockParam);
      const full = url.searchParams.get('full') === '1';
      if (full && !this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      // summary.json 本文は公開R2にもある。既定応答は存在・サイズだけをHEADで返し、
      // DO経由の丸読み＋D1全行fallbackは認証済みfull要求へ限定する。
      if (!full) {
        const head = await this.inspectR2ArtifactHead(`games/block${blockNum}/summary.json`);
        return createCORSResponse({
          blockNum,
          full: false,
          summaryMeta: {
            state: head.state,
            present: head.state === 'succeeded' ? head.exists : null,
            bytes: head.state === 'succeeded' ? head.size : null,
            ...(head.state === 'failed' ? { error: head.error || 'R2 HEAD unavailable' } : {}),
            ...(head.state === 'not_attempted' ? { reason: head.reason || 'head_unavailable' } : {}),
          },
        });
      }

      const noGameState = await this.readTimelineNoGamePublicState(blockNum);
      if (noGameState?.status === 'pending') {
        return createCORSResponse({
          blockNum, full: true, noGame: false, groups: [],
          reason: 'timeline_no_game_finalizing',
        }, 503);
      }

      // R2キャッシュを優先的に参照（D1クエリを回避）
      const cached = await this.getR2Object(`games/block${blockNum}/summary.json`);
      if (cached) {
        // R2キャッシュのclaimed情報は古い可能性があるため、D1から最新のclaimed状態をマージ
        try {
          const db = this.env.BITCOINU_DATA;
          if (db) {
            const { results: claimRows } = await db.prepare(
              'SELECT group_id, userId, role, deposit_id, claimed FROM game_results WHERE block_num = ? AND claimed IS NOT NULL AND claimed != 0 AND claimed != \'0\''
            ).bind(blockNum).all();
            if (claimRows && claimRows.length > 0) {
              // claimedデータをルックアップマップに変換
              const claimMap = {};
              for (const row of claimRows) {
                if (row.role === 'depositor') {
                  claimMap[`dep_${row.group_id}_${row.deposit_id}`] = row.claimed;
                } else {
                  claimMap[`player_${row.group_id}_${row.userId}`] = row.claimed;
                }
              }
              // キャッシュのメンバーとデポジッター結果にclaimed情報をマージ
              for (const group of (cached.groups || [])) {
                for (const member of (group.members || [])) {
                  const key = `player_${group.group_id}_${member.userId}`;
                  if (claimMap[key]) {
                    try { member.claimed = JSON.parse(claimMap[key]); } catch { member.claimed = claimMap[key]; }
                  }
                }
                for (const dep of (group.depositor_results || [])) {
                  const key = `dep_${group.group_id}_${dep.depositId}`;
                  if (claimMap[key]) {
                    try { dep.claimed = JSON.parse(claimMap[key]); } catch { dep.claimed = claimMap[key]; }
                  }
                }
              }
            }
          }
        } catch (err) {
          console.error(`Error merging claimed data from D1 for block ${blockNum}:`, err);
        }
        return createCORSResponse(cached);
      }

      // R2キャッシュが無い場合はD1フォールバック（旧ブロック or キャッシュ未作成）
      const db = this.env.BITCOINU_DATA;
      if (!db) {
        return createCORSResponse({ error: 'BITCOINU_DATA binding not found' }, 500);
      }

      // グループ一覧取得（resultにJSON要約を含む）
      const { results: groupRows } = await db.prepare(
        `SELECT group_id, lang, members, status, result, completed_at FROM game_groups
         WHERE block_num = ? AND status != '${TIMELINE_NO_GAME_INVALIDATED_STATUS}'`
      ).bind(blockNum).all();

      // 全結果取得（簡素化されたスキーマ: 報酬・クレーム情報のみ）
      const { results: resultRows } = await db.prepare(
        'SELECT group_id, userId, role, deposit_id, address, btcu_reward, deposit_to, claimed FROM game_results WHERE block_num = ?'
      ).bind(blockNum).all();

      // グループごとに結果をまとめる
      const resultsByGroup = {};
      for (const r of resultRows || []) {
        if (!resultsByGroup[r.group_id]) resultsByGroup[r.group_id] = [];
        resultsByGroup[r.group_id].push(r);
      }

      const groups = (groupRows || []).map(g => {
        const groupMembers = JSON.parse(g.members || '[]');
        const results = resultsByGroup[g.group_id] || [];
        const playerResults = results.filter(r => r.role === 'player' || !r.role);
        const hasResults = playerResults.length > 0;

        // game_groups.resultから詳細データを取得
        let resultDetail = null;
        const memberDetailMap = {};
        try {
          if (g.result) {
            resultDetail = JSON.parse(g.result);
            for (const mr of (resultDetail.memberResults || [])) {
              memberDetailMap[mr.uid] = mr;
            }
          }
        } catch { /* ignore */ }

        // メンバー情報をマージ（プロフィール + 詳細データ + 報酬データ）
        let members;
        if (hasResults) {
          members = playerResults.map(r => {
            const info = groupMembers.find(m => m.uid === r.userId);
            const detail = memberDetailMap[r.userId];
            return {
              ...r,
              img: info?.img || null,
              name: info?.name || null,
              lang: info?.lang || null,
              verified: info?.verified || false,
              depIds: info?.depIds || null,
              // game_groups.resultからの詳細データ
              deposit_points: detail?.depositPoints ?? null,
              bonus_points: detail?.bonusPoints ?? null,
              total_points: detail?.totalPoints ?? null,
              is_disqualified: detail?.isDisqualified ? 1 : 0,
              disqualify_reason: detail?.disqualifyReason || null
            };
          });
        } else {
          members = groupMembers.map(m => {
            const depositWei = parseDepositWei(m.depIds);
            const depPts = calculateDepositPoints(depositWei);
            return {
              userId: m.uid,
              address: m.addr || null,
              img: m.img || null,
              name: m.name || null,
              lang: m.lang || null,
              verified: m.verified || false,
              depIds: m.depIds || null,
              deposit_points: depPts,
              bonus_points: null,
              total_points: null,
              is_disqualified: 0,
              disqualify_reason: null,
              btcu_reward: null,
              claimed: 0
            };
          });
        }

        const totalPoints = hasResults ? members.reduce((sum, m) => sum + (m.total_points || 0), 0) : null;
        return {
          group_id: g.group_id,
          lang: g.lang,
          member_count: groupMembers.length,
          status: g.status,
          total_points: totalPoints,
          members
        };
      });

      const blockReward = getBlockRewardWei(blockNum).toString();

      // full_btcu_reward を計算（50/50スプリット前の元報酬）
      // game_groups.resultからtotalPointsを取得し、blockRewardから再計算
      const allTotalPoints = groups.reduce((sum, g) =>
        sum + (g.members || []).reduce((s, m) => s + (m.total_points || 0), 0), 0);
      if (allTotalPoints > 0) {
        const blockRewardBigInt = BigInt(blockReward);
        for (const group of groups) {
          for (const member of group.members) {
            if (member.total_points && !member.is_disqualified) {
              const fullReward = blockRewardBigInt * BigInt(member.total_points) / BigInt(allTotalPoints);
              member.full_btcu_reward = fullReward.toString();
              const playerBtcu = BigInt(member.btcu_reward || '0');
              if (playerBtcu < fullReward) {
                const playerShare = fullReward / 2n;
                member.player_share = playerShare.toString();
                member.depositor_share = (fullReward - playerShare).toString();
              }
            }
          }
        }
      }

      // depositor_results をグループに追加（deposit_toでプレイヤー判定可能）
      const depositorRows = (resultRows || []).filter(r => r.role === 'depositor');
      for (const group of groups) {
        const groupDepRows = depositorRows.filter(d => d.group_id === group.group_id);
        if (groupDepRows.length > 0) {
          const groupMembersInfo = JSON.parse(
            (groupRows || []).find(g => g.group_id === group.group_id)?.members || '[]'
          );
          group.depositor_results = groupDepRows.map(d => {
            const depInfo = groupMembersInfo.find(m => m.uid === d.userId);
            return {
              depositorUid: d.userId,
              playerUid: d.deposit_to || null,
              depositId: d.deposit_id,
              depositerAddress: d.address || null,
              btcuReward: d.btcu_reward,
              isPlayerSelf: d.userId === d.deposit_to,
              depositorName: depInfo?.name || null,
              depositorImg: depInfo?.img || null,
              depositorVerified: depInfo?.verified || false
            };
          });
        }
      }

      // 主要言語はD1に無いため、グループ分け進行データ（DO storage・durable）から復元（無ければ[]）
      const progress = await this.storage.get(`grouping_block${blockNum}_progress`);
      const responseData = { blockNum, majorLangs: progress?.majorLangs || [], groups, blockReward };

      // D1フォールバック時にR2キャッシュを作成（次回以降はR2から配信）。
      // 書き込み競合対策（2026-07-31）: ここは「R2 に無かった」ときだけ走る**作成**なので、
      // put-if-absent にする。これは GET 後に別リクエストが作った物を上書きしないだけで、
      // 欠損時に再構築内容が正しいことを検証する CAS ではない。欠損窓を作らない安全性は
      // production の R2 delete が games/ を対象にしないことと、grouping が下で summary を
      // 無条件作成して窓を閉じることに依存する（R15-26固定検査あり）。
      if (groups.length > 0) {
        try {
          const res = await this.env.R2_BUCKET.put(
            `games/block${blockNum}/summary.json`,
            // P-2026-0842（台帳 C-3）: 実行時刻を入れない（`mergeBlockSummary` の注記参照）
            JSON.stringify(responseData),
            { onlyIf: { etagDoesNotMatch: '*' }, httpMetadata: { contentType: 'application/json' } }
          );
          if (res === null) console.log(`R2 cache for block ${blockNum} was created concurrently — keeping the existing object`);
        } catch (err) {
          console.error(`Error creating R2 cache for block ${blockNum}:`, err);
        }
      }

      return createCORSResponse(responseData);
    }

    // 後継の起動はこの認証済みの人手入口だけ（pin不一致の既存復旧を除く）。
    if (path === '/zkp-successor' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) return createCORSResponse({ error: 'Unauthorized' }, 401);
      let body;
      try { body = await request.json(); }
      catch { return createCORSResponse({ error: 'invalid JSON' }, 400); }
      if (!Number.isSafeInteger(body?.block_num) || body.block_num < 0
          || typeof body.adopt_required !== 'boolean'
          || body.successor_of != null && !/^[0-9a-f]{64}$/.test(body.successor_of))
        return createCORSResponse({ error: 'block_num/adopt_required is invalid' }, 400);
      try {
        return createCORSResponse(await this.requestZkpSuccessor(body.block_num, body.adopt_required,
          body.successor_of ?? null));
      } catch (error) {
        return createCORSResponse({ error: error.message }, error.status || 500);
      }
    }

    // 手動結果計算（管理者用）
    if (path === '/calculate-results' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      const body = await request.json();
      const { block_num } = body;

      if (!isNumericBlockNum(block_num)) {
        return createCORSResponse({ error: 'block_num must be a finite number' }, 400);
      }

      try {
        // A1: restart=true で進捗を破棄して最初から再計算。park状態はunpark指定か再実行で解除。
        // レビューM3: 完了済み(done)ブロックへの手動呼び出しは旧モノリスどおり「再集計」＝
        // restart扱いにする（進行中への呼び出しはresume＝進捗を壊さない）。
        const prog = await this.storage.get(this.calcProgressKey(block_num));
        const restart = body.restart !== undefined ? !!body.restart : this.shouldAutoRestartCalc(prog);
        const result = await this.calculateAndStoreResults(block_num, {
          restart,
          unpark: body.unpark !== false, // 手動呼び出しはデフォルトでpark解除（明示的な復旧操作のため）
          // proofRequired=false のときだけ、このブロックを証明なし提出へ進める運用バイパス。
          // trueへ切り替わっていればzkProof/adminCommitの二重読取が無視してfail-closedを維持する。
          zkpFallback: body.zkp_fallback === true || body.zkp_abandon === true,
          zkpAbandon: body.zkp_abandon === true,
          zkpFallbackReason: typeof body.zkp_fallback_reason === 'string'
            ? body.zkp_fallback_reason.slice(0, 500) : null,
        });
        return createCORSResponse(result);
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // K-S5-002: ガス価格上限の確認・変更・解除（test.js のメニューから使う）。
    // env を書き換えて再デプロイしなくても、運用中に即時変更できることが要件。
    //   GET  /max-gas-price                       → 実効値＋現在のガス価格＋待機状況
    //   POST /max-gas-price {"gwei": 12}          → 上書き値を設定
    //   POST /max-gas-price {"clear": true}       → 上書きを解除（env / 既定値へ戻す）
    if (path === '/max-gas-price' && (request.method === 'GET' || request.method === 'POST')) {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }
      try {
        if (request.method === 'POST') {
          const body = await request.json().catch(() => ({}));
          const limit = body.clear === true
            ? await this.clearMaxGasPriceOverride()
            : await this.setMaxGasPriceGwei(body.gwei);
          return createCORSResponse({ ok: true, limit, envValue: this.env.MAX_GAS_PRICE_GWEI ?? null, defaultGwei: DEFAULT_MAX_GAS_PRICE_GWEI });
        }
        const limit = await this.getMaxGasPriceGwei();
        let current = null;
        try {
          const publicClient = this.createReadOnlyClient();
          if (publicClient) current = await this.readGasPriceGwei(publicClient);
        } catch (e) { current = { error: e.shortMessage || e.message }; }
        // 待機中のブロック（あれば）
        const waits = [];
        const list = await this.storage.list({ prefix: 'gas_wait_block' });
        for (const [, v] of list) waits.push(v);
        return createCORSResponse({
          ok: true, limit, current, waiting: waits,
          envValue: this.env.MAX_GAS_PRICE_GWEI ?? null, defaultGwei: DEFAULT_MAX_GAS_PRICE_GWEI,
        });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 400);
      }
    }

    // Merkle root の手動再提出（管理者用）: R2 公開済みツリーの root をオンチェーン提出
    if (path === '/submit-merkle-root' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      const body = await request.json();
      const { block_num } = body;
      // K-S5-002: force=true はガス価格ゲートを飛ばして即送信する（運用の手動介入用）
      const force = body.force === true;

      if (!isNumericBlockNum(block_num)) {
        return createCORSResponse({ error: 'block_num must be a finite number' }, 400);
      }

      try {
        // 検証manifest再公開用: このブロックのグループID一覧（無ければ空＝autoDistribute等）
        const fetchGroupIds = async () => {
          try {
            const db = this.env.BITCOINU_DATA;
            if (!db) return [];
            const { results: rows } = await db.prepare(
              `SELECT group_id FROM game_groups WHERE block_num = ? AND status != '${TIMELINE_NO_GAME_INVALIDATED_STATUS}'`
            ).bind(block_num).all();
            return (rows || []).map(r => r.group_id);
          } catch (e) {
            console.warn(`[verification] failed to fetch group ids for block ${block_num}: ${e.message}`);
            return [];
          }
        };

        // 1. R2 に公開済みツリーがあれば、その root をそのまま提出
        const obj = await this.env.R2_BUCKET.get(`merkle/block_${block_num}.json`);
        if (obj) {
          const tree = JSON.parse(await obj.text());
          // B10-06: 旧版が公開した空ツリーを手動経路から提出する場合にも、現在の
          // summary に正ポイントが無いことを再確認する。配分がある空ツリーはここで止める。
          if (Number(tree.leafCount ?? 0) === 0) {
            let summary;
            try {
              summary = await this.getR2Object(`games/block${block_num}/summary.json`);
              await this.assertFinalizedSummary(block_num, summary, '[submit-merkle-root]');
            } catch (e) {
              return createCORSResponse({
                error: e.message,
                blockNum: block_num,
                reason: 'finalized_summary_required',
              }, 409);
            }
            try {
              this.assertClaimEntriesForPositivePoints(block_num, summary, 0, {
                where: '[submit-merkle-root]',
              });
            } catch (e) {
              return createCORSResponse({
                error: e.message,
                blockNum: block_num,
                reason: 'positive_points_without_claim_entries',
              }, 409);
            }
          }
          // 🔴 R-1 / C-1 レッグ(d) の取りこぼし（2026-08-08・ラウンド20 回帰-1）:
          //    root を出す4経路のうち**この経路だけ**が
          //      ・`submitMerkleRootOnChain` を `publishVerificationManifest` より**先**に呼び
          //        （S3-010「root 提出は常に最後」に真正面から反する）
          //      ・戻り値 `verification.ok` を**一度も見ずに** 200 を返し
          //      ・`recordVerificationPublishFailure` も呼ばない
          //    状態だった。しかも `finalizeNoGameBlock` / `autoDistribute` が案内する復旧手順は
          //    `merkle/block_{N}.json` が既に公開済みの状態で叩かれる＝**100% この経路に落ちる**ので、
          //    ゲーム無し／自動配布側に入れた fail-closed が「再実行1回」で完全に解除されていた。
          //    → 順序を tree(公開済み) → proofs → manifest → root に揃え、
          //      manifest が公開・アンカーできないなら root を出さずに 409 で止める。
          //
          //    proofs ゲート: manifest 段で止まったブロックは proof が1枚も無い。
          //    root 提出は検証期間・請求期間を開始させるので、ここで素通しすると
          //    **proof ゼロのまま請求クロックが走る**（`block-verifier/src/stages/results.js` が
          //    「root 提出済み ⟹ proof 準備済み」を明文で引用して stopReason='fail' にする不変量）。
          const proofs = await this.ensureProofsPublished(block_num, tree.leafCount ?? 0);
          if (!proofs.ok) {
            return createCORSResponse({
              error: `[proofs] block ${block_num}: written ${proofs.written} != leafCount ${proofs.leafCount} `
                + '— merkle root submission SKIPPED (root 提出は proof 準備完了の後). Fix claim-worker (API_SECRET / deploy) and retry.',
              blockNum: block_num,
              reason: 'proofs_incomplete',
              proofs,
            }, 409);
          }
          // adminCommit（root提出）と同じタイミングで検証manifestも再公開・再アンカー
          // （初回計算時にmerkle未公開だった場合のmanifest陳腐化を防ぐ。同一ハッシュなら再登録スキップ）
          const verification = await this.publishVerificationManifest(block_num, await fetchGroupIds());
          if (!verification?.ok) {
            return this.manualVerificationFailureResponse(block_num, verification, 'submit_merkle_root:r2_tree');
          }
          await this.clearVerificationPublishFailure(block_num, { preservePendingPeriod: true });
          await this.clearVerificationAdminFreeze(block_num);
          const merkle = await this.finalizePublishedRootWithPipeline(block_num, {
            merkle: { ok: true, root: tree.root, leafCount: tree.leafCount ?? 0 },
            verification,
            force,
          });
          return createCORSResponse({
            blockNum: block_num, source: 'r2_tree', root: tree.root, leafCount: tree.leafCount,
            proofs, submit: merkle?.submit || null, merkle, verification,
          });
        }

        // 2. ツリー未公開（自動提出が走らなかった等）→ 公開データ summary.json から再構築 → R2 公開 → 提出
        const sumObj = await this.env.R2_BUCKET.get(`games/block${block_num}/summary.json`);
        if (!sumObj) {
          return createCORSResponse({
            error: `Neither merkle/block_${block_num}.json nor games/block${block_num}/summary.json found in R2. Run /calculate-results first.`
          }, 404);
        }
        // P-2026-0822: ここは Merkle ツリーの**入力**を公開データから読み直す経路。
        // 非正準な数値表記（`100.0` / `1e2`）が混ざった summary から作った葉は、
        // Rust の採点コアが同じ summary を読めない＝再現できない root になる。
        // 正準検査を通してから使う（throw → 上の catch が 500 で返す）。
        const summary = parseCanonicalJson(await sumObj.text(), `games/block${block_num}/summary.json`);
        // 🔴 P-2026-0839（2026-08-08・ラウンド19 判断不要-7）: **自動経路と同じガードを通す。**
        //    `calcMerkleUnit` が「レビューH1（多層防御）」として要求している
        //    (a) 全グループ `status === 'completed' | 'auto_distributed'`
        //    (b) D1 グループ集合と uid 集合の被覆
        //    が、同じ木構築をするこの手動経路にだけ**1つも無かった**。
        //    グループ分け直後の summary をここへ通すと `leafCount=0` の空ツリーが
        //    標識ルートとして提出され、ブロック報酬が誰にも配られないまま確定する。
        //    以後どちらか片方だけに入る状態にしないため、検査は `assertFinalizedSummary` に一本化する。
        try {
          await this.assertFinalizedSummary(block_num, summary, '[submit-merkle-root]');
        } catch (e) {
          // 「summary が無い」（404）と「summary はあるが結果確定版ではない」を区別する
          return createCORSResponse({
            error: `${e.message} — games/block${block_num}/summary.json exists but is not a finalized results summary. `
              + `Run POST /calculate-results {"block_num":${block_num}} and wait for it to reach stage=done before retrying.`,
            blockNum: block_num,
            reason: 'summary_not_finalized',
          }, 409);
        }
        // S3-010: root 提出は常に最後（tree publish → proofs → manifest → 提出）
        const pub = await this.publishMerkleTree(block_num, summary);
        if (!pub?.ok) {
          return createCORSResponse({
            error: `[merkle] block ${block_num}: ${pub?.error || pub?.reason || 'tree publish failed'}`,
            blockNum: block_num,
            reason: pub?.reason || 'merkle_publish_failed',
          }, 409);
        }
        // 🔴 R-1（2026-08-08・ラウンド20 回帰-1）: 経路1と同じ proofs ゲート。
        //    ここも旧実装は proof を1枚も作らずに root を出していた。
        const proofs = await this.ensureProofsPublished(block_num, pub.leafCount ?? 0);
        if (!proofs.ok) {
          return createCORSResponse({
            error: `[proofs] block ${block_num}: written ${proofs.written} != leafCount ${proofs.leafCount} `
              + '— merkle root submission SKIPPED (root 提出は proof 準備完了の後). Fix claim-worker (API_SECRET / deploy) and retry.',
            blockNum: block_num,
            reason: 'proofs_incomplete',
            proofs,
          }, 409);
        }
        const verification = await this.publishVerificationManifest(block_num, await fetchGroupIds());
        // 🔴 R-1（2026-08-08・ラウンド20 回帰-1）: 順序は正しかったが `verification.ok` を捨てていた。
        //    ゲーム無し／自動配布経路と同じ判断（manifest が出ていないなら root を出さない）に揃える。
        if (!verification?.ok) {
          return this.manualVerificationFailureResponse(block_num, verification, 'submit_merkle_root:rebuilt');
        }
        await this.clearVerificationPublishFailure(block_num, { preservePendingPeriod: true });
        await this.clearVerificationAdminFreeze(block_num);
        const result = await this.finalizePublishedRootWithPipeline(block_num, { merkle: pub, verification, force });
        return createCORSResponse({ blockNum: block_num, source: 'rebuilt_from_summary', ...result, proofs, verification });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // 検証manifestの手動再公開＋オンチェーン再アンカー（発見2: アンカー失敗時の復旧用・管理者用）
    // publishVerificationManifest は冪等（同一ハッシュなら再登録スキップ）なので何度呼んでも安全。
    if (path === '/anchor-result' && (request.method === 'POST' || request.method === 'GET')) {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }
      let blockNum;
      if (request.method === 'GET') {
        const rawBlock = url.searchParams.get('block');
        blockNum = rawBlock !== null && rawBlock.trim() !== '' ? Number(rawBlock) : NaN;
      } else {
        const body = await request.json().catch(() => ({}));
        blockNum = body.block_num ?? body.block;
      }
      if (!isNumericBlockNum(blockNum)) {
        return createCORSResponse({ error: 'block_num must be a finite number' }, 400);
      }
      try {
        const db = this.env.BITCOINU_DATA;
        let groupIds = [];
        if (db) {
          const { results: rows } = await db.prepare(
            `SELECT group_id FROM game_groups WHERE block_num = ? AND status != '${TIMELINE_NO_GAME_INVALIDATED_STATUS}'`
          ).bind(blockNum).all();
          groupIds = (rows || []).map(r => r.group_id);
        }

        // R12-48: manifest を作り直す前に、必須の ChatGameDO 公開アーカイブ欠落を復旧する。
        // 全件へ completed を再送すると、既に cleanup 済みの正常 DO まで 400 になり得るため、
        // R2 の欠落を head で実確認したグループだけへ `rearchive:true` を送る。
        const archivePresence = await this.batchChatDoCalls(groupIds, async (groupId) => {
          const key = `games/block${blockNum}/group${groupId}.json`;
          const object = typeof this.env.R2_BUCKET.head === 'function'
            ? await this.env.R2_BUCKET.head(key)
            : await this.env.R2_BUCKET.get(key); // テスト用の最小R2 stubとの互換
          return object ? null : { groupId, key };
        });
        const missingArchives = archivePresence.filter(Boolean);
        const rearchive = {
          checked: groupIds.length,
          requested: missingArchives.length,
          archived: 0,
        };
        if (missingArchives.length > 0) {
          if (!this.env.CHAT_GAME_DO) throw new Error('CHAT_GAME_DO binding not found');
          const outcomes = await this.batchChatDoCalls(missingArchives, async ({ groupId, key }) => {
            try {
              const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${groupId}`);
              const chatDO = this.env.CHAT_GAME_DO.get(doId);
              const response = await chatDO.fetch(this.chatDoRequest('/set-phase', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ phase: 'completed', rearchive: true }),
              }));
              const body = await response.json().catch(() => ({}));
              if (response.ok && body?.archive?.ok === true) return { ok: true, groupId, key };
              return {
                ok: false,
                groupId,
                key,
                error: body?.archive?.error || body?.error || `HTTP ${response.status}`,
              };
            } catch (error) {
              return { ok: false, groupId, key, error: String(error?.message || error) };
            }
          });
          const failures = outcomes.filter((outcome) => !outcome.ok);
          if (failures.length > 0) {
            throw new Error(
              `[anchor] failed to re-archive ${failures.length} ChatGameDO result page(s): `
              + failures.map((failure) => `${failure.key}: ${failure.error}`).join(', ')
            );
          }
          rearchive.archived = outcomes.length;
        }
        const verification = await this.publishVerificationManifest(blockNum, groupIds);
        const failedMarker = await this.storage.get(`verification_anchor_failed_block${blockNum}`);
        // 🔴 R-1 追補（2026-08-08・ラウンド20 回帰-1）: `verification_publish_failed_block{N}` は
        //    `collectLifecycleBlockers` に出る park 相当のマーカーなのに、
        //    そのマーカー自身が案内する復旧手順（`POST /anchor-result` → `POST /submit-merkle-root`）は
        //    **どちらも触っていなかった**（clear の呼び出しは集計パイプラインと
        //    ゲーム無し／自動配布経路の3箇所だけ）。R2/RPC を直して再アンカーに成功しても
        //    blocker が永久に残る＝「復旧できない復旧手順」になっていた。
        if (!verification?.ok) {
          return this.manualVerificationFailureResponse(blockNum, verification, 'anchor_result');
        }
        await this.clearVerificationPublishFailure(blockNum, { preservePendingPeriod: true });
        await this.clearVerificationAdminFreeze(blockNum);
        return createCORSResponse({ blockNum, rearchive, verification, previouslyFailed: !!failedMarker });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // 検証アンカー失敗ブロックの一覧（発見2: 運営・監視用。未アンカー＝要再アンカー）
    if (path === '/anchor-failures' && request.method === 'GET') {
      try {
        const list = await this.storage.list({ prefix: 'verification_anchor_failed_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
        const failures = [];
        for (const [, v] of list) failures.push(v);
        failures.sort((a, b) => (a.blockNum ?? 0) - (b.blockNum ?? 0));
        return createCORSResponse({ count: failures.length, failures });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // 集計パイプラインの健全性可視化（監視用）。
    //   GET /calc-status?block=N → ブロックNの progress 概要（stage/parked/failures/lastError 等）
    //   deep成果物が上限を超える場合は artifact_cursor=N で次ページを読む。
    //   GET /calc-status         → 進捗記録を走査した進行中＋park中の集計一覧＋アンカー失敗
    // 既定は HEAD のみの浅い観測。R2 GET と chain eth_call は deep=1 / chain=1 へ
    // 明示オプトインし、その場合だけ API secret を要求する。
    if (path === '/calc-status' && request.method === 'GET') {
      const slim = (p, deep = false) => this.slimCalcProgress(p, { deep });
      try {
        const blockParam = url.searchParams.get('block');
        const deep = url.searchParams.get('deep') === '1';
        const chain = url.searchParams.get('chain') === '1';
        const artifactCursorParam = url.searchParams.get('artifact_cursor');
        const artifactCursor = artifactCursorParam === null || artifactCursorParam === ''
          ? 0 : Number(artifactCursorParam);
        if (!Number.isSafeInteger(artifactCursor) || artifactCursor < 0) {
          return createCORSResponse({ error: 'artifact_cursor must be a non-negative safe integer' }, 400);
        }
        if ((deep || chain) && !this.verifyApiSecret(request)) {
          return createCORSResponse({ error: 'Unauthorized' }, 401);
        }
        if (blockParam !== null && blockParam !== '') {
          const blockNum = Number(blockParam);
          if (Number.isNaN(blockNum)) {
            return createCORSResponse({ error: 'block must be a number' }, 400);
          }
          let prog = await this.storage.get(this.calcProgressKey(blockNum));
          // 完了履歴も読取時に正規化する。通常の計算再開経路を通らない過去ブロックでは、
          // cleanup済みでも旧poll値（taskState=RUNNING）が永続化されたままになり得る。
          // normalizeCompletedCalcProgress は root提出済み＋proof検証済みの場合だけ変更する。
          prog = await this.normalizeCompletedCalcProgress(blockNum, prog);
          const merkleStatus = await this.storage.get(`merkle_status_${blockNum}`);
          const anchorFailed = await this.storage.get(`verification_anchor_failed_block${blockNum}`);
          const restartRejected = await this.storage.get(this.calcRestartRejectedKey(blockNum));
          const fallbackRequested = await this.storage.get(this.calcFallbackRequestKey(blockNum));
          const fallbackRejected = await this.storage.get(this.calcFallbackRejectedKey(blockNum));
          const rosterReadFailed = await this.storage.get(`roster_submission_read_failed_block${blockNum}`);
          const adminTxPending = await this.collectAdminTxPending(blockNum);
          const zkpIssue = await this.storage.get(`zkp_proof_issue_block${blockNum}`);
          const postCommitZkp = await this.storage.get(this.postCommitZkpKey(blockNum));
          const autoProgress = await this.storage.get(`auto_distribute_block${blockNum}`);
          const groupingProgress = await this.storage.get(`grouping_block${blockNum}_progress`);
          const storedRandaoAnchor = await this.storage.get(`randao_anchor_block${blockNum}`);
          const gasAutoForce = await this.storage.get(`gas_auto_force_block${blockNum}`);
          const [phaseShards, doneHealth] = await Promise.all([
            this.inspectPhaseShardStatus(blockNum),
            this.inspectDoneBlockArtifacts(blockNum, {
              progress: prog, autoProgress, deep, chain, artifactCursor,
            }),
          ]);
          return createCORSResponse({
            blockNum,
            progress: slim(prog, deep),
            found: !!prog,
            merkle: merkleStatus
              ? { root: merkleStatus.root ?? null, leafCount: merkleStatus.leafCount ?? null,
                  submitted: !!merkleStatus.submit?.submitted, error: merkleStatus.error ?? null }
              : null,
            adminTxPending,
            restartRejected: restartRejected || null,
            // 運営が入力した理由を含むため、保存中・却下の詳細は認証済みdeepだけへ出す。
            fallbackPending: !!fallbackRequested,
            fallbackRejectedPresent: !!fallbackRejected,
            ...(deep ? {
              fallbackRequested: fallbackRequested || null,
              fallbackRejected: fallbackRejected || null,
            } : {}),
            blockers: rosterReadFailed ? [{
              kind: 'roster_submission_read_failed', blockNum,
              error: rosterReadFailed.error ?? null, at: rosterReadFailed.at ?? null,
              autoResuming: true,
              recover: '名簿履歴・currentGrace・チェーン時刻の読取を復旧すると集計が再試行する',
            }] : [],
            anchorFailed: anchorFailed ? { manifestHash: anchorFailed.manifestHash ?? null, at: anchorFailed.at ?? null } : null,
            zkpIssue: this.calcStatusZkpRecord(zkpIssue, { deep }) || null,
            postCommitZkp: this.calcStatusZkpRecord(postCommitZkp, { deep }) || null,
            autoDistribute: autoProgress || null,
            autoProofWait: groupingProgress?.waitReason === 'auto_distribution_proof_pending'
              ? groupingProgress.waitDetail : null,
            evidenceWindowWait: prog?.zkProof?.evidenceWindowWait || null,
            autoDistributeRecover: this.autoDistributeRecoveryHint(blockNum, groupingProgress, autoProgress),
            archiveRpcRequired: [prog?.lastError, autoProgress?.lastError, groupingProgress?.error]
              .some(error => /archive_rpc_required/.test(String(error || ''))),
            randaoAnchor: groupingProgress?.randaoAnchor || (storedRandaoAnchor
              ? { required: true, anchored: true, ...storedRandaoAnchor }
              : null),
            phaseShards,
            doneHealth,
            gasAutoForce: gasAutoForce || null,
            configured: this.configuredRuntimeValues(),
          });
        }
        // C-2: 必ず先に保存される calc_block{N}_progress を再開・監視の権威にする。
        // calc_active は旧版との互換用ヒントであり、その書込み失敗で進捗を見失わない。
        const activeMap = await this.storage.list({ prefix: 'calc_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
        const inflight = [];
        const inflightBlocks = new Set();
        const doneCandidates = [];
        for (const [key, progress] of activeMap) {
          if (!/^calc_block\d+_progress$/.test(key) || !progress) continue;
          const bn = progress.blockNum;
          if (bn === undefined || bn === null) continue;
          if (progress.stage === 'done') doneCandidates.push({ blockNum: Number(bn), progress });
          else {
            inflight.push(slim(progress));
            inflightBlocks.add(Number(bn));
          }
        }
        // R20-F1: 自動配布のD1〜manifest段は通常calc_activeより前に進むため、
        // 専用checkpointも同じ監視一覧へ統合する。
        const autoMap = await this.storage.list({ prefix: 'auto_distribute_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
        for (const [, p] of autoMap) {
          if (!p) continue;
          if (p.stage === 'done') {
            if (!doneCandidates.some((item) => item.blockNum === Number(p.blockNum))) {
              doneCandidates.push({ blockNum: Number(p.blockNum), autoProgress: p });
            }
            continue;
          }
          if (inflightBlocks.has(Number(p.blockNum))) continue;
          const grouping = await this.storage.get(`grouping_block${p.blockNum}_progress`);
          inflight.push({
            blockNum: p.blockNum,
            stage: `auto:${p.stage}`,
            failures: grouping?.resumeAttempts || p.failures || 0,
            parked: grouping?.status === 'parked',
            lastError: grouping?.error || p.lastError || null,
            archiveRpcRequired: [grouping?.error, p.lastError]
              .some(error => /archive_rpc_required/.test(String(error || ''))),
            autoDistributed: true,
            recover: this.autoDistributeRecoveryHint(p.blockNum, grouping, p),
          });
        }
        // 進捗が無い／doneの盤の要求も、内容を出さず有無だけ一覧へ載せる。
        const fallbackPresence = new Map();
        for (const [prefix, field] of [
          ['calc_fallback_requested:', 'fallbackPending'],
          ['calc_fallback_rejected:', 'fallbackRejectedPresent'],
        ]) {
          const records = await this.storage.list({ prefix, limit: PUBLIC_STORAGE_LIST_LIMIT });
          for (const [key, value] of records) {
            const blockNum = Number(key.slice(prefix.length));
            if (!value || !Number.isSafeInteger(blockNum) || blockNum < 0) continue;
            const presence = fallbackPresence.get(blockNum)
              || { blockNum, fallbackPending: false, fallbackRejectedPresent: false };
            presence[field] = true;
            fallbackPresence.set(blockNum, presence);
          }
        }
        const fallbackRequests = [...fallbackPresence.values()].sort((a, b) => a.blockNum - b.blockNum);
        for (const item of inflight) Object.assign(item, fallbackPresence.get(Number(item.blockNum))
          || { fallbackPending: false, fallbackRejectedPresent: false });
        inflight.sort((a, b) => (a.blockNum ?? 0) - (b.blockNum ?? 0));
        const anchorList = await this.storage.list({ prefix: 'verification_anchor_failed_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
        const anchorFailures = [];
        for (const [, v] of anchorList) anchorFailures.push({ blockNum: v.blockNum ?? null, manifestHash: v.manifestHash ?? null, at: v.at ?? null });
        anchorFailures.sort((a, b) => (a.blockNum ?? 0) - (b.blockNum ?? 0));
        // S3-012（2026-07-29）: ライフサイクル側の停止も同じ画面に出す。
        // 旧実装は calc（集計）と anchor だけを走査しており、フェーズ遷移や
        // ChatGameDO 初期化が park してゲームが恒久停止しても、仕様上案内されている
        // この監視エンドポイントには**何も出なかった**（Cloudflare のログを常時見ている
        // 前提でないと気づけない）。
        const lifecycle = await this.collectLifecycleBlockers();
        const adminTxPending = await this.collectAdminTxPending();
        const gasAutoForceMap = await this.storage.list({ prefix: 'gas_auto_force_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
        const gasAutoForces = [];
        for (const [, value] of gasAutoForceMap) if (value) gasAutoForces.push(value);
        gasAutoForces.sort((a, b) => Number(a.blockNum ?? 0) - Number(b.blockNum ?? 0));
        // R26: applicant hash 登録block + CONFIRMATION_BLOCKS のtargetがEvidenceへ
        // 保存済みかを監視面へ出す。提案値ではなくblockhash事実キャッシュの状態。
        const groupingMap = await this.storage.list({ prefix: 'grouping_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
        const randaoAnchors = [];
        for (const [key, value] of groupingMap) {
          if (!/^grouping_block\d+_progress$/.test(key) || !value?.randaoAnchor) continue;
          randaoAnchors.push({ blockNum: value.blockNum ?? null, ...value.randaoAnchor });
        }
        randaoAnchors.sort((a, b) => (a.blockNum ?? 0) - (b.blockNum ?? 0));
        doneCandidates.sort((a, b) => b.blockNum - a.blockNum);
        const doneHealth = await Promise.all(doneCandidates.slice(0, MONITOR_DONE_BLOCK_LIMIT).map((item) => (
          this.inspectDoneBlockArtifacts(item.blockNum, {
            progress: item.progress || null,
            autoProgress: item.autoProgress || null,
            deep: false,
            chain: false,
          })
        )));
        return createCORSResponse({
          inflightCount: inflight.length,
          parkedCount: inflight.filter(p => p.parked).length,
          inflight,
          fallbackPending: fallbackRequests.some(item => item.fallbackPending),
          fallbackRejectedPresent: fallbackRequests.some(item => item.fallbackRejectedPresent),
          fallbackRequests,
          anchorFailureCount: anchorFailures.length,
          anchorFailures,
          // ライフサイクル（フェーズ遷移・チャット初期化・グループ分け）の停止
          lifecycleBlockerCount: lifecycle.blockers.length,
          lifecycleBlockers: lifecycle.blockers,
          adminTxPending,
          queueOldestExecuteAt: lifecycle.queueOldestExecuteAt,
          queueLength: lifecycle.queueLength,
          phaseTaskActive: lifecycle.activeTask,
          phaseTaskAlarm: lifecycle.alarm,
          groupingRuntime: lifecycle.groupingRuntime,
          groupingRuntimeOmitted: lifecycle.groupingRuntimeOmitted,
          taskRuntime: lifecycle.taskRuntime,
          calcBootstrapWatchdog: lifecycle.calcBootstrapWatchdog,
          gasAutoForceCount: gasAutoForces.length,
          gasAutoForces,
          doneHealth,
          doneHealthOmitted: Math.max(0, doneCandidates.length - MONITOR_DONE_BLOCK_LIMIT),
          doneHealthFailureCount: doneHealth.filter((item) => item.state === 'failed').length,
          configured: this.configuredRuntimeValues(),
          randaoAnchorCount: randaoAnchors.length,
          randaoAnchorMissingCount: randaoAnchors.filter(a => a.required && !a.anchored).length,
          randaoAnchors,
        });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // root 未提出の自動配布だけを K11 から作り直す。ブロック単位の進捗以外には触れない。
    if (path === '/restart-auto-distribute' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) return createCORSResponse({ error: 'Unauthorized' }, 401);
      const body = await request.json().catch(() => ({}));
      const blockNum = body.block_num;
      if (!Number.isSafeInteger(blockNum) || blockNum < 0) {
        return createCORSResponse({ error: 'block_num must be a non-negative safe integer' }, 400);
      }
      try {
        const lifecycle = await this.readBlockLifecycle(blockNum, { fresh: true });
        if (!lifecycle?.available) return createCORSResponse({ error: 'root state unavailable' }, 503);
        if (lifecycle.rootSubmitted) return createCORSResponse({ error: 'root already submitted' }, 409);
        const selection = await this.getR2Object(`entries/block${blockNum}/game_selection.json`);
        if (!Array.isArray(selection?.players) || ![1, 2].includes(selection.players.length)) {
          return createCORSResponse({ error: 'block is not a one or two player auto-distribution' }, 409);
        }
        await this.readDepositSelectionK11(blockNum);
        if (this._calcDriving) return createCORSResponse({ error: 'calculation already running' }, 409);
        const [calcProgress, groupingProgress, publishFailure, adminFreeze] = await Promise.all([
          this.storage.get(this.calcProgressKey(blockNum)),
          this.storage.get(`grouping_block${blockNum}_progress`),
          this.storage.get(`verification_publish_failed_block${blockNum}`),
          this.storage.get(`verification_admin_freeze_block${blockNum}`),
        ]);
        if (['admin_tx_pending', 'admin_freeze'].includes(calcProgress?.waitReason)
            || ['admin_tx_pending', 'admin_freeze'].includes(groupingProgress?.waitReason)
            || publishFailure?.pending === true || adminFreeze) {
          return createCORSResponse({ error: 'admin transaction is still pending' }, 409);
        }
        const taskQueue = await this.storage.get('phase_task_queue') || [];
        const retainedTasks = taskQueue.filter((task) => !(task.type === 'calc_chunk' && task.blockNum === blockNum));
        if (retainedTasks.length !== taskQueue.length) await this.storage.put('phase_task_queue', retainedTasks);
        await this.autoDistributeCleanupKeys(blockNum);
        await this.calcCleanupKeys(blockNum);
        const result = await this.autoDistribute(blockNum, selection.players);
        if (result?.pending) {
          const progress = {
            ...(groupingProgress || {}), blockNum, status: 'failed', phase: 'auto_distributing',
            resumable: true, resumeAttempts: 0,
          };
          const wait = adminTxWaitOf(result);
          if (wait) {
            await this.markGroupingAdminTxWait(blockNum, progress, wait, {
              phase: 'auto_distributing', stage: result.stage || 'manifest',
            });
          } else {
            progress.error = `auto-distribute pending at ${result.stage || 'unknown'}`;
            await this.storage.put(`grouping_block${blockNum}_progress`, progress);
            await this.enqueueGroupingWatchdog(blockNum, result.retryInMs || GameMasterDO.TIMELINE_RETRY_MS);
          }
        } else {
          const completed = {
            ...(groupingProgress || {}), blockNum, status: 'completed', phase: 'completed',
            completedAt: new Date().toISOString(), error: null, resumable: false,
            autoDistributed: true, totalPlayers: selection.players.length, totalGroups: 0,
          };
          delete completed.parkedAt;
          await this.storage.put(`grouping_block${blockNum}_progress`, completed);
        }
        return createCORSResponse({ blockNum, result, restarted: true });
      } catch (error) {
        if (/archive_rpc_required/.test(String(error.message))) {
          const key = `auto_distribute_block${blockNum}`;
          const progress = await this.storage.get(key);
          if (progress) await this.storage.put(key, {
            ...progress, lastError: error.message, updatedAt: Date.now(),
          });
          await sendAlertAndRecord(this.env, this.storage, {
            kind: 'archive_rpc_required',
            subject: `[COINU][CRITICAL] 過去の EthLock 状態を読めない: block ${blockNum}`,
            body: `reason=archive_rpc_required\nblockNum=${blockNum}\n${error.message}\nGET /calc-status?block=${blockNum}`,
          }).catch((alertError) => console.error('[auto-distribute] archive RPC alert failed:', alertError));
        }
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // Evidence reconcile 手動再実行（冪等）: RPC障害等で結果集計が止まった場合の復旧経路。
    // 集計全体をチェーンの歩き直しから再実行する（D1 の判定・中身は再利用しない。S3C5・D-06）。
    if (path === '/reconcile-evidence' && (request.method === 'POST' || request.method === 'GET')) {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }
      let blockNum;
      if (request.method === 'GET') {
        const rawBlock = url.searchParams.get('block');
        blockNum = rawBlock !== null && rawBlock.trim() !== '' ? Number(rawBlock) : NaN;
      } else {
        const body = await request.json().catch(() => ({}));
        blockNum = body.block_num ?? body.block;
      }
      if (!isNumericBlockNum(blockNum)) {
        return createCORSResponse({ error: 'block_num must be a finite number' }, 400);
      }
      try {
        // A1: reconcileのやり直し＝集計全体を最初から再駆動（calcCleanupKeys で歩行カーソルも消える）。
        // 🔴 P-2026-0813／S3C5（D-06）: ingest は**常にチェーンのバイト列で上書きしてその場で判定し直す**。
        //   D1 が汚染されていても、cleanup 後に中身（data）が空いていても、再駆動は必ず
        //   チェーンの歩き直しから始まり、チェーンの内容へ収束する（それが再駆動の目的）。
        const result = await this.calculateAndStoreResults(blockNum, { restart: true, unpark: true });
        const reconciled = await this.storage.get(`evidence_reconciled_block${blockNum}`);
        return createCORSResponse({
          blockNum,
          result,
          evidence: reconciled || null,
          restartRequested: true,
          restartApplied: result?.restartApplied !== false,
        });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // Evidence reconcile 失敗ブロック一覧（運営・監視用。grace延長失敗も含む）
    if (path === '/evidence-failures' && request.method === 'GET') {
      try {
        const failures = [];
        for (const prefix of ['evidence_reconcile_failed_block', 'evidence_grace_extend_failed_block']) {
          const list = await this.storage.list({ prefix, limit: PUBLIC_STORAGE_LIST_LIMIT });
          for (const [k, v] of list) failures.push({ key: k, ...v });
        }
        return createCORSResponse({ count: failures.length, failures });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // Evidence grace 手動延長（障害対応。単調増加のみ・チャット窓終端前のみ成功する）
    // POST /extend-grace {block_num, grace}（秒）
    if (path === '/extend-grace' && (request.method === 'POST' || request.method === 'GET')) {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }
      let blockNum, graceSec;
      if (request.method === 'GET') {
        blockNum = parseInt(url.searchParams.get('block'));
        graceSec = parseInt(url.searchParams.get('grace'));
      } else {
        const body = await request.json().catch(() => ({}));
        blockNum = Number(body.block_num ?? body.block);
        graceSec = Number(body.grace);
      }
      if (!Number.isFinite(blockNum) || !Number.isFinite(graceSec) || graceSec <= 0) {
        return createCORSResponse({ error: 'block_num and grace (seconds) are required' }, 400);
      }
      try {
        const result = await this.extendGraceOnChain(blockNum, graceSec);
        // コントラクトへの延長だけでは不十分: game-master の phase_task_queue（chat→submit→completed
        // のalarm）は固定executeAtで保存済み。組み替えないとサーバーは旧時刻でsubmitへ遷移し、
        // 後ろへ動いたオンチェーン窓とズレる。宣言タイムライン（サーバー従属）を新graceで張り直す。
        let reschedule = null;
        const adoption = await this.adoptGraceExtensionResult(
          blockNum, graceSec, result, 'manual_extend', { reschedule: false },
        );
        const effectiveGrace = adoption.adopted || adoption.rolledBack ? adoption.graceSec : null;
        if (effectiveGrace != null) {
          reschedule = await this.rescheduleRemainingPhaseTasks(blockNum, effectiveGrace);
        }
        return createCORSResponse({ blockNum, graceSec, result, adoption, reschedule });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // S3-003: Service Binding の全数確認（デプロイ直後の設定漏れ検出用・読み取り専用）。
    // 244本を手で書くことはできないので生成器（generate-service-bindings.mjs）で作り、
    // 実際に env へ入っているかは**デプロイ後にここで機械確認する**。
    if (path === '/binding-check' && request.method === 'GET') {
      const r = checkBindings(this.env, expectedGameWorkerBindings());
      return createCORSResponse({
        service: 'game-master-do',
        ...r,
        hint: r.ok ? undefined
          : 'run `node workers/game_workers/script/generate-service-bindings.mjs` then redeploy this worker',
      }, r.ok ? 200 : 503);
    }

    // S3-008: 通知経路の実機テスト送信。
    // 「照合できない」障害は滅多に起きないので、**本当に届くか**を平時に確かめる手段が要る。
    // 障害が起きて初めて「通知が設定ミスで飛んでいなかった」と分かるのでは意味がない
    // （気づけないまま 26 時間が過ぎるとそのブロックは「ゲームなし・報酬永久凍結」に倒れる）。
    //
    // テスト専用の送信経路は作らない。本番と同じ sendAlertAndRecord() をそのまま呼ぶ。
    // 経路が違えば「テストは通ったが本番は飛ばない」を作り込むことになる。
    //
    // 認証必須: 無認証だと運用者の受信箱を叩く嫌がらせ経路になる（1000通/日の枠も消費される）。
    if (path === '/alert-test' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }
      const config = describeAlertConfig(this.env);
      if (!config.configured) {
        return createCORSResponse({
          error: 'alert transport not configured',
          config,
          hint: 'ALERT_EMAIL（[[send_email]] バインディング）＋ ALERT_EMAIL_FROM / ALERT_EMAIL_TO、'
            + 'または ALERT_WEBHOOK_URL を設定して再デプロイ',
        }, 503);
      }
      const at = new Date().toISOString();
      const result = await sendAlertAndRecord(this.env, this.storage, {
        kind: 'test',
        subject: '[COINU] 通知経路のテスト送信',
        body: [
          'これは通知経路の確認用のテスト送信です。障害は発生していません。',
          '',
          `送信時刻: ${at}`,
          '',
          'このメールが届いていれば、チェーン照合ができずゲームを開始できない状態に',
          'なったとき、同じ経路で（初回1回だけ）通知が届きます。',
        ].join('\n'),
      });
      // sendAlert は throw しない契約なので、成否は HTTP ステータスで返す。
      return createCORSResponse({ ok: result.sent, at, config, result }, result.sent ? 200 : 502);
    }

    // ヘルスチェック
    // S3-012: 無条件 available:true のままだと「ゲームが恒久停止していても健全」に見える。
    // 既存の監視スクリプトを壊さないため available は据え置き（到達性の意味）、
    // 停止要因は degraded / blockers として**追加**する。
    if (path === '/status' && request.method === 'GET') {
      let lifecycle = { blockers: [], queueOldestExecuteAt: null, queueLength: 0 };
      try { lifecycle = await this.collectLifecycleBlockers(); } catch (e) {
        const error = this.observationErrorText(e);
        console.error('[status] lifecycle blocker scan failed:', error);
        lifecycle.blockers.push({
          kind: 'lifecycle_scan_failed',
          error,
          recover: 'Durable Object のストレージ／依存先を復旧し、GET /status を再実行',
        });
      }
      // S3-003: バインディング欠落も「停止要因」として同じ画面に出す
      // S3-008: 通知が設定されているか・最後の送信がどうだったかを出す
      // （「気づけるか」が結果を左右するので、通知経路自体の健全性も監視対象にする）
      const alertCfg = describeAlertConfig(this.env);
      const lastAlert = await this.storage.get(ALERT_STATE_KEY) || null;
      const alertMap = await this.storage.list({ prefix: ALERT_STATE_PREFIX, limit: PUBLIC_STORAGE_LIST_LIMIT });
      const alertLastByKind = {};
      for (const [, record] of alertMap) {
        if (record?.kind) alertLastByKind[record.kind] = record;
      }
      // 移行前の単一キーしか無い環境でも監視を途切れさせない。
      if (lastAlert?.kind && !alertLastByKind[lastAlert.kind]) {
        alertLastByKind[lastAlert.kind] = lastAlert;
      }
      if (!alertCfg.configured) {
        lifecycle.blockers.push({
          kind: 'alert_not_configured',
          detail: '照合できずゲームが止まったとき、運用者へ通知する経路がありません',
          recover: 'ALERT_EMAIL（send_email バインディング）＋ ALERT_EMAIL_FROM / ALERT_EMAIL_TO、または ALERT_WEBHOOK_URL を設定',
        });
      } else {
        for (const record of Object.values(alertLastByKind)) {
          if (record.sent !== false || record.skipped) continue;
          lifecycle.blockers.push({
            kind: 'alert_send_failed', alertKind: record.kind,
            at: record.at, via: record.via, error: record.error,
            recover: '通知経路の設定を確認（送信に失敗すると障害に気づけません）',
          });
        }
      }
      const bindings = checkBindings(this.env, expectedGameWorkerBindings());
      if (!bindings.ok) {
        lifecycle.blockers.push({
          kind: 'service_binding_missing',
          missing: bindings.missing.slice(0, 10),
          missingCount: bindings.missing.length,
          expected: bindings.expected,
          recover: 'generate-service-bindings.mjs を実行して game-master-do を再デプロイ',
        });
      }
      const rpcConfig = describeRpcConfig(this.env);
      if (this.env.EVIDENCE_CONTRACT_ADDRESS && rpcConfig.independentProviders < 2) {
        lifecycle.blockers.push({
          kind: 'rpc_independent_providers_insufficient',
          independentProviders: rpcConfig.independentProviders,
          recover: `${RPC_LIST_ENV} に別の登録ドメインの RPC 業者を追加する`,
        });
      }
      return createCORSResponse({
        service: 'game-master-do',
        timestamp: new Date().toISOString(),
        available: true,
        rpcIndependentProviders: rpcConfig.independentProviders,
        bindingsOk: bindings.ok,
        alerts: { ...alertCfg, last: lastAlert, byKind: alertLastByKind },
        degraded: lifecycle.blockers.length > 0,
        blockerCount: lifecycle.blockers.length,
        blockers: lifecycle.blockers,
        queueLength: lifecycle.queueLength,
        queueOldestExecuteAt: lifecycle.queueOldestExecuteAt,
        phaseTaskActive: lifecycle.activeTask,
        phaseTaskAlarm: lifecycle.alarm,
        taskRuntime: lifecycle.taskRuntime,
        calcBootstrapWatchdog: lifecycle.calcBootstrapWatchdog,
        doneArtifactWatchdog: lifecycle.doneArtifactWatchdog,
        operationalObservations: {
          phaseTaskResurrection: this._phaseTaskResurrectionObservation
            || { state: 'not_attempted', at: null },
        },
        ...observationWriteFailureFields(this.observationWriteFailureCounter),
        configured: this.configuredRuntimeValues(),
      });
    }

    // ChatGameDOストレージクリーンアップ（completed済みのDOストレージを解放）
    if (path === '/cleanup-chat-dos' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      const body = await request.json();
      const { block_num } = body;

      if (block_num === undefined || block_num === null) {
        return createCORSResponse({ error: 'block_num is required' }, 400);
      }

      try {
        const db = this.env.BITCOINU_DATA;
        if (!db) {
          return createCORSResponse({ error: 'BITCOINU_DATA binding not found' }, 500);
        }

        const { results: groups } = await db.prepare(
          'SELECT group_id, status FROM game_groups WHERE block_num = ?'
        ).bind(block_num).all();

        if (!groups || groups.length === 0) {
          return createCORSResponse({ error: 'No groups found for this block' }, 404);
        }

        // timeline no-game cleanup は既に同じ /reset 経路を完了している。
        // 専用状態を通常の「未完了」と誤解して409にせず、冪等な成功として扱う。
        if (groups.every(g => g.status === TIMELINE_NO_GAME_INVALIDATED_STATUS)) {
          return createCORSResponse({
            success: true,
            noGame: true,
            blockNum: block_num,
            totalGroups: groups.length,
            cleaned: 0,
            errors: 0,
          });
        }

        // completed以外のグループがあれば拒否
        const notCompleted = groups.filter(g => g.status !== 'completed');
        if (notCompleted.length > 0) {
          return createCORSResponse({
            error: `${notCompleted.length} groups are not completed yet`,
            statuses: [...new Set(notCompleted.map(g => g.status))]
          }, 409);
        }

        let cleaned = 0;
        let errors = 0;
        for (let i = 0; i < groups.length; i += DO_FETCH_CONCURRENCY) {
          const batch = groups.slice(i, i + DO_FETCH_CONCURRENCY);
          const batchResults = await Promise.all(batch.map(async (group) => {
            try {
              const doId = this.env.CHAT_GAME_DO.idFromName(`${block_num}-${group.group_id}`);
              const chatDO = this.env.CHAT_GAME_DO.get(doId);
              const resp = await chatDO.fetch(this.chatDoRequest('/cleanup', { method: 'POST' }));
              return resp.ok;
            } catch (e) {
              console.error(`Cleanup error for ${block_num}-${group.group_id}:`, e.message);
              return false;
            }
          }));
          for (const ok of batchResults) {
            if (ok) cleaned++; else errors++;
          }
        }

        console.log(`ChatGameDO cleanup for block ${block_num}: ${cleaned} cleaned, ${errors} errors`);
        return createCORSResponse({
          success: true,
          blockNum: block_num,
          totalGroups: groups.length,
          cleaned,
          errors
        });
      } catch (error) {
        return createCORSResponse({ error: error.message }, 500);
      }
    }

    // ブロック単位リセット（テスト用：特定ブロックのグループ分けデータを削除して再実行可能にする）
    if (path === '/reset-block' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }
      if (!verifyLoadTestMutationContext(request, this.env)) {
        return createCORSResponse({ error: 'Test deployment context mismatch' }, 403);
      }

      if (!this.releaseTime || isNaN(this.releaseTime)) {
        return createCORSResponse({ error: 'RELEASE_TIME is not configured. Reset is not allowed.' }, 403);
      }
      if (Date.now() >= this.releaseTime) {
        return createCORSResponse({ error: 'System is already released. Reset is not allowed.' }, 403);
      }

      const body = await request.json();
      const { block_num } = body;

      if (block_num === undefined || block_num === null) {
        return createCORSResponse({ error: 'block_num is required' }, 400);
      }

      try {
        const results = { blockNum: block_num, cleared: [] };

        // 1. ChatGameDOをリセット + win_blocksクリーンアップ用にUID収集（D1削除前にデータ取得）
        const db = this.env.BITCOINU_DATA;
        const allGroupIds = [];
        const cleanupUids = new Set();

        if (db) {
          const { results: groups } = await db.prepare(
            'SELECT group_id, members FROM game_groups WHERE block_num = ?'
          ).bind(block_num).all();

          // ChatGameDOリセット（G3: DO_FETCH_CONCURRENCY並列バッチ）
          if (this.env.CHAT_GAME_DO) {
            for (const group of (groups || [])) allGroupIds.push(group.group_id);
            // S3-013: D1 行に加えて「初期化予定として控えた group_id」も対象にする（孤児対策）
            const registry = await this.storage.get(`chatdo_registry_block${block_num}`) || [];
            const targetIds = [...new Set([...allGroupIds, ...registry])].sort((a, b) => a - b);
            const resetOutcomes = await this.batchChatDoCalls(targetIds.map(group_id => ({ group_id })), async (group) => {
              try {
                const doId = this.env.CHAT_GAME_DO.idFromName(`${block_num}-${group.group_id}`);
                const chatDO = this.env.CHAT_GAME_DO.get(doId);
                const resp = await chatDO.fetch(this.chatDoRequest('/reset', { method: 'DELETE' }));
                if (resp.ok) return true;
                console.error(`Failed to reset ChatGameDO ${block_num}-${group.group_id}:`, await resp.text());
                return false;
              } catch (e) {
                console.error(`Error resetting ChatGameDO ${block_num}-${group.group_id}:`, e.message);
                return false;
              }
            });
            const chatResets = resetOutcomes.filter(Boolean).length;
            const chatResetErrors = resetOutcomes.length - chatResets;
            results.chatResetErrors = chatResetErrors;
            if (chatResets > 0 || chatResetErrors > 0) {
              results.cleared.push(`chat_game_dos: ${chatResets} OK, ${chatResetErrors} errors`);
            }
          }

          // win_blocksクリーンアップ用にプレイヤー + デポジッターのUIDを収集
          for (const group of (groups || [])) {
            try {
              const members = JSON.parse(group.members || '[]');
              for (const member of members) {
                const uid = member.uid;
                if (!uid) continue;
                cleanupUids.add(String(uid));

                // 外部デポジッターのUIDも収集
                if (member.depIds) {
                  try {
                    const depIds = typeof member.depIds === 'string' ? JSON.parse(member.depIds) : member.depIds;
                    if (depIds?.deposits) {
                      for (const dep of depIds.deposits) {
                        if (!dep.idFrom || String(dep.idFrom) === String(uid)) continue;
                        cleanupUids.add(String(dep.idFrom));
                      }
                    }
                  } catch (e) { /* depIds parse error, skip */ }
                }
              }
            } catch (e) {
              console.error(`reset-block: Failed to parse members for group ${group.group_id}:`, e.message);
            }
          }
        }

        // 2. DO storageからprogress削除
        await this.storage.delete(`grouping_block${block_num}_progress`);
        await this.storage.delete(`grouping_d1_complete_block${block_num}`);
        await this.storage.delete(`grouping_shard_cursor_block${block_num}`); // C1: チャンク送信カーソル
        await this.storage.delete(`grouping_shard_failure_alert_block${block_num}`);
        await this.clearRosterGateTimelineWait(block_num);
        const phaseCursorMap = await this.storage.list({ prefix: `phase_shard_cursor_block${block_num}:` });
        if (phaseCursorMap.size > 0) await this.storage.delete([...phaseCursorMap.keys()]);
        results.cleared.push('grouping_progress');

        // 2b. A1: 結果集計パイプラインの進捗・中間キーも削除（再テスト時の混入防止）
        await this.calcCleanupKeys(block_num);
        results.cleared.push('calc_progress');

        // R23-F1: autoDistributeのdone checkpointを残すと、同じselectionの
        // 再実行は冒頭returnし、D1/shard/R2/progressを一切再生成しない。
        // 専用state（stage/cursor/failures/tempを内包）とnamespace下を一覧化して消す。
        await this.autoDistributeCleanupKeys(block_num);
        results.cleared.push('auto_distribute_progress');

        // 3. D1 game_groupsから該当ブロックのレコード削除
        if (db) {
          await db.prepare('DELETE FROM game_groups WHERE block_num = ?').bind(block_num).run();
          results.cleared.push('d1_game_groups');

          await db.prepare('DELETE FROM game_results WHERE block_num = ?').bind(block_num).run();
          results.cleared.push('d1_game_results');

          // レビューH2: 残存evidence_eventsはグループ再編成後のreplayで旧グループ束縛の検証結果を
          // 誤再利用させる（検証キャッシュはグループ構成に依存するため、resetで必ず無効化する）
          await db.prepare("DELETE FROM evidence_events WHERE block_num = ?").bind(block_num).run();
          results.cleared.push('d1_evidence_events');
        }

        // 3.5. シャードDBのwin_blocksからゲーム関連データをクリーンアップ
        // S3-003: 公開 workers.dev URL → Service Binding。
        // 対象は最大 40 ワーカーで Service Binding の1リクエスト上限（32）を超えるため、
        // SB_MAX_CALLS_PER_INVOCATION ずつの**分割送信**にする（reset は同期処理なので
        // アラームへ持ち越さず、同一リクエスト内で順に送る…のではなく、
        // 32 の解釈が「リクエスト全体の合計」であっても安全なように、
        // 1リクエストで送る数を上限以下に抑えたうえで残りを次のバッチへ回す）。
        if (cleanupUids.size > 0) {
          // Round 15 SC-01: groups/phase/results と同じ「worker→100 uid→受信側deferred」規則へ
          // 揃える。旧経路は1 worker分（最大約577 uid）を1リクエストへ詰め、受信側にも
          // 人数上限・storage予算が無かった。チャンク列とカーソルを保存し、30 invocationを
          // 越える分は shard_cleanup alarm（別invocation）へ渡す。
          const pendingKey = `reset_cleanup_block${block_num}`;
          const cursorKey = `reset_cleanup_cursor_block${block_num}`;
          const chunks = this.buildShardWriteChunks(
            [...cleanupUids].map((uid) => ({ uid })),
          );
          await this.storage.delete(cursorKey);
          await this.storage.delete(`${cursorKey}:deferred`);
          await this.saveResetCleanupChunks(block_num, chunks);
          const cleanupStats = { totalWritten: 0, totalErrors: 0 };
          let deferredToAlarm = false;
          try {
            const processed = await this.sendShardWriteChunks(
              '/clean-game-win-blocks', block_num, chunks, { cursorKey, stats: cleanupStats },
            );
            await this.clearResetCleanupChunks(block_num);
            results.cleared.push(`shard_win_blocks: ${processed} processed, 0 errors`);
          } catch (error) {
            deferredToAlarm = true;
            console.error(`reset-block: shard cleanup deferred for block ${block_num}:`, error.message);
            await this.enqueuePhaseTask({
              type: 'shard_cleanup', blockNum: block_num, executeAt: Date.now() + 1000,
            });
            results.cleared.push(
              `shard_win_blocks: ${cleanupStats.totalWritten} processed, `
              + `${cleanupStats.totalErrors} errors, ${chunks.length} chunk(s) checkpointed for alarm`,
            );
          }
          if (deferredToAlarm) results.shardCleanupDeferred = true;
          results.shardCleanupErrors = cleanupStats.totalErrors;
        }

        // 4. phase_task_queueから該当ブロックのタスクを除外
        const taskQueue = await this.storage.get('phase_task_queue') || [];
        // このreset内で新規登録したshard_cleanupだけは残す。従来は直前にenqueueした
        // 持ち越し掃除まで同じblockNumという理由で消し、100k規模で一部win_blocksが残った。
        const filtered = taskQueue.filter(t => t.blockNum !== block_num || t.type === 'shard_cleanup');
        await this.storage.put('phase_task_queue', filtered);
        results.cleared.push(`phase_tasks_removed: ${taskQueue.length - filtered.length}`);

        // 5. 残りタスクがあればアラーム再設定、なければアラーム削除
        if (filtered.length > 0) {
          await this.armEarliestQueuedTask(5000);
        } else {
          await this.state.storage.deleteAlarm();
        }

        console.log(`Block ${block_num} reset: ${results.cleared.join(', ')}`);
        // 🔴 周15（統括）: `success` は**誤りの有無**だけを表す。
        //   `shardCleanupDeferred` は周15 T4（SC-01）が入れた**設計どおりの継続**であって
        //   失敗ではない（本番規模では 10,000 shard を1回で掃けないので必ず立つ）。
        //   ここで false にすると「継続中」と「壊れた」が同じ語になり、
        //   運用者は正常な分割実行を障害と読む（型④「二義的な状態」）。
        //   EL-01 が要求する「部分失敗を成功として記録しない」は
        //   `tools/e2e-load/lib/cleanup-runner.mjs` が `shardCleanupDeferred` と
        //   `shardCleanupErrors` を**独立に**見て checkpoint を書かないことで満たしている。
        const success = Number(results.chatResetErrors || 0) === 0
          && Number(results.shardCleanupErrors || 0) === 0;
        return createCORSResponse({ success, ...results });
      } catch (error) {
        console.error(`Error resetting block ${block_num}:`, error);
        return createCORSResponse({ success: false, error: error.message }, 500);
      }
    }

    // ChatGameDO個別リセット（指定ブロック・グループ範囲）
    if (path === '/reset-chat-dos' && request.method === 'POST') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      if (!this.releaseTime || isNaN(this.releaseTime)) {
        return createCORSResponse({ error: 'RELEASE_TIME is not configured. Reset is not allowed.' }, 403);
      }
      if (Date.now() >= this.releaseTime) {
        return createCORSResponse({ error: 'System is already released. Reset is not allowed.' }, 403);
      }

      const body = await request.json();
      // targets: [{ blockNum, groupId }] の配列
      const { targets } = body;
      if (!targets || !Array.isArray(targets) || targets.length === 0) {
        return createCORSResponse({ error: 'targets array is required' }, 400);
      }

      if (!this.env.CHAT_GAME_DO) {
        return createCORSResponse({ error: 'CHAT_GAME_DO binding not found' }, 500);
      }

      // G3: DO_FETCH_CONCURRENCY並列バッチ
      const errors = [];
      const resetOutcomes = await this.batchChatDoCalls(targets, async (target) => {
        const { blockNum, groupId } = target;
        try {
          const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${groupId}`);
          const chatDO = this.env.CHAT_GAME_DO.get(doId);
          const resp = await chatDO.fetch(this.chatDoRequest('/reset', { method: 'DELETE' }));
          if (resp.ok) return null;
          return `${blockNum}-${groupId}: ${resp.status}`;
        } catch (e) {
          return `${blockNum}-${groupId}: ${e.message}`;
        }
      });
      for (const err of resetOutcomes) if (err) errors.push(err);
      const resetErrors = errors.length;
      const resetOk = resetOutcomes.length - resetErrors;

      console.log(`ChatGameDO individual reset: ${resetOk} OK, ${resetErrors} errors`);
      return createCORSResponse({
        success: true,
        total: targets.length,
        reset: resetOk,
        errors: resetErrors,
        errorDetails: errors.length > 0 ? errors : undefined
      });
    }

    // 全リセット（テスト用）
    if (path === '/reset' && request.method === 'DELETE') {
      if (!this.verifyApiSecret(request)) {
        return createCORSResponse({ error: 'Unauthorized' }, 401);
      }

      if (!this.releaseTime || isNaN(this.releaseTime)) {
        return createCORSResponse({
          error: 'RELEASE_TIME is not configured. Reset is not allowed.'
        }, 403);
      }

      if (Date.now() >= this.releaseTime) {
        return createCORSResponse({
          error: 'System is already released. Reset is not allowed.'
        }, 403);
      }

      // 全ブロックのChatGameDOストレージを解放（GameMasterDOストレージから特定）
      let chatResetTotal = 0;
      let chatResetErrors = 0;
      if (this.env.CHAT_GAME_DO) {
        try {
          // ストレージからgrouping_block*_progressキーを取得してブロック番号とグループ数を特定
          const allKeys = await this.storage.list({ prefix: 'grouping_block' });
          const resetTargets = [];
          for (const [key, progressData] of allKeys) {
            const blockMatch = key.match(/^grouping_block(\d+)_progress$/);
            if (!blockMatch) continue;
            const blockNum = parseInt(blockMatch[1]);
            const totalGroups = progressData?.totalGroups || 0;
            const ids = new Set();
            // group_idは0からの連番
            for (let groupId = 0; groupId < totalGroups; groupId++) ids.add(groupId);
            // S3-013: 初期化予定として控えた group_id も対象へ（progress が壊れていても消える）
            for (const gid of (await this.storage.get(`chatdo_registry_block${blockNum}`) || [])) ids.add(gid);
            for (const groupId of [...ids].sort((a, b) => a - b)) resetTargets.push({ blockNum, groupId });
          }
          // G3: DO_FETCH_CONCURRENCY並列バッチ
          const resetOutcomes = await this.batchChatDoCalls(resetTargets, async ({ blockNum, groupId }) => {
            try {
              const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${groupId}`);
              const chatDO = this.env.CHAT_GAME_DO.get(doId);
              const resp = await chatDO.fetch(this.chatDoRequest('/reset', { method: 'DELETE' }));
              return resp.ok;
            } catch (e) {
              return false;
            }
          });
          chatResetTotal = resetOutcomes.filter(Boolean).length;
          chatResetErrors = resetOutcomes.length - chatResetTotal;
          console.log(`ChatGameDO reset: ${chatResetTotal} OK, ${chatResetErrors} errors`);
        } catch (e) {
          console.error('Error resetting ChatGameDOs:', e.message);
        }
      }

      // D1のゲーム所有テーブルも全削除（/reset-block のH2是正と同水準の防御）。
      // 特に evidence_events: 残存すると次サイクルの同一 (block_num, seq) イベントが
      // 捨てられ、旧サイクルの提出バンドルが採用されて正規提出を上書きする
      // （2026-07-20 block0 全員失格の実障害。一次防御は initialize-all-dbs.js だが、
      // /reset 単独実行でも安全になるようここでも削除する）。
      let d1Cleared = [];
      const resetDb = this.env.BITCOINU_DATA;
      if (resetDb) {
        try {
          await resetDb.prepare('DELETE FROM game_groups').run();
          await resetDb.prepare('DELETE FROM game_results').run();
          await resetDb.prepare('DELETE FROM evidence_events').run();
          d1Cleared = ['game_groups', 'game_results', 'evidence_events'];
        } catch (e) {
          console.error('Error clearing D1 game tables on reset:', e.message);
        }
      }

      await this.storage.deleteAll();
      console.log('All game master data reset by admin');
      return createCORSResponse({
        success: true,
        message: 'All game master data reset',
        chatDOs: { reset: chatResetTotal, errors: chatResetErrors },
        d1Cleared
      });
    }

    return createCORSResponse({ error: 'Not Found' }, 404);
  }

  // ============================================================
  // Alarm handler (collect-DOパターン)
  // ============================================================

  async alarm() {
    console.log('GameMasterDO alarm triggered');

    try {
      const now = Date.now();
      let tasksExecuted = 0;
      const maxContinuousExecution = 3;

      // A1: calc_chunk タスクは「実行前dequeue」のためruntime killで失われ得る。
      // 集計が未完了（calc_block{N}_progress あり）なのにタスクが消えていたら自己復旧でre-enqueueする
      // （DOアラームは失敗時に自動リトライされるため、この検査は必ずいつか実行される）。
      // レビューM1: マーカーはブロック別 — 複数ブロックの計算が重なっても互いを消さない。
      try {
        const progressMap = await this.storage.list({ prefix: 'calc_block' });
        const activeMap = new Map([...progressMap].filter(([key]) => /^calc_block\d+_progress$/.test(key)));
        for (const [key, calcActive] of activeMap) {
          if (this._calcDriving) continue;
          const prog = calcActive;
          if (prog?.stage !== 'done' && !prog?.parked
              && !(await this.calcAdminTxWaitState(calcActive.blockNum, prog)).parked) {
            const q = await this.storage.get('phase_task_queue') || [];
            if (!q.some(t => t.type === 'calc_chunk' && t.blockNum === calcActive.blockNum)) {
              prog.lostRuns = (prog.lostRuns || 0) + 1;
              prog.updatedAt = Date.now();
              // reset-block 等が並行して破棄したパイプラインの進捗を復活させない。
              // legacy marker は診断用に読むだけで、再開可否の起点にはしない。
              const legacyActiveMarker = await this.storage.get(`calc_active:${calcActive.blockNum}`);
              if (!(await this.storage.get(this.calcProgressKey(calcActive.blockNum)))) continue;
              await this.storage.put(this.calcProgressKey(calcActive.blockNum), prog);
              console.warn(`[calc] resurrecting lost calc_chunk task for block ${calcActive.blockNum} (stage=${prog.stage}, lostRuns=${prog.lostRuns})`);
              await this.enqueueCalcContinuation(calcActive.blockNum, calcRetryDelayMs(prog.lostRuns));
            }
          }
        }
      } catch (e) {
        console.error('[calc] resurrection check failed:', e.message);
      }

      // A3: phase_transition タスクも「実行前dequeue」のためruntime killで失われ得る。
      // dequeue時に phase_task_active マーカーを立て、実行完了（成功/再enqueue/park確定）で
      // 消す。マーカーが残っているのに同一タスクがキューに無ければ、前回のalarmが実行途中で
      // 死んだということなのでキュー先頭へ復活させる（advancePhaseは冪等＝再実行安全。
      // calc_chunk は calc_block{N}_progress の専用機構で復旧するため対象外）。
      // DOアラームはハンドラ未完了時に自動リトライされるため、この検査は必ずいつか実行される。
      let phaseTaskActive = null;
      try {
        phaseTaskActive = await this.storage.get('phase_task_active');
        if (phaseTaskActive) {
          const q = await this.storage.get('phase_task_queue') || [];
          const inQueue = q.some(t => t.type === phaseTaskActive.type && t.blockNum === phaseTaskActive.blockNum && t.targetPhase === phaseTaskActive.targetPhase);
          if (inQueue) {
            // 既に再スケジュール済み（失敗再enqueue後のマーカー削除前に死んだ等）→ マーカーだけ破棄
            await this.storage.delete('phase_task_active');
          } else {
            const attempts = (phaseTaskActive.attempts || 0) + 1;
            const parkTarget = phaseTaskActive.type === 'phase_shard_update'
              ? `shard_${phaseTaskActive.targetPhase}`
              : (phaseTaskActive.targetPhase ?? phaseTaskActive.type);
            if (attempts > PHASE_TASK_MAX_ATTEMPTS) {
              console.error(`[phase] task ${phaseTaskActive.type} block ${phaseTaskActive.blockNum} -> ${phaseTaskActive.targetPhase ?? phaseTaskActive.type} parked after ${attempts} attempts (lost mid-execution repeatedly). Manual POST /advance-phase required.`);
              await this.storage.put(`phase_task_parked:${phaseTaskActive.blockNum}:${parkTarget}`, { ...phaseTaskActive, attempts, parkedAt: Date.now() });
              await this.storage.delete('phase_task_active');
            } else {
              console.warn(`[phase] resurrecting lost ${phaseTaskActive.type} task for block ${phaseTaskActive.blockNum} -> ${phaseTaskActive.targetPhase} (attempt ${attempts})`);
              q.unshift({ ...phaseTaskActive, attempts });
              await this.storage.put('phase_task_queue', q);
              await this.storage.delete('phase_task_active');
            }
          }
        }
        this._phaseTaskResurrectionObservation = this.observationResult('succeeded', {
          action: 'resurrection_scan',
          blockNum: phaseTaskActive?.blockNum ?? null,
        });
      } catch (e) {
        this._phaseTaskResurrectionObservation = this.observationFailure(e, {
          action: 'resurrection_scan',
          blockNum: phaseTaskActive?.blockNum ?? null,
        });
        if (Number.isSafeInteger(Number(phaseTaskActive?.blockNum))) {
          this.deferGroupObservation(Number(phaseTaskActive.blockNum), {
            operationalObservations: {
              phaseTaskResurrection: this._phaseTaskResurrectionObservation,
            },
          });
        }
        console.error('[phase] resurrection check failed:', e.message);
      }

      while (tasksExecuted < maxContinuousExecution) {
        let taskQueue = await this.storage.get('phase_task_queue') || [];

        if (taskQueue.length === 0) {
          console.log('No tasks in queue');
          break;
        }

        const currentTask = taskQueue[0];

        // 実行時刻が未来の場合は待機
        // S3-009（2026-07-29）: 旧実装は `now + 60000` までを「期限到来」として実行していた。
        // 複数ブロック・複数種別が1つのキューを共有し、1回のアラームで最大3タスクを連続処理
        // するため、別タスク由来のアラームが境界の60秒以内に先行すると
        // **フェーズ遷移が最大60秒早く実行される**。チャット終了が60秒早まれば、
        // その間の発言・提出が拒否され、宣言窓（オンチェーン）と実際の運用がズレる。
        // 猶予は「遅延の検出」にだけ使い、**先取り実行はしない**。
        if (currentTask.executeAt > now) {
          console.log(`Next task is in future (${new Date(currentTask.executeAt).toISOString()}), setting alarm`);
          const { alarmAt: alarmTime } = await this.armEarliestQueuedTask(5000);
          console.log(`Next alarm set for ${new Date(alarmTime).toISOString()}, type: ${currentTask.type}, block: ${currentTask.blockNum}`);
          break;
        }

        // タスクをキューから削除。
        // A3: phase_transition / grouping_watchdog(A6) は実行中マーカーをキュー更新と同一putで
        // 書く（この間に死んでもタスクが「キューにもマーカーにも無い」瞬間が存在しない）。
        // calc_chunk は calc_block{N}_progress の専用機構で復旧するため対象外。
        taskQueue.shift();
        if (currentTask.type === 'phase_transition' || currentTask.type === 'grouping_watchdog'
            || currentTask.type === 'init_chat_games' || currentTask.type === 'roster_anchor'
            || currentTask.type === 'phase_shard_update' || currentTask.type === 'grace_reconcile') {
          await this.storage.put({
            'phase_task_queue': taskQueue,
            'phase_task_active': { ...currentTask, activeAt: Date.now() },
          });
        } else {
          await this.storage.put('phase_task_queue', taskQueue);
        }

        tasksExecuted++;

        console.log(`Executing task ${tasksExecuted}: ${currentTask.type} for block ${currentTask.blockNum}, phase=${currentTask.targetPhase}`);

        // Q50: cleanup 開始後に競合して残った通常ゲーム task は実行しない。
        // cleanup 失敗時の再開を担う grouping_watchdog だけは pending 中に通す。
        const noGameCleanup = await this.storage.get(this.timelineNoGameCleanupKey(currentTask.blockNum));
        const cleanupGroupingProgress = currentTask.type === 'grouping_watchdog'
          ? await this.storage.get(`grouping_block${currentTask.blockNum}_progress`)
          : null;
        const cleanupAdminTxWait = cleanupGroupingProgress?.waitReason === 'admin_freeze'
          || cleanupGroupingProgress?.waitReason === 'admin_tx_pending';
        const allowCleanupRetry = currentTask.type === 'grouping_watchdog'
          && (noGameCleanup?.status === 'pending' || cleanupAdminTxWait);
        if (noGameCleanup
            && TIMELINE_NO_GAME_CANCELLED_TASK_TYPES.has(currentTask.type)
            && !allowCleanupRetry) {
          console.warn(
            `[timeline-no-game] skipping stale ${currentTask.type} task for block ${currentTask.blockNum} `
            + `(cleanup=${noGameCleanup.status})`
          );
          // 便 PLAYAT: availability_seed は実行中の印を書かない。ここでも印に触れない
          // （復活の走査が読めなかった回に残っている、ほかの仕事の印を消さないため）。
          if (currentTask.type !== 'availability_seed') await this.storage.delete('phase_task_active');
          if (currentTask.type === 'grouping_watchdog' || currentTask.type === 'roster_anchor'
              || currentTask.type === 'phase_shard_update') {
            tasksExecuted = maxContinuousExecution;
          }
          continue;
        }

        switch (currentTask.type) {
          case 'grace_reconcile': {
            try {
              await this.runGraceReconcileTask(currentTask.blockNum);
            } catch (e) {
              console.error(`[evidence] grace reconcile failed for block ${currentTask.blockNum}: ${e.message}`);
              await this.enqueueGraceReconcileTask(currentTask.blockNum, {
                reason: 'grace_reconcile_error',
                delayMs: PHASE_TASK_RETRY_DELAY_MS,
              });
            }
            await this.storage.delete('phase_task_active');
            tasksExecuted = maxContinuousExecution;
            break;
          }
          case 'phase_transition': {
            try {
              // 自動 grace 延長: alarm が宣言時刻より大幅に遅れて実行された場合（DO障害からの復帰等）、
              // チャット窓終端（=submitting遷移）より前なら extendGrace で宣言タイムラインを実態に
              // 追従させ、このブロックの残タスクを新タイムラインへ組み直す。
              let requeuedAtDeclaredBoundary = false;
              const latenessMs = Date.now() - currentTask.executeAt;
              if (latenessMs > 60000 &&
                  (currentTask.targetPhase === 'chatting' || currentTask.targetPhase === 'submitting') &&
                  this.env.EVIDENCE_CONTRACT_ADDRESS) {
                try {
                  const shifted = await this.autoExtendAndReschedule(currentTask, latenessMs, taskQueue);
                  if (shifted) {
                    currentTask.phaseEndTime = shifted.phaseEndTime ?? currentTask.phaseEndTime;
                    currentTask.phaseEndTimeSource = 'scheduled_chain_rescheduled';
                    requeuedAtDeclaredBoundary = shifted.requeued === true;
                  }
                } catch (e) {
                  console.error(`[evidence] auto-extend failed:`, e.message);
                }
              }
              // 🔴 ラウンド19 判断不要-4（2026-08-08）: **戻り値を検査する。**
              //    `advancePhase` は per-group の `/set-phase` 失敗を `batchChatDoCalls` の
              //    catch で `false` に潰し、**throw せず** `{success:false, advanced, errors}` を
              //    返す（`batchChatDoCalls` に再試行は無い）。旧実装はその戻り値を一度も見て
              //    おらず、catch は throw にしか反応しないので、1グループの一過性 500 が
              //    **そのグループ全員の全損**になっていた:
              //      ・`chatting` 遷移だけ失敗したグループは `waiting` のまま残る
              //      ・:3447 の SELECT は `WHERE block_num = ?` だけなので、次の
              //        `submitting` 遷移は `waiting` のグループにも送られ、
              //        `chat-game-DO.js:550-553` は後退しか禁じないので **200 で受理**
              //      ・結果: `phaseTimestamps` に `chattingAt` が無いまま採点され
              //        `["min_chars","min_messages","no_vote"]` で全員 0 点
              //    watchdog（`status='formed'` しか拾わない）も、`collectLifecycleBlockers`
              //    （`phase_task_parked:` しか見ない）も、block-verifier（`chattingAt` を
              //    1件も参照しない）も鳴らない＝**静かな 0 点**だった。
              //    🔴 隣の `init_chat_games`（下の case）は既に `if (res?.errors > 0) throw`
              //       を明示している＝同じ switch の隣り合う分岐で扱いが非対称だった。
              //    `advancePhase` は冪等（既に遷移済みのグループは ChatGameDO 側が
              //    `{unchanged:true}` に落とす）なので、再実行は副作用ゼロで安全。
              //    既存のバックオフ（PHASE_TASK_RETRY_DELAY_MS=90s × PHASE_TASK_MAX_ATTEMPTS=20
              //    ＝最大30分）にそのまま載り、恒久障害なら park キーが立って
              //    `/calc-status` の blockers に出る（＝「静かな0点」が「見える0点」になる）。
              if (!requeuedAtDeclaredBoundary) {
                const res = await this.advancePhase(
                  currentTask.blockNum,
                  currentTask.targetPhase,
                  currentTask.phaseEndTime ?? null,
                  {
                    phaseEndTimeSource: currentTask.phaseEndTimeSource || 'scheduled_declared',
                    manualFallback: false,
                  },
                );
                if (!res?.success || (res.errors ?? 0) > 0) {
                  throw new Error(
                    `phase transition partial failure: ${res?.errors ?? '?'} of ${res?.totalGroups ?? '?'} groups failed`
                    + `${res?.error ? ` (${res.error})` : ''}`
                  );
                }
              }
            } catch (e) {
              // A3: 従来はここでのthrowがalarm全体を中断し、タスク喪失＋final setAlarm不達で
              // キューが恒久停止していた。バックオフ付きで再enqueueし、alarmループは継続する。
              const attempts = (currentTask.attempts || 0) + 1;
              if (attempts > PHASE_TASK_MAX_ATTEMPTS) {
                console.error(`[phase] task block ${currentTask.blockNum} -> ${currentTask.targetPhase} parked after ${attempts} failed attempts: ${e.message}. Manual POST /advance-phase required.`);
                await this.storage.put(`phase_task_parked:${currentTask.blockNum}:${currentTask.targetPhase}`, { ...currentTask, attempts, parkedAt: Date.now(), lastError: String(e?.message || e) });
              } else {
                console.error(`[phase] transition failed for block ${currentTask.blockNum} -> ${currentTask.targetPhase} (attempt ${attempts}): ${e.message} — retrying in ${PHASE_TASK_RETRY_DELAY_MS / 1000}s`);
                const q = await this.storage.get('phase_task_queue') || [];
                q.push({ ...currentTask, attempts, executeAt: Date.now() + PHASE_TASK_RETRY_DELAY_MS });
                q.sort((a, b) => a.executeAt - b.executeAt);
                await this.storage.put('phase_task_queue', q);
              }
            }
            // 成功・再enqueue・park確定のいずれでも実行中マーカーを下ろす
            await this.storage.delete('phase_task_active');
            break;
          }
          case 'init_chat_games': {
            // v3.2: 早着ガード撤去後の init_chat_games タスクは「失敗リトライ」と
            // 「安全網（グループ分け完了済みなのに init 未実行）」の再実行専用。
            try {
              const res = await this.initChatGames(currentTask.blockNum);
              if (!res?.success && !res?.deferred) {
                throw new Error(res?.error || `init errors=${res?.errors ?? '?'}`);
              }
              if (res?.errors > 0) {
                // 部分失敗: 初期化済みDOは409で保護されるため再実行は安全。バックオフ再試行。
                throw new Error(`init partial failure: ${res.errors} errors`);
              }
            } catch (e) {
              const attempts = (currentTask.attempts || 0) + 1;
              if (attempts > PHASE_TASK_MAX_ATTEMPTS) {
                console.error(`[init] block ${currentTask.blockNum} chat init parked after ${attempts} failed attempts: ${e.message}. Manual /init-chat-games required.`);
                await this.storage.put(`phase_task_parked:${currentTask.blockNum}:init_chat_games`, { ...currentTask, attempts, parkedAt: Date.now(), lastError: String(e?.message || e) });
              } else {
                console.error(`[init] chat init failed for block ${currentTask.blockNum} (attempt ${attempts}): ${e.message} — retrying in ${PHASE_TASK_RETRY_DELAY_MS / 1000}s`);
                const q = await this.storage.get('phase_task_queue') || [];
                q.push({ ...currentTask, attempts, executeAt: Date.now() + PHASE_TASK_RETRY_DELAY_MS });
                q.sort((a, b) => a.executeAt - b.executeAt);
                await this.storage.put('phase_task_queue', q);
              }
            }
            await this.storage.delete('phase_task_active');
            break;
          }
          case 'roster_anchor': {
            let anchorFailure = null;
            let anchorPending = false;
            let checkedCommitment = null;
            let completenessReadUnavailable = false;
            try {
              // 再試行・手動投入を含め、登録 tx より前に公開一覧と D1 の全組を照らす。
              const d1Completeness = await this.checkGroupingD1Completeness(currentTask.blockNum);
              if (!d1Completeness.complete) {
                await this.noteRosterGateNotReady(currentTask.blockNum, 'groups_incomplete', null);
                throw new Error('groups_incomplete');
              }
              // index/group/manifest を毎回正典入力から再構築する。
              // 保存済み manifest tx の再送だけでは R2 一過性失敗から回復できない。
              // ただし Coordinator が receipt 待ちの間は、直前に保存した同一manifestでtxだけを
              // 再照会する。正常なpendingのたびに全groupを再公開し直さない。
              let manifestText = currentTask.anchorOnly === true
                ? await this.storage.get(`roster_manifest_text_block${currentTask.blockNum}`)
                : null;
              if (typeof manifestText !== 'string' || manifestText.length === 0) {
                ({ manifestText } = await this.rebuildAndPublishRosterManifest(currentTask.blockNum));
                // 全 group の再公開と実バイトの再読を別 invocation に分ける。
                await this.enqueuePhaseTask({
                  type: 'roster_anchor', blockNum: currentTask.blockNum, anchorOnly: true,
                  attempts: currentTask.attempts || 0, executeAt: Date.now() + 1000,
                });
                await this.storage.delete('phase_task_active');
                tasksExecuted = maxContinuousExecution;
                break;
              }
              const registered = currentTask.anchorOnly === true
                ? await this.storage.get(`roster_anchor_block${currentTask.blockNum}`) : null;
              const commitment = await this.computePublishedRosterCommitment(currentTask.blockNum, manifestText);
              checkedCommitment = commitment;
              const anchored = registered?.key?.toLowerCase() === rosterAnchorKey(currentTask.blockNum)
                  && registered?.hash?.toLowerCase() === commitment.C?.toLowerCase()
                ? { anchored: true, alreadyRegistered: true }
                : await this.anchorRosterManifestOnChain(currentTask.blockNum, manifestText, commitment);
              if (!anchored.anchored) {
                if (anchored.pending) anchorPending = true;
                else anchorFailure = anchored.reason || 'not_confirmed';
              }
            } catch (error) {
              anchorFailure = error?.message || error;
              completenessReadUnavailable = !!(error?.resumable || error?.r2ReadUnavailable);
            }
            if (completenessReadUnavailable) {
              // 読取失敗を開始判定へ渡すと同じ R2 例外が alarm の外へ出て共有キューを止める。
              await this.scheduleRosterAnchorRetry(currentTask.blockNum, anchorFailure);
              await this.storage.delete('phase_task_active');
              tasksExecuted = maxContinuousExecution;
              break;
            }
            // 確定した manifest/chain anchor を開始条件として照合する。
            // 失敗時は開始を張らず、登録済みなら関門だけ、未登録なら再公開・登録へ戻す。
            const scheduleResult = await this.scheduleChatWhenAllGroupsReady(currentTask.blockNum, checkedCommitment);
            if (scheduleResult?.pastWaiting) {
              await this.clearRosterGateAfterStart(currentTask.blockNum);
            } else if (anchorPending) {
              await this.enqueuePhaseTask({
                ...currentTask,
                anchorOnly: true,
                executeAt: Date.now() + (scheduleResult?.retryInMs || PHASE_TASK_RETRY_DELAY_MS),
              });
            } else if (anchorFailure) {
              await this.scheduleRosterAnchorRetry(currentTask.blockNum, anchorFailure);
            } else if (!scheduleResult?.ready && !scheduleResult?.noGame) {
              // RPC の遅れ・確定深さ・grace 着地待ちは登録失敗の予算を消費しない。
              await this.enqueuePhaseTask({
                type: 'roster_anchor', blockNum: currentTask.blockNum, anchorOnly: true,
                attempts: currentTask.attempts || 0,
                executeAt: Date.now() + (scheduleResult?.retryInMs || PHASE_TASK_RETRY_DELAY_MS),
              });
            }
            await this.storage.delete('phase_task_active');
            tasksExecuted = maxContinuousExecution;
            break;
          }
          case 'grouping_watchdog': {
            // A6: グループ分けリースの見張り。'started'のままリース失効＝前回実行の途中死を
            // 検知して自己再実行する（乗っ取りクレーム・attempts・parkはstartGrouping側）。
            try {
              await this.checkGroupingWatchdog(currentTask.blockNum);
            } catch (e) {
              console.error(`[grouping] watchdog failed for block ${currentTask.blockNum}:`, e.message);
              this.deferGroupObservation(currentTask.blockNum, {
                watchdog: { run: this.observationFailure(e, { action: 'alarm_run' }) },
              });
              try {
                await this.enqueueGroupingWatchdog(currentTask.blockNum, 60000);
              } catch (e2) { /* 再登録失敗時は次のstartGrouping/手動呼び出しに委ねる */ }
            }
            await this.storage.delete('phase_task_active');
            tasksExecuted = maxContinuousExecution; // 再実行は重い可能性があるためこのalarmはここまで
            break;
          }
          case 'shard_cleanup': {
            // S3-003: reset-block のシャード掃除のうち、Service Binding の
            // 1リクエスト上限（32）に収まらなかったぶんを別リクエストで片づける。
            // 冪等（win_blocks からの削除）なので再実行は安全。
            try {
              await this.drainShardCleanup(currentTask.blockNum);
            } catch (e) {
              if (e?.resumable) {
                console.warn(
                  `[reset] shard cleanup block ${currentTask.blockNum}: ${e.message} `
                  + '— resuming in 1s without consuming an attempt'
                );
                await this.enqueuePhaseTask({
                  ...currentTask,
                  attempts: currentTask.attempts || 0,
                  executeAt: Date.now() + 1000,
                });
              } else {
                const attempts = (currentTask.attempts || 0) + 1;
                if (attempts > PHASE_TASK_MAX_ATTEMPTS) {
                  console.error(
                    `[reset] shard cleanup block ${currentTask.blockNum} parked after ${attempts} `
                    + `failed attempts: ${e.message}`
                  );
                  await this.storage.put(`phase_task_parked:${currentTask.blockNum}:shard_cleanup`, {
                    ...currentTask,
                    attempts,
                    parkedAt: Date.now(),
                    lastError: String(e?.message || e),
                  });
                } else {
                  console.error(
                    `[reset] shard cleanup failed for block ${currentTask.blockNum} `
                    + `(attempt ${attempts}): ${e.message} — retrying in ${PHASE_TASK_RETRY_DELAY_MS / 1000}s`
                  );
                  await this.enqueuePhaseTask({
                    ...currentTask,
                    attempts,
                    lastError: String(e?.message || e),
                    executeAt: Date.now() + PHASE_TASK_RETRY_DELAY_MS,
                  });
                }
              }
            }
            await this.storage.delete('phase_task_active');
            tasksExecuted = maxContinuousExecution;
            break;
          }
          case 'phase_shard_update': {
            // R12-21: phase通知は最大約240チャンク。予算30のresumable yieldは正常な継続なので、
            // 1秒後に同じattemptsのまま再駆動する。実障害だけが90秒バックオフとpark枠を消費する。
            try {
              await this.updateGamePhaseToShards(currentTask.blockNum, currentTask.targetPhase);
            } catch (e) {
              if (e?.resumable) {
                console.warn(
                  `[phase-shard] block ${currentTask.blockNum} -> ${currentTask.targetPhase}: `
                  + `${e.message} — resuming in 1s without consuming an attempt`
                );
                await this.enqueuePhaseTask({
                  ...currentTask,
                  attempts: currentTask.attempts || 0,
                  executeAt: Date.now() + 1000,
                });
              } else {
                const attempts = (currentTask.attempts || 0) + 1;
                if (attempts > PHASE_TASK_MAX_ATTEMPTS) {
                  console.error(
                    `[phase-shard] block ${currentTask.blockNum} -> ${currentTask.targetPhase} `
                    + `parked after ${attempts} failed attempts: ${e.message}`
                  );
                  await this.storage.put(`phase_task_parked:${currentTask.blockNum}:shard_${currentTask.targetPhase}`, {
                    ...currentTask,
                    attempts,
                    parkedAt: Date.now(),
                    lastError: String(e?.message || e),
                  });
                } else {
                  console.error(
                    `[phase-shard] block ${currentTask.blockNum} -> ${currentTask.targetPhase} `
                    + `failed (attempt ${attempts}): ${e.message} — retrying in ${PHASE_TASK_RETRY_DELAY_MS / 1000}s`
                  );
                  await this.enqueuePhaseTask({
                    ...currentTask,
                    attempts,
                    lastError: String(e?.message || e),
                    executeAt: Date.now() + PHASE_TASK_RETRY_DELAY_MS,
                  });
                }
              }
            }
            await this.storage.delete('phase_task_active');
            tasksExecuted = maxContinuousExecution;
            break;
          }
          case 'calc_chunk': {
            // A1: 結果集計の継続実行。1回のalarm呼び出しでは集計driveのみ実行
            // （サブリクエスト/CPU予算を他のタスクと混ぜない）。
            try {
              await this.calculateAndStoreResults(currentTask.blockNum);
            } catch (e) {
              console.error(`[calc] chunk failed for block ${currentTask.blockNum}:`, e.message);
              const prog = await this.storage.get(this.calcProgressKey(currentTask.blockNum));
              if (prog && prog.stage !== 'done' && !prog.parked
                  && !(await this.calcAdminTxWaitState(currentTask.blockNum, prog)).parked) {
                await this.enqueueCalcContinuation(currentTask.blockNum, calcRetryDelayMs(prog.failures)); // R5: 指数バックオフ再試行
              }
            }
            tasksExecuted = maxContinuousExecution; // このalarm呼び出しはここまで
            break;
          }
          case 'post_commit_zkp': {
            // R20-F8: root確定後のproof poll/attach/cancel cleanupは通常calcから分離する。
            // 進行中の proof は期限後も追跡し、attach / GET の失敗は期限で止める。
            try {
              await this.drivePostCommitZkp(currentTask.blockNum);
            } catch (e) {
              console.error(`[zkProof] post-commit drive failed block=${currentTask.blockNum}: ${e.message}`);
              await this.enqueuePhaseTask({
                type: 'post_commit_zkp', blockNum: currentTask.blockNum,
                executeAt: Date.now() + ZKP_POLL_DEFAULT_MS,
              });
            }
            await this.storage.delete('phase_task_active');
            tasksExecuted = maxContinuousExecution;
            break;
          }
          case 'availability_seed': {
            // 便 PLAYAT（2026-11-25）: 参加予定時刻を集める後追いの仕事。表示だけの値なので、
            // 何が起きても alarm のループへ例外を出さない（次の仕事と final setAlarm を止めない）。
            // 実行中の印（phase_task_active）は使わない＝ここで消さない（ほかの仕事の印に触れない）。
            // 同じ alarm で先に別の仕事が動いていたら、fetch の予算を分け合わずに次の alarm へ回す。
            // すぐ後ろに時刻に意味のある仕事（フェーズの遷移・開始の関門）が控えているときも、走らずに後ろへ回す
            // （キューから外した後の残り taskQueue を渡す。保存は読み直さない）。
            let seedIdle = false;
            try {
              const seedOutcome = await this.driveAvailabilitySeedTask(currentTask, {
                sharedInvocation: tasksExecuted > 1, queuedBehind: taskQueue,
              });
              seedIdle = seedOutcome?.idle === true;
            } catch (e) {
              try {
                console.warn(`[availability-seed] block ${currentTask.blockNum}: dropped (${String(e?.message || e)})`);
              } catch (logError) { /* ログの失敗でも alarm を止めない */ }
            }
            if (seedIdle) {
              // 回した・やめただけで fetch を1本も出していない。この alarm の枠を使わず、後ろの仕事を今までどおり
              // 同じ alarm で続ける（回した仕事の時刻は今より後なので、この alarm でもう一度取り出すことは無い）。
              tasksExecuted--;
              break;
            }
            tasksExecuted = maxContinuousExecution; // 読みと配りの予算をほかの仕事と混ぜない
            break;
          }
          default:
            console.warn(`Unknown task type: ${currentTask.type}`);
        }
      }

      // 残りタスクがあればアラーム設定
      const finalTaskQueue = await this.storage.get('phase_task_queue') || [];
      if (finalTaskQueue.length > 0) {
        const nextTask = finalTaskQueue[0];
        const { alarmAt: alarmTime } = await this.armEarliestQueuedTask(5000);
        console.log(`Final alarm set for ${new Date(alarmTime).toISOString()}, type: ${nextTask.type}, block: ${nextTask.blockNum}`);
      } else {
        console.log('All tasks completed');
      }

    } catch (error) {
      console.error('Error in alarm execution:', error);
      // A3: ここに到達するとfinal setAlarmが実行されておらず、外部リクエストが来るまで
      // キューが停止する。安全網として短い再試行alarmを必ず仕掛ける。
      try {
        // 例外復旧ではキュー最早（数日先になり得る）を選ばず、active marker の復活走査を
        // 必ず30秒後に再実行する。通常終了時の earliest-wins 規則とは役割が異なる。
        await this.state.storage.setAlarm(Date.now() + 30000);
      } catch (fallbackError) {
        console.error('Failed to set safety-net alarm:', fallbackError.message);
      }
    }
  }

  // ============================================================
  // Core methods
  // ============================================================

  verifyApiSecret(request) {
    const apiSecretHeader = request.headers.get('X-Api-Secret');
    const validApiSecret = this.env.API_SECRET;
    if (!validApiSecret) {
      console.warn('API_SECRET is not set in environment variables');
      return false;
    }
    return apiSecretHeader === validApiSecret;
  }

  // ============================================================
  // A6: グループ分けのリース化
  // 従来の'started'クレームは無期限で、実行がcatchを通らず死ぬ（runtime kill・退避・
  // 再デプロイ等）と札が'started'のまま残り、以後の再実行要求が永遠に弾かれて
  // そのブロックのゲームが二度と始まらなかった（手動復旧のみ）。
  // 是正: クレームは期限付きリース（各フェーズ境界で延長）。期限切れは乗っ取り再実行可
  // （グループ分けは公開乱数由来の決定論的シード＝再実行で同一グループ・全書き込みは
  // 上書き/重複排除済みで冪等）。クレーム時にwatchdogタスクを仕掛け、外部呼び出しに
  // 頼らず自己復旧する（calc_active / phase_task_active と同思想）。
  // ============================================================

  // phase_task_queue を共有する全タスク種別の alarm は、必ずキュー全体の最早時刻へ張る。
  // setAlarm は既存 alarm を置換するため、追加したタスク自身の時刻へ直接張ると、先に待っている
  // phase_transition を calc_chunk / watchdog が後ろへ追いやってしまう。
  async armEarliestQueuedTask(pastDueDelayMs = 1000, noTaskAlarmMs = null) {
    const queue = await this.storage.get('phase_task_queue') || [];
    const nextTask = queue.reduce((earliest, task) => {
      if (!Number.isFinite(Number(task?.executeAt))) return earliest;
      if (!earliest || Number(task.executeAt) < Number(earliest.executeAt)) return task;
      return earliest;
    }, null);
    const now = Date.now();
    if (!nextTask && (!Number.isFinite(Number(noTaskAlarmMs)) || Number(noTaskAlarmMs) <= 0)) return null;
    const alarmAt = nextTask
      ? (Number(nextTask.executeAt) <= now ? now + pastDueDelayMs : Number(nextTask.executeAt))
      : now + Number(noTaskAlarmMs);
    await this.state.storage.setAlarm(alarmAt);
    return { alarmAt, task: nextTask };
  }

  // S3-003: 汎用のフェーズタスク登録（同種・同ブロック・同targetPhaseの重複は入れない）
  async enqueuePhaseTask(task) {
    const q = await this.storage.get('phase_task_queue') || [];
    if (!q.some(t => t.type === task.type && t.blockNum === task.blockNum
        && (t.targetPhase ?? null) === (task.targetPhase ?? null))) {
      q.push(task);
      q.sort((a, b) => a.executeAt - b.executeAt);
      await this.storage.put('phase_task_queue', q);
    }
    await this.armEarliestQueuedTask();
  }

  // ============================================================
  // 便 PLAYAT（2026-11-25・ユーザー決定）: 参加予定時刻を集める後追いの仕事（availability_seed）
  // エントリーの時・マイページで先に入れた参加予定時刻（users.entry_blocks[N].playAt）を、
  // ChatGameDO の初期化の後で書き込みワーカーの読む口（/read-play-schedule）から集め、
  // グループごとに ChatGameDO（/seed-availability）へ渡す。表示だけの値（署名なし・採点に無関係）。
  // 🔴 この仕事の失敗で、グループ分け・ChatGameDO の初期化・名簿の登録・フェーズの遷移・集計を
  //    1つも変えない。実行中の印・park・警報・保存の鍵を持たない（刻みの定数の所の説明を参照）。
  // ============================================================

  // initChatGames の成功の出口（初回と、全行 waiting での再入）から呼ぶ登録。投げない。
  // 同じブロックの仕事がキューにあれば重ねて入れない（enqueuePhaseTask の決まり）。
  // 何度登録されても、ChatGameDO は一度渡した uid・本人が触った uid に二度と入れないので害は無い。
  async enqueueAvailabilitySeedBestEffort(blockNum) {
    try {
      await this.enqueuePhaseTask({
        type: 'availability_seed', blockNum,
        executeAt: Date.now() + AVAILABILITY_SEED_ENQUEUE_DELAY_MS, cursor: 0, attempts: 0,
      });
    } catch (seedError) {
      try {
        console.warn(`[availability-seed] block ${blockNum}: enqueue failed (${String(seedError?.message || seedError)}) — chat init is unaffected`);
      } catch (logError) { /* ログの失敗でも初期化を止めない */ }
    }
  }

  // alarm の case から呼ぶ入口。1回ぶんを実行し、続き・やり直しの登録までを行う。
  // 状態は仕事のオブジェクトの cursor（次に読むチャンク）・attempts（仕事そのものが投げた回数）・
  // deferrals（走らずに後ろへ回した回数）だけ。どれも鎖の全体で持ち越す＝鎖は有限で終わる
  // （走れば cursor が進むか attempts が増え、走らなければ deferrals が増える。3つとも上限がある）。
  // 戻り値の idle:true は「fetch を1本も出していない」。alarm の case はその回の枠を返す。
  async driveAvailabilitySeedTask(task, { sharedInvocation = false, queuedBehind = null } = {}) {
    const rawBlockNum = task?.blockNum;
    const blockNum = typeof rawBlockNum === 'number' ? rawBlockNum
      : (typeof rawBlockNum === 'string' && /^\d{1,15}$/.test(rawBlockNum) ? Number(rawBlockNum) : Number.NaN);
    if (!Number.isSafeInteger(blockNum) || blockNum < 0) {
      console.warn(`[availability-seed] dropped: invalid block ${String(rawBlockNum)}`);
      return { state: 'dropped', reason: 'invalid_block', idle: true };
    }
    const cursor = Number.isSafeInteger(task?.cursor) && task.cursor >= 0 ? task.cursor : 0;
    const attempts = Number.isSafeInteger(task?.attempts) && task.attempts >= 0 ? task.attempts : 0;
    const deferrals = Number.isSafeInteger(task?.deferrals) && task.deferrals >= 0 ? task.deferrals : 0;
    const requeueAt = (fields, executeAt) => this.enqueuePhaseTask({
      type: 'availability_seed', blockNum, cursor, attempts, deferrals, ...fields, executeAt,
    });

    // キューの残りで、譲る相手の種類（宣言の時刻・開始の関門に関わる仕事）の最も早い時刻。
    // その種類で時刻の読めない仕事は、alarm のループが「期限が来ている」と扱う（`executeAt > now` が偽）
    // ので、ここでも今と同じに数える。一覧の外の種類は、時刻が読めても読めなくても譲る理由にしない
    // （集計の続きなどに譲り続けて、上限でやめないため。ほかのブロックの availability_seed も一覧の外＝
    // 集める仕事どうしで譲り合って止まらない）。
    const nowMs = Date.now();
    let nextOtherAt = null;
    for (const queued of (Array.isArray(queuedBehind) ? queuedBehind : [])) {
      if (!queued || !AVAILABILITY_SEED_YIELD_TO_TASK_TYPES.has(queued.type)) continue;
      const queuedAt = Number.isFinite(Number(queued.executeAt)) ? Number(queued.executeAt) : nowMs;
      if (nextOtherAt === null || queuedAt < nextOtherAt) nextOtherAt = queuedAt;
    }
    // この仕事が今から走ると、その仕事は最悪で「実行の時間の上限＋張り直しの分」待つ。その内にあるなら譲る。
    const yieldToOther = nextOtherAt !== null
      && nextOtherAt <= nowMs + AVAILABILITY_SEED_RUN_BUDGET_MS + AVAILABILITY_SEED_REARM_ALLOWANCE_MS;

    if (sharedInvocation || yieldToOther) {
      // 走らずに後ろへ回す（fetch を1本も出さない）:
      //   ・同じ alarm で先に別の仕事（フェーズの遷移・初期化）が動いた → fetch の予算
      //     （Service Binding 30・サブリクエスト 1000）を分け合わないよう、次の alarm へ。
      //   ・すぐ後ろに時刻に意味のある仕事が控えている → その仕事の時刻の少し後へ。
      // 回した回数には上限を置く。そういう仕事が来続ける間は、いつまでも回さずにやめる。
      const nextDeferrals = deferrals + 1;
      if (nextDeferrals > AVAILABILITY_SEED_MAX_DEFERRALS) {
        console.warn(`[availability-seed] block ${blockNum}: giving up at chunk ${cursor} after ${deferrals} deferrals (other tasks kept coming)`);
        return { state: 'gave_up', reason: 'deferrals', idle: true, cursor, attempts, deferrals };
      }
      const executeAt = yieldToOther
        ? Math.max(nowMs, nextOtherAt) + AVAILABILITY_SEED_YIELD_DELAY_MS
        : nowMs + AVAILABILITY_SEED_CONTINUE_DELAY_MS;
      await requeueAt({ deferrals: nextDeferrals }, executeAt);
      return {
        state: 'deferred', reason: yieldToOther ? 'other_task_near' : 'shared_invocation', idle: true,
        cursor, attempts, deferrals: nextDeferrals, executeAt,
      };
    }

    let outcome;
    try {
      outcome = await this.runAvailabilitySeedTask({ blockNum, cursor });
    } catch (e) {
      // 仕事そのものの失敗（D1 の読みなど）。同じ cursor でやり直し、決めた回数を超えたらやめる。
      const failedAttempts = attempts + 1;
      const detail = this.availabilitySeedErrorText(e);
      if (failedAttempts > AVAILABILITY_SEED_MAX_ATTEMPTS) {
        console.warn(`[availability-seed] block ${blockNum}: giving up at chunk ${cursor} after ${failedAttempts} failed attempts: ${detail}`);
        return { state: 'gave_up', reason: 'attempts', cursor, attempts: failedAttempts, deferrals };
      }
      console.warn(`[availability-seed] block ${blockNum}: failed at chunk ${cursor} (attempt ${failedAttempts}): ${detail} — retrying in ${PHASE_TASK_RETRY_DELAY_MS / 1000}s`);
      await requeueAt({ attempts: failedAttempts }, Date.now() + PHASE_TASK_RETRY_DELAY_MS);
      return { state: 'retry', cursor, attempts: failedAttempts, deferrals };
    }

    const line = `[availability-seed] block ${blockNum}: chunks ${cursor}-${outcome.nextCursor}/${outcome.totalChunks} `
      + `read=${outcome.chunksRead} readFailed=${outcome.chunkFailures} partial=${outcome.partialChunks} `
      + `values=${outcome.values} rejected=${outcome.rejectedValues} `
      + `groups=${outcome.groupsSent} groupFailed=${outcome.groupFailures} groupSkipped=${outcome.groupsSkipped} `
      + `applied=${outcome.applied} done=${outcome.done}`;
    if (outcome.chunkFailures > 0 || outcome.groupFailures > 0 || outcome.groupsSkipped > 0) {
      console.warn(`${line} firstFailure=${outcome.firstFailure || 'none'}`);
    } else {
      console.log(line);
    }
    if (!outcome.done) {
      await requeueAt({ cursor: outcome.nextCursor }, Date.now() + AVAILABILITY_SEED_CONTINUE_DELAY_MS);
      return { state: 'continued', attempts, deferrals, ...outcome };
    }
    return { state: 'done', attempts, deferrals, ...outcome };
  }

  // ログに載せる失敗の理由。1行・200字までにし、URL と secret らしい所は既存の伏せ方で伏せる。
  // 理由を文字にできない値を投げられても、ここからは投げない（失敗を数える側を止めないため）。
  availabilitySeedErrorText(error) {
    try {
      return this.observationErrorText(error).replace(/\s+/g, ' ').slice(0, 200);
    } catch (textError) {
      return 'unprintable error';
    }
  }

  // 1回ぶんの実行。仕事そのものの失敗（D1 の読み）は throw する（呼び手が attempts を数える）。
  // チャンクごと・グループごとの失敗は数えるだけで次へ進む（古い書き込みワーカー・古い ChatGameDO の
  // 404 もここに入る＝片側だけ新しくても落ちない）。
  async runAvailabilitySeedTask(task) {
    const blockNum = task?.blockNum;
    if (!Number.isSafeInteger(blockNum) || blockNum < 0) throw new Error('availability seed: invalid block');
    const cursor = Number.isSafeInteger(task?.cursor) && task.cursor >= 0 ? task.cursor : 0;
    const db = this.env.BITCOINU_DATA;
    if (!db) throw new Error('BITCOINU_DATA binding not found');

    // この実行の残り時間で待ちを見切る。読みと配りの work は「投げずに値を返す」関数にする
    // （名簿の D1 の読みだけは投げてよい＝呼び手が attempts を数える）。
    // 見切った fetch の結果は使わない（遅れて届いても捨てる）。時間切れの後に始まる分は fetch しない。
    const deadlineAt = Date.now() + AVAILABILITY_SEED_RUN_BUDGET_MS;
    const timedOut = { ok: false, reason: 'run budget exhausted' };
    const bounded = (work) => {
      const remainingMs = deadlineAt - Date.now();
      if (remainingMs <= 0) return Promise.resolve(timedOut);
      let timer = null;
      return Promise.race([
        Promise.resolve().then(work),
        new Promise((resolve) => { timer = setTimeout(() => resolve(timedOut), remainingMs); }),
      ]).finally(() => { if (timer !== null) clearTimeout(timer); });
    };

    // 1. 名簿（D1 の game_groups）から uid → グループを作る。uid は数字だけの文字列に限る。
    const groupRead = await bounded(async () => ({
      ok: true,
      rows: (await db.prepare(
        'SELECT group_id, members FROM game_groups WHERE block_num = ? ORDER BY group_id'
      ).bind(blockNum).all())?.results,
    }));
    if (groupRead === timedOut) throw new Error('game_groups read timed out');
    const uidToGroup = new Map();
    const rows = [];
    for (const row of (Array.isArray(groupRead.rows) ? groupRead.rows : [])) {
      const rawGroupId = row?.group_id;
      const groupId = typeof rawGroupId === 'number' ? rawGroupId
        : (typeof rawGroupId === 'string' && /^\d{1,15}$/.test(rawGroupId) ? Number(rawGroupId) : Number.NaN);
      if (!Number.isSafeInteger(groupId) || groupId < 0) continue;
      let members;
      try { members = JSON.parse(row.members); } catch (e) { members = null; }
      if (!Array.isArray(members)) continue;
      for (const member of members) {
        const rawUid = member?.uid;
        const uid = typeof rawUid === 'string' ? rawUid
          : (Number.isSafeInteger(rawUid) ? String(rawUid) : '');
        // 同じ uid が2つの組にあれば、先の組だけを使う（どちらへ渡すかを応答に決めさせない）。
        if (!/^\d{1,20}$/.test(uid) || uidToGroup.has(uid)) continue;
        uidToGroup.set(uid, groupId);
        rows.push({ uid });
      }
    }

    // 2. 書き込みワーカーごと・100人ごとのチャンク（順は決定的＝cursor が実行をまたいで同じ所を指す）。
    const chunks = this.buildShardWriteChunks(rows);
    const totalChunks = chunks.length;
    const nextCursor = Math.min(totalChunks, cursor + AVAILABILITY_SEED_CHUNKS_PER_RUN);
    const summary = {
      done: nextCursor >= totalChunks, nextCursor, totalChunks,
      chunksRead: 0, chunkFailures: 0, partialChunks: 0, values: 0, rejectedValues: 0,
      groupsSent: 0, groupFailures: 0, groupsSkipped: 0, applied: 0, firstFailure: null,
    };
    if (cursor >= totalChunks) return summary;

    // 3. cursor から決めた数だけ読む。応答は信じすぎない: 頼んだ uid（名簿）の、正の安全な整数だけを使う。
    //    部分的に読めた応答（success:false）も、読めた値は使う。
    const readOutcomes = await Promise.all(chunks.slice(cursor, nextCursor).map((chunk) => bounded(async () => {
      try {
        const uids = chunk.members.map((member) => member.uid);
        const response = await requireBinding(this.env, writeWorkerBinding(chunk.workerIndex)).fetch(
          internalJsonRequest('/read-play-schedule', { block_num: blockNum, uids }, this.env.API_SECRET)
        );
        if (response?.status !== 200) return { ok: false, reason: `read HTTP ${response?.status}` };
        const data = await response.json();
        const values = data?.values;
        if (values === null || typeof values !== 'object' || Array.isArray(values)) {
          return { ok: false, reason: 'read values is not an object' };
        }
        const picked = [];
        let rejected = 0;
        for (const uid of uids) {
          if (!Object.hasOwn(values, uid)) continue;
          const value = values[uid];
          if (Number.isSafeInteger(value) && value > 0) picked.push([uid, value]);
          else rejected++;
        }
        return { ok: true, partial: data.success !== true, picked, rejected };
      } catch (e) {
        return { ok: false, reason: `read ${this.availabilitySeedErrorText(e)}` };
      }
    })));
    const byGroup = new Map();
    for (const outcome of readOutcomes) {
      if (!outcome?.ok) {
        summary.chunkFailures++;
        if (!summary.firstFailure) summary.firstFailure = String(outcome?.reason || 'read failed');
        continue;
      }
      summary.chunksRead++;
      if (outcome.partial) summary.partialChunks++;
      summary.rejectedValues += outcome.rejected;
      for (const [uid, value] of outcome.picked) {
        const groupId = uidToGroup.get(uid);
        if (groupId === undefined) continue;
        if (!byGroup.has(groupId)) byGroup.set(groupId, {});
        byGroup.get(groupId)[uid] = value;
        summary.values++;
      }
    }

    // 4. 値が1つ以上あるグループだけへ渡す。窓の内か・本人の操作を上書きしないかは ChatGameDO が決める。
    const targets = [...byGroup.entries()].sort((a, b) => a[0] - b[0]);
    const sendable = targets.slice(0, AVAILABILITY_SEED_MAX_GROUP_CALLS_PER_RUN);
    summary.groupsSkipped = targets.length - sendable.length;
    const seedOutcomes = await this.batchChatDoCalls(sendable, ([groupId, availability]) => bounded(async () => {
      try {
        const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${groupId}`);
        const response = await this.env.CHAT_GAME_DO.get(doId).fetch(this.chatDoRequest('/seed-availability', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ availability }),
        }));
        if (response?.status !== 200) return { ok: false, reason: `seed HTTP ${response?.status}` };
        const body = await response.json();
        if (body?.success !== true) return { ok: false, reason: 'seed not accepted' };
        return { ok: true, applied: Number.isSafeInteger(body.applied) && body.applied > 0 ? body.applied : 0 };
      } catch (e) {
        return { ok: false, reason: `seed ${this.availabilitySeedErrorText(e)}` };
      }
    }));
    for (const outcome of seedOutcomes) {
      if (!outcome?.ok) {
        summary.groupFailures++;
        if (!summary.firstFailure) summary.firstFailure = String(outcome?.reason || 'seed failed');
        continue;
      }
      summary.groupsSent++;
      summary.applied += outcome.applied;
    }
    return summary;
  }

  // S3-003: reset-block の持ち越しぶんを、1リクエストにつき上限以下ずつ処理する。
  // 残りがあれば自分をもう一度登録する（空になったらキーごと削除）。
  async saveResetCleanupChunks(blockNum, chunks) {
    await this.clearResetCleanupChunks(blockNum);
    const pages = [];
    let page = [];
    for (const chunk of chunks) {
      const candidate = [...page, chunk];
      const bytes = new TextEncoder().encode(JSON.stringify(candidate)).byteLength;
      if (bytes > RESET_CLEANUP_STORAGE_PAGE_BYTES && page.length > 0) {
        pages.push(page);
        page = [chunk];
      } else {
        page = candidate;
      }
      const pageBytes = new TextEncoder().encode(JSON.stringify(page)).byteLength;
      if (pageBytes > RESET_CLEANUP_STORAGE_PAGE_BYTES) {
        throw new Error(`reset cleanup chunk exceeds storage page budget (${pageBytes}/${RESET_CLEANUP_STORAGE_PAGE_BYTES})`);
      }
    }
    if (page.length > 0) pages.push(page);
    for (let i = 0; i < pages.length; i++) {
      await this.storage.put(`reset_cleanup_page_block${blockNum}:${i}`, pages[i]);
    }
    const manifest = {
      version: 2,
      pageCount: pages.length,
      totalChunks: chunks.length,
      totalUsers: chunks.reduce((sum, chunk) => sum + Number(chunk.users || 0), 0),
    };
    await this.storage.put(`reset_cleanup_block${blockNum}`, manifest);
    return manifest;
  }

  async loadResetCleanupChunks(blockNum) {
    const key = `reset_cleanup_block${blockNum}`;
    const saved = await this.storage.get(key);
    // 移行前のT4実装が一時的に保存した配列も読み戻せる。
    if (Array.isArray(saved)) return saved;
    // さらに古い workerIndex → uid[] 形式も、共通チャンク規則へ移して再開する。
    if (saved && typeof saved === 'object' && saved.version !== 2) {
      const uids = [...new Set(Object.values(saved).flat().filter(Boolean).map(String))];
      return this.buildShardWriteChunks(uids.map((uid) => ({ uid })));
    }
    if (!saved || saved.version !== 2) return [];
    const pageCount = Number(saved.pageCount);
    const totalChunks = Number(saved.totalChunks);
    if (!Number.isSafeInteger(pageCount) || pageCount < 0
        || !Number.isSafeInteger(totalChunks) || totalChunks < 0) {
      throw new Error(`reset cleanup block ${blockNum}: invalid storage manifest`);
    }
    const chunks = [];
    for (let i = 0; i < pageCount; i++) {
      const page = await this.storage.get(`reset_cleanup_page_block${blockNum}:${i}`);
      if (!Array.isArray(page)) throw new Error(`reset cleanup block ${blockNum}: storage page ${i} missing`);
      chunks.push(...page);
    }
    if (chunks.length !== totalChunks) {
      throw new Error(`reset cleanup block ${blockNum}: chunk count mismatch (${chunks.length}/${totalChunks})`);
    }
    return chunks;
  }

  async clearResetCleanupChunks(blockNum) {
    const key = `reset_cleanup_block${blockNum}`;
    const saved = await this.storage.get(key);
    const pageCount = saved?.version === 2 ? Number(saved.pageCount) : 0;
    if (Number.isSafeInteger(pageCount) && pageCount > 0) {
      for (let i = 0; i < pageCount; i++) {
        await this.storage.delete(`reset_cleanup_page_block${blockNum}:${i}`);
      }
    }
    await this.storage.delete(key);
  }

  async drainShardCleanup(blockNum) {
    const cursorKey = `reset_cleanup_cursor_block${blockNum}`;
    const chunks = await this.loadResetCleanupChunks(blockNum);
    if (!Array.isArray(chunks) || chunks.length === 0) {
      await this.clearResetCleanupChunks(blockNum);
      await this.storage.delete(cursorKey);
      await this.storage.delete(`${cursorKey}:deferred`);
      return { done: true, cleaned: 0 };
    }
    const stats = { totalWritten: 0, totalErrors: 0 };
    const processed = await this.sendShardWriteChunks(
      '/clean-game-win-blocks', blockNum, chunks, { cursorKey, stats },
    );
    await this.clearResetCleanupChunks(blockNum);
    const result = { done: true, cleaned: processed, errors: stats.totalErrors, remaining: 0 };
    console.log(`[reset] shard cleanup block ${blockNum}: ${processed} processed, ${stats.totalErrors} errors, 0 chunks remaining`);
    return result;
  }

  // 見張りタスクを登録（重複登録なし）＋アラーム設定
  async enqueueGroupingWatchdog(blockNum, delayMs) {
    let stage = 'read_queue';
    try {
      const taskQueue = await this.storage.get('phase_task_queue') || [];
      const executeAt = Date.now() + delayMs;
      const existing = taskQueue.find(t => t.type === 'grouping_watchdog' && t.blockNum === blockNum);
      let queueAction = 'unchanged';
      if (!existing) {
        stage = 'write_queue';
        queueAction = 'inserted';
        taskQueue.push({ type: 'grouping_watchdog', blockNum, executeAt });
        taskQueue.sort((a, b) => a.executeAt - b.executeAt);
        await this.storage.put('phase_task_queue', taskQueue);
      } else if (executeAt < existing.executeAt) {
        // S3-007: 既存の見張り予定より早い要求は**前倒しする**。
        // 旧実装は「既にあれば何もしない」で、クレーム時に張られる
        // リース満了ベースの予定（約10.5分後）が resumable 再開の即時要求（1秒後）を
        // 飲み込んでいた。見張り本体は冪等（リースが生きていれば再予約するだけ）なので
        // 前倒しは安全。
        stage = 'write_queue';
        queueAction = 'moved_earlier';
        existing.executeAt = executeAt;
        taskQueue.sort((a, b) => a.executeAt - b.executeAt);
        await this.storage.put('phase_task_queue', taskQueue);
      }
      stage = 'set_alarm';
      const { alarmAt } = await this.armEarliestQueuedTask();
      this.deferGroupObservation(blockNum, {
        watchdog: {
          enqueue: this.observationResult('succeeded', {
            queueAction, requestedExecuteAt: executeAt, alarmAt,
          }),
        },
      });
      return { queued: true, queueAction, executeAt, alarmAt };
    } catch (error) {
      this.deferGroupObservation(blockNum, {
        watchdog: { enqueue: this.observationFailure(error, { stage }) },
      });
      throw error;
    }
  }

  groupingDependencyCause(message) {
    const text = String(message || '');
    if (text.startsWith('MAJOR_LANG_PREV_NOT_READY:')) return 'previous_block_not_ready';
    if (/^grouping integrity \(block \d+\): .*on-chain anchor is not verifiable /.test(text)
        && /resultHashes\(\d+\)=unset/.test(text)) {
      return 'previous_block_anchor_pending';
    }
    return null;
  }

  // 本番切替前に通常failedへ落ちた依存待ちを、group-status pollから安全に蘇生する。
  // progressが実在し、かつ上の厳密な2分類に一致するときだけ状態を「再開可能」に変える。
  async requeueLegacyGroupingDependency(blockNum) {
    const key = `grouping_block${blockNum}_progress`;
    const progress = await this.storage.get(key);
    const cause = progress?.status === 'failed'
      ? this.groupingDependencyCause(progress.error) : null;
    if (!cause) return { queued: false, reason: 'not_recoverable_dependency' };

    const now = Date.now();
    const nextRetryAt = Number(progress.dependencyNextRetryAt || 0);
    if (nextRetryAt > now) {
      return { queued: false, reason: 'already_scheduled', nextRetryAt };
    }

    progress.resumable = true;
    progress.timelineUnverified = true;
    progress.timelineCause = cause;
    progress.dependencyNextRetryAt = now + GROUPING_DEPENDENCY_RETRY_MS;
    await this.storage.put(key, progress);
    await this.enqueueGroupingWatchdog(blockNum, 1000);
    console.warn(`[grouping] revived legacy dependency wait for block ${blockNum} (${cause})`);
    return { queued: true, cause, nextRetryAt: progress.dependencyNextRetryAt };
  }

  // 見張り本体。リースがまだ有効なら失効後の再チェックを予約するだけ。
  // 'started'のまま失効していたらstartGroupingを再実行（乗っ取り側で全判定）。
  async checkGroupingWatchdog(blockNum) {
    const progress = await this.storage.get(`grouping_block${blockNum}_progress`);
    if (progress && progress.status === 'completed') {
      // チャット初期化の安全網: グループ分け完了済みなのに init_chat_games タスクが消えていたら
      //（登録putの失敗・キュー破損等）再登録する。formedが残っている＝チャット初期化未了。
      let initNetObservation = this.observationResult('succeeded', {
        action: 'completed_init_net_check',
      });
      try {
        const db = this.env.BITCOINU_DATA;
        if (db) {
          const row = await db.prepare(
            `SELECT COUNT(*) AS cnt FROM game_groups WHERE block_num = ? AND status = 'formed'`
          ).bind(blockNum).first();
          if (row && row.cnt > 0) {
            const q = await this.storage.get('phase_task_queue') || [];
            const pending = q.some(t => t.type === 'init_chat_games' && t.blockNum === blockNum);
            const active = await this.storage.get('phase_task_active');
            const running = active && active.type === 'init_chat_games' && active.blockNum === blockNum;
            const parked = await this.storage.get(`phase_task_parked:${blockNum}:init_chat_games`);
            if (!pending && !running && !parked) {
              console.warn(`[grouping] watchdog: block ${blockNum} completed but ${row.cnt} groups still 'formed' with no init task — re-enqueueing chat init`);
              await this.enqueueInitChatGames(blockNum, Date.now());
            }
          }
        }
      } catch (e) {
        initNetObservation = this.observationFailure(e, {
          action: 'completed_init_net_check',
        });
        console.error(`[grouping] watchdog init-net failed for block ${blockNum}:`, e.message);
      }
      this.deferGroupObservation(blockNum, {
        operationalObservations: { watchdogInitNet: initNetObservation },
        watchdog: {
          run: this.observationResult('succeeded', {
            action: 'completed_init_net_checked',
            initNetState: initNetObservation.state,
          }),
        },
      });
      return;
    }
    // S3-007: 「1呼び出しの予算切れ」で failed になったものは続きがあるだけ。ここで再駆動する。
    // （通常の failed / parked / リセット済みは従来どおり見張り終了）
    // S3-008: 照合待ち（timelineUnverified）も resumable として再駆動する。
    // 30分間隔なので RPC を叩き続けることはない。
    if (progress && progress.status === 'failed' && progress.resumable) {
      console.warn(`[grouping] watchdog: resuming block ${blockNum} from cursor (attempt ${progress.resumeAttempts || 1})`);
      const res = await this.startGrouping(blockNum);
      console.log(`[grouping] watchdog resume for block ${blockNum}: success=${res?.success} resumable=${!!res?.resumable} error=${res?.error || 'none'}`);
      this.deferGroupObservation(blockNum, {
        watchdog: { run: this.observationResult(res?.success ? 'succeeded' : 'failed', {
          action: 'resumed', resumable: !!res?.resumable,
          error: res?.error ? this.observationErrorText(res.error) : null,
        }) },
      });
      return;
    }
    if (!progress || progress.status !== 'started') {
      this.deferGroupObservation(blockNum, {
        watchdog: { run: this.observationResult('succeeded', { action: 'stopped', progressStatus: progress?.status || 'missing' }) },
      });
      return; // failed/parked/リセット済み → 見張り終了
    }
    const now = Date.now();
    if (Number(progress.leaseUntil || 0) > now) {
      await this.enqueueGroupingWatchdog(blockNum, (Number(progress.leaseUntil) - now) + 30000);
      this.deferGroupObservation(blockNum, {
        watchdog: { run: this.observationResult('succeeded', { action: 'lease_active_rescheduled', leaseUntil: Number(progress.leaseUntil) }) },
      });
      return;
    }
    console.warn(`[grouping] watchdog: lease expired for block ${blockNum} (phase=${progress.phase}, attempts=${progress.attempts || 1}) — restarting grouping`);
    const result = await this.startGrouping(blockNum);
    console.log(`[grouping] watchdog restart for block ${blockNum}: success=${result?.success} error=${result?.error || 'none'} resumed=${!!result?.resumed}`);
    this.deferGroupObservation(blockNum, {
      watchdog: { run: this.observationResult(result?.success ? 'succeeded' : 'failed', {
        action: 'lease_expired_restart', resumed: !!result?.resumed,
        error: result?.error ? this.observationErrorText(result.error) : null,
      }) },
    });
  }

  // 進捗書き込み＋リース延長（実行中の各フェーズ境界で呼ぶ）
  async renewGroupingLease(blockNum, progressData) {
    progressData.leaseUntil = Date.now() + GROUPING_LEASE_MS;
    await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
  }

  // initChatGames の success=false は「formed がもう無い」という健全な冪等再入でも返る。
  // 部分失敗は errors に加え roster sha 欠落そのものを数える。ChatGameDO が 200 を返しても
  // 公開 roster の書込みに失敗した場合、schedule 側と同じ事実をここでも観測・再投入する。
  async completeGroupingAfterChatInit(blockNum, progressData, initResult, patch = {}) {
    if (initResult?.reason === 'groups_incomplete') {
      const error = new Error(`Block ${blockNum} chat initialization blocked: groups_incomplete`);
      error.resumable = true;
      throw error;
    }
    const reportedErrors = Number(initResult?.errors) > 0 ? Number(initResult.errors) : 0;
    const rosterShaMissingCount = Number(initResult?.rosterShaMissingCount) > 0
      ? Number(initResult.rosterShaMissingCount) : 0;
    const chatInitErrorCount = reportedErrors > 0 ? reportedErrors : rosterShaMissingCount;
    Object.assign(progressData, patch);
    progressData.status = 'completed';
    progressData.phase = 'completed';
    progressData.completedAt = new Date().toISOString();
    progressData.chatInitResult = initResult;
    progressData.chatInitErrorCount = chatInitErrorCount;
    progressData.rosterShaMissingCount = rosterShaMissingCount;
    progressData.timelineUnverified = false;
    await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
    // 全ての組分け完了で、組分けが所有する待ちだけを解除する。
    await this.clearGroupingTimelineWait(blockNum);

    // 依存待ちはgrouping完了までの保護だけを担う。記録を残したまま閉じることで、
    // 既に積まれた5分reconcile taskにも「開始後は再送しない」と伝える。
    const shieldKey = `grouping_dependency_shield_block${blockNum}`;
    const shield = await this.storage.get(shieldKey);
    if (shield && shield.closed !== true) {
      await this.storage.put(shieldKey, {
        ...shield,
        pending: false,
        closed: true,
        closedAt: Date.now(),
        closeReason: 'grouping_completed',
      });
    }

    if (chatInitErrorCount > 0) {
      try {
        await this.enqueueInitChatGames(blockNum, Date.now());
      } catch (error) {
        // completed を先に永続化してあるので、即時投入自体が失敗しても watchdog の
        // formed 残留検査が後から再投入できる。
        console.error(`[grouping] block ${blockNum}: immediate chat init re-enqueue failed:`, error.message);
      }
    }
    return chatInitErrorCount;
  }

  // グループ分け処理開始
  async startGrouping(blockNum, maxPlayersOverride, options = {}) {
    console.log(`Starting grouping for block ${blockNum}`);

    try {
      // 重複実行チェック＋アトミック・クレーム。
      // get→（同期判定）→put の間に外部I/O awaitを挟まないので、この区間はDO入力ゲートにより
      // アトミック＝並行2重 /start-grouping の一方が必ず 'started' を先に置き、他方は弾かれる。
      // （以前は get と 'started' put の間にD1クエリ(外部I/O)があり、両者が guard を通過して
      //   グループ重複＋フェーズタスク二重登録を招くTOCTOUだった。）
      // A6: 'started'はリース期限内のみ有効。期限切れ（またはリース導入前の旧'started'）は
      // 前回実行の途中死とみなして乗っ取る。乗っ取り回数の上限超はpark（手動復旧待ち）。
      const now = Date.now();
      const storedProgress = await this.storage.get(`grouping_block${blockNum}_progress`);
      const completedAutoCheckpoint = storedProgress?.status === 'completed'
        ? await this.storage.get(`auto_distribute_block${blockNum}`) : null;
      // 完了札だけが先に保存された途中死も、未完の自動配布 checkpoint があれば再取得する。
      // D1 の全行はクレーム後に照合し、擬似組でなければ fail closed にする。
      const existing = completedAutoCheckpoint?.selectionHash
          && completedAutoCheckpoint.stage !== 'done'
        ? { ...storedProgress, status: 'failed', resumable: true }
        : storedProgress;
      const existingAdminTxWait = existing?.waitReason === 'admin_freeze'
        || existing?.waitReason === 'admin_tx_pending';
      // timeline no-game の cleanup は公開処理より前に live D1 / ChatGameDO を終端する。
      // その途中死だけは既存の専用 checkpoint から再開する必要がある。一方、cleanup 完了後の
      // R2/RPC 等の恒久失敗までこの checkpoint へ閉じ込めると、通常の失敗回数・park・警報を
      // 永久に迂回するため、storage の cleanup record が pending の場合だけを許す。
      let timelineCleanupPending = false;
      if (existing?.timelineNoGameFinalization?.reason === 'timeline_unverified'
          && !existingAdminTxWait) {
        const cleanup = await this.storage.get(this.timelineNoGameCleanupKey(blockNum));
        timelineCleanupPending = cleanup?.status === 'pending';
      }
      // Q50 の cleanup 途中死、または cleanup 後の管理tx待ちは、D1 を通常 grouping へ
      // 戻さず保存済みの safe-chain finality から専用確定処理だけを再開する。
      // その他の公開失敗は下の通常カウンタへ流し、恒久障害なら20回で park する。
      if (existing?.timelineNoGameFinalization
          && (existing.status !== 'parked' || options.recoverPark === true)
          && (existingAdminTxWait || timelineCleanupPending)) {
        // finalizeNoGameBlock は成功時に progressData 上のcheckpointを削除するため、
        // 同じ参照の existing から成功後に読まず、呼出し前にmetaを退避する。
        const finalizationMeta = existing.timelineNoGameFinalization;
        try {
          // R29-C-3b-04: recover_park / 管理tx待ちのどちらから戻る場合も、checkpoint を
          // 書いた後に前ブロックの公開2鍵が差し替わっていないことを、chain marker で再確認する。
          // 読めない／不一致の間は parked 状態も変えず、no-game 確定を再開しない。
          await verifyPreviousBlockArtifacts({
            blockNum,
            readText: async (key) => {
              const text = await this.getR2Text(key);
              if (text != null && isCanonicalJsonRequiredKey(key)) parseCanonicalJson(text, key);
              return text;
            },
            getResultHash: (n) => this.readResultHashOnChain(n),
            anchorRequired: Boolean(this.env.HASH_STORAGE_CONTRACT_ADDRESS),
          });
          if (existing.status === 'parked') {
            existing.status = 'failed';
            existing.resumable = true;
            existing.resumeAttempts = 0;
            existing.adminTxWaitDeadline = null;
            delete existing.waitReason;
            delete existing.waitUntil;
            delete existing.waitDetail;
            existing.error = null;
            delete existing.parkedAt;
            existing.recoveredFromPark = true;
            existing.parkRecoveryCount = Number(existing.parkRecoveryCount || 0) + 1;
            existing.recoveredFromParkAt = now;
            await this.storage.put(`grouping_block${blockNum}_progress`, existing);
          }
          const res = await this.finalizeNoGameBlock(blockNum, finalizationMeta);
          const wait = adminTxWaitOf(res);
          if (wait) {
            return {
              success: false, blockNum, noGame: true,
              reason: finalizationMeta.reason || null,
              resumed: true, resumable: res.resumable !== false,
              parked: res.parked === true,
              waitReason: wait.waitReason, retryInMs: wait.retryInMs,
            };
          }
          await this.clearTimelineWait(blockNum);
          return {
            success: true, blockNum, noGame: true,
            reason: finalizationMeta.reason || null,
            resumed: true, ...res,
          };
        } catch (error) {
          // explicit recover_park でも前ブロック照合が通らない限り parked を解除しない。
          // 回復不能な差し替えを通常の再試行回数へ流して状態だけ変えることも避ける。
          if (existing.status === 'parked' && error?.previousBlockIntegrity) {
            return {
              success: false, blockNum, error: error.message, timelineUnverified: true,
              parked: true, resumable: true,
            };
          }
          if (timelineCleanupPending) {
            existing.status = 'failed';
            existing.phase = 'no_game_finalizing';
            existing.resumable = true;
            existing.timelineUnverified = true;
            existing.error = `no-game finalization failed: ${error.message}`;
            await this.storage.put(`grouping_block${blockNum}_progress`, existing);
            try { await this.enqueueGroupingWatchdog(blockNum, GameMasterDO.TIMELINE_RETRY_MS); }
            catch (enqueueError) {
              console.error(`[evidence] no-game retry enqueue failed for block ${blockNum}:`, enqueueError.message);
            }
            return {
              success: false, blockNum, error: existing.error, timelineUnverified: true,
              retryInMs: GameMasterDO.TIMELINE_RETRY_MS,
            };
          }
          // R2/RPC の一時失敗でも、専用 checkpoint と直前の管理tx待ちを保持する。
          // 成功終端だけが finalizeNoGameBlock 内で checkpoint を削除する。
          existing.status = 'failed';
          existing.phase = 'no_game_finalizing';
          existing.resumable = true;
          existing.timelineUnverified = true;
          existing.error = `no-game finalization failed: ${error.message}`;
          error.resumable = true;
          return this.recordGroupingResumableFailure(
            blockNum, existing, error, GameMasterDO.TIMELINE_RETRY_MS,
          );
        }
      }
      let attempts = 1;
      let recoveredFromPark = false;
      if (existing && existing.status !== 'failed') {
        if (existing.status === 'parked' && options.recoverPark === true) {
          recoveredFromPark = true;
          console.warn(`[grouping] explicit park recovery requested for block ${blockNum}`);
        } else {
          const leaseExpired = existing.status === 'started' && Number(existing.leaseUntil || 0) <= now;
          if (!leaseExpired) {
            return {
              success: false,
              blockNum,
              error: `Grouping already ${existing.status} for this block`,
              totalGroups: existing.totalGroups
            };
          }
          attempts = (existing.attempts || 1) + 1;
          if (attempts > GROUPING_MAX_ATTEMPTS) {
            console.error(`[grouping] block ${blockNum} parked after ${attempts - 1} takeover attempts (repeated mid-execution death). Recover with POST /start-grouping {"block_num":${blockNum},"recover_park":true}.`);
            await this.storage.put(`grouping_block${blockNum}_progress`, {
              ...existing,
              status: 'parked',
              parkedAt: now,
              error: `grouping parked after ${attempts - 1} takeover attempts`
            });
            return { success: false, blockNum, error: 'grouping parked (max takeover attempts exceeded)' };
          }
          console.warn(`[grouping] lease expired for block ${blockNum} (phase=${existing.phase}) — taking over (attempt ${attempts})`);
        }
      }

      // 進行状況初期化＝即座にクレーム（上の get からここまで外部I/O awaitを挟まない＝アトミック）
      // S3-007: resumable な予算切れからの再入では自動再開回数を引き継ぐ（park 判定のため。
      // 引き継がないとカウンタが毎回リセットされ、上限に達することが無くなる）。
      const progressData = {
        blockNum,
        status: 'started',
        attempts,
        resumeAttempts: recoveredFromPark ? 0 : (existing?.resumeAttempts || 0),
        adminTxWaitDeadline: recoveredFromPark ? null : (existing?.adminTxWaitDeadline || null),
        recoveredFromPark,
        parkRecoveryCount: Number(existing?.parkRecoveryCount || 0) + (recoveredFromPark ? 1 : 0),
        recoveredFromParkAt: recoveredFromPark ? now : (existing?.recoveredFromParkAt || null),
        // P-2026-0815: 選出データ照合（データファイル走査）の再開カーソル。
        // 予算切れの resumable 再入でのみ引き継ぐ。それ以外（新規／リース失効の乗っ取り）は
        // 0 に戻して最初から照合し直す＝途中まで検査済みという主張を持ち越さない。
        selectionVerifyCursor: !recoveredFromPark && existing?.status === 'failed' && existing?.resumable
          ? (existing.selectionVerifyCursor || 0) : 0,
        leaseUntil: now + GROUPING_LEASE_MS,
        phase: 'reading_selection',
        startTime: new Date().toISOString(),
        completedAt: null,
        error: null,
        totalPlayers: 0,
        totalGroups: 0
      };
      await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
      this.deferGroupObservation(blockNum, {
        groupingLease: this.observationResult('succeeded', {
          status: 'started', attempts, leaseUntil: progressData.leaseUntil,
          phase: progressData.phase, recoveredFromPark,
        }),
      });

      // A6: 見張りタスク（リース失効後の途中死検知→自己再実行）。失敗しても本処理は続行
      // （その場合の復旧は次の /start-grouping 呼び出し時の乗っ取りに委ねる）。
      try {
        await this.enqueueGroupingWatchdog(blockNum, GROUPING_LEASE_MS + 30000);
      } catch (e) {
        console.error(`[grouping] watchdog enqueue failed for block ${blockNum}:`, e.message);
      }

      // S3-003（2026-07-29）: Service Binding 化でシャード書き込みの1回あたり予算が
      // 500 → 30 チャンクになったため、最大構成では「予算切れ → 自動再開」を何度も繰り返す。
      // そのたびに選出検証・グループ再形成・R2 公開まで丸ごとやり直すのは無駄なので、
      // **resumable な失敗からの再入で、かつ D1 の全組が書き終わっている**場合は
      // 後段（シャード書き込み → チャット初期化）だけを再実行する。
      // 書き込みは冪等 upsert ＋ カーソル再開なので安全（既存の乗っ取り resume と同じ経路）。
      const dbForResume = this.env.BITCOINU_DATA;
      const autoCheckpointForResume = await this.storage.get(`auto_distribute_block${blockNum}`);
      const autoStatusesForResume = dbForResume && autoCheckpointForResume?.selectionHash
        ? (await dbForResume.prepare(
          'SELECT status, COUNT(*) AS cnt FROM game_groups WHERE block_num = ? GROUP BY status'
        ).bind(blockNum).all()).results : null;
      const autoFactsForResume = Array.isArray(autoStatusesForResume)
        && autoStatusesForResume.length > 0
        && autoStatusesForResume.every(row => row.status === 'auto_distributed');
      if (!recoveredFromPark && existing?.resumable && !autoFactsForResume
          && existing?.phase !== 'auto_distributing' && dbForResume) {
        if (['writing_to_shard_dbs', 'initializing_chat_games'].includes(existing.phase)) {
          progressData.phase = 'writing_to_shard_dbs';
          await this.renewGroupingLease(blockNum, progressData);
          const { results: rows } = await dbForResume.prepare(
            'SELECT group_id FROM game_groups WHERE block_num = ?'
          ).bind(blockNum).all();
          const d1Completeness = await this.checkGroupingD1Completeness(blockNum, rows);
          const totalGroups = d1Completeness.expectedGroups;
          if (d1Completeness.complete) {
            console.warn(`[grouping] resumable re-entry for block ${blockNum}: all ${totalGroups} groups in D1 — resuming shard writes from cursor`);
            progressData.phase = 'writing_to_shard_dbs';
            progressData.totalGroups = totalGroups;
            await this.renewGroupingLease(blockNum, progressData);

            const writeResult = await this.writeGameGroupsToShards(blockNum);
            progressData.shardWriteLastCallResult = writeResult;

            progressData.phase = 'initializing_chat_games';
            await this.renewGroupingLease(blockNum, progressData);
            const initResult = await this.initChatGames(blockNum);

            await this.completeGroupingAfterChatInit(blockNum, progressData, initResult, {
              resumed: true,
              resumable: false,
            });
            return { success: true, blockNum, resumed: true, totalGroups, chatInitResult: initResult,
              shardWriteLastCallResult: writeResult };
          }
          if (existing.phase === 'initializing_chat_games') {
            const { results: statuses } = await dbForResume.prepare(
              'SELECT status, COUNT(*) AS cnt FROM game_groups WHERE block_num = ? GROUP BY status'
            ).bind(blockNum).all();
            if (Array.isArray(statuses) && statuses.every(row => row.status === 'formed')) {
              console.warn(`[grouping] block ${blockNum}: incomplete D1 before chat initialization — revalidating selection and rebuilding groups`);
            } else {
              const error = new Error(`Block ${blockNum} chat initialization blocked: groups_incomplete`);
              error.resumable = true;
              progressData.status = 'failed';
              progressData.error = error.message;
              return this.recordGroupingResumableFailure(blockNum, progressData, error);
            }
          }
          console.warn(`[grouping] block ${blockNum}: D1 resume ids incomplete (rows=${rows?.length ?? 0}, expected=${totalGroups}); revalidating selection and rebuilding groups`);
        }
      }

      // D1にも進行済みデータがないか確認（progressデータが壊れた場合の安全弁）。
      // クレーム後に実施し、見つかれば failed に戻して再試行可能にする。
      const db = this.env.BITCOINU_DATA;
      if (db) {
        const { results: d1Check } = await db.prepare(
          "SELECT COUNT(*) as cnt FROM game_groups WHERE block_num = ? AND status != 'formed'"
        ).bind(blockNum).all();
        if (d1Check && d1Check[0]?.cnt > 0) {
          const statuses = autoStatusesForResume || (await db.prepare(
            'SELECT status, COUNT(*) AS cnt FROM game_groups WHERE block_num = ? GROUP BY status'
          ).bind(blockNum).all()).results;
          // 擬似組は完了印の対象ではない。D1 の全行と選出 hash 付き checkpoint
          // という永続事実で再開を決め、上書きされ得る progress の phase は見ない。
          const autoResume = Array.isArray(statuses) && statuses.length > 0
            && statuses.every(row => row.status === 'auto_distributed')
            && typeof autoCheckpointForResume?.selectionHash === 'string'
            && autoCheckpointForResume.selectionHash.length > 0;
          if (autoResume) {
            console.warn(`[grouping] auto-distribute resume block ${blockNum}: keeping checkpoint and revalidating selection`);
            progressData.autoCheckpointResume = true;
            await this.renewGroupingLease(blockNum, progressData);
          } else {
          if (statuses?.some(row => row.status === 'auto_distributed')) {
            progressData.status = 'failed';
            progressData.error = `Block ${blockNum} has auto-distributed D1 rows without a complete selection checkpoint`;
            await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
            return { success: false, blockNum, error: progressData.error };
          }
          // A6: 乗っ取り再実行では「前回実行がD1書き込み後（チャット初期化〜スケジュール登録の
          // 間）で死んだ」状態があり得る。formed/waitingのみ＝グループ分け成果物は完成済みで、
          // チャット初期化またはフェーズタスク登録だけが未了の可能性が残る → 後段だけを再実行
          // して完了させる（/initは初期化済みなら409＝状態を壊さない・スケジュールは置き換え登録）。
          // waitingより先（chatting等）へ進んでいたら、グループ分けはとうに完了 → progressを
          // completedへ自己修復するだけ。初回実行（attempts=1）での既存進行データは従来どおり異常。
          if (attempts > 1 || recoveredFromPark) {
            const stat = statuses;
            const totalGroups = (stat || []).reduce((s, r) => s + (r.cnt || 0), 0);
            const { results: ids } = await db.prepare(
              'SELECT group_id FROM game_groups WHERE block_num = ?'
            ).bind(blockNum).all();
            progressData.phase = 'writing_to_shard_dbs';
            await this.renewGroupingLease(blockNum, progressData);
            const d1Completeness = await this.checkGroupingD1Completeness(blockNum, ids);
            if (!d1Completeness.complete || totalGroups !== d1Completeness.expectedGroups) {
              progressData.status = 'failed';
              progressData.error = `Block ${blockNum} takeover found incomplete D1 groups (rows=${totalGroups}, expected=${d1Completeness.expectedGroups ?? 'none'})`;
              await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
              return { success: false, blockNum, error: progressData.error };
            }
            const onlyFormedWaiting = (stat || []).every(r => r.status === 'formed' || r.status === 'waiting');
            if (onlyFormedWaiting) {
              console.warn(`[grouping] takeover resume for block ${blockNum}: groups already in D1 (${JSON.stringify(stat)}) — re-running shard writes + chat init + phase scheduling`);
              // C1是正: 前回実行が「D1書き込み後〜シャード書き込み中」で死んだ場合、win_blocksの
              // グループ通知が欠けたままだった（従来resumeはチャット初期化のみ再実行＝無音欠落）。
              // 書き込みは冪等upsert＋カーソル再開なのでresumeでも常に再実行して完全性を保証する。
              progressData.phase = 'writing_to_shard_dbs';
              progressData.totalGroups = totalGroups;
              await this.renewGroupingLease(blockNum, progressData);

              const writeResult = await this.writeGameGroupsToShards(blockNum);
              progressData.shardWriteLastCallResult = writeResult;

              progressData.phase = 'initializing_chat_games';
              await this.renewGroupingLease(blockNum, progressData);

              const initResult = await this.initChatGames(blockNum);

              await this.completeGroupingAfterChatInit(blockNum, progressData, initResult, {
                resumed: true,
              });
              return { success: true, blockNum, resumed: true, totalGroups, chatInitResult: initResult,
                shardWriteLastCallResult: writeResult };
            }
            console.warn(`[grouping] takeover for block ${blockNum}: groups already progressed beyond waiting (${JSON.stringify(stat)}) — self-healing progress to completed`);
            progressData.status = 'completed';
            progressData.phase = 'completed';
            progressData.completedAt = new Date().toISOString();
            progressData.resumed = true;
            progressData.totalGroups = totalGroups;
            progressData.note = 'groups already progressed beyond waiting at takeover';
            progressData.timelineUnverified = false;
            await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
            await this.clearGroupingTimelineWait(blockNum);
            return { success: true, blockNum, resumed: true, alreadyProgressed: true, totalGroups };
          }
          progressData.status = 'failed';
          progressData.error = `Block ${blockNum} already has ${d1Check[0].cnt} groups in progress/completed in D1`;
          await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
          return {
            success: false,
            blockNum,
            error: progressData.error
          };
          }
        }
      }

      // 1. R2からgame_selection.jsonを読み込み
      const selectionData = await this.getR2Object(`entries/block${blockNum}/game_selection.json`);
      if (!selectionData) {
        progressData.status = 'failed';
        progressData.error = 'game_selection.json not found';
        await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
        return { success: false, blockNum, error: 'game_selection.json not found' };
      }

      // 擬似組と checkpoint を残したまま選出だけが3人以上に変わった場合、通常組分けに
      // 落として D1 を上書きしてはいけない。RANDAO・選出照合より前に永続事実を照らす。
      if (progressData.autoCheckpointResume) {
        const selected = selectionData.players;
        const selectedHash = Array.isArray(selected)
          ? await this.sha256Hex(JSON.stringify(selected)) : null;
        if (![1, 2].includes(selected?.length)
            || selectedHash !== autoCheckpointForResume.selectionHash) {
          const error = new Error(`Block ${blockNum} auto-distribute checkpoint selection changed or invalid`);
          await sendAlertAndRecord(this.env, this.storage, {
            kind: 'auto_distribute_selection_mismatch',
            subject: `[COINU][CRITICAL] 自動配布の選出と checkpoint が不一致: block ${blockNum}`,
            body: `blockNum=${blockNum}\nreason=auto_distribute_selection_mismatch\n${error.message}\nGET /calc-status?block=${blockNum}`,
          }).catch((alertError) => console.error('[auto-distribute] selection mismatch alert failed:', alertError));
          throw error;
        }
      }

      // 決定3: RANDAO target 到達直後に、消える前の blockhash を Evidence へ保存する。
      // 保存値は Ethereum block番号→blockhash という事実だけなので、選出データの完全性検査より
      // 前に呼んでも汚染面はない。大規模blockの再開可能な選出検査に51分以上かかっても失わない。
      let randaoAnchor;
      try {
        randaoAnchor = await this.anchorRandaoTargetOnChain(blockNum, selectionData);
      } catch (error) {
        if (progressData.autoCheckpointResume) error.resumable = true;
        throw error;
      }
      progressData.randaoAnchor = randaoAnchor;
      if (randaoAnchor.required && !randaoAnchor.anchored) {
        const err = new Error(`RANDAO blockhash anchor not ready: ${randaoAnchor.reason}`);
        err.resumable = randaoAnchor.reason === 'target_not_reached' || randaoAnchor.pending === true;
        await this.renewGroupingLease(blockNum, progressData);
        throw err;
      }

      // S3-001: 選出データの完全性検査（fail-closed）。
      // R2 は運営が掌握しているため、lottery が書いた players が grouping までに
      // 差し替えられていないことを GameMasterDO 自身が公開値から再計算して確かめる。
      // N（応募総数）は申告値ではなく 100 info ファイルの実件数を権威にする。
      // 0名ブロック判定より前に置く（players を空に消して報酬をゼロ確定させる経路も塞ぐ）。
      // P-2026-0815（2026-08-07）: 当選 index だけでなく**当選者行そのもの**を
      // info ファイル＋entries データファイルから再構築して全フィールド照合する
      //（localIndex / file / data）。当選 index を正規のまま残して uid・depositPoints を
      // すり替える経路が規則版数1では素通りしていた。
      // データファイル走査は 1 呼び出しの予算を超えうるので、超えたら
      // カーソルを進捗に保存して S3-007 の「resumable → 1秒後に自動再開」経路へ降りる。
      progressData.phase = 'verifying_selection';
      await this.renewGroupingLease(blockNum, progressData);
      try {
        const { total: committedTotal, infos } = await this.readCommittedEntryInfos(blockNum);
        // 本番は引数を渡さず 2100 固定。小規模の境界試験だけ関数引数で上書きする。
        const maxPlayers = this.getMaxPlayers(maxPlayersOverride);
        let lastRenew = Date.now();
        const sel = await verifySelectionIntegrity({
          blockNum, selectionData, committedTotal, maxPlayers, infos,
          readEntryFile: (filename) => this.getR2Object(`entries/block${blockNum}/entries/${filename}.json`),
          resumeFrom: progressData.selectionVerifyCursor || 0,
          ...(this.getSelectionVerifyBudgetMs() !== null
            ? { wallBudgetMs: this.getSelectionVerifyBudgetMs() } : {}),
          // リース更新は DO storage 書き込みなので、ファイル1個ごとではなく時間で間引く
          onFileVerified: async (p) => {
            if (Date.now() - lastRenew < 60000) return;
            lastRenew = Date.now();
            progressData.selectionVerifyProgress = { filesRead: p.filesRead, playersVerified: p.playersVerified, totalPlayers: p.totalPlayers };
            await this.renewGroupingLease(blockNum, progressData);
          },
        });
        progressData.selectionVerifyCursor = 0;
        progressData.selectionVerifyProgress = null;
        console.log(`Block ${blockNum}: selection integrity OK (rule v${sel.ruleVersion}, N=${committedTotal}, selected=${sel.selectedCount}, data files read=${sel.filesRead})`);
      } catch (selErr) {
        if (progressData.autoCheckpointResume && selErr?.r2ReadUnavailable) selErr.resumable = true;
        if (selErr?.resumable) {
          // 予算切れ＝続きがあるだけ。カーソルを保存して外側の resumable ハンドラに委ねる。
          progressData.selectionVerifyCursor = selErr.selectionResumeFrom;
          await this.renewGroupingLease(blockNum, progressData);
          console.warn(`Block ${blockNum}: selection integrity yielded — ${selErr.message}`);
          throw selErr;
        }
        progressData.status = 'failed';
        progressData.error = selErr.message;
        await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
        console.error(`Block ${blockNum}: selection integrity FAILED — grouping stopped:`, selErr.message);
        return { success: false, blockNum, error: selErr.message };
      }

      if (!selectionData.players || selectionData.players.length === 0) {
        // B4(2026-07-16): 0名ブロックも「ゲーム無し」として確定させる。
        // 従来はfailedで終了し、①summary.jsonが永遠に生成されない（block.jsが恒久的に
        // 単一DOへフォールバックし続ける増幅口）②merkle root未提出のため検証期間・請求期間が
        // 始まらず「報酬の永久凍結」がオンチェーンで確定しない、という2つの穴があった。
        // noGameサマリーを公開し、空ツリーの標識ルート（empty-merkle sentinel・
        // buildMerkleTreeのentries=0経路）を提出して請求期間を開始→終了させ、
        // 「配分ゼロで確定」を第三者が判別できるようにする。
        console.log(`Block ${blockNum}: 0 players - finalizing as no-game block`);
        progressData.phase = 'no_game_finalizing';
        await this.renewGroupingLease(blockNum, progressData);
        let res;
        try {
          res = await this.finalizeNoGameBlock(blockNum, { reason: 'zero_entries' });
        } catch (error) {
          error.resumable = true;
          progressData.phase = 'no_game_finalizing';
          throw error;
        }
        const wait = adminTxWaitOf(res);
        if (wait) {
          return {
            success: false, blockNum, totalPlayers: 0, totalGroups: 0, noGame: true,
            resumable: res.resumable !== false, parked: res.parked === true,
            waitReason: wait.waitReason, retryInMs: wait.retryInMs,
          };
        }
        return { success: true, blockNum, totalPlayers: 0, totalGroups: 0, noGame: true, ...res };
      }

      progressData.totalPlayers = selectionData.players.length;

      // === 応募者2名以下: ゲームなしでデポジットポイント按分 ===
      if (selectionData.players.length <= 2) {
        console.log(`Block ${blockNum}: ${selectionData.players.length} players - auto-distributing without game`);
        progressData.phase = 'auto_distributing';
        await this.renewGroupingLease(blockNum, progressData);

        let result;
        try {
          result = await this.autoDistribute(blockNum, selectionData.players);
        } catch (error) {
          // R20-F1: 全stageは冪等checkpoint付き。通常例外も正式なresumable失敗として
          // watchdogへ戻し、同じselectionを再検証して保存済みcheckpoint以降を再開する。
          error.resumable = true;
          progressData.phase = 'auto_distributing';
          const autoProgress = await this.storage.get(`auto_distribute_block${blockNum}`);
          if (autoProgress) {
            autoProgress.failures = (autoProgress.failures || 0) + 1;
            autoProgress.lastError = error.message;
            autoProgress.updatedAt = Date.now();
            await this.storage.put(`auto_distribute_block${blockNum}`, autoProgress);
          }
          if (/archive_rpc_required/.test(String(error.message))) {
            await sendAlertAndRecord(this.env, this.storage, {
              kind: 'archive_rpc_required',
              subject: `[COINU][CRITICAL] 過去の EthLock 状態を読めない: block ${blockNum}`,
              body: `reason=archive_rpc_required\nblockNum=${blockNum}\n${error.message}\nGET /calc-status?block=${blockNum}`,
            }).catch((alertError) => console.error('[auto-distribute] archive RPC alert failed:', alertError));
          }
          progressData.autoDistributeStage = autoProgress?.stage || null;
          await this.renewGroupingLease(blockNum, progressData);
          throw error;
        }

        const wait = adminTxWaitOf(result);
        if (wait) {
          const waitingProgress = await this.markGroupingAdminTxWait(blockNum, progressData, wait, {
            phase: 'auto_distributing', stage: wait.detail.stage || result.stage || 'manifest',
          });
          return {
            success: false, blockNum, resumable: waitingProgress.resumable,
            parked: waitingProgress.status === 'parked',
            waitReason: wait.waitReason,
            retryInMs: wait.retryInMs,
            autoDistributeStage: wait.detail.stage || result.stage || null,
          };
        }
        if (result?.pending) {
          const evidenceWait = await this.readNormalEvidenceWindowWait(blockNum);
          if (evidenceWait) {
            return await this.markGroupingEvidenceWindowWait(blockNum, progressData, evidenceWait);
          }
          const proofWait = await this.readNormalAutoProofWait(blockNum);
          if (proofWait) {
            return await this.markGroupingProofWait(blockNum, progressData, proofWait);
          }
          const error = new Error(`auto-distribute pending at ${result.stage || 'unknown'}`);
          error.resumable = true;
          progressData.phase = 'auto_distributing';
          progressData.autoDistributeStage = result.stage || null;
          await this.renewGroupingLease(blockNum, progressData);
          throw error;
        }

        progressData.status = 'completed';
        progressData.phase = 'completed';
        progressData.completedAt = new Date().toISOString();
        progressData.autoDistributed = true;
        progressData.totalGroups = 0;
        await this.storage.put(`grouping_block${blockNum}_progress`, progressData);

        return {
          success: true,
          blockNum,
          totalPlayers: selectionData.players.length,
          totalGroups: 0,
          autoDistributed: true,
          ...result
        };
      }

      // 2a. このブロックの主要言語（同言語グループ化を優先する言語）を動的決定
      //     - ブロック0 / 前ブロックが自動配布: 現在の選出プレイヤーの言語比
      //     - ブロック1以降: 前ブロックの非失格採掘者の言語比（未確定ならエラー終了）
      progressData.phase = 'computing_major_langs';
      await this.renewGroupingLease(blockNum, progressData);

      const majorLangs = await this.computeMajorLangs(blockNum);
      progressData.majorLangs = majorLangs;
      console.log(`Block ${blockNum} major languages: ${JSON.stringify(majorLangs)}`);

      progressData.phase = 'forming_groups';
      await this.renewGroupingLease(blockNum, progressData);

      // 2b. グループ分け実行（groupSeedで決定論的ランダム）
      //     groupSeed = keccak256(randao ‖ applicantHash ‖ "group")
      //     game_selection.json の randao / applicantHash（公開・検証可能値）から導出する。
      //     運営署名由来の randomSeed は廃止済み。
      if (!selectionData.randao || !selectionData.applicantHash) {
        progressData.status = 'failed';
        progressData.error = 'game_selection.json missing randao/applicantHash (required for group seed)';
        await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
        return { success: false, blockNum, error: progressData.error };
      }
      const groupSeed = deriveGroupSeed(selectionData.randao, selectionData.applicantHash);
      const groups = await this.formGroups(selectionData.players, groupSeed, majorLangs);

      // 公開物（game_groups.json / summary.json の本文）は**書く前に**組み立てる。
      // 完全性検査が「これから書く現物」を照合するため（後段の put はこの2つをそのまま使う）。
      const groupSummary = this.createGroupSummary(blockNum, groups, selectionData);
      const blockSummaryForR2 = this.buildBlockSummaryForR2(blockNum, groups, majorLangs);

      // P-2026-0816（2026-08-07）: グループ分け完全性検査（fail-closed）。
      // 選出には内側のゲート（verifySelectionIntegrity）があるのに、グループ分けには
      // 何も無かった＝「formGroups を正直に走らせた**後で**結果を差し替える」経路が
      // D1・game_groups.json・summary.json を揃って書き換えるだけで通っていた。
      // ここで formGroups を独立に再実行し、書き込み対象と厳密照合する。
      // 詳細（何が権威に縛られていて何が縛られていないか）は lib/grouping-integrity.js 冒頭。
      progressData.phase = 'verifying_grouping';
      await this.renewGroupingLease(blockNum, progressData);
      let verifiedPrevMarker = null;
      try {
        const gi = await verifyGroupingIntegrity({
          blockNum,
          players: selectionData.players,
          randao: selectionData.randao,
          applicantHash: selectionData.applicantHash,
          usedGroupSeed: groupSeed,
          usedMajorLangs: majorLangs,
          groups, groupSummary, blockSummary: blockSummaryForR2,
          // 独立再実行（this に依存する内部ヘルパーを使うのでメソッドとして渡す）
          formGroups: (p, s, m) => this.formGroups(p, s, m),
          // majorLangs の再導出。computeMajorLangs が読む前ブロック成果物だけを
          // 「アンカー検証つきの読み手」に差し替えるため、this を prototype にした
          // 使い捨てオブジェクトへ getR2Object を被せる（this 自体は書き換えない）。
          recomputeMajorLangs: async (readVerified) => {
            const probe = Object.create(this);
            probe.getR2Object = readVerified;
            return probe.computeMajorLangs(blockNum);
          },
          // P-2026-0822: `verifyGroupingIntegrity` はこの readText で前ブロックの
          // `summary.json` を読み、その中身から majorLangs を再導出する（＝採点の入力）。
          // 生テキストのまま sha256 照合にも使うので**テキストを返す契約は変えず**、
          // 返す前に正準JSON検査だけ通す。非正準なら throw（fail-closed）。
          // ⚠️ `summary.json` 以外（manifest / game_selection.json）は素通し。
          //   整数に見えるキーの並べ替えで偽陽性になるため（lib/canonical-json.js 参照）。
          readText: async (key) => {
            const text = await this.getR2Text(key);
            if (text != null && isCanonicalJsonRequiredKey(key)) parseCanonicalJson(text, key);
            return text;
          },
          getResultHash: async (n) => {
            const marker = await this.readResultHashOnChain(n);
            verifiedPrevMarker = marker;
            return marker;
          },
          anchorRequired: Boolean(this.env.HASH_STORAGE_CONTRACT_ADDRESS),
        });
        console.log(
          `Block ${blockNum}: grouping integrity OK (rule v${gi.ruleVersion}, ${gi.groupCount} groups / ` +
          `${gi.playerCount} players, majorLangs=${JSON.stringify(gi.majorLangs)}, ` +
          `prevAnchor=${gi.prevAnchor.status}, ${gi.elapsedMs}ms)`
        );
        progressData.groupingVerify = {
          ruleVersion: gi.ruleVersion, groupCount: gi.groupCount, prevAnchor: gi.prevAnchor.status,
        };
        if (blockNum > 0 && this.env.HASH_STORAGE_CONTRACT_ADDRESS) {
          try {
            groupSummary.prevResultRegistration = await this.readGroupingPrevRegistration(
              blockNum, gi.prevAnchor.status === 'verified' ? verifiedPrevMarker : null,
              gi.prevAnchor.status,
            );
          } catch (error) {
            // RPC 瞬断と照合後の再登録は次の試行で履歴を読み直す。
            const retryError = error instanceof Error ? error : new Error(String(error));
            retryError.groupingRegistrationRetry = true;
            throw retryError;
          }
        }
      } catch (giErr) {
        if (giErr?.groupingDependencyPending) {
          // 直前ブロックのmanifest/anchor commit待ち。値不一致はこの印を持たないため、
          // fail-closedを保ったまま既存の期限判定・安全なno-game終端へ接続できる。
          giErr.timelineUnverified = true;
          giErr.timelineCause = 'previous_block_anchor_pending';
          giErr.timelineRetryMs = GROUPING_DEPENDENCY_RETRY_MS;
          throw giErr;
        }
        if (giErr?.groupingAnchorUnavailable || giErr?.groupingRegistrationRetry) {
          // 前ブロックのオンチェーンアンカーが読めない＝**照合できていない**。
          // S3-008 と同じ扱い（park せず 30分ごとに再試行・開始窓が閉じたら no-game 確定）へ倒す。
          await this.shieldStartWindow(blockNum, giErr.groupingRegistrationRetry
            ? 'grouping_registration_retry' : 'grouping_anchor_unreadable');
          giErr.timelineUnverified = true;
          giErr.timelineCause = giErr.groupingRegistrationRetry
            ? 'grouping_registration_retry' : 'grouping_anchor_unreadable';
          giErr.rpcConfig = describeRpcConfig(this.env);
          throw giErr;
        }
        progressData.status = 'failed';
        progressData.error = giErr.message;
        await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
        console.error(`Block ${blockNum}: grouping integrity FAILED — nothing was written:`, giErr.message);
        return { success: false, blockNum, error: giErr.message };
      }

      progressData.totalGroups = groups.length;
      progressData.phase = 'writing_to_d1';
      await this.renewGroupingLease(blockNum, progressData);

      // 3. D1 (bitcoinu_data) にグループ情報を書き込み
      await this.writeGroupsToD1(blockNum, groups);

      // 4. R2にサマリーを保存
      progressData.phase = 'saving_summary';
      await this.renewGroupingLease(blockNum, progressData);

      try {
        await this.putR2ObjectOrThrow(`entries/block${blockNum}/game_groups.json`, groupSummary);
        this.deferGroupObservation(blockNum, {
          artifacts: {
            gameGroups: this.observationResult('succeeded', {
              key: `entries/block${blockNum}/game_groups.json`, groupCount: groups.length,
            }),
          },
        });
      } catch (error) {
        this.deferGroupObservation(blockNum, {
          artifacts: {
            gameGroups: this.observationFailure(error, { key: `entries/block${blockNum}/game_groups.json` }),
          },
        });
        throw error;
      }

      // block-summary.json をR2に作成（フロントエンド用キャッシュ）。
      // 宣言タイムラインをここで stamp する＝チャット初期化待機中（早着ガード）も block.js が
      // R2 直読みで正確な残り時間を描ける。verifyEnvChainTimeline 不一致の throw はそのまま
      // 伝播させ、公開前にグループ分けを停止する（F-TL5 の趣旨どおり）。
      // 遅延検知（extendGrace）は initChatGames 側の再 resolve が正 — ここでの値は表示用。
      // （本文は完全性検査の前に組み立て済み。ここでは宣言タイムラインを載せるだけ）
      const groupingTimeline = await this.resolveDeclaredTimeline(blockNum);
      blockSummaryForR2.timeline = this.buildSummaryTimeline(groupingTimeline.declared, groupingTimeline.graceSec);
      // 書き込み競合対策の対象外（2026-07-31・意図的）: グループ分けは「このブロックがこれから
      // 始まる」を宣言する**権威的な新規作成**。この時点で請求は存在しえない（root 未提出）。
      // リセット→再グループ分けでは前回の `claimed` を**引き継いではいけない**ため無条件のまま。
      try {
        // R15-26 summary-window-closure: リセット後の正典を必ず再作成する無条件 put。
        await this.putR2ObjectOrThrow(`games/block${blockNum}/summary.json`, blockSummaryForR2);
        this.deferGroupObservation(blockNum, {
          artifacts: {
            summary: this.observationResult('succeeded', {
              key: `games/block${blockNum}/summary.json`, groupCount: groups.length,
            }),
          },
        });
      } catch (error) {
        this.deferGroupObservation(blockNum, {
          artifacts: {
            summary: this.observationFailure(error, { key: `games/block${blockNum}/summary.json` }),
          },
        });
        throw error;
      }
      console.log(`Block summary cache written to R2 for block ${blockNum}`);

      // B6-01: summary 公開後、長い shard 書き込みへ入る前に uid→groupId 索引を公開する。
      // summary は同じグループ構成を既に公開済みなので情報は増えない。R2 障害でグループ分けを
      // 止めないよう best-effort とし、旧ブロック・公開失敗向けの /my-group D1 fallback も残す。
      await this.publishRosterIndexBestEffort(blockNum, groups);

      // 5. write-workersにゲームグループ情報を書き込み（シャードDB）
      progressData.phase = 'writing_to_shard_dbs';
      await this.renewGroupingLease(blockNum, progressData);

      // 行はD1から再構築する。一時的なshard失敗はresumableとして既存watchdogへ戻し、
      // GROUPING_MAX_ATTEMPTS以内でカーソル再開する。許可一覧外は通常failedで止める。
      const writeResult = await this.writeGameGroupsToShards(blockNum);
      console.log(`Shard DB writes: ${writeResult.totalWritten} written (${writeResult.totalChunks} chunks)`);

      // 6. ChatGameDO初期化
      progressData.phase = 'initializing_chat_games';
      await this.renewGroupingLease(blockNum, progressData);

      const initResult = await this.initChatGames(blockNum);

      // 完了
      await this.completeGroupingAfterChatInit(blockNum, progressData, initResult, {
        shardWriteLastCallResult: writeResult,
      });

      console.log(`Grouping completed for block ${blockNum}: ${groups.length} groups from ${selectionData.players.length} players`);

      return {
        success: true,
        blockNum,
        totalPlayers: selectionData.players.length,
        totalGroups: groups.length,
        majorLangs,
        groupSummary: {
          byLang: this.countGroupsByLang(groups),
          mixedGroups: groups.filter(g => g.mixed).length
        },
        chatInitResult: initResult,
        shardWriteLastCallResult: writeResult
      };

    } catch (error) {
      console.error(`Error in grouping for block ${blockNum}:`, error);

      const progressData = await this.storage.get(`grouping_block${blockNum}_progress`) || {};
      if (progressData.autoCheckpointResume && error?.r2ReadUnavailable) error.resumable = true;
      progressData.status = 'failed';
      progressData.error = error.message;
      this.clearGroupingNormalWait(progressData);

      // S3-008（2026-07-29）: 照合できていない＝**ゲームを開始しない**。
      // 30分ごとに再試行し、運用側が RPC を追加するか env を直せば自動で再開する。
      // 通常の park カウンタ（GROUPING_MAX_ATTEMPTS=20＝10分程度で諦める）には数えない。
      // 「開始できる権利」（オンチェーン窓）が失われたら、そのブロックは
      // 応募0件と同じ「ゲームなし・配分ゼロで確定」に倒す。
      if (error?.timelineUnverified) {
        const requestedRetryMs = Number(error.timelineRetryMs);
        const retryMs = Number.isFinite(requestedRetryMs) && requestedRetryMs >= 1000
          ? requestedRetryMs : GameMasterDO.TIMELINE_RETRY_MS;
        const waitCause = error.timelineCause
          || (error.rpcConfig ? 'chain_unreadable' : 'env_chain_mismatch');
        const dependencyWait = waitCause === 'previous_block_not_ready'
          || waitCause === 'previous_block_anchor_pending';
        if (dependencyWait) {
          try { await this.shieldDependencyStartWindow(blockNum, waitCause); }
          catch (shieldError) {
            console.warn(`[grouping] block ${blockNum}: dependency shield waiting:`, shieldError?.message || shieldError);
          }
        }
        const wait = await this.noteTimelineWait(blockNum, waitCause, error.rpcConfig);
        wait.retryMs = retryMs;
        if (wait.expired) {
          const finality = await this.inspectTimelineNoGameFinality(blockNum);
          if (finality.ready) {
            console.error(
              `[evidence] block ${blockNum}: start window closed while timeline stayed unverified, `
              + `and safe-chain Evidence result window is final with resultCount=0 — finalizing the dedicated `
              + `timeline_unverified no-game schema (cause=${wait.cause})`
            );
            try {
              const selection = await this.getR2Object(`entries/block${blockNum}/game_selection.json`);
              const finalizationMeta = {
                reason: 'timeline_unverified',
                cause: wait.cause,
                totalPlayers: Array.isArray(selection?.players) ? selection.players.length : 0,
                chainFinality: finality,
              };
              // cleanup の途中死や、その後の R2/manifest 失敗から通常 grouping へ戻らないための
              // 専用再開チェックポイント。成功時に finalizeNoGameBlock が削除する。
              progressData.phase = 'no_game_finalizing';
              progressData.timelineNoGameFinalization = finalizationMeta;
              await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
              const res = await this.finalizeNoGameBlock(blockNum, finalizationMeta);
              const adminWait = adminTxWaitOf(res);
              if (adminWait) {
                return {
                  success: false, blockNum, noGame: true, reason: 'timeline_unverified',
                  resumable: res.resumable !== false, parked: res.parked === true,
                  waitReason: adminWait.waitReason, retryInMs: adminWait.retryInMs,
                };
              }
              await this.clearTimelineWait(blockNum);
              return { success: true, blockNum, noGame: true, reason: 'timeline_unverified', ...res };
            } catch (e2) {
              console.error(`[evidence] no-game finalization failed for block ${blockNum}:`, e2.message);
              // 専用 checkpoint と直前の管理tx待ちは次の watchdog 再開に必要。
              // 成功終端だけが finalizeNoGameBlock 内で checkpoint を削除する。
              progressData.status = 'failed';
              progressData.error = `no-game finalization failed: ${e2.message}`;
              e2.resumable = true;
              return this.recordGroupingResumableFailure(
                blockNum, progressData, e2, GameMasterDO.TIMELINE_RETRY_MS,
              );
            }
          }
          if (!finality.ready) {
            // RPCがまだ読めないこと自体はterminalではない。有効／無効を問わずResultが1件でも
            // 観測された場合も空rootへ確定せず、chain復旧後の通常 grouping + Evidence 採点を待つ。
            console.warn(
              `[evidence] block ${blockNum}: start deadline passed but no-game is NOT finalizable `
              + `(chain=${finality.reason || 'unverified'}, resultCount=${finality.resultCount ?? 'unknown'}); retrying`
            );
          } else {
            console.warn(`[evidence] block ${blockNum}: no-game finality is ready but cleanup/publication is incomplete; retrying`);
          }
        }
        progressData.status = 'failed';
        progressData.resumable = true;
        progressData.timelineUnverified = true;
        progressData.timelineWait = wait;
        progressData.timelineCause = waitCause;
        if (retryMs !== GameMasterDO.TIMELINE_RETRY_MS) {
          progressData.dependencyNextRetryAt = Date.now() + retryMs;
        }
        await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
        console.warn(
          `[evidence] block ${blockNum}: waiting for env↔chain verification (${wait.cause}, attempt ${wait.attempts}) — ` +
          `retrying in ${retryMs / 1000}s; start deadline ` +
          `${Number.isFinite(wait.deadlineMs) ? new Date(wait.deadlineMs).toISOString() : 'unknown'} ` +
          `(passing it alone never finalizes an empty result)`
        );
        try {
          await this.enqueueGroupingWatchdog(blockNum, retryMs);
        } catch (e3) {
          console.error(`[evidence] retry enqueue failed for block ${blockNum}:`, e3.message);
        }
        // S3-008（ユーザー要望・2026-07-29）: 成功した通知は**トラブル1件につき1回だけ**。
        // この待機には期限（extendGrace が不可能になる時刻）があり、期限内に運用者が
        // 気づけるかどうかがブロックの成否を分けるため、初回は必ず知らせる。
        // 失敗時はラッチを立てず次周期も試し、成功後は原因が変わるまで送らない。
        // 前ブロックの非同期commit待ちは数十秒で解消する通常過渡状態。
        // 自動再試行のたびに運用メールを送らず、RPC/env等の介入が必要な場合だけ通知する。
        if (wait.shouldAlert && !dependencyWait) await this.alertTimelineWait(wait, error);
        // 依存の開始窓・照合は従来どおり判定した後にだけ、前ブロックの正常待ちを伝える。
        if (dependencyWait && Number.isFinite(wait.deadlineMs) && !wait.expired && blockNum > 0) {
          try {
            const proofWait = await this.readNormalAutoProofWait(blockNum - 1, { verifyForBlock: blockNum });
            if (proofWait) {
              const refreshStartWindow = async () => {
                const current = await this.startWindowDeadlineMs(blockNum);
                Object.assign(wait, { deadlineMs: current.deadlineMs, deadlineSource: current.source,
                  snapshotReadAt: current.readAt, expired: Number.isFinite(current.deadlineMs) && Date.now() >= current.deadlineMs });
                return Number.isFinite(wait.deadlineMs) && !wait.expired;
              };
              // manifest/summary照合後に窓を再読し、保存・予約中の窓切れも返却直前に拒否する。
              if (await refreshStartWindow()) {
                const reply = await this.markGroupingProofWait(blockNum, progressData, proofWait, retryMs);
                if (await refreshStartWindow()) return reply;
              }
              this.clearGroupingNormalWait(progressData);
              progressData.error = error.message;
              await this.storage.put({
                [`timeline_wait_block${blockNum}`]: wait,
                [`grouping_block${blockNum}_progress`]: progressData,
              });
            }
          } catch (waitError) {
            // この枝は既に外側catch内。待ちの保存・予約失敗を独立に失敗予算へ戻す。
            this.clearGroupingNormalWait(progressData);
            progressData.status = 'failed';
            progressData.error = waitError.message;
            return this.recordGroupingResumableFailure(blockNum, progressData, waitError, retryMs);
          }
        }
        return { success: false, blockNum, error: error.message, timelineUnverified: true, retryInMs: retryMs };
      }

      // S3-007（2026-07-29）: 「1呼び出しの予算切れ」は続きがあるだけなので自動で再開する。
      // 旧実装は他の異常と同じ failed に落ち、watchdog は status!=='started' で終了するため
      // **自動再開が一切起きなかった**。許容上限（50デポジット×2100人）では 500 チャンクを
      // 必ず超えるので、grace=2h 内の自動完走が構造的に成立しない状態だった。
      // カーソルは保存済み、シャード書き込みは冪等 upsert なので再入は安全。
      if (error?.resumable) {
        const retryDelay = error.groupingShardTransient
          ? groupingShardRetryDelayMs((progressData.resumeAttempts || 0) + 1)
          : error.r2ReadUnavailable
          ? groupingR2RetryDelayMs((progressData.resumeAttempts || 0) + 1)
          : (progressData.waitReason === 'admin_freeze' || progressData.phase === 'no_game_finalizing' || progressData.phase === 'auto_distributing')
            ? GameMasterDO.TIMELINE_RETRY_MS : 1000;
        return this.recordGroupingResumableFailure(blockNum, progressData, error, retryDelay);
      }

      await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
      if (progressData.phase === 'writing_to_shard_dbs' || error.shardEndpoint === '/write-game-groups') {
        // progress は再入時に作り直すため、警報の印は盤別の独立キーに置く。
        // 外部送信より先に保存し、張り直し・インスタンス再作成・手動再開でも重複させない。
        const alertKey = `grouping_shard_failure_alert_block${blockNum}`;
        const cause = error.groupingShardFailureCause || groupingShardFailureCause(error.message);
        const previousAlert = await this.storage.get(alertKey);
        if (previousAlert?.cause !== cause) {
          const marker = { attemptedAt: Date.now(), attempt: (previousAlert?.attempt || 0) + 1,
            attemptId: crypto.randomUUID(),
            phase: progressData.phase, cause, failureMessage: error.message,
            sent: false, via: null, error: 'delivery_pending' };
          await this.storage.put(alertKey, marker);
          const result = await sendAlertAndRecord(this.env, this.storage, {
            kind: 'grouping_shard_failed',
            subject: `[COINU][CRITICAL] グループのshard書込が停止: block ${blockNum}`,
            body: [
              'severity=CRITICAL',
              'reason=grouping_shard_failed',
              `cause=${cause}`,
              `blockNum=${blockNum}`,
              `phase=${progressData.phase || 'unknown'}`,
              `error=${error.message}`,
              'manualAction=応答の文言・件数・権限・名簿を確認し、原因解消後に POST /start-grouping で再開する',
            ].join('\n'),
          }).catch((alertError) => {
            console.error(`[grouping] block ${blockNum}: shard failure alert failed: ${alertError?.message || alertError}`);
            return { sent: false, via: null, error: String(alertError?.message || alertError) };
          });
          // 配送中の原因変更・resetで新しい印が書かれたら、古い結果で上書きしない。
          const current = await this.storage.get(alertKey);
          if (current?.attemptId === marker.attemptId) {
            await this.storage.put(alertKey, { ...marker, ...result });
          }
        }
      }
      return { success: false, blockNum, error: error.message };
    }
  }

  // ============================================================
  // ChatGameDO管理
  // ============================================================

  // G3是正（2026-07-18）: ChatGameDO群への一斉リクエストの共通バッチ並行ヘルパー。
  // 旧実装は525グループを1件ずつawaitで直列送信し、1フェーズ遷移のwallが10〜26秒
  // かかっていた（cleanup-chat-dosだけが並行化済みだった）。DO_FETCH_CONCURRENCY並列で
  // バッチ実行する。fnはthrowせず結果値を返すこと（各サイトでcatchして値に変換）。
  // S3-002: ChatGameDO の HTTP 制御面は API_SECRET 必須（無認証だと第三者が
  // /init 先回り・任意 phase・全削除・提出物の早期閲覧を実行できた）。
  // DO binding 経由の内部呼び出しは必ずこのヘルパーで secret ヘッダを付ける。
  chatDoRequest(path, init = {}) {
    return new Request(`https://dummy-host${path}`, {
      ...init,
      headers: { ...(init.headers || {}), 'X-Api-Secret': this.env.API_SECRET || '' }
    });
  }

  async batchChatDoCalls(items, fn) {
    const results = [];
    for (let i = 0; i < items.length; i += DO_FETCH_CONCURRENCY) {
      const batch = items.slice(i, i + DO_FETCH_CONCURRENCY);
      results.push(...await Promise.all(batch.map(fn)));
    }
    return results;
  }

  // init_chat_games タスクを登録（同一ブロックの既存タスクは置き換え）＋アラーム設定。
  // アラームはキュー先頭（最も早いタスク）に合わせる＝他ブロックの先行タスクを遅らせない。
  async enqueueInitChatGames(blockNum, executeAt, attempts = 0) {
    const taskQueue = (await this.storage.get('phase_task_queue') || [])
      .filter(t => !(t.type === 'init_chat_games' && t.blockNum === blockNum));
    taskQueue.push({ type: 'init_chat_games', blockNum, executeAt, ...(attempts ? { attempts } : {}) });
    taskQueue.sort((a, b) => a.executeAt - b.executeAt);
    await this.storage.put('phase_task_queue', taskQueue);
    await this.armEarliestQueuedTask();
  }

  buildRosterIndex(groups) {
    const rosterIndex = Object.create(null);
    for (const group of groups || []) {
      const members = typeof group.members === 'string' ? JSON.parse(group.members) : group.members;
      if (!Array.isArray(members)) {
        throw new Error(`group ${group.group_id ?? group.groupId} roster is invalid`);
      }
      const groupId = Number(group.group_id ?? group.groupId);
      for (const member of members) {
        const uid = member?.uid ?? member?.data?.uid;
        rosterIndex[uid] = groupId;
      }
    }
    return rosterIndex;
  }

  // startGrouping と initChatGames の両方から使う非致命 publish。
  // initChatGames 単独の手動再実行でも索引を復旧できるため、後段呼び出しは削除しない。
  async publishRosterIndexBestEffort(blockNum, groups) {
    const key = `games/block${blockNum}/roster/index.json`;
    try {
      // `Object.create(null)` は buildRosterIndex 内で強制する（uid='__proto__' も落とさない）。
      const orderedGroups = [...(groups || [])].sort((a, b) =>
        Number(a.group_id ?? a.groupId) - Number(b.group_id ?? b.groupId));
      const rosterIndex = this.buildRosterIndex(orderedGroups);
      const rosterIndexPublished = await this.putR2Object(key, rosterIndex);
      if (!rosterIndexPublished) throw new Error('R2 put returned false');
      this.deferGroupObservation(blockNum, {
        roster: {
          indexPublish: this.observationResult('succeeded', {
            key, uidCount: Object.keys(rosterIndex).length,
          }),
        },
      });
      console.log(`Roster index written to R2 for block ${blockNum} (${Object.keys(rosterIndex).length} uids)`);
      return true;
    } catch (error) {
      this.deferGroupObservation(blockNum, {
        roster: { indexPublish: this.observationFailure(error, { key }) },
      });
      console.error(`Roster index R2 publish failed for block ${blockNum}:`, error);
      return false;
    }
  }

  async rebuildAndPublishRosterManifest(blockNum, suppliedGroups = null) {
    let stage = 'load_groups';
    const groupObservations = [];
    try {
      const db = this.env.BITCOINU_DATA;
      if (!db) throw new Error('BITCOINU_DATA binding not found');
      let allGroups = suppliedGroups;
      if (!Array.isArray(allGroups)) {
        ({ results: allGroups } = await db.prepare(
          'SELECT group_id, members FROM game_groups WHERE block_num = ? ORDER BY group_id'
        ).bind(blockNum).all());
      }
      if (!Array.isArray(allGroups) || allGroups.length === 0) throw new Error('roster groups unavailable');

      // index は保存済み中間値に依存せず、D1 名簿から毎回同じバイトを再生成する。
      const orderedGroups = [...allGroups].sort((a, b) =>
        Number(a.group_id ?? a.groupId) - Number(b.group_id ?? b.groupId));
      const rosterIndex = this.buildRosterIndex(orderedGroups);
      const rosterIndexText = JSON.stringify(rosterIndex);
      stage = 'publish_index';
      await this.putR2ObjectOrThrow(`games/block${blockNum}/roster/index.json`, rosterIndex);
      const rosterIndexSha256 = await this.sha256Hex(rosterIndexText);
      this.deferGroupObservation(blockNum, {
        roster: {
          indexPublish: this.observationResult('succeeded', {
            key: `games/block${blockNum}/roster/index.json`, sha256: rosterIndexSha256,
            uidCount: Object.keys(rosterIndex).length,
          }),
        },
      });

      const groups = [];
      for (const group of allGroups) {
        const groupId = Number(group.group_id);
        stage = `publish_group_${groupId}`;
        // sha の保存有無にかかわらず毎回再公開する。R2 object だけが消えた場合も
        // roster_anchor リトライ1本で index/group/manifest の全公開物を復旧できる。
        const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${groupId}`);
        const chatDO = this.env.CHAT_GAME_DO.get(doId);
        const response = await chatDO.fetch(this.chatDoRequest('/republish-roster', { method: 'POST' }));
        const body = await response.json().catch(() => ({}));
        if (!response.ok || !body?.rosterSha256) {
          const error = new Error(`group ${groupId} roster republish failed: ${body?.error || response.status}`);
          groupObservations.push({ groupId, rosterPublish: this.observationFailure(error) });
          throw error;
        }
        const sha256 = body.rosterSha256;
        await this.storage.put(`roster_group_sha_block${blockNum}_group${groupId}`, sha256);
        groups.push({ groupId, sha256 });
        groupObservations.push({ groupId, rosterPublish: this.observationResult('succeeded', { sha256 }) });
      }
      groups.sort((a, b) => a.groupId - b.groupId);
      const manifestText = JSON.stringify({ blockNum: Number(blockNum), indexSha256: rosterIndexSha256, groups });
      stage = 'publish_manifest';
      await this.env.R2_BUCKET.put(`games/block${blockNum}/roster/manifest.json`, manifestText, {
        httpMetadata: { contentType: 'application/json' },
      });
      await this.storage.put(`roster_manifest_text_block${blockNum}`, manifestText);
      this.deferGroupObservation(blockNum, {
        groupPatches: groupObservations,
        roster: {
          manifestPublish: this.observationResult('succeeded', {
            key: `games/block${blockNum}/roster/manifest.json`, groupCount: groups.length,
            sha256: await this.sha256Hex(manifestText),
          }),
        },
      });
      return { manifestText, groups, rosterIndexSha256 };
    } catch (error) {
      this.deferGroupObservation(blockNum, {
        groupPatches: groupObservations,
        roster: { rebuild: this.observationFailure(error, { stage }) },
      });
      throw error;
    }
  }

  // 公開物の実バイトと、公開物を介さず D1 から組み立てた名簿を照合する。
  // 再公開とは別 invocation で呼び、最大組数でも subrequest 予算を共有しない。
  async computePublishedRosterCommitment(blockNum, manifestText) {
    const manifest = JSON.parse(manifestText);
    if (manifest?.blockNum !== Number(blockNum) || !Array.isArray(manifest.groups)) {
      throw new Error('roster manifest block/groups mismatch');
    }
    const publishedManifest = await this.getR2Text(`games/block${blockNum}/roster/manifest.json`);
    if (publishedManifest !== manifestText) throw new Error('published roster manifest differs from saved text');
    const indexText = await this.getR2Text(`games/block${blockNum}/roster/index.json`);
    if (indexText === null || await this.sha256Hex(indexText) !== manifest.indexSha256) {
      throw new Error('published roster index sha256 mismatch');
    }
    const db = this.env.BITCOINU_DATA;
    if (!db) throw new Error('BITCOINU_DATA binding not found');
    const { results: d1Groups } = await db.prepare(
      'SELECT group_id, members FROM game_groups WHERE block_num = ? ORDER BY group_id'
    ).bind(blockNum).all();
    if (!Array.isArray(d1Groups) || d1Groups.length !== manifest.groups.length) {
      throw new Error('roster manifest/D1 group count mismatch');
    }
    const d1IndexText = JSON.stringify(this.buildRosterIndex([...d1Groups].sort((a, b) =>
      Number(a.group_id) - Number(b.group_id))));
    if (indexText !== d1IndexText) throw new Error('published roster index/D1 mismatch');
    const d1ByGroup = new Map(d1Groups.map((group) => [Number(group.group_id), group]));
    if (d1ByGroup.size !== d1Groups.length) throw new Error('duplicate D1 roster group');
    const groupTexts = new Map();
    for (const group of manifest.groups) {
      const groupId = group?.groupId;
      const d1 = d1ByGroup.get(groupId);
      if (!d1) throw new Error(`group ${groupId} absent from D1 roster`);
      const text = await this.getR2Text(`games/block${blockNum}/roster/group${groupId}.json`);
      if (text === null) throw new Error(`group ${groupId} roster file missing`);
      if (await this.sha256Hex(text) !== String(group.sha256).toLowerCase()) {
        throw new Error(`group ${groupId} roster sha256 mismatch`);
      }
      groupTexts.set(groupId, text);
      const members = typeof d1.members === 'string' ? JSON.parse(d1.members) : d1.members;
      if (!Array.isArray(members) || text !== canonicalRosterText(blockNum, groupId, members)) {
        throw new Error(`group ${groupId} roster/D1 canonical ten-key bytes mismatch`);
      }
    }
    return buildRosterMemberCommitment({ blockNum, manifestText, groupTexts });
  }

  async scheduleChatWhenAllGroupsReady(blockNum, checkedCommitment = null) {
    const noGameCleanup = await this.storage.get(this.timelineNoGameCleanupKey(blockNum));
    if (noGameCleanup) {
      return { ready: false, noGame: true, reason: 'timeline_no_game_cleanup_started' };
    }
    const db = this.env.BITCOINU_DATA;
    if (!db) {
      const result = { ready: false, reason: 'db_unavailable' };
      this.deferGroupObservation(blockNum, { scheduleDecision: this.observationResult('failed', result) });
      return result;
    }
    const { results: groups } = await db.prepare(
      'SELECT group_id, status FROM game_groups WHERE block_num = ?'
    ).bind(blockNum).all();
    if (!Array.isArray(groups) || groups.length === 0
        || groups.some((group) => group.status !== 'waiting')) {
      const pastWaiting = Array.isArray(groups) && groups.some((group) =>
        ['chatting', 'submitting', 'completed'].includes(group.status));
      if (pastWaiting) await this.clearRosterGateAfterStart(blockNum);
      const result = { ready: false, reason: 'groups_not_all_waiting', pastWaiting };
      this.deferGroupObservation(blockNum, { scheduleDecision: this.observationResult('failed', result) });
      return result;
    }
    for (const group of groups) {
      if (!await this.storage.get(`roster_group_sha_block${blockNum}_group${group.group_id}`)) {
        const result = { ready: false, reason: `group_${group.group_id}_roster_sha_missing` };
        this.deferGroupObservation(blockNum, { scheduleDecision: this.observationResult('failed', result) });
        return result;
      }
    }
    const d1Completeness = await this.checkGroupingD1Completeness(blockNum, groups);
    if (!d1Completeness.complete) {
      const result = { ready: false, reason: 'groups_incomplete',
        groupCount: groups.length, expectedGroups: d1Completeness.expectedGroups };
      await this.noteRosterGateNotReady(blockNum, result.reason, null);
      this.deferGroupObservation(blockNum, { scheduleDecision: this.observationResult('failed', result) });
      return result;
    }
    // roster_anchor の復旧タスクもこの判定を通る。開始前に同タスクが再試行されても
    // grace を再解決して既存の開始時刻を動かさない。キュー書込み後〜alarm設定前に
    // isolate が落ちた場合も、既存3タスクを権威に alarm だけ復旧できる。
    const queue = await this.storage.get('phase_task_queue') || [];
    const existing = queue.filter((task) => task.type === 'phase_transition' && task.blockNum === blockNum);
    if (existing.length === 3
        && new Set(existing.map((task) => task.targetPhase)).size === 3) {
      const executeAt = Math.min(...existing.map((task) => Number(task.executeAt)));
      if (Number.isFinite(executeAt)) await this.armEarliestQueuedTask();
      await this.clearRosterGateAfterStart(blockNum);
      const result = {
        ready: true,
        alreadyScheduled: true,
        groupIds: groups.map((group) => Number(group.group_id)),
        chattingStart: existing.find((task) => task.targetPhase === 'chatting')?.executeAt ?? null,
      };
      this.deferGroupObservation(blockNum, {
        scheduleDecision: this.observationResult('succeeded', {
          ready: true, alreadyScheduled: true, groupCount: result.groupIds.length,
          chattingStart: result.chattingStart,
        }),
      });
      return result;
    }
    // 開始前だけ、manifest の現物と確定した追記履歴を同じ宣言窓で照合する。
    // 欠落や RPC 失敗で phase_transition を張らない。期限が近い場合は既存の
    // shieldStartWindow で開始窓を守り、roster_anchor の再試行に出口を残す。
    let resolvedTimeline;
    let lateAnchorResolved = false;
    try {
      resolvedTimeline = await this.resolveDeclaredTimeline(blockNum, { allowExtension: false });
      const preliminary = await this.checkRosterAnchorForStart(blockNum, resolvedTimeline, checkedCommitment);
      if (preliminary.reason === 'anchor_late') {
        const declaration = await this.storage.get(this.declaredGraceKey(blockNum));
        if (declaration?.source === 'intent' || Number.isSafeInteger(declaration?.watchGraceSec)) {
          await this.noteRosterGateNotReady(blockNum, 'grace_extension_pending', resolvedTimeline);
          return { ready: false, reason: 'grace_extension_pending' };
        }
        await this.shieldRosterStartWindow(blockNum, 'roster_anchor_late');
        // 送信と receipt は別の時点。fresh currentGrace で着地を読める次の再判定まで待つ。
        await this.noteRosterGateNotReady(blockNum, 'anchor_late', resolvedTimeline);
        return { ready: false, reason: 'anchor_late' };
      } else if (!preliminary.ready) {
        await this.noteRosterGateNotReady(blockNum, preliminary.reason, resolvedTimeline);
        const declaration = await this.storage.get(this.declaredGraceKey(blockNum));
        if (Date.now() >= resolvedTimeline.declared.chattingStart - this.rosterShieldLeadMs(preliminary.reason)
            && declaration?.source !== 'intent'
            && !Number.isSafeInteger(declaration?.watchGraceSec)) {
          await this.shieldRosterStartWindow(blockNum, 'roster_anchor_pending');
        }
        const result = { ready: false, reason: preliminary.reason };
        this.deferGroupObservation(blockNum, { scheduleDecision: this.observationResult('failed', result) });
        return result;
      }
      // 確認深さ待ちで短い pipeline_late 延長を繰り返さない。
      // 開始が過ぎていれば、十分な余裕を持つ shield の着地を待って再判定する。
      const pendingDeclaration = await this.storage.get(this.declaredGraceKey(blockNum));
      if (this.env.EVIDENCE_CONTRACT_ADDRESS
          && (pendingDeclaration?.source === 'intent'
            || Number.isSafeInteger(pendingDeclaration?.watchGraceSec))) {
        await this.noteRosterGateNotReady(blockNum, 'grace_extension_pending', resolvedTimeline);
        return { ready: false, reason: 'grace_extension_pending' };
      }
      if (!this.env.EVIDENCE_CONTRACT_ADDRESS) {
        // ローカルの Evidence 無し構成は従来の ephemeral pipeline 延長を維持する。
        resolvedTimeline = await this.resolveDeclaredTimeline(blockNum);
      } else {
        if (Date.now() > resolvedTimeline.declared.chattingStart + 60000) {
          const shield = await this.shieldRosterStartWindow(blockNum, 'roster_pipeline_late',
            { probeStartedWithRoster: true });
          // C32F1（C32-A-14）: grace が上限（BLOCK_TIME）で頭打ちなら shield は already_sufficient を返す。
          // そのときも名簿つきで開始に達していれば（startedWithRoster）、案 U の出口と同じに扱う。
          if (shield?.reason !== 'started_with_roster'
              && !(shield?.reason === 'already_sufficient' && shield?.startedWithRoster === true)) {
            await this.noteRosterGateNotReady(blockNum, 'roster_pipeline_late', resolvedTimeline);
            return { ready: false, reason: 'roster_pipeline_late' };
          }
          // 開始前に名簿が登録済みなら、遅れても現在の grace のまま開始する。
          // 延長を実際に見送ったのはここなので、遅れた開始の印はここで書く（C31-08）。
          await this.noteStartedWithRosterLate(blockNum, 'roster_pipeline_late', shield);
        }
        resolvedTimeline = await this.resolveDeclaredTimeline(blockNum, { allowExtension: false });
      }
      if (resolvedTimeline?.extensionUnconfirmed === true) {
        await this.noteRosterGateNotReady(blockNum, 'grace_extension_unconfirmed', resolvedTimeline);
        return { ready: false, reason: 'grace_extension_unconfirmed' };
      }
      const declaration = await this.storage.get(this.declaredGraceKey(blockNum));
      if (this.env.EVIDENCE_CONTRACT_ADDRESS
          && (declaration?.source === 'intent' || Number.isSafeInteger(declaration?.watchGraceSec))) {
        await this.noteRosterGateNotReady(blockNum, 'grace_extension_pending', resolvedTimeline);
        return { ready: false, reason: 'grace_extension_pending' };
      }
      const checked = await this.checkRosterAnchorForStart(blockNum, resolvedTimeline, preliminary.commitment);
      if (!checked.ready) {
        await this.noteRosterGateNotReady(blockNum, checked.reason, resolvedTimeline);
        if (checked.reason === 'anchor_late'
            || Date.now() >= resolvedTimeline.declared.chattingStart - this.rosterShieldLeadMs(checked.reason)) {
          await this.shieldRosterStartWindow(blockNum, 'roster_anchor_pending');
        }
        const result = { ready: false, reason: checked.reason };
        this.deferGroupObservation(blockNum, { scheduleDecision: this.observationResult('failed', result) });
        return result;
      }
      lateAnchorResolved = !!await this.storage.get(`roster_anchor_late_block${blockNum}`);
      await this.storage.delete(`roster_anchor_late_block${blockNum}`);
      await this.clearRosterGateAfterStart(blockNum);
    } catch (error) {
      const cause = error?.timelineUnverified
        ? (error.timelineCause || 'chain_unreadable') : 'roster_gate_unreadable';
      const wait = await this.noteTimelineWait(blockNum, cause, error?.rpcConfig, 'roster_gate');
      const fallbackStart = Number.isFinite(wait.deadlineMs)
        ? wait.deadlineMs - this.gamePeriodMs : Infinity;
      const declaredStart = resolvedTimeline?.declared?.chattingStart ?? fallbackStart;
      const retryInMs = wait.attempts <= 2 || declaredStart - Date.now() <= GameMasterDO.TIMELINE_RETRY_MS
        ? PHASE_TASK_RETRY_DELAY_MS : GameMasterDO.TIMELINE_RETRY_MS;
      wait.retryMs = retryInMs;
      if (wait.shouldAlert) {
        try { await this.alertTimelineWait(wait, error); }
        catch (alertError) { console.error('[roster-gate] alert failed:', alertError?.message || alertError); }
      }
      if (cause === 'roster_gate_unreadable' && resolvedTimeline?.declared
          && Date.now() >= resolvedTimeline.declared.chattingStart - this.rosterShieldLeadMs(cause)) {
        await this.shieldRosterStartWindow(blockNum, 'roster_gate_unreadable');
      }
      const result = { ready: false, reason: `anchor_check_failed: ${error?.message || error}` };
      this.deferGroupObservation(blockNum, { scheduleDecision: this.observationResult('failed', result) });
      return { ...result, retryInMs };
    }
    const scheduled = await this.schedulePhaseTransitions(blockNum, resolvedTimeline);
    try {
      await this.updateBlockSummaryStatus(blockNum, 'waiting',
        this.buildSummaryTimeline(resolvedTimeline.declared, resolvedTimeline.graceSec));
    } catch (error) {
      console.error(`Error updating block summary status to 'waiting' in R2:`, error);
    }
    const result = { ready: true, resolvedTimeline, groupIds: groups.map((group) => Number(group.group_id)) };
    await this.clearRosterGateAfterStart(blockNum);
    this.deferGroupObservation(blockNum, {
      scheduleDecision: this.observationResult('succeeded', {
        ready: true, alreadyScheduled: false, groupCount: result.groupIds.length,
        chattingStart: resolvedTimeline.declared?.chattingStart ?? null,
        lateAnchorResolved,
        scheduleResult: scheduled?.scheduled === true ? 'succeeded' : 'unknown',
      }),
    });
    return result;
  }

  // 開始関門が「開始できない」ときに shield（延長）を送り始める、宣言開始からの前倒し幅（ms）。
  // 🔴 理由ごとに幅が違う（便 C30F1c・C31-05／C31-06）。
  //   ・roster_confirmations_pending（名簿の登録は見えていて確定深さだけを待つ）:
  //     確認深さ（CONFIRMATION_BLOCKS×12秒）＋関門の再判定2周＋着地の余裕60秒。
  //     案 U（Evidence.extendGrace は名簿つきで開始に達した後を拒否）の下で、延長が開始より前に
  //     着地するよう前倒しする（C30F1 §1-10-2）。着地が開始を越えれば遅れて開始する（案 U の (b)）。
  //   ・grace_confirmation_pending（延長は着地済みで、その grace の確定深さを待つ）:
  //     確認深さ＋再判定1周（C30F1 の前と同じ幅）。広げると、shield の目標（今＋32分）の中で
  //     「着地＋確定深さ」が終わる前に次の shield が出て、開始が押し出され続ける空回りの
  //     着地遅延の下限が下がる（C31-05。本番値の模型 c30f1-grace-chain-test.mjs で、この幅なら
  //     着地 26 ブロックまで延長1本で開始＝C30F1 の前と同じ。C30F1 の一律の前倒しでは 19 ブロックで
  //     2本・20 ブロックから空回りした）。
  //   ・その他（名簿の不一致・未登録・読取不能など）: 開始の60秒前（C30F1 の前と同じ）。
  rosterShieldLeadMs(reason) {
    // 🔴 不正な CONFIRMATION_BLOCKS は関門が roster_confirmation_depth_invalid で先に止める
    //    （checkRosterAnchorForStart）。2つの確認待ちの理由へはその値で来ない。
    const confirmations = Number.parseInt(this.env.CONFIRMATION_BLOCKS || '64', 10);
    const depthMs = Math.max(0, confirmations) * ETHEREUM_BLOCK_TIME_MS;
    if (reason === 'roster_confirmations_pending') {
      return depthMs + 2 * PHASE_TASK_RETRY_DELAY_MS + 60000;
    }
    if (reason === 'grace_confirmation_pending') return depthMs + PHASE_TASK_RETRY_DELAY_MS;
    return 60000;
  }

  // 案 U: 名簿つきで開始に達したため延長を見送り、今の grace のまま遅れて chatting へ進むときだけ
  // 書く印（`/calc-status` の started_with_roster_late）。submitting の遅れでは書かない。
  // 同じキーの split 防止の印（開始済みグループがあるのに延長しかけた異常）は上書きしない。
  // 出口: そのブロックが submitting／completed へ進んだら advancePhase が消す（C31-08）。
  async noteStartedWithRosterLate(blockNum, source, result = null) {
    const key = `timeline_started_no_extend_block${blockNum}`;
    const existing = await this.storage.get(key);
    if (existing && existing.reason !== 'started_with_roster') return;
    await this.storage.put(key, {
      blockNum,
      reason: 'started_with_roster',
      source: existing?.source ?? source,
      detectedAt: existing?.detectedAt ?? Date.now(),
      currentGrace: Number.isSafeInteger(result?.currentGrace) ? result.currentGrace : (existing?.currentGrace ?? null),
      chattingStart: Number.isFinite(result?.chattingStart) ? result.chattingStart : (existing?.chattingStart ?? null),
    });
  }

  async clearStartedWithRosterLate(blockNum) {
    const key = `timeline_started_no_extend_block${blockNum}`;
    const existing = await this.storage.get(key);
    if (existing?.reason === 'started_with_roster') await this.storage.delete(key);
  }

  async shieldRosterStartWindow(blockNum, reason, extendOptions = undefined) {
    const terminalKey = `roster_shield_terminal_block${blockNum}`;
    const terminal = await this.storage.get(terminalKey);
    if (terminal?.reason === reason
        && terminal.rpcAgreement >= 2) {
      return { extended: false, reason: terminal.result, terminal: true };
    }
    const lastKey = `roster_shield_last_intent_block${blockNum}`;
    const last = await this.storage.get(lastKey);
    const singleProvider = !this.createEvidenceReadClients();
    // 1業者では終端の印を書けない。窓を失った後は要求値を固定し、送信係の
    // 同じ intent を照会する。時刻と共に目標を増やして intent を積まない。
    let result;
    const windowLost = last?.windowLost === true
      || (last?.coordinatorQueried === true && Number.isSafeInteger(last.deadlineAt)
        && Date.now() >= last.deadlineAt);
    if (singleProvider && windowLost && typeof last.intentId === 'string'
        && Number.isSafeInteger(last.requestedGraceSec)) {
      if (last.coordinatorQueried) {
        const sent = await this.sendAdminTx({ intentId: last.intentId,
          operation: 'extendGrace', payload: { blockNum, newGraceSec: last.requestedGraceSec },
          deadlineAt: last.deadlineAt });
        result = { ...sent, extended: false, requestedGraceSec: last.requestedGraceSec,
          intentId: last.intentId, reason: sent.reason || 'coordinator_unavailable',
          capped: last.capped, reusedIntent: true };
      } else {
        result = { extended: false, requestedGraceSec: last.requestedGraceSec,
          intentId: last.intentId, reason: last.resultReason, capped: last.capped,
          reusedIntent: true };
      }
    } else {
      result = await this.shieldStartWindow(blockNum, reason, extendOptions);
      if (singleProvider && result?.intentId && Number.isSafeInteger(result?.requestedGraceSec)) {
        await this.storage.put(lastKey, { reason, intentId: result.intentId,
          requestedGraceSec: result.requestedGraceSec, deadlineAt: result.deadlineAt,
          capped: result.capped,
          resultReason: result.reason, coordinatorQueried: typeof result.status === 'string',
          windowLost: ['chat_window_closed', 'deadline_expired', 'started_with_roster'].includes(result.reason)
            || (result.reason === 'start_in_past' && result.capped === true) });
      }
    }
    // 便 C32F2: start_in_past は上限で頭打ちの目標（capped）だけ終端にする。頭打ちでなければ
    // 送信の遅れによる競合なので、次の再判定で今から目標を取り直す（終端にしない）。
    if (['grace_exceeds_block_time', 'chat_window_closed', 'deadline_expired', 'started_with_roster'].includes(result?.reason)
        || (result?.reason === 'start_in_past' && result?.capped === true)) {
      const evidence = await this.verifyRosterShieldTerminal(blockNum, result);
      if (evidence) await this.storage.put(terminalKey, {
        blockNum, reason, result: result.reason, at: Date.now(), ...evidence,
      });
    }
    if (this.env.EVIDENCE_CONTRACT_ADDRESS
        && Number.isSafeInteger(result?.requestedGraceSec)
        && (result?.pending || result?.landed || result?.reason === 'already_sufficient'
          || result?.reason === 'landing_unverified')) {
      await this.adoptGraceExtensionResult(blockNum, result.requestedGraceSec, result,
        reason, { reschedule: true });
    }
    return result;
  }

  // 送信係の preflight 応答は票数を運ばない。印は GM 自身が finalized の2業者一致で
  // 終端条件を読み直せたときだけ残す。古い票数不明の印も読み手側で再試行可能にする。
  async verifyRosterShieldTerminal(blockNum, result) {
    const clients = this.createEvidenceReadClients();
    if (!clients) return null;
    try {
      const snapshot = await this.readEvidenceTimelineSnapshot(blockNum);
      if (!snapshot || !Number.isSafeInteger(snapshot.observedAtMs)) return null;
      const requested = result.requestedGraceSec;
      let confirmed = false;
      if (result.reason === 'grace_exceeds_block_time') {
        confirmed = Number.isSafeInteger(requested) && Number.isSafeInteger(snapshot.params?.BLOCK_TIME)
          && requested > snapshot.params.BLOCK_TIME;
      } else if (result.reason === 'chat_window_closed' || result.reason === 'deadline_expired') {
        confirmed = Number.isSafeInteger(snapshot.chatCloseAt)
          && snapshot.observedAtMs >= snapshot.chatCloseAt * 1000;
      } else if (result.reason === 'start_in_past' && result.capped === true) {
        const block = await readMatchingFinalizedBlock(clients);
        const tolerance = await this.readEvidenceAtBlock(clients, block,
          this.env.EVIDENCE_CONTRACT_ADDRESS,
          [{ name: 'START_PAST_TOLERANCE', type: 'function', stateMutability: 'view',
            inputs: [], outputs: [{ name: '', type: 'uint256' }] }], 'START_PAST_TOLERANCE');
        confirmed = Number.isSafeInteger(requested) && Number.isSafeInteger(snapshot.chatOpenAt)
          && BigInt(snapshot.chatOpenAt) + BigInt(requested) + BigInt(tolerance) <= block.timestamp;
      } else if (result.reason === 'started_with_roster' && this.env.HASH_STORAGE_CONTRACT_ADDRESS) {
        const block = await readMatchingFinalizedBlock(clients);
        const start = snapshot.chatOpenAt + snapshot.graceSec;
        if (Number.isSafeInteger(start) && snapshot.observedAtMs >= start * 1000) {
          const row = await this.readEvidenceAtBlock(clients, block,
            this.env.HASH_STORAGE_CONTRACT_ADDRESS, HASH_STORAGE_ABI, 'rosterLastIn',
            [BigInt(blockNum), BigInt(snapshot.chatOpenAt), BigInt(start)]);
          confirmed = String(row[1]).toLowerCase() !== `0x${'0'.repeat(64)}`;
        }
      }
      return confirmed ? { rpcAgreement: 2, evidenceSource: 'finalized_contract_read' } : null;
    } catch (error) {
      console.warn(`[evidence] block ${blockNum}: shield terminal quorum unavailable:`, error?.message || error);
      return null;
    }
  }

  async checkRosterAnchorForStart(blockNum, timeline, checkedCommitment = null) {
    const anchor = await this.storage.get(`roster_anchor_block${blockNum}`);
    const manifestText = await this.storage.get(`roster_manifest_text_block${blockNum}`);
    if (!anchor || typeof manifestText !== 'string' || !manifestText) {
      return { ready: false, reason: 'roster_anchor_or_manifest_missing' };
    }
    const key = rosterAnchorKey(blockNum);
    let commitment = checkedCommitment;
    try {
      if (!commitment) commitment = await this.computePublishedRosterCommitment(blockNum, manifestText);
    } catch (error) {
      console.error(`[roster-gate] block ${blockNum} published roster check failed:`, error);
      return { ready: false, reason: 'roster_anchor_manifest_mismatch' };
    }
    const expectedHash = commitment.C?.toLowerCase();
    if (!expectedHash) return { ready: false, reason: 'canonical_roster_missing' };
    if (anchor.key?.toLowerCase() !== key || anchor.hash?.toLowerCase() !== expectedHash) {
      return { ready: false, reason: 'roster_anchor_manifest_mismatch' };
    }
    const client = this.createReadOnlyClient();
    if (!client || !this.env.HASH_STORAGE_CONTRACT_ADDRESS || !timeline?.declared) {
      return { ready: false, reason: 'roster_anchor_chain_unavailable' };
    }
    const quorumClients = this.createEvidenceReadClients();
    const latestBlock = quorumClients ? null : await client.getBlockNumber();
    const confirmations = this.env.CONFIRMATION_BLOCKS ? Number.parseInt(this.env.CONFIRMATION_BLOCKS, 10) : 64;
    if (!Number.isSafeInteger(confirmations) || confirmations < 0) {
      return { ready: false, reason: 'roster_confirmation_depth_invalid' };
    }
    if (!quorumClients && latestBlock < BigInt(confirmations)) {
      return { ready: false, reason: 'roster_confirmations_pending' };
    }
    const finalizedBlock = quorumClients ? await readMatchingFinalizedBlock(quorumClients) : null;
    const blockNumber = finalizedBlock ? finalizedBlock.number : latestBlock - BigInt(confirmations);
    const snapshotBlock = finalizedBlock || await client.getBlock({ blockNumber });
    const read = (functionName, args, atBlock = finalizedBlock, atNumber = blockNumber) => quorumClients
      ? this.readEvidenceAtBlock(quorumClients, atBlock, this.env.HASH_STORAGE_CONTRACT_ADDRESS,
        HASH_STORAGE_ABI, functionName, args)
      : client.readContract({
        address: this.env.HASH_STORAGE_CONTRACT_ADDRESS, abi: HASH_STORAGE_ABI,
        functionName, args, blockNumber: atNumber,
      });
    let count;
    let legacyRow = null;
    let legacyMode = false;
    try {
      count = await read('otherRegistrationCount', [key]);
    } catch (error) {
      const legacy = LEGACY_HASH_STORAGE_ALLOWLIST.has(keccak256(stringToHex(
        String(this.env.HASH_STORAGE_CONTRACT_ADDRESS).toLowerCase(),
      )));
      const getterMissing = typeof error?.walk === 'function' && !!error.walk((cause) =>
        cause?.name === 'ContractFunctionRevertedError'
        || cause?.name === 'ContractFunctionZeroDataError'
        || cause?.name === 'ExecutionRevertedError');
      if (!legacy || !(getterMissing || error?.missingGetterQuorum === true)) throw error;
      legacyMode = true;
      const current = await read('getOtherHash', [key]);
      const updated = Number(current[1]);
      if (Number.isSafeInteger(updated) && updated > 0) {
        const registrationBlock = quorumClients
          ? await readMatchingFinalizedBlock(quorumClients, { number: BigInt(updated) })
          : await client.getBlock({ blockNumber: BigInt(updated) });
        legacyRow = { hash: current[0], registeredBlock: updated, registeredAt: registrationBlock.timestamp };
        count = 1;
      } else count = 0;
    }
    // U-B の選択窓は未着地 intent ではなく、この読取ブロックの currentGrace で組む。
    let chainTimeline = timeline.declared;
    if (this.env.EVIDENCE_CONTRACT_ADDRESS) {
      const graceAbi = [{ name: 'currentGrace', type: 'function', stateMutability: 'view',
        inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] }];
      const graceRaw = quorumClients
        ? await this.readEvidenceAtBlock(quorumClients,
          finalizedBlock,
          this.env.EVIDENCE_CONTRACT_ADDRESS, graceAbi, 'currentGrace', [BigInt(blockNum)])
        : await client.readContract({ address: this.env.EVIDENCE_CONTRACT_ADDRESS,
          abi: graceAbi, functionName: 'currentGrace', args: [BigInt(blockNum)], blockNumber });
      const graceSec = Number(graceRaw);
      if (!Number.isSafeInteger(graceSec) || graceSec < 0) {
        return { ready: false, reason: 'roster_chain_grace_unavailable' };
      }
      chainTimeline = this.getDeclaredTimesMs(blockNum, graceSec);
      if (!chainTimeline) return { ready: false, reason: 'roster_chain_timeline_unavailable' };
      if (Number.isSafeInteger(timeline?.graceSec) && timeline.graceSec > graceSec) {
        return { ready: false, reason: 'grace_confirmation_pending' };
      }
    }
    // verifyEnvChainTimeline と同じ秒丸め。ms の端数を共有規則へ漏らさない。
    const entryEndSec = Math.round(chainTimeline.entryEndMs / 1000);
    const chattingStartSec = Math.round(chainTimeline.chattingStart / 1000);
    const at = async (index) => {
      if (legacyRow) return legacyRow;
      const row = await read('otherRegistrationAt', [key, BigInt(index)]);
      return { hash: row[0], registeredBlock: row[1], registeredAt: row[2] };
    };
    const selected = await selectCanonicalRosterRegistration({
      count, at, entryEndSec, chattingStartSec, nowSec: Number(snapshotBlock.timestamp),
    });
    if (selected.row?.hash === expectedHash) {
      if (BigInt(selected.row.registeredBlock) > blockNumber) {
        return { ready: false, reason: 'roster_confirmations_pending' };
      }
      return { ready: true, selected, commitment };
    }
    // 登録が宣言開始に間に合わなければ、開始前に grace を延ばしてから再判定する。
    // 今の名簿以外が最新の場合は延長によって採用しない。
    if (Number(count) > 0) {
      const latest = await at(Number(count) - 1);
      if (String(latest.hash).toLowerCase() === expectedHash
          && Number(latest.registeredAt) >= chattingStartSec) {
        await this.storage.put(`roster_anchor_late_block${blockNum}`, {
          blockNum, updatedBlock: String(latest.registeredBlock),
          updatedTimestampMs: Number(latest.registeredAt) * 1000,
          chattingStart: chainTimeline.chattingStart, detectedAt: Date.now(),
          resolution: 'awaiting_grace_extension',
        });
        return { ready: false, reason: 'anchor_late' };
      }
    }
    // 安全高の ready 判定には触れず、最新高は「待てば解けるか」の診断だけに使う。
    let latestCount;
    let latestRow = null;
    try {
      const diagnosticBlock = quorumClients ? await readMatchingHeadBlock(quorumClients) : null;
      const diagnosticNumber = diagnosticBlock?.number ?? latestBlock;
      if (legacyMode) {
        const current = await read('getOtherHash', [key], diagnosticBlock, diagnosticNumber);
        const updated = Number(current[1]);
        latestCount = Number.isSafeInteger(updated) && updated > 0 ? 1 : 0;
        if (latestCount) {
          const registeredBlock = quorumClients
            ? await readMatchingHeadBlock(quorumClients, { number: BigInt(updated) })
            : await client.getBlock({ blockNumber: BigInt(updated) });
          latestRow = { hash: current[0], registeredBlock: updated, registeredAt: registeredBlock.timestamp };
        }
      } else {
        latestCount = Number(await read('otherRegistrationCount', [key], diagnosticBlock, diagnosticNumber));
        if (latestCount > 0) {
          const row = await read('otherRegistrationAt', [key, BigInt(latestCount - 1)],
            diagnosticBlock, diagnosticNumber);
          latestRow = { hash: row[0], registeredBlock: row[1], registeredAt: row[2] };
        }
      }
    } catch (error) {
      console.warn(`[roster-gate] latest diagnostic unavailable block=${blockNum}:`, error?.message || error);
      return { ready: false, reason: selected.status === 'none' ? 'canonical_roster_missing' : 'canonical_roster_hash_mismatch' };
    }
    const ageMs = Date.now() - Number(anchor.at);
    const diagnosticWaitMs = confirmations * ETHEREUM_BLOCK_TIME_MS + 2 * PHASE_TASK_RETRY_DELAY_MS;
    const oldAnchor = Number.isFinite(ageMs) && ageMs >= diagnosticWaitMs;
    if (latestRow && Number(latestRow.registeredAt) >= entryEndSec) {
      if (String(latestRow.hash).toLowerCase() === expectedHash) {
        return { ready: false, reason: 'roster_confirmations_pending' };
      }
      return { ready: false, reason: 'canonical_roster_hash_mismatch' };
    }
    return { ready: false, reason: oldAnchor ? 'roster_anchor_missing_onchain' : 'canonical_roster_missing' };
  }

  // ChatGameDO初期化: D1からグループ情報を読み取り、各ChatGameDOを初期化。
  // v3.2: 早着ガード撤去 — グループ分け完了後ただちに waiting フェーズで初期化する。
  // 「宣言 chattingStart まで待つ」は waiting→chatting の phase_transition タスクが担う
  //（Evidence.sol「早く準備できたら宣言chattingStartまで待つ」）。
  async initChatGames(blockNum, opts = {}) {
    console.log(`Initializing chat games for block ${blockNum}`);

    const noGameCleanup = await this.storage.get(this.timelineNoGameCleanupKey(blockNum));
    if (noGameCleanup) {
      return { success: true, skipped: true, noGame: true, blockNum,
        reason: 'timeline_no_game_cleanup_started' };
    }

    const db = this.env.BITCOINU_DATA;
    if (!db) {
      return { success: false, error: 'BITCOINU_DATA binding not found' };
    }

    // 手動 /init-chat-games もここを通す。部分 D1 では DO 初期化・waiting 化を始めない。
    const d1Completeness = await this.checkGroupingD1Completeness(blockNum);
    if (!d1Completeness.complete) {
      await this.noteRosterGateNotReady(blockNum, 'groups_incomplete', null);
      return { success: false, blockNum, reason: 'groups_incomplete',
        error: 'groups_incomplete', groupCount: d1Completeness.groupCount,
        expectedGroups: d1Completeness.expectedGroups };
    }

    // D1からformedグループを取得
    const { results } = await db.prepare(
      `SELECT group_id, lang, mixed, members FROM game_groups WHERE block_num = ? AND status = 'formed'`
    ).bind(blockNum).all();

    const { results: allGroups } = await db.prepare(
      `SELECT group_id, members FROM game_groups WHERE block_num = ? ORDER BY group_id`
    ).bind(blockNum).all();

    if (!results || results.length === 0) {
      // Block 18 実測（2026-09-03）: 全DO初期化と waiting 化の後、遅い名簿アンカー中に
      // isolate が終了すると、旧実装は再入時に formed=0 だけを見て永久に終了した。
      // roster sha は waiting 化より先に永続化されるため、全行 waiting の場合だけ
      // 共通フェーズ予約を冪等復旧する。completed/部分状態は成功扱いにしない。
      const { results: statuses } = await db.prepare(
        `SELECT group_id, status FROM game_groups WHERE block_num = ?`
      ).bind(blockNum).all();
      let rosterRecoveryQueued = false;
      if (Array.isArray(statuses) && statuses.length > 0
          && statuses.every((group) => group.status === 'waiting')) {
        const anchorRegistered = !!await this.storage.get(`roster_anchor_block${blockNum}`);
        const wasParked = !!await this.storage.get(`phase_task_parked:${blockNum}:roster_anchor`);
        if (opts.manual === true && wasParked) {
          await this.storage.delete(`phase_task_parked:${blockNum}:roster_anchor`);
          await this.storage.delete(`roster_anchor_attempts_block${blockNum}`);
          await this.storage.delete(`roster_anchor_failed_block${blockNum}`);
        }
        if ((!anchorRegistered || (opts.manual === true && wasParked))
            && !await this.storage.get(`phase_task_parked:${blockNum}:roster_anchor`)) {
          const queued = await this.storage.get('phase_task_queue') || [];
          if (!queued.some((task) => task.type === 'roster_anchor' && task.blockNum === blockNum)) {
            await this.enqueuePhaseTask({
              type: 'roster_anchor', blockNum, anchorOnly: anchorRegistered, attempts: 0,
              executeAt: Date.now() + 1000,
            });
            rosterRecoveryQueued = true;
          }
        }
        const scheduled = await this.scheduleChatWhenAllGroupsReady(blockNum);
        if (scheduled?.ready) {
          // 便 PLAYAT（2026-11-25）: 初回の出口が waiting への更新の後・登録の前で途切れた回にも、
          // 参加予定時刻を集める仕事が1度は登録されるようにする（投げない・戻り値を変えない）。
          await this.enqueueAvailabilitySeedBestEffort(blockNum);
          return {
            success: true,
            blockNum,
            totalGroups: statuses.length,
            initialized: 0,
            alreadyInitialized: statuses.length,
            errors: 0,
            rosterShaMissingCount: 0,
            resumedFromWaiting: true,
          };
        }
      }
      return rosterRecoveryQueued
        ? { success: false, blockNum, recoveryQueued: true, reason: 'roster_anchor_requeued' }
        : { success: false, error: 'No formed groups found', blockNum };
    }

    console.log(`Found ${results.length} groups to initialize`);

    // 宣言タイムラインを先に確定する（この段階では grace を延長しない）。
    // waiting の終了時刻 = 宣言 chattingStart を各 ChatGameDO に渡すことで、
    // フロントの残り時間表示が grace 延長後の実際の遷移時刻と一致する。
    // この時点では部分初期化の可能性があるため、grace はまだ延長しない。
    // 全グループが waiting + roster sha 完備になった一点で scheduleChatWhenAllGroupsReady が
    // 必要な延長を一度だけ解決し、ブロック共通の phase task を張る。
    const resolvedTimeline = await this.resolveDeclaredTimeline(blockNum, { allowExtension: false });

    // P2P §4.6（F4）: uid→groupId の索引をR2公開ドメインへ書く。
    // from-the-start WS検閲下のクライアントは /my-group が使えず自分のgroupIdを知れない。
    // この索引→各グループのロスター（ChatGameDO handleInitが書く）でP2Pチャネルを
    // ブートストラップできる（server非依存の読み取り経路）。
    // 待機ガードより前に書く＝待機中も /my-group がroster索引（1行読み）で応える
    //（G2是正のD1全行走査フォールバックへ落とさない）。グループ構成は summary.json が
    // グループ分け時に既に公開しているため、索引の早期公開は情報を追加しない。
    // 🔴 P-2026-0823（2026-08-07）: buildRosterIndex は **`Object.create(null)`** を使う。
    // 手動 /init-chat-games や reset 後の再初期化でも索引を復旧できるよう、この後段 publish は維持する。
    await this.publishRosterIndexBestEffort(blockNum, allGroups);

    // v3.2: 早着ガードは撤去。グループ分けが宣言 chattingStart より早く完了しても
    // waiting フェーズで即初期化し、chatting への遷移は schedulePhaseTransitions の
    // phase_transition タスクが宣言 chattingStart に発火させる（開始は常に宣言時刻）。
    void opts;

    // S3-013（2026-07-29）: **初期化する予定の ChatGameDO を append-only で控える**。
    // reset 系は D1 の game_groups 行（/reset-block）や progress の totalGroups（/reset）から
    // 対象を列挙するため、その記録が失われた／保存前に死んだ場合の DO が「孤児」として残り、
    // 同じ blockNum で再試験したときに前ランの名簿・発言が混入する。
    // ここに残しておけば reset は D1・progress・このレジストリの**和集合**を消せる。
    try {
      const regKey = `chatdo_registry_block${blockNum}`;
      const known = new Set(await this.storage.get(regKey) || []);
      for (const g of results) known.add(g.group_id);
      await this.storage.put(regKey, [...known].sort((a, b) => a - b));
      this.deferGroupObservation(blockNum, {
        registrySave: this.observationResult('succeeded', { groupCount: known.size }),
        groupPatches: results.map((group) => ({
          groupId: Number(group.group_id),
          registrySave: this.observationResult('succeeded', { registered: true }),
        })),
      });
    } catch (e) {
      this.deferGroupObservation(blockNum, {
        registrySave: this.observationFailure(e),
        groupPatches: results.map((group) => ({
          groupId: Number(group.group_id),
          registrySave: this.observationFailure(e, { registered: false }),
        })),
      });
      console.error(`[init] chat DO registry write failed for block ${blockNum}:`, e.message);
    }

    let initialized = 0;
    let alreadyInitialized = 0; // A6: 乗っ取りresume時の再送で初期化済み(409)は正常
    let errors = 0;
    let rosterShaMissingCount = 0;

    // 各グループのChatGameDOを初期化（G3: DO_FETCH_CONCURRENCY並列バッチ）
    const initOutcomes = await this.batchChatDoCalls(results, async (group) => {
      try {
        const members = JSON.parse(group.members);
        const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${group.group_id}`);
        const chatDO = this.env.CHAT_GAME_DO.get(doId);

        const response = await chatDO.fetch(this.chatDoRequest('/init', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            blockNum,
            groupId: group.group_id,
            lang: group.lang,
            mixed: group.mixed === 1,
            members,
            phaseEndTime: resolvedTimeline.declared.chattingStart,
            periodDurations: {
              gamePeriod: this.gamePeriodMs,
              submitPeriod: this.submitPeriodMs
            }
          })
        }));

        if (response.ok) {
          const body = await response.json().catch(() => ({}));
          return { state: 'initialized', rosterSha256: body?.rosterSha256 || null };
        }
        if (response.status === 409) {
          // A6: 既に初期化済み（乗っ取りresume時の再送）。/init側のガードにより
          // チャット状態は一切変更されない＝正常として数える。
          // S3-013（2026-07-29）: ただし **D1 の名簿と一致する場合だけ**。
          // ChatGameDO の id は `blockNum-groupId` の決定論なので、前ランの残留（孤児）や
          // 別 roster で先回り初期化された DO も 409 を返す。旧実装はそれを無検証で
          // 「成功」と数えていたため、前ランの名簿・フェーズ・発言が混入した状態で
          // ゲームが進み得た。一致しなければ error 扱い（D1 行は formed のまま残り、
          // 再試行 → park → /calc-status に出る＝運用が気づける）。
          const body = await response.json().catch(() => ({}));
          const expected = await this.sha256Hex(canonicalRosterText(blockNum, group.group_id, members));
          if (body?.rosterSha256 === expected) {
            return { state: 'already', rosterSha256: body?.rosterSha256 || null };
          }
          console.error(
            `[init] block ${blockNum} group ${group.group_id}: ChatGameDO already initialized with a DIFFERENT roster ` +
            `(stored=${body?.rosterSha256 ?? 'unknown'}, expected=${expected}, phase=${body?.phase ?? '?'}) — ` +
            `treating as error (reset this DO with POST /reset-chat-dos before re-initializing)`
          );
          return { state: 'error', rosterSha256: null };
        }
        const errorData = await response.json().catch(() => ({}));
        console.error(`Failed to init ChatGameDO for group ${group.group_id}:`, errorData);
        return { state: 'error', rosterSha256: null };
      } catch (error) {
        console.error(`Error initializing ChatGameDO for group ${group.group_id}:`, error);
        return { state: 'error', rosterSha256: null };
      }
    });
    // K-S2-004 関連是正（2026-07-27）: 初期化に成功したグループの group_id を控える。
    // 旧実装は「1グループでも成功していれば formed 行を全部 waiting に flip」していた。
    // すると失敗グループも waiting になり、リトライ時の `WHERE status='formed'` が空振りして
    // `No formed groups found` で永久に再初期化されなくなる（20回リトライ→park するが、
    // その間に失敗グループは未初期化のままチャット期間を通過する）。未初期化DOの
    // /get-results は 200 かつ members:[] を返すため、結果集計では「0人グループの採点成功」
    // として扱われ、そのグループの全員が結果からも Merkle からも無言で消えていた。
    const okGroupIds = [];
    const initGroupObservations = [];
    for (let i = 0; i < initOutcomes.length; i++) {
      const outcome = initOutcomes[i];
      const initAccepted = outcome?.state === 'initialized' || outcome?.state === 'already';
      if (outcome?.state === 'initialized') initialized++;
      else if (outcome?.state === 'already') alreadyInitialized++;
      else errors++;
      if (initAccepted && !outcome?.rosterSha256) {
        rosterShaMissingCount++;
        errors++;
      } else if (initAccepted) {
        // roster が公開できたグループだけ waiting に進める。欠落時は formed に残し、
        // 次の /init (409) が ChatGameDO の再公開経路を通って自己修復できるようにする。
        okGroupIds.push(results[i].group_id);
      }
      if (outcome?.rosterSha256) {
        await this.storage.put(`roster_group_sha_block${blockNum}_group${results[i].group_id}`, outcome.rosterSha256);
      }
      initGroupObservations.push({
        groupId: Number(results[i].group_id),
        chatDoInit: this.observationResult(
          initAccepted && outcome?.rosterSha256 ? 'succeeded' : 'failed',
          {
            outcome: outcome?.state || 'error',
            rosterSha256: outcome?.rosterSha256 || null,
            error: initAccepted && !outcome?.rosterSha256 ? 'roster_sha_missing' : null,
          },
        ),
      });
    }
    this.deferGroupObservation(blockNum, { groupPatches: initGroupObservations });

    // D1のステータスを'waiting'に更新（初期化できたグループのみ。失敗分は formed のまま残し、
    // init_chat_games タスクの再試行対象に留める）
    // A6: 全グループが初期化済み(409)のresumeでも後段（waiting更新は冪等な no-op・
    // フェーズタスク登録）を実行する＝「waiting更新後〜スケジュール登録前」の途中死を治せる
    if (okGroupIds.length > 0) {
      // D1 は1文の束縛変数を100個までに制限する。block_num と合わせて100以下にする
      // （100組ずつでは101個になり、101組以上のブロックで too many SQL variables・段1.5 b1 525組で発覚）。
      for (let i = 0; i < okGroupIds.length; i += D1_GROUP_ID_CHUNK) {
        const chunk = okGroupIds.slice(i, i + D1_GROUP_ID_CHUNK);
        await db.prepare(
          `UPDATE game_groups SET status = 'waiting' WHERE block_num = ? AND status = 'formed' AND group_id IN (${chunk.map(() => '?').join(',')})`
        ).bind(blockNum, ...chunk).run();
      }

    }

    // F-1 / Round 15 GS-01: 全ChatGameDOが返した「実際にR2へ書いたバイト列」のsha256から
    // ライブ名簿manifestを作り、既存HashStorage.otherHashesへアンカーする。
    //
    // 2,100人では約525グループになる。ここで /init の約525回に続けて
    // /republish-roster を約525回呼ぶと、同一invocationが共有の設計上限を必ず越える。
    // roster_anchor は元から冪等なalarmタスクなので、初回も別invocationへ分ける。
    // これは失敗ではないため scheduleRosterAnchorRetry（アラート・attempt加算）は使わない。
    if (errors === 0 && okGroupIds.length === results.length) {
      await this.enqueuePhaseTask({
        type: 'roster_anchor', blockNum, attempts: 0, executeAt: Date.now() + 1000,
      });
      this.deferGroupObservation(blockNum, {
        roster: {
          manifestPublish: this.observationResult('not_attempted', {
            reason: 'deferred_to_separate_invocation', groupCount: allGroups.length,
          }),
        },
      });
      // 全 DO と group sha に加え、別 invocation の manifest/anchor が確定するまで
      // 開始タスクを張らない。遅着時の grace は共通の予約点で解決する。
      await this.scheduleChatWhenAllGroupsReady(blockNum);
      // 便 PLAYAT（2026-11-25）: 全組の初期化が済んだ後で、参加予定時刻を集める後追いの仕事を登録する
      // （エントリーの時・マイページで先に入れた値を、待機中の画面に出すため）。表示だけの値なので、
      // 登録の失敗で初期化の戻り値と後続（名簿の登録・開始の予約）を1つも変えない。
      await this.enqueueAvailabilitySeedBestEffort(blockNum);
    }

    console.log(`ChatGameDO initialization: ${initialized} success, ${alreadyInitialized} already-initialized, ${errors} errors (${rosterShaMissingCount} roster sha missing)`);

    return {
      success: errors === 0,
      blockNum,
      totalGroups: results.length,
      initialized,
      alreadyInitialized,
      errors,
      rosterShaMissingCount,
      rosterAnchorDeferred: errors === 0 && okGroupIds.length === results.length,
    };
  }

  // フェーズ遷移: 全グループのChatGameDOに遷移を通知 + D1更新
  async advancePhase(blockNum, targetPhase, declaredEndTime = null, timingMeta = null) {
    timingMeta = timingMeta || this._nextPhaseTimingMeta || {};
    this._nextPhaseTimingMeta = null;
    console.log(`Advancing phase for block ${blockNum} to ${targetPhase}`);

    const noGameCleanup = await this.storage.get(this.timelineNoGameCleanupKey(blockNum));
    if (noGameCleanup) {
      return { success: true, skipped: true, noGame: true, blockNum,
        reason: 'timeline_no_game_cleanup_started', advanced: 0, errors: 0 };
    }

    const db = this.env.BITCOINU_DATA;
    if (!db) {
      return { success: false, error: 'BITCOINU_DATA binding not found' };
    }

    // D1から該当ブロックの全グループIDを取得
    // 🔴 ラウンド19 判断不要-4（2026-08-08）: `status` も持ってくる。旧実装は group_id だけを
    //    引いていたので、**まだ `waiting` のグループにも `/set-phase submitting` を送り**、
    //    `chat-game-DO.js:550-553` が後退しか禁じない（`waiting → submitting` は 200）ため、
    //    チャット期間を丸ごと飛ばしたグループが静かに次段へ進んでいた。
    //    ここでは遷移を止めない（止めると liveness が壊れる＝そのグループが終われない）。
    //    **検知して見えるところに出す**のが第三の網（判断不要-4 の (2)）。
    const { results } = await db.prepare(
      `SELECT group_id, status FROM game_groups WHERE block_num = ?`
    ).bind(blockNum).all();

    if (!results || results.length === 0) {
      return { success: false, error: 'No groups found', blockNum };
    }

    // フェーズ終了時刻: 宣言タイムライン（タスクに埋め込まれた値）を優先。
    // 手動 /phase 呼び出し等で宣言値が無い場合は従来どおり now + 期間長。
    const now = Date.now();
    let phaseEndTime = declaredEndTime;
    if (phaseEndTime == null) {
      switch (targetPhase) {
        case 'chatting': phaseEndTime = now + this.gamePeriodMs; break;
        case 'submitting': phaseEndTime = now + this.submitPeriodMs; break;
        // waiting, completed は終了時刻なし（completedは終了フェーズ）
        default: phaseEndTime = null;
      }
    }
    const phaseEndTimeSource = timingMeta.phaseEndTimeSource
      || (declaredEndTime != null ? 'declared_argument' : (targetPhase === 'completed' ? 'none_completed' : 'duration_fallback'));
    const manualFallback = timingMeta.manualFallback === true
      || phaseEndTimeSource === 'duration_fallback'
      || phaseEndTimeSource.startsWith('manual_declared_env_');
    // チェーン照合は最後に成功したEvidence snapshotだけを読む。RPCをここで追加実行せず、
    // phase遷移の本処理を遅くしない。snapshot未取得と照合失敗は別状態で残る。
    this.deferGroupObservation(blockNum, async () => {
      const snapshot = await this.storage.get(`evidence_tl_snapshot_block${blockNum}`) || null;
      let chainExpectedEndTime = null;
      if (targetPhase === 'chatting' && Number.isFinite(Number(snapshot?.chatCloseAt))) {
        chainExpectedEndTime = Number(snapshot.chatCloseAt) * 1000;
      } else if (targetPhase === 'submitting' && Number.isFinite(Number(snapshot?.resultCloseAt))) {
        chainExpectedEndTime = Number(snapshot.resultCloseAt) * 1000;
      }
      const comparable = phaseEndTime != null && chainExpectedEndTime != null;
      return {
        phaseTiming: {
          [targetPhase]: this.observationResult('succeeded', {
            phaseEndTime,
            phaseEndTimeSource,
            manualFallback,
            graceSource: timingMeta.graceSource || null,
            graceReadError: timingMeta.graceReadError || null,
            chainComparison: comparable
              ? { state: 'succeeded', snapshotReadAt: snapshot?.readAt ?? null,
                  expectedEndTime: chainExpectedEndTime, differenceMs: phaseEndTime - chainExpectedEndTime }
              : { state: 'not_attempted', reason: targetPhase === 'completed' ? 'no_phase_end' : 'chain_snapshot_unavailable',
                  snapshotReadAt: snapshot?.readAt ?? null },
          }),
        },
      };
    });

    let advanced = 0;
    let errors = 0;

    // 各ChatGameDOにフェーズ遷移を通知（G3: DO_FETCH_CONCURRENCY並列バッチ）
    const phaseOutcomes = await this.batchChatDoCalls(results, async (group) => {
      try {
        const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${group.group_id}`);
        const chatDO = this.env.CHAT_GAME_DO.get(doId);

        const response = await chatDO.fetch(this.chatDoRequest('/set-phase', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ phase: targetPhase, phaseEndTime })
        }));

        if (response.ok) return true;
        const errorData = await response.json().catch(() => ({}));
        console.error(`Failed to advance phase for group ${group.group_id}:`, errorData);
        return false;
      } catch (error) {
        console.error(`Error advancing phase for group ${group.group_id}:`, error);
        return false;
      }
    });
    // S3-006（2026-07-29）: 遷移できたグループの group_id だけを控える。
    // 旧実装は「1グループでも成功していれば block 内の全 row を次 phase へ flip」していた。
    // これは K-S2-004 で initChatGames 側を group 単位に直した効果を打ち消していた:
    // 初期化に失敗して formed のまま残った row まで chatting に飛ばしてしまうため、
    // watchdog の安全網（`status='formed'` が残っていたら init を再登録）が空振りし、
    // そのグループは未初期化のままチャット期間を通過する。
    const advancedGroupIds = [];
    for (let i = 0; i < phaseOutcomes.length; i++) {
      if (phaseOutcomes[i]) { advanced++; advancedGroupIds.push(results[i].group_id); }
      else errors++;
    }

    // D1のステータス更新（遷移できたグループのみ。失敗分は現在の status のまま残し、
    // 未初期化なら formed のまま＝watchdog の init 再登録対象に留まる）
    for (let i = 0; i < advancedGroupIds.length; i += D1_GROUP_ID_CHUNK) {
      const chunk = advancedGroupIds.slice(i, i + D1_GROUP_ID_CHUNK);
      await db.prepare(
        `UPDATE game_groups SET status = ? WHERE block_num = ? AND group_id IN (${chunk.map(() => '?').join(',')})`
      ).bind(targetPhase, blockNum, ...chunk).run();
    }

    console.log(`Phase advance to ${targetPhase}: ${advanced} success, ${errors} errors`);

    // 手動の開始・窓を失った後の終端も含め、全組が進めた時だけ開始関門の待ちを閉じる。
    if (['chatting', 'submitting', 'completed'].includes(targetPhase) && advanced > 0 && errors === 0) {
      await this.clearRosterGateTimelineWait(blockNum);
    }

    // 遅れた開始（案 U）の印は chatting の間だけ意味を持つ。ブロックが先へ進んだら消す（C31-08）。
    if ((targetPhase === 'submitting' || targetPhase === 'completed') && advanced > 0 && errors === 0) {
      await this.clearStartedWithRosterLate(blockNum);
    }

    // 🔴 ラウンド19 判断不要-4 (2)（2026-08-08）: フェーズの飛び越しを検知する（第三の網）。
    //    `submitting` / `completed` へ進むのに、まだ `chatting` を1度も通っていない
    //    （＝ `waiting` / `formed` のまま残っている）グループがあれば、そのグループの
    //    参加者は全員 `min_chars` / `min_messages` / `no_vote` で 0 点になる。
    //    遷移自体は止めない（止めるとそのグループが永久に終われない）が、
    //    マーカーを立てて `collectLifecycleBlockers` → `GET /calc-status` に出す。
    //    復旧は `POST /advance-phase {block_num, phase:'chatting'}`（既に chatting の
    //    グループには `{unchanged:true}` が返る冪等分岐なので副作用ゼロ）。
    // 🔴 R-2（2026-08-08・ラウンド20 回帰-2 ＝ J-32 の未列挙インスタンス）:
    //    旧実装は「直前 status が waiting/formed か」だけを見ていたので、
    //    **`chatting` のまま `completed` にされたグループ**（＝提出期間がまるごと消滅し、
    //    全員 `no_submit`）がマーカーにも `collectLifecycleBlockers` にも一切出なかった。
    //    到達経路は2つ:
    //      (a) `submitting` タスクが park しても `completed` タスクは別 `executeAt` の
    //          独立タスクとして発火する（park マーカーは立つので完全な無音ではない）
    //      (b) `POST /advance-phase {phase:'completed'}` は順序を検証しない
    //          （`test.js` のメニュー4に1キーで存在）＝**完全に無音**
    //    → 「その targetPhase に至るまでに通過していなければならない status」を表で持つ。
    const PHASE_PREREQ_MISSING = {
      submitting: ['waiting', 'formed'],
      completed: ['waiting', 'formed', 'chatting'],
    };
    if (PHASE_PREREQ_MISSING[targetPhase]) {
      const needs = PHASE_PREREQ_MISSING[targetPhase];
      const skipped = results.filter(g => needs.includes(g.status)).map(g => g.group_id);
      if (skipped.length > 0) {
        // 何を失ったかで文言を分ける（チャット窓を失ったのか、提出窓を失ったのか）。
        const lostChat = results.some(g => (g.status === 'waiting' || g.status === 'formed'));
        const lostSubmit = targetPhase === 'completed';
        const lost = lostChat && lostSubmit ? 'the chat window AND the submission window'
          : (lostChat ? 'the chat window' : 'the submission window');
        const damage = lostChat
          ? 'their members will score 0 (min_chars/min_messages/no_vote)'
          : 'their members will all be marked no_submit (nothing was submitted)';
        // ⚠️ 復旧導線ではなく**事後アラート**として書く。`completed` タスクの `executeAt` は宣言
        //    `completedAt`（＝`closeAt`＋確定待ち・timeline-check.js）なので、このマーカーが立つ時点で提出窓は既に閉じている。
        //    `phase:'submitting'` を案内しても `completed` からの後退は 409 になる。
        const recover = lostChat && !lostSubmit
          ? `Recover with POST /advance-phase {"block_num":${blockNum},"phase":"chatting"} if the chat window is still open.`
          : 'NOT recoverable by re-advancing (the declared window has already closed) — investigate the parked phase task / manual /advance-phase call.';
        console.error(
          `[phase] ⚠️ block ${blockNum}: group(s) ${skipped.join(',')} lost ${lost} `
          + `(status was ${[...new Set(results.filter(g => needs.includes(g.status)).map(g => g.status))].join('/')}) `
          + `but are being advanced to '${targetPhase}' — ${damage}. ${recover}`
        );
        try {
          await this.storage.put(`phase_skipped_block${blockNum}`, {
            blockNum, targetPhase, skippedGroupIds: skipped, lost, at: new Date().toISOString(),
          });
        } catch (_) { /* ログは既に出ている */ }
      }
    }

    // シャードDBのwin_blocks.game.phaseを更新
    try {
      const phaseResult = await this.updateGamePhaseToShards(blockNum, targetPhase);
      console.log(`Shard phase update: ${phaseResult.totalWritten} written, ${phaseResult.totalErrors} errors`);
    } catch (error) {
      const resumable = error?.resumable === true;
      const attempts = resumable ? 0 : 1;
      const delayMs = resumable ? 1000 : PHASE_TASK_RETRY_DELAY_MS;
      console.error(
        `Error updating shard phase for block ${blockNum}: ${error.message} `
        + `— queued retry in ${delayMs / 1000}s${resumable ? ' without consuming an attempt' : ''}`
      );
      await this.enqueuePhaseTask({
        type: 'phase_shard_update', blockNum, targetPhase, attempts,
        lastError: String(error?.message || error), executeAt: Date.now() + delayMs,
      });
    }

    // R2のblock-summary.jsonのステータスを更新（completed以外）
    if (targetPhase !== 'completed' && advanced > 0) {
      try {
        await this.updateBlockSummaryStatus(blockNum, targetPhase);
      } catch (err) {
        console.error(`Error updating block summary status in R2:`, err);
      }
    }

    // completedフェーズ: 結果計算実行
    if (targetPhase === 'completed') {
      try {
        const calcResult = await this.calculateAndStoreResults(blockNum);
        console.log(`Results calculated for block ${blockNum}:`, calcResult);
      } catch (error) {
        console.error(`Error calculating results for block ${blockNum}:`, error);
        // 失敗してもフェーズ遷移は成功させる（R2アーカイブから再計算可能）
      }
    }

    return {
      success: errors === 0,
      blockNum,
      targetPhase,
      totalGroups: results.length,
      advanced,
      errors
    };
  }

  // 宣言タイムライン解決（Evidence契約が正・v3.2）
  //   - パイプラインが早く終わった場合: 宣言時刻（chattingStart = entryEnd+grace）をそのまま返す
  //   - パイプラインが遅れた場合（now > 宣言chattingStart）: 先に extendGrace で宣言タイムラインを
  //     実態に合わせてから（遅延+バッファ分）返す＝窓が常に実ゲームをカバーする
  //   - Evidence 無効時: env RESULT_GRACE ベースの宣言タイムライン（動作は従来と同等）
  // initChatGames（waiting終了時刻の配布）と schedulePhaseTransitions（遷移アラーム）が
  // 同一タイムラインを共有するため、解決結果 { declared, graceSec } を受け渡しする。
  async resolveDeclaredTimeline(blockNum, { allowExtension = true } = {}) {
    let now = Date.now();
    let extensionUnconfirmed = false;

    // F-TL5: チェーンのタイムラインを同一ブロック高スナップショットで読み、宣言タイムラインは
    // その grace で組む（照合両辺の grace が構成上同一＝grace 起因の偽陽性なし）。スナップショット不可
    //（契約未設定/RPC失敗）は従来どおり env RESULT_GRACE フォールバックで続行し、照合はスキップ（可用性維持）。
    const chainTL = await this.readEvidenceTimelineSnapshot(blockNum);
    // ローカル時計が遅れていても、同じスナップショットのチェーン時刻より過去として
    // 開始判定しない。実運用のclock skew耐性に加え、将来時刻チェーンの再現試験でも
    // アンカー後の開始時刻を正しく延長できる。
    if (Number.isFinite(chainTL?.observedAtMs)) now = Math.max(now, chainTL.observedAtMs);
    if (chainTL) await this.rememberChainTimeline(blockNum, chainTL);   // S3-008: 最後に読めた窓を保存
    let graceSec = chainTL ? chainTL.graceSec
      : (this.env.RESULT_GRACE ? parseInt(this.env.RESULT_GRACE) : 120);
    let declared = this.getDeclaredTimesMs(blockNum, graceSec);

    // S3-008 是正（2026-07-29・ユーザー判断）: **チェーン照合ができないままゲームを開始しない。**
    //
    // 旧実装はスナップショットが読めないと照合をスキップして env の値で続行していた
    //（＝最も照合が必要な場面で保証が消える）。
    // 対処は「照合できるまで ChatGameDO を初期化しない」。初期化しなければ WS も P2P も
    // 始まらない（P2P も roster/group{G}.json を必要とし、それは初期化時に公開される）ので、
    // 待っている間に発言が採点窓の外へ漏れることはない。
    //
    // ただし `extendGrace` 自体の期限（契約の require(block.timestamp < chatCloseAt)）は
    // 待っていても進む。放置すると「もう延長できない＝正当に開始できない」状態に落ちるため、
    // **チェーンが読めている間は窓を先送りしてから**待機に入る（下の shieldStartWindow）。
    if (this.env.EVIDENCE_CONTRACT_ADDRESS && !chainTL) {
      try { await this.shieldStartWindow(blockNum, 'chain_unreadable'); }
      catch (shieldError) {
        console.warn(`[evidence] block ${blockNum}: start-window shield waiting for RPC quorum:`, shieldError?.message || shieldError);
      }
      const err = new Error(
        `[evidence] block ${blockNum}: Evidence timeline snapshot unavailable (all RPC endpoints failed) — ` +
        `refusing to start the game without env↔chain verification. Add an RPC endpoint via ` +
        `${RPC_LIST_ENV} or wait for recovery; grouping will retry automatically.`
      );
      err.timelineUnverified = true;
      err.timelineCause = 'chain_unreadable';
      err.rpcConfig = describeRpcConfig(this.env);
      throw err;
    }

    // F-TL5: 宣言タイムラインを使い始める前に env↔チェーンの一致を検証（不一致は throw でゲーム開始を
    // 停止）。grace 延長より前＝スナップショットと同じ grace で比較するため、必ずこの位置で行う。
    // S3-008: 不一致でも「開始できる権利」を失わないよう、throw の前に窓を先送りする。
    if (declared && chainTL) {
      try {
        await this.verifyEnvChainTimeline(blockNum, declared, chainTL);
      } catch (e) {
        await this.shieldStartWindow(blockNum, 'env_chain_mismatch');
        e.timelineUnverified = true;
        e.timelineCause = 'env_chain_mismatch';
        throw e;
      }
    }

    // env↔chain の検査は fresh chain grace で済ませた後、宣言ラッチを解決する。
    // 未着地 intent があればその目標を宣言として維持し、別 intent の着地や終端が見えたら
    // phase task と summary.timeline を actual chain grace へ即座に収束させる。
    if (this.env.EVIDENCE_CONTRACT_ADDRESS && chainTL) {
      const reconciled = await this.reconcileDeclaredGrace(blockNum, { chainTL, reschedule: true });
      if (Number.isSafeInteger(reconciled?.graceSec)) {
        graceSec = reconciled.graceSec;
        declared = this.getDeclaredTimesMs(blockNum, graceSec);
      }
    }

    if (!declared) {
      // S3-008（2026-07-29）: Evidence が設定されている＝オンチェーン窓が権威の構成なのに
      // START_TIME/BLOCK_TIME が無い場合、now 起点の相対スケジュールで開始してはいけない。
      // オンチェーンの chat/result 窓とまったく無関係な時刻でゲームが進み、
      //   ・参加者の Evidence 提出が窓外で全部拒否される（検閲対策の自己救済が効かない）
      //   ・サーバーだけが締切後の提出を受ける
      // という状態になる。設定事故を**開始前に**止めるのが F-TL5 の趣旨なので、ここは throw する。
      // 相対スケジュールは Evidence 未設定（ローカルテスト）に限る。
      if (this.env.EVIDENCE_CONTRACT_ADDRESS) {
        throw new Error(
          `[evidence] block ${blockNum}: EVIDENCE_CONTRACT_ADDRESS is configured but START_TIME/BLOCK_TIME are missing — ` +
          `refusing to start on a Date.now()-relative schedule (on-chain windows would not match). Fix the worker env.`
        );
      }
      // START_TIME/BLOCK_TIME 未設定（Evidence 無しのローカルテスト）: now 起点の相対スケジュール
      console.warn('[evidence] START_TIME/BLOCK_TIME not set — falling back to relative scheduling');
      declared = {
        chattingStart: now,
        submittingStart: now + this.gamePeriodMs,
        closeAt: now + this.gamePeriodMs + this.submitPeriodMs,
        completedAt: now + this.gamePeriodMs + this.submitPeriodMs + 30000
      };
    } else if (allowExtension && now > declared.chattingStart + 60000) {
      // 1〜60秒の alarm/初期化遅延は許容し、毎ブロックの無用な tx を避ける。
      // すでに chatting 以降のグループがある場合、開始後の延長はその発言を
      // 新しいチェーン窓の外へ追い出すため、旧タイムラインを維持する。
      let startedGroups = [];
      if (this.env.BITCOINU_DATA) {
        const { results = [] } = await this.env.BITCOINU_DATA.prepare(
          "SELECT group_id, status FROM game_groups WHERE block_num = ? AND status IN ('chatting','submitting','completed')"
        ).bind(blockNum).all();
        startedGroups = results;
      }
      if (startedGroups.length > 0) {
        const marker = {
          blockNum,
          groupIds: startedGroups.map((group) => Number(group.group_id)),
          statuses: startedGroups.map((group) => group.status),
          detectedAt: Date.now(),
          reason: 'grace extension suppressed after chatting started',
        };
        await this.storage.put(`timeline_started_no_extend_block${blockNum}`, marker);
        await sendAlertAndRecord(this.env, this.storage, {
          kind: 'timeline_split_prevented',
          subject: `[COINU] block ${blockNum} grace延長を中止`,
          body: `chatting以降のグループ (${marker.groupIds.join(',')}) が存在するため、既存発言を窓外にしないよう旧タイムラインを維持しました。`,
        }).catch((error) => console.error('[evidence] split-timeline alert failed:', error?.message || error));
        return { declared, graceSec, extensionSuppressed: true, startedGroupIds: marker.groupIds };
      }

      // パイプライン遅延: grace を実態＋バッファへ延長してから開始。
      const neededGraceSec = Math.ceil((now - declared.entryEndMs) / 1000) + 120;
      console.warn(`[evidence] pipeline late for block ${blockNum}: extending grace ${graceSec}s → ${neededGraceSec}s`);
      const res = await this.extendGraceOnChain(blockNum, neededGraceSec);
      if (!this.env.EVIDENCE_CONTRACT_ADDRESS) {
        graceSec = neededGraceSec; // Evidence無効: ローカル計算のみ（非永続）
        declared = this.getDeclaredTimesMs(blockNum, graceSec);
        return { declared, graceSec, ephemeralGrace: true };
      }
      const adoption = await this.adoptGraceExtensionResult(
        blockNum, neededGraceSec, res, 'pipeline_late', { reschedule: true },
      );
      if (adoption.adopted) {
        graceSec = adoption.graceSec;
      } else if (this.env.EVIDENCE_CONTRACT_ADDRESS) {
        // 同期終端/accepted:false は記録済み。既存の pending 宣言が無ければ、fresh snapshot で
        // 読んだ chain grace のまま進む。fallback 時は resolve 冒頭で開始自体を止めている。
        if (res?.reason !== 'started_with_roster') {
          console.error(`[evidence] extendGrace failed — retaining declared grace ${graceSec}s`);
          extensionUnconfirmed = true;
        } else {
          await this.noteStartedWithRosterLate(blockNum, 'pipeline_late', res);
        }
      }
      declared = this.getDeclaredTimesMs(blockNum, graceSec);
    }

    return { declared, graceSec, ...(extensionUnconfirmed ? { extensionUnconfirmed: true } : {}) };
  }

  // フェーズ遷移スケジュール設定（宣言タイムラインに従う）
  async schedulePhaseTransitions(blockNum, resolvedTimeline = null) {
    let stage = 'resolve_timeline';
    try {
      const { declared, graceSec } = resolvedTimeline || await this.resolveDeclaredTimeline(blockNum);

      const tasks = [
        { type: 'phase_transition', blockNum, targetPhase: 'chatting',
          executeAt: declared.chattingStart, phaseEndTime: declared.submittingStart,
          phaseEndTimeSource: 'scheduled_declared' },
        { type: 'phase_transition', blockNum, targetPhase: 'submitting',
          executeAt: declared.submittingStart, phaseEndTime: declared.closeAt,
          phaseEndTimeSource: 'scheduled_declared' },
        { type: 'phase_transition', blockNum, targetPhase: 'completed',
          executeAt: declared.completedAt, phaseEndTime: null,
          phaseEndTimeSource: 'none_completed' }
      ];

      // 既存のタスクキューに追加。
      // A6: 同一ブロックの既存phase_transitionタスクは置き換える（乗っ取りresumeの再実行で
      // 二重登録しない・宣言タイムライン再解決後の値が常に正）。
      stage = 'write_queue';
      let taskQueue = await this.storage.get('phase_task_queue') || [];
      taskQueue = taskQueue.filter(t => !(t.type === 'phase_transition' && t.blockNum === blockNum));
      taskQueue.push(...tasks);

      // executeAt順にソート
      taskQueue.sort((a, b) => a.executeAt - b.executeAt);
      await this.storage.put('phase_task_queue', taskQueue);

      // 最初のタスクのアラーム設定
      stage = 'set_alarm';
      const { alarmAt } = await this.armEarliestQueuedTask();
      this.deferGroupObservation(blockNum, {
        phaseSchedule: this.observationResult('succeeded', {
          graceSec,
          alarmAt,
          tasks: tasks.map(({ targetPhase, executeAt, phaseEndTime, phaseEndTimeSource }) => (
            { targetPhase, executeAt, phaseEndTime, phaseEndTimeSource }
          )),
        }),
      });

      console.log(`Scheduled phase transitions for block ${blockNum} (declared timeline, grace=${graceSec}s):`);
      for (const task of tasks) {
        console.log(`  ${task.targetPhase} at ${new Date(task.executeAt).toISOString()}`);
      }
      return { scheduled: true, graceSec, tasks };
    } catch (error) {
      this.deferGroupObservation(blockNum, {
        phaseSchedule: this.observationFailure(error, { stage }),
      });
      throw error;
    }
  }

  // ============================================================
  // 結果計算
  // ============================================================

  // ゲーム終了後のオンチェーン・ライフサイクル（TokenMining.getBlockLifecycle）を読む。
  // monitor / group-status で「オンチェーン提出→検証期間→請求期間→クローズ」を追えるようにする。
  // RPC/コントラクト未設定・読取失敗時は available:false（group-status本体は壊さない）。
  async readBlockLifecycle(blockNum, { fresh = false } = {}) {
    const contractAddr = this.env.TOKEN_MINING_CONTRACT_ADDRESS;
    if (!contractAddr) {
      return { available: false, reason: 'no_contract' };
    }
    const cacheKey = String(blockNum);
    const now = Date.now();
    if (!fresh) {
      const cached = this._blockLifecycleCache?.get(cacheKey);
      if (cached && cached.expiresAt > now) return cached.promise;
    }
    const publicClient = this.createReadOnlyClient();
    if (!publicClient) return { available: false, reason: 'no_rpc' };

    const promise = (async () => {
      try {
        const lc = await publicClient.readContract({
          address: getAddress(contractAddr), abi: TOKEN_MINING_ABI,
          functionName: 'getBlockLifecycle', args: [BigInt(blockNum)],
        });
        // viem は名前付き outputs をオブジェクトで返す
        const mode = Number(lc.mode ?? lc[0]);
        const stage = Number(lc.stage ?? lc[5]);
        const root = lc.merkleRoot ?? lc[1];
        const rootSubmitted = !!root && root !== `0x${'0'.repeat(64)}`;
        const toSec = v => Number(v ?? 0);
        return {
          available: true,
          contract: contractAddr,
          mode, modeName: TM_MODE_NAMES[mode] || `mode${mode}`,
          stage, stageName: TM_STAGE_NAMES[stage] || `stage${stage}`,
          merkleRoot: rootSubmitted ? root : null,
          rootSubmitted,
          verificationStartedAt: toSec(lc.verificationStartedAt ?? lc[2]),
          verificationEndsAt: toSec(lc.verificationEndsAt ?? lc[3]),
          claimEndsAt: toSec(lc.claimEndsAt ?? lc[4]),
          checkedAt: new Date().toISOString(),
        };
      } catch (e) {
        return { available: false, reason: 'read_error', error: e.shortMessage || e.message };
      }
    })();
    if (!fresh) {
      if (!this._blockLifecycleCache) this._blockLifecycleCache = new Map();
      for (const [key, value] of this._blockLifecycleCache) {
        if (value.expiresAt <= now) this._blockLifecycleCache.delete(key);
      }
      while (this._blockLifecycleCache.size >= BLOCK_LIFECYCLE_CACHE_LIMIT) {
        this._blockLifecycleCache.delete(this._blockLifecycleCache.keys().next().value);
      }
      this._blockLifecycleCache.set(cacheKey, {
        expiresAt: now + BLOCK_LIFECYCLE_CACHE_TTL_MS,
        promise,
      });
    }
    return promise;
  }

  // R15-10: 再計算が R2 / HashStorage を更新した後で adminCommit に拒否される順序を作らない。
  // restart の入口だけで getBlockLifecycle を1回読み、既存 root の検証期間が終わっていれば
  // fail-closed。検証期間中の差し替えは TokenMining の正規経路なので許可する。
  async assertResultRestartAccepted(blockNum) {
    // 状態変更の可否判定に30秒古い監視キャッシュを使わない。
    const lifecycle = await this.readBlockLifecycle(blockNum, { fresh: true });
    if (!lifecycle?.available) {
      const error = new Error(
        `result restart rejected: block ${blockNum} lifecycle unavailable (${lifecycle?.reason || 'unknown'})`
      );
      error.code = 'restart_lifecycle_unavailable';
      throw error;
    }
    if (!lifecycle.rootSubmitted) return lifecycle;

    const verificationEndsAt = Number(lifecycle.verificationEndsAt);
    if (!Number.isSafeInteger(verificationEndsAt) || verificationEndsAt <= 0) {
      const error = new Error(`result restart rejected: block ${blockNum} has invalid verificationEndsAt`);
      error.code = 'restart_lifecycle_invalid';
      throw error;
    }
    const nowSec = Math.floor(Date.now() / 1000);
    if (nowSec >= verificationEndsAt) {
      const error = new Error(
        `result restart rejected: block ${blockNum} verification ended at ${verificationEndsAt}`
      );
      error.code = 'verification_window_closed';
      throw error;
    }
    return lifecycle;
  }

  // 読み取り専用 publicClient（B1デポジット再検証用）。RPC未設定なら null。
  createReadOnlyClient() {
    // S3-008／D-05: RPC 一覧は lib/rpc-urls.js が読み取りの順で組む（ETHEREUM_MAINNET_RPC_URLS で本数無制限に追加可）
    const rpcUrls = rpcReadUrlsFromEnv(this.env);
    if (rpcUrls.length === 0) return null;
    const chainId = resolveEthChainId(this.env);
    const chain = chainId === 1 ? mainnet : defineChain({
      id: chainId, name: `chain-${chainId}`,
      nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
      rpcUrls: { default: { http: rpcUrls } },
    });
    const transport = rpcUrls.length > 1 ? fallback(rpcUrls.map(u => http(u))) : http(rpcUrls[0]);
    return createPublicClient({ chain, transport });
  }

  // Evidence 専用。登録ドメイン内は可用性のため fallback、登録ドメイン間は別 client の票。
  createEvidenceReadClients() {
    const urls = rpcReadUrlsFromEnv(this.env);
    const providers = new Map();
    for (const url of urls) {
      const key = rpcProvider(url);
      if (!providers.has(key)) providers.set(key, []);
      providers.get(key).push(url);
    }
    if (providers.size < 2) return null;
    const chainId = resolveEthChainId(this.env);
    const chain = chainId === 1 ? mainnet : defineChain({
      id: chainId, name: `chain-${chainId}`,
      nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
      rpcUrls: { default: { http: urls } },
    });
    return [...providers.values()].map((providerUrls) => createPublicClient({ chain,
      transport: providerUrls.length > 1
        ? fallback(providerUrls.map((url) => http(url))) : http(providerUrls[0]),
    }));
  }

  async noteRpcQuorumFailure(blockNum, error) {
    const key = `rpc_quorum_wait_block${blockNum}`;
    const previous = await this.storage.get(key);
    const now = Date.now();
    const firstSeenAt = previous?.firstSeenAt || now;
    await this.storage.put(key, { firstSeenAt, lastSeenAt: now,
      error: String(error?.message || error).slice(0, 400), alerted: previous?.alerted === true });
    if (now - firstSeenAt < RPC_QUORUM_ALERT_AFTER_MS || previous?.alerted) return;
    const result = await sendAlertAndRecord(this.env, this.storage, {
      kind: 'rpc_quorum_unavailable',
      subject: `[COINU][CRITICAL] GM の RPC 2本の一致を得られません: block ${blockNum}`,
      body: `blockNum=${blockNum}\nwaitMs=${now - firstSeenAt}\nreason=${String(error?.message || error).slice(0, 400)}\nGET /calc-status?block=${blockNum}`,
    }).catch((alertError) => {
      console.error('[rpc-quorum] alert failed:', alertError?.message || alertError);
      return null;
    });
    if (result?.sent) await this.storage.put(key, { firstSeenAt, lastSeenAt: now,
      error: String(error?.message || error).slice(0, 400), alerted: true });
  }

  async readEvidenceAtBlock(clients, block, address, abi, functionName, args = []) {
    return readMatchingContractAtHash(clients, block,
      { address, abi, functionName, args }, { encodeFunctionData, decodeFunctionResult });
  }

  hashStorageBindingError(code, message, cause = null) {
    const error = new Error(`${code}: ${message}`);
    error.code = code;
    if (cause) error.cause = cause;
    return error;
  }

  async assertHashStorageBinding(publicClient = null) {
    const tokenMiningRaw = this.env.TOKEN_MINING_CONTRACT_ADDRESS;
    const hashStorageRaw = this.env.HASH_STORAGE_CONTRACT_ADDRESS;
    if (!tokenMiningRaw) {
      throw this.hashStorageBindingError(
        'token_mining_not_configured',
        'TOKEN_MINING_CONTRACT_ADDRESS is not configured',
      );
    }
    if (!hashStorageRaw) {
      throw this.hashStorageBindingError(
        'hash_storage_not_configured',
        'HASH_STORAGE_CONTRACT_ADDRESS is not configured',
      );
    }

    let tokenMining;
    let hashStorage;
    try {
      tokenMining = getAddress(tokenMiningRaw);
      hashStorage = getAddress(hashStorageRaw);
    } catch (cause) {
      throw this.hashStorageBindingError(
        'hash_storage_binding_invalid_config',
        'TokenMining or HashStorage address is invalid',
        cause,
      );
    }
    const key = `${tokenMining.toLowerCase()}:${hashStorage.toLowerCase()}`;
    if (this._hashStorageBindingCache?.key === key) {
      return this._hashStorageBindingCache.promise;
    }

    const client = publicClient || this.createReadOnlyClient();
    if (!client) {
      throw this.hashStorageBindingError(
        'hash_storage_binding_read_failed',
        `no RPC endpoint configured (${RPC_LIST_ENV})`,
      );
    }
    const promise = (async () => {
      let linkedRaw;
      try {
        linkedRaw = await client.readContract({
          address: tokenMining,
          abi: TOKEN_MINING_ABI,
          functionName: 'hashStorage',
        });
      } catch (cause) {
        throw this.hashStorageBindingError(
          'hash_storage_binding_read_failed',
          'TokenMining.hashStorage() RPC read failed',
          cause,
        );
      }
      let linked;
      try {
        linked = getAddress(linkedRaw);
      } catch (cause) {
        throw this.hashStorageBindingError(
          'hash_storage_binding_read_failed',
          'TokenMining.hashStorage() returned an invalid address',
          cause,
        );
      }
      if (linked.toLowerCase() !== hashStorage.toLowerCase()) {
        throw this.hashStorageBindingError(
          'hash_storage_mismatch',
          `TokenMining.hashStorage=${linked} configured=${hashStorage}`,
        );
      }
      return { ok: true, tokenMining, hashStorage, linked };
    })();
    this._hashStorageBindingCache = { key, promise };
    try {
      return await promise;
    } catch (error) {
      if (this._hashStorageBindingCache?.promise === promise) {
        this._hashStorageBindingCache = null;
      }
      throw error;
    }
  }

  // B1: uidごとのdepositIdリストをEthLockから権威的にオンチェーン再検証する共通コア。
  //   各depositをEthLockから再読込し、
  //     ① unlockTime >= START_TIME + (N+2) × BLOCK_TIME（ロック窓）
  //     ② idTo === 当該プレイヤー（E4: strict JSON {"id":...} のみ受理）
  //     ③ amount > 0（不変 amount の破損データ/非存在ガード。正規デポジットは常に > 0）
  //   を満たすもののみ「適格」とする。
  //   ★ 新 EthLock は引き出しても amount を原額保存し withdrawn=true を立てる。ゲームブロック適格な
  //     デポジットの引き出しは（早期解禁 `> fromBlock` 修正により）通常/早期いずれも締切より後になるため、
  //     withdrawn の預金も「締切時点スナップショット＝原額」で計上する（withdrawn では除外しない。
  //     除外すると grace 遅延時に正当な引き出し済みを 0 扱いする旧バグを再導入するため）。
  //   同じdepositIdの申告が複数あっても、各 (depositId, uid) を独立に②で判定する。
  //   String(idTo) と完全一致できる正準uidは高々1つなので、正当な持ち主を巻き添えにしない。
  //   戻り値: {
  //     verifiedDepositWei:  { [uid]: 適格wei合計文字列 }（デポジットポイント計算用）,
  //     verifiedDeposits:    { [uid]: [{ depositId, amount, depositerAddress, idFrom }] }
  //                          （デポジッター配当用。depositId昇順＝決定論的順序。
  //                           depositerAddress/amount/idFromは全てオンチェーン値＝
  //                           運営がD1/R2キャッシュを書き換えても配当先・金額を変更できない）
  //   }
  //   オンチェーン読取が失敗した場合は throw（サイレントに0点にしない）。
  async verifyDepositsOnChainForUids(blockNum, perUid) {
    // A1/Q7: チャンク実行パイプラインと共有する3部品
    // （distinct ID列挙→チェーン読取→uidごとの適格フィルタ）を合成する。
    const { uniqueIds } = this.calcCollectDepositIds(blockNum, perUid);
    const k11 = await this.readDepositSelectionK11(blockNum);
    const { chainData, failedReads, archiveFailedReads } = await this.calcFetchDepositsFromChain(uniqueIds, k11);
    if (failedReads.length > 0) {
      const error = new Error(`[B1] ${archiveFailedReads?.length ? 'archive_rpc_required: historical EthLock state unavailable; ' : ''}on-chain deposit reads failed for ${failedReads.length}/${uniqueIds.length} ids (first: ${failedReads[0]}) — aborting`);
      if (archiveFailedReads?.length) { error.code = 'archive_rpc_required'; error.terminal = true; }
      throw error;
    }
    const result = this.calcFilterEligibleDeposits(blockNum, perUid, chainData);
    console.log(`[B1] block ${blockNum}: on-chain verified deposits for ${Object.keys(result.verifiedDepositWei).length} players (${uniqueIds.length} distinct ids)`);
    return result;
  }

  // B1部品①: ブロック内の全正準depositIdをdistinct列挙（決定論的・純粋関数）。
  // Q7: 誰が何回申告しても同じuint256 IDは1回だけ読む。無効IDは葉を作らない側へ倒す。
  calcCollectDepositIds(blockNum, perUid) {
    const distinctIds = new Set();
    for (const ids of Object.values(perUid)) {
      for (const rawId of (Array.isArray(ids) ? ids : [])) {
        try {
          const canonicalId = canonicalizeDepositId(rawId);
          if (canonicalId !== rawId) continue;
          distinctIds.add(canonicalId);
        } catch {
          // entry authority が壊れていても不正なIDをRPCへ渡さず、その申告だけを不適格にする。
        }
      }
    }
    if (distinctIds.size > MAX_CHAIN_DEPOSIT_READS) {
      throw new Error(
        `[B1] block ${blockNum}: on-chain deposit read limit exceeded ` +
        `(${distinctIds.size}/${MAX_CHAIN_DEPOSIT_READS} distinct ids) — aborting`
      );
    }
    // BigInt昇順でチャンク実行時のカーソルを安定させる（Number化で精度を落とさない）。
    const uniqueIds = [...distinctIds].sort((a, b) => {
      const x = BigInt(a); const y = BigInt(b);
      return x < y ? -1 : x > y ? 1 : 0;
    });
    return { uniqueIds };
  }

  // 抽選の基準のブロックは公開 selection の値だけから取る。欠落・不正なら RPC を始めない。
  async readDepositSelectionK11(blockNum) {
    const selection = await this.getR2Object(`entries/block${blockNum}/game_selection.json`);
    const target = selection?.targetBlockNum;
    if (!Number.isSafeInteger(target) || target < 0) {
      throw new Error(`[B1] invalid K11 targetBlockNum in game_selection.json for block ${blockNum}`);
    }
    return BigInt(target);
  }

  // 過去 state の欠落を示す応答だけを数える。header not found はノードの追随遅延でも起きる。
  // 他クライアントの文言は代表例であり、実 RPC では未確認（OPS §8.6）。
  isArchiveStateUnavailable(error) {
    const detail = [error?.shortMessage, error?.message, error?.cause?.message].filter(Boolean).join(' ');
    return !/header not found/i.test(detail)
      && /missing trie node|state not available|no state available for block|world state unavailable|state at block .* pruned|history has been pruned|historical state|pruned state|archive (?:node|state)/i.test(detail);
  }

  // B1部品②: EthLockからのgetLock読取（並列バッチ）。高さ省略の表示専用呼出しは latest。
  async calcFetchDepositsFromChain(ids, blockNumber = undefined) {
    const ethLockAddr = this.env.ETH_LOCK_CONTRACT_ADDRESS;
    const publicClient = this.createReadOnlyClient();
    if (!ethLockAddr || !publicClient) {
      const missing = [];
      if (!ethLockAddr) missing.push('ETH_LOCK_CONTRACT_ADDRESS');
      if (!publicClient) missing.push('ETHEREUM_MAINNET_RPC_URL');
      throw new Error(`B1 deposit verification requires env: ${missing.join(', ')}`);
    }
    const chainData = {};
    const archiveFailedReads = [];
    const readErrors = new Map();
    const endpointResponses = [];
    // viem fallback は最後の endpoint のエラーだけを投げる。全 endpoint の応答を
    // 観測し、一時障害が1本でも混ざれば archive 不足として即 park しない。
    publicClient.transport?.onResponse?.((response) => endpointResponses.push(response));
    const READ_CONCURRENCY = 10;
    for (let i = 0; i < ids.length; i += READ_CONCURRENCY) {
      const batch = ids.slice(i, i + READ_CONCURRENCY);
      const res = await Promise.all(batch.map(async (id) => {
        try {
          const dep = await publicClient.readContract({
            address: getAddress(ethLockAddr), abi: ETH_LOCK_ABI,
            functionName: 'getLock', args: [BigInt(id)],
            ...(blockNumber === undefined ? {} : { blockNumber }),
          });
          return [id, {
            ...dep,
            depositerAddress: dep.lockOwnerAddress,
            withdrawn: dep.unlocked,
          }];
        } catch (e) {
          console.error(`[B1] getLock(${id}) read failed: ${e.shortMessage || e.message}`);
          readErrors.set(id, e);
          return [id, null];
        }
      }));
      for (const [id, dep] of res) chainData[id] = dep;
    }
    const failedReads = ids.filter(id => !chainData[id]);
    const responses = endpointResponses.filter((response) => response.method === 'eth_call');
    const allReadsLackHistory = blockNumber !== undefined && failedReads.length > 0
      && (responses.length > 0
        ? responses.every((response) => response.status === 'error'
          && this.isArchiveStateUnavailable(response.error))
        : failedReads.every((id) => this.isArchiveStateUnavailable(readErrors.get(id))));
    if (allReadsLackHistory) archiveFailedReads.push(...failedReads);
    return { chainData, failedReads, archiveFailedReads };
  }

  // B1部品③: 適格判定・合算（純粋関数。chainDataの値はBigIntでも文字列化済みでも受理）
  calcFilterEligibleDeposits(blockNum, perUid, chainData) {
    const startTime = this.env.START_TIME ? (Number(this.env.START_TIME) || Date.parse(this.env.START_TIME)) : NaN;
    const blockTime = this.env.BLOCK_TIME ? parseInt(this.env.BLOCK_TIME) : NaN;
    if (!Number.isFinite(startTime) || !Number.isFinite(blockTime)) {
      const missing = [];
      if (!Number.isFinite(startTime)) missing.push('START_TIME');
      if (!Number.isFinite(blockTime)) missing.push('BLOCK_TIME');
      throw new Error(`B1 deposit verification requires env: ${missing.join(', ')}`);
    }
    const requiredLockUntilMs = startTime + (blockNum + 2) * blockTime;
    // idFrom（寄付者の X ユーザーID）: 2026-08-01 以降は EthLock 上で **uint256**。
    // JSON パースは廃止（表示用の name / profile_image_url は profileFrom へ分離された）。
    // 0 は EthLock が deposit() 時点で拒否するので「未設定」を意味する。
    const parseIdFromUid = (idFrom) => {
      if (idFrom == null) return null;
      const s = String(idFrom);
      if (!/^\d+$/.test(s) || s === '0') return null;
      return BigInt(s).toString();   // 正準10進（先頭0なし）
    };

    // uidごとに適格デポジットを抽出・合算（depositId昇順＝検証ツールが再現できる決定論的順序）
    // 🔴 P-2026-0820（2026-08-07）: uid を鍵にする辞書は **`Object.create(null)`**。
    //    `isCanonicalUid` は `/^[\x21-\x7E]+$/` を許すので uid に `__proto__` を置ける。
    //    素の `{}` だと `m['__proto__'] = v` が setter を叩くだけで own property にならず、
    //    その uid が辞書から**黙って落ちて**自己申告デポジットへフォールバックする
    //    （＝オンチェーン権威検証を1文字で迂回できる）。読み側だけ直しても塞がらない。
    const verifiedDepositWei = Object.create(null);
    const verifiedDeposits = Object.create(null);
    for (const [uid, ids] of Object.entries(perUid)) {
      let sum = 0n;
      const eligible = [];
      // Q7: 破損したauthority入力でも1 uid内の同じuint256 IDは集合として1回だけ扱う。
      const validIds = [];
      for (const rawId of (Array.isArray(ids) ? ids : [])) {
        try {
          const canonicalId = canonicalizeDepositId(rawId);
          if (canonicalId !== rawId) continue;
          validIds.push(canonicalId);
        } catch { /* 不正IDは不適格 */ }
      }
      const sortedIds = [...new Set(validIds)].sort((a, b) => {
        const x = BigInt(a); const y = BigInt(b);
        return x < y ? -1 : x > y ? 1 : 0;
      });
      for (const id of sortedIds) {
        const dep = chainData[id];
        if (!dep) continue;

        // E4 / 請求データ自己完結化（2026-08-01）: idTo は EthLock 上で **uint256**。
        // Q7: viem が uint256 を bigint としてdecodeした `String(dep.idTo)`（先頭ゼロ・符号なし）と
        // uidの正準十進文字列をbyte-exactに照合する。TokenMining._parseUint は先頭ゼロを弾かないため、
        // この正典は契約より**厳しい**。不一致では葉を作らず請求されない fail-closed であり、
        // 「正典が緩く、契約が弾くIDを葉へ入れる」という最悪の失敗方向とは逆である。
        // `"01"` / `"+1"` のような数値別名を同じidToへ成立させず、二重計上を構造的に防ぐ。
        const uidStr = String(uid);
        if (!/^\d{1,20}$/.test(uidStr) || BigInt(uidStr) === 0n) continue;
        const idToStr = String(dep.idTo ?? '');
        if (!/^\d+$/.test(idToStr)) continue;
        if (idToStr === '0') continue;                     // EthLock が 0 を拒否＝未設定
        if (idToStr !== uidStr) continue;

        // B1: ロック窓（unlockTimeはunix秒）
        if (Number(dep.unlockTime) * 1000 < requiredLockUntilMs) continue;

        // amount=0（非存在/破損データ）は除外。
        // ★ 新 EthLock（不変 amount・引き出しても amount 保存）では、引き出し済みでも amount>0 なので
        //   ここで計上される。通常の引き出しは締切より後（早期解禁は (K+1)*BLOCK_INTERVAL 以降）なので、
        //   締切時点スナップショット＝原額を計上するのが正しい。旧 EthLock（amount=0 リセット）の
        //   「引き出し済みを 0 扱いで誤除外」問題は契約側の是正で解消。
        const amount = BigInt(dep.amount);
        if (amount <= 0n) continue;

        sum += amount;
        eligible.push({
          depositId: id,
          amount: amount.toString(),
          depositerAddress: dep.depositerAddress,
          idFrom: parseIdFromUid(dep.idFrom)
        });
      }
      verifiedDepositWei[uid] = sum.toString();
      verifiedDeposits[uid] = eligible;
    }
    return { verifiedDepositWei, verifiedDeposits };
  }

  // ⚠️ 旧 `verifySignedDepositsOnChain`（提出物の depositIds を権威とするラッパー）は
  //    **2026-08-01 に削除した**。K-S2-002 で depositId 一覧の権威は
  //    「エントリー時の depIds（game_selection.json・applicantHash でオンチェーン固定）」に
  //    移っており（calcDepidsUnit / autoDistribute / block-verifier のいずれも entry depIds）、
  //    提出物起点の実装は **応募締切後に作ったデポジットを後出しで足せる**旧脆弱性そのもの。
  //    呼び出し元が無いまま残しておくと、いつか誰かが呼んで脆弱性が復活する。
  //    入口は verifyDepositsOnChainForUids(blockNum, perUid) 一本に統一する。

  // ============================================================
  // A1是正（2026-07-16）: 結果集計のチャンク化・再開可能パイプライン
  // 旧実装は全グループ分を1回のDO呼び出しで処理し、2100人/約525グループ規模では
  // サブリクエスト(約4,300-8,000 vs WORKER_SUBREQUEST_LIMIT)・CPU(署名検証50-800s vs 約30s)・
  // メモリ(260MB-1.3GB vs 128MB)の3上限に同時violationしていた（②監査 A1/H1-H3）。
  // 本実装はステージ×カーソルで分割し、進捗を calc_block{N}_progress に永続化。
  // 途中死しても次のalarm/driveで続きから再開する（採点・報酬・公開アーティファクトの
  // 意味論は旧モノリスと完全同一。報酬按分ブロックは block-verifier ミラー台帳
  // (VENDOR_SYNC.md mirrorRewardSplit) の対象領域そのまま・バイト無変更）。
  //
  // ステージ: evidence → depids → chain → vdep → scoring → rewards → writing
  //           → shards → summary → merkle → manifest → proofs → zkProof → adminCommit → cleanup → done
  //   🔴 2026-08-10 G2: `zkProof` を proofs と adminCommit の間へ追加し、
  //      実装は15ステージ（dispatch の `case` 群・予算表・遷移集合すべて一致）。
  //      この2つは飾りではなく**「オンチェーン提出を最後に置く」設計そのもの**で、
  //      `adminCommit`（root 提出＝唯一の最終コミット点）の手前で `proofs` を揃えることで
  //      「proof 欠落のまま請求期間に入る」を構造的に防いでいる（S3-010）。
  // 冪等性: D1はUPSERT・R2は同一内容put・DOストレージは上書き・チェーン読取は読取専用・
  // merkle/manifest提出は同一値スキップ内蔵 → どのユニットも安全に再実行できる。
  // ============================================================

  // operator_bypassの入力理由はfallback後にも複数の診断記録へ写る。公開表示では全て伏せる。
  calcStatusZkpRecord(record, { deep = false } = {}) {
    if (!record || deep) return record;
    const publicRecord = { ...record };
    delete publicRecord.operatorFallbackReason;
    if (record.fallbackReason === 'operator_bypass' || record.reason === 'operator_bypass') {
      for (const field of ['fallbackDetail', 'detail', 'lastError']) {
        if (Object.hasOwn(publicRecord, field)) publicRecord[field] = null;
      }
    }
    return publicRecord;
  }

  slimCalcProgress(p, { deep = false } = {}) {
    if (!p) return null;
    return {
      blockNum: p.blockNum,
      stage: p.stage ?? null,
      cursor: p.cursor ?? 0,
      evidenceFinal: p.evidenceFinal
        ? { seq: p.evidenceFinal.cursor, invalidCount: p.evidenceFinal.invalidCount,
            adoptedCount: p.evidenceFinal.adoptedCount }
        : null,
      evidenceReport: p.summaryPhase === 'evidence_report' && p.evidenceReport
        ? { mode: p.evidenceReport.mode, invalidChunk: p.evidenceReport.chunk,
            partNumber: p.evidenceReport.partNumber,
            partByteOffset: (p.evidenceReport.partNumber - 1) * CALC_EVIDENCE_REPORT_PART_BYTES }
        : null,
      done: p.stage === 'done',
      parked: !!p.parked,
      failures: p.failures ?? 0,
      lostRuns: p.lostRuns ?? 0,
      lastError: p.lastError ?? null,
      archiveRpcRequired: /archive_rpc_required/.test(String(p.lastError || '')),
      groupArchiveFailures: Array.isArray(p.groupArchiveFailures) ? p.groupArchiveFailures : [],
      startedAt: p.startedAt ?? null,
      updatedAt: p.updatedAt ?? null,
      // K-S5-002: 自発待機（park ではない＝手動介入は不要だが、見えないと不安になる）
      waiting: p.waitUntil && Date.now() < p.waitUntil
        ? { reason: p.waitReason ?? null, until: p.waitUntil, detail: p.waitDetail ?? null }
        : null,
      // 🔴 C-1 / ラウンド19 判断不要-3（2026-08-08）: manifest 段の結果を監視面に出す。
      verification: p.verification
        ? { ok: !!p.verification.ok, manifestHash: p.verification.manifestHash ?? null, error: p.verification.error ?? null }
        : null,
      zkProof: p.zkProof
        ? this.calcStatusZkpRecord({
            required: !!p.zkProof.required,
            status: p.zkProof.status ?? null,
            jobId: p.zkProof.jobId ?? null,
            inputHash: p.zkProof.inputHash ?? null,
            requestedAt: p.zkProof.requestedAt ?? null,
            normalWait: p.stage === 'zkProof' ? p.zkProof.normalWait ?? null : null,
            evidenceWindowWait: p.stage === 'zkProof' ? p.zkProof.evidenceWindowWait ?? null : null,
            verifiedAt: p.zkProof.verifiedAt ?? null,
            attempt: p.zkProof.attempt ?? null,
            attemptHistory: p.zkProof.attemptHistory ?? [],
            failure: p.zkProof.failure ?? null,
            contradiction: p.zkProof.contradiction ?? null,
            monitor: p.zkProof.monitor ?? null,
            severity: p.zkProof.severity ?? null,
            stale: p.zkProof.stale ?? null,
            fallbackReason: p.zkProof.fallbackReason ?? null,
            fallbackDetail: p.zkProof.fallbackDetail ?? null,
            fallbackAt: p.zkProof.fallbackAt ?? null,
            lastError: p.zkProof.lastError ?? null,
          }, { deep })
        : null,
    };
  }

  calcProgressKey(blockNum) { return `calc_block${blockNum}_progress`; }
  calcKey(blockNum, ...parts) { return `calc:${blockNum}:${parts.join(':')}`; }
  calcCancelKey(blockNum) { return `calc_cancelled:${blockNum}`; }
  calcRestartRequestKey(blockNum) { return `calc_restart_requested:${blockNum}`; }
  calcFallbackRequestKey(blockNum) { return `calc_fallback_requested:${blockNum}`; }
  calcFallbackRejectedKey(blockNum) { return `calc_fallback_rejected:${blockNum}`; }

  async deleteCalcFallbackRequest(blockNum, request) {
    const current = await this.storage.get(this.calcFallbackRequestKey(blockNum));
    if (current?.requestId === request.requestId) {
      await this.storage.delete(this.calcFallbackRequestKey(blockNum));
    }
  }

  async rejectCalcFallbackRequest(blockNum, request, reason) {
    const current = await this.storage.get(this.calcFallbackRequestKey(blockNum));
    if (current?.requestId !== request.requestId) return;
    // 却下も先に永続化する。delete失敗後は、この印で適用への逆戻りを防ぐ。
    await this.storage.put(this.calcFallbackRejectedKey(blockNum), {
      blockNum, at: Date.now(), reason, request,
    });
    await this.deleteCalcFallbackRequest(blockNum, request);
  }

  calcFallbackGenerationRejection(request, progress) {
    if (request.targetStartedAt == null || !progress) return 'progress_missing';
    if (progress.startedAt !== request.targetStartedAt
      || (progress.runId ?? null) !== (request.targetRunId ?? null)) return 'generation_changed';
    if (progress.stage === 'done') return 'run_done';
    return null;
  }
  calcRestartRejectedKey(blockNum) { return `calc_restart_rejected_${blockNum}`; }

  async collectAdminTxPending(blockNum = null) {
    const status = await getAdminTxCoordinatorStatus(this.env);
    if (!status.ok) {
      return { count: 0, queued: null, reasons: { [status.reason || 'coordinator_unavailable']: 1 }, items: [], coordinator: status };
    }
    const active = status.inflight;
    const matches = active && (blockNum == null || Number(active.blockNum) === Number(blockNum));
    const activeItems = matches ? [{
      key: active.intentId,
      blockNum: active.blockNum ?? null,
      label: active.operation ?? null,
      txHash: active.txHash || null,
      nonce: active.nonce ?? null,
      attempts: active.attempts ?? null,
      reason: active.reason || 'receipt_pending',
      status: active.status || null,
    }] : [];
    const signerRotationDiscards = (Array.isArray(status.signerRotationDiscards)
      ? status.signerRotationDiscards : [])
      .filter((row) => blockNum == null || Number(row?.blockNum) === Number(blockNum));
    // 既存monitorは items/count を赤表示するため、手動再実行待ちの破棄も同じ一覧へ載せる。
    // pendingとは区別できるよう status=failed と元reason・manualRetryRequiredを保つ。
    const discardItems = signerRotationDiscards.map((row) => ({
      key: row?.intentId ?? null,
      blockNum: row?.blockNum ?? null,
      label: row?.operation ?? null,
      txHash: row?.txHash || null,
      nonce: row?.nonce ?? null,
      attempts: row?.attempts ?? null,
      reason: row?.reason || 'signer_rotation_requires_manual_retry',
      status: 'failed',
      manualRetryRequired: row?.manualRetryRequired !== false,
      mayStillConfirm: row?.mayStillConfirm === true,
      signerAddress: row?.signerAddress ?? null,
      currentSignerAddress: row?.currentSignerAddress ?? null,
      discardedAt: row?.discardedAt ?? null,
    }));
    const items = [...activeItems, ...discardItems];
    const reasons = {};
    for (const item of items) reasons[item.reason || 'receipt_pending'] = (reasons[item.reason || 'receipt_pending'] || 0) + 1;
    return {
      count: items.length,
      queued: status.queued ?? null,
      queuedIntents: Array.isArray(status.queuedIntents) ? status.queuedIntents : [],
      reasons,
      items,
      signerRotationDiscards,
      coordinator: { ok: true, alerts: status.alerts || null },
    };
  }

  async recordCalcRestartRejected(blockNum, request, error) {
    try {
      await this.storage.put(this.calcRestartRejectedKey(blockNum), {
        blockNum,
        request,
        errorCode: error?.code || 'restart_rejected',
        error: String(error?.message || error),
        rejectedAt: Date.now(),
      });
    } catch (_) { /* 元の restart 拒否をストレージ障害で置き換えない */ }
  }

  // no-game／2名以下自動配布は D1 game_groups が0件なので、完了後の確認目的の
  // /calculate-results を暗黙restartすると、正常なdoneを消した直後に No groups found で止まる。
  // 明示 restart=true は尊重し、暗黙restartは通常ゲームの完了結果だけに限定する。
  shouldAutoRestartCalc(progress) {
    if (progress?.stage !== 'done') return false;
    return Number(progress?.result?.groupCount ?? progress?.groupCount ?? 0) > 0;
  }

  // 集計が最終コミットまで完了した後に、途中のreceipt timeout等で残った診断だけを消す。
  // no-game/自動配布は grouping の呼出し元が一度 failed になっても、継続キュー側の calc が
  // proof/root提出を完遂できる。その場合は calc の確定結果を根拠に grouping も completed へ
  // 収束させ、正常ブロックを恒久的な lifecycle blocker として表示し続けない。
  async normalizeCompletedCalcProgress(blockNum, progress) {
    if (progress?.stage !== 'done') return progress;
    const rootSubmitted = progress.result?.merkle?.submit?.submitted === true;
    // groupingの呼出し元より先に継続キューがroot提出を終えた場合も、関門の待ちを終端する。
    if (rootSubmitted) await this.clearRosterGateTimelineWait(blockNum);
    let changed = false;
    const clearField = (field) => {
      if (Object.prototype.hasOwnProperty.call(progress, field)) {
        delete progress[field];
        changed = true;
      }
    };
    if (progress.failures !== 0) { progress.failures = 0; changed = true; }
    if (progress.parked) { progress.parked = false; changed = true; }
    if (progress.lastError != null) { progress.lastError = null; changed = true; }
    clearField('waitUntil'); clearField('waitReason'); clearField('waitDetail');
    if (progress.zkProof?.evidenceWindowWait) {
      delete progress.zkProof.evidenceWindowWait; changed = true;
    }
    if (progress.zkProof?.lastError != null) {
      progress.zkProof = { ...progress.zkProof, lastError: null };
      changed = true;
    }
    // cleanup完了後に旧実装の表示だけRUNNINGのまま残った履歴も、確定済みrootとverified proofを
    // 根拠にterminal表示へ収束させる。root未提出・未検証attemptは変更しない。
    if (rootSubmitted && progress.zkProof?.status === 'verified'
      && progress.zkProof?.attempt
      && (progress.zkProof.attempt.state !== 'CLEANED' || progress.zkProof.attempt.taskState != null)) {
      const { taskState: _staleTaskState, ...cleanedAttempt } = progress.zkProof.attempt;
      progress.zkProof = {
        ...progress.zkProof,
        attempt: { ...cleanedAttempt, state: 'CLEANED' },
      };
      changed = true;
    }
    if (changed) {
      progress.updatedAt = Date.now();
      await this.storage.put(this.calcProgressKey(blockNum), progress);
    }

    const groupCount = Number(progress.result?.groupCount ?? progress.groupCount ?? -1);
    if (groupCount === 0 && rootSubmitted) {
      const key = `grouping_block${blockNum}_progress`;
      const grouping = await this.storage.get(key);
      const finalizingPhase = grouping?.phase === 'no_game_finalizing' || grouping?.phase === 'auto_distributing';
      if ((grouping?.status === 'failed' || grouping?.status === 'parked') && finalizingPhase) {
        const wasNoGame = grouping.phase === 'no_game_finalizing';
        grouping.status = 'completed';
        grouping.phase = 'completed';
        grouping.completedAt ||= new Date().toISOString();
        grouping.totalGroups = 0;
        grouping.resumable = false;
        grouping.error = null;
        if (['auto_distribution_proof_pending', 'evidence_window_pending'].includes(grouping.waitReason)) {
          delete grouping.waitReason; delete grouping.waitUntil; delete grouping.waitDetail;
        }
        if (wasNoGame) grouping.noGame = true;
        else grouping.autoDistributed = true;
        delete grouping.parkedAt;
        await this.storage.put(key, grouping);
      }
    }
    return progress;
  }

  // 呼び出し元互換の入口（advancePhase / POST /calculate-results / /reconcile-evidence）。
  // 完了時は旧モノリスと同形の結果を返す。予算内に終わらない場合は {pending:true,...} を返し、
  // 継続タスクを phase_task_queue に登録してalarm駆動で続行する
  // （小規模ブロックでは常に1回で同期完了＝従来挙動と同じ）。
  async calculateAndStoreResults(blockNum, opts = {}) {
    const ownerState = await this.calcAdminTxWaitState(blockNum);
    if (ownerState.parked) {
      return this.calcGroupingParkedResult(blockNum,
        await this.storage.get(this.calcProgressKey(blockNum)), ownerState);
    }
    if (this._calcDriving) {
      // レビューM1: 別ブロックのdrive中に到着した計算要求を無言で落とさない。
      // 継続タスクを積んでおけば、進捗未初期化でもalarm経由のdriveが初期化から実行する。
      // B10-04: reconcile の restart 要求も durable に積む。単なる calc_chunk だけでは
      // 次の drive が既存進捗を resume し、Evidence を再照合しないまま終わり得る。
      const targetProgress = opts.zkpFallback
        ? await this.storage.get(this.calcProgressKey(blockNum)) : null;
      let restartRequestId = opts.restart ? crypto.randomUUID() : null;
      if (opts.restart) {
        await this.storage.put(this.calcRestartRequestKey(blockNum), {
          blockNum,
          requestId: restartRequestId,
          requestedAt: Date.now(),
          unpark: opts.unpark === true,
        });
      }
      if (opts.zkpFallback) {
        const previous = await this.storage.get(this.calcFallbackRequestKey(blockNum));
        const targetStartedAt = targetProgress?.startedAt ?? null;
        // 同じ要求のrestartがまだ未消費なら、再送もその作り直しに結び付ける。
        if (!opts.restart && previous?.restartRequestId) {
          const pendingRestart = await this.storage.get(this.calcRestartRequestKey(blockNum));
          if (pendingRestart?.requestId === previous.restartRequestId) {
            restartRequestId = previous.restartRequestId;
          }
        }
        // 後のmode/理由だけを上書きするのは同じrunへの要求だけ。
        const sameTarget = targetStartedAt != null && previous?.targetStartedAt === targetStartedAt
          && (previous?.targetRunId ?? null) === (targetProgress?.runId ?? null)
          && previous?.restartRequestId === restartRequestId;
        if (previous) await this.rejectCalcFallbackRequest(blockNum, previous, 'replaced');
        await this.storage.put(this.calcFallbackRequestKey(blockNum), {
          blockNum,
          requestId: crypto.randomUUID(),
          targetStartedAt,
          targetRunId: targetProgress?.runId ?? null,
          restartRequestId,
          requestedAt: (sameTarget && previous?.requestedAt) || Date.now(),
          abandon: opts.zkpAbandon === true,
          reason: opts.zkpFallbackReason || 'operator_requested',
          unpark: opts.unpark === true || (sameTarget && previous?.unpark === true),
        });
      }
      await this.enqueueCalcContinuation(blockNum, 500, { expedite: opts.zkpFallback === true });
      return {
        pending: true,
        busy: true,
        blockNum,
        restartRequested: opts.restart === true,
        restartApplied: false,
        ...(opts.zkpFallback ? {
          fallbackQueued: true,
          fallbackMode: opts.zkpAbandon ? 'proof_abandoned' : 'root_fallback_keep_proving',
        } : {}),
      };
    }
    this._calcDriving = true;
    let queuedFallback = null;
    let pairedRestart = false;
    let restartInitialized = false;
    let fallbackRestartFailureReason = 'restart_initialization_failed';
    try {
      // GAME_CALC_UNITS_PER_DRIVE は任意の調整つまみ。宣言・配布なしは意図的で、未設定なら Infinity。
      const unitCap = opts.maxUnits ?? (this.env.GAME_CALC_UNITS_PER_DRIVE ? parseInt(this.env.GAME_CALC_UNITS_PER_DRIVE) : Infinity);
      // GAME_CALC_WALL_BUDGET_MS は任意の調整つまみ。宣言・配布なしは意図的で、未設定なら定数を使う。
      const wallBudget = this.env.GAME_CALC_WALL_BUDGET_MS ? parseInt(this.env.GAME_CALC_WALL_BUDGET_MS) : CALC_WALL_BUDGET_MS;
      const t0 = Date.now();

      let progress = await this.storage.get(this.calcProgressKey(blockNum));
      const queuedRestart = await this.storage.get(this.calcRestartRequestKey(blockNum));
      queuedFallback = await this.storage.get(this.calcFallbackRequestKey(blockNum));
      const restart = opts.restart === true || !!queuedRestart;
      pairedRestart = !!queuedFallback?.restartRequestId && !opts.restart
        && queuedRestart?.requestId === queuedFallback.restartRequestId;
      if (queuedFallback) {
        const rejected = await this.storage.get(this.calcFallbackRejectedKey(blockNum));
        if (progress?.appliedFallbackRequestId === queuedFallback.requestId) {
          await this.deleteCalcFallbackRequest(blockNum, queuedFallback);
          queuedFallback = null;
        } else {
          const reason = rejected?.request?.requestId === queuedFallback.requestId ? rejected.reason
            : queuedFallback.restartRequestId && !pairedRestart && !restart ? 'restart_not_accepted'
            : !pairedRestart && !queuedFallback.restartRequestId
              ? this.calcFallbackGenerationRejection(queuedFallback, progress) : null;
          if (reason) {
            await this.rejectCalcFallbackRequest(blockNum, queuedFallback, reason);
            queuedFallback = null;
          }
        }
      }
      await this.assertCalcGroupingActive(blockNum, progress);
      // queued request はこの drive が必ず1回だけ消費する。受理判定が throw しても残さず、
      // 却下内容は calc_restart_rejected_{N} へ移して運営面から見えるようにする。
      if (queuedRestart) {
        await this.storage.delete(this.calcRestartRequestKey(blockNum));
      }
      if (restart) {
        try {
          await this.assertResultRestartAccepted(blockNum);
          await this.storage.delete(this.calcRestartRejectedKey(blockNum));
        } catch (error) {
          fallbackRestartFailureReason = 'restart_rejected';
          await this.recordCalcRestartRejected(blockNum, queuedRestart || {
            blockNum,
            requestedAt: null,
            unpark: opts.unpark === true,
            source: 'direct',
          }, error);
          throw error;
        }
      }
      if (restart && progress) {
        await this.calcCleanupKeys(blockNum, { preserveFallbackRequest: true });
        progress = null;
      }
      if (queuedRestart?.unpark) opts = { ...opts, unpark: true };
      // 本番ブロック32で、証明検証直後の progress は adminCommit まで永続化された一方、
      // calc_active と calc_chunk が両方消える孤児状態を観測した。従来は marker 欠落を
      // 常に reset と解釈していたため、手動 /calculate-results ですら1ユニット実行後に
      // cancelled 扱いとなり復旧できない。reset は下の専用 tombstone を先に立てるので、
      // tombstone が無い未完了 progress は安全に marker を自己修復する。
      if (progress && progress.stage !== 'done' && !(await this.storage.get(`calc_active:${blockNum}`))) {
        if (await this.storage.get(this.calcCancelKey(blockNum))) {
          return { pending: false, cancelled: true, blockNum };
        }
        console.warn(`[calc] block ${blockNum}: recovering orphaned progress at stage=${progress.stage}`);
        await this.storage.put(`calc_active:${blockNum}`, {
          blockNum, at: Date.now(), kind: 'orphan_recovery', recoveredStage: progress.stage,
        });
      }
      if (!progress) {
        const db = this.env.BITCOINU_DATA;
        if (!db) throw new Error('BITCOINU_DATA binding not found');
        // レビューL4: B1必須env（旧モノリスは冒頭で一括検出）を全チェーン読取前に早期検証する
        {
          const missing = [];
          if (!this.env.ETH_LOCK_CONTRACT_ADDRESS) missing.push('ETH_LOCK_CONTRACT_ADDRESS');
          const st = this.env.START_TIME ? (Number(this.env.START_TIME) || Date.parse(this.env.START_TIME)) : NaN;
          if (!Number.isFinite(st)) missing.push('START_TIME');
          if (!Number.isFinite(this.env.BLOCK_TIME ? parseInt(this.env.BLOCK_TIME) : NaN)) missing.push('BLOCK_TIME');
          if (!this.createReadOnlyClient()) missing.push('ETHEREUM_MAINNET_RPC_URL');
          if (missing.length > 0) throw new Error(`B1 deposit verification requires env: ${missing.join(', ')}`);
        }
        const { results: rows } = await db.prepare(
          `SELECT COUNT(*) as cnt FROM game_groups WHERE block_num = ?`
        ).bind(blockNum).all();
        if (!rows || !(rows[0]?.cnt > 0)) throw new Error('No groups found');
        console.log(`Calculating results for block ${blockNum} (chunked pipeline)`);
        progress = { blockNum, stage: 'evidence', cursor: 0, startedAt: Date.now(),
          runId: crypto.randomUUID(), failures: 0 };
        // C-2: この進捗が唯一のliveness/cancellation記録。互換マーカーはbest-effortの診断値。
        await this.storage.put(this.calcProgressKey(blockNum), progress);
        try { await this.storage.put(`calc_active:${blockNum}`, { blockNum, at: Date.now(), advisory: true }); } catch (_) {}
      }
      // (b)はこのdriveでrestartを受理し、進捗を保存できた直後だけ。
      restartInitialized = true;
      progress = await this.refreshExistingTimelineNoGameProgress(blockNum, progress);
      // reset後の新要求や、読取後に置き換わった要求は次のdriveへ残す。
      let pendingFallback = queuedFallback
        && await this.storage.get(this.calcFallbackRequestKey(blockNum));
      let fallbackStillQueued = !!queuedFallback
        && pendingFallback?.requestId === queuedFallback.requestId;
      if (fallbackStillQueued) {
        const live = await this.storage.get(this.calcProgressKey(blockNum));
        const laterRestart = await this.storage.get(this.calcRestartRequestKey(blockNum));
        // 別のrestartで失効するのは、受理されて新しいrunを保存できた後だけ。
        const reason = restart && !pairedRestart ? 'restart_superseded'
          : !live || live.startedAt !== progress.startedAt
            || live.runId !== progress.runId ? 'generation_changed'
          : progress.stage === 'done' || live.stage === 'done' ? 'run_done'
          : progress.zkProof?.status === 'verified' || live.zkProof?.status === 'verified' ? 'proof_already_verified'
          : !pairedRestart ? this.calcFallbackGenerationRejection(queuedFallback, progress) : null;
        if (reason) {
          await this.rejectCalcFallbackRequest(blockNum, queuedFallback, reason);
          fallbackStillQueued = false;
          pendingFallback = null;
        } else if (laterRestart) {
          // 外部await中に届いたrestartはまだ受理されていない。今回の適用だけを保留する。
          fallbackStillQueued = false;
          pendingFallback = null;
        }
      }
      if (progress.stage === 'done') {
        progress = await this.normalizeCompletedCalcProgress(blockNum, progress);
        return progress.result;
      }
      const applyQueuedFallback = fallbackStillQueued;
      if (applyQueuedFallback) {
        opts = {
          ...opts,
          unpark: opts.unpark === true || queuedFallback.unpark === true,
          zkpFallback: true,
          zkpAbandon: opts.zkpFallback ? opts.zkpAbandon : queuedFallback.abandon,
          zkpFallbackReason: opts.zkpFallback ? opts.zkpFallbackReason : queuedFallback.reason,
        };
      }
      if (progress.parked && !opts.unpark) {
        if (fallbackStillQueued) {
          await this.rejectCalcFallbackRequest(blockNum, queuedFallback, 'parked_not_unparked');
        }
        return { pending: true, parked: true, blockNum, stage: progress.stage, error: progress.lastError || null };
      }
      if (opts.unpark) {
        progress.parked = false; progress.failures = 0;
        delete progress.adminTxWaitDeadline;
      }
      if (opts.zkpFallback) {
        progress.zkProof = {
          ...(progress.zkProof || {}),
          operatorFallbackRequestedAt: progress.zkProof?.operatorFallbackRequestedAt
            || (fallbackStillQueued && pendingFallback?.requestedAt) || Date.now(),
          operatorFallbackReason: opts.zkpFallbackReason || 'operator_requested',
          operatorFallbackMode: opts.zkpAbandon ? 'proof_abandoned' : 'root_fallback_keep_proving',
        };
        // R20-F4/F8: adminCommit待ちに入った後の明示fallbackも、設定を再読取する
        // zkProofへ戻して実際に消費する。gas以外の安全条件を直接解除しない。
        if (progress.stage === 'zkProof' || progress.stage === 'adminCommit' || progress.stage === 'timelineNoGameManualFallback') {
          progress.stage = 'zkProof';
          delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
        }
      }
      if (fallbackStillQueued) {
        // 適用済みの印も進捗と一緒に保存する。delete失敗後の再開で段を二度戻さない。
        progress.appliedFallbackRequestId = queuedFallback.requestId;
        await this.storage.put(this.calcProgressKey(blockNum), progress);
        // 外部await中に届いた次の要求を、古いdriveの後片付けで消さない。
        await this.deleteCalcFallbackRequest(blockNum, queuedFallback);
      }

      let units = 0;
      let subreqSpent = 0; // R3: ステージ別概算の累計
      while (progress.stage !== 'done' && progress.stage !== 'timelineNoGameManualFallback' && units < unitCap && (Date.now() - t0) < wallBudget) {
        // K-S5-002: 自発待機中は回さない（無いと同じユニットを unitCap 回まで空回しする）。
        if (progress.waitUntil && Date.now() < progress.waitUntil) {
          console.log(`[calc] block ${blockNum}: waiting (${progress.waitReason}) until ${new Date(progress.waitUntil).toISOString()}`);
          break;
        }
        // R3: 次のユニットの概算で予算超過が見込まれるなら自発yield（最低1ユニットは必ず実行＝前進保証）
        const unitEstimate = CALC_UNIT_SUBREQ_ESTIMATES[progress.stage] ?? 100;
        if (units > 0 && subreqSpent + unitEstimate > CALC_SUBREQ_BUDGET) break;
        try {
          progress = await this.execCalcUnit(blockNum, progress);
          await this.assertCalcGroupingActive(blockNum, progress);
          // 正常な管理tx待ちの観測だけでは、既に消費した失敗予算を戻さない。
          // 通常calcも許可集合内かつintent期限内の待ちはthrowせず、回数を保持する。
          if (!(progress.waitReason === 'admin_tx_pending' && progress.waitUntil > Date.now())) {
            progress.failures = 0;
          }
          progress.lostRuns = 0;
          // 一時障害から前進できた時点で過去の診断を消す。従来はfailuresだけ0へ戻し、
          // lastErrorがdone後も残ったため、正常完了ブロックが監視上は失敗に見え続けた。
          progress.lastError = null;
        } catch (e) {
          // groupingのparkはcalcの失敗ではない。予算・期限・進捗を変えず復旧を待つ。
          if (e?.groupingParked) throw e;
          if (e?.code === 'rpc_quorum_unavailable') {
            progress.waitReason = 'rpc_quorum_unavailable';
            progress.waitUntil = Date.now() + 30_000;
            progress.waitDetail = String(e?.message || e).slice(0, 400);
            progress.updatedAt = Date.now();
            await this.storage.put(this.calcProgressKey(blockNum), progress);
            break;
          }
          progress.failures = (progress.failures || 0) + 1;
          progress.lastError = String(e?.message || e);
          let parkedNow = false;
          const failureBudgetExhausted = e?.adminTxPending === true
            ? progress.failures > CALC_MAX_CONSECUTIVE_FAILURES
            : progress.failures >= CALC_MAX_CONSECUTIVE_FAILURES;
          if (e?.terminal === true || failureBudgetExhausted) {
            parkedNow = !progress.parked;
            progress.parked = true;
            console.error(`[calc] block ${blockNum}: parked after ${progress.failures} failure(s) at stage=${progress.stage}: ${progress.lastError}`);
          }
          progress.updatedAt = Date.now();
          if (await this.storage.get(this.calcProgressKey(blockNum))) {
            await this.storage.put(this.calcProgressKey(blockNum), progress);
            if (parkedNow) await this.alertCalcParked(blockNum, progress);
            // レビューM4: 最初のdrive（advancePhase同期経路）での失敗も自動リトライに乗せる。
            // 呼び出し元がthrowを握り潰しても、alarm経由のバックオフ再試行が必ずスケジュールされる。
            if (!progress.parked) await this.enqueueCalcContinuation(blockNum, calcRetryDelayMs(progress.failures)); // R5: 指数バックオフ
          }
          throw e; // 呼び出し元へ伝播（advancePhaseはcatch・alarm経路もバックオフ済み）
        }
        // レビューH3: reset-block等が並行してパイプラインを破棄した場合、進捗を書き戻すと
        // 中間キーの無いゾンビ進捗が復活する（scoringのvdep欠落→検証なし自己申告デポジットで
        // 採点される資金バグ）。マーカー存在を確認してからput（この2操作間にawaitなし＝原子的）。
        if (!(await this.storage.get(`calc_active:${blockNum}`))) {
          if (await this.storage.get(this.calcCancelKey(blockNum))) {
            console.warn(`[calc] block ${blockNum}: pipeline was cancelled externally (reset?) — aborting drive without persisting progress`);
            return { pending: false, cancelled: true, blockNum };
          }
          // tombstone の無い marker 消失は reset ではなく孤児化。今完了したユニットを
          // 捨てずに marker を戻し、同じ drive / alarm で処理を継続する。
          console.warn(`[calc] block ${blockNum}: active marker disappeared without cancellation — restoring it at stage=${progress.stage}`);
          await this.storage.put(`calc_active:${blockNum}`, {
            blockNum, at: Date.now(), kind: 'orphan_recovery', recoveredStage: progress.stage,
          });
        }
        progress.updatedAt = Date.now();
        await this.storage.put(this.calcProgressKey(blockNum), progress);
        subreqSpent += unitEstimate;
        units++;
      }

      if (progress.stage === 'timelineNoGameManualFallback') return { pending: true, manualActionRequired: true, blockNum, stage: progress.stage, waitReason: 'timeline_no_game_manual_fallback' };
      if (progress.stage !== 'done' && progress.waitUntil) {
        await this.enqueueCalcContinuation(blockNum,
          Math.max(250, progress.waitUntil - Date.now()), { replaceEarlier: true });
        return {
          pending: true, blockNum, stage: progress.stage, cursor: progress.cursor,
          waitReason: progress.waitReason || null, waitUntil: progress.waitUntil,
          waitDetail: progress.waitDetail || null,
        };
      }
      if (progress.stage === 'done') {
        progress = await this.normalizeCompletedCalcProgress(blockNum, progress);
        await this.storage.delete(`calc_active:${blockNum}`);
        return progress.result;
      }
      await this.enqueueCalcContinuation(blockNum, 250);
      return {
        pending: true, blockNum, stage: progress.stage, cursor: progress.cursor,
        waitReason: progress.waitReason || null, waitUntil: progress.waitUntil || null,
        waitDetail: progress.waitDetail || null,
      };
    } catch (e) {
      if (pairedRestart && queuedFallback && !restartInitialized) {
        await this.rejectCalcFallbackRequest(blockNum, queuedFallback, fallbackRestartFailureReason);
      }
      if (e?.groupingParked) return e.groupingParked;
      throw e;
    } finally {
      this._calcDriving = false;
    }
  }

  // 継続タスクをキューへ（重複登録なし）＋アラーム設定
  async enqueueCalcContinuation(blockNum, delayMs = 250, { replaceEarlier = false, expedite = false } = {}) {
    if ((await this.calcAdminTxWaitState(blockNum)).parked) return;
    const taskQueue = await this.storage.get('phase_task_queue') || [];
    const existing = taskQueue.find(t => t.type === 'calc_chunk' && t.blockNum === blockNum);
    // 前倒しはbusyで保存した直後だけ。失敗後のバックオフは短縮しない。
    // 成功したdriveの長いwaitだけは、既に前倒しした予定を後ろへ押し戻さない。
    const fallbackPending = replaceEarlier && !!(await this.storage.get(this.calcFallbackRequestKey(blockNum)));
    const executeAt = Date.now() + delayMs;
    if (!existing) {
      taskQueue.push({ type: 'calc_chunk', blockNum, executeAt });
      taskQueue.sort((a, b) => a.executeAt - b.executeAt);
      await this.storage.put('phase_task_queue', taskQueue);
    } else if ((expedite && existing.executeAt > executeAt)
      || (!fallbackPending && replaceEarlier && existing.executeAt < executeAt)) {
      existing.executeAt = executeAt;
      taskQueue.sort((a, b) => a.executeAt - b.executeAt);
      await this.storage.put('phase_task_queue', taskQueue);
    }
    await this.armEarliestQueuedTask();
  }

  async alertCalcParked(blockNum, progress) {
    await sendAlertAndRecord(this.env, this.storage, {
      kind: CALC_PARKED_ALERT_KIND,
      subject: `[COINU][CRITICAL] 結果集計を棚上げ: block ${blockNum}`,
      body: [
        'severity=CRITICAL',
        `reason=${/archive_rpc_required/.test(String(progress?.lastError || '')) ? 'archive_rpc_required' : 'calc_pipeline_parked'}`,
        `blockNum=${blockNum}`,
        `stage=${progress?.stage || 'unknown'}`,
        `failures=${progress?.failures ?? 'unknown'}`,
        `lastError=${progress?.lastError || 'unknown'}`,
        'manualAction=原因を確認し POST /calculate-results で再開する',
      ].join('\n'),
    }).catch((error) => {
      console.error(`[calc] block ${blockNum}: parked alert failed: ${error?.message || error}`);
    });
  }

  // 中間キーと進捗の全掃除（restart・reset用）。
  // レビューH3: 進捗を最初に消す — 並行driveはユニット完了後の「進捗存在チェック→
  // 進捗put」で必ず中止側に倒れ、ゾンビ進捗が復活しない。
  async calcCleanupKeys(blockNum, { preserveFallbackRequest = false } = {}) {
    const cancelKey = this.calcCancelKey(blockNum);
    // marker 欠落の自己修復と明示 reset/restart を区別する。先に tombstone を置くことで、
    // 並行 drive は marker が消えた瞬間を孤児化と誤認せず必ず中止側へ倒れる。
    await this.storage.put(cancelKey, { blockNum, at: Date.now() });
    try {
      await this.storage.delete(`calc_active:${blockNum}`);
      // T4: invalid_chunk が resultCount/200 個になる。list 全件を一度に読むと
      // restart 自体が 128 MiB を使うため、削除済みの先頭から次の128鍵を読む。
      for (;;) {
        const page = await this.storage.list({ prefix: `calc:${blockNum}:`, limit: 128 });
        if (!page.size) break;
        await this.storage.delete([...page.keys()]);
      }
      await this.storage.delete(this.calcProgressKey(blockNum));
      await this.storage.delete(this.calcRestartRequestKey(blockNum));
      if (!preserveFallbackRequest) await this.storage.delete(this.calcFallbackRequestKey(blockNum));
    } finally {
      await this.storage.delete(cancelKey);
    }
  }

  // R23-F1: block単位resetで消すauto-distribution専用キーの唯一の一覧。
  // 現行は exact key に checkpoint/cursor/failures/temp を内包するが、
  // 旧/将来の分割キーも同じnamespaceなら漏れない。全resetは deleteAll()で包含。
  async autoDistributeCleanupKeys(blockNum) {
    const exact = `auto_distribute_block${blockNum}`;
    await this.storage.delete(exact);
    for (const prefix of [`${exact}:`, `auto:${blockNum}:`]) {
      const map = await this.storage.list({ prefix });
      const keys = [...map.keys()];
      for (let i = 0; i < keys.length; i += 128) {
        await this.storage.delete(keys.slice(i, i + 128));
      }
    }
  }

  async execCalcUnit(blockNum, progress) {
    await this.assertCalcGroupingActive(blockNum, progress);
    switch (progress.stage) {
      case 'evidence': return this.calcEvidenceUnit(blockNum, progress);
      case 'depids': return this.calcDepIdsUnit(blockNum, progress);
      case 'chain': return this.calcChainUnit(blockNum, progress);
      case 'vdep': return this.calcVdepUnit(blockNum, progress);
      case 'scoring': return this.calcScoringUnit(blockNum, progress);
      case 'rewards': return this.calcRewardsUnit(blockNum, progress);
      case 'writing': return this.calcWritingUnit(blockNum, progress);
      case 'shards': return this.calcShardsUnit(blockNum, progress);
      case 'summary': return this.calcSummaryUnit(blockNum, progress);
      case 'merkle': return this.calcMerkleUnit(blockNum, progress);
      case 'manifest': return this.calcManifestUnit(blockNum, progress);
      case 'proofs': return this.calcProofsUnit(blockNum, progress);
      case 'zkProof': return this.calcZkProofUnit(blockNum, progress);
      case 'adminCommit': return this.calcAdminCommitUnit(blockNum, progress);
      case 'cleanup': return this.calcFinalizeUnit(blockNum, progress);
      default: throw new Error(`unknown calc stage: ${progress.stage}`);
    }
  }

  /// このブロックの**グループとメンバーの権威** ＝ `entries/block{N}/game_groups.json`。
  ///
  /// 🔴 J-34（2026-08-09・ユーザー確定）: 集計の**起点**をこのファイルにする。
  ///    読めない／壊れている／グループが1件も無い、はすべて throw（fail-closed）。
  ///    `getR2Text` は読取エラーを throw し、不存在だけ `null` を返す
  ///    （`getR2Object` はエラーも `null` に潰すので、ここでは使えない）。
  ///
  /// ⚠️ 正準JSON検査は**かけない**。このファイルは整数に見えるキーを持つオブジェクトを含み、
  ///    `JSON.parse` が仕様どおりそれを昇順へ並べ替えるので、正しく書かれたファイルでも
  ///    往復が一致しない＝偽陽性になる（`getR2Object` / `lib/canonical-json.js` の注記と同じ理由）。
  async calcLoadGroupAuthority(blockNum) {
    const key = `entries/block${blockNum}/game_groups.json`;
    const text = await this.getR2Text(key);
    if (text == null) {
      throw new Error(
        `[calc] authoritative ${key} is missing — refusing to score block ${blockNum} from D1 alone ` +
        '(D1 game_groups is the source of points, not the source of truth for which groups exist)'
      );
    }
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch (e) {
      throw new Error(`[calc] authoritative ${key} is not valid JSON: ${e.message}`);
    }
    const list = Array.isArray(parsed?.groups) ? parsed.groups : null;
    if (!list || list.length === 0) {
      throw new Error(`[calc] authoritative ${key} has no groups[] — grouping artifact is corrupted`);
    }
    // 申告 totalGroups との自己整合（申告だけ書き換えても得は無いが、壊れたファイルは通さない）
    if (parsed.totalGroups != null && Number(parsed.totalGroups) !== list.length) {
      throw new Error(
        `[calc] authoritative ${key} is self-inconsistent — totalGroups=${parsed.totalGroups} ` +
        `but groups[] has ${list.length} entries`
      );
    }
    const out = [];
    const seenIds = new Set();
    for (const g of list) {
      const groupId = Number(g?.groupId);
      if (!Number.isSafeInteger(groupId) || groupId < 0) {
        throw new Error(`[calc] authoritative ${key} has a group with a non-integer groupId (${g?.groupId})`);
      }
      if (seenIds.has(groupId)) {
        throw new Error(`[calc] authoritative ${key} lists group ${groupId} more than once`);
      }
      seenIds.add(groupId);
      const memberIds = Array.isArray(g?.memberIds) ? g.memberIds.map(v => String(v)) : null;
      if (!memberIds || memberIds.length === 0) {
        throw new Error(`[calc] authoritative ${key} group ${groupId} has no memberIds[]`);
      }
      if (g?.memberCount != null && Number(g.memberCount) !== memberIds.length) {
        throw new Error(
          `[calc] authoritative ${key} group ${groupId} is self-inconsistent — ` +
          `memberCount=${g.memberCount} but memberIds[] has ${memberIds.length} entries`
        );
      }
      out.push({ groupId, memberIds });
    }
    // 並びは group_id 昇順に固定（旧実装の `ORDER BY group_id ASC` と同一の順序）
    out.sort((a, b) => a.groupId - b.groupId);
    return out;
  }

  // 集計に使うグループ行の取得。
  //
  // 🔴 J-34（2026-08-09・ユーザー確定）: **起点は R2 の `game_groups.json`（権威）。
  //    D1 は「権威」から「点数の供給元」へ降格する。**
  //
  //    旧実装は D1 の `game_groups` 行を起点にしていて、「本来いくつあるはずか」を
  //    一度も確かめていなかった。行が1件消えても**残りだけで按分して完走する**。
  //    実測（3グループ9人で D1 の行を1件削除）:
  //      分母 900 → 600 ／ 1人あたり 1.28e22 → 1.92e22 wei（**+50%**）／
  //      移動額は**ブロック報酬の 33.3%**／消えた3人とそのデポッターは
  //      **葉が無く恒久的に請求不能**。
  //    既存の安全装置（`calcAssertGroupsComplete` / `calcAssertGroupMembers` /
  //    `calcNormalizeRoster` / `calcMerkleUnit`）は**一つ残らず素通り**する ——
  //    どれも期待値を `calcLoadGroups`（＝同じ D1）から作る**自己参照ガード**だから。
  //
  //    直し方は「件数を数えて比べる」ではなく**起点を権威に変える**:
  //      ① `entries/block{N}/game_groups.json` を読む（グループとメンバーの権威）
  //      ② その各グループについて D1 から行（＝点数の供給元）を引く
  //           引けない → 止まる ／ メンバーが食い違う → 止まる
  //      ③ 引けた行で先へ進む
  //    権威を起点にすると**欠落が「引けない」という形で自然に現れる**＝
  //    件数を数えて比べる別の検査が要らない＝「**比べ忘れる**」余地が構造的に消える。
  //    D1 に余分な行があっても、権威に無ければ読まれない。
  //
  //    ⚠️ `game_groups.json` に点数は無い（グループ分けの時点で書かれる・`createGroupSummary`）。
  //       点数は D1 にしかない（ChatGameDO の結果を集計して書く）ので、D1 を使わない計算は不可能。
  //    ⚠️ 過剰遮断リスクは実質ゼロ: 行を**1件だけ**消すコード経路は存在しない
  //       （`DELETE` は4箇所とも「そのブロック全部」）。自動配布・0名ブロックはそもそも
  //       D1 に行を書かず `calculateResults` の入口（`No groups found`）で止まる。
  //       グループ分けは D1 → R2 の順に書き、途中で死んでも `status='formed'` のまま
  //       full path 再実行に落ちるので自己修復する。
  //
  // レビューL1: カーソル分割・順序パリティが行順に依存するため group_id 昇順で明示固定する
  // （旧モノリスの実効順序＝挿入順＝group_id昇順と同一。
  //  writeGroupsToD1 は formGroups の出力を groupId 0..n-1 の順で挿入する）。
  async calcLoadGroups(blockNum) {
    const authority = await this.calcLoadGroupAuthority(blockNum);
    const db = this.env.BITCOINU_DATA;
    const { results: rows } = await db.prepare(
      `SELECT block_num, group_id, members FROM game_groups WHERE block_num = ? ORDER BY group_id ASC`
    ).bind(blockNum).all();
    const byId = new Map();
    for (const row of (rows || [])) byId.set(Number(row.group_id), row);

    const groups = [];
    for (const ag of authority) {
      const row = byId.get(ag.groupId);
      if (!row) {
        throw new Error(
          `[calc] game_groups row missing for block ${blockNum} group ${ag.groupId} — ` +
          `entries/block${blockNum}/game_groups.json (authoritative) lists ${authority.length} groups ` +
          `but D1 has ${(rows || []).length}; refusing to score a partial block`
        );
      }
      // 権威の名簿 ↔ D1 の名簿。食い違ったら止まる（点数の供給元が別のグループを指している）。
      const expected = new Set(ag.memberIds);
      if (expected.size !== ag.memberIds.length) {
        throw new Error(
          `[calc] authoritative entries/block${blockNum}/game_groups.json group ${ag.groupId} ` +
          'has duplicate memberIds'
        );
      }
      const actual = this.calcD1GroupUids(row);
      const missing = [...expected].filter(u => !actual.has(u));
      const extra = [...actual].filter(u => !expected.has(u));
      if (missing.length > 0 || extra.length > 0) {
        throw new Error(
          `[calc] member roster mismatch between authoritative game_groups.json and D1 ` +
          `for block ${blockNum} group ${ag.groupId} — ` +
          `expected ${expected.size} uids, D1 has ${actual.size} ` +
          `(missing: ${missing.join(',') || '-'} / unexpected: ${extra.join(',') || '-'})`
        );
      }
      groups.push(row);
    }
    if (groups.length === 0) throw new Error('No groups found');
    return groups;
  }

  // ChatGameDO get-results（1グループ）
  //
  // K-S2-004 是正（2026-07-27）: 旧実装は取得失敗を null に変えて返し、呼び出し側が
  // そのグループを「失敗」として**無言で名簿から外して**先へ進んでいた。リトライは1度も
  // 行われず、消えたグループの参加者・デポッターは結果にも Merkle の leaf にも現れないまま
  // ブロックが最終化される（＝恒久的に請求不能）。しかも除外分の報酬は未配分にならず
  // 残存グループへ再按分されるため、運営が狙ったグループの応答だけを失敗させれば
  // 自分の取り分を増やせた。一過性の 5xx が1回起きただけでも同じ結果になる。
  //
  // 対処: 失敗は throw して calc パイプラインの既存リトライ機構
  //（指数バックオフ 15s→10分・累計約2.5時間 → 20回で park → /calc-status に露出）に乗せる。
  // 部分的な結果の最終化は「遅延」より常に悪い ── TokenMining.submitMerkleRoot の
  // **初回提出に期限は無い**ため park は遅延にすぎないが、部分最終化は不可逆である。
  async calcFetchGroupData(blockNum, groupId) {
    let response;
    let fetchError = null;
    try {
      const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${groupId}`);
      const chatDO = this.env.CHAT_GAME_DO.get(doId);
      response = await chatDO.fetch(this.chatDoRequest('/get-results', { method: 'GET' }));
    } catch (error) {
      fetchError = new Error(`[calc] get-results fetch failed for block ${blockNum} group ${groupId}: ${String(error?.message || error)}`);
    }
    if (!fetchError && !response.ok) {
      fetchError = new Error(`[calc] get-results returned ${response.status} for block ${blockNum} group ${groupId}`);
    }
    let data = null;
    if (!fetchError) {
      try {
        data = await response.json();
      } catch (error) {
        fetchError = new Error(`[calc] get-results body is not valid JSON for block ${blockNum} group ${groupId}: ${String(error?.message || error)}`);
      }
    }

    // S3C8（D-09・2026-09-27）: 取得の失敗（上の3種）は救済より前に throw し、上の再試行→park に乗せる。
    // 旧実装は失敗でも下の救済へ入り、採用 Evidence が1件以上で群アーカイブが R2 に無いと、一過性の
    // 失敗1回で発言・提出が空の基底アーカイブを公開し、WS だけの提出者を no_submit にして警報なしに進んだ。
    // 挙動の差: 取得が失敗し続ける組は救済されず park＋CRITICAL 警報になり、運営が原因を直して POST /calculate-results で再開する。
    if (fetchError) throw fetchError;

    // V25-03: ChatGameDO が未初期化だと /get-results は 200 でも members=[] を返す。
    // 以前は後段の完全性検査で永久 park し、参加者が正式な Evidence を提出していても
    // BTCu 配分・Merkle 生成へ一切到達できなかった。ここでは「取得に成功し、members が空か無い
    //（＝未初期化の ChatGameDO）」だけを欠損として扱い、ブロック内に採用済み Evidence が1件以上ある
    // 場合に限って、D1 game_groups の確定 roster から通常採点用の入力を復元する。
    // 非空だが roster/meta が壊れた応答は既存の fail-closed 検査へ渡し、救済で隠さない。
    if (Array.isArray(data?.members) && data.members.length > 0) return data;
    if (data?.members != null && !Array.isArray(data.members)) return data;

    const recovered = await this.calcRecoverEvidenceGroupData(blockNum, groupId);
    if (recovered) return recovered;
    return data;
  }

  // V25-03 end-to-end 救済。Evidence が正規検証・first-write-wins を通った後にしか呼ばれない。
  // 復元データは calculateGroupResults の通常経路へ入り、Evidence 未提出者は規則どおり
  // no_submit、提出者は calcApplyEvidenceToGroup で正式な compact bundle が適用される。
  // S3C8 以降、呼び手（calcFetchGroupData）は取得に成功したときだけ呼ぶので originalError は
  // 常に null（reason は chat_do_uninitialized）。chat_do_unavailable は旧実装が書いた公開物にだけ現れうる。
  async calcRecoverEvidenceGroupData(blockNum, groupId, originalError = null) {
    const adoptedRec = await this.calcLoadAdopted(blockNum);
    if (!adoptedRec || Number(adoptedRec.adoptedCount ?? adoptedRec.adopted?.length ?? 0) <= 0) {
      return null;
    }

    const groups = await this.calcLoadGroups(blockNum);
    const group = groups.find(g => Number(g.group_id) === Number(groupId));
    if (!group) {
      throw new Error(`[calc] evidence rescue: group ${groupId} is absent from authoritative D1 roster for block ${blockNum}`);
    }
    let members;
    try {
      members = JSON.parse(group.members || '[]');
    } catch (error) {
      throw new Error(`[calc] evidence rescue: D1 roster for block ${blockNum} group ${groupId} is invalid JSON: ${error.message}`);
    }
    if (!Array.isArray(members) || members.length === 0) {
      throw new Error(`[calc] evidence rescue: D1 roster for block ${blockNum} group ${groupId} is empty`);
    }

    const r2Key = `games/block${blockNum}/group${groupId}.json`;
    const existingText = await this.getR2Text(r2Key);
    if (existingText != null) {
      let archived;
      try { archived = JSON.parse(existingText); }
      catch (error) {
        throw new Error(`[calc] evidence rescue: existing ${r2Key} is invalid JSON: ${error.message}`);
      }
      // ChatGameDO だけ失われたケースでは、既存の完成アーカイブをそのまま通常採点へ戻す。
      // 空／壊れたアーカイブは「欠損」ではなく改変可能な成果物なので上書きしない。
      if (archived && typeof archived === 'object' && Array.isArray(archived.members) && archived.members.length > 0) {
        console.warn(`[calc] Evidence rescue for block ${blockNum} group ${groupId}: using existing R2 archive after ChatGameDO loss`);
        return archived;
      }
      throw new Error(`[calc] evidence rescue: existing ${r2Key} has no usable member roster — refusing to overwrite a published artifact`);
    }

    const charCounts = Object.create(null);
    for (const member of members) charCounts[String(member.uid)] = 0;
    const rescued = {
      phase: 'completed',
      meta: {
        blockNum: Number(blockNum),
        groupId: Number(groupId),
        lang: group.lang || 'mixed',
        mixed: (group.lang || 'mixed') === 'mixed',
        memberCount: members.length,
      },
      members,
      messages: [],
      receipts: [],
      charCounts,
      phaseTimestamps: {},
      submissions: Object.create(null),
      submissionsRaw: Object.create(null),
      reports: Object.create(null),
      votes: Object.create(null),
      gameSkipped: null,
      evidenceRescue: {
        schemaVersion: 1,
        source: 'committed_grouping',
        reason: originalError ? 'chat_do_unavailable' : 'chat_do_uninitialized',
      },
    };

    // 後段の canonicalTimeline / gameResults CAS は group archive の存在を前提にする。
    // root 提出前のこの時点で決定論的な基底アーカイブを作り、以後は通常 writer だけが更新する。
    await this.putR2ObjectOrThrow(r2Key, rescued);
    console.warn(
      `[calc] Evidence rescue for block ${blockNum} group ${groupId}: `
      + `reconstructed ${members.length} members from committed grouping and published a base archive`
    );
    return rescued;
  }

  // ステージ1: Evidence（§4.2）— 取得・検証・D1永続をイベント数でチャンク化。
  // 完了時に採用集合（uidごとseq最小の有効＝first-write-wins）を calc:{N}:adopted へ確定。
  // 旧 reconcileEvidence と同一の finality ガード・完全性検証・マーカー管理を維持する。
  // membersIndex はD1グループ行から構築（ChatGameDOへの依存なし＝メンバーシップの正はD1）。
  async calcRecordRosterReadFailure(blockNum, error) {
    const key = `roster_submission_read_failed_block${blockNum}`;
    if (await this.storage.get(key)) return;
    await this.storage.put(key, { blockNum, error: String(error?.message || error), at: Date.now() });
    await sendAlertAndRecord(this.env, this.storage, {
      kind: 'roster_submission_read_failed',
      subject: `[COINU][CRITICAL] 採点用名簿を読めない: block ${blockNum}`,
      body: `blockNum=${blockNum}\nreason=${String(error?.message || error)}\nGET /calc-status?block=${blockNum}`,
    }).catch((alertError) => console.error('[calc] roster read alert failed:', alertError?.message || alertError));
  }

  async calcRosterSubmissionEligibility(blockNum, client, safeBlockNumber, safeTimestamp, chatOpenAt, chatCloseAt, evidenceGrace = null, quorumClients = null, safeBlock = null) {
    if (!this.env.HASH_STORAGE_CONTRACT_ADDRESS) {
      throw new Error('[calc] roster registration reader unavailable: HashStorage address missing');
    }
    const entryEndSec = Number(chatOpenAt);
    const closeSec = Number(chatCloseAt);
    const nowSec = Number(safeTimestamp);
    if (![entryEndSec, closeSec, nowSec].every(Number.isSafeInteger) || nowSec < closeSec) {
      throw new Error('[calc] roster chain time unavailable or chat window not final');
    }
    const grace = Number(evidenceGrace ?? (quorumClients
      ? await this.readEvidenceAtBlock(quorumClients, safeBlock, this.env.EVIDENCE_CONTRACT_ADDRESS,
        [{ name: 'currentGrace', type: 'function', stateMutability: 'view',
          inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] }],
        'currentGrace', [BigInt(blockNum)])
      : await client.readContract({
      address: this.env.EVIDENCE_CONTRACT_ADDRESS,
      abi: [{ name: 'currentGrace', type: 'function', stateMutability: 'view',
        inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] }],
      functionName: 'currentGrace', args: [BigInt(blockNum)], blockNumber: safeBlockNumber,
    })));
    if (!Number.isSafeInteger(grace) || grace <= 0 || !Number.isSafeInteger(entryEndSec + grace)) {
      throw new Error('[calc] roster currentGrace unavailable');
    }
    const chattingStartSec = entryEndSec + grace;
    const key = rosterAnchorKey(blockNum);
    const read = (functionName, args) => quorumClients
      ? this.readEvidenceAtBlock(quorumClients, safeBlock, this.env.HASH_STORAGE_CONTRACT_ADDRESS,
        HASH_STORAGE_ABI, functionName, args)
      : client.readContract({
        address: this.env.HASH_STORAGE_CONTRACT_ADDRESS, abi: HASH_STORAGE_ABI,
        functionName, args, blockNumber: safeBlockNumber,
      });
    let selection;
    let legacy = false;
    try {
      const count = await read('otherRegistrationCount', [key]);
      selection = await selectCanonicalRosterRegistration({
        count,
        at: async (index) => {
          const row = await read('otherRegistrationAt', [key, BigInt(index)]);
          return { hash: row[0], registeredBlock: row[1], registeredAt: row[2] };
        },
        entryEndSec, chattingStartSec, nowSec,
      });
    } catch (error) {
      const allowlisted = LEGACY_HASH_STORAGE_ALLOWLIST.has(keccak256(stringToHex(
        String(this.env.HASH_STORAGE_CONTRACT_ADDRESS).toLowerCase(),
      )));
      const missingGetter = typeof error?.walk === 'function' && !!error.walk((cause) =>
        cause?.name === 'ContractFunctionRevertedError'
        || cause?.name === 'ContractFunctionZeroDataError'
        || cause?.name === 'ExecutionRevertedError');
      if (!allowlisted || !(missingGetter || error?.missingGetterQuorum === true)) throw error;
      legacy = true;
      const current = await read('getOtherHash', [key]);
      const updated = Number(current[1]);
      let registeredAt = null;
      if (Number.isSafeInteger(updated) && updated > 0) {
        try {
          registeredAt = Number((await (quorumClients
            ? readMatchingFinalizedBlock(quorumClients, { number: BigInt(updated) })
            : client.getBlock({ blockNumber: BigInt(updated) }))).timestamp);
        }
        catch (error) {
          if (quorumClients) throw error;
          // 単独設定の旧版 HashStorage 互換。
        }
      }
      const row = Number.isSafeInteger(updated) && updated > 0
        ? { hash: current[0], registeredBlock: updated, registeredAt } : null;
      selection = { status: row ? 'legacy' : 'none', index: row ? 0 : null, row };
    }
    return evaluateRosterSubmissionEligibility({ selection, legacy, chattingStartSec });
  }

  async calcEvidenceUnit(blockNum, progress) {
    const contractAddress = this.env.EVIDENCE_CONTRACT_ADDRESS;
    if (!contractAddress) {
      const error = new Error('[calc] roster currentGrace unavailable: EVIDENCE_CONTRACT_ADDRESS not set');
      await this.calcRecordRosterReadFailure(blockNum, error);
      throw error;
    }
    const db = this.env.BITCOINU_DATA;
    const publicClient = this.createReadOnlyClient();
    const quorumClients = this.createEvidenceReadClients();
    if (!publicClient) {
      const error = new Error('[calc] roster chain reader unavailable: ETHEREUM_MAINNET_RPC_URL not configured');
      await this.calcRecordRosterReadFailure(blockNum, error);
      throw error;
    }
    const confirmations = this.env.CONFIRMATION_BLOCKS ? parseInt(this.env.CONFIRMATION_BLOCKS) : 64;

    try {
      if (progress.evidenceAnchor && !quorumClients) {
        const error = new Error('[rpc-quorum] pinned Evidence progress requires two independent RPC providers');
        error.code = 'rpc_quorum_unavailable';
        await this.noteRpcQuorumFailure(blockNum, error);
        throw error;
      }
      // 固定前に必要な state を全て読む。旧進捗の pin には窓の検査済み記録がないため破棄する。
      let safeBlockNumber; let safeBlock;
      try {
        if (quorumClients) {
          if (progress.evidenceAnchor && !progress.evidenceSnapshot) {
            delete progress.evidenceAnchor;
            delete progress.evidenceIngest;
            delete progress.evidenceFinal;
            delete progress.rosterSubmission;
          }
          safeBlock = await readMatchingFinalizedBlock(quorumClients, progress.evidenceAnchor || null);
          if (progress.evidenceAnchor
              && Number(safeBlock.timestamp) < Number(progress.evidenceSnapshot.window.closeAt)) {
            delete progress.evidenceAnchor;
            delete progress.evidenceSnapshot;
            delete progress.evidenceIngest;
            delete progress.evidenceFinal;
            delete progress.rosterSubmission;
            safeBlock = await readMatchingFinalizedBlock(quorumClients);
          }
          safeBlockNumber = safeBlock.number;
        } else {
          const latest = await publicClient.getBlock();
          safeBlockNumber = latest.number - BigInt(confirmations);
          safeBlock = await publicClient.getBlock({ blockNumber: safeBlockNumber });
        }
      } catch (error) {
        if (error?.code !== 'rpc_quorum_unavailable') await this.calcRecordRosterReadFailure(blockNum, error);
        throw error;
      }

      const windowAbi = [
        { name: 'resultCount', type: 'function', stateMutability: 'view',
          inputs: [{ name: '', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] },
        { name: 'resultWindow', type: 'function', stateMutability: 'view',
          inputs: [{ name: 'blockNum', type: 'uint256' }],
          outputs: [{ name: 'openAt', type: 'uint256' }, { name: 'closeAt', type: 'uint256' }] },
        { name: 'chatWindow', type: 'function', stateMutability: 'view',
          inputs: [{ name: 'blockNum', type: 'uint256' }],
          outputs: [{ name: 'chatOpenAt', type: 'uint256' }, { name: 'chatCloseAt', type: 'uint256' }] },
      ];
      const evidenceAt = (functionName) => quorumClients
        ? this.readEvidenceAtBlock(quorumClients, safeBlock, contractAddress, windowAbi, functionName, [BigInt(blockNum)])
        : publicClient.readContract({ address: contractAddress, abi: windowAbi,
          functionName, args: [BigInt(blockNum)], blockNumber: safeBlockNumber });

      let snapshot = quorumClients ? progress.evidenceSnapshot : null;
      if (!snapshot) {
        let resultWindow; let chatWindow; let resultCountRaw; let grace;
        try {
          resultWindow = await evidenceAt('resultWindow');
          if (Number(safeBlock.timestamp) < Number(resultWindow[1])) {
            progress.waitReason = 'evidence_finality_pending';
            progress.waitUntil = Date.now() + 30_000;
            progress.waitDetail = { safeBlock: safeBlockNumber.toString(), closeAt: Number(resultWindow[1]) };
            return progress;
          }
          [chatWindow, resultCountRaw, grace] = await Promise.all([
            evidenceAt('chatWindow'), evidenceAt('resultCount'),
            quorumClients
              ? this.readEvidenceAtBlock(quorumClients, safeBlock, contractAddress,
                [{ name: 'currentGrace', type: 'function', stateMutability: 'view',
                  inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] }],
                'currentGrace', [BigInt(blockNum)])
              : null,
          ]);
          const resultCount = Number(resultCountRaw);
          if (!Number.isSafeInteger(resultCount) || resultCount < 0) {
            throw new Error('[evidence] resultCount is outside the JS safe integer range');
          }
          if (quorumClients || !progress.rosterSubmission) {
            progress.rosterSubmission = await this.calcRosterSubmissionEligibility(
              blockNum, publicClient, safeBlockNumber, safeBlock.timestamp,
              chatWindow[0], chatWindow[1], grace, quorumClients, safeBlock,
            );
          }
          if (quorumClients) await readMatchingFinalizedBlock(quorumClients, safeBlock);
          snapshot = {
            window: { openAt: Number(resultWindow[0]), closeAt: Number(resultWindow[1]) },
            chatWindow: { chatOpenAt: Number(chatWindow[0]), chatCloseAt: Number(chatWindow[1]) },
            resultCount, graceSec: Number(grace),
          };
          if (quorumClients) {
            progress.evidenceSnapshot = snapshot;
            progress.evidenceAnchor = { number: safeBlockNumber.toString(), hash: safeBlock.hash };
          }
        } catch (error) {
          if (error?.code !== 'rpc_quorum_unavailable') await this.calcRecordRosterReadFailure(blockNum, error);
          throw error;
        }
      }
      delete progress.waitReason; delete progress.waitUntil; delete progress.waitDetail;
      const openAt = snapshot.window.openAt;
      const closeAt = snapshot.window.closeAt;
      const chatOpenAt = snapshot.chatWindow.chatOpenAt;
      const chatCloseAt = snapshot.chatWindow.chatCloseAt;
      const CLOCK_SKEW_ALLOW_MS = CHAT_WINDOW_CLOCK_SKEW_MS; // 正典は protocol-v2.js（表示側と同値）
      const chatWindowMs = {
        startMs: Number(chatOpenAt) * 1000 - CLOCK_SKEW_ALLOW_MS,
        endMs: Number(chatCloseAt) * 1000 + CLOCK_SKEW_ALLOW_MS
      };

      await this.storage.delete(`roster_submission_read_failed_block${blockNum}`);

      const resultCount = snapshot.resultCount;

      const meta = {
        contractAddress, resultCount,
        window: { openAt: Number(openAt), closeAt: Number(closeAt) },
        chatWindow: { chatOpenAt: Number(chatOpenAt), chatCloseAt: Number(chatCloseAt), clockSkewAllowMs: CLOCK_SKEW_ALLOW_MS },
        safeBlock: safeBlockNumber.toString(), confirmations,
      };

      if (resultCount === 0) {
        if (quorumClients) {
          await readMatchingFinalizedBlock(quorumClients, safeBlock);
          await this.storage.delete(`rpc_quorum_wait_block${blockNum}`);
        }
        const report = {
          contractAddress, blockNum, resultCount,
          window: meta.window, chatWindow: meta.chatWindow,
          safeBlock: meta.safeBlock, confirmations,
          adopted: [], invalid: [],   // P-2026-0842（台帳 C-3）: 実行時刻は載せない
        };
        if (!progress.rosterSubmission.accepted) report.rosterSubmission = progress.rosterSubmission;
        // 🔴 ラウンド19 判断不要-3 step2 の棚卸し: evidence-report.json も manifest の
        //    `artifactKeys` に載る。put 失敗を握ると「宣言したファイルが無い」manifest を焼く。
        await this.publishEvidenceReportIdempotent(blockNum, report);
        await this.publishEvidenceSegmentArtifact(blockNum, [], {
          progress,
        });
        await this.storage.put(`evidence_reconciled_block${blockNum}`, { resultCount: 0, chatWindowMs, at: Date.now() });
        await this.storage.delete(`evidence_reconcile_failed_block${blockNum}`);
        await this.calcStoreAdopted(blockNum, { adopted: [], invalid: [], meta, reportPublished: true });
        console.log(`[evidence] block ${blockNum}: no on-chain submissions`);
        progress.evidence = { disabled: false, chatWindowMs, resultCount: 0, adoptedCount: 0 };
        progress.stage = 'depids'; progress.cursor = 0;
        return progress;
      }

      // ── R2/R12-06是正: イベント取得の再開可能な範囲歩行＋即D1永続（メモリ有界化） ──
      // dataは最大約260KB/件のhex文字列で、名簿本人の最大長の提出（U-8前は誰でも）を
      // 2,000ブロックぶん配列へ集めると128MBを超える。ブロック幅だけでは同一block集中を
      // 抑えられないため、indexed seq も RESULT_LOG_SEQS_PER_READ件のtopic ORへ刻む。
      // 成功した最小範囲・seq組は即D1へ永続し、同じ物理範囲を1ユニット最大8応答だけ
      // 前進させてから、残りを
      // progress.evidenceIngest.adaptive に保存して返す。
      // したがって分割後の全ログを1配列へ再結合せず、alarmをまたいで続きを再開できる。
      // カーソル= progress.evidenceIngest（segs=歩行区間、segIdx/next=現在の広幅チャンク、
      // adaptive.pending=まだ読んでいない分割範囲）。calc_chunk は既存 phase_task_queue と
      // calc_active の復旧・park・/calc-status 可視化をそのまま使い、新しいキューは作らない。
      // 完全性はseqが1..resultCountの連番（Evidence.solの規約・verifyCompletenessと同一）で
      // あることを **今回の歩行で観測した seq 集合**（ingest.seen）で検証する。不足時は旧実装と同じく
      // 一度だけ範囲を拡張（前方50,000ブロック＋safeBlockまで後方）して再歩行→なお不足はthrow。
      // 1ブロックまで割ってもRPCが拒否した場合だけは、物理的にそれ以上割れないためthrowする。
      //
      // 🔴 P-2026-0813（2026-08-07）: 旧実装はここを **D1 の行数**（COUNT）で数えていた。
      //   前サイクルの残存行（tx_hash が違う旧世界の行）があると、**現行世界のイベントを
      //   1件も取得していない seq でもカウントが埋まり**、RPC の取りこぼしが検出されない。
      //   実測: seq2 を RPC が返さない状況で、残存行が無ければ正しく throw したが、
      //   seq2 に前サイクルの行（valid=1）が残っていると完全性検査を通過し、
      //   本物の seq2 提出が最後まで取得されず消え、seq3 は捨てられた。
      //   対処: 「今回の歩行で実際に観測した seq」だけを数える。
      //
      // 🔴 S3C5（D-06・R33-B-3-02・2026-09-27）: **取り込みの段でその場で判定し、D1 には要約と判定だけを置く。**
      //   旧実装は全イベントの中身（data・1件最大約260KB）を判定の前に D1 へ写し、無効と判定した後も
      //   消さなかった。名簿本人の提出（U-8前は誰でも）が積もるだけで中央 D1 の容量が埋まりうる（旧版のS2）。
      //   いまは各イベントを取り込んだその場で判定し（判定の関数・無効の理由コードは旧検証段と同じ
      //   decodeEvidenceData → validateResultBundle）、行には seq・送り手・tx・ブロック・時刻・
      //   data のバイト長と keccak256・判定・理由・uid・group を置く。中身を残すのは
      //   **各 uid の採用候補（範囲 1..resultCount で最小 seq の有効な1件）だけ**で、より小さい seq の
      //   有効な提出が後から見つかれば入れ替えて前の候補の中身を空ける（下の「候補以外を空ける」SQL）。
      //   無効な提出と、採用候補でない有効な提出（同じ uid の2件目以降）は中身を残さない。
      //   採用候補の中身は calcLoadAdoptedRaw（depids / scoring の採用時の再検証）が読むので、
      //   そのブロックの集計がすべて終わる cleanup（calcFinalizeUnit）まで空けない。
      //   やり直し（/reconcile-evidence・完了済みへの /calculate-results の restart）は calcCleanupKeys で
      //   歩行カーソルごと消すので、必ずチェーンの歩き直しから始まり、中身が空いていても戻る。
      if (!db) throw new Error('[evidence] BITCOINU_DATA binding required');
      if (!progress.evidenceIngest) {
        let { fromBlock, toBlock } = estimateBlockRange(safeBlockNumber, safeBlock.timestamp, Number(openAt), Number(closeAt));
        if (toBlock > safeBlockNumber) toBlock = safeBlockNumber;
        progress.evidenceIngest = {
          segs: [[fromBlock.toString(), toBlock.toString()]],
          segIdx: 0, next: fromBlock.toString(), widened: false, done: false,
          seen: [],   // 観測済み seq の区間表現（calcSeqSeenAdd 参照）
          judgedAtIngest: true,   // S3C5: この歩行の行はすべて取り込み時に判定済み
        };
      }
      const ingest = progress.evidenceIngest;
      // 旧デプロイの進行中カーソル（seen が無い）は観測集合を再現できない。D1 の行数に
      // 頼るくらいなら歩き直す方が安全（ingest は ON CONFLICT で冪等なので再歩行は無害）。
      // S3C5: 取り込み時に判定しない旧デプロイのカーソル（judgedAtIngest が無い）も同じく歩き直す。
      //   旧カーソルの行は判定前（valid IS NULL）か中身を全件持つので、この歩行の規則で書き直す。
      //   seq 1 から歩き直すため nextSeq も捨てる（残すと観測集合の先頭が欠けて完全性で止まる）。
      if (!Array.isArray(ingest.seen) || ingest.judgedAtIngest !== true) {
        console.warn('[evidence] legacy ingest cursor (no observed-seq set or not judged at ingest) — restarting the walk');
        ingest.seen = [];
        ingest.segIdx = 0;
        ingest.next = ingest.segs[0][0];
        ingest.done = false;
        delete ingest.adaptive;
        delete ingest.nextSeq;
        ingest.judgedAtIngest = true;
      }
      if (!ingest.done) {
        // 1ユニットでは同じ物理範囲の成功seq応答を最大8つだけ逐次処理する。範囲過大エラーから最初の
        // 成功範囲へ到達するまでの二分（最大 log2(2000)≒11段）は同じユニット内で行う。
        // 範囲が変わるとき、または8応答後はreturnし、呼び出し側がprogressを永続化してから
        // 次のalarm/ユニットへ進む。各応答をD1へ逃がしてから次を読むため、全量は保持しない。
        // S3C5: 判定を取り込みへ移したので、旧検証段の1ユニットの上限（件数 CALC_EVENTS_PER_UNIT・
        //   data 文字数 CALC_EVENTS_CHARS_PER_UNIT）もここで守る。次の1応答が運びうる最大量
        //   （RESULT_LOG_SEQS_PER_READ 件 × 契約の MAX_DATA_BYTES の hex）を足して上限を超えるなら、
        //   読む前にユニットを返す（最初の1応答は必ず処理する＝旧検証段の「1件目は必ず取る」と同じ前進保証）。
        const readMaxChars = RESULT_LOG_SEQS_PER_READ * (2 + 2 * EVIDENCE_MAX_WIRE_BYTES);
        let judgedThisUnit = 0;
        let judgedCharsThisUnit = 0;
        let membersIndex = null;   // 判定の名簿（D1 game_groups が権威）。ユニットごとに最初の判定で1回だけ作る
        let seqReadsThisUnit = 0;
        while (ingest.segIdx < ingest.segs.length) {
          const segTo = BigInt(ingest.segs[ingest.segIdx][1]);
          const cursor = BigInt(ingest.next);
          if (cursor > segTo) {
            ingest.segIdx++;
            if (ingest.segIdx < ingest.segs.length) ingest.next = ingest.segs[ingest.segIdx][0];
            continue;
          }

          if (!ingest.adaptive) {
            const chunkTo = cursor + BigInt(CALC_EVIDENCE_GETLOGS_WIDTH - 1) > segTo
              ? segTo
              : cursor + BigInt(CALC_EVIDENCE_GETLOGS_WIDTH - 1);
            ingest.adaptive = {
              chunkFrom: cursor.toString(),
              chunkTo: chunkTo.toString(),
              pending: [[cursor.toString(), chunkTo.toString(), String(ingest.nextSeq ?? '1')]],
              splitCount: 0,
            };
          }
          const adaptive = ingest.adaptive;
          if (!Array.isArray(adaptive.pending) || adaptive.pending.length === 0) {
            throw new Error('[evidence] invalid adaptive getLogs cursor');
          }

          let events;
          while (adaptive.pending.length > 0) {
            // 成功範囲はD1保存が完了するまでスタックから外さない。getLogs後のD1一時障害や
            // 通信障害で外側の再試行へ戻っても、同じ範囲から安全にやり直せる。
            const [rangeFromRaw, rangeToRaw, seqFromRaw = '1'] = adaptive.pending[adaptive.pending.length - 1];
            const rangeFrom = BigInt(rangeFromRaw);
            const rangeTo = BigInt(rangeToRaw);
            const seqFrom = BigInt(seqFromRaw);
            const seqTo = seqFrom + BigInt(RESULT_LOG_SEQS_PER_READ - 1) > BigInt(resultCount)
              ? BigInt(resultCount)
              : seqFrom + BigInt(RESULT_LOG_SEQS_PER_READ - 1);
            const seqs = Array.from(
              { length: Number(seqTo - seqFrom + 1n) },
              (_, index) => seqFrom + BigInt(index),
            );
            ingest.rpcCalls = (ingest.rpcCalls || 0) + 1;
            try {
              events = quorumClients
                ? await readMatchingLogs(quorumClients, safeBlock, (client) => fetchResultEventsRange(
                  client, contractAddress, blockNum, rangeFrom, rangeTo, seqs, true,
                ))
                : await fetchResultEventsRange(
                  publicClient, contractAddress, blockNum, rangeFrom, rangeTo, seqs,
                );
              if (quorumClients) await this.storage.delete(`rpc_quorum_wait_block${blockNum}`);
              ingest.lastSuccessfulRange = [rangeFrom.toString(), rangeTo.toString()];
              ingest.lastSuccessfulSeqRange = [seqFrom.toString(), seqTo.toString()];
              break;
            } catch (error) {
              // 1ブロックで票が足りない場合は quorum 待ちのままにする。
              // 範囲超過の拒否が1本でもあり、まだ割れるときだけ分割する。
              if (error?.code === 'rpc_quorum_unavailable'
                  && (!error.logRangeTooLarge || rangeFrom === rangeTo)) throw error;
              const splitError = error?.logRangeTooLarge
                ? new Error('block range too large') : error;
              const { left, right, mid } = splitLogRangeOrThrow(splitError, rangeFrom, rangeTo);
              adaptive.splitCount = (adaptive.splitCount || 0) + 1;
              console.warn(
                `[evidence] getLogs ${rangeFrom}-${rangeTo} too large — splitting into `
                + `${left[0]}-${left[1]} / ${right[0]}-${right[1]}`
              );
              adaptive.pending.pop();
              adaptive.pending.push(
                [right[0].toString(), right[1].toString(), seqFrom.toString()],
                [left[0].toString(), left[1].toString(), seqFrom.toString()],
              );
              ingest.lastSplitAt = mid.toString();
            }
          }
          if (!events) throw new Error('[evidence] adaptive getLogs made no progress');

          if (events.length > 0) {
            if (!membersIndex) {
              const groups = await this.calcLoadGroups(blockNum);
              membersIndex = buildMembersIndex(
                groups.map(g => ({ group_id: g.group_id, members: JSON.parse(g.members || '[]') })), { chatWindow: chatWindowMs }
              );
            }
            let batch = [];
            let batchChars = 0;
            const flush = async () => {
              if (batch.length > 0) await db.batch(batch);
              batch = []; batchChars = 0;
            };
            // seq はチェーン上でブロック順に単調なので、応答は通常 seq 昇順。採用候補の入れ替えを
            // 応答内の並びに依存させないため、念のため seq 昇順に並べてから判定・書き込みする。
            const orderedEvents = [...events].sort((a, b) => Number(a.seq) - Number(b.seq));
            for (const ev of orderedEvents) {
              // ── S3C5（D-06）: その場で判定（旧検証段と同じ関数・同じ理由コード） ──
              let validation;
              const decoded = await decodeEvidenceData(ev.data);
              if (!decoded.ok) {
                validation = { valid: false, reason: decoded.reason };
              } else {
                validation = await validateResultBundle(
                  decoded.raw, blockNum, membersIndex, ev.sender, decoded.compactContext,
                );
              }
              const dataHex = typeof ev.data === 'string' && ev.data.startsWith('0x') ? ev.data : null;
              const dataLen = dataHex ? Math.ceil((dataHex.length - 2) / 2) : null;
              const dataKeccak = dataHex ? keccak256(dataHex) : null;
              // 中身は有効な提出だけ仮に書き、直後の「候補以外を空ける」で最小 seq の1件だけに絞る。
              const retainedData = validation.valid ? ev.data : '';
              // 🔴 P-2026-0813（2026-08-07）: **チェーンが権威。D1 はキャッシュにすぎない。**
              //
              //   旧実装は `WHERE evidence_events.tx_hash != excluded.tx_hash` を付けており、
              //   tx_hash が一致する行は `data` も判定列も一切更新しなかった。つまり運営が
              //   `UPDATE evidence_events SET data=<壊した変種>`（tx_hash は据え置き）を
              //   1回打つだけで、その改竄が**再駆動しても直らない**（実測: 正常なサーバー版が
              //   無効なチェーン版で上書きされ 3人×200pt → {DQ, 100, 200}）。
              //   `SET valid=0, invalid_reason=...` も同様に固着し、ブロック内の Evidence 保険が
              //   全滅したうえ evidence-report.json に虚偽の失格理由が公開された。
              //
              //   対処: WHERE 句を外して**常にチェーンの値で上書き**し、判定列
              //   （valid / invalid_reason / uid / group_id）もその場の判定で書き直す
              //   （S3C5 までは NULL に戻して後段の検証段で判定していた）。
              //   同一イベントを取り込み直しても値は変わらない ── 変わるなら D1 が汚染されていた
              //   ということなので、上書きは常に正しい方向にしか働かない。
              //
              // ⚠️ 採用候補の中身の入れ替えは歩行の途中では前の世界の行に左右されうるが、最後は収束する:
              //   範囲を広げて歩き直す場合、広げる前の1巡目では、欠番の seq に残る前の世界の有効な行が「候補以外を
              //   空ける」の MIN を取り、候補の中身が一時的に空きうる。再歩行は欠番の seq から昇順に全部を取り直す
              //   （INSERT が中身を書き直す）ので、歩行の完了時には MIN は現行世界の行だけで決まる状態に収束する。
              //   採用集合の確定（下の「全件判定済み」）は歩行の完了後にしか始まらない（R-S3C5-T2）。
              batch.push(db.prepare(
                `INSERT INTO evidence_events
                 (kind, block_num, seq, sender, data, tx_hash, evt_block, evt_timestamp, valid, invalid_reason, uid, group_id, ingested_at, data_len, data_keccak)
                 VALUES ('result', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                 ON CONFLICT(kind, block_num, seq) DO UPDATE SET
                   sender = excluded.sender, data = excluded.data, tx_hash = excluded.tx_hash,
                   evt_block = excluded.evt_block, evt_timestamp = excluded.evt_timestamp,
                   valid = excluded.valid, invalid_reason = excluded.invalid_reason,
                   uid = excluded.uid, group_id = excluded.group_id,
                   ingested_at = excluded.ingested_at,
                   data_len = excluded.data_len, data_keccak = excluded.data_keccak`
              ).bind(
                blockNum, ev.seq, ev.sender, retainedData, ev.txHash, ev.evtBlock, ev.timestamp,
                validation.valid ? 1 : 0, validation.reason || null,
                validation.uid || null, validation.groupId ?? null, Date.now(),
                dataLen, dataKeccak,
              ));
              if (validation.valid) {
                // 候補以外を空ける: この uid の行のうち、範囲 1..resultCount で最小 seq の有効な1件
                // （＝採用候補・first-write-wins）以外の中身を空ける。今書いた行が候補でなければ
                // それ自身が空き、候補ならより大きい seq の前の候補が空く（入れ替え）。
                batch.push(db.prepare(
                  `UPDATE evidence_events SET data = ''
                   WHERE kind='result' AND block_num = ? AND uid = ? AND data <> ''
                     AND seq <> (SELECT MIN(seq) FROM evidence_events
                                 WHERE kind='result' AND block_num = ? AND uid = ? AND valid = 1 AND seq BETWEEN 1 AND ?)`
                ).bind(blockNum, validation.uid, blockNum, validation.uid, resultCount));
              }
              batchChars += retainedData.length;
              judgedThisUnit++;
              judgedCharsThisUnit += typeof ev.data === 'string' ? ev.data.length : 0;
              // 🔴 P-2026-0813: 完全性は「今回の歩行で**実際に観測した** seq」で判定する。
              //   1..resultCount の外側は完全性に無関係なので記録しない（記録量の上界を保つ）。
              if (Number(ev.seq) >= 1 && Number(ev.seq) <= resultCount) {
                this.calcSeqSeenAdd(ingest.seen, Number(ev.seq));
              }
              if (batch.length >= RESULT_BATCH_SIZE || batchChars >= CALC_INGEST_CHARS_PER_BATCH) await flush();
            }
            await flush();
            // 判定済み件数（/calc-status の進み具合）。D1 batch がすべて成功してから数える。
            progress.cursor = (progress.cursor || 0) + orderedEvents.length;
          }

          // getLogsと全D1 batchが成功して初めて、このseq組を完了扱いにする。
          // seqはブロック順に単調なので、要求窓の先頭から連続して観測できた区間の直後が
          // 現在の物理範囲で最初の未観測seqになる。空応答だけでなく、8件窓が物理範囲の
          // 境界をまたぐ部分応答でも、そのseqを次の範囲へ渡して現在範囲をpopできる。
          // 8件すべてを観測した場合だけ、同じ範囲の次の8 seqへ進む。
          const completed = adaptive.pending[adaptive.pending.length - 1];
          const completedSeqFrom = BigInt(completed[2] ?? '1');
          const completedSeqTo = completedSeqFrom + BigInt(RESULT_LOG_SEQS_PER_READ - 1) > BigInt(resultCount)
            ? BigInt(resultCount)
            : completedSeqFrom + BigInt(RESULT_LOG_SEQS_PER_READ - 1);
          const returnedSeqs = new Set(events.map((ev) => String(ev.seq)));
          let nextUnobservedSeq = completedSeqFrom;
          while (nextUnobservedSeq <= completedSeqTo && returnedSeqs.has(nextUnobservedSeq.toString())) {
            nextUnobservedSeq++;
          }
          const currentRangeEnded = nextUnobservedSeq <= completedSeqTo;
          const sameRangeContinues = !currentRangeEnded && completedSeqTo < BigInt(resultCount);
          if (currentRangeEnded) {
            adaptive.pending.pop();
            if (adaptive.pending.length > 0) {
              adaptive.pending[adaptive.pending.length - 1][2] = nextUnobservedSeq.toString();
            } else {
              ingest.nextSeq = nextUnobservedSeq.toString();
            }
          } else if (completedSeqTo < BigInt(resultCount)) {
            completed[2] = (completedSeqTo + 1n).toString();
          } else {
            adaptive.pending.pop();
            delete ingest.nextSeq;
          }
          ingest.successfulRanges = (ingest.successfulRanges || 0) + 1;
          seqReadsThisUnit++;
          if (adaptive.pending.length === 0) {
            ingest.next = (BigInt(adaptive.chunkTo) + 1n).toString();
            delete ingest.adaptive;
          }
          // S3C5: 次の1応答で旧検証段の1ユニット上限（件数・文字数）を超えうるなら、読む前に返す。
          const nextReadExceedsJudgeBudget = judgedThisUnit + RESULT_LOG_SEQS_PER_READ > CALC_EVENTS_PER_UNIT
            || judgedCharsThisUnit + readMaxChars > CALC_EVENTS_CHARS_PER_UNIT;
          if (!sameRangeContinues || seqReadsThisUnit >= CALC_EVIDENCE_SEQ_READS_PER_UNIT
              || nextReadExceedsJudgeBudget) {
            return progress;
          }
        }

        // 🔴 全区間の歩行完了後だけ完全性を判定する。分割チャンク単位では当然
        // 1..resultCountが揃わないため、ここを上の成功範囲処理へ移してはいけない。
        // 今回の歩行で観測した seq 集合について verifyCompleteness の
        // 「seq が 1..N を欠番なく被覆」と同値。D1 の行数は見ない＝残存行では埋まらない）
        const { covered, missing } = this.calcSeqSeenCovered(ingest.seen, resultCount);
        if (covered !== resultCount) {
          if (!ingest.widened) {
            console.warn(`[evidence] completeness failed (observed ${covered}, expected ${resultCount}, first missing seq=${missing}) — widening range and re-walking`);
            const firstFrom = BigInt(ingest.segs[0][0]);
            const lastTo = BigInt(ingest.segs[ingest.segs.length - 1][1]);
            const widenedFrom = firstFrom > 50000n ? firstFrom - 50000n : 0n;
            if (widenedFrom === firstFrom && lastTo === safeBlockNumber) {
              throw new Error(`evidence completeness: got ${covered}, expected resultCount=${resultCount} (missing seq ${missing})`);
            }
            // 概算開始点より前に低いseqがあった場合、高いseqだけが元範囲にある。
            // 追加部分だけでなく結合後の全範囲をmissingから再歩行し、元範囲も取り直す。
            ingest.segs = [[widenedFrom.toString(), safeBlockNumber.toString()]];
            ingest.widened = true;
            ingest.segIdx = 0;
            ingest.next = widenedFrom.toString();
            ingest.nextSeq = String(missing);
            delete ingest.adaptive;
            return progress;
          }
          throw new Error(`evidence completeness: got ${covered}, expected resultCount=${resultCount} (missing seq ${missing}, after widening)`);
        }
        ingest.done = true;
      }

      // S3C5（D-06）: 旧実装はここに「未検証行（valid IS NULL）を D1 から data ごと読み出して判定する
      // 検証段」があった。判定は取り込みの段（上）へ移したので、この歩行が書いた行はすべて判定済みで、
      // D1 から中身を読み直して判定することはもう無い（無効な提出の中身は D1 に残っていない）。

      // ── 全件判定済み: 採用集合＋invalid一覧をD1から確定（旧 selectAdoptedResults と同一規則） ──
      // レビューH2: 採用対象は「現行チェーン世界のイベント集合」に限定する。完全性検証済みの
      // 現行世界はseq 1..resultCountの連番（旧実装のcurrentSeqs Setと同値＝範囲条件で表現）。
      // 範囲内の行は、完全性（この歩行で観測した seq 集合）を満たした時点でこの歩行がすべて
      // チェーンの値とその場の判定で書き直している（S3C5）。範囲外の残存行（reset 失敗時のみ
      // 発生し得る）は採用に使わない。一次防御は /reset-block の evidence_events DELETE（H2是正）のまま。
      // seq のキーセットを一回400行だけ読む。カーソルとチャンクは進捗が成功した後にだけ
      // 有効になるため、例外後の再実行は同じ範囲を上書きする。
      const finished = await this.calcFinalizeEvidencePage(blockNum, progress, db, resultCount, meta);
      if (!finished) return progress;
      const segmentFrames = await this.loadEvidenceSegmentFrames(blockNum, db, resultCount);
      await this.publishEvidenceSegmentArtifact(blockNum, segmentFrames, {
        progress,
      });
      const scoringAdopted = finished.adopted;
      await this.storage.put(`evidence_reconciled_block${blockNum}`, {
        resultCount, adoptedCount: scoringAdopted.length, chatWindowMs, at: Date.now()
      });
      await this.storage.delete(`evidence_reconcile_failed_block${blockNum}`);
      console.log(`[evidence] block ${blockNum}: count=${resultCount}, adopted=${scoringAdopted.length}, invalid=${finished.invalidCount}`);
      progress.evidence = { disabled: false, chatWindowMs, resultCount, adoptedCount: scoringAdopted.length };
      delete progress.evidenceIngest; // R2: 歩行カーソルはステージ完了で不要
      delete progress.evidenceFinal;
      progress.stage = 'depids'; progress.cursor = 0;
      return progress;
    } catch (error) {
      if (quorumClients && error?.code === 'rpc_quorum_unavailable') {
        await this.noteRpcQuorumFailure(blockNum, error);
      }
      console.error(`[evidence] reconcile failed for block ${blockNum}:`, error);
      await this.storage.put(`evidence_reconcile_failed_block${blockNum}`, {
        error: String(error?.message || error), at: Date.now()
      });
      throw error;
    }
  }

  // T4: 最終集計の一ページ。取り込みで確定した D1 判定を seq 順に写すだけで、
  // 採用の規則（uid ごとの最小 seq）と invalid の公開順は従来どおり。
  async calcFinalizeEvidencePage(blockNum, progress, db, resultCount, meta) {
    const state = progress.evidenceFinal || { cursor: 0, invalidCount: 0, adoptedCount: 0 };
    const { results = [] } = await db.prepare(
      `SELECT seq, tx_hash, sender, valid, invalid_reason, uid, group_id FROM evidence_events WHERE kind='result' AND block_num = ? AND seq > ? AND seq <= ? ORDER BY seq ASC LIMIT ?`
    ).bind(blockNum, state.cursor, resultCount, CALC_EVIDENCE_FINAL_ROWS_PER_UNIT).all();
    // 作業用チャンクは最初に見た uid の挿入順を保つ。Object.entries は配列添字の
    // uid を先頭へ移すため、最後のページの失敗後に古い件数で切ると採用が欠ける。
    const byUid = new Map();
    for (let i = 0; i < Math.ceil(state.adoptedCount / CALC_EVIDENCE_STORAGE_CHUNK); i++) {
      const chunk = await this.storage.get(this.calcKey(blockNum, 'adopted_work_chunk', String(i)));
      if (!Array.isArray(chunk)) throw new Error(`[evidence] adopted work chunk ${i} missing`);
      for (const a of chunk.slice(0, Math.min(CALC_EVIDENCE_STORAGE_CHUNK, state.adoptedCount - i * CALC_EVIDENCE_STORAGE_CHUNK))) {
        byUid.set(a.uid, { groupId: a.groupId, seq: a.seq, txHash: a.txHash, sender: a.sender });
      }
    }
    let nextSeq = state.cursor + 1;
    const invalidPage = [];
    for (const row of results) {
      if (Number(row.seq) !== nextSeq) {
        throw new Error(`[evidence] row completeness after ingest: missing seq ${nextSeq}; これは事故防止であり、悪意ある改竄は block-verifier が検出する`);
      }
      nextSeq++;
      if (row.valid == null) {
        throw new Error(`[evidence] unjudged row after ingest: seq ${row.seq} has valid=NULL (block ${blockNum}); POST /reconcile-evidence でチェーンから歩き直す`);
      }
      if (!row.valid) {
        invalidPage.push({ seq: row.seq, txHash: row.tx_hash, reason: row.invalid_reason });
      } else if (row.uid != null && !byUid.has(row.uid)) {
        byUid.set(row.uid, { groupId: row.group_id, seq: row.seq, txHash: row.tx_hash, sender: row.sender });
      }
    }
    if (nextSeq <= resultCount && results.length < CALC_EVIDENCE_FINAL_ROWS_PER_UNIT) {
      throw new Error(`[evidence] row completeness after ingest: missing seq ${nextSeq}; これは事故防止であり、悪意ある改竄は block-verifier が検出する`);
    }
    // 同じページの再実行は、進捗に記録された件数以降を切り捨てて上書きする。
    let invalidCount = state.invalidCount;
    let offset = 0;
    while (offset < invalidPage.length) {
      const chunkId = Math.floor(invalidCount / CALC_EVIDENCE_STORAGE_CHUNK);
      const used = invalidCount % CALC_EVIDENCE_STORAGE_CHUNK;
      const key = this.calcKey(blockNum, 'invalid_chunk', String(chunkId));
      const previous = used ? await this.storage.get(key) : [];
      if (!Array.isArray(previous) || previous.length < used) throw new Error(`[evidence] invalid chunk ${chunkId} missing`);
      const take = Math.min(CALC_EVIDENCE_STORAGE_CHUNK - used, invalidPage.length - offset);
      await this.storage.put(key, [...previous.slice(0, used), ...invalidPage.slice(offset, offset + take)]);
      invalidCount += take;
      offset += take;
    }
    const adopted = [...byUid].map(([uid, a]) => ({ uid, groupId: a.groupId,
      seq: a.seq, txHash: a.txHash, sender: a.sender }));
    for (let i = 0; i < Math.ceil(adopted.length / CALC_EVIDENCE_STORAGE_CHUNK); i++) {
      await this.storage.put(this.calcKey(blockNum, 'adopted_work_chunk', String(i)),
        adopted.slice(i * CALC_EVIDENCE_STORAGE_CHUNK, (i + 1) * CALC_EVIDENCE_STORAGE_CHUNK));
    }
    const cursor = nextSeq - 1;
    if (cursor < resultCount) {
      progress.evidenceFinal = { cursor, invalidCount, adoptedCount: adopted.length };
      progress.cursor = cursor;
      return null;
    }
    // 確定記録では従来の Object.entries の列挙順を再現する。配列添字 uid の
    // 順序は evidence-report.json にも流れるため、ここでだけ並べ替える。
    const finalAdopted = Object.values(Object.fromEntries(adopted.map(a => [a.uid, a])));
    const scoringAdopted = adoptedForRoster(finalAdopted, progress.rosterSubmission);
    for (let i = 0; i < Math.ceil(scoringAdopted.length / CALC_EVIDENCE_STORAGE_CHUNK); i++) {
      await this.storage.put(this.calcKey(blockNum, 'adopted_chunk', String(i)),
        scoringAdopted.slice(i * CALC_EVIDENCE_STORAGE_CHUNK, (i + 1) * CALC_EVIDENCE_STORAGE_CHUNK));
    }
    await this.storage.put(this.calcKey(blockNum, 'adopted'), {
      meta, reportPublished: false, adoptedCount: scoringAdopted.length, invalidCount,
      adoptedChunks: Math.ceil(scoringAdopted.length / CALC_EVIDENCE_STORAGE_CHUNK),
      invalidChunks: Math.ceil(invalidCount / CALC_EVIDENCE_STORAGE_CHUNK),
    });
    return { adopted: scoringAdopted, invalidCount };
  }

  async loadEvidenceSegmentFrames(blockNum, db, resultCount) {
    const frames = [];
    let cursor = 0;
    while (cursor < resultCount) {
      const { results = [] } = await db.prepare(
        `SELECT seq, data_len FROM evidence_events WHERE kind='result' AND block_num = ? AND seq > ? AND seq <= ? ORDER BY seq ASC LIMIT ?`
      ).bind(blockNum, cursor, resultCount, CALC_EVIDENCE_FINAL_ROWS_PER_UNIT).all();
      if (results.length === 0) throw new Error(`[evidence-segments] missing seq ${cursor + 1}`);
      for (const row of results) {
        if (Number(row.seq) !== cursor + 1) {
          throw new Error(`[evidence-segments] missing or duplicate seq ${cursor + 1} (got ${row.seq})`);
        }
        frames.push({ seq: row.seq, rawBytes: row.data_len });
        cursor++;
      }
    }
    return frames;
  }

  async publishEvidenceSegmentArtifact(blockNum, frames, options = {}) {
    const key = `games/block${blockNum}/zkp/evidence-segments.json`;
    // The calc driver owns calc progress. Early paths have no calc progress and
    // must not manufacture a grouping progress record (startGrouping reads it).
    const pinKey = `auto:${blockNum}:evidence_segment_pin`;
    const progress = options.progress;
    const earlyPin = progress ? null : await this.storage.get(pinKey);
    const existing = await this.getR2Text(key); // read failure must never turn into overwrite
    let existingVersion;
    if (existing != null) {
      try { existingVersion = JSON.parse(existing).pinVersion; }
      catch { throw new Error(`[evidence-segments] existing artifact is not readable JSON: ${key}`); }
    }
    const version = options.pinVersion || progress?.evidenceSegmentPinVersion || earlyPin
      || existingVersion || CURRENT_EVIDENCE_SEGMENT_PIN_VERSION;
    evidenceSegmentPrice(version); // reject unknown historical versions
    if ((progress?.evidenceSegmentPinVersion && progress.evidenceSegmentPinVersion !== version) || (earlyPin && earlyPin !== version)) {
      throw new Error(`[evidence-segments] pinned version changed for ${key}`);
    }
    if (progress && !progress.evidenceSegmentPinVersion) {
      progress.evidenceSegmentPinVersion = version;
      // The driver persists this same object only after its reset/cancel gate.
    } else if (!progress && !earlyPin) {
      await this.storage.put(pinKey, version);
    }
    const artifact = evidenceSegmentArtifact(frames, version);
    const bytes = JSON.stringify(artifact);
    if (existing === bytes) return artifact;
    if (existing != null) throw new Error(`[evidence-segments] public artifact changed: ${key}`);
    await this.putR2ObjectOrThrow(key, artifact);
    return artifact;
  }

  async publishEmptyEvidenceSegmentArtifact(blockNum) {
    return this.publishEvidenceSegmentArtifact(blockNum, []);
  }

  // ============================================================
  // 🔴 P-2026-0813（2026-08-07）: 歩行中に観測した seq の集合
  // ============================================================
  // 「D1 に行があるか」ではなく「**このサイクルの歩行で実際にチェーンから取得したか**」を
  // 完全性の根拠にするための小さな集合表現。progress（DO storage の1値・128KiB上限）に
  // 載るため、素の配列ではなく**昇順・互いに素な閉区間の配列** `[[lo,hi], ...]` で持つ。
  // Evidence の seq はブロックごとの連番で、歩行はブロック昇順なので通常は区間1個に収まる。
  // 記録対象は 1..resultCount に限定しているので、最悪でも要素数は resultCount/2 で止まる。

  // seq を1つ追加（既に被覆済みなら無変更）。ranges は破壊的に更新して返す。
  calcSeqSeenAdd(ranges, seq) {
    const s = Number(seq);
    if (!Number.isInteger(s)) return ranges;
    let i = 0;
    while (i < ranges.length && ranges[i][1] < s - 1) i++;
    if (i === ranges.length) { ranges.push([s, s]); return ranges; }
    const r = ranges[i];                      // r[1] >= s-1 が保証される＝ s <= r[1]+1
    if (s >= r[0] && s <= r[1]) return ranges;              // 既に被覆
    if (s === r[0] - 1) { r[0] = s; return ranges; }        // 左に隣接（前区間とは s-2 以下で離れている）
    if (s === r[1] + 1) {                                    // 右に隣接 → 次区間と繋がるなら併合
      r[1] = s;
      if (i + 1 < ranges.length && ranges[i + 1][0] === s + 1) {
        r[1] = ranges[i + 1][1];
        ranges.splice(i + 1, 1);
      }
      return ranges;
    }
    ranges.splice(i, 0, [s, s]);                             // 孤立
    return ranges;
  }

  // 1..count の被覆件数と、最初の欠番 seq（無ければ null）
  calcSeqSeenCovered(ranges, count) {
    let covered = 0;
    let missing = null;
    let next = 1;
    for (const [lo, hi] of (Array.isArray(ranges) ? ranges : [])) {
      const a = Math.max(Number(lo), 1);
      const b = Math.min(Number(hi), Number(count));
      if (b < a) continue;
      if (missing === null && a > next) missing = next;
      covered += b - a + 1;
      if (b + 1 > next) next = b + 1;
    }
    if (missing === null && next <= Number(count)) missing = next;
    return { covered, missing };
  }

  // R1是正: adopted/invalid の分割保存。Z2と同じ「チャンク→マーカーの順」で書き、
  // マーカー（calc:{N}:adopted）にはmeta＋件数＋チャンク数のみを持つ（常に小さく有界）。
  // 読み出しはマーカー宣言のチャンク数だけを結合するため、再試行でチャンク数が減った場合の
  // 残存キーは無視され、最終的に calcCleanupKeys のprefix掃除で消える。
  async calcStoreAdopted(blockNum, { adopted, invalid, meta, reportPublished = false }) {
    const adoptedChunks = Math.ceil(adopted.length / CALC_ADOPTED_CHUNK);
    for (let i = 0; i < adoptedChunks; i++) {
      await this.storage.put(this.calcKey(blockNum, 'adopted_chunk', String(i)),
        adopted.slice(i * CALC_ADOPTED_CHUNK, (i + 1) * CALC_ADOPTED_CHUNK));
    }
    const invalidChunks = Math.ceil(invalid.length / CALC_ADOPTED_CHUNK);
    for (let i = 0; i < invalidChunks; i++) {
      await this.storage.put(this.calcKey(blockNum, 'invalid_chunk', String(i)),
        invalid.slice(i * CALC_ADOPTED_CHUNK, (i + 1) * CALC_ADOPTED_CHUNK));
    }
    await this.storage.put(this.calcKey(blockNum, 'adopted'), {
      meta, reportPublished,
      adoptedCount: adopted.length, invalidCount: invalid.length,
      adoptedChunks, invalidChunks
    });
  }

  // withInvalid: invalid一覧はレポート公開（summaryステージ）でのみ必要。攻撃時は
  // メガバイト級になり得るため、depids/scoringでは読み込まない。
  async calcLoadAdopted(blockNum, { withInvalid = false, requireMarker = false } = {}) {
    const rec = await this.storage.get(this.calcKey(blockNum, 'adopted'));
    if (!rec) {
      if (requireMarker) throw new Error('[evidence] 採用の記録の欠け・POST /reconcile-evidence で取り直す');
      return null;
    }
    if (withInvalid && Number(rec.invalidCount) > 10000) {
      throw new Error('[evidence] large invalid list must be read by calcPublishEvidenceReportUnit');
    }
    if (Array.isArray(rec.adopted)) return rec; // 分割前の旧形状（進行中ブロック互換）
    if (!Number.isSafeInteger(rec.adoptedCount) || rec.adoptedCount < 0
      || !Number.isSafeInteger(rec.adoptedChunks) || rec.adoptedChunks < 0
      || (rec.adoptedCount === 0 && rec.adoptedChunks !== 0)
      || (rec.adoptedCount > 0 && (rec.adoptedChunks === 0 || rec.adoptedChunks > rec.adoptedCount))) {
      throw new Error('[evidence] invalid adopted chunk marker');
    }
    const adopted = [];
    for (let i = 0; i < rec.adoptedChunks; i++) {
      const chunk = await this.storage.get(this.calcKey(blockNum, 'adopted_chunk', String(i)));
      if (!Array.isArray(chunk) || chunk.length === 0 || chunk.length > CALC_ADOPTED_CHUNK) {
        throw new Error(`[evidence] adopted chunk ${i} missing or invalid`);
      }
      adopted.push(...chunk);
    }
    if (adopted.length !== rec.adoptedCount) {
      throw new Error(`[evidence] adopted count mismatch: ${adopted.length} != ${rec.adoptedCount}`);
    }
    let invalid = [];
    if (withInvalid) {
      for (let i = 0; i < (rec.invalidChunks || 0); i++) {
        invalid.push(...(await this.storage.get(this.calcKey(blockNum, 'invalid_chunk', String(i))) || []));
      }
    }
    return { ...rec, adopted, invalid };
  }

  // 採用イベントのrawをD1から復元（decodeはvalidate時と同一関数＝バイト同一）
  //
  // 🔴 P-2026-0813（2026-08-07）: **採用のたびに必ず再検証する。**
  //   旧実装は D1 の `data` を復号して**検証なしに**返し、呼び出し側が無条件に
  //   `data.submissions[uid]` へ上書きしていた。`evidence_events` は運営が書けるので、
  //   1回の UPDATE で任意のバイト列を「オンチェーン提出」として採点へ流し込めた。実測:
  //     ・(E) `data` を壊した変種に差し替え（valid=1 据え置き）
  //          → 正常なサーバー版を無効なチェーン版が上書きし {200,200,200} → {DQ,100,200}
  //     ・(F) 実イベント1件の `data` を他人のバンドルの壊れた版に、`uid` をその他人に付け替え
  //          → **一度もオンチェーン提出していない参加者が失格**（攻撃枠は resultCount 個）
  //   対処: 復号後に `validateResultBundle` を**もう一度**通し、valid かつ uid/groupId が
  //   採用レコードの期待値と一致することを要求する。不一致は throw（park）— 採点は進めない。
  //   membersIndex は D1 の game_groups（＝メンバーシップの権威）から作る。
  async calcLoadAdoptedRaw(blockNum, seq, {
    expectUid = null, expectGroupId = null, expectSender = null, expectTxHash = null, membersIndex = null,
  } = {}) {
    const db = this.env.BITCOINU_DATA;
    const row = await db.prepare(
      `SELECT data, sender, tx_hash FROM evidence_events WHERE kind='result' AND block_num = ? AND seq = ?`
    ).bind(blockNum, seq).first();
    // S3C5（D-06）: D1 は採用候補の中身だけを cleanup まで持つ。行はあるのに中身が空なら、
    // 集計の後に空けた後の読み直しか候補の食い違い。チェーンから歩き直せば戻る。
    if (row && row.data === '') {
      throw new Error(
        `[evidence] adopted event seq=${seq} has no retained data in D1 (block ${blockNum}) `
        + '— D1 keeps only adoption candidates until cleanup; POST /reconcile-evidence でチェーンから歩き直す'
      );
    }
    if (!row?.data) throw new Error(`[evidence] adopted event seq=${seq} not found in D1`);
    if (expectSender != null && String(row.sender).toLowerCase() !== String(expectSender).toLowerCase()) {
      throw new Error(`[evidence] adopted event seq=${seq} sender mismatch at adoption time`);
    }
    if (expectTxHash != null && String(row.tx_hash).toLowerCase() !== String(expectTxHash).toLowerCase()) {
      throw new Error(`[evidence] adopted event seq=${seq} tx hash mismatch at adoption time`);
    }
    const decoded = await decodeEvidenceData(row.data);
    if (!decoded.ok) throw new Error(`[evidence] adopted event seq=${seq} decode failed: ${decoded.reason}`);
    if (membersIndex) {
      const v = await validateResultBundle(
        decoded.raw, blockNum, membersIndex, row.sender, decoded.compactContext,
      );
      if (!v.valid) {
        throw new Error(
          `[evidence] adopted event seq=${seq} failed re-validation at adoption time: ${v.reason} ` +
          `— D1 evidence_events is a cache, not the authority (block ${blockNum})`
        );
      }
      if (expectUid != null && String(v.uid) !== String(expectUid)) {
        throw new Error(
          `[evidence] adopted event seq=${seq} uid mismatch at adoption time: bundle=${v.uid} expected=${expectUid} (block ${blockNum})`
        );
      }
      if (expectGroupId != null && Number(v.groupId) !== Number(expectGroupId)) {
        throw new Error(
          `[evidence] adopted event seq=${seq} groupId mismatch at adoption time: bundle=${v.groupId} expected=${expectGroupId} (block ${blockNum})`
        );
      }
    }
    return decoded.raw;
  }

  // 🔴 P-2026-0813: 採用時の再検証に使う membersIndex（D1 game_groups が権威）。
  //   通常は呼び出し側（calcDepIdsUnit / calcScoringUnit）がユニットごとに1回だけ作って渡す。
  //   ここはその取りこぼし用のフォールバックなので、**キャッシュは持たない**
  //   （DO インスタンスは長命で、reset → 再グループ分けを跨いだ古い名簿を掴む方が危ない）。
  async calcMembersIndexForBlock(blockNum) {
    const groups = await this.calcLoadGroups(blockNum);
    return buildMembersIndex(
      groups.map(g => ({ group_id: g.group_id, members: JSON.parse(g.members || '[]') }))
    );
  }

  // 旧2a′のsubmissionsマージをグループ単位で適用（identical/missing/mismatch判定は旧と同一規則）。
  // 戻り値: { [uid]: { seq, txHash, serverState } }
  async calcApplyEvidenceToGroup(blockNum, groupId, data, adoptedList, membersIndex = null) {
    // 🔴 P-2026-0823（2026-08-07）: **`Object.create(null)`**。下の `if (adoption[uid]) continue`
    //   が素の `{}` だと uid=`toString` などで Object.prototype のメソッド（truthy）を拾い、
    //   **採用済みでもないのにスキップ**する＝そのメンバーの Evidence 採用が丸ごと消える
    //   （data.submissions への上書きも adoption レコードも作られない）。
    //   uid=`__proto__` は `adoption[uid] = {...}` が [[Prototype]] 設定に化け、
    //   DO storage へ put した時点で（V8 直列化は [[Prototype]] を運ばない）消える。
    const adoption = Object.create(null);
    let idx = membersIndex;   // 採用が1件も無いグループでは D1 を引かない（遅延構築）
    for (const a of adoptedList) {
      if (a.groupId !== groupId) continue;
      const uid = a.uid;
      // 🔴 P-2026-0813 ⑧: 同一 uid の採用は seq 最小の1件だけ（first-write-wins）。
      //   上流の adoptedByUid が一意性を保証しているが、不変量が別関数にしかない状態だと
      //   ここは黙って last-write-wins になる（同一 uid の2件目が1件目を上書きする）。
      //   採用は「最初の有効なオンチェーン提出」と決まっているので、ここでも明示的に守る。
      if (adoption[uid]) continue;
      if (!idx) idx = await this.calcMembersIndexForBlock(blockNum);
      // 🔴 P-2026-0823（2026-08-07）: `data` は ChatGameDO 応答の `JSON.parse` ＝ **素の `{}`**。
      //   `data.submissionsRaw?.[uid]` を素で引くと uid=`toString` / `constructor` /
      //   `valueOf` / `hasOwnProperty` で **Object.prototype のメソッド**が返り、
      //   サーバー版が存在しないのに `mismatch`（バイト不一致）と誤分類される。
      //   分類そのものは証拠ではない（下の serverState のコメント）が、
      //   **診断のノイズになる**ので潰してはいけない。
      const serverRaw = (hasOwn(data.submissionsRaw, uid) ? data.submissionsRaw[uid] : null) || null;
      const raw = await this.calcLoadAdoptedRaw(blockNum, a.seq, {
        expectUid: uid, expectGroupId: groupId, expectSender: a.sender,
        expectTxHash: a.txHash, membersIndex: idx
      });
      let serverState;
      if (serverRaw === raw) {
        serverState = 'identical'; // バイト一致 → 上書き不要
      } else {
        // 🔴 R18（2026-08-08）で言い回しを実態へ訂正。旧コメント
        //   「missing=握り潰し疑い / mismatch=改ざん疑い」は**誤解を招く**:
        //   ・`mismatch` は**参加者由来でも正常に発生する**。`planOnChainTrim` で
        //     オンチェーン提出用にバンドルを絞って再署名すると、サーバー版とはバイト一致
        //     しなくなる（`docs/CHAT_GAME_SIMPLIFICATION_SPEC.md:739-742` が明記・実害なし）。
        //     実測: キー順を入れ替えただけのバンドルでも valid=true / mismatch / 点数不変。
        //   ・`missing` は WS を経由せずオンチェーンだけに出せば**必ず**立つ
        //     ＝ 正当な自己救済と握り潰しは**この値では区別できない**。
        //     逆向き（運営が `/get-results` にチェーンのバイト列を返して `missing` を消す）も1行で可能。
        //   → **`serverState` は運営の不正の証拠ではない**（分類のメモに過ぎない）。
        //     握り潰しの証明は「チェーンに有効な Result があるのに集計が `no_submit`」だけで、
        //     それを見るのは block-verifier の独立再採点（`check.stageC.summaryMatch`）。
        //     詳細は `docs/EVIDENCE_CENSORSHIP_PLAN.md`。
        serverState = serverRaw == null ? 'missing' : 'mismatch'; // missing=サーバー版なし / mismatch=バイト不一致
        // 🔴 P-2026-0823: 書き戻し先も **プロトタイプ鎖なし**にしてから書く。素の `{}` のままだと
        //   uid=`__proto__` の `data.submissions[uid] = ...` が [[Prototype]] 設定に化けて
        //   **チェーンから復元した提出物が黙って捨てられる**（＝Evidence が効かない）。
        data.submissions = nullProtoMap(data.submissions);
        data.submissions[uid] = decodeSubmissionPayloadString(raw).bundle;
        data.submissionsRaw = nullProtoMap(data.submissionsRaw);
        data.submissionsRaw[uid] = raw;
        data.evidenceSources = nullProtoMap(data.evidenceSources);
        data.evidenceSources[uid] = { seq: a.seq, txHash: a.txHash };
      }
      adoption[uid] = { seq: a.seq, txHash: a.txHash, serverState };
    }
    return adoption;
  }

  // ステージ2: depids — 各グループの提出（evidence採用反映後）から署名済みdepositIdsを収集。
  // B1のブロック全体dedup（検証ツールが再現する正典規則）を正確に保つため、採点前に全グループ分を確定する。
  async calcDepIdsUnit(blockNum, progress) {
    const groups = await this.calcLoadGroups(blockNum);
    const adoptedRec = await this.calcLoadAdopted(blockNum, { requireMarker: !!progress.evidence });
    const adoptedList = adoptedRec?.adopted || [];
    // K-S2-002: エントリー時に確定した depIds（uid → 生の depIds 値）を1回だけ読み込む。
    // 出どころは applicantHash でオンチェーン固定された選出結果（block-verifier と同一ソース）。
    const entryDepIdsByUid = await this.calcLoadEntryDepIds(blockNum);
    // 🔴 P-2026-0813: Evidence 採用の再検証に使う membersIndex は D1（権威）から1回だけ作る。
    const membersIndex = buildMembersIndex(
      groups.map(g => ({ group_id: g.group_id, members: JSON.parse(g.members || '[]') }))
    );
    const start = progress.cursor || 0;
    const slice = groups.slice(start, start + CALC_GROUPS_PER_UNIT);
    for (const g of slice) {
      // K-S2-004: 取得失敗は throw（calcFetchGroupData 内）。旧実装の fetchFailed 記録＝
      // 無言の除外は廃止し、ユニットのリトライ→park に委ねる。
      const data = await this.calcFetchGroupData(blockNum, g.group_id);
      const adoption = await this.calcApplyEvidenceToGroup(blockNum, g.group_id, data, adoptedList, membersIndex);
      // K-S2-002 是正（2026-07-27）: depositId の一覧は **エントリー時に確定した depIds** を権威とする。
      //
      // 旧実装は提出物（submissions[uid].depositIds）から組み立てていた。ウォレット署名済み
      // なので運営は改竄できないが、**参加者本人が後から作ったデポジットを追加できた**。
      // EthLock には応募期間の概念が無く、応募締切後でも新規デポジットを作成できるため、
      // 「0.01 ETH で応募 → 選出とゲーム結果を見てから 10 ETH を作って提出物に足す」
      // （10pt → 316pt）が成立していた。エントリー時にリスクへ晒していない資金で
      // 報酬重みを後出し増額でき、他参加者の取り分を希釈する。
      //
      // エントリー時の depIds は entries/block{N}/game_selection.json に載り、
      // その内容は収集済みエントリーデータから再導出可能で applicantHash として
      // オンチェーンに固定されている（block-verifier check.stageB.playersMatch が
      // canonicalEqual で players[].data 全体を照合する）。したがって運営も事後に書き換えられない。
      //
      // なお **金額と状態はここでは使わない**。ID 一覧だけを確定させ、各 ID の amount /
      // unlockTime は後段の chain ステージでオンチェーンから読み直す（B1 の権威的再検証は維持）。
      //
      // block-verifier は元からエントリー depIds を使っており（src/stages/results.js の
      // parseEntryDepositIds）、旧実装は正典と検証ツールで入力ソースが食い違っていた。
      // 本是正で両者が同一ソースになる。
      // P-2026-0820: uid 鍵の辞書は `Object.create(null)`（`__proto__` uid の代入が消えないように）
      const depositIdsByUid = Object.create(null);
      for (const m of (data.members || [])) {
        if (m?.uid == null) continue;
        depositIdsByUid[String(m.uid)] = this.parseEntryDepositIds(entryDepIdsByUid[String(m.uid)]);
      }
      await this.storage.put(this.calcKey(blockNum, 'prep', g.group_id), { depositIdsByUid, adoption });
    }
    progress.cursor = start + slice.length;
    if (progress.cursor >= groups.length) { progress.stage = 'chain'; progress.cursor = 0; }
    return progress;
  }

// K-S2-002: entries/block{N}/game_selection.json から uid → depIds（生値）を取り出す。
  // これがデポジットID一覧の唯一の権威（エントリー時に確定・applicantHash でオンチェーン固定）。
  async calcLoadEntryDepIds(blockNum) {
    const sel = await this.getR2Object(`entries/block${blockNum}/game_selection.json`);
    const players = Array.isArray(sel?.players) ? sel.players : [];
    if (players.length === 0) {
      throw new Error(`[calc] game_selection.json for block ${blockNum} has no players — cannot resolve entry depositIds`);
    }
    // 🔴 P-2026-0823（2026-08-07）: **`Object.create(null)`**。`depIds` は文字列なので
    //   素の `{}` だと `map['__proto__'] = depIds` が黙って捨てられ、その uid の
    //   エントリー depIds が空になる（= 権威デポジットが 0 扱い＝点数の取りこぼし）。
    //   逆に uid=`toString` の人が居ない場合でも `map['toString']` が
    //   `Object.prototype.toString` を返し、`parseEntryDepositIds` が関数を受け取る。
    const map = Object.create(null);
    for (const p of players) {
      const uid = p?.data?.uid;
      if (uid == null) continue;
      map[String(uid)] = p.data.depIds;
    }
    return map;
  }

  // depIds（文字列JSON or オブジェクト）から depositId 配列を取り出す。
  // block-verifier src/stages/results.js の parseEntryDepositIds と同一規則。
  parseEntryDepositIds(depIdsRaw) {
    if (!depIdsRaw) return [];
    try {
      const parsed = typeof depIdsRaw === 'string' ? JSON.parse(depIdsRaw) : depIdsRaw;
      return Array.isArray(parsed?.ids) ? [...new Set(parsed.ids.map(id => String(id)))] : [];
    } catch { return []; }
  }

  // 全グループのprep記録から perUid（uid→depositIds）を再構成
  async calcAssemblePerUid(blockNum) {
    const prefix = this.calcKey(blockNum, 'prep', '');
    const map = await this.storage.list({ prefix });
    // P-2026-0820: uid 鍵の辞書は `Object.create(null)`。素の `{}` だと
    // `perUid['__proto__'] = ids` が setter に吸われて uid が丸ごと消える。
    const perUid = Object.create(null);
    for (const [, rec] of map) {
      for (const [uid, ids] of Object.entries(rec.depositIdsByUid || {})) perUid[uid] = ids;
    }
    return { perUid };
  }

  // ステージ3: chain — ブロック全体のユニークdepositIdをチャンクでオンチェーン読取（B1部品②）
  async calcChainUnit(blockNum, progress) {
    const { perUid } = await this.calcAssemblePerUid(blockNum);
    const { uniqueIds } = this.calcCollectDepositIds(blockNum, perUid);
    const start = progress.cursor || 0;
    const slice = uniqueIds.slice(start, start + CALC_CHAIN_IDS_PER_UNIT);
    if (slice.length > 0) {
      const k11 = await this.readDepositSelectionK11(blockNum);
      const { chainData, failedReads, archiveFailedReads } = await this.calcFetchDepositsFromChain(slice, k11);
      if (failedReads.length > 0) {
        const error = new Error(`[B1] ${archiveFailedReads?.length ? 'archive_rpc_required: historical EthLock state unavailable; ' : ''}on-chain deposit reads failed for ${failedReads.length}/${slice.length} ids (first: ${failedReads[0]}) — aborting`);
        if (archiveFailedReads?.length) { error.code = 'archive_rpc_required'; error.terminal = true; }
        throw error;
      }
      // BigIntを文字列化して永続（適格フィルタは文字列でも同一判定）
      const stored = {};
      for (const [id, dep] of Object.entries(chainData)) {
        stored[id] = {
          amount: String(dep.amount), unlockTime: String(dep.unlockTime),
          idTo: dep.idTo, depositerAddress: dep.depositerAddress, idFrom: dep.idFrom
        };
      }
      await this.storage.put(this.calcKey(blockNum, 'chain', String(Math.floor(start / CALC_CHAIN_IDS_PER_UNIT))), stored);
    }
    progress.cursor = start + slice.length;
    if (progress.cursor >= uniqueIds.length) { progress.stage = 'vdep'; progress.cursor = 0; }
    return progress;
  }

  // ステージ4: vdep — 適格フィルタ（B1部品③・正典規則そのまま）→ グループ別スライスを永続
  async calcVdepUnit(blockNum, progress) {
    const groups = await this.calcLoadGroups(blockNum);
    const { perUid } = await this.calcAssemblePerUid(blockNum);
    this.calcCollectDepositIds(blockNum, perUid); // vdep単独再開時も総数上限を再検査する
    const chainMap = await this.storage.list({ prefix: this.calcKey(blockNum, 'chain', '') });
    const chainData = {};
    for (const [, slice] of chainMap) Object.assign(chainData, slice);
    const { verifiedDepositWei, verifiedDeposits } = this.calcFilterEligibleDeposits(blockNum, perUid, chainData);
    console.log(`[B1] block ${blockNum}: on-chain verified deposits for ${Object.keys(verifiedDepositWei).length} players (${Object.keys(chainData).length} distinct ids)`);
    for (const g of groups) {
      const memberUids = JSON.parse(g.members || '[]').map(m => String(m.uid));
      // P-2026-0820: uid 鍵の辞書は `Object.create(null)`（`__proto__` uid が消えないように）
      const wei = Object.create(null);
      const deps = Object.create(null);
      for (const uid of memberUids) {
        if (verifiedDepositWei[uid] !== undefined) wei[uid] = verifiedDepositWei[uid];
        if (verifiedDeposits[uid] !== undefined) deps[uid] = verifiedDeposits[uid];
      }
      await this.storage.put(this.calcKey(blockNum, 'vdep', g.group_id), { wei, deps });
    }
    progress.stage = 'scoring'; progress.cursor = 0;
    return progress;
  }

  // ステージ5: scoring — グループ単位で取得→evidenceマージ→アーカイブパッチ→採点→スコア記録を永続。
  // メモリは常に処理中の数グループ分のみ（旧実装の全グループ同時保持を排除）。
  // CPU予算: グループ数上限に加えて実時間ガード（署名検証の重いグループが続く場合の保険）。
  // 🔴 P-2026-0814: ガードは while の条件＝「この時間未満ならもう1グループ入る」なので、
  //    しきい値は **CPU 予算 − 1グループの最悪** でなければならない（CALC_SCORING_GUARD_MS の導出）。
  async calcScoringUnit(blockNum, progress) {
    const groups = await this.calcLoadGroups(blockNum);
    const adoptedRec = await this.calcLoadAdopted(blockNum, { requireMarker: !!progress.evidence });
    const adoptedList = adoptedRec?.adopted || [];
    // P-2026-0821: manifest の宣言値（finalizeVerificationManifest の rules）と同一ソース。
    const { minChars, minMessages } = this.getScoringMins();
    const chatCaps = this.getChatCaps();
    // 🔴 P-2026-0822（2026-08-07・ユーザー確定）: **採点の入口で ZKP ゲスト定数との一致を検査する。**
    //    サーバーは5つのしきい値を環境変数から読むが、ZKP ゲスト（`crates/scoring-core` の
    //    `Rules::default()`）は同じ5つを**定数として ELF に焼いて**いる（2026-08-04 の決定・
    //    「運営が特定ブロックだけ min_chars を下げて仲間を救う」攻撃面を消すため）。
    //    食い違っても従来は**誰にも警告が出なかった**。実測（3人が全員ちょうど500字・
    //    `GAME_MIN_CHARS=501`）: サーバー側 全員0点 ／ 回路側 全員200点 ＝
    //    同一入力から2つの点数表が出て、そのブロックは永久に配布できない。
    //
    //    起動時に1回ではなく**ここ**で検査するのは:
    //      ① 環境変数は起動後にも変わりうる（長寿命の DO には古い値が残る）
    //      ② より本質的に、`calculateGroupResults` はしきい値を**引数で受け取る**ので、
    //         env を検査しても「実際に採点で使われた値」を縛れていない。
    //    ⚠️ `calcScoringUnit` はチャンク実行で1ブロックにつき何度も呼ばれる。それでよい
    //       （呼ばれるたびに守られる）。検査は5値の比較だけで CPU 予算に影響しない。
    assertGuestPinnedRules({ minChars, minMessages, ...chatCaps }, `block ${blockNum} scoring`);
    const chatWindowMs = progress.evidence?.chatWindowMs || null;
    if (!progress.rosterSubmission) {
      throw new Error(`[calc] roster submission decision missing for block ${blockNum} — restart calculation`);
    }
    // 🔴 P-2026-0813: Evidence 採用の再検証に使う membersIndex は D1（権威）から1回だけ作る。
    const membersIndex = buildMembersIndex(
      groups.map(g => ({ group_id: g.group_id, members: JSON.parse(g.members || '[]') }))
    );
    const tUnit = Date.now();
    let processed = 0;
    let cursor = progress.cursor || 0;
    while (cursor < groups.length && processed < CALC_GROUPS_PER_UNIT && (Date.now() - tUnit) < CALC_SCORING_GUARD_MS) {
      const g = groups[cursor];
      cursor++;
      processed++;
      const prep = await this.storage.get(this.calcKey(blockNum, 'prep', g.group_id));
      // K-S2-004: 取得失敗・採点例外を握り潰して「失敗グループ」に落とす経路は廃止した。
      // ここでの例外はそのままユニットの失敗としてリトライ→park に乗る（前掲 calcFetchGroupData の説明）。
      const data = await this.calcFetchGroupData(blockNum, g.group_id);
      applyRosterSubmissionGate(data, progress.rosterSubmission);
      {
        // 防御的な名簿境界: depositIdsByUid は depids 時点の**全メンバー**を鍵に持つため、
        // 正規メンバーの depids→scoring 間の遅延提出はここでは除外しない（採点へ含める）。
        // ここで落ちるのは、上流の member 走査を迂回して混入した非メンバー鍵だけである。
        if (prep?.depositIdsByUid && data.submissions) {
          for (const uid of Object.keys(data.submissions)) {
            // 🔴 P-2026-0820: `in` は**プロトタイプ鎖まで見る**。`prep.depositIdsByUid` は
            //    DO storage から読み戻した素のオブジェクトなので、uid=`toString` /
            //    `constructor` / `valueOf` などは載っていなくても `in` が true になり、
            //    非メンバー鍵として混入した提出物が除外されずに採点へ通っていた。
            if (!Object.prototype.hasOwnProperty.call(prep.depositIdsByUid, uid)) {
              console.warn(`[calc] block ${blockNum} group ${g.group_id}: submission key ${uid} is outside the roster snapshot — excluded from scoring`);
              delete data.submissions[uid];
              if (data.submissionsRaw) delete data.submissionsRaw[uid];
            }
          }
        }
        await this.calcApplyEvidenceToGroup(blockNum, g.group_id, data, adoptedList, membersIndex);
        // レビューH3: vdep記録はvdepステージで全グループ分書かれる。欠落＝パイプライン状態の破損
        // （reset競合等）なので、無言で自己申告デポジットにフォールバックせず明示エラーで停止する。
        const vdep = await this.storage.get(this.calcKey(blockNum, 'vdep', g.group_id));
        if (!vdep) throw new Error(`[calc] vdep record missing for group ${g.group_id} — pipeline state corrupted (reset during drive?)`);
        // 🔴 P-2026-0822（2026-08-07・ユーザー判断 J-10 (B)）: **レコードが在るだけでは足りない。
        //    `vdep.wei` が uid 添字の**オブジェクトである**ことまで見る（同上・同じ作法で throw）。
        //    ここが壊れている（`wei` が欠落 / `null` / 文字列 / 配列）と、
        //    `data.verifiedDepositWei` が非オブジェクトのまま `calculateGroupResults` へ渡り、
        //    そこの**自己申告フォールバック枝**（`verifiedDepositProvided === false`＝
        //    B1 の上限も下限も一切かけない、唯一の残存経路）へ**静かに**落ちる。
        //    その枝はテストと一部ツールのために意図的に残してあるもので、本番からは到達しない。
        //    到達したときの被害は無音（実測: 自己申告 1e12 ETH がそのまま 100,000,000pt）なので、
        //    枝を塞ぐのではなく**枝へ続く扉に鍵をかける**＝入口で止める。
        if (typeof vdep.wei !== 'object' || vdep.wei === null || Array.isArray(vdep.wei)) {
          throw new Error(
            `[calc] vdep record for group ${g.group_id} has a malformed wei table ` +
            `(${Array.isArray(vdep.wei) ? 'array' : (vdep.wei === null ? 'null' : typeof vdep.wei)}) — ` +
            'pipeline state corrupted (reset during drive?); refusing to fall back to self-reported deposits'
          );
        }
        data.verifiedDepositWei = vdep.wei;
        // K-S2-004: ChatGameDO が 200 を返しつつ members が空・欠落しているケースを弾く。
        // calculateGroupResults は members が空だと results:[] を返して「成功」してしまうため、
        // 未初期化DO・cleanup済みDOの応答がそのまま「0人グループの採点成功」として最終化され、
        // 取得失敗と同じ被害（参加者が結果からもMerkleからも消える）を groupId 集合の
        // 照合だけではすり抜ける。名簿の照合は D1（グループ分け時に確定・summary.json で公開済み）を権威に行う。
        this.calcAssertGroupMembers(blockNum, g, data.members);
        // 🔴 P-2026-0813 ④（2026-08-07）: **meta（blockNum / groupId）を採点前に照合する。**
        //   `calculateGroupResults` は `data.meta.blockNum` / `data.meta.groupId` を無検証で信用し、
        //   その2値が chatHash・msgKey・actionHash・受領証明の**署名文脈すべて**を支配する。
        //   ChatGameDO の応答は運営が完全に掌握しているので、meta を差し替えるだけで
        //   グループ全員を任意の理由で失格にできた（実測: groupId=999 → 3人×200pt が全員
        //   `chathash_mismatch` で 0pt / blockNum 違い・meta 欠落 → 全員 `invalid_signature`）。
        //   **全員がオンチェーン提出済みでも同じ**＝ Evidence が一切効かない検閲レバーだった。
        //   独立検証ツールには既にこの検査がある（block-verifier/src/stages/results.js の
        //   `check.stageC.groupMeta`）ので、正典側にだけ無い非対称を解消する。
        if (Number(data.meta?.blockNum) !== Number(blockNum) ||
            Number(data.meta?.groupId) !== Number(g.group_id)) {
          throw new Error(
            `[calc] scoring: group meta mismatch for block ${blockNum} group ${g.group_id} — ` +
            `got blockNum=${data.meta?.blockNum} groupId=${data.meta?.groupId} ` +
            `(meta drives every signature context: chatHash / msgKey / actionHash / receipts)`
          );
        }
        // 🔴 P-2026-0812: 名簿の**並び**を D1（権威）に揃えてから採点する。
        //    結果行の並びがそのまま summary.json に載り、block-verifier が
        //    グループ分けを独立再現して厳密一致で照合するため。
        // 🔴 P-2026-0813: 名簿は **D1（権威）のものへ置き換える**。並びだけでなく
        //    `addr` / `bAddr` / `depIds` も D1 の値にする（ChatGameDO の応答は運営が掌握しており、
        //    `bAddr` を1人ぶん差し替えるだけでその人を失格にできた）。
        data.members = this.calcNormalizeRoster(g, data.members);
        // K-S2-001: 採点入力は必ず submissionsRaw から導出する（parsed を直接信用しない）
        this.deriveSubmissionsFromRaw(data, g.group_id);
        // Stage 3: 採点と同じ権威入力を、後段の group-guest が読む witness として確定する。
        // vdep はこの直前に形状検査済み、members は D1 権威へ正規化済み、submissions は
        // raw から再導出済み、chatWindowMs は Evidence の宣言窓である。Cloud Run 側で
        // 21,000件の EthLock 読取をやり直さず、この同じ入力から proof を作る。
        const groupWitness = buildGroupWitness({
          // test/recovery由来の旧D1 rowは block_num を省略し得る。採点ドライバが確定済みの
          // blockNum と、現在走査中の group_id を権威として明示し、rowの省略値へ依存しない。
          groupRow: { ...g, block_num: blockNum, group_id: g.group_id },
          groupData: data,
          verifiedDepositWei: vdep.wei,
          chatWindow: chatWindowMs,
        });
        await this.putR2ObjectOrThrow(
          `zkp/block${blockNum}/group-${g.group_id}.json`,
          groupWitness,
        );
        const groupWitnessText = JSON.stringify(groupWitness);
        const groupWitnessMeta = {
          key: `zkp/block${blockNum}/group-${g.group_id}.json`,
          sha256: await this.sha256Hex(groupWitnessText),
          bytes: new TextEncoder().encode(groupWitnessText).byteLength,
        };
        const { results: memberResults, canonicalTimeline } =
          await calculateGroupResults(data, minChars, minMessages, chatCaps, chatWindowMs);

        // Stage 3 は採点の別実装ではなく、同じ権威入力を group-guest の入力形へ写す。
        // witness の bytes と sha256 は採点完了時に同時に固定し、後段では大きな公開物を
        // 読み直さず score record の小さな pin だけから集約入力目録を組み立てる。
        const stage3WitnessPin = await this.publishStage3GroupWitness({
          blockNum, groupRow: g, groupData: data,
          verifiedDepositWei: vdep.wei, chatWindow: chatWindowMs,
        });

        // Evidence で採用した提出物と、結果表示用タイムラインを同じ CAS で公開する。
        // 🔴 P-2026-0813 ⑦: submissions は必ず deriveSubmissionsFromRaw の**後ろ**で書く。
        //   これで公開アーカイブの提出物と実際の採点入力が一致する。
        //
        // 結果画面が表示する会話・投票・密告は、生の ChatGameDO 保存値ではなく
        // **この採点で確定した union** を唯一の正典にする。投票／密告には復号済み標的も含む。
        // タイムラインは最大チャット量に比例して大きくなり得るため、DO の score レコードへ
        // 重複保存せず、採点直後に対象 group archive へ CAS で確定する。
        // ここが失敗したまま後段（manifest / root）へ進むと、画面と検証ツールが参照すべき
        // 成果物が欠落するため fail-closed。再駆動時は同じ入力から同じ配列を書ける。
        {
          const r2Key = `games/block${blockNum}/group${g.group_id}.json`;
          const archiveWrite = await this.mutateR2ObjectWithCAS(r2Key, (archiveData) => {
            if (data.evidenceSources && Object.keys(data.evidenceSources).length > 0) {
              archiveData.submissions = data.submissions || archiveData.submissions;
              archiveData.submissionsRaw = data.submissionsRaw || archiveData.submissionsRaw;
              archiveData.evidenceSources = data.evidenceSources;
            }
            archiveData.canonicalTimeline = canonicalTimeline;
          }, { tag: 'scoring-canonical' });
          if (!archiveWrite.ok) {
            throw new Error(
              `[calc] canonical scoring archive write failed for ${r2Key}: `
              + (archiveWrite.missing ? 'archive missing' : (archiveWrite.error || 'unknown'))
            );
          }
          if (data.evidenceSources && Object.keys(data.evidenceSources).length > 0) {
            console.log(`[evidence] archive patched with on-chain submissions: ${r2Key}`);
          }
        }

        await this.storage.put(this.calcKey(blockNum, 'score', g.group_id), {
          groupId: g.group_id,
          members: memberResults,
          groupWitness: groupWitnessMeta,
          evidenceSources: data.evidenceSources || {},
          adoption: prep?.adoption || {},
          stage3: stage3WitnessPin,
        });
      }
    }
    progress.cursor = cursor;
    if (cursor >= groups.length) { progress.stage = 'rewards'; progress.cursor = 0; }
    return progress;
  }

  // ============================================================
  // K-S2-004 是正（2026-07-27）: グループ完全性の fail-closed 検査
  // ============================================================
  // 旧実装は「取得できたグループ・採点できたグループだけ」で報酬按分・summary・Merkle を
  // 組み立てていた。欠けたグループは未配分にならず残存グループへ再按分されるため、
  //   ・運営が狙ったグループの応答だけ失敗させれば自分の取り分を増やせる
  //   ・一過性の 5xx でも同じ結果になり、被害者の leaf は永久に存在しない（請求不能）
  // という状態だった。ここでは各境界で「D1 に登録された全グループが、D1 の名簿どおりの
  // メンバーで採点されている」ことを要求し、1件でも欠ければ throw して park に倒す。
  //
  // 名簿まで見るのは、groupId 集合の照合だけでは
  // 「グループは在るがメンバーが空（未初期化DOの 200 応答）」を通してしまうため。

  // uid 集合の正準化（型ゆらぎを吸収し順序に依存しない比較にする）
  calcMemberUidSet(members) {
    const set = new Set();
    for (const m of (Array.isArray(members) ? members : [])) {
      if (m?.uid == null) continue;
      set.add(String(m.uid));
    }
    return set;
  }

  // D1 game_groups.members（グループ分け時に確定・summary.json で公開済み）を権威の名簿とする
  calcD1GroupUids(g) {
    let parsed;
    try {
      parsed = JSON.parse(g.members || '[]');
    } catch (e) {
      throw new Error(`[calc] game_groups.members for group ${g.group_id} is not valid JSON: ${e.message}`);
    }
    const set = this.calcMemberUidSet(parsed);
    if (set.size === 0) {
      throw new Error(`[calc] game_groups.members for group ${g.group_id} is empty — grouping data corrupted`);
    }
    return set;
  }

  calcAssertGroupMembers(blockNum, g, actualMembers, where = 'scoring') {
    const expected = this.calcD1GroupUids(g);
    const actual = this.calcMemberUidSet(actualMembers);
    // 🔴 P-2026-0811 #14（2026-08-05）: **重複 uid が Set 比較を素通りしていた。**
    //    `members` に同じ uid が2回入っていても集合としては一致するため、
    //    pro-rata の分母が二重計上され、その uid の点数が2回加算された。
    //    件数を先に見て落とす（block-verifier は既に JSON 厳密一致で照合しており、
    //    DO 側だけが緩かった）。
    const actualUids = (Array.isArray(actualMembers) ? actualMembers : []).map(m => m?.uid);
    if (actualUids.length !== actual.size) {
      const dup = actualUids.filter((u, i) => actualUids.indexOf(u) !== i);
      throw new Error(
        `[calc] ${where}: duplicate uid in member roster for block ${blockNum} ` +
        `group ${g.group_id} — ${[...new Set(dup)].join(',')}`
      );
    }
    const missing = [...expected].filter(u => !actual.has(u));
    const extra = [...actual].filter(u => !expected.has(u));
    if (missing.length > 0 || extra.length > 0) {
      throw new Error(
        `[calc] ${where}: member roster mismatch for block ${blockNum} group ${g.group_id} — ` +
        `expected ${expected.size} uids, got ${actual.size} ` +
        `(missing: ${missing.join(',') || '-'} / unexpected: ${extra.join(',') || '-'})`
      );
    }
    // 🔴 P-2026-0812/0813: **名簿は `calcNormalizeRoster` が D1（権威）のものへ置き換える。**
    //    `calculateGroupResults` は結果行を名簿の並びで返し、それが
    //    `games/block{N}/summary.json` の `groups[].members[]` になって
    //    manifest → HashStorage にアンカーされる。block-verifier はグループ分けを
    //    独立再現して `canonicalEqual`（JSON 厳密一致）でこの並びを照合している
    //    （`block-verifier/src/stages/grouping.js` の `summaryStructure`）。
    //    ここが集合比較だけだと、ChatGameDO が別の順で名簿を返した再集計
    //    （reset 後の再実行など）で**同じ採点結果なのに summary.json のバイト列が変わり**、
    //    アンカー済みの manifestHash と食い違って検証が落ちる。
    //    ここ（集合の照合）は従来どおり順序を見ない。順序は採点の直前に正規化する。
  }

  /// 名簿を **D1 `game_groups.members`（グループ分け時に確定した権威データ）そのもの**に置き換える。
  ///
  /// 🔴 P-2026-0812（2026-08-06）: `calculateGroupResults` は結果行を渡された名簿の並びで返し、
  ///    それが `games/block{N}/summary.json` の `groups[].members[]` になって
  ///    manifest → HashStorage にアンカーされる。block-verifier はグループ分けを**独立再現**し
  ///    `canonicalEqual`（JSON 厳密一致）でこの並びを照合する
  ///    （`block-verifier/src/stages/grouping.js` の `summaryStructure`）。
  ///    ChatGameDO が別の順で名簿を返すと、**同じ採点結果なのに summary.json のバイト列が変わり**
  ///    アンカー済みの manifestHash と食い違う。
  ///
  /// ⚠️ **弾かずに揃える**のが正しい。D1 が権威だと明示されている以上、
  ///    権威に合わせるのは「黙って直す」ではなく**定義に合わせる**操作だから。
  ///    集合の一致は `calcAssertGroupMembers` が別途 fail-closed で保証しているので、
  ///    ここで置き換えてもメンバーが増減することはない。
  ///
  /// 🔴 P-2026-0813（2026-08-07）: **並び順だけでなく「中身」も D1 のものにする。**
  ///    旧実装は並べ替えるだけで、member オブジェクト（`addr` / `bAddr` / `depIds`）は
  ///    ChatGameDO の応答のままだった。`calcAssertGroupMembers` は **uid 集合と重複しか見ない**ので、
  ///    運営が `/get-results` の応答で**1人の `bAddr` だけを差し替える**と、
  ///    その人の発言・投票・受領証明の署名検証がすべて落ちる。実測（3人・各1 ETH・巡回投票）:
  ///
  ///      D1 どおり          → 1:200  2:200  3:200
  ///      p2 の bAddr だけ差替 → 1:200  **2:0 (min_chars, min_messages, no_vote)**  3:100
  ///      bAddr を全員入替    → 全員 0
  ///      addr を全員入替     → 全員 0 (invalid_signature)
  ///
  ///    uid 集合は一致したままなので既存ガードを素通りする。狙った1人だけを 200pt → 0pt にでき、
  ///    その人に投票していた第三者も巻き添えで落ちる（点数は pro-rata なので他へ移動）。
  ///    **全員がオンチェーン提出済みでも同じ** — Evidence は `submissions` しか差し替えないので
  ///    名簿には一切効かない。P-2026-0813 ④ で塞いだ `meta` とまったく同型の検閲レバー。
  ///    📌 独立検証ツールには**既にこの検査がある**
  ///       （`block-verifier/src/stages/results.js` の `check.stageC.groupMembersMatch` が
  ///        `canonicalEqual(data.members, 独立再構成した D1 members)`）。
  ///        またしても「検証ツールにはあるのに正典に無い」形だった。
  calcNormalizeRoster(g, actualMembers) {
    if (!Array.isArray(actualMembers)) return actualMembers;
    let d1Members = null;
    try {
      const parsed = JSON.parse(g.members || '[]');
      if (Array.isArray(parsed)) d1Members = parsed;
    } catch { /* JSON 不正は calcD1GroupUids が既に throw 済み */ }
    if (!Array.isArray(d1Members)) return actualMembers;

    // 🔴 P-2026-0813: 長さ不一致は**黙って no-op にしない**。
    //    旧実装は `return actualMembers` していたため、D1 側に重複 uid があると
    //    （`calcAssertGroupMembers` は DO 側の重複しか見ないので集合比較は通る）
    //    正規化が丸ごと飛んで並びが DO 依存に戻り、しかもログすら出なかった。
    //    D1 が権威である以上、権威が壊れているなら止めるべき。
    if (d1Members.length !== actualMembers.length) {
      throw new Error(
        `[calc] group ${g.group_id}: D1 game_groups.members has ${d1Members.length} entries ` +
        `but ChatGameDO returned ${actualMembers.length} — authoritative roster is inconsistent`
      );
    }
    const seen = new Set();
    for (const m of d1Members) {
      const u = String(m?.uid);
      if (seen.has(u)) {
        throw new Error(
          `[calc] group ${g.group_id}: duplicate uid ${u} in D1 game_groups.members ` +
          `— authoritative roster is corrupted`
        );
      }
      seen.add(u);
    }
    // 権威データそのものを返す（並びも中身も D1）。
    return d1Members;
  }

  // 報酬按分・summary 公開の直前関門。部分ブロックの最終化を構造的に拒否する。
  async calcAssertGroupsComplete(blockNum, groups, where) {
    for (const g of groups) {
      const rec = await this.storage.get(this.calcKey(blockNum, 'score', g.group_id));
      if (!rec) {
        throw new Error(`[calc] ${where}: score record missing for block ${blockNum} group ${g.group_id} — refusing to finalize a partial block`);
      }
      if (rec.failed) {
        throw new Error(`[calc] ${where}: group ${g.group_id} is marked failed (${rec.reason || 'unknown'}) — refusing to finalize a partial block`);
      }
      this.calcAssertGroupMembers(blockNum, g, rec.members, where);
    }
  }


  // ============================================================
  // K-S2-001 是正（2026-07-27）: 採点入力を submissionsRaw から必ず導出する
  // ============================================================
  // 背景: 同じ提出物が submissionsRaw（生バイト列）と submissions（パース済み）の
  // **2つのフィールド**に別々に保存されていた。Evidence 照合は submissionsRaw だけを
  // チェーンと突き合わせ、一致すれば「直すものは無い」として submissions に触れなかった。
  // しかし採点が読むのは submissions のほう。運営は submissionsRaw をチェーンと同一のまま
  // 残し、submissions だけを削除・改変することで、Evidence にオンチェーン提出が
  // 存在するにもかかわらず任意の参加者を no_submit / invalid_signature 等で失格にできた。
  // block-verifier も同じ分岐を複製していたため公式検証でも検出できなかった。
  //
  // 対処: submissions を submissionsRaw の**派生値**にする。これにより
  // 「チェーンで裏の取れたバイト列」と「採点に使う値」が同一物になり、
  // 片方だけを差し替える経路が構造的に消える。
  // （通常の提出経路は chat-game-DO が bundle と raw を同時に保存するため、
  //   提出があれば raw も必ず存在する。raw の無い parsed は honest path では発生しない）
  deriveSubmissionsFromRaw(data, groupId) {
    const raws = data?.submissionsRaw || {};
    const parsed = data?.submissions || {};
    // parsed だけ存在して raw が無い＝DO 応答の不整合。無言で落として誰かを失格に
    // するより、パイプラインを止めて可視化する（fail-closed）。
    // 🔴 P-2026-0823（2026-08-07）: `in` は**プロトタイプ鎖まで見る**。`raws` は DO 応答の
    //   `JSON.parse` 由来＝素の `{}` なので、uid=`toString` / `constructor` / `valueOf` /
    //   `hasOwnProperty` は raw が無くても `uid in raws` が true になり、この fail-closed 検査
    //   （= 運営が raw を消して parsed だけ残す改竄の検出）が**その uid でだけ素通り**していた。
    for (const uid of Object.keys(parsed)) {
      if (!Object.prototype.hasOwnProperty.call(raws, uid)) {
        throw new Error(`[calc] submissionsRaw missing for uid=${uid} (group ${groupId}) — parsed/raw inconsistency`);
      }
    }
    // 🔴 P-2026-0823: **`Object.create(null)`**。素の `{}` だと uid=`__proto__` の
    //   `derived[uid] = v` が [[Prototype]] 設定に化けて own property にならず、
    //   採点入力から提出物が丸ごと消える＝理由の見えない `no_submit` 失格になる。
    const derived = Object.create(null);
    for (const [uid, raw] of Object.entries(raws)) {
      let v;
      try {
        v = decodeSubmissionPayloadString(raw).bundle;
      } catch (e) {
        throw new Error(`[calc] submissionsRaw for uid=${uid} (group ${groupId}) is not a valid compact submission: ${e.message}`);
      }
      // 🔴 P-2026-0813 ⑤（2026-08-07）: **パースの成否だけでは足りない。**
      //   `JSON.parse` は `"null"` / `"123"` / `'"str"'` / `"[]"` も成功させる。旧実装はその値を
      //   そのまま `data.submissions[uid]` に置いていたので、
      //     raw="null"  → 提出が無いのと同じ扱い＝**理由の見えない `no_submit` 失格**
      //     raw="123" / '"str"' / "[]" → `invalid_signature` 失格
      //   になった。運営が raw を1バイト（`null`）に書き換えるだけで、提出済みの参加者を
      //   「そもそも提出していない人」として消せる＝ここは黙って通してはいけない境界。
      //   バンドルは必ずオブジェクト。そうでなければ park に倒して可視化する（fail-closed）。
      if (!v || typeof v !== 'object' || Array.isArray(v)) {
        throw new Error(
          `[calc] submissionsRaw for uid=${uid} (group ${groupId}) is not a JSON object ` +
          `(got ${Array.isArray(v) ? 'array' : (v === null ? 'null' : typeof v)}) — refusing to treat it as a submission`
        );
      }
      derived[uid] = v;
    }
    data.submissions = derived;
    return data;
  }

  // ステージ6: rewards — 全スコア記録を読み戻し、ブロック報酬の按分を1回で実行
  // （ポイントは全グループ確定済み＝軽量。以下の「// 4.」〜50/50スプリットは
  //   block-verifier ミラー台帳 mirrorRewardSplit の対象領域＝バイト無変更で維持）。
  async calcRewardsUnit(blockNum, progress) {
    const groups = await this.calcLoadGroups(blockNum);
    // K-S2-004: 按分は「全グループが揃っている」ことを前提に行う。1グループでも欠けた状態で
    // 分母を作ると、欠けた分の報酬が残存グループへ再按分され不可逆に最終化される。
    await this.calcAssertGroupsComplete(blockNum, groups, 'rewards');
    // スコア記録からallGroupResultsを再構成（D1グループ行の順序＝旧groupDataList順と同一）
    const allGroupResults = [];
    for (const g of groups) {
      const rec = await this.storage.get(this.calcKey(blockNum, 'score', g.group_id));
      allGroupResults.push({ groupId: g.group_id, members: rec.members });
    }
    if (allGroupResults.length === 0) {
      throw new Error('No group results could be calculated');
    }
    // オンチェーン検証済みデポジット（vdepスライスの合成）
    // 🔴 P-2026-0820（2026-08-07）: `Object.assign` は **[[Set]]** なので、素の `{}` を
    //    ターゲットにすると own property の `__proto__` が setter に吸われて uid が消える。
    //    消えた uid はデポッター配当のフォールバック（自己申告キャッシュ）へ落ちる。
    const verifiedDeposits = Object.create(null);
    {
      const vdepMap = await this.storage.list({ prefix: this.calcKey(blockNum, 'vdep', '') });
      for (const [, rec] of vdepMap) Object.assign(verifiedDeposits, rec.deps || {});
    }

    // 4. 全グループのtotalPointsを集計
    let totalPoints = 0;
    for (const group of allGroupResults) {
      for (const member of group.members) {
        totalPoints += member.totalPoints;
      }
    }

    // 5. BTCu分配 (BigInt演算)
    const blockRewardWei = getBlockRewardWei(blockNum);

    for (const group of allGroupResults) {
      for (const member of group.members) {
        if (member.isDisqualified || totalPoints === 0) {
          member.btcuReward = '0';
        } else {
          member.btcuReward = (
            blockRewardWei * BigInt(member.totalPoints) / BigInt(totalPoints)
          ).toString();
        }
        // 50/50スプリット前の元報酬を保存（プレイヤー+デポジッター合計）
        member.fullReward = member.btcuReward;
      }
    }

    // 6. BTCu 50/50 Split: プレイヤー50% / デポジッター50%
    //    デポジッター配当の宛先（depositerAddress）と金額（amount＝プロラタの重み）は
    //    エントリー時の自己申告キャッシュ（D1/R2）ではなく、B1でオンチェーン検証済みの
    //    verifiedDeposits を権威とする。→ 運営が保存データを書き換えても配当先・比率を
    //    変更できない（プレイヤー側のwalletSignature束縛と同水準の保証）。
    //    verifiedDeposits に無いuid（旧データ・未提出者の報酬0行）のみキャッシュへフォールバック。
    const depositorResults = [];

    const parseDepIds = (depIdsRaw) => {
      if (!depIdsRaw) return null;
      try {
        return typeof depIdsRaw === 'string' ? JSON.parse(depIdsRaw) : depIdsRaw;
      } catch { return null; }
    };

    // オンチェーン検証済みデポジット（適格のみ・depositId昇順）
    const onchainDepositsOf = (uid) => {
      const verified = verifiedDeposits[uid];
      if (!Array.isArray(verified) || verified.length === 0) return null;
      return {
        source: 'onchain',
        deposits: verified,
        totalWei: verified.reduce((s, d) => s + BigInt(d.amount), 0n)
      };
    };
    // エントリー時キャッシュ（フォールバック専用: 旧データ／未提出者の報酬0行の上書き用）
    const cachedDepositsOf = (memberInfo) => {
      const depIds = parseDepIds(memberInfo?.depIds);
      if (!depIds?.deposits?.length) return null;
      const deposits = depIds.deposits.map(d => ({
        depositId: String(d.id),
        amount: d.amount,
        depositerAddress: d.depositerAddress || null,
        idFrom: d.idFrom ?? null
      }));
      // F-R1 是正（Lean 監査 finding）: 分母は自己申告の depIds.deposit ではなく、按分に使う各 amount の
      // 実合計にする。分子(amount)と分母(Σamount)を同一由来にすることで、末尾デポジットが負の報酬に
      // なる経路を構造的に排除（Σweights=1・非末尾合計≤dst・末尾=残余≥0）。Lean: Reward.fr1_last_nonneg。
      let totalWei = 0n;
      for (const d of deposits) { try { totalWei += BigInt(d.amount); } catch { /* skip malformed */ } }
      return { source: 'cache', deposits, totalWei };
    };

    for (const group of allGroupResults) {
      const groupRow = groups.find(g => g.group_id === group.groupId);
      const memberData = groupRow ? JSON.parse(groupRow.members || '[]') : [];

      for (const member of group.members) {
        const totalReward = BigInt(member.btcuReward || '0');

        const memberInfo = memberData.find(m => m.uid === member.uid);
        // 請求データ自己完結化（2026-08-01）: **報酬>0 のときはオンチェーン検証済みのみを使う。**
        //   デポッター葉は「適格集合そのもの」を setHash で葉に焼き込み、
        //   TokenMining.claimLockReward の _resolveLockRewardSplit は集合の**全件**を再検証して1件でも不適格なら revert する。
        //   自己申告キャッシュ由来の未検証 ID が1つ混ざるだけで、そのプレイヤーのデポッター配分が
        //   **丸ごと永久に請求不能**になる（旧方式ではその1件の葉が無効になるだけだった）。
        //   キャッシュ経路は当初から「旧データ／未提出者の報酬0行の上書き用」であり、
        //   報酬>0 の正常系はオンチェーン検証を必ず通過している。
        const onchain = onchainDepositsOf(member.uid);
        const depInfo = totalReward === 0n ? (onchain || cachedDepositsOf(memberInfo)) : onchain;
        if (totalReward > 0n && !onchain && cachedDepositsOf(memberInfo)) {
          console.warn(`[reward] block ${blockNum}: player ${member.uid} has cached depIds but no on-chain verified deposits — player takes 100% (unverified ids must never enter setHash)`);
        }

        // 報酬0（失格・無得点）でも各デポジットを報酬0でdepositorResultsへ登録する。
        // ここでskipすると、過去集計で付いたデポジット報酬が中央game_results・
        // シャードwin_blocksに残存し、再集計しても上書きされない（失格者が報酬を持ち続ける）。
        if (totalReward === 0n) {
          member.playerShare = '0';
          if (depInfo?.deposits?.length) {
            member.depositorShare = '0';
            for (const dep of depInfo.deposits) {
              depositorResults.push({
                groupId: group.groupId,
                playerUid: member.uid,
                depositorUid: dep.idFrom,
                depositId: dep.depositId,
                depositerAddress: dep.depositerAddress || null,
                depositAmount: dep.amount,
                btcuReward: '0',
                isPlayerSelf: dep.idFrom === member.uid
              });
            }
          }
          continue;
        }

        if (!depInfo?.deposits?.length || depInfo.totalWei <= 0n) {
          // 適格deposit詳細なし → プレイヤーが全額取得
          // （報酬>0の非失格者は署名済みdepositIdsのオンチェーン検証を通過している＝
          //   通常ここには来ない。旧データのみの経路）
          member.playerShare = totalReward.toString();
          continue;
        }

        const playerShare = totalReward / 2n;
        const depositorShareTotal = totalReward - playerShare;
        member.btcuReward = playerShare.toString();
        member.playerShare = playerShare.toString();
        member.depositorShare = depositorShareTotal.toString();

        // プロラタ配分（重み＝オンチェーンamount）。**全員切り捨て**（SPEC §7・2026-08-01）。
        // 旧規則「端数は最後のdeposit（depositId昇順の末尾）へ」は順序依存で、
        // 契約が請求時に計算する額（自分のamountと分母だけで決まる）と一致しなかった。
        // 端数（最大 N−1 wei）は誰にも配られず未請求のまま残る。
        // ⚠️ ここは表示値（summary / D1）を作る場所。契約 TokenMining._payLockReward の
        //    `(depositorShareTotal * myAmount) / totalDepWei` と**同じ式**でなければ
        //    「表示額と実際に届く額が違う」ことになる。式は depositorShareOf 1箇所に集約。
        const totalDepWei = depInfo.totalWei;

        for (let i = 0; i < depInfo.deposits.length; i++) {
          const dep = depInfo.deposits[i];
          const depBtcu = depositorShareOf(depositorShareTotal, dep.amount, totalDepWei);

          // F-R1 belt-and-suspenders: 切り捨て式では負にならないはずだが、万一（別経路・
          // 将来の回帰）でも負の報酬を保存せず顕在化させる（無言スキップ禁止の方針に一致）。
          if (depBtcu < 0n) {
            throw new Error(`[reward] block ${blockNum}: negative depositor reward (player=${member.uid}, deposit=${dep.depositId}, dst=${depositorShareTotal}, totalDepWei=${totalDepWei}) — aborting`);
          }

          depositorResults.push({
            groupId: group.groupId,
            playerUid: member.uid,
            depositorUid: dep.idFrom,
            depositId: dep.depositId,
            depositerAddress: dep.depositerAddress || null,
            depositAmount: dep.amount,
            btcuReward: depBtcu.toString(),
            isPlayerSelf: dep.idFrom === member.uid
          });
        }

      }
    }

    console.log(`COINU split: ${depositorResults.length} lock-owner entries (${depositorResults.filter(d => d.isPlayerSelf).length} self, ${depositorResults.filter(d => !d.isPlayerSelf).length} external)`);

    // 報酬確定値をスコア記録へ書き戻し（以後のステージはこの永続値だけで再開できる）
    const nowIso = new Date().toISOString();
    for (const group of allGroupResults) {
      const rec = await this.storage.get(this.calcKey(blockNum, 'score', group.groupId));
      // K-S2-004: 完全性は冒頭の calcAssertGroupsComplete で確認済み（欠落はここへ到達しない）
      if (!rec) throw new Error(`[calc] rewards: score record vanished for group ${group.groupId} during drive`);
      rec.members = group.members; // btcuReward/fullReward/playerShare/depositorShare が上の按分で確定済み
      await this.storage.put(this.calcKey(blockNum, 'score', group.groupId), rec);
      const groupDeps = depositorResults.filter(d => d.groupId === group.groupId);
      await this.storage.put(this.calcKey(blockNum, 'deps', group.groupId), groupDeps);
    }
    progress.totalPoints = totalPoints;
    progress.blockRewardWei = blockRewardWei.toString();
    progress.nowIso = nowIso;
    progress.groupCount = allGroupResults.length;
    progress.stage = 'writing'; progress.cursor = 0;
    return progress;
  }

  // スコア/デポジット記録からグループ結果を復元（writing以降の共通ローダ）
  async calcLoadResultsFromRecords(blockNum, groups) {
    const allGroupResults = [];
    const depositorResults = [];
    for (const g of groups) {
      const rec = await this.storage.get(this.calcKey(blockNum, 'score', g.group_id));
      // K-S2-004: 欠落・失敗を無言でスキップしない（部分結果の公開・部分Merkleを構造的に防ぐ）
      if (!rec || rec.failed) {
        throw new Error(`[calc] score record for block ${blockNum} group ${g.group_id} is ${rec ? `failed (${rec.reason || 'unknown'})` : 'missing'} — refusing to build partial results`);
      }
      this.calcAssertGroupMembers(blockNum, g, rec.members, 'load-results');
      allGroupResults.push({ groupId: g.group_id, members: rec.members });
      const deps = await this.storage.get(this.calcKey(blockNum, 'deps', g.group_id));
      if (Array.isArray(deps)) depositorResults.push(...deps);
    }
    return { allGroupResults, depositorResults };
  }

  // ステージ7: writing — D1書き込み（UPSERT・claimed温存）＋グループ別R2アーカイブへの
  // gameResults追記（旧7・8・12と同一の行内容。created_at/completed_atはrewards確定時の
  // nowIsoで全グループ統一＝旧モノリスの単一タイムスタンプと同等）。
  async calcWritingUnit(blockNum, progress) {
    const db = this.env.BITCOINU_DATA;
    const groups = await this.calcLoadGroups(blockNum);
    const start = progress.cursor || 0;
    const slice = groups.slice(start, start + CALC_GROUPS_PER_UNIT);
    const now = progress.nowIso;
    const statements = [];
    const sliceResults = [];
    const sliceDeps = [];

    for (const g of slice) {
      const rec = await this.storage.get(this.calcKey(blockNum, 'score', g.group_id));
      // K-S2-004: rewards の関門を通っている以上ここでの欠落は状態破損。無言スキップしない
      if (!rec || rec.failed) {
        throw new Error(`[calc] writing: score record for block ${blockNum} group ${g.group_id} is ${rec ? `failed (${rec.reason || 'unknown'})` : 'missing'} — refusing to write a partial block`);
      }
      this.calcAssertGroupMembers(blockNum, g, rec.members, 'writing');
      const group = { groupId: g.group_id, members: rec.members };
      const groupDepositors = await this.storage.get(this.calcKey(blockNum, 'deps', g.group_id)) || [];
      sliceResults.push(group);
      sliceDeps.push(...groupDepositors);

      // プレイヤー行（ユーザー毎に1行、デポジッター分の報酬は含まない）
      for (const member of group.members) {
        // INSERT OR REPLACE ではなく UPSERT。再集計時に、外部のlisten/claim-workerが
        // 書き込む claimed 列を消さない（INSERT OR REPLACEは行ごと差し替えるためclaimedが消えていた）。
        statements.push(
          db.prepare(
            `INSERT INTO game_results (block_num, group_id, userId, role, deposit_id, address, btcu_reward, created_at) VALUES (?, ?, ?, 'player', '', ?, ?, ?)
             ON CONFLICT(block_num, group_id, userId, role, deposit_id) DO UPDATE SET
               address = excluded.address, btcu_reward = excluded.btcu_reward, created_at = excluded.created_at`
          ).bind(
            blockNum, group.groupId, member.uid, member.addr || null,
            member.btcuReward, now
          )
        );
      }

      // デポジッター行（自己デポジット含む全デポジット、各deposit毎に1行）
      for (const depResult of groupDepositors) {
        // UPSERT（claimed保全・上記playerと同理由）
        statements.push(
          db.prepare(
            `INSERT INTO game_results (block_num, group_id, userId, role, deposit_id, address, btcu_reward, deposit_to, created_at) VALUES (?, ?, ?, 'depositor', ?, ?, ?, ?, ?)
             ON CONFLICT(block_num, group_id, userId, role, deposit_id) DO UPDATE SET
               address = excluded.address, btcu_reward = excluded.btcu_reward, deposit_to = excluded.deposit_to, created_at = excluded.created_at`
          ).bind(
            blockNum, depResult.groupId, depResult.depositorUid,
            depResult.depositId, depResult.depositerAddress,
            depResult.btcuReward, depResult.playerUid, now
          )
        );
      }

      // game_groups.result にJSON要約をUPDATE（旧8と同一形状）
      const resultSummary = JSON.stringify({
        totalGroupPoints: group.members.reduce((s, m) => s + m.totalPoints, 0),
        disqualifiedCount: group.members.filter(m => m.isDisqualified).length,
        memberResults: group.members.map(m => ({
          uid: m.uid,
          depositPoints: m.depositPoints,
          bonusPoints: m.bonusPoints,
          totalPoints: m.totalPoints,
          isDisqualified: m.isDisqualified,
          disqualifyReason: m.disqualifyReasons?.length ? m.disqualifyReasons.join(',') : m.disqualifyReason,
          btcuReward: m.btcuReward,
          reportGainPoints: m.reportGainPoints,
          voteTargetUid: m.voteTargetUid,
          reportTargetUids: m.reportTargetUids,
          votedByUids: m.votedByUids
        })),
        depositorResults: groupDepositors.map(d => ({
          depositorUid: d.depositorUid,
          playerUid: d.playerUid,
          depositId: d.depositId,
          depositAmount: d.depositAmount,
          btcuReward: d.btcuReward,
          isPlayerSelf: d.isPlayerSelf
        }))
      });

      statements.push(
        db.prepare(
          `UPDATE game_groups SET result = ?, completed_at = ? WHERE block_num = ? AND group_id = ?`
        ).bind(resultSummary, now, blockNum, group.groupId)
      );
    }

    // D1バッチ書き込み（RESULT_BATCH_SIZE件ずつ）
    for (let i = 0; i < statements.length; i += RESULT_BATCH_SIZE) {
      await db.batch(statements.slice(i, i + RESULT_BATCH_SIZE));
    }

    // 旧12: グループ別R2アーカイブへgameResults追記（このユニットのグループ分のみ・冪等）
    try {
      await this.appendGameResultsToR2Groups(blockNum, sliceResults, sliceDeps, groups);
      delete progress.groupArchiveFailures;
    } catch (err) {
      // R11-F1: cursor はこの slice の先頭に据え置き、構造化失敗を monitor 面へ残す。
      progress.groupArchiveFailures = Array.isArray(err?.failures)
        ? err.failures
        : [{ groupId: null, key: null, reason: String(err?.message || err) }];
      throw err;
    }

    progress.cursor = start + slice.length;
    if (progress.cursor >= groups.length) { progress.stage = 'shards'; progress.cursor = 0; }
    return progress;
  }

    // ステージ8: shards — write-worker群への結果ファンアウト（旧10と同一・書き込み側dedupで冪等）
  async calcShardsUnit(blockNum, progress) {
    const groups = await this.calcLoadGroups(blockNum);
    const { allGroupResults, depositorResults } = await this.calcLoadResultsFromRecords(blockNum, groups);
    // C1/R4是正: 失敗はcatchせずthrow（ユニットリトライ→park=可視）。旧実装はcatchで握り潰し、
    // win_blocksのゲーム結果が無音欠落していた（自己修復なし）。書き込みは
    // calc:{N}:shards_cursor で続きから再開されるため、リトライで完走できる。
    const writeResult = await this.writeGameResultsToShards(blockNum, allGroupResults, depositorResults);
    console.log(`Shard game results: ${writeResult.totalWritten} written (${writeResult.totalChunks} chunks)`);
    console.log(`Results saved: ${allGroupResults.length} groups, totalPoints=${progress.totalPoints}`);
    progress.stage = 'summary'; progress.cursor = 0;
    return progress;
  }

  // ステージ9: summary — フル結果アーカイブ・summary.json・evidenceレポートのR2公開（旧9・11＋レポート）
  async calcSummaryUnit(blockNum, progress) {
    const groups = await this.calcLoadGroups(blockNum);
    let adoptedRec = progress.evidence ? await this.calcLoadAdopted(blockNum, { requireMarker: true }) : null;

    if (progress.summaryPhase === 'evidence_report') {
      if (!(await this.calcPublishEvidenceReportUnit(blockNum, progress, groups))) return progress;
      progress.stage = 'merkle'; progress.cursor = 0;
      delete progress.summaryPhase;
      delete progress.evidenceReport;
      return progress;
    }

    // Round 14 T2: グループ別overlayを全件1ユニットで公開すると、R2操作数が
    // ブロックのグループ数に比例して上限なく伸びる。既存のstage/cursor語彙に合わせ、
    // create-only公開をCALC_CLAIM_OVERLAYS_PER_UNIT件ずつ進める。失敗時はカーソルを
    // 進めないので、再実行は同じ範囲から冪等に再開できる。
    if ((progress.summaryPhase || 'claim_overlays') === 'claim_overlays') {
      const start = Number(progress.cursor || 0);
      const groupUnit = groups.slice(start, start + CALC_CLAIM_OVERLAYS_PER_UNIT);
      const { allGroupResults, depositorResults } = await this.calcLoadResultsFromRecords(blockNum, groupUnit);
      const published = await this.publishInitialClaimOverlays(
        blockNum, allGroupResults, depositorResults,
        { cursor: 0, limit: CALC_CLAIM_OVERLAYS_PER_UNIT },
      );
      progress.cursor = start + published.processed;
      if (progress.cursor < groups.length) return progress;
      progress.summaryPhase = 'artifacts';
      progress.cursor = 0;
      return progress;
    }

    const { allGroupResults, depositorResults } = await this.calcLoadResultsFromRecords(blockNum, groups);
    const totalPoints = progress.totalPoints;
    const blockRewardWei = BigInt(progress.blockRewardWei);
    const now = progress.nowIso;

    const witnessFiles = [];
    for (const g of groups) {
      const rec = await this.storage.get(this.calcKey(blockNum, 'score', g.group_id));
      const witness = rec?.groupWitness;
      if (!witness || witness.key !== `zkp/block${blockNum}/group-${g.group_id}.json`
          || !/^[0-9a-f]{64}$/.test(String(witness.sha256 || ''))
          || !Number.isSafeInteger(witness.bytes) || witness.bytes <= 0) {
        throw new Error(`[zkProof] group witness metadata missing for block ${blockNum} group ${g.group_id}`);
      }
      witnessFiles.push({ groupId: Number(g.group_id), ...witness });
    }
    await this.putR2ObjectOrThrow(`zkp/block${blockNum}/manifest.json`, {
      schemaVersion: 1,
      blockNum,
      groupCount: witnessFiles.length,
      files: witnessFiles,
    });

    // R15-F1: ブロック全体のフル表示結果を1オブジェクトへ再集約しない。
    // 詳細は writing 段でグループ別 `games/blockN/groupG.json` へ確定済み。
    // ここは再開・発見用の小さな index だけを公開する。
    const archiveData = {
      schemaVersion: 2,
      blockNum,
      blockReward: blockRewardWei.toString(),
      totalPoints,
      groupCount: allGroupResults.length,
      groupKeys: allGroupResults
        .map(g => ({ groupId: g.groupId, key: `games/block${blockNum}/group${g.groupId}.json` }))
        .sort((a, b) => a.groupId - b.groupId),
      depositorCount: depositorResults.length
    };
    await this.putR2ObjectOrThrow(`entries/block${blockNum}/game_results.json`, archiveData);

    // 旧11: R2のsummary.jsonを結果データで更新（フロントエンド公開データ兼 Merkleツリーの入力）。
    // レビューH1: 旧モノリスはビルド失敗を握ってもメモリ上のsummaryをmerkleへ渡していたが、
    // 本パイプラインはR2経由で次ステージへ渡すため、ここでの失敗は握らず throw する
    // （握るとグループ分け時点の結果なしsummaryからmerkleが構築され、実報酬ブロックに
    //   空ツリー標識ルートを誤提出する）。throwはユニット再試行→park→手動復旧に乗る。
    const blockSummary = await this.buildBlockSummaryWithResults(blockNum, allGroupResults, groups, blockRewardWei.toString(), depositorResults);
    // グループ別overlayは上のcursorフェーズで全件公開済み。
    await this.publishInitialClaimStatus(blockNum, this.buildInitialClaimStatus(allGroupResults, depositorResults));
    await this.publishBlockSummaryPreservingClaims(blockNum, blockSummary);
    console.log(`Block summary cache updated in R2 for block ${blockNum}`);

    // Evidence レポート公開（旧reconcileEvidence末尾と同一形状。採用uidのserverStateは
    // scoring時に確定したadoptionから合成。配列添字uidは数の昇順で先、残りはseq順
    // （FIX1の確定記録の順）。
    if (!progress.evidence) adoptedRec = await this.calcLoadAdopted(blockNum);
    if (adoptedRec && !adoptedRec.reportPublished && progress.evidence && !progress.evidence.disabled) {
      // 無効の大量提出は R2 multipart へ複数ユニットで載せる。
      // 小規模は従来の publishEvidenceReportIdempotent をそのまま使う。
      if (adoptedRec.invalidCount > 10000) {
        progress.summaryPhase = 'evidence_report';
        progress.cursor = 0;
        return progress;
      }
      // 🔴 P-2026-0823（2026-08-07）: **`Object.create(null)`**。素の `{}` だと
      //   ・`adoptionByUid[a.uid]` の filter が uid=`toString` などで Object.prototype の
      //     メソッド（truthy）を拾い、**採点時に採用されなかった提出をレポートへ載せた上に**
      //     `.serverState` が undefined になる（evidence-report.json は block-verifier が照合する）
      //   ・uid=`__proto__` の代入は own property にならず、逆に**本当に採用された提出が
      //     レポートから消える**（filter も落ちる）
      const adoptionByUid = Object.create(null);
      for (const g of groups) {
        const rec = await this.storage.get(this.calcKey(blockNum, 'score', g.group_id));
        for (const [uid, a] of Object.entries(rec?.adoption || {})) adoptionByUid[uid] = a;
      }
      const meta = adoptedRec.meta;
      const report = {
        contractAddress: meta.contractAddress,
        blockNum,
        resultCount: meta.resultCount,
        window: meta.window,
        chatWindow: meta.chatWindow,
        safeBlock: meta.safeBlock,
        confirmations: meta.confirmations,
        adopted: adoptedRec.adopted
          .filter(a => adoptionByUid[a.uid])
          .map(a => ({ uid: a.uid, groupId: a.groupId, seq: a.seq, txHash: a.txHash, serverState: adoptionByUid[a.uid].serverState })),
        invalid: (await this.calcLoadAdopted(blockNum, { withInvalid: true, requireMarker: !!progress.evidence })).invalid,
      };
      if (!progress.rosterSubmission.accepted) report.rosterSubmission = progress.rosterSubmission;
      // 🔴 ラウンド19 判断不要-3 step2 の棚卸し: 同上（manifest の artifactKeys）
      await this.publishEvidenceReportIdempotent(blockNum, report);
    }

    progress.stage = 'merkle'; progress.cursor = 0;
    delete progress.summaryPhase;
    return progress;
  }

  // T4b: 一ユニット一 part。非最終 part は R2 の制約どおり同じ 6 MiB。
  // 進捗には JSON 要素内のバイト位置だけを持ち、6 MiB の持ち越しは保存しない。
  async calcPublishEvidenceReportUnit(blockNum, progress, groups) {
    const rec = await this.calcLoadAdopted(blockNum, { requireMarker: !!progress.evidence });
    if (!rec || rec.reportPublished || progress.evidence?.disabled) return true;
    const key = `verification/block${blockNum}/evidence-report.json`;
    const adoptionByUid = Object.create(null);
    for (const g of groups) {
      const score = await this.storage.get(this.calcKey(blockNum, 'score', g.group_id));
      for (const [uid, a] of Object.entries(score?.adoption || {})) adoptionByUid[uid] = a;
    }
    let state = progress.evidenceReport;
    if (!state) {
      try {
        const existing = await this.env.R2_BUCKET.get(key, { range: { offset: 0, length: 4096 } });
        if (existing && Number.isSafeInteger(existing.size)) {
          const head = await existing.text();
          const oldSafeBlock = /"safeBlock":"([^"]+)"/.exec(head)?.[1];
          if (oldSafeBlock != null) {
            state = { mode: 'compare', safeBlock: oldSafeBlock, existingSize: existing.size,
              existingOffset: 0, partNumber: 1, chunk: 0, offset: 0,
              byteOffset: 0, suffixOffset: 0, hasInvalid: false };
          }
        }
      } catch (error) {
        console.warn(`[evidence] idempotent re-publish disabled for ${key} (read failed): ${error?.message || error}`);
      }
      if (!state) {
        const upload = await this.env.R2_BUCKET.createMultipartUpload(key, {
          httpMetadata: { contentType: 'application/json' },
        });
        state = { mode: 'upload', uploadId: upload.uploadId, partNumber: 1,
          chunk: 0, offset: 0, byteOffset: 0, suffixOffset: 0, hasInvalid: false };
      }
      progress.evidenceReport = state;
    }
    const meta = state.mode === 'compare' ? { ...rec.meta, safeBlock: state.safeBlock } : rec.meta;
    const report = {
      contractAddress: meta.contractAddress, blockNum, resultCount: meta.resultCount,
      window: meta.window, chatWindow: meta.chatWindow, safeBlock: meta.safeBlock,
      confirmations: meta.confirmations,
      adopted: rec.adopted.filter(a => adoptionByUid[a.uid]).map(a => ({
        uid: a.uid, groupId: a.groupId, seq: a.seq, txHash: a.txHash,
        serverState: adoptionByUid[a.uid].serverState,
      })),
      invalid: [],
    };
    if (!progress.rosterSubmission.accepted) report.rosterSubmission = progress.rosterSubmission;
    const template = JSON.stringify(report);
    const marker = '"invalid":[]';
    const markerAt = template.indexOf(marker);
    if (markerAt < 0) throw new Error('[evidence] report template missing invalid array');
    const splitAt = markerAt + marker.length - 1;
    const prefix = template.slice(0, splitAt);
    const suffix = template.slice(splitAt);
    if (state.partNumber > 10000) throw new Error('[evidence] R2 multipart part limit exceeded');
    const encoder = new TextEncoder();
    const prefixBytes = encoder.encode(prefix);
    const suffixBytes = encoder.encode(suffix);
    if (prefixBytes.length > CALC_EVIDENCE_REPORT_PART_BYTES) throw new Error('[evidence] report prefix exceeds part size');
    const part = new Uint8Array(CALC_EVIDENCE_REPORT_PART_BYTES);
    let bytes = 0;
    if (state.partNumber === 1) {
      part.set(prefixBytes);
      bytes = prefixBytes.length;
    }
    let { chunk, offset, hasInvalid } = state;
    let byteOffset = state.byteOffset || 0;
    let suffixOffset = state.suffixOffset || 0;
    while (chunk < rec.invalidChunks && bytes < part.length) {
      const values = await this.storage.get(this.calcKey(blockNum, 'invalid_chunk', String(chunk)));
      if (!Array.isArray(values) || values.length === 0 || offset >= values.length) {
        throw new Error(`[evidence] report invalid chunk ${chunk} missing`);
      }
      while (offset < values.length && bytes < part.length) {
        const piece = encoder.encode(`${hasInvalid ? ',' : ''}${JSON.stringify(values[offset])}`);
        if (byteOffset >= piece.length) throw new Error('[evidence] report byte cursor outside item');
        const take = Math.min(piece.length - byteOffset, part.length - bytes);
        part.set(piece.subarray(byteOffset, byteOffset + take), bytes);
        bytes += take;
        byteOffset += take;
        if (byteOffset === piece.length) {
          byteOffset = 0;
          hasInvalid = true;
          offset++;
        }
      }
      if (offset === values.length) { chunk++; offset = 0; }
    }
    if (chunk === rec.invalidChunks && bytes < part.length) {
      const take = Math.min(suffixBytes.length - suffixOffset, part.length - bytes);
      part.set(suffixBytes.subarray(suffixOffset, suffixOffset + take), bytes);
      bytes += take;
      suffixOffset += take;
    }
    const last = chunk === rec.invalidChunks && suffixOffset === suffixBytes.length;
    if (!last && bytes !== part.length) throw new Error('[evidence] short non-final report part');
    const partBytes = part.subarray(0, bytes);
    if (state.mode === 'compare') {
      let same = false;
      try {
        const existingPart = await this.env.R2_BUCKET.get(key, {
          range: { offset: state.existingOffset, length: bytes },
        });
        if (existingPart) {
          const oldBytes = new Uint8Array(await existingPart.arrayBuffer());
          same = oldBytes.length === bytes && oldBytes.every((value, i) => value === partBytes[i]);
        }
      } catch (error) {
        console.warn(`[evidence] idempotent compare failed for ${key}: ${error?.message || error}`);
      }
      const nextOffset = state.existingOffset + bytes;
      if (same && (!last || nextOffset === state.existingSize)) {
        if (last) return true;
        progress.evidenceReport = { ...state, partNumber: state.partNumber + 1,
          chunk, offset, byteOffset, suffixOffset, hasInvalid, existingOffset: nextOffset };
        progress.cursor = chunk;
        return false;
      }
      const fresh = await this.env.R2_BUCKET.createMultipartUpload(key, {
        httpMetadata: { contentType: 'application/json' },
      });
      progress.evidenceReport = { mode: 'upload', uploadId: fresh.uploadId, partNumber: 1,
        chunk: 0, offset: 0, byteOffset: 0, suffixOffset: 0, hasInvalid: false };
      progress.cursor = 0;
      return false;
    }
    const upload = this.env.R2_BUCKET.resumeMultipartUpload(key, state.uploadId);
    const retryPublished = async () => {
      const existing = await this.env.R2_BUCKET.get(key, { range: { offset: 0, length: 4096 } }).catch(() => null);
      if (!existing) return false;
      const oldSafeBlock = /"safeBlock":"([^"]+)"/.exec(await existing.text())?.[1];
      if (oldSafeBlock == null) return false;
      progress.evidenceReport = { mode: 'compare', safeBlock: oldSafeBlock, existingSize: existing.size,
        existingOffset: 0, partNumber: 1, chunk: 0, offset: 0,
        byteOffset: 0, suffixOffset: 0, hasInvalid: false };
      progress.cursor = 0;
      return true;
    };
    let uploaded;
    try {
      uploaded = await upload.uploadPart(state.partNumber, partBytes);
    } catch (error) {
      // complete 済みで応答・進捗保存だけが失われた場合は公開物を範囲比較する。
      if (await retryPublished()) return false;
      throw error;
    }
    await this.storage.put(this.calcKey(blockNum, 'report_part', String(state.partNumber)), uploaded);
    if (!last) {
      progress.evidenceReport = { mode: 'upload', uploadId: state.uploadId, partNumber: state.partNumber + 1,
        chunk, offset, byteOffset, suffixOffset, hasInvalid };
      progress.cursor = chunk;
      return false;
    }
    const parts = [];
    for (let i = 1; i <= state.partNumber; i++) {
      const part = await this.storage.get(this.calcKey(blockNum, 'report_part', String(i)));
      if (!part) throw new Error(`[evidence] report part ${i} missing`);
      parts.push(part);
    }
    try {
      await upload.complete(parts);
    } catch (error) {
      // complete がサーバーでは成功し、応答だけ失われた場合もあり得る。
      // 公開済みなら次ユニットで範囲ごとに照合し、同じバイト列だけを採る。
      console.warn(`[evidence] report multipart complete response uncertain for ${key}: ${error?.message || error}`);
      if (await retryPublished()) return false;
      throw error;
    }
    return true;
  }

  // ステージ10: merkle — 公開summaryからツリー生成→R2公開（オンチェーン提出はしない）。
  // 提出は proofs と zkProof 完了後の最終 adminCommit 段階に回す ── これにより proof 欠落のまま
  // 検証/請求期間へ突入するのを構造的に防ぐ。失敗は内部でstatus記録され再試行可能。
  /// summary.json が「**結果確定版**」であることを要求する（fail-closed）。
  ///
  /// 🔴 P-2026-0839（2026-08-08・ラウンド19 判断不要-7）: この検査は
  ///    `calcMerkleUnit`（自動パイプライン）にしか無く、**同じ木構築を行う手動経路**
  ///    （`POST /submit-merkle-root` の「経路2: summary から再構築」）には1つも無かった。
  ///    通していたのは `parseCanonicalJson` と `publishMerkleTree` の
  ///    `Array.isArray(summary.groups)` だけ。
  ///
  ///    実測（実 DO を起動し `POST /submit-merkle-root {block_num:0, force:true}`）:
  ///      HTTP 200 / source="rebuilt_from_summary" / **leafCount=0**
  ///      publishClaimData(0, 0, 1, 0x424344330000)   ← blob 6 バイト
  ///      submitMerkleRoot(0, 0x9fad44fd…647f12)      ← 空ツリーの標識ルートそのもの
  ///      同じ summary を `calcMerkleUnit` へ渡すと「is not a finalized results summary」で THREW
  ///    グループ分け直後の summary は `btcu_reward: null` かつ `full_btcu_reward` 未設定なので
  ///    `claim-data-codec.js` の `fullRewardOfMember` が 0 を返し、葉が1枚も作られない。
  ///    `submitMerkleRootOnChain` の fail-closed は「両方とも標識ルート」で素通りし、
  ///    契約側も `root != 0` / `isBlockTimeUnlocked` / `cd.chunks > 0` を全部満たすので
  ///    **何も止めない** ＝ ブロック報酬 115,384.615 BTCu が誰にも配られないまま確定する。
  ///
  ///    到達は運用ミス経路（集計は13段中7段が summary ステージより手前で park しうる。
  ///    `docs/archive/CODEX_HANDOFF.md:701` に block 0 を手動復旧した実績が残っている）。
  ///
  /// ⚠️ 過剰遮断ゼロ: ここで新たに拒否される状態は、自動パイプラインが既に throw で
  ///    拒否している状態と**同一**。ゲーム無し（`groups: []` → `.every()` が true）と
  ///    自動配布（`status: 'auto_distributed'`）は正当なので必ず通る。
  ///
  /// @param where エラー文の接頭辞（`[merkle]` / `[submit-merkle-root]`）
  async assertFinalizedSummary(blockNum, blockSummary, where = '[merkle]') {
    // レビューH1（多層防御）: summaryが「結果確定版」であることを検証してから木を構築する。
    // グループ分け時点のsummary（status!=completed）から構築すると、実報酬があるのに
    // 空ツリー標識ルートを（後段adminCommitで）提出してしまう。
    if (!blockSummary || !Array.isArray(blockSummary.groups) ||
        !blockSummary.groups.every(g => g.status === 'completed' || g.status === 'auto_distributed')) {
      throw new Error(`${where} summary.json for block ${blockNum} is not a finalized results summary — retry summary stage (restart if persistent)`);
    }
    // R20-F2: no-game / auto-distribute は表示・claim 用の疑似 group を持ち得るが、
    // manifest が列挙する通常ゲームの group artifact 集合は常に空。
    if (blockSummary.noGame === true || blockSummary.autoDistributed === true) return true;
    // K-S2-004: 旧ガードは「summary に載っているグループ」の status しか見ておらず、
    // 除外されたグループは検査対象にすら入らなかった（＝欠落したまま素通り）。
    // Merkle ルートの提出は不可逆なので、最後の関門として D1 の期待集合との一致を要求する。
    const d1Groups = await this.calcLoadGroups(blockNum);
    const expected = new Set(d1Groups.map(g => String(g.group_id)));
    const actual = new Set(blockSummary.groups.map(g => String(g.group_id)));
    const missing = [...expected].filter(id => !actual.has(id));
    const extra = [...actual].filter(id => !expected.has(id));
    if (missing.length > 0 || extra.length > 0 || actual.size !== blockSummary.groups.length) {
      throw new Error(
        `${where} summary.json for block ${blockNum} does not cover all D1 groups — ` +
        `expected ${expected.size}, got ${blockSummary.groups.length} ` +
        `(missing: ${missing.join(',') || '-'} / unexpected: ${extra.join(',') || '-'}) — refusing to build a partial tree`
      );
    }
    for (const g of d1Groups) {
      const sg = blockSummary.groups.find(s => String(s.group_id) === String(g.group_id));
      const expectedUids = this.calcD1GroupUids(g);
      const actualUids = new Set((Array.isArray(sg.members) ? sg.members : []).map(m => String(m.userId)));
      const missingUids = [...expectedUids].filter(u => !actualUids.has(u));
      const extraUids = [...actualUids].filter(u => !expectedUids.has(u));
      if (missingUids.length > 0 || extraUids.length > 0) {
        throw new Error(
          `${where} summary.json group ${g.group_id} roster mismatch for block ${blockNum} — ` +
          `(missing: ${missingUids.join(',') || '-'} / unexpected: ${extraUids.join(',') || '-'}) — refusing to build a partial tree`
        );
      }
    }
    return true;
  }

  // R20-F2: manifest / anchor / root 復旧が共有する唯一の group-id 導出。
  // 引数や D1 だけを信じず、結果確定 summary と D1 の完全一致を先に検査する。
  async canonicalGroupIdsFromFinalizedSummary(blockNum, blockSummary = null, where = '[manifest]') {
    const summary = blockSummary || await this.getR2Object(`games/block${blockNum}/summary.json`);
    await this.assertFinalizedSummary(blockNum, summary, where);
    if (summary.noGame === true || summary.autoDistributed === true) return [];
    return summary.groups.map(g => Number(g.group_id)).sort((a, b) => a - b);
  }

  canonicalResultPageKeys(blockNum, summary, where = '[manifest]') {
    if (!summary?.autoDistributed) return [];
    // 旧 inline summary は後方互換で読むが、新schemaは必ず専用ページをmanifest固定する。
    if (Number(summary.schemaVersion || 1) < 2) return [];
    const expected = `games/block${blockNum}/auto-results.json`;
    const groups = Array.isArray(summary.groups) ? summary.groups : [];
    if (summary.resultLayout !== 'auto-distribution-page-v1'
      || groups.length !== 1 || groups[0]?.detailKey !== expected) {
      throw new Error(`${where} auto result page declaration is invalid for block ${blockNum}`);
    }
    return [expected];
  }

  async calcMerkleUnit(blockNum, progress) {
    let blockSummary = await this.getR2Object(`games/block${blockNum}/summary.json`);
    await this.assertFinalizedSummary(blockNum, blockSummary, '[merkle]');
    // G1b（メモリ）: 実上限23,100葉でのピークを抑える。publishMerkleTree は葉抽出後に
    // 引数参照を捨てるので、呼び出し側も
    // await前にローカル参照を手放してGC可能にする。
    const merklePromise = this.publishMerkleTree(blockNum, blockSummary, {
      expectedTotalPoints: progress.totalPoints,
    });
    blockSummary = null;
    const merkle = await merklePromise;
    progress.merkle = merkle;
    // 🔴 C-1 / ラウンド19 判断不要-3 レッグ (c)（2026-08-08）:
    //    `publishMerkleTree` は例外を握って `{ok:false, error}` を返す。旧実装は
    //    `ok` を一度も見ずに次段（manifest）へ進んでいたため、
    //    `files["merkle/block_{N}.json"] = null` の manifest を**先にオンチェーンへ
    //    焼いてから** adminCommit で throw していた（`resultRegistrationCount` が汚れ
    //    nonce とガスも消費する）。ここで止めれば manifest は1バイトも公開されない。
    //    throw → ユニットリトライ → 20回で park（R2 put は冪等なので再実行は安全）。
    if (!merkle?.ok) {
      throw new Error(
        `[merkle] block ${blockNum}: publishMerkleTree failed (${merkle?.reason || merkle?.error || 'unknown'}) `
        + `— refusing to anchor a manifest that points at a missing tree`
      );
    }
    // 確定（manifest/anchor）を proofs より前に完了させる。オンチェーン提出は最後。
    progress.stage = 'manifest'; progress.cursor = 0; progress.manifestFiles = {};
    return progress;
  }

  // ステージ10.5: proofs（G1・2026-07-18）— 請求キー毎のproofファイル事前生成を
  // claim-worker /build-proofs へレンジ発注する。重い仕事（葉・レベルページを読んで
  // proofを計算しファイル出力）はclaim-worker側で、Workersの自動スケールにより
  // 発注した並列数だけ同時実行される。masterはカーソルと完全性検証のみ担う。
  // 失敗はthrow→ユニットリトライ（発注は冪等上書き）。
  async calcProofsUnit(blockNum, progress) {
    const status = await this.storage.get(`merkle_status_${blockNum}`);
    const leafCount = status?.leafCount ?? 0;
    if (!leafCount) {
      // 空ツリー（0配分）またはmerkle失敗記録（/submit-merkle-rootで再試行される）。
      // proofはフォールバック（claim-workerのその場生成）でも賄えるため前進する。
      progress.stage = 'zkProof'; progress.cursor = 0;
      delete progress.proofsWritten;
      return progress;
    }
    const totalRanges = Math.ceil(leafCount / PROOFS_RANGE);
    const start = progress.cursor || 0;
    const end = Math.min(start + PROOFS_RANGES_PER_UNIT, totalRanges);
    let written = progress.proofsWritten || 0;
    for (let i = start; i < end; i += PROOFS_DISPATCH_CONCURRENCY) {
      const batch = [];
      for (let r = i; r < Math.min(i + PROOFS_DISPATCH_CONCURRENCY, end); r++) {
        batch.push(this.dispatchBuildProofs(blockNum, r * PROOFS_RANGE, Math.min((r + 1) * PROOFS_RANGE, leafCount)));
      }
      const results = await Promise.all(batch);
      for (const res of results) written += res.written;
    }
    progress.proofsWritten = written;
    progress.cursor = end;
    if (end < totalRanges) return progress; // 発注継続（次ユニット）
    // 完全性検証: 書き込み合計 == 葉数（不一致＝どこかのレンジが欠けた→リトライで再発注）
    if (written !== leafCount) {
      progress.cursor = 0; progress.proofsWritten = 0;
      throw new Error(`[proofs] block ${blockNum}: written ${written} != leafCount ${leafCount} — re-dispatching all ranges`);
    }
    console.log(`[proofs] block ${blockNum}: ${written} proof file(s) published via claim-worker`);
    delete progress.proofsWritten;
    progress.stage = 'zkProof'; progress.cursor = 0;
    return progress;
  }

  async readZkpProofConfig({ allowUnsupportedRequired = false } = {}) {
    const contractAddr = this.env.TOKEN_MINING_CONTRACT_ADDRESS;
    const publicClient = this.createReadOnlyClient();
    if (!contractAddr || !publicClient) {
      // ローカル単体テスト／未配備shadowの後方互換。ここでfalseへ倒しても、同じ設定を使う
      // submitMerkleRootOnChainがmissing_configを返すので実txは送れない。契約+RPCが揃う本番では
      // 必ずproofRequiredを読み、trueを証明なしで通す経路にはならない。
      console.warn(`[zkProof] proofRequired read skipped: TOKEN_MINING_CONTRACT_ADDRESS or ${RPC_LIST_ENV} is unavailable`);
      return {
        required: false, address: null, publicClient: null, vkey: null, verifier: null,
        supported: false, configUnavailable: true,
      };
    }
    const address = getAddress(contractAddr);
    // proofRequired と実効世代を同じEthereum blockで読む。false→trueやvkey切替の境界で
    // 異なるsnapshotを組み合わせて証明なし提出へ進まないための固定点。
    const snapshotBlock = await publicClient.getBlockNumber();
    const [required, effective] = await Promise.all([
      publicClient.readContract({
        address, abi: TOKEN_MINING_ABI, functionName: 'proofRequired', blockNumber: snapshotBlock,
      }),
      publicClient.readContract({
        address, abi: TOKEN_MINING_ABI, functionName: 'effectiveVerifierAndVkey', blockNumber: snapshotBlock,
      }),
    ]);
    const verifier = Array.isArray(effective) ? effective[0] : effective.v;
    const vkey = (Array.isArray(effective) ? effective[1] : effective.k)?.toLowerCase();
    const supported = /^0x[0-9a-f]{64}$/.test(ZKP_WIRE_EXPECTED.vkey || '')
      && /^0x[0-9a-f]{64}$/.test(ZKP_WIRE_EXPECTED.elfSha256 || '')
      && vkey === ZKP_WIRE_EXPECTED.vkey
      && String(verifier).toLowerCase() === ZKP_EXPECTED.verifier;
    if (required && !supported && !allowUnsupportedRequired) {
      const error = new Error(
        `[zkProof] effective verifier/vkey ${verifier}/${vkey} is not supported by this deployed prover `
        + `(${ZKP_EXPECTED.verifier}/${ZKP_WIRE_EXPECTED.vkey})`
      );
      error.code = 'effective_prover_unsupported';
      throw error;
    }
    return { required: !!required, address, publicClient, vkey, verifier, supported, snapshotBlock };
  }

  async callZkpProver(method, pathname, payload = null, { returnNotFound = false } = {}) {
    // ZKP_PROVER_URL / ZKP_PROVER_HMAC_SECRET は Stage 5 まで使わない任意設定。
    // 宣言・配布なしは意図的で、未設定のまま呼ばれた場合は下で throw する設計。
    const base = this.env.ZKP_PROVER_URL;
    const secret = this.env.ZKP_PROVER_HMAC_SECRET;
    if (!base || !secret) {
      const missing = [!base && 'ZKP_PROVER_URL', !secret && 'ZKP_PROVER_HMAC_SECRET'].filter(Boolean);
      throw new Error(`[zkProof] prover control config missing: ${missing.join(', ')}`);
    }
    const url = new URL(pathname, base.endsWith('/') ? base : `${base}/`);
    if (url.protocol !== 'https:' && url.hostname !== 'localhost' && url.hostname !== '127.0.0.1') {
      throw new Error('[zkProof] ZKP_PROVER_URL must use HTTPS');
    }
    const body = payload === null ? '' : JSON.stringify(payload);
    const headers = await createZkpAuthHeaders({ secret, method, pathname: url.pathname, body });
    const response = await fetch(url.toString(), {
      method,
      headers: { ...headers, accept: 'application/json', ...(body ? { 'content-type': 'application/json' } : {}) },
      ...(body ? { body } : {}),
    });
    const text = await response.text();
    let value;
    try { value = text ? JSON.parse(text) : {}; }
    catch { throw new Error(`[zkProof] control API returned non-JSON HTTP ${response.status}: ${text.slice(0, 500)}`); }
    // post-commit の呼び手だけ、job 不在とルート不一致の 404 を終端値として受ける。
    // pre-commit は従来どおり例外を受け、control error と shadow の待ちに通す。
    if (returnNotFound && (method === 'GET' || method === 'DELETE') && response.status === 404
      && (value?.status === 'not_found' || value?.error === 'not_found')) {
      return { ...value, status: 'not_found' };
    }
    if (!response.ok && value?.status !== 'failed') {
      throw new Error(`[zkProof] control API HTTP ${response.status}: ${value?.detail || value?.reason || value?.error || text.slice(0, 500)}`);
    }
    return value;
  }

  async recordZkpProofIssue(blockNum, detail) {
    const value = { blockNum, ...detail, at: new Date().toISOString() };
    await this.storage.put(`zkp_proof_issue_block${blockNum}`, value);
    return value;
  }

  async clearZkpProofIssue(blockNum) {
    try { await this.storage.delete(`zkp_proof_issue_block${blockNum}`); } catch (_) {}
  }

  async diagnoseZkpAnchor(blockNum, expectedManifestHash = null) {
    const marker = await this.storage.get(`verification_anchor_failed_block${blockNum}`).catch(() => null);
    try {
      const chain = await this.readResultHashOnChain(blockNum);
      const expected = expectedManifestHash || marker?.manifestHash || null;
      return {
        expectedManifestHash: expected,
        actualManifestHash: chain.hash || null,
        updatedBlock: chain.updated,
        matches: !!expected && String(chain.hash).toLowerCase() === String(expected).toLowerCase(),
        failureMarker: marker ? {
          at: marker.at || null, reason: marker.registered?.reason || null,
        } : null,
      };
    } catch (error) {
      return {
        expectedManifestHash: expectedManifestHash || marker?.manifestHash || null,
        actualManifestHash: null, updatedBlock: null, matches: false,
        readError: error.shortMessage || error.message,
        failureMarker: marker ? {
          at: marker.at || null, reason: marker.registered?.reason || null,
        } : null,
      };
    }
  }

  async maybeAlertZkpDelay(blockNum, progress, response) {
    const requestedAt = progress.zkProof?.requestedAt || Date.now();
    const elapsedMs = Number(response?.elapsedMs ?? (Date.now() - requestedAt));
    const level = response?.warningLevel
      || (elapsedMs >= ZKP_HARD_FAILURE_MS ? 'hard_failure'
        : elapsedMs >= ZKP_ALERT_MS ? 'alert'
          : elapsedMs >= ZKP_WARNING_MS ? 'warning' : null);
    if (!level) return;
    await this.recordZkpProofIssue(blockNum, {
      kind: 'zkp_proof_delay', level, elapsedMs,
      jobId: progress.zkProof?.jobId ?? response?.jobId ?? null,
      phase: response?.phase ?? null,
      attempt: response?.attempt ?? null,
      recover: 'docs/OPS_TASKS.md G2 の切り分けと手動フォールバックを実行',
    });
    if (progress.zkProof?.alertedLevel === level) return;
    progress.zkProof.alertedLevel = level;
    try {
      await sendAlertAndRecord(this.env, this.storage, {
        kind: `zkp_${level}`,
        subject: `[COINU] ZKP ${level}: block ${blockNum}`,
        body: `block ${blockNum} / job ${progress.zkProof?.jobId || response?.jobId || 'pending'} / elapsed ${Math.round(elapsedMs / 60000)} min\nGET /calc-status?block=${blockNum}`,
      });
    } catch (error) {
      console.error(`[zkProof] delay alert failed block=${blockNum}: ${error.message}`);
    }
  }

  shadowZkpMaxWaitMs() {
    const configured = Number(this.env.ZKP_SHADOW_MAX_WAIT_MS);
    if (!Number.isFinite(configured) || configured < 60_000) return ZKP_SHADOW_MAX_WAIT_DEFAULT_MS;
    // GMの証明遅延の重大しきい値より長く待たない。誤設定でblockを永久parkさせない。
    return Math.min(configured, ZKP_HARD_FAILURE_MS);
  }

  postCommitZkpMaxWaitMs() {
    // ZKP_POST_COMMIT_MAX_MS は任意の調整つまみ。宣言・配布なしは意図的で、未設定・60,000 未満なら既定値。
    const configured = Number(this.env.ZKP_POST_COMMIT_MAX_MS);
    if (!Number.isFinite(configured) || configured < 60_000) return ZKP_POST_COMMIT_MAX_DEFAULT_MS;
    return configured;
  }

  postCommitZkpKey(blockNum) {
    return `post_commit_zkp_block${blockNum}`;
  }

  wireProverRequest(blockNum, anchors, vkey, successor = null) {
    const safe = (value, label) => {
      const result = Number(value);
      if (!Number.isSafeInteger(result) || result < 0) throw new Error(`[zkProof] invalid ${label}`);
      return result;
    };
    const sentAnchors = {
      resultManifestHash: anchors.resultManifestHash, evidenceAcc: anchors.evidenceAcc,
      evidenceGraceSec: safe(anchors.evidenceGraceSec, 'evidenceGraceSec'),
      rosterManifestHash: anchors.rosterManifestHash,
      prevResultManifestHash: anchors.prevResultManifestHash,
      prevRegistrationIndex: anchors.prevRegistrationIndex,
      anchorsReadBlock: safe(anchors.anchorsReadBlock, 'anchorsReadBlock'),
    };
    return { sentAnchors, body: {
      chainId: String(resolveEthChainId(this.env)), blockNum: safe(blockNum, 'blockNum'),
      graph: 'wire-v1', vkey, anchors: {
        resultManifestHash: sentAnchors.resultManifestHash, evidenceAcc: sentAnchors.evidenceAcc,
        evidenceGraceSec: sentAnchors.evidenceGraceSec, rosterManifestHash: sentAnchors.rosterManifestHash,
      }, anchorsReadBlock: sentAnchors.anchorsReadBlock,
      ...(blockNum > 0 ? { prevResultRegistration: { index: String(anchors.prevRegistrationIndex),
        registeredBlock: safe(anchors.previousResultUpdatedBlock, 'registeredBlock'),
        hash: anchors.prevResultManifestHash } } : {}), ...(successor || {}),
    } };
  }

  async requestZkpSuccessor(blockNum, adoptRequired, successorOf = null) {
    this._zkpSuccessorTasks ||= new Map();
    const signature = JSON.stringify([adoptRequired, successorOf]);
    const current = this._zkpSuccessorTasks.get(blockNum);
    if (current) {
      if (current.signature !== signature) throw Object.assign(new Error('[zkProof] successor request is in flight'), { status: 409 });
      return current.promise;
    }
    if (this._calcDriving) throw Object.assign(new Error('[zkProof] calc is driving; retry after the current unit'), { status: 409 });
    this._calcDriving = true;
    const task = this.requestZkpSuccessorUnlocked(blockNum, adoptRequired, successorOf);
    this._zkpSuccessorTasks.set(blockNum, { signature, promise: task });
    try { return await task; }
    finally { this._zkpSuccessorTasks.delete(blockNum); this._calcDriving = false; }
  }

  async requestZkpSuccessorUnlocked(blockNum, adoptRequired, successorOf) {
    const conflict = message => { throw Object.assign(new Error(`[zkProof] ${message}`), { status: 409 }); };
    const progress = await this.storage.get(this.calcProgressKey(blockNum));
    const post = await this.storage.get(this.postCommitZkpKey(blockNum));
    const ticketKey = `zkp_successor_block${blockNum}`;
    let ticket = await this.storage.get(ticketKey);
    const previousId = post?.jobId || progress?.zkProof?.jobId;
    if (!previousId) conflict('no predecessor job');
    // A network retry remains the same operation even if its successor has
    // already failed. Starting a further successor requires naming that job.
    if (ticket?.applied && (!successorOf || successorOf === ticket.previousId)) {
      if (ticket.body.adoptRequired !== adoptRequired) conflict('successor options differ');
      return { success: true, jobId: ticket.jobId, successorOf: ticket.previousId, repeated: true };
    }
    if (successorOf && successorOf !== previousId && successorOf !== ticket?.previousId)
      conflict('successor_of is not the current predecessor');
    const previous = await this.callZkpProver('GET', `/v1/jobs/${previousId}`);
    // A repeated request while the accepted successor runs is an idempotent read.
    if (ticket?.jobId === previousId && !['failed', 'cancelled'].includes(previous?.status)) {
      if (ticket.body.adoptRequired !== adoptRequired) conflict('successor options differ');
      if (!ticket.applied) {
        if (ticket.shadow) await this.enqueuePostCommitZkp(blockNum, 1000);
        else await this.enqueueCalcContinuation(blockNum, 1000);
        ticket.applied = true;
        await this.storage.put(ticketKey, ticket);
      }
      return { success: true, jobId: ticket.jobId, successorOf: ticket.previousId, repeated: true };
    }
    if (!['failed', 'cancelled'].includes(previous?.status) || this.isZkpCleanupPending(previous))
      conflict('predecessor is not terminal or cleanup is pending');
    const shadow = post?.status === 'proof_abandoned';
    if (!shadow && progress?.stage !== 'zkProof') conflict('block is not at zkProof or shadow fallback');
    const chain = await this.readZkpProofConfig();
    if (chain.configUnavailable || !chain.publicClient || !chain.address) conflict('chain config unavailable');
    const state = await chain.publicClient.readContract({ address: chain.address, abi: TOKEN_MINING_ABI,
      functionName: 'blockStates', args: [BigInt(blockNum)] });
    const root = Array.isArray(state) ? state[0] : state?.merkleRoot;
    const epoch = BigInt(Array.isArray(state) ? state[2] : state?.zkEpochPlusOne || 0);
    if (epoch > 0n) conflict('proof is already attached');
    if (shadow && String(root).toLowerCase() !== String(post.root).toLowerCase()) conflict('root replaced');
    if (!ticket || ticket.previousId !== previousId) {
      const anchors = await this.readWireAnchorsForRequest(blockNum, progress, chain);
      if (!anchors || anchors.fallback) conflict('anchors are not ready');
      await this.stage3DispatchForBlock(blockNum);
      const prepared = this.wireProverRequest(blockNum, anchors, chain.vkey, {
        adoptFrom: previousId, adoptRequired,
      });
      ticket = { previousId, body: prepared.body, sentAnchors: prepared.sentAnchors,
        requestedAt: Date.now(), shadow, root: shadow ? post.root : progress.merkle?.root };
      // Persist before POST: a lost response is retried with exactly the same ID material.
      await this.storage.put(ticketKey, ticket);
    } else if (ticket.body.adoptRequired !== adoptRequired) conflict('pending successor options differ');
    const response = await this.callZkpProver('POST', '/v1/jobs', ticket.body);
    if (!/^[0-9a-f]{64}$/.test(response?.jobId || '') || response.jobId === previousId)
      throw new Error('[zkProof] invalid successor jobId');
    ticket.jobId = response.jobId;
    await this.storage.put(ticketKey, ticket);
    if (ticket.shadow) {
      await this.persistPostCommitZkp(blockNum, {
        blockNum, status: 'root_fallback_keep_proving', root: ticket.root,
        jobId: ticket.jobId, successorOf: previousId, inputHash: response.inputHash || null,
        sentAnchors: ticket.sentAnchors, requestedAt: ticket.requestedAt,
        deadlineAt: ticket.requestedAt + this.postCommitZkpMaxWaitMs(), cleanupStatus: null,
      });
      await this.enqueuePostCommitZkp(blockNum, 1000);
    } else {
      this.clearWireJobState(progress);
      progress.zkProof = { ...progress.zkProof, jobId: ticket.jobId, successorOf: previousId,
        requestedAt: ticket.requestedAt, sentAnchors: ticket.sentAnchors, status: 'requesting', lastError: null };
      delete progress.zkProof.operatorFallbackRequestedAt;
      delete progress.zkProof.operatorFallbackMode;
      delete progress.zkProof.successorRequest;
      progress.parked = false; progress.failures = 0; progress.lastError = null;
      delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
      await this.storage.put(this.calcProgressKey(blockNum), progress);
      await this.enqueueCalcContinuation(blockNum, 1000);
    }
    ticket.applied = true;
    await this.storage.put(ticketKey, ticket);
    return { success: true, jobId: ticket.jobId, successorOf: previousId, status: response.status };
  }

  async publishPostCommitZkpArtifact(blockNum, state) {
    await this.putR2ObjectOrThrow(`verification/block${blockNum}/zkp-proof.json`, {
      schemaVersion: 2,
      blockNum,
      mode: 'best_effort_shadow',
      proofRequired: false,
      ...state,
    });
  }

  async finishShadowZkpFallback(blockNum, progress, {
    reason, detail = null, response = null, cancelledState = null,
  } = {}) {
    const fallbackAt = Date.now();
    const fallbackDetail = detail ? String(detail).slice(0, 2000) : null;
    const jobId = cancelledState?.jobId ?? progress.zkProof?.jobId ?? response?.jobId ?? null;
    const explicitlyAbandoned = progress.zkProof?.operatorFallbackMode === 'proof_abandoned';
    const terminal = String(reason || '').startsWith('terminal_')
      || ['unsupported_effective_prover', 'existing_no_proof_submission', 'onchain_config_unavailable',
        'effective_prover_changed_after_verification'].includes(String(reason || ''));
    const keepProving = !cancelledState && !!jobId && !explicitlyAbandoned && !terminal;
    const postCommit = {
      blockNum,
      status: keepProving ? 'root_fallback_keep_proving' : 'proof_abandoned',
      root: progress.merkle?.root ?? (await this.storage.get(`merkle_status_${blockNum}`))?.root ?? null,
      jobId,
      inputHash: progress.zkProof?.inputHash ?? response?.inputHash ?? null,
      requestedAt: progress.zkProof?.requestedAt ?? null,
      fallbackAt,
      fallbackReason: reason || 'unknown',
      fallbackDetail,
      deadlineAt: keepProving ? fallbackAt + this.postCommitZkpMaxWaitMs() : null,
      cleanupStatus: keepProving || !jobId ? null : 'zkp_cleanup_pending',
      updatedAt: fallbackAt,
    };
    // 完全放棄はroot提出を待たずに課金停止を始める。失敗してもroot確定は進め、
    // post_commit_zkp alarmがtombstone作成／Batch削除を再試行する。
    if (cancelledState) {
      postCommit.cleanupStatus = cancelledState.cleanupStatus || 'zkp_cleanup_pending';
      postCommit.cleanupFailures = cancelledState.cleanupFailures || null;
      postCommit.cleanupError = cancelledState.cleanupError || null;
    } else if (!keepProving && jobId) {
      try {
        const cancelled = await this.callZkpProver('DELETE', `/v1/jobs/${jobId}`, {
          reason: explicitlyAbandoned ? 'proof_abandoned' : String(reason || 'fallback_terminal'),
        });
        postCommit.cleanupStatus = this.isZkpCleanupPending(cancelled) ? 'zkp_cleanup_pending' : 'cancelled';
        postCommit.cleanupFailures = cancelled?.cleanupFailures || null;
      } catch (error) {
        postCommit.cleanupStatus = 'zkp_cleanup_pending';
        postCommit.cleanupError = error.message;
      }
    }
    await this.storage.put(this.postCommitZkpKey(blockNum), postCommit);
    progress.zkProof = {
      ...(progress.zkProof || {}),
      required: false,
      status: postCommit.status,
      fallbackReason: reason || 'unknown',
      fallbackDetail,
      fallbackAt,
      attempt: response?.attempt ?? progress.zkProof?.attempt ?? null,
      attemptHistory: Array.isArray(response?.attemptHistory)
        ? response.attemptHistory : (progress.zkProof?.attemptHistory || []),
      failure: response?.failure ?? progress.zkProof?.failure ?? null,
      contradiction: response?.contradiction ?? progress.zkProof?.contradiction ?? null,
      lastError: fallbackDetail,
    };
    const artifact = {
      schemaVersion: 1,
      blockNum,
      mode: 'best_effort_shadow',
      proofRequired: false,
      status: postCommit.status,
      jobId,
      inputHash: progress.zkProof.inputHash ?? response?.inputHash ?? null,
      requestedAt: progress.zkProof.requestedAt ?? null,
      attempt: progress.zkProof.attempt,
      attemptHistory: progress.zkProof.attemptHistory,
      failure: progress.zkProof.failure,
      contradiction: progress.zkProof.contradiction,
      fallbackReason: progress.zkProof.fallbackReason,
      fallbackDetail,
      fallbackAt,
      deadlineAt: postCommit.deadlineAt,
      cleanupStatus: postCommit.cleanupStatus,
    };
    await this.putR2ObjectOrThrow(`verification/block${blockNum}/zkp-proof.json`, artifact);
    await this.recordZkpProofIssue(blockNum, {
      kind: 'zkp_no_proof_fallback', level: 'warning',
      jobId: artifact.jobId, inputHash: artifact.inputHash,
      reason: artifact.fallbackReason, detail: fallbackDetail, attempt: artifact.attempt,
      recover: keepProving
        ? 'proofRequired=falseのためrootを先行確定し、進行中のproofを追跡'
        : (postCommit.cleanupStatus === 'zkp_cleanup_pending'
          ? 'root確定は維持し、post_commit_zkp alarmでjob cancelを再試行'
          : 'proof生成は完全放棄済み。次ブロックは通常どおり再試行'),
    });
    delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
    progress.stage = 'adminCommit'; progress.cursor = 0;
    return progress;
  }

  async enqueuePostCommitZkp(blockNum, delayMs = ZKP_POLL_DEFAULT_MS) {
    await this.enqueuePhaseTask({ type: 'post_commit_zkp', blockNum, executeAt: Date.now() + delayMs });
  }

  // R21-F4: controllerの正準cancel応答は status=pending + phase=cleanup。
  // cleanupPendingは移行中の二重防御としても読むが、それだけに依存しない。
  isZkpCleanupPending(result) {
    return result?.cleanupPending === true
      || (result?.status === 'pending' && result?.phase === 'cleanup');
  }

  async persistPostCommitZkp(blockNum, state, { publish = true } = {}) {
    const next = { ...state, updatedAt: Date.now() };
    await this.storage.put(this.postCommitZkpKey(blockNum), next);
    if (publish) await this.publishPostCommitZkpArtifact(blockNum, next);
    return next;
  }

  async retryPostCommitDeadlineFailure(blockNum, state, error) {
    const consecutiveDeadlineFailures = Number(state.consecutiveDeadlineFailures || 0) + 1;
    const next = { ...state, status: 'post_commit_proving', lastError: error,
      consecutiveDeadlineFailures };
    if (consecutiveDeadlineFailures >= 3) {
      return this.cancelPostCommitZkp(blockNum, next, 'post_commit_deadline_exceeded');
    }
    const saved = await this.persistPostCommitZkp(blockNum, next);
    await this.enqueuePostCommitZkp(blockNum);
    return { done: false, state: saved };
  }

  async cancelPostCommitZkp(blockNum, state, reason) {
    const jobAlreadyGone = reason === 'controller_job_not_found';
    let next = {
      ...state,
      status: 'proof_abandoned',
      abandonedAt: state.abandonedAt || Date.now(),
      abandonReason: reason,
      cleanupStatus: state.jobId && !jobAlreadyGone ? 'zkp_cleanup_pending' : 'not_needed',
    };
    // cancel fence を controller 呼出しより先に永続化する。呼出し中に isolate が落ちても
    // post_commit_zkp task が同じ DELETE を再送し、root の結論とは独立に cleanup を追える。
    next = await this.persistPostCommitZkp(blockNum, next, { publish: false });
    if (state.jobId && !jobAlreadyGone) await this.enqueuePostCommitZkp(blockNum);
    if (state.jobId && !jobAlreadyGone) {
      try {
        const result = await this.callZkpProver('DELETE', `/v1/jobs/${state.jobId}`, { reason }, { returnNotFound: true });
        next.cleanupStatus = this.isZkpCleanupPending(result) ? 'zkp_cleanup_pending' : 'cancelled';
        next.cleanupFailures = result?.cleanupFailures || null;
        delete next.cleanupError;
      } catch (error) {
        next.cleanupStatus = 'zkp_cleanup_pending';
        next.cleanupError = error.message;
      }
    }
    next = await this.persistPostCommitZkp(blockNum, next);
    const excluded = ['timeline_no_game_proof_excluded', 'root_replaced',
      'missing_post_commit_job_or_root'].includes(reason);
    const previousIssue = await this.storage.get(`zkp_proof_issue_block${blockNum}`).catch(() => null);
    const canUpdateIssue = ['zkp_no_proof_fallback', 'zkp_cleanup_pending'].includes(previousIssue?.kind)
      || (previousIssue?.kind === 'zkp_proof_delay' && previousIssue.jobId === state.jobId);
    if (excluded) {
      await this.clearZkpProofIssue(blockNum);
    } else if (next.cleanupStatus === 'zkp_cleanup_pending') {
      await this.recordZkpProofIssue(blockNum, {
        kind: 'zkp_cleanup_pending', level: 'warning', jobId: next.jobId,
        reason, error: next.cleanupError || null, cleanupFailures: next.cleanupFailures || null,
        recover: 'post_commit_zkp alarmがHMAC DELETEを再試行。rootとclaim clockは確定済みのまま維持',
      });
    } else if (canUpdateIssue) {
      await this.recordZkpProofIssue(blockNum, {
        kind: 'zkp_no_proof_fallback', level: 'warning', jobId: next.jobId,
        reason, recover: 'rootは確定済み。proof jobは取り消し済みでattachは行わない',
      });
    } else if (previousIssue) {
      await this.clearZkpProofIssue(blockNum);
    }
    return next;
  }

  // root先行後のproofを、通常calcとは独立してpollし、
  // 同一rootへattachする。ここではsubmitMerkleRootForBlockを呼ばないため
  // claim-timing.jsonとverificationStartedAtを更新しない。
  async drivePostCommitZkp(blockNum) {
    let state = await this.storage.get(this.postCommitZkpKey(blockNum));
    if (!state) return { done: true, reason: 'not_found' };

    if (state.status === 'proof_abandoned' || state.cleanupStatus === 'zkp_cleanup_pending') {
      if (state.cleanupStatus !== 'zkp_cleanup_pending') return { done: true, state };
      state = await this.cancelPostCommitZkp(blockNum, state, state.abandonReason || 'proof_abandoned');
      return { done: state.cleanupStatus !== 'zkp_cleanup_pending', state };
    }
    if (state.status === 'proof_attached') return { done: true, state };
    if (!state.jobId || !state.root) {
      return this.cancelPostCommitZkp(blockNum, state, 'missing_post_commit_job_or_root');
    }
    const deadlineExceeded = Date.now() >= Number(state.deadlineAt || 0);

    let chainConfig;
    try {
      chainConfig = await this.readZkpProofConfig();
    } catch (error) {
      if (error.code === 'effective_prover_unsupported') {
        return this.cancelPostCommitZkp(blockNum, { ...state, lastError: error.message }, error.code);
      }
      if (deadlineExceeded) return this.retryPostCommitDeadlineFailure(blockNum, state, error.message);
      state = await this.persistPostCommitZkp(blockNum, {
        ...state, status: 'post_commit_proving', lastError: error.message,
      });
      await this.enqueuePostCommitZkp(blockNum);
      return { done: false, state };
    }
    if (chainConfig.configUnavailable || !chainConfig.publicClient || !chainConfig.address) {
      if (deadlineExceeded) return this.retryPostCommitDeadlineFailure(blockNum, state, 'onchain_config_unavailable');
      state = await this.persistPostCommitZkp(blockNum, {
        ...state, status: 'post_commit_proving', lastError: 'onchain_config_unavailable',
      });
      await this.enqueuePostCommitZkp(blockNum);
      return { done: false, state };
    }

    const chainState = await chainConfig.publicClient.readContract({
      address: chainConfig.address, abi: TOKEN_MINING_ABI,
      functionName: 'blockStates', args: [BigInt(blockNum)],
    });
    const currentRoot = Array.isArray(chainState) ? chainState[0] : chainState?.merkleRoot;
    const epochPlusOne = BigInt(Array.isArray(chainState) ? chainState[2] : (chainState?.zkEpochPlusOne || 0));
    const attachedAt = BigInt(Array.isArray(chainState) ? chainState[3] : (chainState?.proofAttachedAt || 0));
    if (String(currentRoot).toLowerCase() !== String(state.root).toLowerCase()) {
      return this.cancelPostCommitZkp(blockNum, state, 'root_replaced');
    }
    if (epochPlusOne > 0n || attachedAt > 0n) {
      state = await this.persistPostCommitZkp(blockNum, {
        ...state, status: 'proof_attached', proofAttachedAt: Number(attachedAt),
        attachedEpochIndex: epochPlusOne > 0n ? Number(epochPlusOne - 1n) : null,
        detectedExistingAttachment: true,
      });
      await this.clearZkpProofIssue(blockNum);
      return { done: true, state };
    }

    let response;
    try {
      response = await this.callZkpProver('GET', `/v1/jobs/${state.jobId}`, null, { returnNotFound: true });
    } catch (error) {
      if (deadlineExceeded) return this.retryPostCommitDeadlineFailure(blockNum, state, error.message);
      state = await this.persistPostCommitZkp(blockNum, {
        ...state, status: 'post_commit_proving', lastError: error.message,
      });
      await this.enqueuePostCommitZkp(blockNum);
      return { done: false, state };
    }
    if (response?.status === 'not_found') {
      return this.cancelPostCommitZkp(blockNum, state, 'controller_job_not_found');
    }
    if (response?.status === 'pending') {
      if (deadlineExceeded) {
        await this.recordZkpProofIssue(blockNum, {
          kind: 'zkp_proof_delay', level: 'warning', jobId: state.jobId,
          phase: response.phase || null, elapsedMs: Date.now() - Number(state.requestedAt || 0),
          recover: '進行中のjobを監視し、必要なら明示的にabandon',
        });
        if (!state.deadlineAlertedAt) {
          try {
            await sendAlertAndRecord(this.env, this.storage, {
              kind: 'zkp_warning',
              subject: `[COINU] ZKP post-commit warning: block ${blockNum}`,
              body: `block ${blockNum} / job ${state.jobId} / deadline exceeded\nGET /calc-status?block=${blockNum}`,
            });
          } catch (error) {
            console.error(`[zkProof] post-commit delay alert failed block=${blockNum}: ${error.message}`);
          }
        }
      }
      const delay = Math.max(10_000, Math.min(Number(response.pollAfterMs) || ZKP_POLL_DEFAULT_MS, 10 * 60 * 1000));
      state = await this.persistPostCommitZkp(blockNum, {
        ...state, status: 'post_commit_proving', phase: response.phase || null,
        attempt: response.attempt || null, lastPollAt: Date.now(), lastError: null,
        consecutiveDeadlineFailures: 0,
        ...(deadlineExceeded ? { deadlineAlertedAt: state.deadlineAlertedAt || Date.now() } : {}),
      });
      await this.enqueuePostCommitZkp(blockNum, delay);
      return { done: false, state };
    }
    if (response?.status === 'failed') {
      return this.cancelPostCommitZkp(blockNum, {
        ...state, attempt: response.attempt || null,
        lastError: response.detail || response.reason || 'prover_failed',
      }, `terminal_${response.reason || 'prover_failure'}`);
    }
    if (response?.status === 'cancelled') {
      return this.cancelPostCommitZkp(blockNum, state, 'controller_cancelled');
    }
    if (response?.status !== 'verified' || !response.proof) {
      if (deadlineExceeded) return this.retryPostCommitDeadlineFailure(blockNum, state,
        `[zkProof] unexpected post-commit response: ${JSON.stringify(response)}`);
      throw new Error(`[zkProof] unexpected post-commit response: ${JSON.stringify(response)}`);
    }

    let proof;
    try {
      proof = validateZkpProof(response.proof, { blockNum, root: state.root, vkey: chainConfig.vkey,
        elfSha256: ZKP_WIRE_EXPECTED.elfSha256 });
      if (String(proof.verifierAddress).toLowerCase() !== String(chainConfig.verifier).toLowerCase()) {
        throw new Error(`verifier mismatch: proof=${proof.verifierAddress} chain=${chainConfig.verifier}`);
      }
    } catch (error) {
      return this.cancelPostCommitZkp(blockNum, { ...state, lastError: error.message }, 'stale_or_invalid_proof_generation');
    }

    let submit;
    try {
      submit = await this.submitMerkleRootOnChain(blockNum, state.root, { zkProof: proof });
    } catch (error) {
      if (deadlineExceeded) return this.retryPostCommitDeadlineFailure(blockNum, state, error.message);
      throw error;
    }
    if (submit?.reason === 'gas_price_wait') {
      state = await this.persistPostCommitZkp(blockNum, {
        ...state, status: 'proof_attach_gas_wait', lastError: null,
        currentGwei: submit.currentGwei, limitGwei: submit.limitGwei,
      });
      await this.enqueuePostCommitZkp(blockNum, GameMasterDO.TIMELINE_RETRY_MS);
      return { done: false, state };
    }
    if (submit?.reason === 'classification_unavailable' || submit?.reason === 'preflight_unavailable') {
      if (deadlineExceeded) return this.retryPostCommitDeadlineFailure(blockNum, state, submit.reason);
      state = await this.persistPostCommitZkp(blockNum, {
        ...state,
        status: 'proof_attach_receipt_pending',
        lastError: null,
        waitReason: submit.reason,
        pendingTxHash: submit.txHash || null,
      });
      await this.enqueuePostCommitZkp(blockNum, ADMIN_TX_PENDING_RETRY_MS);
      return { done: false, state };
    }
    if (!submit?.submitted) {
      if (deadlineExceeded) return this.retryPostCommitDeadlineFailure(blockNum, state,
        `[zkProof] proof attach not confirmed: ${JSON.stringify(submit)}`);
      throw new Error(`[zkProof] proof attach not confirmed: ${JSON.stringify(submit)}`);
    }

    const after = await chainConfig.publicClient.readContract({
      address: chainConfig.address, abi: TOKEN_MINING_ABI,
      functionName: 'blockStates', args: [BigInt(blockNum)],
    });
    const afterEpoch = BigInt(Array.isArray(after) ? after[2] : (after?.zkEpochPlusOne || 0));
    const afterAttachedAt = BigInt(Array.isArray(after) ? after[3] : (after?.proofAttachedAt || 0));
    if (afterEpoch === 0n || afterAttachedAt === 0n) {
      throw new Error('[zkProof] attach tx confirmed but blockStates has no proof epoch/timestamp');
    }
    state = await this.persistPostCommitZkp(blockNum, {
      ...state, status: 'proof_attached', proofAttachedAt: Number(afterAttachedAt),
      attachedEpochIndex: Number(afterEpoch - 1n), attachedTxHash: submit.txHash || null,
      attachedAt: Date.now(), lastError: null, consecutiveDeadlineFailures: 0,
    });
    await this.clearZkpProofIssue(blockNum);
    return { done: true, state };
  }

  async waitAfterShadowControlError(blockNum, progress, error, anchorDiagnosis = null) {
    progress.zkProof.status = 'control_error';
    progress.zkProof.lastError = error.message;
    progress.zkProof.lastPollAt = Date.now();
    const delay = ZKP_POLL_DEFAULT_MS;
    progress.waitUntil = Date.now() + delay;
    progress.waitReason = 'zk_proof_control_retry';
    progress.waitDetail = {
      jobId: progress.zkProof.jobId || null, error: error.message,
      ...(anchorDiagnosis ? { anchorDiagnosis } : {}),
    };
    await this.enqueueCalcContinuation(blockNum, delay);
    return progress;
  }

  // G2: claim proof と adminCommit の間で、短い発注/pollだけを行う。
  // pending は失敗回数に数えず alarm キューへ戻し、1 drive で待ち続けない。
  async calcZkProofUnit(blockNum, progress) {
    await this.assertCalcGroupingActive(blockNum, progress);
    // この呼出しでcontrollerの正常pendingを再観測できなければ、古い免除札は使わない。
    if (progress.zkProof) {
      delete progress.zkProof.normalWait;
      delete progress.zkProof.evidenceWindowWait;
    }
    let root = progress.merkle?.root;
    if (!root) root = (await this.storage.get(`merkle_status_${blockNum}`))?.root || null;
    if (!root) throw new Error(`[zkProof] no merkle root available for block ${blockNum}`);

    const timelineNoGame = await this.readFinalizedTimelineNoGame(blockNum);
    const chainConfig = await this.readZkpProofConfig({ allowUnsupportedRequired: !!timelineNoGame });
    if (timelineNoGame) return this.finishTimelineNoGameProofRoute(blockNum, progress, chainConfig, timelineNoGame);
    if (chainConfig.configUnavailable) {
      progress.zkProof = {
        ...(progress.zkProof || {}), required: false, status: 'fallback_no_proof',
        fallbackReason: 'onchain_config_unavailable', fallbackAt: Date.now(),
      };
      progress.stage = 'adminCommit'; progress.cursor = 0;
      return progress;
    }

    // 運営がZ2手動フォールバックで同じrootを証明付き提出済みなら、失敗したGCP jobを
    // 永久にpollしない。adminCommitへ渡し、既存rootのpreflightでtxなしに最終化する。
    if (chainConfig.publicClient && chainConfig.address) {
      try {
        const state = await chainConfig.publicClient.readContract({
          address: chainConfig.address, abi: TOKEN_MINING_ABI,
          functionName: 'blockStates', args: [BigInt(blockNum)],
        });
        const existingRoot = Array.isArray(state) ? state[0] : state?.merkleRoot;
        const existingEpochPlusOne = Array.isArray(state) ? state[2] : state?.zkEpochPlusOne;
        if (existingRoot && String(existingRoot).toLowerCase() === String(root).toLowerCase()) {
          if (BigInt(existingEpochPlusOne || 0) > 0n) {
            progress.zkProof = {
              ...(progress.zkProof || {}), required: !!chainConfig.required, status: 'submitted_manually',
              detectedAt: Date.now(), vkey: chainConfig.vkey,
            };
            await this.clearZkpProofIssue(blockNum);
            delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
            progress.stage = 'adminCommit'; progress.cursor = 0;
            return progress;
          }
          if (!chainConfig.required) {
            return this.finishShadowZkpFallback(blockNum, progress, {
              reason: 'existing_no_proof_submission',
              detail: 'same root is already on-chain with zkEpochPlusOne=0',
            });
          }
          // false時に先行した証明なしrootへ、検証期間中ならproofを付け直す。
          // adminCommitのpreflightはzkEpochPlusOne=0の同一rootだけ再提出を許可する。
        }
      } catch (error) {
        console.warn(`[zkProof] blockStates preflight read failed block=${blockNum}: ${error.shortMessage || error.message}`);
      }
    }

    if (!chainConfig.supported) {
      if (!chainConfig.required) {
        return this.finishShadowZkpFallback(blockNum, progress, {
          reason: 'unsupported_effective_prover',
          detail: `effective verifier/vkey ${chainConfig.verifier}/${chainConfig.vkey}`,
        });
      }
      throw new Error('[zkProof] proof is required but effective verifier/vkey is unsupported');
    }

    // ゲーム無し／2名以下の自動配布は通常の calcEvidenceUnit を通らず、Evidence の
    // 提出窓が開いたままここへ到達しうる。窓内に作った proof は evidenceAcc/currentGrace が
    // その後変わって stale になるため、安全ブロックでも窓が閉じるまで発注時計を開始しない。
    if (Number(progress.groupCount ?? progress.result?.groupCount ?? -1) === 0
        && !progress.zkProof?.jobId) {
      let finality;
      try { finality = await this.readEvidenceWindowFinality(blockNum, { waitDetails: true }); }
      catch (error) {
        if (error?.code === 'rpc_quorum_unavailable') await this.noteRpcQuorumFailure(blockNum, error);
        throw error;
      }
      if (!finality.ready) {
        // safe blockの提出窓終端が近ければ30分丸ごと待たない。
        // 再観測を早めるだけで、発注は次回も同じ64確認のready判定を通す。
        const gapMs = (Number(finality.closeAt) - Number(finality.safeTimestamp)) * 1000;
        const delay = Number.isFinite(gapMs) && gapMs > 0
          ? Math.min(GameMasterDO.TIMELINE_RETRY_MS, Math.max(ADMIN_TX_PENDING_RETRY_MS, gapMs))
          : GameMasterDO.TIMELINE_RETRY_MS;
        progress.zkProof = {
          ...(progress.zkProof || {}),
          required: !!chainConfig.required,
          status: 'waiting_evidence_window_finality',
          vkey: chainConfig.vkey,
          verifier: chainConfig.verifier,
        };
        delete progress.zkProof.requestedAt;
        const evidenceWait = this.rememberEvidenceWindowWait(blockNum, progress, finality, delay);
        if (evidenceWait) progress.zkProof.evidenceWindowWait = evidenceWait;
        progress.waitUntil = Date.now() + delay;
        progress.waitReason = 'evidence_window_not_final';
        progress.waitDetail = {
          stage: 'zkProof',
          safeBlockNumber: finality.safeBlockNumber,
          safeTimestamp: finality.safeTimestamp,
          closeAt: finality.closeAt,
          confirmations: finality.confirmations,
          ...(evidenceWait || {}),
        };
        await this.enqueueCalcContinuation(blockNum, delay);
        return progress;
      }
      delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
    }

    const previousZkProof = progress.zkProof || {};
    progress.zkProof = {
      ...previousZkProof,
      required: !!chainConfig.required,
      status: previousZkProof.status
        && previousZkProof.status !== 'skipped_shadow'
        && previousZkProof.status !== 'fallback_no_proof'
        ? previousZkProof.status : 'preparing_claim_data',
      requestedAt: previousZkProof.requestedAt || Date.now(),
      vkey: chainConfig.vkey,
      verifier: chainConfig.verifier,
    };

    if (!chainConfig.required && progress.zkProof.operatorFallbackRequestedAt) {
      return this.finishShadowZkpFallback(blockNum, progress, {
        reason: 'operator_bypass', detail: progress.zkProof.operatorFallbackReason || 'operator_requested',
      });
    }
    const shadowElapsedMs = Date.now() - progress.zkProof.requestedAt;
    if (!chainConfig.required && shadowElapsedMs >= this.shadowZkpMaxWaitMs()) {
      return this.finishShadowZkpFallback(blockNum, progress, {
        reason: 'shadow_wait_timeout', detail: `elapsedMs=${shadowElapsedMs}`,
      });
    }

    const namedPrevious = await this.readPrevResultRegistrationOnChain(blockNum);
    if (blockNum > 0 && namedPrevious.prevRegistrationCount === '0') {
      const delay = GameMasterDO.TIMELINE_RETRY_MS;
      progress.zkProof.status = 'waiting_previous_result_registration';
      progress.waitUntil = Date.now() + delay;
      progress.waitReason = 'previous_result_registration_missing';
      progress.waitDetail = { stage: 'zkProof', previousBlock: blockNum - 1 };
      await this.enqueueCalcContinuation(blockNum, delay);
      return progress;
    }

    if (!progress.zkProof.claimDataPrepared) {
      await this.assertCalcGroupingActive(blockNum, progress);
      const prepared = await this.submitMerkleRootOnChain(blockNum, root, {
        force: !!progress.forceSubmit, prepareOnly: true,
      });
      if (prepared?.reason === 'gas_price_wait') {
        // 管理tx待ちから非管理系の費用待ちへ移ったので、連続保留期間と凍結印を切る。
        await this.clearVerificationAdminTxWait(blockNum);
        progress.waitUntil = Date.now() + GameMasterDO.TIMELINE_RETRY_MS;
        progress.waitReason = 'gas_price_wait';
        progress.waitDetail = { stage: 'zkProof', currentGwei: prepared.currentGwei, limitGwei: prepared.limitGwei };
        await this.enqueueCalcContinuation(blockNum, GameMasterDO.TIMELINE_RETRY_MS);
        return progress;
      }
      const adminWait = adminTxWaitOf(prepared);
      if (adminWait) {
        await this.recordVerificationAdminTxWait(blockNum, prepared, adminWait, 'claim_data');
        progress.zkProof.status = 'preparing_claim_data';
        progress.zkProof.lastError = null;
        progress.waitUntil = Date.now() + adminWait.retryInMs;
        progress.waitReason = adminWait.waitReason;
        progress.waitDetail = { ...adminWait.detail, stage: 'claim_data' };
        await this.enqueueCalcContinuation(blockNum, adminWait.retryInMs);
        if (await this.calcAdminTxWaitConsumesFailure(blockNum, progress, adminWait)) {
          const error = new Error('[zkProof] waiting for admin_tx_pending at claim_data');
          error.adminTxPending = true;
          throw error;
        }
        return progress;
      }
      // 受領・分類・決定的失敗・成功のどれでも、管理tx専用の待ちはここで解消済み。
      await this.clearVerificationAdminTxWait(blockNum);
      if (prepared?.reason === 'claim_data_receipt_pending') {
        const delay = Number(prepared.retryInMs) || ADMIN_TX_PENDING_RETRY_MS;
        progress.zkProof.status = 'preparing_claim_data';
        progress.zkProof.lastError = null;
        progress.waitUntil = Date.now() + delay;
        progress.waitReason = 'claim_data_receipt_pending';
        progress.waitDetail = {
          stage: 'zkProof',
          txHash: prepared.claimData?.txHash || null,
          chunkIndex: prepared.claimData?.chunkIndex ?? null,
          pendingReason: prepared.claimData?.reason || 'receipt_timeout',
        };
        await this.enqueueCalcContinuation(blockNum, delay);
        return progress;
      }
      if (prepared?.reason === 'classification_unavailable' || prepared?.reason === 'preflight_unavailable') {
        const delay = Number(prepared.retryInMs) || ADMIN_TX_PENDING_RETRY_MS;
        progress.zkProof.status = 'preparing_claim_data';
        progress.zkProof.lastError = null;
        progress.waitUntil = Date.now() + delay;
        progress.waitReason = prepared.reason;
        progress.waitDetail = { stage: 'zkProof', txHash: prepared.txHash || null };
        await this.enqueueCalcContinuation(blockNum, delay);
        return progress;
      }
      if (!prepared?.prepared) {
        throw new Error(`[zkProof] claim data preparation failed: ${JSON.stringify(prepared)}`);
      }
      progress.zkProof.claimDataPrepared = true;
      progress.zkProof.claimDataHash = prepared.claimData?.dataHash || null;
      progress.zkProof.status = 'requesting';
      delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
    }

    let requestAnchors = null;
    if (!progress.zkProof.jobId) {
      requestAnchors = await this.readWireAnchorsForRequest(blockNum, progress, chainConfig);
      if (!requestAnchors) return progress;
      if (requestAnchors.fallback) return requestAnchors.fallback;
    }
    let response;
    try {
      if (!progress.zkProof.jobId) {
        await this.stage3DispatchForBlock(blockNum);
        const prepared = this.wireProverRequest(blockNum, requestAnchors, chainConfig.vkey,
          progress.zkProof.successorRequest || null);
        progress.zkProof.sentAnchors = prepared.sentAnchors;
        response = await this.callZkpProver('POST', '/v1/jobs', prepared.body);
      } else {
        response = await this.callZkpProver('GET', `/v1/jobs/${progress.zkProof.jobId}`);
      }
    } catch (error) {
      const stage3Missing = !!error?.stage3ArtifactsMissing || /stage\s*3|stage3/i.test(error?.message || '');
      const anchorDiagnosis = await this.diagnoseZkpAnchor(
        blockNum, progress.verification?.manifestHash || null,
      );
      await this.recordZkpProofIssue(blockNum, {
        kind: stage3Missing ? 'stage3_artifact_missing' : 'zkp_control_error',
        jobId: progress.zkProof.jobId || null,
        error: error.message, anchorDiagnosis,
        recover: chainConfig.required
          ? (stage3Missing
              ? `verification/block${blockNum}/stage3/manifest.json と group witness を再生成して再試行`
              : 'Cloud Run/GCP Batch/GCS を復旧して自動再試行。または Z2 手動導線')
          : '上限までは自動再試行し、期限超過時は証明なしrootへ自動fallback',
      });
      if (!chainConfig.required) {
        const elapsedMs = Date.now() - progress.zkProof.requestedAt;
        if (elapsedMs >= this.shadowZkpMaxWaitMs()) {
          return this.finishShadowZkpFallback(blockNum, progress, {
            reason: 'shadow_wait_timeout', detail: error.message,
          });
        }
        return this.waitAfterShadowControlError(blockNum, progress, error, anchorDiagnosis);
      }
      throw error;
    }

    if (response?.monitor) progress.zkProof.monitor = response.monitor;
    if (response?.severity) progress.zkProof.severity = response.severity;
    if (response?.jobId) {
      if (progress.zkProof.jobId && progress.zkProof.jobId !== response.jobId) {
        throw new Error(`[zkProof] control API changed jobId ${progress.zkProof.jobId} -> ${response.jobId}`);
      }
      progress.zkProof.jobId = response.jobId;
      delete progress.zkProof.successorRequest;
    }
    if (response?.inputHash) {
      if (progress.zkProof.inputHash && progress.zkProof.inputHash !== response.inputHash) {
        const error = new Error(`[zkProof] inputHash changed: ${progress.zkProof.inputHash} -> ${response.inputHash}`);
        await this.recordZkpProofIssue(blockNum, {
          kind: 'zkp_input_changed', level: 'hard_failure', jobId: progress.zkProof.jobId || null,
          error: error.message, recover: 'Cloud Run の request/input GCS object を照合。fallbackせず原因を確定',
        });
        throw error;
      }
      progress.zkProof.inputHash = response.inputHash;
    }

    if (response?.status === 'pending') {
      const elapsedMs = Number(response.elapsedMs ?? (Date.now() - progress.zkProof.requestedAt));
      if (!chainConfig.required && elapsedMs >= this.shadowZkpMaxWaitMs()) {
        return this.finishShadowZkpFallback(blockNum, progress, {
          reason: 'shadow_wait_timeout', detail: `elapsedMs=${elapsedMs}`, response,
        });
      }
      progress.zkProof.status = response.phase || 'pending';
      progress.zkProof.lastError = null;
      progress.zkProof.lastPollAt = Date.now();
      progress.zkProof.attempt = response.attempt || null;
      progress.zkProof.attemptHistory = Array.isArray(response.attemptHistory)
        ? response.attemptHistory : (progress.zkProof.attemptHistory || []);
      progress.zkProof.failure = response.failure || null;
      progress.zkProof.contradiction = response.contradiction || null;
      if (response.alert || response.monitor?.longRunningAlert) {
        await this.recordZkpProofIssue(blockNum, {
          kind: 'zkp_proof_delay', level: 'warning', jobId: progress.zkProof.jobId,
          alert: response.alert || response.monitor.longRunningAlert,
        });
      }
      await this.maybeAlertZkpDelay(blockNum, progress, response);
      const delay = Math.max(10_000, Math.min(Number(response.pollAfterMs) || ZKP_POLL_DEFAULT_MS, 10 * 60 * 1000));
      progress.waitUntil = Date.now() + delay;
      progress.waitReason = response.phase === 'wire_collect_waiting'
        ? (response.waitReason || 'zk_proof_pending') : 'zk_proof_pending';
      progress.waitDetail = {
        jobId: progress.zkProof.jobId, phase: response.phase || null,
        pollAfterMs: response.pollAfterMs ?? null, alert: response.alert ?? null,
        attempt: response.attempt || null, failure: response.failure || null,
        contradiction: response.contradiction || null,
      };
      // AUTOZK: 免除は「zkProof段にいる」だけでは与えない。成功したcontroller応答だけが
      // 次回pollまで有効な札を作る。12h/14hの通知は上で維持し、15h以後は失敗予算へ戻す。
      const now = Date.now();
      const deadlineAt = Math.min(progress.zkProof.normalWaitDeadlineAt ?? Infinity,
        progress.zkProof.requestedAt + ZKP_HARD_FAILURE_MS,
        now + ZKP_HARD_FAILURE_MS - elapsedMs);
      const pendingShapeValid = typeof response.jobId === 'string' && response.jobId.length > 0
          && (response.phase == null || typeof response.phase === 'string')
          && (response.inputHash == null || (typeof response.inputHash === 'string' && /^0x[0-9a-fA-F]{64}$/.test(response.inputHash)))
          && (response.monitor == null || (typeof response.monitor === 'object' && !Array.isArray(response.monitor)
            && ['unavailable', 'longRunningAlert'].every(flag =>
              !Object.hasOwn(response.monitor, flag) || typeof response.monitor[flag] === 'boolean')))
          && (response.severity == null || typeof response.severity === 'string')
          && (response.elapsedMs == null || typeof response.elapsedMs === 'number')
          && Number.isFinite(elapsedMs) && elapsedMs >= 0
          && (response.pollAfterMs == null || (typeof response.pollAfterMs === 'number'
            && Number.isFinite(response.pollAfterMs) && response.pollAfterMs > 0))
          && response.error == null
          && [undefined, null, 'warning', 'alert', 'hard_failure'].includes(response.warningLevel);
      if (pendingShapeValid && Number.isSafeInteger(deadlineAt)) progress.zkProof.normalWaitDeadlineAt = deadlineAt;
      if (pendingShapeValid
          && response.monitor?.unavailable !== true && response.monitor?.longRunningAlert !== true
          && response.warningLevel !== 'hard_failure'
          && !['hard_failure', 'critical'].includes(response.severity?.toLowerCase()) && now < deadlineAt) {
        progress.zkProof.firstNormalWaitAt ??= now;
        progress.zkProof.normalWait = {
          blockNum, stage: 'zkProof', reason: 'controller_pending',
          phase: response.phase || 'pending', jobId: response.jobId,
          firstWaitAt: progress.zkProof.firstNormalWaitAt, observedAt: now,
          recheckAt: progress.waitUntil, deadlineAt,
        };
      }
      await this.enqueueCalcContinuation(blockNum, delay);
      return progress;
    }

    if (response?.status === 'failed') {
      if (response.reason === 'immutable_runtime_pin_mismatch'
          && !progress.zkProof.pinMismatchRetriedAt) {
        progress.zkProof.successorRequest = { adoptFrom: progress.zkProof.jobId, adoptRequired: false };
        progress.zkProof.successorOf = progress.zkProof.jobId;
        progress.zkProof.pinMismatchPreviousJobId = progress.zkProof.jobId;
        progress.zkProof.pinMismatchRetriedAt = Date.now();
        this.clearWireJobState(progress);
        return this.calcZkProofUnit(blockNum, progress);
      }
      if (response.reason === 'not_provable'
          && ['anchor_mismatch', 'prev_registration_mismatch'].includes(response.detail)) {
        const client = this.createReadOnlyClient();
        const latest = Number(await client.getBlockNumber());
        const confirmations = this.env.CONFIRMATION_BLOCKS
          ? Number.parseInt(this.env.CONFIRMATION_BLOCKS, 10) : 64;
        if (Number.isSafeInteger(latest) && latest >= confirmations) {
          const current = await this.readWireAnchorSnapshot(blockNum, latest - confirmations);
          const head = await this.readWireAnchorSnapshot(blockNum, latest);
          if (this.wireJobAnchorChanged(progress.zkProof.sentAnchors, current)
              || this.wireJobAnchorChanged(current, head)) {
            this.clearWireJobState(progress);
            return this.calcZkProofUnit(blockNum, progress);
          }
        }
      }
      progress.zkProof.attemptHistory = Array.isArray(response.attemptHistory)
        ? response.attemptHistory : (progress.zkProof.attemptHistory || []);
      progress.zkProof.failure = response.failure || null;
      progress.zkProof.contradiction = response.contradiction || null;
      const issue = await this.recordZkpProofIssue(blockNum, {
        kind: 'zkp_proof_failed', level: response.warningLevel || 'hard_failure',
        severity: response.severity || null,
        jobId: progress.zkProof.jobId || response.jobId || null,
        reason: response.reason || 'unknown', detail: response.detail || null,
        attempt: response.attempt || null, cleanupFailures: response.cleanupFailures || null,
        recover: 'docs/OPS_TASKS.md G2 の手動フォールバックを実行',
      });
      if (!chainConfig.required) {
        return this.finishShadowZkpFallback(blockNum, progress, {
          reason: `terminal_${response.reason || 'prover_failure'}`,
          detail: response.detail || response.reason || 'prover failed', response,
        });
      }
      throw new Error(`[zkProof] prover failed: ${JSON.stringify(issue)}`);
    }
    if (response?.status !== 'verified' || !response.proof) {
      throw new Error(`[zkProof] unexpected control response: ${JSON.stringify(response)}`);
    }

    let proof;
    try {
      proof = validateZkpProof(response.proof, { blockNum, root, vkey: chainConfig.vkey,
        elfSha256: ZKP_WIRE_EXPECTED.elfSha256 });
      const decoded = decodeZkpPublicValues(proof.publicValues);
      const sent = progress.zkProof.sentAnchors;
      if (!sent || decoded.evidenceAcc !== sent.evidenceAcc
          || decoded.resultManifestHash !== sent.resultManifestHash
          || decoded.evidenceGraceSec !== BigInt(sent.evidenceGraceSec)
          || decoded.rosterManifestHash !== sent.rosterManifestHash
          || decoded.prevResultManifestHash !== sent.prevResultManifestHash) {
        throw new Error('[zkProof] FINAL PV differs from sent anchors');
      }
      if (String(proof.verifierAddress).toLowerCase() !== String(chainConfig.verifier).toLowerCase()) {
        throw new Error(
          `[zkProof] verifier mismatch: proof=${proof.verifierAddress} chain=${chainConfig.verifier}`
        );
      }
    } catch (error) {
      await this.recordZkpProofIssue(blockNum, {
        kind: 'zkp_proof_invalid', level: 'hard_failure',
        jobId: progress.zkProof.jobId || response.jobId || null,
        error: error.message,
        recover: 'proof/PV/vkey/ELF/selector を照合し、入力を再収集して新しい証明を生成',
      });
      throw error;
    }
    progress.zkProof = {
      ...progress.zkProof,
      status: 'verified', verifiedAt: Date.now(), inputHash: response.inputHash,
      lastError: null,
      // control APIがverifiedを返す時点では全Batch attemptの削除も成功済み。
      // 最後のpoll値（RUNNING）を成果物へ残さず、terminalな実状態を明示する。
      attempt: (() => {
        const attempt = response.attempt ?? progress.zkProof.attempt;
        if (!attempt) return null;
        const { taskState: _staleTaskState, ...cleanedAttempt } = attempt;
        return { ...cleanedAttempt, state: 'CLEANED' };
      })(),
      attemptHistory: Array.isArray(response.attemptHistory)
        ? response.attemptHistory : (progress.zkProof.attemptHistory || []),
      failure: null,
      contradiction: null,
      proof: {
        schemaVersion: proof.schemaVersion,
        proofSystem: proof.proofSystem,
        vkey: proof.vkey,
        elfSha256: proof.elfSha256,
        verifierSelector: proof.verifierSelector,
        verifierAddress: proof.verifierAddress,
        merkleRoot: proof.merkleRoot,
        publicValues: proof.publicValues,
        proofBytes: proof.proofBytes,
      },
    };
    await this.putR2ObjectOrThrow(`verification/block${blockNum}/zkp-proof.json`, {
      schemaVersion: 1, blockNum,
      mode: chainConfig.required ? 'proof_required' : 'best_effort_shadow', status: 'verified',
      proofRequired: !!chainConfig.required,
      jobId: progress.zkProof.jobId, inputHash: progress.zkProof.inputHash,
      requestedAt: progress.zkProof.requestedAt, verifiedAt: progress.zkProof.verifiedAt,
      attempt: progress.zkProof.attempt ?? null,
      attemptHistory: progress.zkProof.attemptHistory ?? [],
      ...progress.zkProof.proof,
    });
    await this.clearZkpProofIssue(blockNum);
    delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
    progress.stage = 'adminCommit'; progress.cursor = 0;
    return progress;
  }

  // 🔴 R-1（2026-08-08・ラウンド20 回帰-1）: 手動 `/submit-merkle-root` 用の proof 準備。
  //    `calcProofsUnit` は「ユニット分割された集計パイプライン」用で、手動経路からは使えない
  //    （progress を持たない）。手動経路は proof を一切作らずに root を出していたので、
  //    「root 提出済み ⟹ proof も検証バンドルも準備済み」という不変量が
  //    **復旧手順を踏むたびに壊れる**状態だった。
  //    ここは 1リクエストで全レンジを発注し、`written === leafCount` を満たさなければ
  //    `ok:false` を返す（呼び出し側が root 提出を止める）。throw しないのは、
  //    HTTP 応答で「何が足りないか」を運用者へ返したいため。
  //    ⚠️ 発注は冪等（同じ proof ファイルを上書きするだけ）なので何度呼んでも安全。
  async ensureProofsPublished(blockNum, leafCount) {
    const n = Number(leafCount) || 0;
    // 空ツリー（0配分＝標識ルート）は proof が存在しない。`calcProofsUnit` の
    // `if (!leafCount)` と同じ判断で前進する。
    if (n <= 0) return { ok: true, written: 0, leafCount: 0, skipped: 'empty_tree' };
    const totalRanges = Math.ceil(n / PROOFS_RANGE);
    let written = 0;
    for (let i = 0; i < totalRanges; i += PROOFS_DISPATCH_CONCURRENCY) {
      const batch = [];
      for (let r = i; r < Math.min(i + PROOFS_DISPATCH_CONCURRENCY, totalRanges); r++) {
        batch.push(this.dispatchBuildProofs(blockNum, r * PROOFS_RANGE, Math.min((r + 1) * PROOFS_RANGE, n)));
      }
      const results = await Promise.all(batch);
      for (const res of results) written += res.written;
    }
    if (written !== n) {
      console.error(`[proofs] block ${blockNum}: written ${written} != leafCount ${n} — merkle root submission must be skipped`);
    }
    return { ok: written === n, written, leafCount: n };
  }

  // B-3: proof を除き、第三者が木を再構築するための分冊だけを決定論的に列挙する。
  // メタが旧版／不完全なら従来互換で空配列（メタ自体のhashはmanifestに残る）。
  merkleRebuildArtifactKeys(blockNum, treeMeta) {
    const leafCount = Number(treeMeta?.leafCount);
    const proofDepth = Number(treeMeta?.proofDepth);
    if (!Number.isSafeInteger(leafCount) || leafCount <= 0
      || !Number.isSafeInteger(proofDepth) || proofDepth < 0) return [];
    const declaredLayout = [
      ['leafChunkSize', MERKLE_LEAF_CHUNK],
      ['levelSegSize', MERKLE_LEVEL_SEG],
      ['indexFanout', MERKLE_INDEX_FANOUT],
    ];
    if (declaredLayout.some(([field, expected]) => treeMeta?.[field] != null && Number(treeMeta[field]) !== expected)
      || proofDepth !== Math.ceil(Math.log2(leafCount)) || proofDepth > 30) {
      throw new Error('[manifest] invalid merkle reconstruction metadata');
    }
    const leafChunkSize = MERKLE_LEAF_CHUNK;
    const levelSegSize = MERKLE_LEVEL_SEG;
    const indexFanout = MERKLE_INDEX_FANOUT;

    const keys = [];
    for (let h = 0; h < indexFanout; h++) {
      keys.push(`merkle/block_${blockNum}/index/${h.toString(16)}.json`);
    }
    for (let c = 0; c < Math.ceil(leafCount / leafChunkSize); c++) {
      keys.push(`merkle/block_${blockNum}/leaves/${c}.json`);
    }
    const paddedLeaves = 2 ** proofDepth;
    for (let level = 0; level < proofDepth; level++) {
      const levelLength = paddedLeaves / (2 ** level);
      for (let seg = 0; seg < Math.ceil(levelLength / levelSegSize); seg++) {
        keys.push(`merkle/block_${blockNum}/levels/${level}/${seg}.json`);
      }
    }
    if (keys.length > MONITOR_ARTIFACT_LIMIT) {
      throw new Error(`[manifest] merkle reconstruction artifact count ${keys.length} exceeds ${MONITOR_ARTIFACT_LIMIT}`);
    }
    return keys;
  }

  // /build-proofs 1レンジ発注（claim-worker）。書き込み数を返す。
  //
  // block0 の proofs park 事後分析（2026-07-21）: proof 生成ロジック・ツリーデータ自体は健全
  //（9葉すべて root へ畳めることを実データで確認）。park は本 dispatch の HTTP 失敗が
  // ~20回の指数バックオフ・ユニットリトライを越えて「永続」したために発生した。永続失敗の
  // 典型は 401（claim-worker の API_SECRET 未配布＝reset の secret 伝播漏れ／未デプロイ）。
  // 対策:
  //   ・認証失敗(401/403)は永続的＝即 throw＋原因を名指し（無駄なリトライをしない・lastError に出す）
  //   ・一過性(ネットワーク/5xx)は単一ユニット内で少数回リトライして吸収（park に至らせない）
  //   ・失敗時はレスポンス body を lastError に含める（/calc-status で即座に切り分け可能に）
  async dispatchBuildProofs(blockNum, from, to) {
    // S3-003: 公開 workers.dev URL → Service Binding（1ユニット最大 PROOFS_RANGES_PER_UNIT=12 呼び出し）
    const claimWorker = requireBinding(this.env, 'CLAIM_WORKER');
    if (!this.env.API_SECRET) {
      throw new Error(`[proofs] /build-proofs ${from}-${to}: game-master-DO に API_SECRET 未設定 — claim-worker に認証できません（set-all-secrets 要）`);
    }
    const MAX_ATTEMPTS = 3;
    let lastErr = null;
    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
      let response;
      try {
        response = await claimWorker.fetch(internalJsonRequest(
          '/build-proofs', { block_number: blockNum, from, to }, this.env.API_SECRET
        ));
      } catch (e) {
        // ネットワーク層の失敗＝一過性とみなしてリトライ
        lastErr = new Error(`[proofs] /build-proofs ${from}-${to}: fetch failed: ${e.message}`);
        if (attempt < MAX_ATTEMPTS) { await new Promise(r => setTimeout(r, 300 * attempt)); continue; }
        throw lastErr;
      }
      if (response.ok) {
        const data = await response.json().catch(() => null);
        if (typeof data?.written !== 'number') {
          throw new Error(`[proofs] /build-proofs ${from}-${to}: bad response (written 欠落)`);
        }
        return data;
      }
      const bodyText = await response.text().catch(() => '');
      const detail = bodyText ? ` body=${bodyText.slice(0, 200)}` : '';
      // 認証失敗は永続的＝即 throw（リトライ無駄・原因を名指し）
      if (response.status === 401 || response.status === 403) {
        throw new Error(`[proofs] /build-proofs ${from}-${to}: HTTP ${response.status} — claim-worker が認証拒否。claim-worker の API_SECRET 配布（reset の secret 伝播）とデプロイを確認してください。${detail}`);
      }
      // 5xx は一過性の可能性が高い＝リトライ。4xx はそのまま throw（body 付き）
      lastErr = new Error(`[proofs] /build-proofs ${from}-${to}: HTTP ${response.status}${detail}`);
      if (response.status >= 500 && attempt < MAX_ATTEMPTS) { await new Promise(r => setTimeout(r, 300 * attempt)); continue; }
      throw lastErr;
    }
    throw lastErr;
  }

  // ステージ11: manifest — アーティファクトsha256をチャンク収集→最終化（旧14の分割版。
  // filesのキー挿入順＝artifactKeys順を維持＝manifestCoreのJSONハッシュは旧実装と同一規則）
  async calcManifestUnit(blockNum, progress) {
    await this.assertCalcGroupingActive(blockNum, progress);
    // 旧layoutの途中cursorを新しいキー配列へ当てると挿入位置以降を読み飛ばすため、
    // デプロイを跨いだmanifest途中再開だけはhash収集を先頭からやり直す（R2書込みは冪等）。
    if (progress.manifestLayoutVersion !== CALC_MANIFEST_LAYOUT_VERSION) {
      progress.manifestLayoutVersion = CALC_MANIFEST_LAYOUT_VERSION;
      progress.cursor = 0;
      progress.manifestFiles = {};
    }
    const finalizedSummary = await this.getR2Object(`games/block${blockNum}/summary.json`);
    const merkleMeta = await this.getR2Object(`merkle/block_${blockNum}.json`);
    const merkleRebuildKeys = this.merkleRebuildArtifactKeys(blockNum, merkleMeta);
    const sortedGroupIds = await this.canonicalGroupIdsFromFinalizedSummary(blockNum, finalizedSummary, '[manifest]');
    await this.publishStage3InputManifest(blockNum, sortedGroupIds);
    const resultPageKeys = this.canonicalResultPageKeys(blockNum, finalizedSummary, '[manifest]');
    // 🔴 Q-6（2026-08-08・ユーザー確定）: 名簿（P2P の起点ファイル）も目録に載せる。
    //    ⚠️ **`publishVerificationManifest` の同名リストと1バイトも違ってはいけない**
    //       （キーの並びがそのまま `manifestCore` のバイト列＝チェーンに焼くハッシュを決める）。
    //       理由と実測は `publishVerificationManifest` 側のコメントを参照。
    const artifactKeys = [
      `entries/block${blockNum}/game_selection.json`,
      `entries/block${blockNum}/game_groups.json`,
      `games/block${blockNum}/summary.json`,
      `merkle/block_${blockNum}.json`,
      ...merkleRebuildKeys,
      `verification/block${blockNum}/evidence-report.json`,
      `games/block${blockNum}/zkp/evidence-segments.json`,
      `verification/block${blockNum}/stage3/manifest.json`,
      ...sortedGroupIds.map(g => `games/block${blockNum}/group${g}.json`),
      ...resultPageKeys,
      `games/block${blockNum}/roster/index.json`,
      ...sortedGroupIds.map(g => `games/block${blockNum}/roster/group${g}.json`),
      ...(finalizedSummary?.autoDistributed === true && [1, 2].includes(finalizedSummary.totalPlayers)
        ? [`games/block${blockNum}/roster/group0.json`] : []),
    ];
    const requiredResultKeys = new Set([
      ...merkleRebuildKeys,
      `games/block${blockNum}/zkp/evidence-segments.json`,
      `verification/block${blockNum}/stage3/manifest.json`,
      ...sortedGroupIds.map(g => `games/block${blockNum}/group${g}.json`),
      ...resultPageKeys,
      ...(finalizedSummary?.autoDistributed === true && [1, 2].includes(finalizedSummary.totalPlayers)
        ? [`games/block${blockNum}/roster/group0.json`] : []),
    ]);
    const start = progress.cursor || 0;
    const slice = artifactKeys.slice(start, start + CALC_MANIFEST_KEYS_PER_UNIT);
    const files = progress.manifestFiles || {};
    for (const key of slice) {
      const obj = await this.env.R2_BUCKET.get(key);
      if (!obj && requiredResultKeys.has(key)) {
        throw new Error(`[manifest] required result page is missing: ${key}`);
      }
      files[key] = obj ? await this.sha256R2Object(obj) : null;
    }
    progress.manifestFiles = files;
    progress.cursor = start + slice.length;
    if (progress.cursor >= artifactKeys.length) {
      await this.assertCalcGroupingActive(blockNum, progress);
      progress.verification = await this.finalizeVerificationManifest(blockNum, files);
      // 🔴 C-1 / ラウンド19 判断不要-3 レッグ (a)（2026-08-08）:
      //    `finalizeVerificationManifest` は内部の例外を握って `{ok:false, error}` を返す。
      //    旧実装は戻り値を**一度も見ずに** `stage='proofs'` へ前進していたため、
      //    **manifest を1バイトも公開していないブロックが root 提出（adminCommit）まで
      //    到達**していた。`calcAdminCommitUnit` の直前コメントが宣言する
      //    「root 提出済み ⟹ 検証も請求も全て準備済み」も、
      //    `assertGuestPinnedRules` の「fail-closed で止める」も成立していなかった。
      //    `block-verifier/src/stages/results.js` はこの不変条件を**明文で引用したうえで**
      //    manifest 欠落を `stopReason='fail'` にするので、正典側で強制しないと
      //    「第三者ツールだけが恒久 FAIL を出すブロック」が量産される。
      //    → ここで throw してユニットリトライ（20回で park）に載せる。
      //    ⚠️ `progress.manifestFiles` は throw 時も保持される（`delete` はこの後）ので、
      //       リトライは R2 の再読み込み無しに `finalizeVerificationManifest` だけをやり直す。
      if (!progress.verification?.ok) {
        const wait = adminTxWaitOf(progress.verification);
        if (wait) {
          await this.recordVerificationAdminTxWait(blockNum, progress.verification, wait, 'calculation');
          progress.waitUntil = Date.now() + wait.delay;
          progress.waitReason = wait.waitReason;
          progress.waitDetail = wait.detail;
          await this.enqueueCalcContinuation(blockNum, wait.delay);
          if (await this.calcAdminTxWaitConsumesFailure(blockNum, progress, wait)) {
            const error = new Error('[manifest] waiting for admin_tx_pending');
            error.adminTxPending = true;
            throw error;
          }
          return progress;
        }
        await this.clearVerificationAdminTxWait(blockNum);
        await this.recordVerificationPublishFailure(blockNum, progress.verification);
        throw new Error(
          `[manifest] block ${blockNum}: verification manifest not published/anchored `
          + `(${progress.verification?.error || 'unknown'}) — refusing to advance to proofs/zkProof/adminCommit`
        );
      }
      await this.clearVerificationAdminTxWait(blockNum);
      delete progress.manifestFiles;
      progress.stage = 'proofs'; progress.cursor = 0;
    }
    return progress;
  }

  // 🔴 C-1 / ラウンド19 判断不要-3 レッグ (5): manifest 公開の失敗を**監視面に出す**。
  //    `slim()` は `verification` を返さず、`done` で `calc_active:{N}` が消えるので
  //    `GET /calc-status` の `inflight` にも現れず、`sendAlertAndRecord` の対象でもなかった。
  //    park マーカーと同じ形のキーを立て、`collectLifecycleBlockers` の走査対象にする。
  verificationAdminTxPendingPeriodKey(blockNum) {
    return `verification_admin_tx_pending_period_block${blockNum}`;
  }

  async rememberVerificationAdminTxPending(blockNum, reason, source = null) {
    const key = this.verificationAdminTxPendingPeriodKey(blockNum);
    const previous = await this.storage.get(key);
    // T1c 以前の印から移行する最初の1回も、既に続いていた保留期間を失わない。
    // 理由が admin_freeze と admin_tx_pending の間で変わる場合も同じ期間を引き継ぐ。
    const legacy = previous?.pending === true
      ? null : await this.storage.get(`verification_publish_failed_block${blockNum}`);
    const carried = previous?.pending === true ? previous : (legacy?.pending === true ? legacy : null);
    const now = Date.now();
    const record = {
      blockNum,
      pending: true,
      firstSeenAt: Number.isSafeInteger(carried?.firstSeenAt) ? carried.firstSeenAt : now,
      lastSeenAt: now,
      latestReason: reason || 'admin_tx_pending',
      latestSource: source || carried?.latestSource || null,
      notifiedReasons: carried?.notifiedReasons
        ? { ...carried.notifiedReasons }
        : (carried?.notifiedReason && carried?.notifiedAt
            ? { [carried.notifiedReason]: carried.notifiedAt } : {}),
    };
    await this.storage.put(key, record);
    return record;
  }

  async recordVerificationPublishFailure(blockNum, verification, detail = {}) {
    try {
      const key = `verification_publish_failed_block${blockNum}`;
      const previous = await this.storage.get(key);
      const reason = detail.reason || verification?.reason || verification?.registered?.reason || null;
      const now = Date.now();
      let pendingPeriod = null;
      if (detail.pending === true) {
        pendingPeriod = await this.rememberVerificationAdminTxPending(
          blockNum, reason, detail.source || null,
        );
      } else {
        await this.storage.delete(this.verificationAdminTxPendingPeriodKey(blockNum));
      }
      const record = {
        blockNum,
        error: verification?.error ?? 'unknown',
        reason,
        source: detail.source || pendingPeriod?.latestSource || previous?.source || null,
        pending: detail.pending === true,
        firstSeenAt: pendingPeriod?.firstSeenAt
          ?? (Number.isSafeInteger(previous?.firstSeenAt) ? previous.firstSeenAt : now),
        lastSeenAt: now,
        notifiedReason: pendingPeriod?.notifiedReasons?.[reason] ? reason : null,
        notifiedAt: pendingPeriod?.notifiedReasons?.[reason] || null,
        notifiedReasons: pendingPeriod?.notifiedReasons || {},
        at: new Date(now).toISOString(),
      };
      await this.storage.put(key, record);
      return record;
    } catch (_) { /* ストレージ書き込み失敗は無視（throw 側のログは既に出ている） */ }
    return null;
  }

  async clearVerificationPublishFailure(blockNum, { preservePendingPeriod = false } = {}) {
    try { await this.storage.delete(`verification_publish_failed_block${blockNum}`); } catch (_) {}
    if (!preservePendingPeriod) {
      try { await this.storage.delete(this.verificationAdminTxPendingPeriodKey(blockNum)); } catch (_) {}
    }
  }

  async recordVerificationAdminFreeze(blockNum, verification, source, wait = null) {
    try {
      await this.storage.put(`verification_admin_freeze_block${blockNum}`, {
        blockNum,
        source,
        reason: 'admin_freeze',
        error: verification?.error ?? null,
        intentId: wait?.detail?.intentId ?? verification?.registered?.intentId ?? null,
        operation: wait?.detail?.operation ?? verification?.registered?.operation ?? null,
        status: wait?.detail?.status ?? verification?.registered?.status ?? null,
        txHash: wait?.detail?.txHash ?? verification?.registered?.txHash ?? null,
        at: new Date().toISOString(),
      });
    } catch (_) {}
  }

  async clearVerificationAdminFreeze(blockNum) {
    try { await this.storage.delete(`verification_admin_freeze_block${blockNum}`); } catch (_) {}
  }

  async clearVerificationAdminTxWait(blockNum) {
    await this.clearVerificationPublishFailure(blockNum);
    await this.clearVerificationAdminFreeze(blockNum);
  }

  async recordVerificationAdminTxWait(blockNum, result, wait, source) {
    // root pipeline の最初の管理txは claim data。上位の no_game / auto_distribute が
    // 同じ待ちを再観測しても、lifecycle には最も具体的な発生源を残す。
    const markerSource = wait?.detail?.stage === 'claim_data' ? 'claim_data' : source;
    if (wait.waitReason === 'admin_freeze') {
      await this.rememberVerificationAdminTxPending(blockNum, 'admin_freeze', markerSource);
      await this.clearVerificationPublishFailure(blockNum, { preservePendingPeriod: true });
      await this.recordVerificationAdminFreeze(blockNum, result, markerSource, wait);
      return null;
    }
    await this.clearVerificationAdminFreeze(blockNum);
    const failure = await this.recordVerificationPublishFailure(blockNum, result, {
      reason: wait.detail.pendingReason || wait.waitReason,
      pending: true,
      source: markerSource,
    });
    await this.maybeAlertVerificationAdminTxPending(blockNum, failure);
    return failure;
  }

  async manualVerificationFailureResponse(blockNum, verification, source) {
    const wait = adminTxWaitOf(verification);
    if (wait) {
      await this.recordVerificationAdminTxWait(blockNum, verification, wait, source);
      return createCORSResponse({
        error: wait.waitReason === 'admin_freeze'
          ? '管理鍵の差し替えを検出して送信係が凍結中です。'
            + '送信係の鍵を新しい管理鍵にすると解除されます。'
          : `管理tx送信係が不達です（${wait.detail.pendingReason || 'admin_tx_pending'}）。`
            + 'ADMIN_TX_COORDINATORのService Binding・配備・5xx・RPCを確認して再試行してください。',
        blockNum,
        reason: wait.waitReason,
        retryInMs: wait.delay,
        verification,
      }, 409);
    }
    await this.clearVerificationAdminFreeze(blockNum);
    await this.recordVerificationPublishFailure(blockNum, verification, {
      reason: verification?.reason || 'verification_publish_failed',
      pending: false,
    });
    return createCORSResponse({
      error: `[verification] block ${blockNum}: manifest not published/anchored `
        + `(${verification?.error || 'unknown'}) — merkle root submission SKIPPED. Fix R2/RPC and retry.`,
      blockNum,
      reason: 'verification_publish_failed',
      retryInMs: null,
      verification,
    }, 409);
  }

  async maybeAlertVerificationAdminTxPending(blockNum, failure) {
    if (!failure || failure.notifiedReasons?.[failure.reason]
        || Date.now() - Number(failure.firstSeenAt || Date.now()) < ADMIN_TX_PENDING_ALERT_MS) return null;
    const result = await sendAlertAndRecord(this.env, this.storage, {
      subject: `[COINU] block ${blockNum} の管理tx送信係が1時間以上応答しません`,
      body: [
        `ブロック ${blockNum} の検証manifestアンカーが管理tx送信係待ちのまま1時間以上停止しています。`,
        `理由: ${failure.reason || 'admin_tx_pending'}`,
        `初回検出: ${new Date(failure.firstSeenAt).toISOString()}`,
        `対処: ADMIN_TX_COORDINATOR のService Binding、配備状態、5xx、RPCを確認してください。`,
        `管理鍵の差し替え凍結ではありません。GET /calc-status の verification_publish_failed を確認してください。`,
      ].join('\n'),
      kind: 'verification_admin_tx_pending',
    });
    if (result.sent) {
      const key = `verification_publish_failed_block${blockNum}`;
      const current = await this.storage.get(key);
      if (current?.reason === failure.reason) {
        const notifiedAt = Date.now();
        const notifiedReasons = { ...(current.notifiedReasons || {}), [failure.reason]: notifiedAt };
        await this.storage.put(key, {
          ...current,
          notifiedReason: failure.reason,
          notifiedAt,
          notifiedReasons,
        });
        const periodKey = this.verificationAdminTxPendingPeriodKey(blockNum);
        const period = await this.storage.get(periodKey);
        if (period?.pending === true) {
          await this.storage.put(periodKey, { ...period, notifiedReasons });
        }
      }
    }
    return result;
  }

  // B01-L02: 正常な受理済み管理txの期限を、待ちの永続状態に固定する。
  // grouping と、その後に待ちを引き継いだcalcで同じ許可集合・最小期限を使う。
  rememberNormalAdminTxWait(progress, wait) {
    const detail = wait.detail;
    const normalPending = detail.accepted === true && typeof detail.intentId === 'string'
      && ['queued', 'in_flight'].includes(detail.status)
      && ['coordinator_queued', 'coordinator_requeued', 'coordinator_in_flight',
        'allocating_nonce', 'prepared_before_broadcast', 'replaced_allocating_fresh_nonce',
        'receipt_pending', 'receipt_timeout', 'receipt_finality_pending',
        'gas_price_above_cap', 'gas_price_below_base_fee',
        'preempted_before_nonce_allocation', 'propagation_grace', 'rbf_after_pending'].includes(detail.pendingReason)
      && Number.isSafeInteger(detail.deadlineAt) && detail.deadlineAt > 0;
    if (!normalPending) return false;
    const previous = progress.adminTxWaitDeadline;
    const deadlineAt = previous?.intentId === detail.intentId && Number.isSafeInteger(previous.deadlineAt)
      ? Math.min(previous.deadlineAt, detail.deadlineAt) : detail.deadlineAt;
    progress.adminTxWaitDeadline = { intentId: detail.intentId, deadlineAt };
    progress.waitDetail.deadlineAt = deadlineAt;
    return Date.now() < deadlineAt;
  }

  // B01-L04: 待ちの担当と自動停止を同じ現在状態から決める。
  // parkの正本はgroupingだけに置き、calcへ別のpark札や新しい期限を作らない。
  async calcAdminTxWaitState(blockNum, progress) {
    const grouping = await this.storage.get(`grouping_block${blockNum}_progress`);
    return {
      owner: progress?.adminTxFailureOwner === 'grouping'
        && grouping && grouping.status !== 'completed' ? 'grouping' : 'calc',
      parked: grouping?.status === 'parked',
      error: grouping?.error || null,
    };
  }

  calcGroupingParkedResult(blockNum, progress, state) {
    return {
      pending: true, parked: true, blockNum, stage: progress?.stage || null,
      waitReason: 'grouping_parked', error: state.error,
    };
  }

  async assertCalcGroupingActive(blockNum, progress) {
    const state = await this.calcAdminTxWaitState(blockNum, progress);
    if (state.parked) {
      const error = new Error(`[calc] block ${blockNum}: grouping is parked; recover_park required`);
      error.groupingParked = this.calcGroupingParkedResult(blockNum, progress, state);
      throw error;
    }
    return state;
  }

  async calcAdminTxWaitConsumesFailure(blockNum, progress, wait) {
    if (wait.waitReason !== 'admin_tx_pending') return false;
    const state = await this.assertCalcGroupingActive(blockNum, progress);
    // adminTxFailureOwnerはpipelineを作った起点。grouping未完の間の失敗加算は
    // markGroupingAdminTxWaitだけが担当する。
    // groupingがEvidence/proof待ちで完了した後はcalc自身が期限・予算・警報を持つ。
    if (state.owner === 'grouping') return false;
    return !this.rememberNormalAdminTxWait(progress, wait);
  }

  async markGroupingAdminTxWait(blockNum, progressData, wait, {
    phase, stage = 'manifest', timelineUnverified = false,
  } = {}) {
    progressData.status = 'failed';
    progressData.phase = phase || progressData.phase || 'no_game_finalizing';
    progressData.resumable = true;
    progressData.waitReason = wait.waitReason;
    progressData.waitUntil = Date.now() + wait.delay;
    progressData.waitDetail = { ...wait.detail, stage };
    progressData.timelineUnverified = timelineUnverified;
    progressData.error = `waiting for ${wait.waitReason} at ${stage}`;
    if (wait.waitReason === 'admin_tx_pending') {
      if (!this.rememberNormalAdminTxWait(progressData, wait)) {
        // 不達・RPC/照合障害・期限超過は従来の20回の予算とCRITICALを維持する。
        if (progressData.adminTxWaitDeadline?.intentId === wait.detail.intentId
            && Date.now() >= progressData.adminTxWaitDeadline.deadlineAt) {
          progressData.error = `admin tx deadline expired at ${stage}`;
        }
        const error = new Error(progressData.error);
        error.resumable = true;
        await this.recordGroupingResumableFailure(blockNum, progressData, error, wait.delay);
        return progressData;
      }
    } else {
      // 鍵差し替え凍結の既存の復旧規則は維持する。
      progressData.resumeAttempts = 0;
    }
    await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
    await this.enqueueGroupingWatchdog(blockNum, wait.delay);
    return progressData;
  }

  // 未確定の窓は正常な観測に限って免除する。履歴は異常を挟んでも延命しない。
  rememberEvidenceWindowWait(blockNum, progress, finality, delay) {
    const now = Date.now();
    if (finality.ready !== false || !Number.isSafeInteger(finality.deadlineAt)
        || !Number.isSafeInteger(finality.remainingDepth) || finality.remainingDepth <= 0
        || !Number.isSafeInteger(finality.openAt) || !Number.isSafeInteger(finality.closeAt)
        || finality.openAt < 0 || finality.openAt >= finality.closeAt
        || !Number.isSafeInteger(finality.safeTimestamp) || finality.safeTimestamp < 0
        || finality.safeTimestamp >= finality.closeAt) return null;
    const previous = progress.zkProof.evidenceWindowWaitState;
    const firstWaitAt = previous?.firstWaitAt ?? now;
    const deadlineAt = Math.min(previous?.deadlineAt ?? finality.deadlineAt, finality.deadlineAt);
    progress.zkProof.evidenceWindowWaitState = { firstWaitAt, deadlineAt };
    if (!Number.isSafeInteger(firstWaitAt) || firstWaitAt <= 0 || firstWaitAt > now
        || !Number.isSafeInteger(deadlineAt) || now >= deadlineAt) return null;
    return {
      blockNum, stage: 'zkProof', reason: 'evidence_window_not_final',
      openAt: finality.openAt, closeAt: finality.closeAt,
      safeBlockNumber: finality.safeBlockNumber, safeTimestamp: finality.safeTimestamp,
      headBlockNumber: finality.headBlockNumber, headTimestamp: finality.headTimestamp,
      closeBlockNumber: finality.closeBlockNumber,
      requiredDepth: finality.confirmations, remainingDepth: finality.remainingDepth,
      depthIsLowerBound: finality.depthIsLowerBound, finalityMode: finality.finalityMode,
      verificationPeriodSec: finality.verificationPeriodSec,
      firstWaitAt, observedAt: now, recheckAt: now + delay, deadlineAt,
    };
  }

  async readNormalEvidenceWindowWait(blockNum) {
    const [grouping, calc] = await Promise.all([
      this.storage.get(`grouping_block${blockNum}_progress`),
      this.storage.get(this.calcProgressKey(blockNum)),
    ]);
    const wait = calc?.zkProof?.evidenceWindowWait;
    const now = Date.now();
    if (grouping?.phase !== 'auto_distributing' || grouping.status === 'parked' || grouping.error
        || calc?.stage !== 'zkProof' || calc.parked || calc.lastError || calc.zkProof.jobId
        || calc.waitReason !== 'evidence_window_not_final'
        || wait?.blockNum !== blockNum || wait.reason !== 'evidence_window_not_final'
        || !Number.isSafeInteger(wait.firstWaitAt) || wait.firstWaitAt <= 0
        || wait.firstWaitAt > wait.observedAt || !Number.isSafeInteger(wait.observedAt)
        || wait.observedAt > now || !Number.isSafeInteger(wait.recheckAt) || now >= wait.recheckAt
        || !Number.isSafeInteger(wait.deadlineAt) || now >= wait.deadlineAt) return null;
    return { ...wait };
  }

  async markGroupingEvidenceWindowWait(blockNum, progressData, evidenceWait) {
    const delay = GameMasterDO.TIMELINE_RETRY_MS;
    progressData.status = 'failed';
    progressData.resumable = true;
    progressData.error = null;
    progressData.waitReason = 'evidence_window_pending';
    progressData.waitUntil = Date.now() + delay;
    progressData.waitDetail = evidenceWait;
    await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
    try { await this.enqueueGroupingWatchdog(blockNum, delay); }
    catch (error) { error.resumable = true; throw error; }
    return { success: false, blockNum, resumable: true, parked: false,
      waitReason: 'evidence_window_pending', retryInMs: 5 * 60 * 1000, evidenceWait };
  }

  // 正常pendingの札はcalcだけが発行する。失敗・park・poll時刻超過後の古い札は無効。
  async readNormalAutoProofWait(blockNum, { verifyForBlock = null } = {}) {
    const [grouping, calc] = await Promise.all([
      this.storage.get(`grouping_block${blockNum}_progress`),
      this.storage.get(this.calcProgressKey(blockNum)),
    ]);
    const wait = calc?.zkProof?.normalWait;
    const now = Date.now();
    if (grouping?.phase !== 'auto_distributing' || grouping.status === 'parked' || grouping.error
        || calc?.stage !== 'zkProof' || calc.parked || calc.lastError
        || wait?.reason !== 'controller_pending' || wait.blockNum !== blockNum
        || wait.stage !== 'zkProof' || wait.jobId !== calc.zkProof.jobId
        || !Number.isSafeInteger(wait.firstWaitAt) || wait.firstWaitAt > wait.observedAt
        || !Number.isSafeInteger(wait.observedAt) || wait.observedAt > now
        || !Number.isSafeInteger(wait.recheckAt) || now >= wait.recheckAt
        || !Number.isSafeInteger(wait.deadlineAt) || now >= wait.deadlineAt) return null;
    if (verifyForBlock !== null) {
      if (verifyForBlock !== blockNum + 1) return null;
      // 前ブロックの正常proof待ちと、別のR2/anchor障害が同時にある場合を混同しない。
      // 照合不能・不一致なら元の拒否を維持し、lotteryの失敗予算からも外さない。
      try {
        await verifyPreviousBlockArtifacts({
          blockNum: verifyForBlock,
          readText: async key => {
            const text = await this.getR2Text(key);
            if (text != null && isCanonicalJsonRequiredKey(key)) parseCanonicalJson(text, key);
            return text;
          },
          getResultHash: n => this.readResultHashOnChain(n),
          anchorRequired: Boolean(this.env.HASH_STORAGE_CONTRACT_ADDRESS),
        });
      } catch (_) { return null; }
      // 照合の外部I/O中にもpoll・期限・parkが変わり得るので、返す直前の現在状態で再判定。
      return this.readNormalAutoProofWait(blockNum);
    }
    return { ...wait };
  }

  async markGroupingProofWait(blockNum, progressData, proofWait, delay = GameMasterDO.TIMELINE_RETRY_MS) {
    progressData.status = 'failed';
    progressData.resumable = true;
    progressData.error = null;
    progressData.waitReason = 'auto_distribution_proof_pending';
    progressData.waitUntil = Date.now() + delay;
    progressData.waitDetail = proofWait;
    await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
    try { await this.enqueueGroupingWatchdog(blockNum, delay); }
    catch (error) { error.resumable = true; throw error; }
    return {
      success: false, blockNum, resumable: true, parked: false,
      waitReason: progressData.waitReason, retryInMs: delay, proofWait,
    };
  }

  clearGroupingNormalWait(progressData) {
    if (['auto_distribution_proof_pending', 'evidence_window_pending'].includes(progressData.waitReason)) {
      delete progressData.waitReason;
      delete progressData.waitUntil;
      delete progressData.waitDetail;
    }
  }

  async recordGroupingResumableFailure(blockNum, progressData, error, retryDelay = 1000) {
    const resumeAttempts = (progressData.resumeAttempts || 0) + 1;
    progressData.resumeAttempts = resumeAttempts;
    progressData.resumable = resumeAttempts <= GROUPING_MAX_ATTEMPTS;
    if (!progressData.resumable) {
      progressData.status = 'parked';
      progressData.parkedAt = Date.now();
      progressData.error = `${error.message} (parked after ${resumeAttempts - 1} auto-resumes)`;
      console.error(`[grouping] block ${blockNum} parked after ${resumeAttempts - 1} auto-resumes of a resumable stage`);
    }
    await this.storage.put(`grouping_block${blockNum}_progress`, progressData);
    if (!progressData.resumable) {
      await sendAlertAndRecord(this.env, this.storage, {
        kind: 'grouping_pipeline_parked',
        subject: `[COINU][CRITICAL] グループ処理を棚上げ: block ${blockNum}`,
        body: [
          'severity=CRITICAL',
          'reason=grouping_pipeline_parked',
          `blockNum=${blockNum}`,
          `phase=${progressData.phase || 'unknown'}`,
          `resumeAttempts=${progressData.resumeAttempts}`,
          `error=${progressData.error || error.message}`,
          'manualAction=原因を修正し POST /start-grouping の recover_park で再開する',
        ].join('\n'),
      }).catch((alertError) => {
        console.error(`[grouping] block ${blockNum}: parked alert failed: ${alertError?.message || alertError}`);
      });
    }
    if (progressData.resumable) {
      console.warn(`[grouping] block ${blockNum}: resumable yield (${error.message}) — auto-resuming (attempt ${resumeAttempts})`);
      try {
        await this.enqueueGroupingWatchdog(blockNum, retryDelay);
      } catch (enqueueError) {
        console.error(`[grouping] resume enqueue failed for block ${blockNum}:`, enqueueError.message);
      }
    }
    return { success: false, blockNum, error: error.message, resumable: !!progressData.resumable };
  }

  async readEvidenceWindowFinality(blockNum, { waitDetails = false } = {}) {
    const contractAddress = this.env.EVIDENCE_CONTRACT_ADDRESS;
    if (!contractAddress) throw new Error('[zkProof] EVIDENCE_CONTRACT_ADDRESS is not configured');
    const publicClient = this.createReadOnlyClient();
    const quorumClients = this.createEvidenceReadClients();
    if (!publicClient) throw new Error(`[zkProof] no RPC endpoint configured (${RPC_LIST_ENV})`);
    const confirmations = this.env.CONFIRMATION_BLOCKS ? parseInt(this.env.CONFIRMATION_BLOCKS) : 64;
    if (!Number.isSafeInteger(confirmations) || confirmations < 0) {
      throw new Error(`[zkProof] invalid CONFIRMATION_BLOCKS: ${this.env.CONFIRMATION_BLOCKS}`);
    }
    let safeBlockNumber; let safeBlock; let observedHead;
    if (quorumClients) {
      safeBlock = await readMatchingFinalizedBlock(quorumClients);
      safeBlockNumber = safeBlock.number;
    } else {
      const latest = await publicClient.getBlock();
      observedHead = latest;
      if (latest.number < BigInt(confirmations)) {
        return { ready: false, safeBlockNumber: null, safeTimestamp: null, closeAt: null, confirmations };
      }
      safeBlockNumber = latest.number - BigInt(confirmations);
      safeBlock = await publicClient.getBlock({ blockNumber: safeBlockNumber });
    }
    const resultWindowAbi = [{
        name: 'resultWindow', type: 'function', stateMutability: 'view',
        inputs: [{ name: 'blockNum', type: 'uint256' }],
        outputs: [{ name: 'openAt', type: 'uint256' }, { name: 'closeAt', type: 'uint256' }],
      }];
    const [openAtRaw, closeAtRaw] = quorumClients
      ? await this.readEvidenceAtBlock(quorumClients, safeBlock, getAddress(contractAddress),
        resultWindowAbi, 'resultWindow', [BigInt(blockNum)])
      : await publicClient.readContract({ address: getAddress(contractAddress), abi: resultWindowAbi,
        functionName: 'resultWindow', args: [BigInt(blockNum)], blockNumber: safeBlockNumber });
    if (quorumClients) await readMatchingFinalizedBlock(quorumClients, safeBlock);
    const safeTimestamp = Number(safeBlock.timestamp);
    const openAt = Number(openAtRaw);
    const closeAt = Number(closeAtRaw);
    if (!Number.isSafeInteger(safeTimestamp) || safeTimestamp < 0
        || !Number.isSafeInteger(openAt) || openAt < 0
        || !Number.isSafeInteger(closeAt) || closeAt <= openAt) {
      throw new Error('[zkProof] non-canonical Evidence safe timestamp/result closeAt returned by RPC');
    }
    let detail = {};
    if (waitDetails && safeTimestamp < closeAt) {
      // 既存のroot提出期限を、同じsafe blockのチェーン値から計算する。
      const miningAddress = getAddress(this.env.TOKEN_MINING_CONTRACT_ADDRESS);
      const periodRaw = quorumClients
        ? await this.readEvidenceAtBlock(quorumClients, safeBlock, miningAddress,
          TOKEN_MINING_ABI, 'verificationPeriod', [])
        : await publicClient.readContract({ address: miningAddress, abi: TOKEN_MINING_ABI,
          functionName: 'verificationPeriod', blockNumber: safeBlockNumber });
      const verificationPeriodSec = Number(periodRaw);
      const { deadlineAt } = calculateRootSubmissionDeadline(closeAt * 1000, verificationPeriodSec);
      const head = quorumClients ? await readMatchingHeadBlock(quorumClients) : observedHead;
      if (head.number < safeBlockNumber || head.timestamp < safeBlock.timestamp) {
        throw new Error('[zkProof] Evidence head precedes safe block');
      }
      let closeBlockNumber = null;
      let remainingDepth = Number(head.number - safeBlockNumber + 1n);
      const depthIsLowerBound = head.timestamp < BigInt(closeAt);
      if (!depthIsLowerBound) {
        // closeAt以降の最初の実ブロックを探す。head診断だけでreadyには昇格しない。
        let lo = safeBlockNumber + 1n; let hi = head.number;
        while (lo < hi) {
          const mid = (lo + hi) / 2n;
          const block = quorumClients ? await readMatchingHeadBlock(quorumClients, { number: mid })
            : await publicClient.getBlock({ blockNumber: mid });
          if (block.timestamp >= BigInt(closeAt)) hi = mid;
          else lo = mid + 1n;
        }
        closeBlockNumber = lo.toString();
        remainingDepth = Number(lo - safeBlockNumber);
      }
      if (!Number.isSafeInteger(remainingDepth) || remainingDepth <= 0
          || !Number.isSafeInteger(Number(head.timestamp))) {
        throw new Error('[zkProof] invalid Evidence remaining depth/head timestamp');
      }
      // 診断中のreorg/RPC不一致も免除しない。
      if (quorumClients) {
        await readMatchingHeadBlock(quorumClients, head);
        await readMatchingFinalizedBlock(quorumClients, safeBlock);
      }
      detail = { openAt, headBlockNumber: head.number.toString(), headTimestamp: Number(head.timestamp),
        closeBlockNumber, remainingDepth, depthIsLowerBound,
        finalityMode: quorumClients ? 'finalized' : 'confirmation_depth', verificationPeriodSec, deadlineAt };
    }
    if (quorumClients) await this.storage.delete(`rpc_quorum_wait_block${blockNum}`);
    return {
      ...detail,
      ready: safeTimestamp >= closeAt,
      safeBlockNumber: safeBlockNumber.toString(),
      safeTimestamp,
      closeAt,
      confirmations,
    };
  }

  // adminCommit の直前に、proof の PV 語3/10と比較する Evidence 値を同一ブロックで読む。
  // 読取不能は throw のまま呼出し元へ返し、root tx を作らない（fail-closed）。
  async readEvidenceZkpAnchorsOnChain(blockNum, atBlock = null) {
    const contractAddress = this.env.EVIDENCE_CONTRACT_ADDRESS;
    if (!contractAddress) throw new Error('[adminCommit] EVIDENCE_CONTRACT_ADDRESS is not configured');
    const publicClient = this.createReadOnlyClient();
    if (!publicClient) throw new Error(`[adminCommit] no RPC endpoint configured (${RPC_LIST_ENV})`);
    const blockNumber = atBlock == null ? await publicClient.getBlockNumber() : BigInt(atBlock);
    const abi = [
      { name: 'evidenceAcc', type: 'function', stateMutability: 'view',
        inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'bytes32' }] },
      { name: 'currentGrace', type: 'function', stateMutability: 'view',
        inputs: [{ name: 'blockNum', type: 'uint256' }], outputs: [{ name: '', type: 'uint256' }] },
    ];
    const at = (functionName) => publicClient.readContract({
      address: getAddress(contractAddress), abi, functionName,
      args: [BigInt(blockNum)], blockNumber,
    });
    const [evidenceAccRaw, currentGraceRaw] = await Promise.all([
      at('evidenceAcc'), at('currentGrace'),
    ]);
    const evidenceAcc = String(evidenceAccRaw).toLowerCase();
    if (!/^0x[0-9a-f]{64}$/.test(evidenceAcc)) {
      throw new Error('[adminCommit] non-canonical Evidence.evidenceAcc returned by RPC');
    }
    let currentGrace;
    try { currentGrace = BigInt(currentGraceRaw); }
    catch { throw new Error('[adminCommit] non-canonical Evidence.currentGrace returned by RPC'); }
    if (currentGrace < 0n) throw new Error('[adminCommit] negative Evidence.currentGrace returned by RPC');
    return { evidenceAcc, currentGrace, snapshotBlock: blockNumber.toString() };
  }

  // 🔴 2026-09-22（契約が第7引数 prevRegistrationIndex を要求）: PV word7 は
  //    **添字で名指した前ブロックの結果登録行**に束縛される（TokenMining._checkAnchors）。
  //    word7 は組分けで記録した履歴行から取り、その添字を一緒に返す。
  //    記録の無い盤は最新行を使い、履歴0件なら番兵 ＋ word7 = 0 を返す。
  //    block>0 の証明提出は履歴0件で待ち、番兵を作らない。
  //    旧記述「ユーザー決定（2026-09-22）どおり」は誤り（R30-C-2c-02）。どの行が正しいかの判定は契約でもここでもせず、block-verifier が見張り役の観測記録と突き合わせて行う。
  //    🔴 履歴getterを読めない配備では**番兵を名乗らずに throw する**。旧 HashStorage には
  //    履歴getterが無く、同じ配備の TokenMining には7引数の関数も無いので提出自体が成立しない。
  //    黙って番兵を名乗ると「履歴0件」を偽って gas を捨てるだけになる。
  // 組分けで実際に照合した前ブロックのビューを、履歴行へ固定する。
  async readGroupingPrevRegistration(blockNum, verifiedMarker, anchorStatus) {
    if (blockNum <= 0 || !this.env.HASH_STORAGE_CONTRACT_ADDRESS) return null;
    const client = this.createReadOnlyClient();
    if (!client) throw new Error('[grouping] RPC for previous registration is unavailable');
    await this.assertHashStorageBinding(client);
    const address = getAddress(this.env.HASH_STORAGE_CONTRACT_ADDRESS);
    const snapshotBlock = await client.getBlockNumber();
    const readAt = (functionName, args) => client.readContract({
      address, abi: HASH_STORAGE_ABI, functionName, args, blockNumber: snapshotBlock,
    });
    const previous = BigInt(blockNum - 1);
    const count = BigInt(await readAt('resultRegistrationCount', [previous]));
    const latest = await readAt('resultHashes', [previous]);
    const latestHash = String(Array.isArray(latest) ? latest[0] : latest?.hash).toLowerCase();
    const latestUpdated = BigInt(Array.isArray(latest) ? latest[1] : latest?.updated);
    if (anchorStatus === 'verified' && (!verifiedMarker || count === 0n
        || String(verifiedMarker.hash).toLowerCase() !== latestHash
        || BigInt(verifiedMarker.updated) !== latestUpdated)) {
      throw new Error('[grouping] previous result changed after integrity verification; retry grouping');
    }
    if (count === 0n) {
      if (latestHash !== `0x${'00'.repeat(32)}` || latestUpdated !== 0n) {
        throw new Error('[grouping] zero previous registrations disagree with latest view');
      }
      return { status: 'none' };
    }
    const index = count - 1n;
    const row = await readAt('resultRegistrationAt', [previous, index]);
    const value = (i, key) => Array.isArray(row) ? row[i] : row?.[key];
    const hash = String(value(0, 'hash')).toLowerCase();
    const registeredBlock = BigInt(value(1, 'registeredBlock'));
    const registeredAt = BigInt(value(2, 'registeredAt'));
    if (!/^0x[0-9a-f]{64}$/.test(hash) || hash !== latestHash
        || registeredBlock !== latestUpdated || registeredAt <= 0n) {
      throw new Error('[grouping] previous result history head disagrees with latest view');
    }
    return { index: index.toString(), registeredBlock: registeredBlock.toString(),
      registeredAt: registeredAt.toString(), hash };
  }

  async readPrevResultRegistrationOnChain(blockNum, atBlock = null) {
    const n = Number(blockNum);
    if (!Number.isSafeInteger(n) || n < 0) {
      throw new Error(`[adminCommit] invalid blockNum for prev result registration: ${blockNum}`);
    }
    const zero = `0x${'00'.repeat(32)}`;
    // ブロック0は前ブロックが無く、契約は `if (blockNum > 0)` で履歴を読まずに prev=0 で束縛する
    // ＝添字は無視される。オフチェーンは「履歴0件」を素直に名乗る。
    if (n === 0) {
      return {
        prevResultManifestHash: zero,
        prevRegistrationIndex: PREV_REGISTRATION_SENTINEL.toString(),
        prevRegistrationCount: '0',
        previousResultUpdatedBlock: 0,
        registeredAt: null,
        recordedStatus: null,
        snapshotBlock: null,
      };
    }
    const gameGroups = await this.getR2Object(`entries/block${n}/game_groups.json`);
    const recorded = gameGroups?.prevResultRegistration;
    if (!gameGroups) {
      const summary = await this.getR2Object(`games/block${n}/summary.json`);
      if (!summary || (summary.autoDistributed !== true
          && Array.isArray(summary.groups) && summary.groups.length > 0)) {
        throw new Error(`[adminCommit] block ${n} game_groups.json is missing`);
      }
    }
    if (gameGroups && (Number(gameGroups.blockNum) !== n
        || !Array.isArray(gameGroups.groups) || gameGroups.groups.length === 0)) {
      throw new Error(`[adminCommit] block ${n} game_groups.json is inconsistent`);
    }
    if (gameGroups && recorded === undefined) {
      throw new Error(`[adminCommit] block ${n} game_groups.json is missing prevResultRegistration`);
    }
    if (gameGroups && (!recorded || typeof recorded !== 'object' || Array.isArray(recorded))) {
      throw new Error(`[adminCommit] block ${n} has invalid recorded previous registration`);
    }
    if (recorded && recorded.status !== 'none'
        && (!/^(0|[1-9]\d*)$/.test(String(recorded.index))
          || !/^[1-9]\d*$/.test(String(recorded.registeredBlock))
          || !/^[1-9]\d*$/.test(String(recorded.registeredAt))
          || !/^0x[0-9a-f]{64}$/.test(String(recorded.hash)))) {
      throw new Error(`[adminCommit] block ${n} has invalid recorded previous registration`);
    }
    if (recorded?.status === 'none' && Object.keys(recorded).length !== 1) {
      throw new Error(`[adminCommit] block ${n} has invalid zero-registration marker`);
    }
    const contractAddr = this.env.HASH_STORAGE_CONTRACT_ADDRESS;
    if (!contractAddr) throw new Error('HASH_STORAGE_CONTRACT_ADDRESS is not configured');
    const publicClient = this.createReadOnlyClient();
    if (!publicClient) throw new Error(`no RPC endpoint configured (${RPC_LIST_ENV})`);
    await this.assertHashStorageBinding(publicClient);
    if (LEGACY_HASH_STORAGE_ALLOWLIST.has(keccak256(stringToHex(String(contractAddr).toLowerCase())))) {
      throw new Error(
        `[adminCommit] HashStorage ${contractAddr} has no result registration history getters`
        + ' — refusing to name prevRegistrationIndex (and the paired TokenMining has no 7-argument'
        + ' submitMerkleRootWithProof either, so a proof-bearing root cannot be submitted there)',
      );
    }
    const address = getAddress(contractAddr);
    const snapshotBlock = atBlock == null ? await publicClient.getBlockNumber() : BigInt(atBlock);
    const readAt = (functionName, args) => publicClient.readContract({
      address, abi: HASH_STORAGE_ABI, functionName, args, blockNumber: snapshotBlock,
    });
    const prevBlock = BigInt(n - 1);
    const historyUnreadable = (functionName, cause) => new Error(
      `[adminCommit] HashStorage ${contractAddr} ${functionName}(block ${n - 1}) unreadable`
      + ` — refusing to claim the 0-history sentinel: ${cause?.shortMessage || cause?.message || cause}`,
    );
    let count;
    try { count = BigInt(await readAt('resultRegistrationCount', [prevBlock])); }
    catch (cause) { throw historyUnreadable('resultRegistrationCount', cause); }
    if (count < 0n) {
      throw new Error('[adminCommit] non-canonical HashStorage.resultRegistrationCount returned by RPC');
    }
    if (count === 0n) {
      if (recorded && recorded.status !== 'none') {
        throw new Error('[adminCommit] recorded previous registration is absent from chain');
      }
      let latest;
      try { latest = await readAt('resultHashes', [prevBlock]); }
      catch (cause) { throw historyUnreadable('resultHashes', cause); }
      const latestHash = String(Array.isArray(latest) ? latest[0] : latest?.hash).toLowerCase();
      let latestUpdated;
      try { latestUpdated = BigInt(Array.isArray(latest) ? latest[1] : latest?.updated); }
      catch { throw new Error('[adminCommit] non-canonical HashStorage.resultHashes.updated returned by RPC'); }
      if (!/^0x[0-9a-f]{64}$/.test(latestHash) || latestUpdated < 0n) {
        throw new Error('[adminCommit] non-canonical HashStorage.resultHashes returned by RPC');
      }
      if (latestHash !== zero || latestUpdated !== 0n) {
        throw new Error(
          `[adminCommit] HashStorage result registration count is zero but latest view is nonzero:`
          + ` block=${n - 1} hash=${latestHash} updated=${latestUpdated}`
          + ' — refusing to claim the 0-history sentinel',
        );
      }
      return {
        prevResultManifestHash: zero,
        prevRegistrationIndex: PREV_REGISTRATION_SENTINEL.toString(),
        prevRegistrationCount: '0',
        previousResultUpdatedBlock: 0,
        registeredAt: null,
        recordedStatus: recorded?.status ?? null,
        snapshotBlock: snapshotBlock.toString(),
      };
    }
    const index = recorded && recorded.status !== 'none' ? BigInt(recorded.index) : count - 1n;
    if (index >= count) throw new Error('[adminCommit] recorded previous registration index is out of range');
    let row;
    try { row = await readAt('resultRegistrationAt', [prevBlock, index]); }
    catch (cause) { throw historyUnreadable('resultRegistrationAt', cause); }
    const rowHash = String(Array.isArray(row) ? row[0] : row?.hash).toLowerCase();
    if (!/^0x[0-9a-f]{64}$/.test(rowHash)) {
      throw new Error('[adminCommit] non-canonical HashStorage.resultRegistrationAt.hash returned by RPC');
    }
    const latest = await readAt('resultHashes', [prevBlock]);
    const latestHash = String(Array.isArray(latest) ? latest[0] : latest?.hash).toLowerCase();
    if (recorded && recorded.status !== 'none'
        && (String(recorded.hash).toLowerCase() !== rowHash
          || BigInt(recorded.registeredBlock) !== BigInt(Array.isArray(row) ? row[1] : row?.registeredBlock)
          || BigInt(recorded.registeredAt) !== BigInt(Array.isArray(row) ? row[2] : row?.registeredAt))) {
      throw new Error('[adminCommit] recorded previous registration differs from chain row');
    }
    if (index === count - 1n && latestHash !== rowHash) {
      throw new Error(
        `[adminCommit] HashStorage result registration history head disagrees with the latest view:`
        + ` block=${n - 1} index=${index} history=${rowHash} latest=${latestHash}`,
      );
    }
    const latestUpdated = BigInt(Array.isArray(latest) ? latest[1] : latest?.updated);
    if (index === count - 1n && latestUpdated !== BigInt(Array.isArray(row) ? row[1] : row?.registeredBlock)) {
      throw new Error('[adminCommit] previous registration head block differs from latest view');
    }
    const rowBlock = Number(Array.isArray(row) ? row[1] : row?.registeredBlock);
    const rowTime = Number(Array.isArray(row) ? row[2] : row?.registeredAt);
    if (!Number.isSafeInteger(rowBlock) || rowBlock < 0
        || !Number.isSafeInteger(rowTime) || rowTime <= 0) {
      throw new Error('[adminCommit] unsafe previous result registration number');
    }
    return {
      prevResultManifestHash: rowHash,
      prevRegistrationIndex: index.toString(),
      prevRegistrationCount: count.toString(),
      previousResultUpdatedBlock: rowBlock,
      registeredAt: rowTime,
      recordedStatus: recorded?.status ?? (recorded ? 'recorded' : null),
      snapshotBlock: snapshotBlock.toString(),
    };
  }

  // 版5の K14 と STOP-07 は同じ snapshot の追記履歴で決める。
  async readWireRosterAnchor(blockNum, atBlock, graceSec) {
    const client = this.createReadOnlyClient();
    if (!client || !this.env.EVIDENCE_CONTRACT_ADDRESS || !this.env.HASH_STORAGE_CONTRACT_ADDRESS) {
      throw new Error('[zkProof] roster anchor reader is unavailable');
    }
    await this.assertHashStorageBinding(client);
    const height = BigInt(atBlock);
    const bn = BigInt(blockNum);
    const readHash = (functionName, args) => client.readContract({
      address: getAddress(this.env.HASH_STORAGE_CONTRACT_ADDRESS), abi: HASH_STORAGE_ABI,
      functionName, args, blockNumber: height,
    });
    const safeNumber = (value, label) => {
      const number = Number(value);
      if (!Number.isSafeInteger(number) || number < 0) throw new Error(`[zkProof] invalid ${label}`);
      return number;
    };
    const entryEnd = safeNumber(await client.readContract({
      address: getAddress(this.env.EVIDENCE_CONTRACT_ADDRESS),
      abi: [{ name: 'scheduledGameStart', type: 'function', stateMutability: 'view',
        inputs: [{ type: 'uint256' }], outputs: [{ type: 'uint256' }] }],
      functionName: 'scheduledGameStart', args: [bn], blockNumber: height,
    }), 'scheduledGameStart');
    const chattingStart = safeNumber(entryEnd + safeNumber(graceSec, 'currentGrace'), 'chattingStart');
    const key = rosterAnchorKey(blockNum);
    const count = safeNumber(await readHash('otherRegistrationCount', [key]), 'otherRegistrationCount');
    const rowAt = async (index) => {
      const row = await readHash('otherRegistrationAt', [key, BigInt(index)]);
      return {
        hash: String(Array.isArray(row) ? row[0] : row?.hash).toLowerCase(),
        registeredBlock: safeNumber(Array.isArray(row) ? row[1] : row?.registeredBlock, 'roster registeredBlock'),
        registeredAt: safeNumber(Array.isArray(row) ? row[2] : row?.registeredAt, 'roster registeredAt'),
      };
    };
    const selection = await selectCanonicalRosterRegistration({
      count, at: rowAt, entryEndSec: entryEnd, chattingStartSec: chattingStart,
      nowSec: chattingStart,
    });
    if (selection.status !== 'canonical' && selection.status !== 'none') {
      throw new Error(`[zkProof] invalid canonical roster status: ${selection.status}`);
    }
    const rosterManifestHash = selection.row?.hash ?? `0x${'00'.repeat(32)}`;
    const view = await readHash('rosterLastIn', [bn, BigInt(entryEnd), BigInt(chattingStart)]);
    const viewFound = Boolean(Array.isArray(view) ? view[0] : view?.found);
    const viewHash = String(Array.isArray(view) ? view[1] : view?.hash).toLowerCase();
    if (viewHash !== rosterManifestHash || viewFound !== (selection.status === 'canonical')) {
      throw new Error('[zkProof] rosterLastIn differs from canonical roster history');
    }
    return { rosterManifestHash, entryEnd, chattingStart, key, count, rowAt };
  }

  async deriveWireGroupingUpperBound(roster) {
    if (roster.rosterManifestHash === `0x${'00'.repeat(32)}`) return roster.chattingStart;
    for (let index = 0; index < roster.count; index += 1) {
      const row = await roster.rowAt(index);
      if (row.registeredAt < roster.entryEnd) continue;
      if (row.registeredAt >= roster.chattingStart) break;
      if (row.hash === roster.rosterManifestHash) return row.registeredAt;
    }
    return roster.chattingStart;
  }

  async readWireAnchorSnapshot(blockNum, atBlock) {
    const [evidence, result, previous] = await Promise.all([
      this.readEvidenceZkpAnchorsOnChain(blockNum, atBlock),
      this.readResultHashOnChain(blockNum, atBlock),
      this.readPrevResultRegistrationOnChain(blockNum, atBlock),
    ]);
    const client = this.createReadOnlyClient();
    const registrationCount = Number(await client.readContract({
      address: getAddress(this.env.HASH_STORAGE_CONTRACT_ADDRESS), abi: HASH_STORAGE_ABI,
      functionName: 'registrationCount', args: [BigInt(blockNum)], blockNumber: BigInt(atBlock),
    }));
    const grace = Number(evidence.currentGrace);
    if (!Number.isSafeInteger(grace) || grace < 0 || !Number.isSafeInteger(registrationCount)
        || registrationCount < 0) throw new Error('[zkProof] unsafe wire anchor number');
    const resultManifestHash = String(result.hash).toLowerCase();
    if (!/^0x[0-9a-f]{64}$/.test(resultManifestHash)) {
      throw new Error('[zkProof] invalid HashStorage.resultHashes hash');
    }
    const roster = await this.readWireRosterAnchor(blockNum, atBlock, grace);
    return {
      resultManifestHash, evidenceAcc: evidence.evidenceAcc,
      evidenceGraceSec: grace, rosterManifestHash: roster.rosterManifestHash,
      prevResultManifestHash: previous.prevResultManifestHash,
      prevRegistrationIndex: previous.prevRegistrationIndex,
      previousResultUpdatedBlock: previous.previousResultUpdatedBlock,
      previousRegisteredAt: previous.registeredAt,
      recordedStatus: previous.recordedStatus,
      registrationCount,
      groupingUpperBound: await this.deriveWireGroupingUpperBound(roster),
    };
  }

  wireJobAnchorChanged(sent, current) {
    return ['resultManifestHash', 'evidenceAcc', 'evidenceGraceSec', 'rosterManifestHash',
      'prevResultManifestHash', 'prevRegistrationIndex'].some((name) =>
      String(sent?.[name]) !== String(current?.[name]));
  }

  clearWireJobState(progress) {
    for (const name of ['jobId', 'inputHash', 'attempt', 'attemptHistory', 'failure',
      'contradiction', 'monitor', 'severity', 'sentAnchors']) delete progress.zkProof[name];
  }

  async readWireAnchorsForRequest(blockNum, progress, chainConfig) {
    const client = this.createReadOnlyClient();
    if (!client) throw new Error('[zkProof] wire anchor RPC unavailable');
    const confirmations = this.env.CONFIRMATION_BLOCKS
      ? Number.parseInt(this.env.CONFIRMATION_BLOCKS, 10) : 64;
    if (!Number.isSafeInteger(confirmations) || confirmations < 0) {
      throw new Error('[zkProof] invalid CONFIRMATION_BLOCKS');
    }
    const latest = Number(await client.getBlockNumber());
    if (!Number.isSafeInteger(latest) || latest < 0) throw new Error('[zkProof] invalid latest block');
    const safe = latest - confirmations;
    let anchored = null;
    let different = safe < 0 ? ['safeBlock'] : [];
    if (safe >= 0) {
      anchored = await this.readWireAnchorSnapshot(blockNum, safe);
      const head = await this.readWireAnchorSnapshot(blockNum, latest);
      const manifest = String(progress.verification?.manifestHash || '').toLowerCase();
      different = ['resultManifestHash', 'evidenceAcc', 'evidenceGraceSec',
        'rosterManifestHash', 'prevResultManifestHash', 'prevRegistrationIndex',
        'previousResultUpdatedBlock', 'previousRegisteredAt', 'registrationCount', 'groupingUpperBound'].filter((name) =>
        String(anchored[name]) !== String(head[name]));
      const zeroHash = `0x${'00'.repeat(32)}`;
      if (anchored.resultManifestHash === zeroHash && head.resultManifestHash === zeroHash) {
        const anchorDiagnosis = await this.diagnoseZkpAnchor(blockNum, manifest);
        const previousIssue = await this.storage.get(`zkp_proof_issue_block${blockNum}`).catch(() => null);
        const issue = {
          kind: 'verification_anchor_failed', level: 'hard_failure', anchorDiagnosis,
          error: 'HashStorage.resultHashes is zero at safe and latest block',
          recover: `POST /anchor-result?block=${blockNum} で結果 manifest を再登録し、チェーンの K6 を照合`,
          alertSent: previousIssue?.kind === 'verification_anchor_failed' && previousIssue.alertSent === true,
        };
        await this.recordZkpProofIssue(blockNum, issue);
        if (!issue.alertSent) {
          try {
            const alert = await sendAlertAndRecord(this.env, this.storage, {
              kind: 'verification_anchor_failed',
              subject: `[COINU] result anchor missing: block ${blockNum}`,
              body: `block ${blockNum} / K6 is zero at safe and latest block\nPOST /anchor-result?block=${blockNum}`,
            });
            if (alert.sent) await this.recordZkpProofIssue(blockNum, { ...issue, alertSent: true });
          } catch (error) {
            console.error(`[zkProof] anchor alert failed block=${blockNum}: ${error.message}`);
          }
        }
        throw new Error('[zkProof] HashStorage.resultHashes is zero at safe and latest block');
      }
      if (anchored.resultManifestHash === zeroHash && !different.includes('resultManifestHash')) {
        different.unshift('resultManifestHash');
      }
      if (!different.length && anchored.resultManifestHash !== manifest) {
        throw new Error('[zkProof] HashStorage.resultHashes differs from GM manifest');
      }
    }
    if (different.length) {
      const delay = Math.min(GameMasterDO.TIMELINE_RETRY_MS, confirmations * 12_000 + 60_000);
      progress.zkProof.status = 'waiting_zkp_anchor_finality';
      progress.waitUntil = Date.now() + delay;
      progress.waitReason = 'zkp_anchors_not_final';
      progress.waitDetail = { stage: 'zkProof', differing: different, latestBlock: latest,
        safeBlock: safe, confirmations };
      await this.enqueueCalcContinuation(blockNum, delay);
      return null;
    }
    if (anchored.registrationCount === 0
        || (blockNum > 0 && anchored.recordedStatus === 'recorded'
          && anchored.previousRegisteredAt > anchored.groupingUpperBound)) {
      const reason = anchored.registrationCount === 0
        ? 'applicant_registration_zero' : 'prev_registration_after_grouping_upper_bound';
      await this.recordZkpProofIssue(blockNum, { kind: 'zkp_not_provable', reason,
        level: 'hard_failure', recover: 'chain anchorと組分け記録を照合' });
      if (!chainConfig.required) {
        return { fallback: await this.finishShadowZkpFallback(blockNum, progress, { reason: `terminal_${reason}` }) };
      }
      const error = new Error(`[zkProof] ${reason}`);
      error.terminal = true;
      throw error;
    }
    return { ...anchored, anchorsReadBlock: safe };
  }

  async readZkpSubmissionAnchors(blockNum) {
    const evidence = await this.readEvidenceZkpAnchorsOnChain(blockNum);
    const [chainPrev, result] = await Promise.all([
      this.readPrevResultRegistrationOnChain(blockNum, evidence.snapshotBlock),
      this.readResultHashOnChain(blockNum, evidence.snapshotBlock),
    ]);
    const roster = await this.readWireRosterAnchor(blockNum, BigInt(evidence.snapshotBlock),
      evidence.currentGrace);
    return {
      resultManifestHash: String(result.hash).toLowerCase(),
      rosterManifestHash: roster.rosterManifestHash,
      evidenceAcc: evidence.evidenceAcc,
      evidenceGraceSec: evidence.currentGrace,
      evidenceSnapshotBlock: evidence.snapshotBlock,
      prevResultManifestHash: chainPrev.prevResultManifestHash,
      previousResultUpdatedBlock: chainPrev.previousResultUpdatedBlock ?? null,
      prevRegistrationIndex: chainPrev.prevRegistrationIndex,
      prevRegistrationCount: chainPrev.prevRegistrationCount,
      prevRegistrationSnapshotBlock: chainPrev.snapshotBlock ?? null,
    };
  }

  zkpSubmissionAnchorMismatches(decoded, chainAnchors) {
    const comparisons = [
      { word: 3, name: 'evidenceAcc', chainSource: 'Evidence.evidenceAcc',
        expected: chainAnchors.evidenceAcc, actual: decoded.evidenceAcc.toLowerCase() },
      { word: 6, name: 'resultManifestHash', chainSource: 'HashStorage.resultHashes',
        expected: chainAnchors.resultManifestHash, actual: decoded.resultManifestHash.toLowerCase() },
      // 2026-09-22: 契約が束縛するのは `resultRegistrationAt(N-1, prevRegistrationIndex)` の行。
      { word: 7, name: 'prevResultManifestHash', chainSource: 'HashStorage.resultRegistrationAt',
        expected: chainAnchors.prevResultManifestHash, actual: decoded.prevResultManifestHash.toLowerCase() },
      { word: 10, name: 'evidenceGraceSec', chainSource: 'Evidence.currentGrace',
        expected: chainAnchors.evidenceGraceSec.toString(), actual: decoded.evidenceGraceSec.toString() },
      { word: 14, name: 'rosterManifestHash', chainSource: 'HashStorage.rosterLastIn',
        expected: chainAnchors.rosterManifestHash, actual: decoded.rosterManifestHash.toLowerCase() },
    ];
    return comparisons.filter(({ actual, expected }) => actual !== expected);
  }

  async resetStaleZkpProof(blockNum, progress, chainConfig, mismatches, chainAnchors) {
    const onlyPrevResult = mismatches.length === 1 && mismatches[0].word === 7;
    const reason = onlyPrevResult ? 'stale_prev_result_manifest' : 'stale_zkp_submission_anchors';
    const mismatchByWord = (word) => mismatches.find((item) => item.word === word);
    const staleJobId = progress.zkProof?.jobId || null;
    if (staleJobId) {
      try {
        await this.callZkpProver('DELETE', `/v1/jobs/${staleJobId}`, {
          reason,
        });
      } catch (error) {
        console.warn(`[zkProof] stale job cleanup pending ${staleJobId}: ${error.message}`);
      }
    }
    const stale = {
      kind: onlyPrevResult ? 'zkp_stale_prev_result_manifest' : 'zkp_stale_submission_anchors',
      level: 'warning', staleJobId,
      mismatchedWords: mismatches.map(({ word, name }) => `word${word}:${name}`),
      mismatches,
      evidenceSnapshotBlock: chainAnchors.evidenceSnapshotBlock ?? null,
      ...(mismatches.some(({ word }) => word === 3) ? {
        expectedEvidenceAcc: chainAnchors.evidenceAcc,
        actualProofEvidenceAcc: mismatchByWord(3).actual,
      } : {}),
      ...(mismatches.some(({ word }) => word === 7) ? {
        expectedPrevResultManifestHash: chainAnchors.prevResultManifestHash,
        actualProofPrevResultManifestHash: mismatchByWord(7).actual,
        previousResultUpdatedBlock: chainAnchors.previousResultUpdatedBlock,
        // 🔴 2026-09-22: word7 を作り直すと**名乗る添字も変わる**。提出の第7引数は
        //    送信直前に `readPrevResultRegistrationOnChain` から組み直されるので、
        //    ここは再収集時に運用者が突き合わせるための観測値として残す。
        expectedPrevRegistrationIndex: chainAnchors.prevRegistrationIndex ?? null,
        expectedPrevRegistrationCount: chainAnchors.prevRegistrationCount ?? null,
      } : {}),
      ...(mismatches.some(({ word }) => word === 10) ? {
        expectedEvidenceGraceSec: chainAnchors.evidenceGraceSec.toString(),
        actualProofEvidenceGraceSec: mismatchByWord(10).actual,
      } : {}),
      recover: 'current anchorから入力を再収集し、新しいjob/proofを生成してからadminCommitを再開',
    };
    await this.recordZkpProofIssue(blockNum, stale);
    progress.zkProof = {
      required: !!chainConfig.required,
      status: reason,
      claimDataPrepared: !!progress.zkProof?.claimDataPrepared,
      claimDataHash: progress.zkProof?.claimDataHash || null,
      requestedAt: Date.now(),
      vkey: chainConfig.vkey,
      verifier: chainConfig.verifier,
      stale,
    };
    delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
    progress.stage = 'zkProof'; progress.cursor = 0;
    return progress;
  }

  // zkProof の直後: adminCommit — R2公開済みツリーの root をオンチェーン提出（全工程の最後）。
  // これが成功して初めてブロックが検証/請求期間へ遷移する（フロント getBlockLifecycle stage2 の唯一の信号）。
  // manifest/proofs は既に完了済みなので、「root 提出済み ⟹ 検証も請求も全て準備済み」が保証される。
  // 提出失敗は throw→リトライ（提出は冪等・既提出はスキップ）。詰まっても「集計中（未commit）」に
  // 留まるだけで、proof 欠落のまま請求期間へ入ることはない＝安全側。
  async calcAdminCommitUnit(blockNum, progress) {
    await this.assertCalcGroupingActive(blockNum, progress);
    let root = progress.merkle?.root;
    if (!root) {
      const status = await this.storage.get(`merkle_status_${blockNum}`);
      root = status?.root || null;
    }
    if (!root) {
      throw new Error(`[adminCommit] no merkle root available for block ${blockNum} — retry merkle stage (restart if persistent)`);
    }
    // shadow 検査後に proofRequired が一方向で有効化される競合を閉じる。
    // この場合は証明なし tx を送らず、同じ alarm キューの zkProof 段へ戻す。
    const chainConfig = await this.readZkpProofConfig();
    const proofReady = progress.zkProof?.status === 'verified' || progress.zkProof?.status === 'submitted_manually';
    if (chainConfig.required && !proofReady) {
      progress.stage = 'zkProof'; progress.cursor = 0;
      return progress;
    }
    // R20-F3: proof 検証後〜broadcast前に実効世代が変わった競合を閉じる。
    if (progress.zkProof?.status === 'verified' && progress.zkProof?.proof && !chainConfig.configUnavailable) {
      const proof = progress.zkProof.proof;
      const generationMatches = String(proof.vkey).toLowerCase() === String(chainConfig.vkey).toLowerCase()
        && String(proof.verifierAddress).toLowerCase() === String(chainConfig.verifier).toLowerCase();
      if (!generationMatches) {
        if (progress.zkProof.jobId) {
          try { await this.callZkpProver('DELETE', `/v1/jobs/${progress.zkProof.jobId}`, { reason: 'effective_prover_changed' }); }
          catch (error) { console.warn(`[zkProof] old generation cancel pending: ${error.message}`); }
        }
        if (!chainConfig.required) {
          return this.finishShadowZkpFallback(blockNum, progress, {
            reason: 'effective_prover_changed_after_verification',
            detail: `proof=${proof.verifierAddress}/${proof.vkey} effective=${chainConfig.verifier}/${chainConfig.vkey}`,
          });
        }
        progress.zkProof = {
          required: true,
          status: 'generation_invalidated',
          claimDataPrepared: !!progress.zkProof.claimDataPrepared,
          claimDataHash: progress.zkProof.claimDataHash || null,
          invalidatedAt: Date.now(),
          invalidatedReason: 'effective_prover_changed_after_verification',
          verifier: chainConfig.verifier,
          vkey: chainConfig.vkey,
        };
        progress.stage = 'zkProof'; progress.cursor = 0;
        delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
        return progress;
      }
    }
    // 証明生成後に可変anchorが変わると同じproofは決定的にrevertする。送信前に
    // PV word 3/7/10 と現在chainを比較し、古いproofを再利用せず新しい入力/jobへ戻す。
    if (progress.zkProof?.status === 'verified' && progress.zkProof?.proof) {
      const decoded = decodeZkpPublicValues(progress.zkProof.proof.publicValues);
      const chainAnchors = await this.readZkpSubmissionAnchors(blockNum);
      const mismatches = this.zkpSubmissionAnchorMismatches(decoded, chainAnchors);
      if (mismatches.length > 0) {
        return this.resetStaleZkpProof(blockNum, progress, chainConfig, mismatches, chainAnchors);
      }
    }
    // [pin] merkle-submit-exempt: 集計パイプラインの adminCommit ステージ。
    //   verification.ok の検査は**前段の `calcManifestUnit` が担う**（`!progress.verification?.ok`
    //   で throw → ユニットリトライ → 20回で park）。ステージ順は
    //   merkle → manifest → proofs → zkProof → adminCommit で固定（`merkle-order-test.mjs` が静的に固定）
    //   なので、ここへ到達している時点で manifest は公開・アンカー済み。
    //   ⚠️ この免除注記を消す／ステージ順を変える場合は、ここでも verification.ok を見ること。
    await this.assertCalcGroupingActive(blockNum, progress);
    const submit = await this.submitMerkleRootForBlock(blockNum, root, {
      force: !!progress.forceSubmit,
      // falseのbest-effort期間でも、完成済みproofは1txの証明付きrootとして提出する。
      zkProof: progress.zkProof?.status === 'verified' ? progress.zkProof.proof : null,
    });
    // K-S5-002: ガス価格待ちは一時的な費用待ちなので park カウンタを進めず、30分後に再試行する。
    // ただし初回提出にも closeAt + 90日 - verificationPeriod の期限があり、待機は無料ではない。
    // 自動 force はせず、期限と残り日数を待機理由・監視・通知へ伝える。
    if (submit?.reason === 'gas_price_wait') {
      // 管理tx待ちから非管理系の費用待ちへ移ったので、連続保留期間と凍結印を切る。
      await this.clearVerificationAdminTxWait(blockNum);
      progress.waitUntil = Date.now() + GameMasterDO.TIMELINE_RETRY_MS;
      progress.waitReason = 'gas_price_wait';
      progress.waitDetail = {
        currentGwei: submit.currentGwei,
        limitGwei: submit.limitGwei,
        limitSource: submit.limitSource,
        deadlineAt: submit.deadlineAt ?? null,
        deadlineDaysLeft: submit.deadlineDaysLeft ?? null,
      };
      await this.enqueueCalcContinuation(blockNum, GameMasterDO.TIMELINE_RETRY_MS);
      return progress; // stage は adminCommit のまま（drive ループが waitUntil を見て抜ける）
    }
    const wait = adminTxWaitOf(submit);
    if (wait) {
      const source = wait.detail.stage === 'claim_data' ? 'claim_data' : 'admin_commit';
      await this.recordVerificationAdminTxWait(blockNum, submit, wait, source);
      progress.waitUntil = Date.now() + wait.retryInMs;
      progress.waitReason = wait.waitReason;
      progress.waitDetail = { ...wait.detail, stage: wait.detail.stage || 'adminCommit' };
      await this.enqueueCalcContinuation(blockNum, wait.retryInMs);
      if (await this.calcAdminTxWaitConsumesFailure(blockNum, progress, wait)) {
        const error = new Error(`[adminCommit] waiting for admin_tx_pending at ${progress.waitDetail.stage}`);
        error.adminTxPending = true;
        throw error;
      }
      return progress;
    }
    // 受領・分類・決定的失敗・成功のどれでも、管理tx専用の待ちはここで解消済み。
    await this.clearVerificationAdminTxWait(blockNum);
    if (submit?.reason === 'claim_data_receipt_pending') {
      const delay = Number(submit.retryInMs) || ADMIN_TX_PENDING_RETRY_MS;
      progress.waitUntil = Date.now() + delay;
      progress.waitReason = 'claim_data_receipt_pending';
      progress.waitDetail = {
        stage: 'adminCommit',
        txHash: submit.claimData?.txHash || null,
        chunkIndex: submit.claimData?.chunkIndex ?? null,
        pendingReason: submit.claimData?.reason || 'receipt_timeout',
      };
      await this.enqueueCalcContinuation(blockNum, delay);
      return progress;
    }
    if (submit?.reason === 'classification_unavailable' || submit?.reason === 'preflight_unavailable') {
      const delay = Number(submit.retryInMs) || ADMIN_TX_PENDING_RETRY_MS;
      progress.waitUntil = Date.now() + delay;
      progress.waitReason = submit.reason;
      progress.waitDetail = {
        stage: 'adminCommit',
        txHash: submit.txHash || null,
      };
      await this.enqueueCalcContinuation(blockNum, delay);
      return progress;
    }
    if (!submit?.submitted && submit?.reason === 'tx_error'
      && /\bPV:\s*prevResultManifest mismatch\b/.test(String(submit.error || ''))
      && progress.zkProof?.status === 'verified' && progress.zkProof?.proof) {
      // preflight直後に前ブロックanchorが更新された競合も、同じproofの再送へ戻さない。
      const decoded = decodeZkpPublicValues(progress.zkProof.proof.publicValues);
      const chainAnchors = await this.readZkpSubmissionAnchors(blockNum);
      const mismatches = this.zkpSubmissionAnchorMismatches(decoded, chainAnchors);
      if (mismatches.length > 0) {
        return this.resetStaleZkpProof(blockNum, progress, chainConfig, mismatches, chainAnchors);
      }
    }
    if (!submit?.submitted) {
      const error = new Error(`[adminCommit] submitMerkleRoot not confirmed for block ${blockNum}: ${JSON.stringify(submit)}`);
      if (submit?.reason === 'tx_error' && /\bPV:\s*[^\n]+ mismatch\b/.test(String(submit.error || ''))) {
        error.terminal = true;
        error.errorClass = 'deterministic_contract_revert';
        await this.recordZkpProofIssue(blockNum, {
          kind: 'zkp_admin_commit_deterministic_revert', level: 'hard_failure',
          error: submit.error,
          recover: 'PVと現在chain anchorを照合し、staleなら入力再収集。その他は同一proofを再送せず原因修正後にunpark',
        });
      }
      throw error;
    }
    delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
    delete progress.forceSubmit;
    if (!progress.merkle) progress.merkle = { ok: true, root };
    progress.merkle.submit = submit;
    const postCommit = await this.storage.get(this.postCommitZkpKey(blockNum));
    if (postCommit?.status === 'root_fallback_keep_proving'
      || postCommit?.cleanupStatus === 'zkp_cleanup_pending') {
      await this.enqueuePostCommitZkp(blockNum, 1000);
    }
    progress.stage = 'cleanup'; progress.cursor = 0;
    return progress;
  }

  // ステージ12: cleanup — 中間キー掃除＋最終結果確定（旧モノリスの戻り値と同形）。
  // best-effort: この段階に来た時点で公開物・オンチェーン提出は全て確定済みなので、
  // 掃除が失敗しても実害は無い（残るのは一時キーだけ）。throw せず必ず done にして park を避ける。
  async calcFinalizeUnit(blockNum, progress) {
    const result = {
      success: true,
      blockNum,
      groupCount: progress.groupCount,
      totalPoints: progress.totalPoints,
      blockReward: progress.blockRewardWei,
      merkle: progress.merkle,
      verification: progress.verification
    };
    try {
      for (;;) {
        const page = await this.storage.list({ prefix: `calc:${blockNum}:`, limit: 128 });
        if (!page.size) break;
        await this.storage.delete([...page.keys()]);
      }
    } catch (e) {
      console.warn(`[calc] block ${blockNum}: cleanup of intermediate keys failed (harmless, block already finalized): ${e.message}`);
    }
    // 🔴 S3C5（D-06）: そのブロックの集計がすべて終わったので、D1 evidence_events に残した
    //   採用候補の中身（data）も空ける。要約と判定（seq・送り手・tx・長さ・keccak・valid ほか）は残す。
    //   採用候補の中身を読むのは depids / scoring の calcLoadAdoptedRaw だけで、ここはその後。
    //   やり直し（restart）は calcCleanupKeys で歩行カーソルごと消すので、チェーンの歩き直しで戻る。
    //   失敗しても残るのは uid ごと最大1件の有効な提出物だけ（第三者が積み増せない）なので、
    //   このステージの規則どおり throw せず警告だけにする。Evidence を取り込んだブロックだけが対象
    //   （ゲーム無し・2名以下・提出0件は evidence_events に行を書かない）。
    const evidenceDb = this.env.BITCOINU_DATA;
    if (evidenceDb && Number(progress.evidence?.resultCount) > 0) {
      try {
        await evidenceDb.prepare(
          `UPDATE evidence_events SET data = '' WHERE kind='result' AND block_num = ? AND data <> ''`
        ).bind(blockNum).run();
      } catch (e) {
        console.warn(`[calc] block ${blockNum}: clearing retained evidence data failed (block already finalized; at most one valid submission per uid remains): ${e.message}`);
      }
    }
    progress.stage = 'done';
    progress.result = result;
    return progress;
  }

  // zero_entries／2名以下自動配布／手動復旧は通常どおり zkProof → adminCommit → cleanup。
  // 安全確定済みtimeline no-gameだけはcalcZkProofUnitが証明発注前に別終端へ振り分ける。
  // calc progress と既存alarmを再利用し、proofRequired=false の手動fallback導線も維持する。
  async finalizePublishedRootWithPipeline(blockNum, {
    merkle, verification, groupCount = 0, totalPoints = '0', blockRewardWei = null, force = false,
    adminTxFailureOwner = 'calc',
  }) {
    if (!merkle?.ok || !verification?.ok) return merkle;
    // ゲーム無し／2名以下の自動配布でも zkp-guest は「leaf 0件」の集約proofを必須にする。
    // 通常採点は calcSummaryUnit が manifest を公開するが、この2経路は scoring/summary を
    // 通らないため、ここで空manifestを確定する。復旧APIは groupCount の既定値0でここへ
    // 来ることがあるので、確定summaryも空である場合だけ書き、実ゲームのmanifestを
    // 空配列で上書きしない。
    if (Number(groupCount) === 0) {
      const finalizedSummary = await this.getR2Object(`games/block${blockNum}/summary.json`);
      // 空かどうかの判定だけで D1 / game_groups を再読しない。summary はこの直前の
      // verification manifest でbyte固定済み。不明な形は空とみなさずfail-closedにする。
      if (Number(finalizedSummary?.blockNum) === Number(blockNum)
          && Array.isArray(finalizedSummary?.groups) && finalizedSummary.groups.length === 0) {
        await this.putR2ObjectOrThrow(`zkp/block${blockNum}/manifest.json`, {
          schemaVersion: 1,
          blockNum,
          groupCount: 0,
          files: [],
        });
      }
    }
    const key = this.calcProgressKey(blockNum);
    let progress = await this.storage.get(key);
    if (progress?.stage === 'done' && progress?.result?.merkle?.root === merkle.root) {
      return progress.result.merkle;
    }
    if (!progress || progress.stage === 'done') {
      progress = {
        blockNum,
        stage: 'zkProof',
        cursor: 0,
        startedAt: Date.now(),
        runId: crypto.randomUUID(),
        failures: 0,
        groupCount,
        totalPoints,
        blockRewardWei: blockRewardWei ?? getBlockRewardWei(blockNum).toString(),
        merkle,
        verification,
        adminTxFailureOwner,
        ...(force ? { forceSubmit: true } : {}),
      };
      await this.storage.put(key, progress);
      try {
        await this.storage.put(`calc_active:${blockNum}`, { blockNum, at: Date.now(), kind: 'root_finalization', advisory: true });
      } catch (_) {}
    } else if (force) {
      // R20-F4: 既存 progress にも force を反映する。ただし解除できる待ちは gas 価格だけ。
      progress.forceSubmit = true;
      if (progress.waitReason === 'gas_price_wait') {
        delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
      }
      await this.storage.put(key, progress);
      // 互換マーカーの欠落は再開を止めない。進捗自身が必ず保存される起点。
      try {
        if (!(await this.storage.get(`calc_active:${blockNum}`))) {
          await this.storage.put(`calc_active:${blockNum}`, { blockNum, at: Date.now(), kind: 'root_finalization', advisory: true });
        }
      } catch (_) {}
    }
    if (progress.adminTxFailureOwner !== adminTxFailureOwner) {
      progress.adminTxFailureOwner = adminTxFailureOwner;
      await this.storage.put(key, progress);
    }
    let result;
    try {
      result = await this.calculateAndStoreResults(blockNum);
    } catch (error) {
      // calculateAndStoreResultsは一時失敗を永続化し、alarm再試行を積んだうえで呼び出し元にも
      // throwする。no-game/grouping側までfailedへ落とすと、calcだけ回復してgroup-statusが
      // failed/no_game_finalizingに残る。calc_activeが生きていて未parkなら通常のpendingと同じ扱いにする。
      const [active, current] = await Promise.all([
        this.storage.get(`calc_active:${blockNum}`),
        this.storage.get(key),
      ]);
      if (!active || !current || current.parked) throw error;
      return {
        ...merkle,
        submit: {
          submitted: false,
          reason: 'zk_proof_pending',
          stage: current.stage || progress.stage,
          parked: false,
          retryingAfterError: String(error?.message || error).slice(0, 500),
        },
      };
    }
    if (result?.pending) {
      const wait = adminTxWaitOf(result);
      return {
        ...merkle,
        submit: {
          submitted: false,
          reason: result.parked ? 'zk_proof_parked' : (wait?.waitReason || result.waitReason || 'zk_proof_pending'),
          stage: result.stage || progress.stage,
          parked: !!result.parked,
          retryInMs: wait?.retryInMs || null,
          waitDetail: wait?.detail || result.waitDetail || null,
        },
      };
    }
    return result?.merkle || merkle;
  }

  // ============================================================
  // 検証バンドルmanifest: 公開 → HashStorage にアンカー（改善C / D2・D3）
  //   結果確定時に、検証に必要な全アーカイブ（選出・グループ分け・summary・merkle・
  //   全グループアーカイブ）のsha256一覧をmanifestとしてR2公開し、そのハッシュを
  //   HashStorage.registerResultHash でオンチェーンコミットする。
  //   → 第三者は取得したアーカイブをmanifestと照合し、manifestハッシュをオンチェーン値と
  //     照合することで「アーカイブの事後差し替え」を暗号学的に検出できる。
  //   applicantHash同様、再計算時は上書き登録できる（回数はresultRegistrationCountで可視化）。
  // ============================================================

  async sha256Hex(text) {
    const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
    return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
  }

  async sha256R2Object(obj) {
    // WebCrypto digest は入力全体を要求する。既存依存の noble は逐次 update 可能。
    if (!obj.body?.getReader) return this.sha256Hex(await obj.text()); // 小さいテスト stub
    const hash = incrementalSha256.create();
    const reader = obj.body.getReader();
    try {
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        hash.update(value);
      }
    } finally { reader.releaseLock(); }
    return Array.from(hash.digest()).map(b => b.toString(16).padStart(2, '0')).join('');
  }

  async publishStage3GroupWitness({
    blockNum, groupRow, groupData, verifiedDepositWei, chatWindow,
  }) {
    const witness = buildGroupWitness({
      groupRow, groupData, verifiedDepositWei, chatWindow,
    });
    const text = JSON.stringify(witness);
    const object = `verification/block${blockNum}/stage3/group-${groupRow.group_id}.json`;
    const sha256 = await this.sha256Hex(text);
    await this.putR2ObjectOrThrow(object, witness);
    return { object, sha256 };
  }

  async publishStage3InputManifest(blockNum, sortedGroupIds) {
    if (!Array.isArray(sortedGroupIds) || sortedGroupIds.length > 530) {
      throw new Error(`[stage3] block ${blockNum}: group count must be 0..530`);
    }
    if (sortedGroupIds.some((groupId, index) => Number(groupId) !== index)) {
      throw new Error(`[stage3] block ${blockNum}: group ids must equal their zero-based indices`);
    }
    const scoreRecords = await this.storage.list({ prefix: this.calcKey(blockNum, 'score', '') });
    const byGroupId = new Map();
    for (const [, record] of scoreRecords) {
      const groupId = Number(record?.groupId);
      if (Number.isSafeInteger(groupId) && groupId >= 0) byGroupId.set(groupId, record);
    }
    const missingPins = [];
    const groups = sortedGroupIds.map((rawGroupId) => {
      const groupId = Number(rawGroupId);
      const expectedObject = `verification/block${blockNum}/stage3/group-${groupId}.json`;
      const pin = byGroupId.get(groupId)?.stage3;
      if (pin?.object !== expectedObject || !/^[0-9a-f]{64}$/.test(String(pin?.sha256 || ''))) {
        missingPins.push(groupId);
        return null;
      }
      return { groupId, object: expectedObject, sha256: pin.sha256 };
    }).filter(Boolean);
    if (missingPins.length > 0) {
      // 完了後は calc:* の一時 score record が削除済みになる。既存の固定済み目録が
      // 同じ groupId 集合を厳密に持つ場合だけ再利用し、部分欠落は必ず止める。
      if (byGroupId.size === 0) {
        const existing = await this.getR2Object(`verification/block${blockNum}/stage3/manifest.json`);
        const existingIds = Array.isArray(existing?.groups)
          ? existing.groups.map(group => Number(group?.groupId)) : null;
        if (existing?.schemaVersion === 1 && existing?.kind === 'bitcoinu-stage3-input-manifest'
            && Number(existing.blockNum) === Number(blockNum)
            && existing.groupCount === sortedGroupIds.length
            && JSON.stringify(existingIds) === JSON.stringify(sortedGroupIds.map(Number))
            && existing.groups.every(group => (
              group?.object === `verification/block${blockNum}/stage3/group-${group.groupId}.json`
              && /^[0-9a-f]{64}$/.test(String(group?.sha256 || ''))
            ))) {
          return existing;
        }
      }
      throw new Error(
        `[stage3] block ${blockNum}: witness pin is missing or invalid for groups ${missingPins.join(',')}`,
      );
    }
    for (let index = 0; index < groups.length; index++) {
      if (groups[index].groupId !== index) {
        throw new Error(`[stage3] block ${blockNum}: group ids must equal their zero-based indices`);
      }
    }
    const manifest = {
      schemaVersion: 1,
      kind: 'bitcoinu-stage3-input-manifest',
      blockNum,
      groupCount: groups.length,
      groups,
    };
    await this.putR2ObjectOrThrow(`verification/block${blockNum}/stage3/manifest.json`, manifest);
    return manifest;
  }

  async stage3DispatchForBlock(blockNum) {
    const manifestObject = `verification/block${blockNum}/stage3/manifest.json`;
    const text = await this.getR2Text(manifestObject);
    const fail = (message) => {
      const error = new Error(`[stage3] block ${blockNum}: ${message}`);
      error.stage3ArtifactsMissing = true;
      throw error;
    };
    if (text == null) fail(`input manifest is missing: ${manifestObject}`);
    let manifest;
    try { manifest = JSON.parse(text); }
    catch (error) { fail(`input manifest is invalid JSON: ${error.message}`); }
    if (JSON.stringify(manifest) !== text
        || manifest?.schemaVersion !== 1 || manifest?.kind !== 'bitcoinu-stage3-input-manifest'
        || Number(manifest?.blockNum) !== Number(blockNum)
        || !Number.isInteger(manifest?.groupCount) || manifest.groupCount < 0 || manifest.groupCount > 530
        || !Array.isArray(manifest?.groups) || manifest.groups.length !== manifest.groupCount) {
      fail('input manifest schema/group count is invalid');
    }
    return {
      manifestObject,
      manifestSha256: await this.sha256Hex(text),
      groupCount: manifest.groupCount,
    };
  }

  async publishVerificationManifest(blockNum, groupIds) {
    try {
      // 🔴 Q-6（2026-08-08・ユーザー確定）: **名簿（P2P の起点ファイル）も目録に載せる。**
      //    `games/block{N}/roster/index.json`（uid→groupId の索引）と
      //    `games/block{N}/roster/group{G}.json`（walletAddress / blockAddress / pubKey / depositIds）は
      //    WS を検閲されたクライアントが P2P 冗長経路を張るための**信頼の起点**なのに、
      //    ここに入っていなかった＝検証ツールが一度も読まない＝**バイト列が何にも固定されていなかった**。
      //    実測: `roster/group0.json` の1人の `blockAddress`/`pubKey` を攻撃者鍵へ差し替えても
      //    `exit 0 / ##RESULT full / pass 62 / warn 0 / fail 0`。しかも差し替えは無言
      //    （`relay-verify.js:71` の `catch { return false }`）で、被害者には
      //    「相手が何も喋っていない」ようにしか見えない（削除は可視・差し替えは不可視）。
      //    → 目録に入れることでバイト列が manifest ハッシュ経由でチェーンに固定される。
      //    ⚠️ これだけでは足りない（運営が差し替えた名簿を manifest に含めて一貫させれば通る）。
      //       検証ツール側で**応募データ（applicantHash でチェーンに固定）との突き合わせ**も行う。
      // `groupIds` は旧呼び出し互換のため受けるだけ。権威は確定 summary から導く。
      const finalizedSummary = await this.getR2Object(`games/block${blockNum}/summary.json`);
      const merkleMeta = await this.getR2Object(`merkle/block_${blockNum}.json`);
      const merkleRebuildKeys = this.merkleRebuildArtifactKeys(blockNum, merkleMeta);
      const sortedGroupIds = await this.canonicalGroupIdsFromFinalizedSummary(blockNum, finalizedSummary, '[manifest]');
      await this.publishStage3InputManifest(blockNum, sortedGroupIds);
      const resultPageKeys = this.canonicalResultPageKeys(blockNum, finalizedSummary, '[manifest]');
      const artifactKeys = [
        `entries/block${blockNum}/game_selection.json`,
        `entries/block${blockNum}/game_groups.json`,
        `games/block${blockNum}/summary.json`,
        `merkle/block_${blockNum}.json`,
        ...merkleRebuildKeys,
        `verification/block${blockNum}/evidence-report.json`,
        `games/block${blockNum}/zkp/evidence-segments.json`,
        `verification/block${blockNum}/stage3/manifest.json`,
        ...sortedGroupIds.map(g => `games/block${blockNum}/group${g}.json`),
        ...resultPageKeys,
        `games/block${blockNum}/roster/index.json`,
        ...sortedGroupIds.map(g => `games/block${blockNum}/roster/group${g}.json`),
        ...(finalizedSummary?.autoDistributed === true && [1, 2].includes(finalizedSummary.totalPlayers)
          ? [`games/block${blockNum}/roster/group0.json`] : []),
      ];
      const requiredResultKeys = new Set([
        ...merkleRebuildKeys,
        `games/block${blockNum}/zkp/evidence-segments.json`,
        `verification/block${blockNum}/stage3/manifest.json`,
        ...sortedGroupIds.map(g => `games/block${blockNum}/group${g}.json`),
        ...resultPageKeys,
        ...(finalizedSummary?.autoDistributed === true && [1, 2].includes(finalizedSummary.totalPlayers)
          ? [`games/block${blockNum}/roster/group0.json`] : []),
      ]);

      // 各アーカイブのsha256（存在しないものはnull＝autoDistribute等でグループ無しのケース）
      const files = {};
      for (const key of artifactKeys) {
        const obj = await this.env.R2_BUCKET.get(key);
        if (!obj) {
          if (requiredResultKeys.has(key)) {
            throw new Error(`[manifest] required result page is missing: ${key}`);
          }
          files[key] = null;
          continue;
        }
        files[key] = await this.sha256R2Object(obj);
      }

      return await this.finalizeVerificationManifest(blockNum, files);
    } catch (e) {
      console.error(`[verification] ⚠️ publishVerificationManifest FAILED for block ${blockNum}:`, e);
      return { ok: false, error: e.message };
    }
  }

  // manifest最終化（rules構築→R2公開→オンチェーンアンカー）。
  // publishVerificationManifest（一括ハッシュ）と calcManifestUnit（チャンクハッシュ）が共有する。
  async finalizeVerificationManifest(blockNum, files) {
    try {
      const selection = await this.getR2Object(`entries/block${blockNum}/game_selection.json`);
      const target = selection?.targetBlockNum;
      const registeredBlock = selection?.hashRegisteredBlock;
      const confirmationBlocks = target - registeredBlock;
      if (!Number.isSafeInteger(target) || target < 0
          || !Number.isSafeInteger(registeredBlock) || registeredBlock < 0
          || !Number.isSafeInteger(confirmationBlocks) || confirmationBlocks < 0) {
        throw new Error(`[manifest] invalid K11 confirmation depth in game_selection.json for block ${blockNum}`);
      }
      // このブロックの採点に適用したルール定数一式も core に含めてアンカーする。
      // → 「どの定数で採点したか」がオンチェーンハッシュに固定され、運営が特定ブロックだけ
      //   密かに定数を変えて採点する操作（例: minCharsを吊り上げて全員失格）が
      //   公開宣言との照合で検出可能になる。検証ツールはこの値で再計算して照合する。
      // 🔴 P-2026-0821（2026-08-07・B-4）: **宣言値は採点の適用値と同一ソースから出す。**
      //    旧実装は `minChars` / `minMessages` をここで別に `parseInt` しており、
      //    `GAME_MIN_CHARS` が非数値のとき manifest には `null`（JSON 化で NaN → null）が載る一方、
      //    採点側は比較が空振りして「閾値なし」で走った ＝ **宣言と適用が別物**だった。
      //    （この食い違いは block-verifier の `check.stageC.rulesPins` が
      //      `null ≠ 100` で FAIL にするので第三者からは可視だが、可視なだけで採点は間違っている。）
      const declaredMins = this.getScoringMins();
      const declaredCaps = this.getChatCaps();
      // 🔴 P-2026-0822（2026-08-07）: **宣言値もゲスト定数と一致していなければ公開しない。**
      //    採点側（`calcScoringUnit`）にも同じ検査があるが、ここは重複ではない:
      //    この関数は**採点を一度も通らない経路**からも呼ばれる。
      //      ・ゲーム無しブロック（:561）／自動配布ブロック（:7014）— グループが無く scoring 段が走らない
      //      ・`/submit-merkle-root`（:1541/:1555）・`/anchor-result` — 復旧用の manifest 再公開
      //    manifest の `rules` は R2 で公開され HashStorage にアンカーされる**対外的な宣言**で、
      //    block-verifier はこの値を pin と突き合わせる。ゲストの焼き込み値と違う宣言を
      //    公開してしまうと「証明が通らない規則で採点された」と第三者に読める状態が残る。
      //    fail-closed（throw → `{ok:false}` を返し manifest を公開しない）で止める。
      assertGuestPinnedRules(
        { ...declaredMins, ...declaredCaps },
        `block ${blockNum} manifest rules`
      );
      const rules = {
        // P2P計画 §7: 採点プロトコル版数。版数ゲート廃止＝常に 2（v1ブロック不在・2026-07-07）。
        protocol: 2,
        minChars: declaredMins.minChars,
        minMessages: declaredMins.minMessages,
        // §2.1b チャット量キャップ（applyChatCaps 規則: id昇順累積・超過分を正本から除外）
        maxChars: declaredCaps.maxChars,
        maxMessages: declaredCaps.maxMessages,
        maxMsgChars: declaredCaps.maxMsgChars,
        periodDurations: { gamePeriod: this.gamePeriodMs, submitPeriod: this.submitPeriodMs },
        startTime: this.env.START_TIME || null,        // 応募期間開始（オンチェーンTokenMining.START_TIME − BLOCK_INTERVAL）
        blockTime: this.env.BLOCK_TIME ? parseInt(this.env.BLOCK_TIME) : null,
        blockRewardWei: getBlockRewardWei(blockNum).toString(),
        maxReports: 2,
        // K-S2-003: 適格条件（最低発言量・発言回数）で不可視文字を除外する規則の版数。
        // 範囲表を変更したら char-counter.js の VISIBLE_CHARS_RULE_VERSION を上げること。
        visibleCharsRule: VISIBLE_CHARS_RULE_VERSION,
        // v3.3: 受領証明のリアルタイム窓（|受領ts − 発信主張ts| ≤ この値のみ有効・バックデート挟み込み遮断）
        receiptFreshWindowMs: RECEIPT_FRESH_WINDOW_MS,
        // 規則版数5: 密告の資格は標的の確定投票と、標的ごとの時刻条件で判定する。
        // reportMinReadReceipts は manifest の形を保つために残すが、採点では使わない。
        // reportEligibilityRule は protocol-v2.js の REPORT_ELIGIBILITY_RULE_VERSION（5）。
        reportMinReadReceipts: REPORT_MIN_READ_RECEIPTS,
        reportEligibilityRule: REPORT_ELIGIBILITY_RULE_VERSION,
        // 案B（2026-07-28）: 既読受領証明が指す参照は msgKey の先頭 msgRefBytes バイト。
        // Evidence の gzip後128KB（= geth のトランザクション伝播上限）に収めるための短縮。
        msgRefBytes: MSG_REF_BYTES,
        // Q-S2-001（2026-07-28）: 受領証明の分量上限（採点CPUの枯渇対策）。
        // 超過は無視するだけで失格にはしない。
        //
        // 🔴 P-2026-0909（2026-08-08）: 行動受領証明の枠は **基数 × groupSize**（`protocol-v2.js`
        //    の `receiptMaxActionsPerPair`）であって、基数そのものではない。
        //    実際の枠は 3人組=30 / 4人組=40 / 5人組=50。
        //    ここが基数10を「枠」として公開していたため、manifest だけが
        //    `docs/CHAT_GAME_SIMPLIFICATION_SPEC.md:740` と矛盾していた。
        receiptMaxActionsPerPairBase: RECEIPT_MAX_ACTIONS_PER_PAIR_BASE,   // 適用値 = base × groupSize
        // ← 旧鍵。互換のため残す（消すと旧ブロックが照合スキップで素通りする）。
        receiptMaxActionsPerPair: RECEIPT_MAX_ACTIONS_PER_PAIR_BASE,
        receiptMaxRefsPerReceipt: receiptMaxRefsPerReceipt(declaredCaps.maxMessages),
        // K-S6-002（2026-07-29）: 受領証明・観測発信の受理規則。
        //   ・受領証明は**実在する対象**をカバーするものだけ数える（参照整合性）
        //   ・観測発信は (提出者, 発信者) ペアごとに maxObservedActionsPerActor 件まで
        // 数え方を変えたら protocol-v2.js の RECEIPT_ACCEPTANCE_RULE_VERSION を上げること。
        maxObservedActionsPerActor: MAX_OBSERVED_ACTIONS_PER_ACTOR,
        receiptAcceptanceRule: RECEIPT_ACCEPTANCE_RULE_VERSION,
        // Round 21 F1: 署名済み提出物全体の有限入力契約と transport 形式。
        // block-verifier は全キーを必須 pin として厳密照合する。
        submissionLimitsVersion: SUBMISSION_LIMITS_VERSION,
        evidenceCompactFormat: EVIDENCE_COMPACT_FORMAT,
        maxDepositIds: MAX_DEPOSIT_IDS,
        maxMessagesPerPlayer: MAX_MESSAGES_PER_PLAYER,
        maxMessagesTotal: MAX_MESSAGES_TOTAL,
        maxMessageChars: MAX_MESSAGE_CHARS,
        maxMessageCharsPerPlayer: MAX_MESSAGE_CHARS_PER_PLAYER,
        maxAcceptedVotesPerPlayer: MAX_ACCEPTED_VOTES_PER_PLAYER,
        maxAcceptedReportsPerPlayer: MAX_ACCEPTED_REPORTS_PER_PLAYER,
        maxReceiptFacts: MAX_RECEIPT_FACTS,
        maxSelfAggregateTargets: MAX_SELF_AGGREGATE_TARGETS,
        serverMaxSubmissionWireBytes: SERVER_MAX_WIRE_BYTES,
        serverMaxSubmissionDecodedBytes: SERVER_MAX_DECODED_BYTES,
        evidenceMaxDataBytesExclusive: EVIDENCE_MAX_WIRE_BYTES,
        // S3R4-U-PRIORITY: E と E′ の独立した上限。
        maxPriorityOwnMessages: PRIORITY_OWN_MESSAGES_MAX,
        maxPriorityOtherMessages: PRIORITY_OTHER_MESSAGES_MAX,
        maxPriorityReceipts: PRIORITY_RECEIPTS_MAX,
        // 🔴 J-31（2026-08-08）: **宣言は適用に使う定数そのものから導く。**
        //    以前はここだけ文字列リテラルで、採点エンジンの定数とは無関係だった。
        //    「宣言はしているが適用していない」状態（自動配布経路がまさにそれだった）を
        //    構造的に作れなくする。値は従来と1バイトも変わらない
        //    （`(10n**16n).toString()` = '10000000000000000' / `(10n**19n).toString()` = '10000000000000000000'）。
        minDepositWei: MIN_DEPOSIT_WEI.toString(),     // 0.01 ETH
        // K-S4-002（2026-07-31）: 1人あたりの**合計**上限（製品仕様）。
        // EthLock は「1口あたり」0.01〜10 ETH しか強制しないので、合計はこちらの規則で縛る。
        maxDepositWei: MAX_DEPOSIT_WEI.toString(),     // 10 ETH
        // 請求データ自己完結化（2026-08-01・SPEC §7）: 端数規則を「末尾へ寄せる」から
        // 「全員切り捨て・端数は未配布」へ変更した。順序非依存になり、契約が請求時に
        // 計算する額（自分の amount と分母だけで決まる）と1 wei も違わなくなる。
        // ✅ block-verifier の `pins` に登録済み（config.js）。stages/results.js の逸脱照合ループが
        //    **厳密照合**する（未宣言も逸脱扱い＝maxDepositWei と同じ）。
        //    「宣言を書き換える／落とすだけで規則を無効化できる」穴が塞がっていることは
        //    mutations.mjs の depositor-rounding-pin / depositor-leaf-format-undeclared で実測済み。
        depositorRounding: DEPOSITOR_ROUNDING,
        // デポッターの葉はプレイヤー単位1枚:
        //   key = {blockNum}_{gid}_lock_owners_{uid}_{setHash} / to = 0x0 / amount = lockRewardTotal
        //   setHash = keccak256(abi.encodePacked(uint256[] depositIds ascending))
        // これにより葉が請求データ blob の純関数になる（EthLock を1件も読まずに root を再現できる）。
        depositorLeafFormat: DEPOSITOR_LEAF_FORMAT,
        // K-S5-002（2026-07-31）: 請求データのオンチェーン公開フォーマットの版数。
        // 検証ツールはこの宣言と自分の pin を突き合わせる（ずれたら FAIL＝
        // 「知らない形式のデータをそれっぽく読んで通す」ことを防ぐ）。
        // フォーマットを変えたら lib/claim-data-codec.js の CLAIM_DATA_FORMAT を上げること。
        claimDataFormat: CLAIM_DATA_FORMAT,
        claimDataChunkBytes: CLAIM_DATA_CHUNK_BYTES,
        // Evidence（検閲対策・結果提出オンチェーン記録）: 採点に使った証拠集合の宣言。
        // 検証ツールはコントラクトの resultCount/イベントと照合し、有効イベントの反映漏れ＝検閲を機械検知する
        //
        // 🔴 Q-4（2026-08-08・ユーザー確定）: **目録から `contractAddress` と `precedence` を落とした。**
        //    ・`contractAddress` … `TokenMining.evidence()` は **set-once** で誰でもチェーンから読める
        //      （`TokenMining.evidence` の宣言と TokenMining.setEvidence の `revert EvidenceAlreadySet()`）。
        //      運営が動かせる申告をわざわざ置くと、検証ツールがそれを読んで
        //      「Evidence は使っていません」という**運営の自己申告で検査を飛ばす**経路になる。
        //      検証ツールは常にチェーンから読む（`block-verifier/src/stages/results.js`）。
        //    ・`precedence` … 固定文字列で誰も照合していなかった。
        //
        //    🔴 **残すもの**（`chatWindowMs` / `resultCount` / `adoptedCount`）は
        //    「運営の申告」であることに意味がある。検証ツールがチェーンから再導出した値と
        //    突き合わせる相手なので、落とすと照合そのものが消える。
        //
        //    🔴 `null` を返す枝も無くした。Evidence は必須（`reset.js` は
        //    `EVIDENCE_CONTRACT_ADDRESS` が無ければエラーで止まる＝空にする正当な運用は無い）。
        //    reconcile 記録が無ければ各値は null のまま出て、検証ツール側でチェーン値と
        //    食い違って FAIL する（＝「宣言しなければ検査が消える」を作らない）。
        evidence: await (async () => {
          const rec = await this.storage.get(`evidence_reconciled_block${blockNum}`);
          return {
            resultCount: rec?.resultCount ?? null,
            adoptedCount: rec?.adoptedCount ?? null,
            // 採点に適用した宣言チャット窓（メッセージ/投票/密告の有効タイムスタンプ範囲。
            // Evidence.chatWindow(N) ± clockSkewAllow。検証ツールはチェーンから同一値を再導出して照合）
            chatWindowMs: rec?.chatWindowMs ?? null,
          };
        })(),
        ethereumHeaderRuleVersion: ETH_HEADER_RULE_VERSION,
        ethereumHeaderFork: ETH_HEADER_FORK,
        confirmationBlocks,
      };

      // アンカー対象のハッシュは決定的な core 部分のみから計算する
      // （createdAt等を含めると同一内容の再登録でもハッシュが変わってしまうため）
      const manifestCore = { blockNum, algorithm: 'sha256', rules, files };
      const manifestHash = '0x' + await this.sha256Hex(JSON.stringify(manifestCore));

      const manifest = { ...manifestCore, manifestHash, createdAt: new Date().toISOString() };
      // 🔴 C-1 / ラウンド19 判断不要-3 レッグ (b)（2026-08-08）: `putR2Object` は
      //    例外を握って `false` を返すだけで、旧実装は戻り値を見ずに
      //    `published …` と**嘘のログ**を出し、そのまま `registerResultHash` を送って
      //    `{ok:true}` を返していた。R2 に manifest が無いまま
      //    **存在しない manifest のハッシュだけがオンチェーンに焼かれる**状態になり、
      //    そのブロックは block-verifier で恒久的に Stage C FAIL になる。
      //    （`summary.json` / `game_results.json` は S3-011 で fail-closed 済みで、
      //      manifest だけが取り残されていた。）
      //    → `putR2ObjectOrThrow` にして、**put が成功したときにしか**
      //      `published` と言わない／アンカーしない。
      await this.putR2ObjectOrThrow(`verification/block${blockNum}/manifest.json`, manifest);
      console.log(`[verification] published verification/block${blockNum}/manifest.json hash=${manifestHash}`);

      const registered = await this.registerResultHashOnChain(blockNum, manifestHash);

      // 発見2: アンカー失敗はサイレントにしない。ラウドに警告し、進行状況ストレージへ記録して
      // 運営が気付き・手動再アンカー（POST /anchor-result）できるようにする。
      // 未アンカーのブロックは検証ツールが「resultRegistrationCount==0＝要警戒」として扱う。
      if (!(registered?.submitted)) {
        const reason = registered?.reason || 'unknown';
        console.error(`[verification] ⚠️ ON-CHAIN ANCHOR FAILED block=${blockNum} reason=${reason} — result hash is NOT anchored. Re-run POST /anchor-result?block=${blockNum}. detail=${JSON.stringify(registered)}`);
        try {
          await this.storage.put(`verification_anchor_failed_block${blockNum}`, {
            blockNum, manifestHash, registered, at: new Date().toISOString()
          });
        } catch (_) { /* ストレージ書き込み失敗は無視（ログは既に出ている） */ }
        return {
          ok: false, manifestHash, registered, reason,
          pending: reason === 'admin_freeze' || isAdminTxPending(registered),
          error: `result manifest anchor failed: ${reason}`,
        };
      } else {
        // 成功していれば過去の失敗マーカーを掃除
        try { await this.storage.delete(`verification_anchor_failed_block${blockNum}`); } catch (_) {}
      }

      return { ok: true, manifestHash, registered };
    } catch (e) {
      console.error(`[verification] ⚠️ publishVerificationManifest FAILED for block ${blockNum}:`, e);
      return { ok: false, error: e.message };
    }
  }

  // ============================================================
  // 管理者トランザクション共通（nonce固定 → 送信 → 確定判定 → 置き換え時の再送）
  // ------------------------------------------------------------
  // 2026-07-24 に block2/7 の registerResultHash が消えた（receipt_timeout・チェーン上に痕跡なし・
  // nonce欠番なし＝別txに同一nonceを奪われた置き換え）。原因は「1つの管理者EOAを4経路が
  // 無協調で使う」構造にある:
  //   game-master-DO: registerResultHash / submitMerkleRoot / extendGrace（viem・pending nonce）
  //   collect-DO:     registerHash（毎時・従来は 'latest' nonce ＝ 未確定txを数えず必ず衝突）
  // viem任せの nonce は fallback transport が送信時と別ノードに当たると未確定txを見落とし、
  // 同じ番号を再び返す。そこで
  //   ① nonce は「全RPCの 'pending' 最大値」を1回だけ決めて明示指定する
  //      （1本pinだと遅延RPCの古い値を掴む。最大値なら1本落ちても安全側）
  //   ② receipt が取れない時は pending / replaced / dropped を判定し、消えている時だけ再送する
  // ============================================================

  async recordRosterAnchorFailure(blockNum, reason, { willRetry = false } = {}) {
    const detail = String(reason?.message || reason || 'unknown');
    console.error(`[roster-anchor] block=${blockNum}: ${detail}`);
    await this.storage.put(`roster_anchor_failed_block${blockNum}`, { blockNum, error: detail, at: Date.now() });
    await sendAlertAndRecord(this.env, this.storage, {
      kind: 'roster_anchor',
      subject: `[COINU] block ${blockNum} ライブ名簿アンカー失敗`,
      body: willRetry
        ? `名簿アンカーの確定を待ってチャット開始予約を保留しています。R2名簿再公開とHashStorage登録を自動再試行します。\n\n${detail}`
        : `名簿アンカーの自動復旧は上限回数に達し、parkしました。原因を直した後、API_SECRET付き POST /init-chat-games {"block_num":${blockNum}} で再開してください。登録済みなら同一manifestのtxは出し直さず、開始関門だけ再判定します。\n\n${detail}`,
    }).catch((error) => console.error('[roster-anchor] alert failed:', error?.message || error));
  }

  async scheduleRosterAnchorRetry(blockNum, reason) {
    const attempts = Number(await this.storage.get(`roster_anchor_attempts_block${blockNum}`) || 0) + 1;
    await this.storage.put(`roster_anchor_attempts_block${blockNum}`, attempts);
    if (attempts > PHASE_TASK_MAX_ATTEMPTS) {
      await this.recordRosterAnchorFailure(blockNum, reason, { willRetry: false });
      await this.storage.put(`phase_task_parked:${blockNum}:roster_anchor`, {
        type: 'roster_anchor', blockNum, attempts, parkedAt: Date.now(),
        lastError: String(reason?.message || reason || 'unknown'),
      });
      return { scheduled: false, parked: true, attempts };
    }
    await this.recordRosterAnchorFailure(blockNum, reason, { willRetry: true });
    await this.enqueuePhaseTask({
      type: 'roster_anchor', blockNum, attempts,
      executeAt: Date.now() + Math.min(PHASE_TASK_RETRY_DELAY_MS * Math.max(1, attempts), 30 * 60 * 1000),
    });
    return { scheduled: true, parked: false, attempts };
  }

  async anchorRosterManifestOnChain(blockNum, manifestText, checkedCommitment = null) {
    const observed = (result) => {
      this.deferGroupObservation(blockNum, {
        roster: {
          anchor: this.observationResult(result?.anchored ? 'succeeded' : (result?.pending ? 'pending' : 'failed'), {
            anchored: !!result?.anchored,
            pending: !!result?.pending,
            reason: result?.reason ? this.observationErrorText(result.reason) : null,
            hash: result?.hash || null,
            txHash: result?.txHash || null,
          }),
        },
      });
      return result;
    };
    const contractAddress = this.env.HASH_STORAGE_CONTRACT_ADDRESS;
    const rpcUrls = rpcReadUrlsFromEnv(this.env);
    if (!contractAddress || !this.env.ADMIN_TX_COORDINATOR || rpcUrls.length === 0) {
      return observed({
        anchored: false,
        reason: !contractAddress ? 'hash_storage_not_configured'
          : (!this.env.ADMIN_TX_COORDINATOR ? 'coordinator_binding_missing' : 'no_rpc'),
      });
    }
    try {
      const chainId = resolveEthChainId(this.env);
      const chain = chainId === 1 ? mainnet : defineChain({
        id: chainId, name: `chain-${chainId}`,
        nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
        rpcUrls: { default: { http: rpcUrls } },
      });
      const transport = rpcUrls.length > 1 ? fallback(rpcUrls.map((url) => http(url))) : http(rpcUrls[0]);
      const publicClient = createPublicClient({ chain, transport });
      await this.assertHashStorageBinding(publicClient);
      const key = rosterAnchorKey(blockNum);
      const commitment = checkedCommitment
        || await this.computePublishedRosterCommitment(blockNum, manifestText);
      const hash = commitment.C;
      if (!hash) return observed({ anchored: false, reason: 'canonical_roster_missing' });
      const sent = await this.sendAdminTx({
        intentId: `setRosterManifestHash:${blockNum}:${hash}`,
        operation: 'setRosterManifestHash',
        payload: { blockNum, hash },
      });
      if (!sent.submitted) {
        return observed({
          anchored: false,
          pending: sent.accepted === true && isAdminTxPending(sent),
          reason: sent.reason,
          txHash: sent.txHash,
        });
      }
      const receiptBlockNumber = adminTxReceiptBlockNumber(sent);
      if (receiptBlockNumber != null) {
        try {
          const [registeredBlock, timeline] = await Promise.all([
            publicClient.getBlock({ blockNumber: BigInt(receiptBlockNumber) }),
            this.storage.get(`evidence_tl_snapshot_block${blockNum}`),
          ]);
          const updatedTimestampMs = Number(registeredBlock.timestamp) * 1000;
          const chattingStart = Number.isFinite(Number(timeline?.chatCloseAt))
            ? Number(timeline.chatCloseAt) * 1000 - this.gamePeriodMs
            : null;
          if (chattingStart != null && updatedTimestampMs >= chattingStart) {
            await this.storage.put(`roster_anchor_late_block${blockNum}`, {
              blockNum,
              updatedBlock: String(receiptBlockNumber),
              updatedTimestampMs,
              chattingStart,
              detectedAt: Date.now(),
            });
          }
        } catch (error) {
          console.error(`[roster-anchor] late-anchor monitoring failed block=${blockNum}:`, error?.message || error);
        }
      }
      await this.storage.delete(`roster_anchor_failed_block${blockNum}`);
      await this.storage.delete(`roster_anchor_attempts_block${blockNum}`);
      await this.storage.delete(`phase_task_parked:${blockNum}:roster_anchor`);
      await this.storage.put(`roster_anchor_block${blockNum}`, {
        blockNum, key, hash, txHash: sent.txHash || null, at: Date.now(), alreadyRegistered: !!sent.alreadySubmitted,
      });
      return observed({ anchored: true, key, hash, txHash: sent.txHash || null });
    } catch (error) {
      return observed({
        anchored: false,
        pending: error?.code === 'hash_storage_binding_read_failed',
        reason: error?.code || error?.shortMessage || error?.message || String(error),
      });
    }
  }

  // 署名・nonce割当・receipt/RBF追跡はprivate Service Binding先の単一DOだけが行う。
  async sendAdminTx(intent) {
    return enqueueAdminTx(this.env, intent);
  }

  // 凍結判定専用の読取。送信・再enqueueは絶対に行わない。
  async readAdminTxFreezeStatus(intentId = null) {
    const status = await getAdminTxCoordinatorStatus(this.env);
    return {
      ok: status?.ok === true,
      frozen: status?.ok === true && status?.adminFreeze?.active === true,
      intentId,
      reason: status?.ok === true
        ? (status?.adminFreeze?.reason || null)
        : (status?.reason || 'coordinator_unavailable'),
    };
  }

  async resolveGmRandaoAnchorBlockhashWindow(publicClient, evidenceAddress) {
    try {
      const result = await publicClient.readContract({
        address: evidenceAddress,
        abi: EVIDENCE_BLOCK_HASH_ABI,
        functionName: 'BLOCKHASH_ANCHOR_WINDOW',
      });
      const value = BigInt(result);
      if (value <= 0n || value > BigInt(Math.floor(Number.MAX_SAFE_INTEGER / ETHEREUM_BLOCK_TIME_MS))) {
        throw new Error('Invalid BLOCKHASH_ANCHOR_WINDOW value');
      }
      return value;
    } catch {
      console.warn('[randao-anchor] Evidence BLOCKHASH_ANCHOR_WINDOW read failed; using legacy 256-block window');
      return RANDAO_ANCHOR_BLOCKHASH_WINDOW_DEFAULT;
    }
  }

  gmRandaoAnchorWindow(targetBlock, latestBlock, blockhashWindow = RANDAO_ANCHOR_BLOCKHASH_WINDOW_DEFAULT) {
    const target = BigInt(targetBlock);
    const latest = BigInt(latestBlock);
    const deadlineBlock = target + BigInt(blockhashWindow);
    return {
      deadlineBlock,
      blocksRemaining: deadlineBlock - latest,
    };
  }

  gmRandaoAnchorWindowStatus(anchorWindow, latestBlock) {
    return {
      latest: BigInt(latestBlock).toString(),
      deadlineBlock: anchorWindow.deadlineBlock.toString(),
      blocksRemaining: anchorWindow.blocksRemaining.toString(),
    };
  }

  // game_selection.json が選んだ HashStorage 履歴登録をチェーンで照合し、その登録block +
  // CONFIRMATION_BLOCKS を Evidence の permissionless blockhash cacheへ保存する。
  async anchorRandaoTargetOnChain(blockNum, selectionData) {
    const evidenceAddr = this.env.EVIDENCE_CONTRACT_ADDRESS;
    const hashStorageAddr = this.env.HASH_STORAGE_CONTRACT_ADDRESS;
    if (!evidenceAddr || !hashStorageAddr) {
      return { required: false, anchored: false, reason: 'contracts_not_configured' };
    }
    const rpcUrls = rpcReadUrlsFromEnv(this.env);
    if (rpcUrls.length === 0 || !this.env.ADMIN_TX_COORDINATOR) {
      return {
        required: true, anchored: false,
        reason: rpcUrls.length === 0 ? 'no_rpc' : 'coordinator_binding_missing',
      };
    }

    const chainId = resolveEthChainId(this.env);
    const chain = chainId === 1 ? mainnet : defineChain({
      id: chainId, name: `chain-${chainId}`,
      nativeCurrency: { name: 'Ether', symbol: 'ETH', decimals: 18 },
      rpcUrls: { default: { http: rpcUrls } },
    });
    const transport = rpcUrls.length > 1 ? fallback(rpcUrls.map(u => http(u))) : http(rpcUrls[0]);
    const publicClient = createPublicClient({ chain, transport });
    const evidence = getAddress(evidenceAddr);
    const hashStorage = getAddress(hashStorageAddr);

    const selectedRegistration = selectionData?.hashRegisteredBlock;
    const selectedHash = selectionData?.applicantHash;
    if (!Number.isSafeInteger(selectedRegistration) || selectedRegistration <= 0
      || typeof selectedHash !== 'string' || !/^0x[0-9a-fA-F]{64}$/.test(selectedHash)) {
      return { required: true, anchored: false, reason: 'invalid_selection_registration' };
    }
    try {
      await this.assertHashStorageBinding(publicClient);
    } catch (error) {
      return {
        required: true,
        anchored: false,
        pending: error?.code === 'hash_storage_binding_read_failed',
        reason: error?.code || 'hash_storage_binding_read_failed',
      };
    }
    const registrationBlock = BigInt(selectedRegistration);
    let registrationPresent;
    if (LEGACY_HASH_STORAGE_ALLOWLIST.has(keccak256(stringToHex(hashStorageAddr.toLowerCase())))) {
      const applicant = await publicClient.readContract({
        address: hashStorage, abi: HASH_STORAGE_ABI, functionName: 'applicantHashes', args: [BigInt(blockNum)],
      });
      const latestHash = Array.isArray(applicant) ? applicant[0] : applicant.hash;
      const latestUpdated = Array.isArray(applicant) ? applicant[1] : applicant.updated;
      registrationPresent = latestUpdated === registrationBlock
        && String(latestHash).toLowerCase() === selectedHash.toLowerCase();
    } else {
      registrationPresent = await publicClient.readContract({
        address: hashStorage,
        abi: HASH_STORAGE_ABI,
        functionName: 'isApplicantRegistered',
        args: [BigInt(blockNum), registrationBlock, selectedHash],
      });
    }
    if (!registrationPresent) {
      return { required: true, anchored: false, reason: 'selection_registration_missing' };
    }
    const confirmations = BigInt(this.env.CONFIRMATION_BLOCKS ? parseInt(this.env.CONFIRMATION_BLOCKS) : 64);
    const target = registrationBlock + confirmations;
    let publishedTarget;
    try { publishedTarget = BigInt(selectionData?.targetBlockNum); }
    catch { return { required: true, anchored: false, reason: 'invalid_selection_target' }; }
    if (publishedTarget !== target) {
      return {
        required: true, anchored: false, reason: 'selection_target_mismatch',
        target: target.toString(), publishedTarget: publishedTarget.toString(),
      };
    }

    const readAnchored = () => publicClient.readContract({
      address: evidence, abi: EVIDENCE_BLOCK_HASH_ABI, functionName: 'blockHashOf', args: [target],
    });
    const existing = await readAnchored();
    if (existing !== `0x${'00'.repeat(32)}`) {
      return { required: true, anchored: true, alreadyAnchored: true, target: target.toString(), blockHash: existing };
    }
    const latest = await publicClient.getBlockNumber();
    const blockhashWindow = await this.resolveGmRandaoAnchorBlockhashWindow(publicClient, evidence);
    const anchorWindow = this.gmRandaoAnchorWindow(target, latest, blockhashWindow);
    // blockhash(current) は0。targetの次のblockまで待つ。
    if (latest <= target) {
      return { required: true, anchored: false, reason: 'target_not_reached', target: target.toString(), latest: latest.toString() };
    }
    if (anchorWindow.blocksRemaining < 1n) {
      return {
        required: true, anchored: false, reason: 'blockhash_unavailable', target: target.toString(),
        ...this.gmRandaoAnchorWindowStatus(anchorWindow, latest),
      };
    }

    const deadlineAt = Date.now() + Number(anchorWindow.blocksRemaining) * ETHEREUM_BLOCK_TIME_MS;

    const sent = await this.sendAdminTx({
      intentId: `anchorBlockHash:${target}`,
      operation: 'anchorBlockHash',
      payload: { blockNum, ethBlockNumber: Number(target) },
      deadlineAt,
    });
    const blockHash = sent.blockHash || await readAnchored().catch(() => null);
    const anchored = Boolean(blockHash && blockHash !== `0x${'00'.repeat(32)}`);
    if (anchored) {
      await this.storage.put(`randao_anchor_block${blockNum}`, {
        target: target.toString(), blockHash, txHash: sent.txHash || null, at: Date.now(),
      });
    }
    return {
      required: true, anchored, pending: isAdminTxPending(sent), target: target.toString(), blockHash,
      txHash: sent.txHash || null, reason: anchored ? null : (sent.reason || 'anchor_failed'),
    };
  }

  // HashStorage.registerResultHash(blockNum, hash, signer) をオンチェーン送信（best-effort）
  async registerResultHashOnChain(blockNum, manifestHash) {
    // S3-008／D-05: RPC 一覧は lib/rpc-urls.js が読み取りの順で組む（ETHEREUM_MAINNET_RPC_URLS で本数無制限に追加可）
    const rpcUrls = rpcReadUrlsFromEnv(this.env);
    const contractAddr = this.env.HASH_STORAGE_CONTRACT_ADDRESS;
    if (rpcUrls.length === 0 || !this.env.ADMIN_TX_COORDINATOR || !contractAddr) {
      const missing = [];
      if (rpcUrls.length === 0) missing.push('ETHEREUM_MAINNET_RPC_URL');
      if (!this.env.ADMIN_TX_COORDINATOR) missing.push('ADMIN_TX_COORDINATOR');
      if (!contractAddr) missing.push('HASH_STORAGE_CONTRACT_ADDRESS');
      console.warn(`[verification] on-chain anchor skipped: missing env ${missing.join(', ')}`);
      return { submitted: false, reason: 'missing_config', missing };
    }

    try {
      const address = getAddress(contractAddr);
      await this.assertHashStorageBinding();
      const sent = await this.sendAdminTx({
        intentId: `registerResultHash:${blockNum}:${manifestHash.toLowerCase()}`,
        operation: 'registerResultHash',
        payload: { blockNum, hash: manifestHash },
      });
      if (sent.submitted) {
        if (sent.alreadySubmitted) return sent;
        console.log(`[verification] registerResultHash confirmed block=${blockNum} tx=${sent.txHash} attempts=${sent.attempts}`);
        return {
          submitted: true, txHash: sent.txHash, hash: manifestHash, from: this.env.SIGNER_ADDRESS || null, contract: address,
          minedBlock: adminTxReceiptBlockNumber(sent), attempts: sent.attempts,
        };
      }
      console.error(`[verification] registerResultHash NOT confirmed block=${blockNum} reason=${sent.reason} tx=${sent.txHash} attempts=${sent.attempts}`);
      return {
        submitted: false, accepted: sent.accepted === true,
        status: sent.status || null, reason: sent.reason,
        intentId: sent.intentId || null, operation: sent.operation || 'registerResultHash',
        deadlineAt: sent.deadlineAt ?? null,
        retryInMs: isAdminTxPending(sent) ? ADMIN_TX_PENDING_RETRY_MS : null,
        txHash: sent.txHash, hash: manifestHash, contract: address, attempts: sent.attempts,
      };
    } catch (e) {
      console.error(`[verification] registerResultHashOnChain failed block=${blockNum}: ${e.shortMessage || e.message}`);
      return { submitted: false, reason: e?.code || 'tx_error', error: e.shortMessage || e.message };
    }
  }

  // HashStorage.resultHashes(blockNumber) の読み取り（P-2026-0816 のアンカー検証用）。
  // 「読めなかった」と「まだ登録されていない（updated===0）」を**呼び出し側が区別できる**よう、
  // 前者は throw・後者は updated:0 を返す。
  //   ・throw  → 照合不能 ＝ グループ分けを止めて再試行（S3-008 と同じ扱い）
  //   ・updated:0 → 前ブロックが未アンカー ＝ 恒久的な不備（POST /anchor-result で解消）
  async readResultHashOnChain(blockNumber, atBlock = null) {
    const contractAddr = this.env.HASH_STORAGE_CONTRACT_ADDRESS;
    if (!contractAddr) throw new Error('HASH_STORAGE_CONTRACT_ADDRESS is not configured');
    const publicClient = this.createReadOnlyClient();
    if (!publicClient) throw new Error(`no RPC endpoint configured (${RPC_LIST_ENV})`);
    await this.assertHashStorageBinding(publicClient);
    const res = await publicClient.readContract({
      address: getAddress(contractAddr), abi: HASH_STORAGE_ABI,
      functionName: 'resultHashes', args: [BigInt(blockNumber)],
      ...(atBlock == null ? {} : { blockNumber: BigInt(atBlock) }),
    });
    const hash = Array.isArray(res) ? res[0] : (res?.hash ?? null);
    const updated = Array.isArray(res) ? res[1] : (res?.updated ?? 0n);
    return { hash, updated: Number(updated), signer: Array.isArray(res) ? res[2] : (res?.signer ?? null) };
  }

  // ============================================================
  // Merkle ツリー: 生成 → R2 公開 → コントラクトに root 提出
  // ============================================================

  summaryTotalPointsForMerkle(blockNum, summary, where = '[merkle]') {
    const parsePoints = (value, label) => {
      if (typeof value === 'number') {
        if (!Number.isSafeInteger(value) || value < 0) {
          throw new Error(`${where} block ${blockNum}: ${label} is not a non-negative safe integer`);
        }
        return BigInt(value);
      }
      if (typeof value === 'string' && /^(0|[1-9]\d*)$/.test(value)) return BigInt(value);
      throw new Error(`${where} block ${blockNum}: ${label} is missing or non-canonical`);
    };

    let total = 0n;
    for (const group of (Array.isArray(summary?.groups) ? summary.groups : [])) {
      if (group?.total_points != null) {
        total += parsePoints(group.total_points, `group ${group.group_id ?? '?'} total_points`);
        continue;
      }
      const members = Array.isArray(group?.members) ? group.members : [];
      for (const member of members) {
        total += parsePoints(
          member?.total_points,
          `group ${group.group_id ?? '?'} member ${member?.userId ?? '?'} total_points`,
        );
      }
    }
    return total;
  }

  // B10-06: 正ポイントがあるブロックを空ツリー標識ルートとして確定させない。
  // 現行パラメータでは到達不能でも、将来の低報酬化や報酬フィールド回帰に対する最終ガードになる。
  assertClaimEntriesForPositivePoints(blockNum, summary, leafCount, {
    expectedTotalPoints = null,
    where = '[merkle]',
  } = {}) {
    const totalPoints = expectedTotalPoints == null
      ? this.summaryTotalPointsForMerkle(blockNum, summary, where)
      : (() => {
          if (typeof expectedTotalPoints === 'number') {
            if (!Number.isSafeInteger(expectedTotalPoints) || expectedTotalPoints < 0) {
              throw new Error(`${where} block ${blockNum}: expected totalPoints is not a non-negative safe integer`);
            }
            return BigInt(expectedTotalPoints);
          }
          if (typeof expectedTotalPoints === 'string' && /^(0|[1-9]\d*)$/.test(expectedTotalPoints)) {
            return BigInt(expectedTotalPoints);
          }
          throw new Error(`${where} block ${blockNum}: expected totalPoints is missing or non-canonical`);
        })();
    if (totalPoints > 0n && Number(leafCount) === 0) {
      throw new Error(
        `${where} block ${blockNum}: totalPoints=${totalPoints} but the Merkle tree has zero claimable leaves `
        + '— refusing to submit an empty-tree sentinel for a positive allocation',
      );
    }
    return totalPoints;
  }

  // 公開データ summary.json から claim エントリーを収集 (= ツリーの入力を公表データに一致させる)
  //   players:    groups[].members[] → {N}_{gid}_player_{uid},                to=address, amount=playerShare
  //   Lock Owners: **プレイヤー単位1枚** → {N}_{gid}_lock_owners_{uid}_{setHash}, to=0x0, amount=lockRewardTotal
  //   報酬 0 / 不正アドレスのプレイヤーは丸ごと除外 (コントラクトが amount>0 を要求するため)
  //
  // ★ 実装は lib/claim-data-codec.js の claimEntriesFromSummary **1本だけ**。
  //   blob 経路（claimEntriesFromClaimData）と同じ claimEntriesForMember を通るので、
  //   「片方だけ直して root が食い違う」という最頻の事故が構造的に起きない。
  //   検証ツール（block-verifier / chatgame-tools）は同じファイルを vendor しているので
  //   自動的に同じ規則になる。
  collectClaimEntriesFromSummary(blockNum, summary) {
    const stats = {};
    const entries = claimEntriesFromSummary(blockNum, summary, stats);
    if (stats.skipped > 0) {
      console.log(`[merkle] block ${blockNum}: excluded ${stats.skipped} player(s) (zero reward / invalid address)`);
    }
    return entries;
  }

  // entries から merkle_tree.json 形式のツリーを構築 (test.js メニュー12 と同形式)
  // entries が0件（全員失格等で配分なし）でも決定的な非ゼロ標識ルートを持つ空ツリーを返す。
  // コントラクトは root=0 を拒否し、blockStates.merkleRoot=0 は「未提出」と区別できないため、
  // 空でも提出して「配分ゼロで確定」をオンチェーンで判別可能にする。
  // 標識ルートはどの葉（leaf=keccak256(keccak256(abi.encode(...)))）の値にもならないため請求は成立しない。
  // G1b是正（2026-07-18）: proof埋め込み（items・O(N log N)）を廃止し、O(N)のin-memory構造
  // （leavesMeta＋layers）を返す。R2への保存は publishMerkleTree が「メタのみの
  // merkle/block_{N}.json＋leaves/levels/indexチャンク」に分割し、proofファイルは
  // proofsステージがclaim-worker並列で事前生成する。
  // root計算方式（leaf式・sorted-pairハッシュ・2のべき乗までの末尾複製パディング）は完全に不変。
  buildMerkleTree(blockNum, entries) {
    if (entries.length === 0) {
      const root = keccak256(stringToHex(`bitcoinu:empty-merkle:${blockNum}`));
      return { blockNum, root, leafCount: 0, proofDepth: 0, totalAmount: '0', leavesMeta: [], layers: [] };
    }
    const leaves = [];
    const meta = [];
    let total = 0n;
    const seenKeys = new Set();
    for (const e of entries) {
      // 防御assert②: key の重複禁止。重複keyは2つのleafを生成する一方で items は
      // 後勝ち1件になり、ツリー合計の水増し・cap消費のズレを生む（正常系では一意）。
      if (seenKeys.has(e.key)) {
        throw new Error(`[merkle] block ${blockNum}: duplicate claim key "${e.key}" — aborting tree build`);
      }
      seenKeys.add(e.key);
      const { claimId, leaf } = merkleLeafAndClaimId(blockNum, e.key, e.to, e.amount);
      leaves.push(leaf);
      // ⚠️ claimId（＝ usedClaimIds のキー）を公開してよいのは **プレイヤー葉だけ**。
      //    デポッター葉の usedClaimIds キーは keccak256(abi.encode(blockNum, myDepositId))
      //    ＝ **デポジット単位**（TokenMining.claimLockReward）なので、葉ごとに1つの claimId は存在しない。
      //    ここで leaf 由来の値を出すと「請求済み判定に使える値」と誤用される（R2 に公開されるため）。
      meta.push({ ...e, claimId: isDepositorLeafKey(e.key) ? null : claimId, leaf });
      total += BigInt(e.amount);
    }
    // 防御assert①: 配分合計 ≤ ブロック報酬。超過したrootを提出すると先着後の請求が
    // "Exceeds block reward" でrevertし資金ロックになるため、提出せずここで止める。
    const blockRewardWei = getBlockRewardWei(blockNum);
    if (total > blockRewardWei) {
      throw new Error(`[merkle] block ${blockNum}: total assigned ${total} exceeds block reward ${blockRewardWei} — aborting tree build`);
    }
    const layers = buildMerkleLayers(leaves);
    const root = merkleRootOf(layers);

    return {
      blockNum, root,
      leafCount: meta.length,
      proofDepth: layers.length - 1,
      totalAmount: total.toString(),
      // G1b: 葉のメタ（index順）。proofは持たない＝O(N)。
      // Lock Owner 葉には請求引数（gid / uid / lockIds）を添える。TokenMining.claimLockReward は
      // **集合そのもの**を calldata で要求するが setHash は一方向なので鍵から復元できない。
      // ここに載せておかないと、運営以外は proof を持っていても請求引数を組み立てられない。
      leavesMeta: meta.map((m, i) => ({
        key: m.key, index: i, to: m.to, amount: m.amount, claimId: m.claimId, leaf: m.leaf,
        ...(m.depositIds ? { gid: m.gid, uid: m.uid, depositIds: m.depositIds } : {}),
      })),
      // パディング込みの全レベル（proof計算＝純粋なインデックス演算の前提）
      layers,
    };
  }

  // G1b: ツリーのR2分割保存。levelsはパディング込みで保存する（葉indexから
  // 「レベルLの位置 = i>>L・兄弟 = 位置^1」の算術だけで必要ページが決まる）。
  // 最上段（root層）はproofに不要なので保存しない。約91ファイル・冪等上書き。
  async publishMerkleArtifacts(blockNum, tree) {
    if (!tree.leafCount) return { files: 0 };
    const puts = [];
    for (let c = 0; c * MERKLE_LEAF_CHUNK < tree.leavesMeta.length; c++) {
      const from = c * MERKLE_LEAF_CHUNK;
      puts.push([`merkle/block_${blockNum}/leaves/${c}.json`,
        { blockNum, chunk: c, from, entries: tree.leavesMeta.slice(from, from + MERKLE_LEAF_CHUNK) }]);
    }
    for (let L = 0; L < tree.layers.length - 1; L++) {
      const layer = tree.layers[L];
      for (let s = 0; s * MERKLE_LEVEL_SEG < layer.length; s++) {
        const from = s * MERKLE_LEVEL_SEG;
        puts.push([`merkle/block_${blockNum}/levels/${L}/${s}.json`,
          { blockNum, level: L, seg: s, from, hashes: layer.slice(from, from + MERKLE_LEVEL_SEG) }]);
      }
    }
    const shards = Array.from({ length: MERKLE_INDEX_FANOUT }, () => ({}));
    for (const m of tree.leavesMeta) {
      shards[parseInt(merkleIndexShardOf(m.key), 16)][m.key] = m.index;
    }
    for (let h = 0; h < MERKLE_INDEX_FANOUT; h++) {
      puts.push([`merkle/block_${blockNum}/index/${h.toString(16)}.json`,
        { blockNum, shard: h.toString(16), keys: shards[h] }]);
    }
    for (let i = 0; i < puts.length; i += 8) {
      // 🔴 ラウンド19 判断不要-3 step2 の棚卸し: 葉・レベル・索引は proof 生成
      //    （claim-worker /build-proofs）の唯一の入力。欠けたまま前進すると
      //    proofs 段が「書けたのに読めない」で詰まる。put 失敗はここで throw する。
      await Promise.all(puts.slice(i, i + 8).map(([k, v]) => this.putR2ObjectOrThrow(k, v)));
    }
    console.log(`[merkle] block ${blockNum}: published ${puts.length} artifact file(s) (leaves/levels/index)`);
    return { files: puts.length };
  }

  // 公開データ summary.json を入力に: ツリー生成 → R2 公開 (merkle/block_{N}.json) → コントラクトに root 提出。
  // 「公表データ == ツリーの入力」にすることで第三者が summary.json から root を再計算・検証できる。
  // 失敗しても結果保存フローを壊さない (status を記録し /submit-merkle-root で再試行可能)。
  // ツリー構築＋R2公開＋オンチェーン提出を一括で行う（autoDistribute/noGame の同期経路と
  // /submit-merkle-root 手動経路が使う）。チャンク化 calc パイプラインでは、この2つを
  // publishMerkleTree（merkle 段階）と submitMerkleRootForBlock（最終 adminCommit 段階）に
  // 分割して呼ぶ ── 提出を最後に回すことで proof 欠落のまま検証/請求期間へ入るのを防ぐ。
  // ツリー構築＋R2公開のみ（オンチェーン提出はしない）。merkle_status に leafCount を記録して
  // proofs 段階に引き渡す。初回は submit=null、同じ root の再公開では既存の提出結果を保持する。
  //
  // S3-010（2026-07-29）: 「公開と提出をまとめて行う publishAndSubmitMerkle」は**削除した**。
  // root 提出は検証期間・請求期間を開始させるので、常に全工程の最後（唯一のコミット点）に
  // 置く必要がある。まとめて呼べるヘルパーがあると、自動配布・0名ブロック・手動復旧のように
  // 通常パイプラインを通らない経路で「提出が先」に戻りやすい。
  async publishMerkleTree(blockNum, summary, { expectedTotalPoints = null } = {}) {
    try {
      if (!summary || !Array.isArray(summary.groups)) {
        console.warn(`[merkle] block ${blockNum}: no summary.json available, skip tree`);
        return { ok: false, reason: 'no_summary' };
      }
      const entries = this.collectClaimEntriesFromSummary(blockNum, summary);
      this.assertClaimEntriesForPositivePoints(blockNum, summary, entries.length, {
        expectedTotalPoints,
        where: '[merkle]',
      });
      summary = null; // G1b（メモリ）: 葉抽出後はsummaryを手放す（最大規模で128MB接近を避ける）
      if (entries.length === 0) {
        // 全員失格などで配分が1件も無いブロックもスキップしない: 空ツリーの標識ルートを
        // （adminCommit 段階で）提出し、「配分ゼロでゲーム終了（確定）」を root未提出（未確定）と区別できるようにする。
        console.warn(`[merkle] block ${blockNum}: no claimable entries — empty-tree sentinel root will be submitted at adminCommit`);
      }

      const tree = this.buildMerkleTree(blockNum, entries);

      // R2 公開（G1b: メタのみ＝数百B。葉・レベル・索引は別ファイルに分割）
      const treeMeta = {
        blockNum: tree.blockNum, root: tree.root, leafCount: tree.leafCount,
        proofDepth: tree.proofDepth, totalAmount: tree.totalAmount,
        format: 'v2',
        leafChunkSize: MERKLE_LEAF_CHUNK, levelSegSize: MERKLE_LEVEL_SEG, indexFanout: MERKLE_INDEX_FANOUT,
      };
      // 🔴 ラウンド19 判断不要-3 step2 の棚卸し（2026-08-08）: `merkle/block_{N}.json` は
      //    manifest の `artifactKeys` に載る**権威的な公開アーティファクト**。
      //    `putR2Object` のままだと put 失敗が `false` に潰れ、`{ok:true}` を返した木の
      //    メタが R2 に無いまま manifest が `files["merkle/block_{N}.json"]=null` を焼く。
      //    throw は publishMerkleTree の catch が `{ok:false}` に変え、
      //    `calcMerkleUnit` の新しい ok 検査がユニットリトライへ載せる。
      await this.putR2ObjectOrThrow(`merkle/block_${blockNum}.json`, treeMeta);
      await this.publishMerkleArtifacts(blockNum, tree);
      console.log(`[merkle] published merkle/block_${blockNum}.json root=${tree.root} leaves=${tree.leafCount} total=${tree.totalAmount}`);

      let status = {
        blockNum, root: tree.root, leafCount: tree.leafCount,
        totalAmount: tree.totalAmount, publishedAt: new Date().toISOString(), submit: null,
      };
      let previous = null;
      try { previous = await this.storage.get(`merkle_status_${blockNum}`); } catch {}
      const sameRoot = previous?.root && String(previous.root).toLowerCase() === String(tree.root).toLowerCase();
      if (sameRoot) {
        status = {
          ...status,
          submit: previous.submit ?? null,
          ...(previous.submittedAt != null ? { submittedAt: previous.submittedAt } : {}),
        };
      }
      try { await this.storage.put(`merkle_status_${blockNum}`, status); } catch {}
      try { await this.putR2Object(`merkle/block_${blockNum}_status.json`, status); } catch {}

      return { ok: true, root: tree.root, leafCount: tree.leafCount };
    } catch (e) {
      console.error(`[merkle] publishMerkleTree failed for block ${blockNum}:`, e);
      try {
        const previous = (await this.storage.get(`merkle_status_${blockNum}`)) || { blockNum };
        const failedStatus = {
          blockNum,
          error: e.message,
          failedAt: new Date().toISOString(),
          ...(previous.submit != null ? { submit: previous.submit, stale: true } : {}),
          ...(previous.submittedAt != null ? { submittedAt: previous.submittedAt } : {}),
        };
        await this.storage.put(`merkle_status_${blockNum}`, failedStatus);
      } catch {}
      return {
        ok: false,
        error: e.message,
        reason: /zero claimable leaves/.test(String(e.message))
          ? 'positive_points_without_claim_entries'
          : 'merkle_publish_failed',
      };
    }
  }

  // R2公開済みツリーの root をオンチェーン提出（best-effort）＋claim-timing 公開＋merkle_status.submit 追記。
  // これが成功して初めてブロックが検証/請求期間へ遷移する（calc では proofs/zkProof 完了後の最終段階で呼ぶ）。
  // ============================================================
  // K-S5-002: ガス価格ゲート
  //
  // 「上限を超えていたら提出しない・30分ごとに再試行・初回だけ LINE 通知・手動で強制可」。
  // 初回提出にも closeAt + 90日 - verificationPeriod の期限がある。待機は次ブロックを
  // 止めないが、この期限を越えると当該ブロックの root は恒久的に提出できなくなる。
  // 自動 force 昇格は費用判断なので行わず、残り日数を progress / blocker / 通知へ出す。
  // ============================================================

  async getVerificationPeriodSec(publicClient, address) {
    const contractAddress = String(address || this.env.TOKEN_MINING_CONTRACT_ADDRESS || '').toLowerCase();
    if (!contractAddress) return null;
    if (this._verificationPeriodCache?.address === contractAddress) {
      return this._verificationPeriodCache.seconds;
    }

    try {
      const cached = await this.storage.get(VERIFICATION_PERIOD_CACHE_KEY);
      if (cached?.address === contractAddress
        && Number.isSafeInteger(Number(cached.seconds)) && Number(cached.seconds) > 0) {
        this._verificationPeriodCache = { address: contractAddress, seconds: Number(cached.seconds) };
        return this._verificationPeriodCache.seconds;
      }
    } catch (error) {
      console.warn(`[merkle] verificationPeriod cache read failed: ${error.message}`);
    }
    if (!publicClient) return null;

    try {
      const raw = await publicClient.readContract({
        address: getAddress(contractAddress), abi: TOKEN_MINING_ABI, functionName: 'verificationPeriod',
      });
      const seconds = Number(raw);
      if (!Number.isSafeInteger(seconds) || seconds <= 0) {
        throw new Error(`invalid on-chain verificationPeriod: ${raw}`);
      }
      this._verificationPeriodCache = { address: contractAddress, seconds };
      try {
        await this.storage.put(VERIFICATION_PERIOD_CACHE_KEY, {
          address: contractAddress, seconds, cachedAt: Date.now(),
        });
      } catch (error) {
        console.warn(`[merkle] verificationPeriod cache write failed: ${error.message}`);
      }
      return seconds;
    } catch (error) {
      console.warn(`[merkle] verificationPeriod read failed: ${error.shortMessage || error.message}`);
      return null;
    }
  }

  async getRootSubmissionDeadline(blockNum, publicClient = null, address = null, nowMs = Date.now()) {
    let closeAtMs = null;
    let source = null;
    try {
      const summary = await this.getR2Object(`games/block${blockNum}/summary.json`);
      const summaryCloseAt = Number(summary?.timeline?.closeAt);
      if (summary?.timeline?.closeAt != null
        && Number.isSafeInteger(summaryCloseAt) && summaryCloseAt >= 0) {
        closeAtMs = summaryCloseAt;
        source = 'summary_timeline';
      }
    } catch (error) {
      console.warn(`[merkle] block ${blockNum} summary closeAt read failed: ${error.message}`);
    }

    if (closeAtMs === null) {
      try {
        const timing = await this.getR2Object(`games/block${blockNum}/claim-timing.json`);
        // claim-timing.submitEnd は root の提出成功時刻であって Evidence closeAt ではない。
        // 符号だけでなく基準時刻も違うため、将来 resultCloseAt を明示した形式だけを使う。
        const timingCloseAt = Number(timing?.resultCloseAt);
        if (timing?.resultCloseAt != null
          && Number.isSafeInteger(timingCloseAt) && timingCloseAt >= 0) {
          closeAtMs = timingCloseAt;
          source = 'claim_timing_result_close';
        }
      } catch (error) {
        console.warn(`[merkle] block ${blockNum} claim timing read failed: ${error.message}`);
      }
    }
    if (closeAtMs === null) return null;

    const verificationPeriodSec = await this.getVerificationPeriodSec(publicClient, address);
    if (verificationPeriodSec === null) return null;
    return {
      ...calculateRootSubmissionDeadline(closeAtMs, verificationPeriodSec, nowMs),
      closeAt: closeAtMs,
      verificationPeriodSec,
      source,
    };
  }

  /// 実効上限（gwei）。優先順: DO storage の上書き ＞ env ＞ 既定 5。
  async getMaxGasPriceGwei() {
    const override = await this.storage.get(MAX_GAS_PRICE_OVERRIDE_KEY);
    if (override && Number.isFinite(Number(override.gwei)) && Number(override.gwei) > 0) {
      return { gwei: Number(override.gwei), source: 'override', setAt: override.setAt || null };
    }
    const fromEnv = this.env.MAX_GAS_PRICE_GWEI ? Number(this.env.MAX_GAS_PRICE_GWEI) : NaN;
    if (Number.isFinite(fromEnv) && fromEnv > 0) return { gwei: fromEnv, source: 'env', setAt: null };
    return { gwei: DEFAULT_MAX_GAS_PRICE_GWEI, source: 'default', setAt: null };
  }

  async setMaxGasPriceGwei(gwei) {
    const v = Number(gwei);
    if (!Number.isFinite(v) || v <= 0) throw new Error('MAX_GAS_PRICE_GWEI must be a positive number');
    await this.storage.put(MAX_GAS_PRICE_OVERRIDE_KEY, { gwei: v, setAt: Date.now() });
    return this.getMaxGasPriceGwei();
  }

  async clearMaxGasPriceOverride() {
    await this.storage.delete(MAX_GAS_PRICE_OVERRIDE_KEY);
    return this.getMaxGasPriceGwei();
  }

  /// 現在の実効ガス価格（gwei）。EIP-1559 下では gasPrice 単体が曖昧なので
  /// 「最新ブロックの baseFeePerGas ＋ 優先手数料」で見る。
  async readGasPriceGwei(publicClient) {
    const block = await publicClient.getBlock();
    const baseFee = block.baseFeePerGas ?? 0n;
    let priority = 0n;
    try {
      priority = await publicClient.estimateMaxPriorityFeePerGas();
    } catch { /* 対応していない RPC もある。base fee だけで判断する */ }
    const wei = baseFee + priority;
    return { gwei: Number(wei) / 1e9, baseFeeGwei: Number(baseFee) / 1e9, priorityGwei: Number(priority) / 1e9 };
  }

  /// 提出してよいか。{ ok, current, limit } を返す。読めなかったときは通す
  /// （ガス価格が読めないことを理由に集計を止めない＝ここは費用の話であって正当性の話ではない）。
  async checkGasPriceGate(publicClient, { force = false } = {}) {
    const limit = await this.getMaxGasPriceGwei();
    if (force) return { ok: true, forced: true, limit };
    let current;
    try {
      current = await this.readGasPriceGwei(publicClient);
    } catch (e) {
      console.warn(`[gas] gas price read failed (${e.shortMessage || e.message}) — proceeding`);
      return { ok: true, unreadable: true, limit };
    }
    return { ok: current.gwei <= limit.gwei, current, limit };
  }

  /// ガス価格待ちの記録＋通知（トラブル1件につき1通・S3-008 の決定を踏襲）。
  async noteGasWait(blockNum, gate, publicClient = null, address = null) {
    const key = `gas_wait_block${blockNum}`;
    const prev = await this.storage.get(key) || {};
    const now = Date.now();
    let deadline = null;
    if (prev.deadlineAt != null && Number.isSafeInteger(Number(prev.deadlineAt))) {
      deadline = {
        deadlineAt: Number(prev.deadlineAt),
        deadlineDaysLeft: (Number(prev.deadlineAt) - now) / DAY_MS,
        closeAt: prev.closeAt ?? null,
        verificationPeriodSec: prev.verificationPeriodSec ?? null,
        source: prev.deadlineSource ?? null,
      };
    } else {
      try {
        deadline = await this.getRootSubmissionDeadline(blockNum, publicClient, address, now);
      } catch (error) {
        // 期限の可視化失敗を理由に、既存のガス待ち・自動再試行まで止めない。
        console.warn(`[merkle] block ${blockNum} root submission deadline unavailable: ${error.message}`);
      }
    }
    const state = {
      blockNum,
      firstSeenAt: prev.firstSeenAt || now,
      lastSeenAt: now,
      attempts: (prev.attempts || 0) + 1,
      currentGwei: gate.current?.gwei ?? null,
      limitGwei: gate.limit.gwei,
      limitSource: gate.limit.source,
      notifiedAt: prev.notifiedAt || null,
      deadlineAt: deadline?.deadlineAt ?? null,
      deadlineDaysLeft: deadline?.deadlineDaysLeft ?? null,
      deadlineSource: deadline?.source ?? null,
      closeAt: deadline?.closeAt ?? null,
      verificationPeriodSec: deadline?.verificationPeriodSec ?? null,
    };
    await this.storage.put(key, state);
    if (prev.notifiedAt) return state; // 送信成功済みなら2回目以降は通知しない

    const deadlineAtText = state.deadlineAt === null
      ? '不明（R2 timeline または verificationPeriod を確認してください）'
      : new Date(state.deadlineAt).toISOString();
    const deadlineDaysText = Number.isFinite(state.deadlineDaysLeft)
      ? `${state.deadlineDaysLeft.toFixed(2)} 日`
      : '不明';
    const subject = `[COINU] block ${blockNum} ガス価格が上限を超えています（root 提出を待機中）`;
    const body = [
      `ブロック ${blockNum} の Merkle root 提出を、ガス価格が下がるまで待機しています。`,
      ``,
      `現在のガス価格 : 約 ${state.currentGwei?.toFixed(2)} gwei`,
      `設定した上限   : ${state.limitGwei} gwei（${state.limitSource}）`,
      `再試行         : ${GameMasterDO.TIMELINE_RETRY_MS / 60000} 分ごとに自動`,
      `root 提出期限  : ${deadlineAtText}`,
      `期限まで残り   : ${deadlineDaysText}`,
      `メール         : **このトラブルについての通知はこの1通だけです**（復旧時の通知はありません）`,
      ``,
      `⚠️ submitMerkleRoot の初回提出にも期限があります。期限を越えると、`,
      `   このブロックの root は恒久的に提出できず、報酬を請求できなくなります。`,
      `   summary.json は公開済みなので次のブロックは進みますが、期限前の提出確認が必要です。`,
      ``,
      `対処（どれでも可）:`,
      `  ・自動再試行を待つ → ガス価格が ${state.limitGwei} gwei 以下に下がれば提出（期限前に要確認）`,
      `  ・上限を変える → test.js のメニューで変更（再デプロイ不要・即時反映）`,
      `  ・今すぐ出す   → POST /submit-merkle-root {"block_num":${blockNum},"force":true}`,
      ``,
      `状況確認: GET /calc-status（blockers に gas_price_wait が出ます）`,
    ].join('\n');
    const result = await sendAlertAndRecord(this.env, this.storage, { subject, body, kind: 'gas_price_wait' });
    if (result.sent) {
      state.notifiedAt = Date.now();
      await this.storage.put(key, state);
    }
    return state;
  }

  // 待機開始から3日経過したガス価格待ちだけを自動解除する。手動 force と同じく
  // 費用ゲートだけを通し、時刻・proof・claim data・simulateContract 等の安全条件は残す。
  async noteGasAutoForce(blockNum, gate, wait) {
    const key = `gas_auto_force_block${blockNum}`;
    const prev = await this.storage.get(key) || {};
    const now = Date.now();
    const state = {
      blockNum,
      firstSeenAt: Number(wait.firstSeenAt),
      triggeredAt: prev.triggeredAt || now,
      lastAttemptAt: now,
      waitedMs: Math.max(0, now - Number(wait.firstSeenAt)),
      thresholdMs: GAS_AUTO_FORCE_AFTER_MS,
      currentGwei: gate.current?.gwei ?? null,
      limitGwei: gate.limit?.gwei ?? null,
      limitSource: gate.limit?.source ?? null,
      attempts: (prev.attempts || 0) + 1,
      notifiedAt: prev.notifiedAt || null,
      notification: prev.notification || null,
    };
    await this.storage.put(key, state);

    if (!prev.notifiedAt) {
      const subject = `[COINU] block ${blockNum} ガス価格待機3日到達 — 自動forceを実行`;
      const body = [
        `ブロック ${blockNum} はガス価格上限超過の待機開始から3日以上経過したため、自動 force で再実行します。`,
        `待機開始       : ${new Date(state.firstSeenAt).toISOString()}`,
        `自動force時刻  : ${new Date(state.triggeredAt).toISOString()}`,
        `現在のガス価格 : ${state.currentGwei == null ? '不明' : `約 ${state.currentGwei.toFixed(2)} gwei`}`,
        `設定した上限   : ${state.limitGwei} gwei（${state.limitSource}）`,
        `解除対象       : ガス価格ゲートのみ`,
        `維持する検査   : 時刻、root/proof、claim data、eth_call事前検査、receipt確認`,
        `状況確認       : GET /calc-status または monitor`,
      ].join('\n');
      const notification = await sendAlertAndRecord(this.env, this.storage, {
        subject,
        body,
        kind: 'gas_price_auto_force',
      });
      state.notification = { ...notification, at: Date.now() };
      if (notification.sent) state.notifiedAt = Date.now();
      await this.storage.put(key, state);
    }
    return state;
  }

  /// 提出できたら待機記録を消す（次に詰まったときにまた1通だけ届くように）。
  async clearGasWait(blockNum) {
    try { await this.storage.delete(`gas_wait_block${blockNum}`); } catch { /* 無害化 */ }
  }

  // ============================================================
  // K-S5-002: 請求データのオンチェーン公開
  // ============================================================

  /// summary.json → 案C エンコード → 96KiB 分割。決定論的（同じ summary なら同じバイト列）。
  /// ⚠️ bitcoinu-claimdata/3 で **gzip をやめた**（ZKP Stage 1 の回路から DEFLATE を消すため。
  ///    圧縮率が 6.8〜12.8% しかなく、解凍が回路の主コストになって逆転するのが理由。
  ///    `docs/ZKP_ROADMAP.md` §6 / `docs/ZKP_HANDOFF_FROM_CLAIM_LEAF.md` §3）。
  async buildClaimDataChunks(blockNum, summary) {
    const { bytes, stats } = encodeClaimData(blockNum, summary);
    const chunks = splitChunks(bytes, CLAIM_DATA_CHUNK_BYTES);
    return { chunks, stats: { ...stats, onchainBytes: bytes.length, chunkCount: chunks.length } };
  }

  /// 未送信のチャンクだけを publishClaimData で送る（冪等）。
  /// 契約はチャンクを 0 から順に受け取るので、received を見て続きから送る。
  async publishClaimDataOnChain(blockNum, chunks, ctx) {
    const { address, publicClient } = ctx;
    const total = chunks.length;

    const readRef = async () => {
      const r = await publicClient.readContract({
        address, abi: TOKEN_MINING_ABI, functionName: 'claimDataOf', args: [BigInt(blockNum)],
      });
      const ref = Array.isArray(r)
        ? { dataHash: r[0], chunks: Number(r[1]), received: Number(r[2]) }
        : { dataHash: r.dataHash, chunks: Number(r.chunks), received: Number(r.received) };
      if (typeof ref.dataHash !== 'string' || !/^0x[0-9a-fA-F]{64}$/.test(ref.dataHash)
        || !Number.isSafeInteger(ref.chunks) || ref.chunks < 0
        || !Number.isSafeInteger(ref.received) || ref.received < 0 || ref.received > ref.chunks) {
        throw new Error('malformed claimDataOf response');
      }
      return ref;
    };

    // 🔴 P-2026-0838（2026-08-08・ラウンド19 判断不要-6）: **内容で照合する。**
    //    旧実装は `let start = (ref.chunks === total) ? ref.received : 0;` で、
    //    コメントは「総数が変わった＝再計算でデータが変わった場合は chunk 0 から作り直す」と
    //    書いていたが、**総数はデータが変わったことの代理指標として成立していない**。
    //    読んだ `ref.dataHash` は一度も比較していなかった（`dataHash` の出現は ABI 定義・
    //    読み取り・返り値・記録だけで、**比較は0箇所**）。
    //    チャンク本数はデータ内容の同一性を表さず、正典 `MAX_DEPOSIT_IDS` から導出する
    //    サイズ回帰では本番到達可能な入力も複数チャンクになる。したがって本数一致を
    //    内容一致の代理にすると、チャンク数が同じまま内容だけ変わる再計算をスキップし得た。
    //    結果 `claimDataOf[N].dataHash`（旧 blob）と `blockStates[N].merkleRoot`（新 root）が
    //    食い違い、K-S5-002 の「root がある ⟹ その root を再現できる請求データがチェーン上にある」
    //    が壊れる。ZKP Stage 2（`zkp-guest/src/main.rs:118-124` の `assert_eq!(from_blob, entries)`
    //    と `TokenMining._verifyRootProof` の `pv.claimDataHash == claimDataOf[N].dataHash`）も同時に
    //    要求するので、そのブロックは**証明不能**になる。
    //    到達は敵対的でなくてよい: `POST /reconcile-evidence` が
    //    `calculateAndStoreResults(blockNum, {restart:true, unpark:true})` を無条件で呼び、
    //    `POST /calculate-results` も `prog.stage === 'done'` なら自動 restart する。
    //    🔴 自己修復もできなかった（運営が気づいて再実行しても同じ判定でまた `alreadyComplete`）。
    //    契約側は `chunkIndex == 0` で系列を作り直せるのに、DO からその tx が永久に出ない。
    //    検証期間（4日）経過後は `TokenMining.publishClaimData` の検査で
    //    `revert VerificationPeriodEnded()` ＝ **修復不能**。
    const expectedDataHash = chunkChainHash(chunks);
    const prefixHashes = [`0x${'00'.repeat(32)}`];
    for (let i = 1; i <= total; i++) prefixHashes.push(chunkChainHash(chunks.slice(0, i)));
    const sameSeries = (r) => r.chunks === total
      && r.received <= total
      && String(r.dataHash).toLowerCase() === prefixHashes[r.received].toLowerCase();

    let ref;
    try {
      ref = await readRef();
    } catch (error) {
      console.warn(`[claimdata] block ${blockNum}: initial claimDataOf read failed: ${error.shortMessage || error.message}`);
      return { published: false, pending: true, reason: 'preflight_unavailable', chunks: total };
    }
    // 本数**かつ**内容（連鎖ハッシュ）が一致するときだけ続きから送る。
    // どちらか違えば chunk 0 から系列を作り直す（契約の `chunkIndex==0` 分岐）。
    let start = sameSeries(ref) ? ref.received : 0;
    if (start >= total) {
      console.log(`[claimdata] block ${blockNum}: all ${total} chunk(s) already on-chain (dataHash matches)`);
      return { published: true, alreadyComplete: true, chunks: total, dataHash: ref.dataHash };
    }
    if (ref.chunks === total && ref.received > 0 && !sameSeries(ref)) {
      console.warn(`[claimdata] block ${blockNum}: on-chain dataHash ${ref.dataHash} != expected ${expectedDataHash} `
        + `(same chunk count ${total}) — republishing from chunk 0`);
    }

    for (let i = start; i < total; i++) {
      const hex = `0x${Array.from(chunks[i]).map((b) => b.toString(16).padStart(2, '0')).join('')}`;
      const sent = await this.sendAdminTx({
        intentId: `publishClaimData:${blockNum}:${expectedDataHash.toLowerCase()}:${i}`,
        operation: 'publishClaimData',
        payload: {
          blockNum, chunkIndex: i, totalChunks: total, data: hex,
          previousDataHash: prefixHashes[i], resultingDataHash: prefixHashes[i + 1], expectedDataHash,
        },
      });
      if (!sent.submitted) {
        if (isAdminTxPending(sent)) {
          // in_flight/receipt_pending は送信済みtxの通常の受領待ちであり、送信係の不達ではない。
          // それ以外の Coordinator 保留だけを共通の管理tx待ちへ持ち上げる。
          const receiptPending = sent.status === 'in_flight'
            && (sent.reason === 'receipt_pending' || sent.reason === 'receipt_timeout');
          const waitReason = sent.reason === 'admin_freeze'
            ? 'admin_freeze' : (receiptPending ? null : 'admin_tx_pending');
          return {
            published: false, pending: true, reason: sent.reason,
            accepted: sent.accepted === true, deadlineAt: sent.deadlineAt ?? null,
            status: sent.status || null,
            intentId: sent.intentId || null,
            operation: sent.operation || 'publishClaimData',
            retryInMs: ADMIN_TX_PENDING_RETRY_MS,
            chunkIndex: i, chunks: total, txHash: sent.txHash || null,
            ...(waitReason ? {
              waitReason,
              waitDetail: {
                stage: 'claim_data',
                intentId: sent.intentId || null,
                accepted: sent.accepted === true, deadlineAt: sent.deadlineAt ?? null,
                operation: sent.operation || 'publishClaimData',
                status: sent.status || null,
                txHash: sent.txHash || null,
                pendingReason: sent.reason || waitReason,
              },
            } : {}),
          };
        }
        throw new Error(`[claimdata] block ${blockNum}: chunk ${i}/${total} not confirmed (${sent.reason})`);
      }
      console.log(`[claimdata] block ${blockNum}: chunk ${i + 1}/${total} published (${chunks[i].length} bytes)`);
    }

    try {
      ref = await readRef();
    } catch (error) {
      console.warn(`[claimdata] block ${blockNum}: final claimDataOf read failed: ${error.shortMessage || error.message}`);
      return { published: false, pending: true, reason: 'preflight_unavailable', chunks: total };
    }
    if (ref.received !== total || ref.chunks !== total) {
      throw new Error(`[claimdata] block ${blockNum}: on-chain state says ${ref.received}/${ref.chunks} after publishing ${total}`);
    }
    // 🔴 P-2026-0838: 最終検査も件数だけでなく**内容**を見る。
    //    契約が積算した連鎖ハッシュ（`TokenMining.publishClaimData`）が、いま載せたチャンク列の
    //    `chunkChainHash` と一致していなければ、載っているバイト列は別物。
    if (String(ref.dataHash).toLowerCase() !== expectedDataHash.toLowerCase()) {
      throw new Error(
        `[claimdata] block ${blockNum}: on-chain dataHash ${ref.dataHash} != expected ${expectedDataHash} `
        + '— published bytes do not match the chunks we built'
      );
    }
    return { published: true, chunks: total, dataHash: ref.dataHash, expectedDataHash };
  }

  async submitMerkleRootForBlock(blockNum, root, opts = {}) {
    // [pin] merkle-submit-exempt: これは提出そのものの実装（送信＋claim-timing.json＋
    //   merkle_status 追記）であって「提出するかどうか」を決める場所ではない。
    //   verification.ok の判断は**呼び出し側**（noGame / autoDistribute / /submit-merkle-root /
    //   adminCommit ステージ）が行う。
    const submit = await this.submitMerkleRootOnChain(blockNum, root, opts);

    // 請求期限フォールバック用アンカー: 新規ブロードキャスト時のみ submitEnd を公開R2へ記録する。
    // submitEnd = 提出時刻 (≈ オンチェーン verificationStartedAt)。フロント (resolveClaimDeadline)
    // がオンチェーン取得に失敗した際、この値 + VERIFICATION_PERIOD + CLAIM_PERIOD で期限を算出する。
    // alreadySubmitted の場合は検証開始が過去の提出時刻なので上書きしない。
    if (submit?.submitted && !submit.alreadySubmitted) {
      try {
        await this.putR2Object(`games/block${blockNum}/claim-timing.json`, {
          blockNum, submitEnd: Date.now(), txHash: submit.txHash || null, root,
        });
        console.log(`[merkle] published games/block${blockNum}/claim-timing.json submitEnd=now`);
      } catch (e) {
        console.warn(`[merkle] claim-timing.json write failed block=${blockNum}: ${e.message}`);
      }
    } else if (submit?.submitted && submit.alreadySubmitted) {
      // 送信係経由の着地はalreadySubmittedで戻る。不存在を確認できた場合だけ、
      // 遅れて呼ばれた現在時刻ではなくチェーンの検証開始時刻で補完する。
      try {
        const key = `games/block${blockNum}/claim-timing.json`;
        const head = await this.inspectR2ArtifactHead(key);
        if (head.state === 'succeeded' && head.exists === false) {
          const lifecycle = await this.readBlockLifecycle(blockNum, { fresh: true });
          if (lifecycle.available && lifecycle.rootSubmitted
              && typeof lifecycle.merkleRoot === 'string'
              && lifecycle.merkleRoot.toLowerCase() === root.toLowerCase()
              && lifecycle.verificationStartedAt > 0) {
            // head後の並行作成も上書きしない。公開するJSONの形は直接送信の道と同じ。
            await this.env.R2_BUCKET.put(key, JSON.stringify({
              blockNum, submitEnd: lifecycle.verificationStartedAt * 1000,
              txHash: submit.txHash || null, root,
            }), {
              onlyIf: { etagDoesNotMatch: '*' },
              httpMetadata: { contentType: 'application/json' },
            });
          }
        }
      } catch (e) {
        console.warn(`[merkle] claim-timing.json write failed block=${blockNum}: ${e.message}`);
      }
    }

    // merkle_status に submit 結果を追記（既存 status とマージ）
    try {
      const prev = (await this.storage.get(`merkle_status_${blockNum}`)) || { blockNum };
      const status = { ...prev, submit, submittedAt: new Date().toISOString() };
      await this.storage.put(`merkle_status_${blockNum}`, status);
      await this.putR2Object(`merkle/block_${blockNum}_status.json`, status);
    } catch {}

    console.log(`[merkle] block ${blockNum} submit:`, JSON.stringify(submit));
    return submit;
  }

  // 🔴 2026-09-22（契約が7引数化）: 証明付き root 提出の第7引数 `prevRegistrationIndex` を
  //    **送信直前に現物から**組む。契約は ①添字が範囲内 ②その行の hash が PV word7 と一致
  //    ③番兵は履歴0件のときだけ を見る（TokenMining._checkAnchors）。②が破れていれば
  //    `PvPrevResultManifestMismatch` で決定的に revert するので、tx を作らずに
  //    **契約と同じ文言**で止める。呼出元（`calcAdminCommitUnit`）の stale 判定
  //    `/\bPV:\s*prevResultManifest mismatch\b/` がこれを拾い、proof を捨てて入力を再収集する
  //    ＝ word7 と添字が必ず同じ再収集で作り直される。
  //    ⚠️ 添字を proof 側にキャッシュしない。`resetStaleZkpProof` が proof を作り直しても
  //    添字が古いままになる経路を作らないため、毎回ここで読む。
  async resolvePrevRegistrationIndexForProof(blockNum, zkProof) {
    const decoded = decodeZkpPublicValues(zkProof.publicValues);
    const prev = await this.readPrevResultRegistrationOnChain(blockNum);
    if (blockNum > 0 && prev.prevRegistrationCount === '0') {
      throw new Error(`[merkle] block ${blockNum}: previous result registration is pending; refusing proof sentinel`);
    }
    if (decoded.prevResultManifestHash !== prev.prevResultManifestHash) {
      throw new Error(
        `[merkle] block ${blockNum}: PV: prevResultManifest mismatch — proof word7=${decoded.prevResultManifestHash}`
        + ` but HashStorage result registration index=${prev.prevRegistrationIndex}`
        + ` (count=${prev.prevRegistrationCount}) holds ${prev.prevResultManifestHash}`,
      );
    }
    return prev.prevRegistrationIndex;
  }

  // submitMerkleRoot をAdminTxCoordinatorへ委譲する。
  //   env (workers/.env → set-all-secrets.js でシークレット化):
  //     ETHEREUM_MAINNET_RPC_URLS → _URL_BACKUP → _URL → _URL_BACKUP2（読み取りの順・lib/rpc-urls.js・D-05）, TOKEN_MINING_CONTRACT_ADDRESS
  //     署名用秘密鍵はCoordinatorだけが保持する。
  //   未設定なら no-op (R2 公開のみ)。二重提出 (検証タイマーのリセット) を防ぐため既提出 root を確認。
  async submitMerkleRootOnChain(blockNum, root, opts = {}) {
    // S3-008／D-05: RPC 一覧は lib/rpc-urls.js が読み取りの順で組む（ETHEREUM_MAINNET_RPC_URLS で本数無制限に追加可）
    const rpcUrls = rpcReadUrlsFromEnv(this.env);
    const contractAddr = this.env.TOKEN_MINING_CONTRACT_ADDRESS;
    if (rpcUrls.length === 0 || !this.env.ADMIN_TX_COORDINATOR || !contractAddr) {
      const missing = [];
      if (rpcUrls.length === 0) missing.push('ETHEREUM_MAINNET_RPC_URL');
      if (!this.env.ADMIN_TX_COORDINATOR) missing.push('ADMIN_TX_COORDINATOR');
      if (!contractAddr) missing.push('TOKEN_MINING_CONTRACT_ADDRESS');
      console.warn(`[merkle] on-chain submit skipped: missing env ${missing.join(', ')}`);
      return { submitted: false, reason: 'missing_config', missing };
    }

    let gasAutoForce = null;
    try {
      const address = getAddress(contractAddr);
      // 読取クライアントの構築は全経路で共通化する。productionのRPC fallbackは同じで、
      // 単体試験もpublishClaimDataまで本物の経路を通して凍結保留を観測できる。
      const publicClient = this.createReadOnlyClient();
      if (!publicClient) return { submitted: false, reason: 'preflight_unavailable' };
      const parseMerkleBlockState = (state) => {
        const hasEpoch = Array.isArray(state)
          ? state.length > 2
          : !!state && Object.prototype.hasOwnProperty.call(state, 'zkEpochPlusOne');
        const merkleRoot = Array.isArray(state) ? state[0] : state?.merkleRoot;
        const epochRaw = Array.isArray(state) ? state[2] : state?.zkEpochPlusOne;
        if (!hasEpoch || typeof merkleRoot !== 'string' || !/^0x[0-9a-fA-F]{64}$/.test(merkleRoot)) {
          throw new Error('malformed blockStates merkleRoot');
        }
        let zkEpochPlusOne;
        try { zkEpochPlusOne = BigInt(epochRaw ?? 0); }
        catch { throw new Error('malformed blockStates zkEpochPlusOne'); }
        if (zkEpochPlusOne < 0n) throw new Error('malformed blockStates zkEpochPlusOne');
        return { merkleRoot, zkEpochPlusOne };
      };

      // 時刻アンロック前は submitMerkleRoot が revert するので送らない
      try {
        const unlocked = await publicClient.readContract({
          address, abi: TOKEN_MINING_ABI, functionName: 'isBlockTimeUnlocked', args: [BigInt(blockNum)],
        });
        if (!unlocked) {
          console.warn(`[merkle] block ${blockNum} not time-unlocked on-chain; deferring submit`);
          return { submitted: false, reason: 'not_time_unlocked' };
        }
      } catch (e) {
        console.warn(`[merkle] isBlockTimeUnlocked read failed: ${e.shortMessage || e.message}`);
      }

      // ── K-S5-002 ①: ガス価格ゲート ──
      // 上限を超えていたら**何も送らない**。ここで止めるのは publishClaimData も含めた
      // 一連の送信すべて（データだけ出して root は出さない、という中途半端な状態を作らない）。
      const gate = await this.checkGasPriceGate(publicClient, { force: !!opts.force });
      if (!gate.ok) {
        const wait = await this.noteGasWait(blockNum, gate, publicClient, address);
        if (!shouldAutoForceGasWait(wait)) {
          console.warn(`[gas] block ${blockNum}: waiting — ${gate.current.gwei.toFixed(2)} gwei > ${gate.limit.gwei} gwei (${gate.limit.source}), attempt ${wait.attempts}`);
          return {
            submitted: false, reason: 'gas_price_wait',
            currentGwei: gate.current.gwei, limitGwei: gate.limit.gwei, limitSource: gate.limit.source,
            deadlineAt: wait.deadlineAt ?? null, deadlineDaysLeft: wait.deadlineDaysLeft ?? null,
            retryInMs: GameMasterDO.TIMELINE_RETRY_MS,
          };
        }
        gasAutoForce = await this.noteGasAutoForce(blockNum, gate, wait);
        console.warn(
          `[gas] block ${blockNum}: AUTO FORCE after ${Math.floor(gasAutoForce.waitedMs / DAY_MS)} days — `
          + `${gate.current.gwei.toFixed(2)} gwei > ${gate.limit.gwei} gwei; gas gate only is bypassed`
        );
      } else if (gate.current && gate.current.gwei <= gate.limit.gwei) {
        // 「3日連続で上限超過」の時計なので、価格が一度下がった時点で待機開始をリセットする。
        await this.clearGasWait(blockNum);
      }

      // R20-F8: 同じrootが証明なしで既に確定している場合は、claim dataを再公開せず
      // permissionless attachだけを行う。claim期間後でも添付でき、clockは一切動かさない。
      let attachMode = false;
      try {
        const state = await publicClient.readContract({
          address, abi: TOKEN_MINING_ABI, functionName: 'blockStates', args: [BigInt(blockNum)],
        });
        const { merkleRoot: existingRoot, zkEpochPlusOne: existingEpochPlusOne } = parseMerkleBlockState(state);
        if (existingRoot && existingRoot.toLowerCase() === root.toLowerCase()) {
          attachMode = !!opts.zkProof && BigInt(existingEpochPlusOne || 0) === 0n;
          if (!attachMode) {
            if (opts.prepareOnly) {
              return {
                prepared: true, alreadySubmitted: true, root, contract: address, claimData: null,
                ...(gasAutoForce ? { gasAutoForce: true, gasAutoForceAt: gasAutoForce.triggeredAt } : {}),
              };
            }
            await this.clearGasWait(blockNum);
            return {
              submitted: true, alreadySubmitted: true, root, contract: address,
              ...(gasAutoForce ? { gasAutoForce: true, gasAutoForceAt: gasAutoForce.triggeredAt } : {}),
            };
          }
        }
      } catch (e) {
        console.warn(`[merkle] initial blockStates read failed: ${e.shortMessage || e.message}`);
        return { submitted: false, reason: 'preflight_unavailable' };
      }

      // ── K-S5-002 ②: 請求データを先に載せる ──
      // 契約が「全チャンク受領」を require するので、これが通らないと root は出せない。
      // 順序が逆（root が先）だと「root はあるがデータは無い」瞬間ができてしまう。
      if (!attachMode) {
      const summary = await this.getR2Object(`games/block${blockNum}/summary.json`);
      if (!summary) {
        throw new Error(`[claimdata] block ${blockNum}: summary.json not found in R2 — cannot publish claim data`);
      }
      const { chunks, stats } = await this.buildClaimDataChunks(blockNum, summary);
      console.log(`[claimdata] block ${blockNum}: ${stats.players} players / ${stats.deposits} deposits → raw ${stats.rawBytes}B → onchain ${stats.onchainBytes}B (uncompressed) → ${stats.chunkCount} chunk(s)`);

      // ★ 請求データ自己完結化（2026-08-01）: **今から載せる blob が、今から出す root と噛み合うか**を
      //   ここで1度だけ機械照合する。root は先に作られた成果物（merkle/block_{N}.json や
      //   手動 /submit-merkle-root の引数）から来るのに対し、blob は summary.json を**この場で読み直して**
      //   作るので、その間に summary が書き換わると「root は正しいが blob からは別の木しか組めない」
      //   状態でオンチェーンに固定されてしまう。BCD2 では blob が唯一の自己完結請求データなので、
      //   これは「未請求報酬が永久に取り出せない」に直結する。整合しないなら提出しない（fail-closed）。
      {
        const rebuilt = this.buildMerkleTree(blockNum, this.collectClaimEntriesFromSummary(blockNum, summary)).root;
        if (rebuilt.toLowerCase() !== String(root).toLowerCase()) {
          throw new Error(
            `[claimdata] block ${blockNum}: summary.json rebuilds to root ${rebuilt} but ${root} is about to be submitted `
            + '— refusing to publish claim data that cannot reproduce the submitted root'
          );
        }
      }
      const claimData = await this.publishClaimDataOnChain(blockNum, chunks, {
        address, publicClient,
      });
      if (claimData?.pending) {
        const waitReason = claimData.waitReason || null;
        return {
          submitted: false,
          prepared: false,
          reason: 'claim_data_receipt_pending',
          retryInMs: Number(claimData.retryInMs) || ADMIN_TX_PENDING_RETRY_MS,
          claimData,
          ...(waitReason ? {
            waitReason,
            status: claimData.status || null,
            waitDetail: {
              ...(claimData.waitDetail || {}),
              stage: 'claim_data',
              operation: claimData.operation || 'publishClaimData',
              pendingReason: claimData.reason || waitReason,
            },
          } : {}),
        };
      }
      // 🔴 P-2026-0838（ラウンド19 判断不要-6）: **root を出す前に、チェーン上の請求データが
      //    いま組んだチャンク列そのものであることを確認する。** 上の rebuild 照合は
      //    「summary → root」だけを見ており、「チェーンに載っている blob」は見ていなかった。
      //    ここを通らないと `claimDataOf[N].dataHash`（旧 blob）と
      //    `blockStates[N].merkleRoot`（新 root）が食い違ったまま確定しうる。
      {
        const expected = chunkChainHash(chunks);
        if (String(claimData?.dataHash ?? '').toLowerCase() !== expected.toLowerCase()) {
          throw new Error(
            `[claimdata] block ${blockNum}: on-chain claim data hash ${claimData?.dataHash} != ${expected} `
            + '— refusing to submit a merkle root whose claim data is not on-chain'
          );
        }
      }
      await this.storage.put(`claim_data_block${blockNum}`, {
        blockNum, format: CLAIM_DATA_FORMAT, ...stats, ...claimData, at: Date.now(),
      });
      await this.clearGasWait(blockNum);

      // G2: ZKP 入力収集は claimDataOf / ClaimDataPublished を公開チェーンから読む。
      // root だけは最後の adminCommit まで送らず、ここで claim data の完成だけを返す。
      if (opts.prepareOnly) {
        return {
          prepared: true, root, contract: address, claimData,
          ...(gasAutoForce ? { gasAutoForce: true, gasAutoForceAt: gasAutoForce.triggeredAt } : {}),
        };
      }
      }
      if (attachMode) await this.clearGasWait(blockNum);

      // 既提出チェック (同一 root なら再送しない = 検証タイマーをリセットしない)。
      // sendAdminTx の再送前にも毎回実行される＝置き換え判定が誤っていても二重提出しない。
      const preflight = async () => {
        try {
          const state = await publicClient.readContract({
            address, abi: TOKEN_MINING_ABI, functionName: 'blockStates', args: [BigInt(blockNum)],
          });
          const { merkleRoot: existingRoot, zkEpochPlusOne: existingEpochPlusOne } = parseMerkleBlockState(state);
          if (existingRoot && existingRoot.toLowerCase() === root.toLowerCase()) {
            if (attachMode && BigInt(existingEpochPlusOne || 0) === 0n) {
              return { skip: false };
            }
            console.log(`[merkle] block ${blockNum} root already submitted on-chain`);
            return {
              skip: true,
              terminal: true,
              result: { submitted: true, alreadySubmitted: true, root, contract: address },
            };
          }
        } catch (e) {
          console.warn(`[merkle] blockStates read failed: ${e.shortMessage || e.message}`);
          return {
            skip: true,
            terminal: false,
            result: { submitted: false, reason: 'preflight_unavailable', root, contract: address },
          };
        }
        return { skip: false };
      };

      // Coordinatorがreceiptまで1件ずつ直列追跡し、同じ管理者EOAの別経路とnonceを共有する。
      const zkProof = opts.zkProof || null;
      if (zkProof) validateZkpProof(zkProof, { blockNum, root,
        vkey: ZKP_WIRE_EXPECTED.vkey, elfSha256: ZKP_WIRE_EXPECTED.elfSha256 });
      const functionName = zkProof
        ? (attachMode ? 'attachProofToMerkleRoot' : 'submitMerkleRootWithProof')
        : 'submitMerkleRoot';
      // 既提出の同一rootは、検証期間終了後だと eth_call 自体が Verification period ended で
      // revertする。従来はpreflightをsendAdminTx内（simulate後）でしか実行しなかったため、
      // 確認・復旧目的の冪等呼び出しが期限後だけ失敗した。まず既提出を返し、未提出の場合だけ
      // simulateする。Coordinator側もbroadcast直前に同じ不変条件を再確認する。
      const existing = await preflight();
      if (existing?.skip) return { ...existing.result, attempts: 0 };
      const operation = functionName;
      const payload = zkProof
        ? {
          blockNum, root, verifierAddress: zkProof.verifierAddress, vkey: zkProof.vkey,
          publicValues: zkProof.publicValues, proofBytes: zkProof.proofBytes,
          // 🔴 2026-09-22: 契約の第7引数。送信直前に現物から組む（下の resolve… を参照）。
          //    Coordinator の `normalizePayload` はこの欄を**必須**にしているので、
          //    欠けたまま送ると `invalid_request` で止まる。
          prevRegistrationIndex: await this.resolvePrevRegistrationIndexForProof(blockNum, zkProof),
        }
        : { blockNum, root };
      const proofIntentSuffix = zkProof
        ? keccak256(concatHex([
          zkProof.publicValues, zkProof.proofBytes,
          encodeAbiParameters(parseAbiParameters('uint256'), [BigInt(payload.prevRegistrationIndex)]),
        ])).slice(2)
        : 'shadow';
      const sent = await this.sendAdminTx({
        intentId: `${operation}:${blockNum}:${root.toLowerCase()}:${proofIntentSuffix}`,
        operation,
        payload,
      });
      if (sent.submitted) {
        if (sent.alreadySubmitted) {
          return {
            ...sent,
            ...(gasAutoForce ? { gasAutoForce: true, gasAutoForceAt: gasAutoForce.triggeredAt } : {}),
          };
        }
        console.log(`[merkle] ${functionName} confirmed block=${blockNum} tx=${sent.txHash} attempts=${sent.attempts}`);
        return {
          submitted: true, txHash: sent.txHash, root, from: this.env.SIGNER_ADDRESS || null, contract: address,
          minedBlock: adminTxReceiptBlockNumber(sent), attempts: sent.attempts,
          ...(gasAutoForce ? { gasAutoForce: true, gasAutoForceAt: gasAutoForce.triggeredAt } : {}),
        };
      }
      console.error(`[merkle] ${functionName} NOT confirmed block=${blockNum} reason=${sent.reason} tx=${sent.txHash} attempts=${sent.attempts}`);
      return {
        submitted: false, accepted: sent.accepted === true,
        status: sent.status || null, reason: sent.reason,
        intentId: sent.intentId || null, operation: sent.operation || operation,
        deadlineAt: sent.deadlineAt ?? null,
        retryInMs: isAdminTxPending(sent) ? ADMIN_TX_PENDING_RETRY_MS : null,
        txHash: sent.txHash, root, contract: address, attempts: sent.attempts,
        ...(gasAutoForce ? { gasAutoForce: true, gasAutoForceAt: gasAutoForce.triggeredAt } : {}),
      };
    } catch (e) {
      console.error(`[merkle] submitMerkleRootOnChain failed block=${blockNum}: ${e.shortMessage || e.message}`);
      return {
        submitted: false, reason: 'tx_error', error: e.shortMessage || e.message,
        ...(gasAutoForce ? { gasAutoForce: true, gasAutoForceAt: gasAutoForce.triggeredAt } : {}),
      };
    }
  }

  // ============================================================
  // 応募者2名以下: ゲームなしでデポジットポイント按分
  // ============================================================

  async publishAutoRosterFile(blockNum, players) {
    const members = players.map(p => ({ ...p.data, globalIndex: p.globalIndex }));
    if (members.some((member, index) => index > 0 && member.globalIndex <= members[index - 1].globalIndex)) {
      throw new Error('[auto-distribute] selected entries are not in winner index order');
    }
    const text = canonicalRosterText(blockNum, 0, members);
    await this.env.R2_BUCKET.put(`games/block${blockNum}/roster/group0.json`, text,
      { httpMetadata: { contentType: 'application/json' } });
    return text;
  }

  async autoDistribute(blockNum, players) {
    const db = this.env.BITCOINU_DATA;
    if (!db) throw new Error('BITCOINU_DATA binding not found');

    const blockRewardWei = getBlockRewardWei(blockNum);
    const stateKey = `auto_distribute_block${blockNum}`;
    const selectionHash = await this.sha256Hex(JSON.stringify(players));
    let autoProgress = await this.storage.get(stateKey);
    if (!autoProgress) {
      autoProgress = {
        blockNum, stage: 'computed', startedAt: Date.now(), createdAt: new Date().toISOString(),
        failures: 0, totalPlayers: players.length, selectionHash,
      };
      await this.storage.put(stateKey, autoProgress);
    }
    if (autoProgress.totalPlayers !== players.length || autoProgress.selectionHash !== selectionHash
      || players.length < 1 || players.length > 2) {
      throw new Error(`[auto-distribute] selection changed or invalid: expected ${autoProgress.totalPlayers}/${autoProgress.selectionHash}, got ${players.length}/${selectionHash}`);
    }
    if (autoProgress.stage === 'done') {
      await this.clearRosterGateTimelineWait(blockNum);
      return autoProgress.result;
    }
    const now = autoProgress.createdAt;
    const stages = ['computed', 'd1', 'summary', 'archive', 'shards', 'merkle', 'proofs', 'manifest', 'root_pipeline', 'done'];
    const completed = (stage) => stages.indexOf(autoProgress.stage) >= stages.indexOf(stage);
    const checkpoint = async (stage, extra = {}) => {
      autoProgress = { ...autoProgress, ...extra, stage, updatedAt: Date.now(), lastError: null };
      await this.storage.put(stateKey, autoProgress);
    };

    // B1: コミット済みエントリーのdepositIdsをEthLockで権威的に再検証。
    // ゲーム無しブロック（提出ウォレット署名が無い）でも、depositIdの集合自体は
    // applicantHashにコミット済みのエントリーデータ由来なので、そのIDをオンチェーンで
    // 再読込すればポイントの重み・配当先（depositerAddress）・金額を権威的に確定できる。
    const parseEntryDepositIds = (depIdsRaw) => {
      if (!depIdsRaw) return [];
      try {
        const parsed = typeof depIdsRaw === 'string' ? JSON.parse(depIdsRaw) : depIdsRaw;
        return Array.isArray(parsed?.ids) ? [...new Set(parsed.ids.map(id => String(id)))] : [];
      } catch { return []; }
    };
    // P-2026-0820: uid 鍵の辞書は `Object.create(null)`（`__proto__` uid が消えないように）
    const perUid = Object.create(null);
    for (const p of players) {
      const uid = p.data?.uid;
      if (uid == null) continue;
      perUid[uid] = parseEntryDepositIds(p.data?.depIds);
    }
    const { verifiedDepositWei, verifiedDeposits } = await this.verifyDepositsOnChainForUids(blockNum, perUid);

    // 各プレイヤーのデポジットポイント計算（オンチェーン検証済み適格weiから）
    //
    // 🔴 J-31（2026-08-08・ユーザー確定）: **ゲーム経路と同一の適格帯判定をここにも入れる。**
    //    この経路には範囲検査が1行も無く、`isDisqualified: false` を決め打ちしていた。
    //    実測: 上限の2倍（20 ETH）の応募者1人が `deposit_points=447` / 非失格で報酬の 93.71% を取り、
    //    それでも block-verifier は 45項目 FAIL 0 / WARN 0 で PASS した
    //    （`src/stages/results.js` の rules 照合は**宣言と pin の一致**しか見ておらず、
    //      「宣言した規則が実際に適用されたか」を見ていないため）。
    //
    //    問題は金額ではない。2名以下のブロックで全部取りたいなら、運営は正直に 10 ETH で
    //    1人応募すれば 100% 取れるので利得は無い。塞ぐべきは
    //    **「宣言した規則を適用していないブロックが第三者検証で満点を出す」**ことそのもの。
    //    これを許すと「第三者が独立に検証できる」という柱が空手形になる。
    //
    //    ⚠️ 下限側（0.01 ETH 未満）は EthLock が1口あたり 0.01 ETH 下限を強制するので
    //       実際には到達不能。それでも**対称に**入れる（片側だけにすると、将来どちらかを
    //       動かしたときにもう片方が黙って抜ける）。
    //    ⚠️ 権威表（オンチェーン再検証済み）がある行にだけ適用する。自己申告 depIds への
    //       フォールバック枝にはかけない — ゲーム経路（`calculateGroupResults`）と同じ判断で、
    //       「DB を弄るだけで参加者を落とせる」状態を作らないため。
    const memberResults = players.map(p => {
      const uid = p.data?.uid;
      const hasVerified = uid != null && verifiedDepositWei[uid] !== undefined;
      const depositWei = hasVerified
        ? verifiedDepositWei[uid]
        : parseDepositWei(p.data?.depIds);
      const depositPoints = calculateDepositPoints(depositWei);
      // 判定はゲーム経路と**同じ関数**（game-result-calculator.js の唯一の実装）。
      const ineligible = hasVerified && isIneligibleDepositWei(depositWei);
      return {
        uid,
        addr: p.data?.addr || null,
        bAddr: p.data?.bAddr || null,
        lang: p.data?.lang || null,
        depIds: p.data?.depIds || null,
        name: p.data?.name || null,
        img: p.data?.img || null,
        verified: p.data?.verified || false,
        globalIndex: p.globalIndex,
        depositPoints,
        bonusPoints: 0,
        // 失格者の合計ポイントは 0（ゲーム経路 `r.totalPoints = r.isDisqualified ? 0 : …` と同じ）。
        totalPoints: ineligible ? 0 : depositPoints,
        isDisqualified: ineligible,
        disqualifyReason: ineligible ? 'ineligible_deposit' : null,
        btcuReward: '0'
      };
    });

    // 合計ポイント
    const totalPoints = memberResults.reduce((s, m) => s + m.totalPoints, 0);

    // BTCu按分（BigInt演算）
    for (const member of memberResults) {
      if (totalPoints === 0) {
        member.btcuReward = '0';
      } else {
        member.btcuReward = (
          blockRewardWei * BigInt(member.totalPoints) / BigInt(totalPoints)
        ).toString();
      }
      member.fullReward = member.btcuReward;
    }

    // 50/50 Split: プレイヤー50% / デポジッター50%
    // デポジッター配当の宛先・金額はオンチェーン検証済みverifiedDepositsが権威
    // （エントリー時キャッシュの改ざんで配当先を変更できない）
    const depositorResults = [];

    for (const member of memberResults) {
      const totalReward = BigInt(member.btcuReward || '0');
      if (totalReward === 0n) continue;

      const deposits = verifiedDeposits[member.uid] || [];
      const totalDepWei = deposits.reduce((s, d) => s + BigInt(d.amount), 0n);
      if (deposits.length === 0 || totalDepWei <= 0n) {
        member.playerShare = totalReward.toString();
        continue;
      }

      const playerShare = totalReward / 2n;
      const depositorShareTotal = totalReward - playerShare;
      member.btcuReward = playerShare.toString();
      member.playerShare = playerShare.toString();
      member.depositorShare = depositorShareTotal.toString();

      // プロラタ配分（重み＝オンチェーンamount）。**全員切り捨て**（SPEC §7・2026-08-01）。
      // ⚠️ これは calcRewardsUnit とは**完全に独立した第2実装**（応募2名以下の自動配布経路）。
      //    通常テストでは自動配布ブロックが出にくいので、片方だけ直すと気づきにくい。
      //    式は claim-data-codec.js の depositorShareOf 1箇所に集約している。
      for (let i = 0; i < deposits.length; i++) {
        const dep = deposits[i];
        const depBtcu = depositorShareOf(depositorShareTotal, dep.amount, totalDepWei);

        depositorResults.push({
          groupId: 0,
          playerUid: member.uid,
          depositorUid: dep.idFrom,
          depositId: dep.depositId,
          depositerAddress: dep.depositerAddress || null,
          depositAmount: dep.amount,
          btcuReward: depBtcu.toString(),
          isPlayerSelf: dep.idFrom === member.uid
        });
      }
    }

    // game_groups に1行書き込み（status='auto_distributed'）
    const membersJson = JSON.stringify(memberResults.map(m => ({
      uid: m.uid,
      addr: m.addr,
      bAddr: m.bAddr,
      lang: m.lang,
      depIds: m.depIds,
      globalIndex: m.globalIndex,
      name: m.name,
      img: m.img,
      verified: m.verified
    })));

    const resultSummary = JSON.stringify({
      totalGroupPoints: totalPoints,
      // J-31: 決め打ち 0 をやめる（帯判定の結果を素直に映す）。
      disqualifiedCount: memberResults.filter(m => m.isDisqualified).length,
      autoDistributed: true,
      memberResults: memberResults.map(m => ({
        uid: m.uid,
        depositPoints: m.depositPoints,
        bonusPoints: 0,
        totalPoints: m.totalPoints,
        isDisqualified: m.isDisqualified,
        disqualifyReason: m.disqualifyReason,
        btcuReward: m.btcuReward
      })),
      depositorResults: depositorResults.map(d => ({
        depositorUid: d.depositorUid,
        playerUid: d.playerUid,
        depositId: d.depositId,
        depositAmount: d.depositAmount,
        btcuReward: d.btcuReward,
        isPlayerSelf: d.isPlayerSelf
      }))
    });

    if (!completed('d1')) {
      // R20-F1: D1は「追加」ではなく今回の正典集合へ1 transactionで置換する。
      // root提出前のstageなのでclaimedは存在せず、旧positive depositor行も確実に消える。
      const { results: oldRows } = await db.prepare(
        'SELECT DISTINCT userId FROM game_results WHERE block_num = ?'
      ).bind(blockNum).all();
      const replaceShardUids = [...new Set([
        ...(autoProgress.replaceShardUids || []),
        ...(oldRows || []).map(row => String(row.userId)).filter(Boolean),
      ])];
      // D1 commit直後のruntime終了でも旧shard対象を失わないよう、置換対象を先にdurable化する。
      autoProgress = { ...autoProgress, replaceShardUids, updatedAt: Date.now() };
      await this.storage.put(stateKey, autoProgress);
      const statements = [
        db.prepare('DELETE FROM game_results WHERE block_num = ?').bind(blockNum),
        db.prepare('DELETE FROM game_groups WHERE block_num = ?').bind(blockNum),
        db.prepare(
          `INSERT INTO game_groups (block_num, group_id, lang, mixed, members, status, result, completed_at, created_at)
           VALUES (?, 0, 'auto', 0, ?, 'auto_distributed', ?, ?, ?)`
        ).bind(blockNum, membersJson, resultSummary, now, now),
      ];
      for (const member of memberResults) {
        // 🔴 R26-C12（2026-08-14）: **migration 010 が落とした5列をここだけ書き続けていた。**
        //    `deposit_points` / `bonus_points` / `total_points` / `is_disqualified` /
        //    `disqualify_reason` は 010 で DROP 済みで、正典 writer（`calcWritingUnit`・:6224）は
        //    同じコミットで追随したのに、**この自動配布側だけが取り残されていた**
        //    （11行下のデポジッター INSERT は 010 後の正しい列で書いている＝同じ関数の片側だけ古い）。
        //
        //    実害: 応募 1〜2名のブロック（`:3296` で `autoDistribute` へ入る＝**新規ローンチ直後は
        //    ほぼ確実にこの経路**）で `db.batch` が
        //    `table game_results has no column named deposit_points` で落ちる。
        //    batch は1トランザクションなので DELETE も巻き戻り、`checkpoint('d1')` に到達しない。
        //    さらに `error.resumable = true` なので watchdog が**同じ SQL を永久に再試行**する。
        //    以降の summary / archive / shards / merkle / proofs / manifest / root 提出が
        //    一切走らず、**そのブロックの報酬は永久に請求不能**。次ブロック以降も
        //    「前ブロック確定待ち」で連鎖停止する。
        //
        //    点数・失格理由は `game_groups.result` の `resultSummary`（:8843）と
        //    `auto-results.json`（:8767）に既に入っているので、ここで失うものは無い。
        //    列と UPSERT 節は正典 writer（:6224）と**同一**にしてある。
        //    ⚠️ 上の `DELETE FROM game_results WHERE block_num = ?` が同一 transaction 内で
        //    先に走るので `ON CONFLICT` は現状は発火しない。それでも正典と同じ形にするのは、
        //    「2つの writer が同じ表へ違う形で書く」状態こそが本 finding の原因だったため。
        statements.push(db.prepare(
          `INSERT INTO game_results (block_num, group_id, userId, role, deposit_id, address, btcu_reward, created_at) VALUES (?, 0, ?, 'player', '', ?, ?, ?)
           ON CONFLICT(block_num, group_id, userId, role, deposit_id) DO UPDATE SET
             address = excluded.address, btcu_reward = excluded.btcu_reward, created_at = excluded.created_at`
        ).bind(
          blockNum, member.uid, member.addr || null, member.btcuReward, now
        ));
      }
      for (const depResult of depositorResults) {
        statements.push(db.prepare(
          `INSERT INTO game_results
           (block_num, group_id, userId, role, deposit_id, address, btcu_reward, deposit_to, created_at)
           VALUES (?, 0, ?, 'depositor', ?, ?, ?, ?, ?)`
        ).bind(
          blockNum, depResult.depositorUid, depResult.depositId, depResult.depositerAddress,
          depResult.btcuReward, depResult.playerUid, now
        ));
      }
      await db.batch(statements);
      await checkpoint('d1', { replaceShardUids });
    }

    // R15-F1: 自動配布も schema v2 の lean index と表示ページを分ける。
    // auto は通常ゲームの group artifact 集合には数えないため、専用の決定論的 key を使う。
    const autoDetailKey = `games/block${blockNum}/auto-results.json`;
    const autoGameResults = [
      ...memberResults.map(m => ({
        userId: m.uid,
        role: 'player',
        deposit_id: '',
        address: m.addr || null,
        btcu_reward: m.btcuReward,
        deposit_to: null,
        deposit_points: m.depositPoints,
        bonus_points: 0,
        total_points: m.totalPoints,
        is_disqualified: m.isDisqualified ? 1 : 0,
        disqualify_reason: m.disqualifyReason || null,
        report_gain_points: 0,
        vote_target_uid: null,
        report_target_uids: null,
        voted_by_uids: null,
      })),
      ...depositorResults.map(d => ({
        userId: d.depositorUid,
        role: 'depositor',
        deposit_id: d.depositId,
        address: d.depositerAddress || null,
        btcu_reward: d.btcuReward,
        deposit_to: d.playerUid,
      })),
    ];
    const autoDetail = {
      schemaVersion: 1,
      meta: { blockNum, groupId: 0, autoDistributed: true },
      members: memberResults.map(m => ({
        uid: m.uid, addr: m.addr, bAddr: m.bAddr, lang: m.lang, depIds: m.depIds,
        globalIndex: m.globalIndex, name: m.name, img: m.img, verified: m.verified,
      })),
      gameResults: autoGameResults,
      canonicalTimeline: [],
    };

    // R2にサマリー保存
    const blockSummary = {
      schemaVersion: 3,
      blockNum,
      blockReward: blockRewardWei.toString(),
      totalPlayers: players.length,
      totalGroups: 0,
      autoDistributed: true,
      majorLangs: [], // 自動配布はグループ分けなし＝主要言語なし
      groups: [{
        group_id: 0,
        lang: 'auto',
        member_count: memberResults.length,
        status: 'auto_distributed',
        total_points: totalPoints,
        detailKey: autoDetailKey,
        claimOverlayKey: `games/block${blockNum}/claim-status/group0.json`,
        members: memberResults.map(m => ({
          userId: m.uid,
          address: m.addr,
          lang: canonicalSummaryLang(m.lang, `block ${blockNum} auto member ${m.uid}`),
          total_points: m.totalPoints,
          is_disqualified: m.isDisqualified ? 1 : 0,
          full_btcu_reward: m.fullReward,
        })),
        depositor_results: depositorResults.map(d => ({
          playerUid: d.playerUid,
          depositId: d.depositId,
        }))
      }],
      resultLayout: 'auto-distribution-page-v1',
      claimStatusKey: `games/block${blockNum}/claim-status.json`,
      claimLayout: 'group-overlays-v1',
    };
    // S4: 自動配布も行別 claimed は manifest 外の group0 overlay にだけ置く。
    if (!completed('summary')) {
      await this.putR2ObjectOrThrow(autoDetailKey, autoDetail);
      await this.publishInitialClaimOverlays(blockNum, [{ groupId: 0, members: memberResults }], depositorResults);
      await this.publishInitialClaimStatus(blockNum, this.buildInitialClaimStatus(
        [{ groupId: 0, members: memberResults }], depositorResults));
      await this.publishBlockSummaryPreservingClaims(blockNum, blockSummary);
      await this.publishAutoRosterFile(blockNum, players);
      await checkpoint('summary');
    }

    // R2にフル結果アーカイブ
    const allGroupResults = [{
      groupId: 0,
      members: memberResults
    }];
    const archiveData = {
      schemaVersion: 2,
      blockNum,
      blockReward: blockRewardWei.toString(),
      totalPoints,
      groupCount: 0,
      autoDistributed: true,
      resultLayout: 'auto-distribution-page-v1',
      groupKeys: [],
      playerCount: memberResults.length,
      depositorCount: depositorResults.length,
    };
    if (!completed('archive')) {
      await this.putR2ObjectOrThrow(`entries/block${blockNum}/game_results.json`, archiveData);
      await checkpoint('archive');
    }

    // シャードDBにゲーム結果を書き込み。C1/R4是正: 失敗はthrow（startGroupingのcatch→failed→
    // 再実行で自己回復。autoDistributeは決定論的・書き込みは冪等upsertなので再実行安全）
    let writeResult = autoProgress.writeResult || null;
    if (!completed('shards')) {
      writeResult = await this.writeGameResultsToShards(blockNum, allGroupResults, depositorResults, {
        replace: true, autoDistributed: true,
        replaceUids: autoProgress.replaceShardUids || [],
      });
      await checkpoint('shards', { writeResult });
    }
    console.log(`Auto-distribute shard writes: ${writeResult.totalWritten} written (${writeResult.totalChunks} chunks)`);

    console.log(`Auto-distributed block ${blockNum}: ${memberResults.length} players, totalPoints=${totalPoints}, blockReward=${blockRewardWei.toString()}`);

    // S3-010（2026-07-29）: 通常集計と同じ順序
    //   tree publish → proofs → manifest anchor → **root 提出（最後）**
    // にそろえた。旧実装は root をオンチェーンへ提出してから proof / manifest を作っており、
    // 「root 提出済み ⇒ proof・検証バンドル準備済み」という通常集計の不変量が
    // 自動配布ブロックだけ成立しなかった。root 提出は検証期間・請求期間を開始させるので、
    // 提出後に proof 生成が失敗すると**利用者は請求可能期間に入ったのに proof を取得できない**。
    // root 提出を唯一の最終コミット点にすれば、途中の失敗は「まだ始まっていない」に倒れる
    // （autoDistribute は決定論的・全書き込みが冪等なので再実行で自己回復する）。

    // 1. 公開データ summary.json から Merkle ツリー生成 → R2 公開（オンチェーン提出はしない）
    let pub = autoProgress.merkle || null;
    if (!completed('merkle')) {
      pub = await this.publishMerkleTree(blockNum, blockSummary);
      if (!pub?.ok) throw new Error(`[merkle] auto-distribute block ${blockNum}: publish failed`);
      await checkpoint('merkle', { merkle: pub });
    }

    // 2. proof ファイル事前生成（葉は最大約100個=1レンジ。失敗は throw → startGrouping の
    //    catch → failed → 再実行で自己回復）
    if (!completed('proofs') && pub?.ok && pub.leafCount > 0) {
      const proofRes = await this.dispatchBuildProofs(blockNum, 0, pub.leafCount);
      if (proofRes.written !== pub.leafCount) {
        throw new Error(`[proofs] auto-distribute block ${blockNum}: written ${proofRes.written} != leafCount ${pub.leafCount}`);
      }
    }
    if (!completed('proofs')) await checkpoint('proofs');

    // 3. 検証バンドルmanifest公開＋オンチェーンアンカー（改善C。自動配布はグループアーカイブ無し）
    let verification = autoProgress.verification || null;
    if (!completed('manifest')) {
      await this.publishEmptyEvidenceSegmentArtifact(blockNum);
      verification = await this.publishVerificationManifest(blockNum, []);
      if (!verification?.ok) {
        const wait = adminTxWaitOf(verification);
        if (wait) {
          // checkpointを進めず同じmanifest段を保つ。startGrouping側へ返し、正常な確定待ちと
          // admin_freezeは予算非消費、不達・照合障害・期限超過はresumeAttemptsを消費する。
          await this.recordVerificationAdminTxWait(blockNum, verification, wait, 'auto_distribute');
          return {
            pending: true,
            stage: 'manifest',
            waitReason: wait.waitReason,
            retryInMs: wait.delay,
            waitDetail: wait.detail,
            totalPoints,
            blockReward: blockRewardWei.toString(),
            verification,
          };
        }
        await this.recordVerificationPublishFailure(blockNum, verification);
        throw new Error(`[verification] auto-distribute block ${blockNum}: ${verification?.error || 'manifest failed'}`);
      }
      // 後段のadminCommit待ちが既にある再入では連続待機の時計を切らない。
      await this.clearVerificationPublishFailure(blockNum, { preservePendingPeriod: true });
      await this.clearVerificationAdminFreeze(blockNum);
      await checkpoint('manifest', { verification });
    }

    // 4. root pipeline（zkProof→adminCommit）もcheckpoint化する。pendingは成功扱いにせず、
    // grouping watchdogから同じ選出を再検証した後に再driveする。
    const merkle = await this.finalizePublishedRootWithPipeline(blockNum, {
      merkle: pub,
      verification,
      groupCount: 0,
      totalPoints: String(totalPoints),
      blockRewardWei: blockRewardWei.toString(),
      adminTxFailureOwner: 'grouping',
    });
    await checkpoint('root_pipeline', { merkle });
    const wait = adminTxWaitOf(merkle);
    if (wait) {
      await this.recordVerificationAdminTxWait(blockNum, merkle, wait, 'auto_distribute');
      return {
        pending: true,
        stage: wait.detail.stage || merkle?.submit?.stage || 'adminCommit',
        waitReason: wait.waitReason,
        retryInMs: wait.retryInMs,
        waitDetail: wait.detail,
        totalPoints,
        blockReward: blockRewardWei.toString(),
        merkle,
        verification,
      };
    }
    if (!merkle?.submit?.submitted) {
      return {
        pending: true,
        stage: merkle?.submit?.stage || merkle?.submit?.reason || 'root_pipeline',
        totalPoints,
        blockReward: blockRewardWei.toString(),
        merkle,
        verification,
      };
    }
    await this.clearVerificationAdminTxWait(blockNum);

    const result = {
      totalPoints,
      blockReward: blockRewardWei.toString(),
      merkle,
      verification,
      memberResults: memberResults.map(m => ({
        uid: m.uid,
        depositPoints: m.depositPoints,
        totalPoints: m.totalPoints,
        btcuReward: m.btcuReward
      }))
    };
    await checkpoint('done', { result, completedAt: Date.now() });
    await this.clearRosterGateTimelineWait(blockNum);
    return result;
  }

  // ============================================================
  // グループ分けアルゴリズム（主要言語の動的決定 + グループ形成）
  // ============================================================

  // 選出人数の上限は 2100 固定。環境変数では上書きしない。
  // 本番は引数なしで呼び、現実的な人数で境界を試すテストだけ正の整数を引数で渡す。
  getMaxPlayers(override) {
    return Number.isInteger(override) && override > 0 ? override : GAME_MAX_PLAYERS;
  }

  // 選出データ照合の1回あたり実時間予算。任意の調整つまみで、宣言・配布なしは意図的。
  // 未設定なら selection-integrity 側の既定を使う。
  // 内部レビュー（2026-08-07）: 旧実装は `parseInt(...)` の結果を無検査で wallBudgetMs へ渡していた。
  // 'abc' のような値だと NaN が入り、`Date.now() - start > NaN` が常に false ＝ **一度も yield しない**
  // → 予算切れ検出が消えて CPU 上限で死に、A6 の乗っ取りで同じことを繰り返す。
  // 非負の有限値でなければ null（＝渡さない＝既定を使う）。
  // 0 は「1ファイルごとに必ず yield する」という**意味のある値**なので受け付ける
  //（selection-integrity-test.mjs の自動再開テストが使っている）。
  getSelectionVerifyBudgetMs() {
    const v = parseInt(this.env?.GAME_SELECTION_VERIFY_BUDGET_MS);
    return Number.isFinite(v) && v >= 0 ? v : null;
  }

  // --- 主要言語（同言語グループ化を優先する言語）の動的決定 ---
  //
  // 主要言語は「前ブロックの失格していない採掘者」が
  // MAJOR_LANG_MIN_COUNT 人以上いる言語のみ。
  // - ブロック0: 前ブロックが無いため主要言語なし（[]）= 全員ミックス。
  // - ブロック1以降:
  //     - 前ブロックがゲーム無し（応募2名以下＝自動配布、またはプレイヤー0名）→ 主要言語なし（[]）。
  //     - 前ブロックでゲームが実施されたが結果が未確定（3名以上なのにsummary.jsonが無い／未集計）
  //       → エラー終了。（前ブロック完了後に手動でグループ分けを再実行する運用）
  //     - それ以外（結果確定済み）→ 前ブロック非失格採掘者の言語別人数で決定。
  // - どの言語も MAJOR_LANG_MIN_COUNT 人未満なら主要言語なし（[]）= 全員ミックス。
  async computeMajorLangs(blockNum) {
    // 内部レビュー（2026-08-07）: `Number(blockNum)` の結果を無検査で使っていた。garbage が来ると
    // n=NaN → prevBlock=NaN → `games/blockNaN/summary.json` を読みに行き、最終的に
    // MAJOR_LANG_PREV_NOT_READY（「前ブロックの結果が未確定」）という**嘘の診断**で止まる。
    // `null` はさらに悪く、`Number(null) === 0` なのでブロック0扱い＝主要言語なしで通っていた。
    // 受けるのは「数値」または「10進表記の文字列」だけ。原因が引数の型だと分かる形で落とす。
    const n = (typeof blockNum === 'number' || (typeof blockNum === 'string' && /^[0-9]+$/.test(blockNum)))
      ? Number(blockNum) : NaN;
    if (!Number.isSafeInteger(n) || n < 0) {
      throw new Error(`computeMajorLangs: invalid blockNum ${JSON.stringify(blockNum)} (expected a non-negative integer)`);
    }

    // ブロック0: 前ブロックが無いため主要言語なし
    if (n === 0) {
      return [];
    }

    // ブロック1以降: 前ブロックの非失格採掘者の言語比で決定
    const prevBlock = n - 1;
    const prevSummary = await this.getR2Object(`games/block${prevBlock}/summary.json`);

    if (!prevSummary) {
      // 🔴 Q-5（2026-08-08・ユーザー確定）: **`game_selection.json` へのフォールバックを削除した。**
      //
      //    旧実装はここで `entries/block{prev}/game_selection.json` を読み、
      //    `players.length <= 2` なら「ゲーム無し」とみなして `[]` を返していた。
      //    根拠にしていたコメント「プレイヤー0名の場合は startGrouping が summary を
      //    書かずに終了する」は**実装と食い違う古い記述**で、いまは
      //    `finalizeNoGameBlock`（:544-565）が 0名ブロックでも `summary.json` を
      //    `putR2ObjectOrThrow` で必ず書く（`noGame: true` / `majorLangs: []` を中に持ち、
      //    検証 manifest も公開する）。自動配布も同じ。
      //    ＝「ゲームが有ったか無かったか」は summary.json の中に書いてあるので、
      //      `game_selection.json` を見る必要が無い。
      //
      //    🔴 消した理由は「不要だから」だけではない。`game_selection.json` は
      //    **前ブロックの結果 manifest がアンカーしていない**ファイル
      //    （manifest の files に載るのは当該ブロックのぶんだけ）なので、
      //    この経路は「検証されていない入力でグループ分けの主要言語が決まる」穴だった。
      //    ZKP（Stage 4）と検証ツールは独立した2層防御という位置付けなので、
      //    ツール側だけでも塞ぐ（`block-verifier/src/stages/grouping.js` も同時に修正）。
      //    入力経路を1本にするほうが、食い違いを検出するより確実。
      const error = new Error(
        `MAJOR_LANG_PREV_NOT_READY: 前ブロック${prevBlock}のsummary.jsonが見つかりません（結果未確定）。` +
        `ブロック${prevBlock}は chatCloseAt 後かつ結果窓終了+安全ブロック後に` +
        ` /advance-phase で chatting→submitting→completed まで進めてください。` +
        ` /calculate-results 単独では group archive が無く scoring が park します。` +
        `前ブロック完了後にグループ分けを再実行してください。`
      );
      error.timelineUnverified = true;
      error.timelineCause = 'previous_block_not_ready';
      error.timelineRetryMs = GROUPING_DEPENDENCY_RETRY_MS;
      throw error;
    }

    this.assertPrevSummarySchemaVersion(prevSummary, prevBlock);

    // 前ブロックが自動配布（応募2名以下・ゲーム無し）→ 主要言語なし
    if (prevSummary.autoDistributed === true) {
      console.log(`Block ${prevBlock} was auto-distributed; no major languages.`);
      return [];
    }

    // 前ブロックがゲーム無し（プレイヤー0名 → noGame:true・groups空）→ 主要言語なし。
    // 0名ブロックの summary は autoDistributed を持たず noGame:true を立てて groups:[] を書く
    // （line 2278付近）。この場合 groups が空なので下の resultsReady 判定では常に未確定扱いに
    // なってしまい、集計は完了しているのに MAJOR_LANG_PREV_NOT_READY で誤エラーになる。
    if (prevSummary.noGame === true) {
      console.log(`Block ${prevBlock} had no game (noGame; 0 players); no major languages.`);
      return [];
    }

    // 結果確定済み判定: 全グループが 'completed'（buildBlockSummaryWithResultsの出力）。
    // フェーズ遷移中(formed/waiting/chatting/submitting)は未確定とみなしエラー終了。
    const resultsReady = Array.isArray(prevSummary.groups)
      && prevSummary.groups.length > 0
      && prevSummary.groups.every(g => g.status === 'completed');
    if (!resultsReady) {
      const error = new Error(
        `MAJOR_LANG_PREV_NOT_READY: 前ブロック${prevBlock}の結果が未確定です。` +
        `ブロック${prevBlock}は chatCloseAt 後かつ結果窓終了+安全ブロック後に` +
        ` /advance-phase で chatting→submitting→completed まで進めてください。` +
        ` /calculate-results 単独では group archive が無く scoring が park します。` +
        `前ブロック完了後にグループ分けを再実行してください。`
      );
      error.timelineUnverified = true;
      error.timelineCause = 'previous_block_not_ready';
      error.timelineRetryMs = GROUPING_DEPENDENCY_RETRY_MS;
      throw error;
    }

    // 非失格採掘者（is_disqualified !== 1）の言語を集計
    return this.langsAboveThreshold(this.tallyPrevBlockLangs(prevSummary, prevBlock));
  }

  // ============================================================
  // 前ブロック completed summary → 言語別の非失格採掘者数（fail-closed）
  // ============================================================
  // 🔴 外部レビュー（2026-08-07・⑥）で実測された穴。旧実装は
  //     `for (const m of (g.members || []))` ／ `if (m.is_disqualified === 1) continue;`
  //   と書かれており、**壊れた前ブロック結果から黙って部分集計**していた:
  //     ・{status:'completed', member_count:4} で members が欠けている → [] を返す（エラーにならない）
  //       ＝「前ブロックの結果を読んだ」ふりをして全員ミックスへ倒せる
  //     ・同じ userId を200回複製した summary → ['en']（水増しで主要言語を作れる）
  //     ・is_disqualified: true（boolean）の200人 → ['en']（=== 1 が false なので**非失格**扱い。
  //       失格者だけの言語を主要言語に昇格できる）
  //
  //   主要言語は「同言語グループを作るか／マイナーを混ぜるか」を決める＝結託耐性の根幹なので、
  //   壊れた入力は throw して止める（MAJOR_LANG_PREV_NOT_READY と同じく、前ブロックを直してから
  //   グループ分けを再実行する運用に落ちる）。block-verifier も同じコードを実行するため、
  //   運営がここを黙って通した場合は検証ツール側が同じ例外で FAIL する。
  assertPrevSummarySchemaVersion(prevSummary, prevBlock) {
    const schemaVersion = prevSummary?.schemaVersion === undefined ? 1 : prevSummary.schemaVersion;
    if (!Number.isSafeInteger(schemaVersion) || schemaVersion <= 0) {
      throw new Error(`MAJOR_LANG_PREV_INVALID: 前ブロック${prevBlock}のsummary.jsonが不正です — schemaVersion は正の安全整数である必要があります`);
    }
    return schemaVersion;
  }

  tallyPrevBlockLangs(prevSummary, prevBlock) {
    const bad = (msg) => {
      throw new Error(`MAJOR_LANG_PREV_INVALID: 前ブロック${prevBlock}のsummary.jsonが不正です — ${msg}`);
    };
    const groups = prevSummary?.groups;
    if (!Array.isArray(groups) || groups.length === 0) bad('groups が配列でないか空');

    // 🔴 P-2026-0823（2026-08-07）: **`Object.create(null)`**。`normalizeLang` は
    //   `trim().toLowerCase()` するだけなので `constructor` / `__proto__` はそのまま残る
    //   （両方すでに小文字）。素の `{}` だと
    //     lang=`constructor` → `counts['constructor'] || 0` が **Object 関数（truthy）**を返し
    //       `Object + 1` の文字列連結になる → `count >= minCount` が常に false
    //     lang=`__proto__`   → 数値代入が黙って捨てられ `Object.entries` にも出ない
    //   ＝その言語は人数がいくら居ても主要言語にならない。majorLangs は summary.json に
    //   公開され block-verifier が厳密照合するので、グループ分けの前提そのものが割れる。
    const counts = Object.create(null);
    const strictLeanV2 = this.assertPrevSummarySchemaVersion(prevSummary, prevBlock) >= 2;
    let total = 0;
    const seenUids = new Set();
    for (let i = 0; i < groups.length; i++) {
      const g = groups[i];
      if (!g || typeof g !== 'object' || Array.isArray(g)) bad(`groups[${i}] がオブジェクトでない`);
      if (!Array.isArray(g.members)) bad(`groups[${i}] (group_id=${g.group_id}) に members 配列が無い`);
      // 正典 writer（buildBlockSummaryWithResults）は member_count を必ず書く。
      // 省略された古い/合成 summary は許すが、書いてあるなら実件数と一致していなければならない。
      if (g.member_count !== undefined && g.member_count !== null && g.member_count !== g.members.length) {
        bad(`groups[${i}] (group_id=${g.group_id}) member_count=${g.member_count} だが members は ${g.members.length} 件`);
      }
      for (let j = 0; j < g.members.length; j++) {
        const m = g.members[j];
        if (!m || typeof m !== 'object' || Array.isArray(m)) bad(`groups[${i}].members[${j}] がオブジェクトでない`);
        const uid = m.userId;
        // 🔴 P-2026-0831（2026-08-08・ユーザー確定 (A)「利用者IDの形式は文字列で統一する」）:
        //   旧実装は数値 userId も受理していた。正典の writer
        //   （`buildBlockSummaryWithResults` / `buildAutoDistributeSummary` はいずれも
        //   `userId: m.uid` ＝名簿値）は**必ず文字列**を書くので、正規の summary.json は
        //   1件もここで落ちない。summary.json は R2（＝運営が書ける）なので、
        //   受け側だけが型を緩めていると「正典が書けない形」を検査が通す状態になる。
        //   ⚠️ 集計そのものは変わらない（`String(uid)` で重複排除しているので
        //      `1` と `"1"` は元から同一人物として数えていた）。型の口を揃えるだけ。
        if (typeof uid !== 'string') {
          bad(`groups[${i}].members[${j}] の userId が文字列でない (${JSON.stringify(uid)})`);
        }
        const key = uid;
        if (key === '') bad(`groups[${i}].members[${j}] の userId が空`);
        if (seenUids.has(key)) bad(`userId ${key} が重複している（同一人物を複数回集計させない）`);
        seenUids.add(key);
        // 失格フラグは厳密に 0 / 1。true / '1' / null などは「判定不能」として止める
        //（=== 1 の素通りで失格者を非失格として数える経路を塞ぐ）。
        if (m.is_disqualified !== 0 && m.is_disqualified !== 1) {
          bad(`groups[${i}].members[${j}] (userId=${key}) の is_disqualified が 0|1 でない (${JSON.stringify(m.is_disqualified)})`);
        }
        if (m.is_disqualified === 1) continue;
        total++;
        // R22-F1: schema v2 lean summaryはwriterがentryと同じ正準langを必ず書く。
        // この経路で欠落/空/大文字/前後空白/32文字超を unknown へ丸めると、
        // 運営が主要言語を無音で消せる。旧inline schemaだけは従来の正規化読取を維持。
        if (strictLeanV2 && !isCanonicalLang(m.lang)) {
          bad(`groups[${i}].members[${j}] (userId=${key}) のlangがentry正準形でない (${JSON.stringify(m.lang)})`);
        }
        // 周11 A-1（2026-09-04）: 非 strict（旧 inline schema）経路にも文字集合検査を掛ける。
        // 🔴 ここが無いと `normalizeLang` の `toLowerCase()` が Unicode 表に依存したまま残り、
        //    JS と Rust が**別のバケット鍵**へ黙って振り分ける（Err にすらならない）。
        //    正規化は「trim → 小文字化 → 32 で切る → trim」なので、最初の trim の後が
        //    ASCII 英数字・ハイフンだけなら小文字化は ASCII しか触らず、どちらの表が
        //    更新されても結果は永久に一致する。
        //    ↔ Rust `crates/stage4-core/src/major_langs.rs` の非 strict 分岐と同一条件。
        if (!strictLeanV2
            && !hasOnlyBcp47LangCharacters(typeof m.lang === 'string' ? m.lang.trim() : '')) {
          bad(`groups[${i}].members[${j}] (userId=${key}) のlangがBCP 47の文字集合外 (${JSON.stringify(m.lang)})`);
        }
        const lang = normalizeLang(m.lang);
        counts[lang] = (counts[lang] || 0) + 1;
      }
    }
    return { counts, total };
  }

  // 人数が minCount 以上の「実言語」を返す（null/unknownは主要言語候補から除外）。
  // ⑤（2026-08-07）: 戻り値は**辞書順**。旧実装は Object.entries の挿入順＝前ブロック
  // summary を走査した順だったため、同じ集合でも走査順が変われば ['en','ja'] / ['ja','en']
  // と別の配列になった。この配列は summary.json に公開され、block-verifier が
  // 厳密一致で照合するので、一意な規則へ固定する。
  langsAboveThreshold({ counts, total }, minCount = MAJOR_LANG_MIN_COUNT) {
    if (!total) return [];
    const result = [];
    for (const [lang, count] of Object.entries(counts)) {
      if (!lang || lang === 'unknown') continue;
      if (count >= minCount) result.push(lang);
    }
    result.sort();
    return result;
  }

  // ============================================================
  // formGroups の入口検査＋正準順序（⑤⑦・2026-08-07）
  // ============================================================
  // 🔴 外部レビュー ⑤ で実測された穴:
  //   12人・全員 en・seed="seed"・主要言語=["en"] で、players を昇順で渡した場合と
  //   逆順で渡した場合にグループ分けが変わった（u8 が group 0 → group 2 へ移動）。
  //   bucket が入力配列の順序をそのまま保持し、決定論的シャッフルは
  //   「その配列上の位置」を入れ替えるだけなので、入力順が結果に残っていた。
  //   グループ分けの結果は entries/block{N}/game_groups.json として manifest →
  //   オンチェーンにアンカーされ、block-verifier が独立再現して**厳密一致**で照合する。
  //   同じ論理的集合から2通りの正解が作れる状態は、その照合の前提を壊す。
  //
  // 🔴 同 ⑦: 2人入力が group size [2] を返し、uid 重複 ["same","same","other"] が
  //   3人グループとしてそのまま通り、randomSeed=undefined でも正常終了していた。
  //   2人以下は呼び出し元（startGrouping:2851）の自動配布経路だけが扱う領域であり、
  //   ここへ来ること自体が前提違反。undefined の seed は "undefined:maj:en" という
  //   もっともらしいハッシュ入力になって黙って通る（＝seed 未設定に気づけない）。
  //
  // 正準順序のキー:
  //   第一に globalIndex（lottery-DO.collectWinnerData / block-verifier buildPlayers が
  //   共に昇順で作る値＝本番では既に昇順なので、この整列は**本番の出力を変えない**）。
  //   globalIndex を持たない合成入力では uid の辞書順へ落とす。
  //   どちらも「検証済みで一意」であることを先に確かめてから使う。
  validateAndOrderPlayers(players, randomSeed) {
    if (!Array.isArray(players)) {
      throw new Error(`formGroups: players must be an array (got ${Object.prototype.toString.call(players)})`);
    }
    if (players.length < 3) {
      throw new Error(
        `formGroups: needs at least 3 players (got ${players.length}) — ` +
        `1〜2名は startGrouping の自動配布経路が扱う（グループは作らない）`
      );
    }
    if (typeof randomSeed !== 'string' || randomSeed.length === 0) {
      throw new Error(
        `formGroups: randomSeed must be a non-empty string (got ${JSON.stringify(randomSeed)}) — ` +
        `本番は deriveGroupSeed(randao, applicantHash) の keccak256`
      );
    }

    const uids = new Set();
    const gidx = new Set();
    let allHaveGlobalIndex = true;
    for (let i = 0; i < players.length; i++) {
      const p = players[i];
      if (!p || typeof p !== 'object' || Array.isArray(p)) {
        throw new Error(`formGroups: players[${i}] is not an object`);
      }
      const uid = p.data?.uid;
      // 🔴 P-2026-0831（2026-08-08・ユーザー確定 (A)「利用者IDの形式は文字列で統一する」）:
      //   旧実装は `typeof uid === 'number'` も受理し、`String(uid)` で鍵にしていた。
      //   `game_selection.json` は R2（＝運営が書ける）なので、数値 uid の名簿が
      //   **グループ分けを通過して D1 game_groups へ書かれ、ゲームが丸ごと進行した後**、
      //   採点本体の `memberUids.every(isCanonicalUid)` で
      //   `[calc] invalid member roster` を投げる ＝ **入力が不変のままブロックが park**
      //   （リトライも `/reset-block` も同じ壁）。Rust 側（`group-host`）は
      //   `m["uid"].as_str().unwrap()` なので数値 uid をそもそも読めない。
      //   受け側を採点本体と**同じ述語**（`isCanonicalUid` ＋ escape後のuid長）に揃え、park ではなく
      //   グループ分け時点（＝まだやり直せる段階）で落とす。
      //   ⚠️ 数字でない uid は FINAL で証明不可。凍結した採点の核は鍵・値の \ を拒む。
      //   本当の守りは応募の入口（1〜20桁の数字）。isCanonicalUid の広さは維持。
      if (!isCanonicalUid(uid) || uidEscapedLength(uid) > MAX_UID_BYTES) {
        throw new Error(`formGroups: players[${i}] has no usable data.uid (${JSON.stringify(uid)}) — uid must be a canonical (ASCII-printable, non-empty, escaped length <= ${MAX_UID_BYTES}) string`);
      }
      // R-4.6: 必ず normalizeLang の slice(0, 32) **後**を検査する。
      // well-formed な入力でも切り詰めがサロゲートペアを分断しうるため、入力原文の検査では不足する。
      const normalizedLang = normalizeLang(p.data?.lang);
      if (!isWellFormedLangUtf16(normalizedLang)) {
        throw new Error(`formGroups: players[${i}] has an ill-formed normalized data.lang (${JSON.stringify(normalizedLang)})`);
      }
      // 周11 R11-C01: ↔ Rust `crates/stage4-core/src/grouping.rs:221` と同一条件
      //   （`!normalized.is_well_formed() || !normalized.has_only_bcp47_lang_characters()`）。
      if (!hasOnlyBcp47LangCharacters(normalizedLang)) {
        throw new Error(`formGroups: players[${i}] has a normalized data.lang outside the canonical character domain (${JSON.stringify(normalizedLang)})`);
      }
      const uidKey = String(uid);
      if (uids.has(uidKey)) {
        throw new Error(`formGroups: duplicate uid ${uidKey} at players[${i}] — 同一人物を複数グループに入れない`);
      }
      uids.add(uidKey);

      const gi = p.globalIndex;
      if (gi === undefined || gi === null) {
        allHaveGlobalIndex = false;
      } else if (!Number.isSafeInteger(gi) || gi < 0) {
        throw new Error(`formGroups: players[${i}] has invalid globalIndex ${JSON.stringify(gi)}`);
      } else {
        if (gidx.has(gi)) {
          throw new Error(`formGroups: duplicate globalIndex ${gi} at players[${i}]`);
        }
        gidx.add(gi);
      }
    }
    // 一部だけ globalIndex を持つ入力は、どちらのキーで並べるか一意に決まらない＝前提違反。
    if (!allHaveGlobalIndex && gidx.size > 0) {
      throw new Error('formGroups: globalIndex is present on some players but not all — 整列キーが一意に決まらない');
    }

    const ordered = [...players];
    if (allHaveGlobalIndex) {
      ordered.sort((a, b) => a.globalIndex - b.globalIndex);
    } else {
      ordered.sort((a, b) => {
        const x = String(a.data.uid); const y = String(b.data.uid);
        return x < y ? -1 : x > y ? 1 : 0;
      });
    }
    return ordered;
  }

  // --- グループ形成 ---
  //
  // 結託防止のため、非主要(マイナー)言語のプレイヤーはできる限り主要言語と混ぜる。
  //  Step 1: 主要言語バケット / マイナープールに分類。
  //  Step 2: 非主要が当選者の10%以下なら3:1、それ以外は2:2を目標に主要言語から
  //          ミックスプールへ比例拠出する。
  //  Step 3: 残った主要言語は同言語グループ。ミックスでは非主要を組間へ分散し、
  //          主要を同言語で連続配置する。各グループは3〜5人。
  // ランダム選択はrandomSeed(SHA-256ベース)で決定論的に行う。
  async formGroups(players, randomSeed, majorLangs = []) {
    // ⑦（2026-08-07）: 純関数としての前提を入口で assert する。
    // ⑤（2026-08-07）: 入力順に依存しないよう、検証済みの一意キーで正準順序へ並べ替える。
    const ordered = this.validateAndOrderPlayers(players, randomSeed);

    // 周11 R11-C01: ↔ Rust `crates/stage4-core/src/grouping.rs:78-88` と同一条件。
    //   majorLangs は前ブロック summary 由来＝R2（運営が書ける）なので、
    //   ここも受け側で値域を強制する（Rust だけが Err になる非対称を作らない）。
    const majorSet = new Set((majorLangs || []).map((raw) => {
      const normalized = normalizeLang(raw);
      if (!isWellFormedLangUtf16(normalized) || !hasOnlyBcp47LangCharacters(normalized)) {
        throw new Error(`formGroups: major lang is outside the canonical character domain (${JSON.stringify(raw)})`);
      }
      return normalized;
    }).filter(l => l && l !== 'unknown'));

    // === Step 1: 主要言語バケット / マイナープールに分類 ===
    // 🔴 P-2026-0823（2026-08-07）: lang を鍵にする辞書はすべて **`Object.create(null)`**。
    //   `counts` を直した結果 `constructor` / `__proto__` も正しく主要言語になりうるので、
    //   ここを素の `{}` のまま残すと `!majorBuckets[lang]` が Object 関数（truthy）を拾って
    //   初期化を飛ばし、`majorBuckets[lang].push(...)` が TypeError になる（穴の移動）。
    const majorBuckets = Object.create(null);
    const minorPool = [];
    for (const player of ordered) {
      const lang = normalizeLang(player.data?.lang);
      if (majorSet.has(lang)) {
        if (!majorBuckets[lang]) majorBuckets[lang] = [];
        majorBuckets[lang].push(player);
      } else {
        minorPool.push(player);
      }
    }
    const majTotal = Object.values(majorBuckets).reduce((s, b) => s + b.length, 0);
    const minTotal = minorPool.length;

    // === Step 2: 10%以下は3:1、それ以外は2:2を目標に比例拠出 ===
    const threeToOne = minTotal > 0 && minTotal * 10 <= ordered.length;
    const contributeTotal = Math.min(threeToOne ? 3 * minTotal : minTotal, majTotal);
    const contributions = this.proportionalContribute(majorBuckets, contributeTotal);

    const mixedPool = [...minorPool];
    const remainingMajor = Object.create(null); // lang -> 同言語グループに残るプレイヤー（P-2026-0823）
    // ⑤: 言語キーの走査順は**辞書順**に固定する。旧実装は Object.entries の挿入順＝
    //     players に各言語が最初に現れた順だったため、同じ集合でも並べ替えると
    //     mixedPool の連結順・remainingMajor の走査順（= groupId の割り当て順）が変わった。
    for (const lang of Object.keys(majorBuckets).sort()) {
      const bucket = majorBuckets[lang];
      const shuffled = await this.seededShuffle(bucket, randomSeed, `maj:${lang}`);
      const k = contributions[lang] || 0;
      mixedPool.push(...shuffled.slice(0, k));
      remainingMajor[lang] = shuffled.slice(k);
    }

    // === Step 3: グループ形成（各グループ3〜5人） ===
    const groups = [];
    const idRef = { v: 0 };

    // 3a. 残った主要言語 → 同言語グループ。3人未満ならミックスへ回す
    //     ⑤: ここも辞書順（groupId 0..N-1 の割り当て順が入力順に依存しないように）
    for (const lang of Object.keys(remainingMajor).sort()) {
      const rem = remainingMajor[lang];
      if (rem.length === 0) continue;
      if (rem.length < 3) { mixedPool.push(...rem); continue; }
      const ordered = await this.seededShuffle(rem, randomSeed, `majgrp:${lang}`);
      this.dealIntoGroups(ordered, groups, idRef);
    }

    // 3b. ミックスプール → 非主要は分散、主要は同言語で連続配置
    if (mixedPool.length >= 3) {
      const ordered = await this.languageRoundRobinOrder(mixedPool, randomSeed, majorSet);
      dealMixedGroups(ordered, majorSet, groups, idRef);
    } else if (mixedPool.length > 0) {
      // 端数(1〜2名)を既存グループへ混ぜる（6人以上になるなら再分割し3〜5人を維持）
      this.absorbStragglers(mixedPool, groups, idRef);
    }

    // groupId を 0..N-1 に振り直し、lang / mixed をメンバーから確定
    let gid = 0;
    for (const g of groups) {
      g.groupId = gid++;
      const langs = new Set(g.members.map(m => normalizeLang(m.data?.lang)));
      g.mixed = langs.size > 1;
      g.lang = g.mixed ? 'mixed' : normalizeLang(g.members[0]?.data?.lang);
    }

    return groups;
  }

  // 主要言語からミックスプールへの拠出数を当選者数に比例配分（最大剰余法）
  proportionalContribute(majorBuckets, total) {
    const langs = Object.keys(majorBuckets);
    // P-2026-0823: lang 鍵の辞書は `Object.create(null)`。素の `{}` だと lang=`__proto__` の
    // `result[l] = 0` が捨てられ、`contributions[lang] || 0` が Object.prototype（truthy）に
    // なって `slice(0, {})` ＝拠出0扱いのまま比例配分の帳尻だけが崩れる。
    const result = Object.create(null);
    for (const l of langs) result[l] = 0;
    const majTotal = langs.reduce((s, l) => s + majorBuckets[l].length, 0);
    if (total <= 0 || majTotal === 0) return result;
    if (total >= majTotal) { // 全員拠出
      for (const l of langs) result[l] = majorBuckets[l].length;
      return result;
    }
    const fracs = [];
    let used = 0;
    for (const l of langs) {
      const exact = total * majorBuckets[l].length / majTotal;
      result[l] = Math.floor(exact);
      used += result[l];
      fracs.push({ l, frac: exact - Math.floor(exact) });
    }
    // 残りを小数部の大きい言語へ（同値は言語名で決定論的に）
    fracs.sort((a, b) => b.frac - a.frac || (a.l < b.l ? -1 : 1));
    let left = total - used;
    for (let i = 0; i < fracs.length && left > 0; i++) {
      const l = fracs[i].l;
      if (result[l] < majorBuckets[l].length) { result[l]++; left--; }
    }
    return result;
  }

  // 決定論的Fisher-Yatesシャッフル（seed + saltで再現可能）
  async seededShuffle(arr, seed, salt) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = await deterministicRandom(`${seed}:${salt}`, i, i + 1);
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  // ミックスプールを言語別にまとめ（主要言語を先にし、各クラス内はサイズ降順→UTF-16順）。
  // この順で i%G にラウンドロビン配分すると、主要言語と同一言語を最大限分散する。
  async languageRoundRobinOrder(pool, randomSeed, majorSet = new Set()) {
    // 🔴 P-2026-0823（2026-08-07）: **`Object.create(null)`**。ここの lang は
    //   `majorSet` の篩を通っていない**生の自己申告言語**（マイナー言語は全員ここへ来る）。
    //   `normalizeLang` の `toLowerCase()` を素通りする Object.prototype 名は
    //   **`constructor` と `__proto__` の2つ**（他は `tostring` 等になって無害）。
    //   素の `{}` だとこの2つで `!byLang[lang]` が truthy（Object 関数 / Object.prototype）を
    //   拾って初期化を飛ばし、`byLang[lang].push(p)` が **TypeError** になる。
    //   ＝参加者ひとりがプロフィール言語を書き換えるだけで**ブロック全体のグループ分けが
    //   決定論的に失敗**する（入力が同じなので再実行しても同じ壁）。
    const byLang = Object.create(null);
    for (const p of pool) {
      const lang = normalizeLang(p.data?.lang);
      if (!byLang[lang]) byLang[lang] = [];
      byLang[lang].push(p);
    }
    const langsSorted = Object.keys(byLang).sort((a, b) => {
      const aMajor = majorSet.has(a);
      const bMajor = majorSet.has(b);
      if (aMajor !== bMajor) return aMajor ? -1 : 1;
      return byLang[b].length - byLang[a].length || (a < b ? -1 : 1);
    });
    const ordered = [];
    for (const lang of langsSorted) {
      ordered.push(...await this.seededShuffle(byLang[lang], randomSeed, `mix:${lang}`));
    }
    return ordered;
  }

  // 並べ替え済みリストを 3〜5人のグループへ分配（i % G のラウンドロビン）。
  //   G = max(floor(P/4), ceil(P/5)) … 端数を5人組に吸収しつつ最大5人を保証
  dealIntoGroups(ordered, groups, idRef) {
    const P = ordered.length;
    if (P === 0) return;
    const G = Math.max(Math.floor(P / GROUP_SIZE), Math.ceil(P / (GROUP_SIZE + 1)));
    const bins = Array.from({ length: G }, () => []);
    for (let i = 0; i < P; i++) bins[i % G].push(ordered[i]);
    for (const members of bins) groups.push({ groupId: idRef.v++, mixed: false, lang: null, members });
  }

  // 端数(1〜2名)を最小人数の既存グループへ混ぜる。6人以上になる場合はそのグループを
  // 取り除いて再分割し、全グループ3〜5人を保証する。
  // （formGroupsは3名以上で呼ばれるため、ここで groups が空になることはない＝安全弁）
  absorbStragglers(stragglers, groups, idRef) {
    if (groups.length === 0) {
      groups.push({ groupId: idRef.v++, mixed: false, lang: null, members: [...stragglers] });
      return;
    }
    let target = groups[0];
    for (const g of groups) if (g.members.length < target.members.length) target = g;
    target.members.push(...stragglers);
    if (target.members.length > GROUP_SIZE + 1) {
      const idx = groups.indexOf(target);
      const members = target.members;
      groups.splice(idx, 1);
      this.dealIntoGroups(members, groups, idRef);
    }
  }

  // ============================================================
  // D1 / R2操作
  // ============================================================

  // デポジットにデポジッタープロフィール（name, img）を補完
  // entry-workerでparseIdFromProfileが未実行の場合のフォールバック
  // D1 行と公開一覧の group ID は、期待組数に対する 0..N-1 の全単射で照合する。
  hasExpectedGroupIds(rows, expectedCount, field = 'group_id') {
    if (!Number.isSafeInteger(expectedCount) || expectedCount <= 0
        || !Array.isArray(rows) || rows.length !== expectedCount) return false;
    const ids = new Set(rows.map((row) => row?.[field]));
    if (ids.size !== expectedCount) return false;
    for (let id = 0; id < expectedCount; id++) if (!ids.has(id)) return false;
    return true;
  }

  // 完了印がある新ブロックはその組数、印の無い旧ブロックは自己整合な公開一覧を権威にする。
  // D1 と公開一覧の双方を 0..N-1 の ID 集合として照らし、部分 batch を後段へ渡さない。
  async checkGroupingD1Completeness(blockNum, rows = null) {
    const complete = await this.storage.get(`grouping_d1_complete_block${blockNum}`);
    let expectedGroups = null;
    if (complete !== undefined) {
      if (Number.isSafeInteger(complete?.totalGroups) && complete.totalGroups > 0) {
        expectedGroups = complete.totalGroups;
      }
    } else if (this.env.R2_BUCKET) {
      try {
        const published = await this.getR2Object(`entries/block${blockNum}/game_groups.json`);
        if (Array.isArray(published?.groups)
            && this.hasExpectedGroupIds(published.groups, published.totalGroups, 'groupId')) {
          expectedGroups = published.totalGroups;
        }
      } catch (error) {
        const retryError = new Error(`Block ${blockNum} published group list unreadable at completeness gate: ${error?.message || error}`);
        retryError.resumable = true;
        retryError.r2ReadUnavailable = true;
        retryError.cause = error;
        throw retryError;
      }
    }
    const d1Rows = rows ?? (await this.env.BITCOINU_DATA.prepare(
      'SELECT group_id FROM game_groups WHERE block_num = ?'
    ).bind(blockNum).all()).results;
    return {
      complete: this.hasExpectedGroupIds(d1Rows, expectedGroups),
      groupCount: Array.isArray(d1Rows) ? d1Rows.length : 0,
      expectedGroups,
    };
  }

  // D1にグループ情報をバッチ書き込み
  async writeGroupsToD1(blockNum, groups) {
    const db = this.env.BITCOINU_DATA;
    if (!db) {
      throw new Error('BITCOINU_DATA binding not found');
    }

    // リトライ時の重複防止: 未進行('formed')の既存データのみ削除してからINSERT
    // 進行済み(waiting/chatting/completed等)のデータは保護
    const { results: existingRows } = await db.prepare(
      "SELECT COUNT(*) as cnt FROM game_groups WHERE block_num = ? AND status != 'formed'"
    ).bind(blockNum).all();
    if (existingRows && existingRows[0]?.cnt > 0) {
      throw new Error(`Block ${blockNum} has ${existingRows[0].cnt} groups already in progress/completed. Cannot overwrite.`);
    }
    // 部分 batch と旧世代の完了印を同時に完成済みと見なさない。
    // 印は最後の batch 成功後にだけ再作成する。
    await this.storage.delete(`grouping_d1_complete_block${blockNum}`);
    await db.prepare('DELETE FROM game_groups WHERE block_num = ?').bind(blockNum).run();

    const now = new Date().toISOString();

    // バッチINSERT（BATCH_INSERT_SIZE件ずつ）
    for (let i = 0; i < groups.length; i += BATCH_INSERT_SIZE) {
      const batch = groups.slice(i, i + BATCH_INSERT_SIZE);
      const statements = batch.map(group => {
        const membersJson = JSON.stringify(group.members.map(m => ({
          uid: m.data?.uid,
          addr: m.data?.addr,
          bAddr: m.data?.bAddr,
          lang: m.data?.lang,
          depIds: m.data?.depIds,
          globalIndex: m.globalIndex,
          name: m.data?.name || null,
          img: m.data?.img || null,
          verified: m.data?.verified || false
        })));

        return db.prepare(
          `INSERT INTO game_groups (block_num, group_id, lang, mixed, members, status, created_at) VALUES (?, ?, ?, ?, ?, 'formed', ?)`
        ).bind(blockNum, group.groupId, group.lang, group.mixed ? 1 : 0, membersJson, now);
      });

      await db.batch(statements);
      console.log(`Wrote groups ${i} to ${Math.min(i + BATCH_INSERT_SIZE, groups.length) - 1} to D1`);
    }

    await this.storage.put(`grouping_d1_complete_block${blockNum}`, { totalGroups: groups.length });
    console.log(`Total ${groups.length} groups written to D1 for block ${blockNum}`);
  }

  // フロントエンド用ブロックサマリーをR2キャッシュ向けに構築（グループ形成時・結果未確定）
  buildBlockSummaryForR2(blockNum, groups, majorLangs = []) {
    const blockReward = getBlockRewardWei(blockNum).toString();
    const summaryGroups = groups.map(g => {
      const members = g.members.map(m => {
        const depositWei = parseDepositWei(m.data?.depIds);
        const depPts = calculateDepositPoints(depositWei);
        return {
          userId: m.data?.uid,
          address: m.data?.addr || null,
          img: m.data?.img || null,
          name: m.data?.name || null,
          lang: m.data?.lang || null,
          verified: m.data?.verified || false,
          depIds: m.data?.depIds || null,
          deposit_points: depPts,
          bonus_points: null,
          total_points: null,
          is_disqualified: 0,
          disqualify_reason: null,
          btcu_reward: null
        };
      });
      return {
        group_id: g.groupId,
        lang: g.lang,
        member_count: g.members.length,
        status: 'formed',
        total_points: null,
        members
      };
    });
    // P-2026-0842（台帳 C-3）: 実行時刻（旧 `updatedAt`）は載せない（`mergeBlockSummary` の注記参照）
    return { blockNum, majorLangs: majorLangs || [], groups: summaryGroups, blockReward };
  }

  // 宣言タイムラインを summary.json 配信用の形へ（grace 込みの確定絶対時刻）。
  // フロントが env から再計算すると grace（チェーン値・extendGrace で変動）を知り得ず
  // ズレるため、サーバーが確定させた時刻をそのまま配る。
  buildSummaryTimeline(declared, graceSec) {
    if (!declared) return null;
    return {
      graceSec,
      chattingStart: declared.chattingStart,
      submittingStart: declared.submittingStart,
      closeAt: declared.closeAt,
      completedAt: declared.completedAt
    };
  }

  // R2のblock-summaryの部分更新（読み→マージ→書き）。status / timeline のうち渡された方だけ変える。
  async mergeBlockSummary(blockNum, { status = null, timeline = null } = {}) {
    const detail = (status ? ` status='${status}'` : '')
      + (timeline ? ` grace=${timeline.graceSec}s chattingStart=${new Date(timeline.chattingStart).toISOString()}` : '');

    // 書き込み競合対策（2026-07-31）: ここは典型的な read-modify-write なのに
    // 無条件 put だった。差分（status / timeline だけ差し替え）を etag 条件付きで書き、
    // 競合したら読み直して当て直す。listen-worker の `claimed` patch を巻き込まない。
    const res = await this.mutateR2ObjectWithCAS(`games/block${blockNum}/summary.json`, (existing) => {
      if (status) existing.groups = (existing.groups || []).map(g => ({ ...g, status }));
      if (timeline) existing.timeline = timeline;
      // 🔴 P-2026-0842（2026-08-08・台帳 C-3）: **`updatedAt` は書かない。**
      //    `games/block{N}/summary.json` は manifest の `artifactKeys` に載り、
      //    その sha256 が `manifestHash` に入って**オンチェーンにアンカーされる**。
      //    実行時刻を書くと同一入力の再集計でも manifestHash が変わり、
      //    `HashStorage.resultRegistrationCount` が加算されて block-verifier の
      //    「結果差し替えの可能性」WARN（`check.stageC.resultReregistration`）が
      //    無害な再実行と区別できなくなる。読む側は1箇所も無い
      //    （block-verifier の `neutralizeSummary` は元から delete している）。
      //    ⚠️ 4つある writer（ここ／`buildBlockSummary`／`buildBlockSummaryWithResults`／
      //       D1 フォールバックのキャッシュ作成）の**どれか1つでも書くと**非決定に戻る。
      //    生成時刻はオンチェーン（`HashStorage` の `updatedAt`）と
      //    `games/block{N}/claim-timing.json` に残る。
    }, { tag: 'r2' });

    if (res.missing) {
      console.log(`No existing block summary in R2 for block ${blockNum}, skipping merge`);
      return;
    }
    // S3-011: put の成否を無視して「更新した」とログしない（公開データと実状態の乖離が
    // ログ上は見えなくなるため）。呼び出し元は try/catch でこの戻り値／例外を扱う。
    if (!res.ok) {
      console.error(`[r2] Block summary update FAILED for block ${blockNum}${detail} — public timeline is now stale (${res.error || 'unknown'})`);
      return false;
    }
    console.log(`Block summary updated in R2 for block ${blockNum}${detail}`);
    return true;
  }

  // R2のblock-summaryのステータス更新（waiting→chatting→submittingなど）
  // timeline を渡すと同一書き込みでタイムラインも更新する（R2往復を1回に抑える）
  async updateBlockSummaryStatus(blockNum, newStatus, timeline = null) {
    return this.mergeBlockSummary(blockNum, { status: newStatus, timeline });
  }

  // grace 延長時など、ステータスを変えずタイムラインだけ更新する
  async updateBlockSummaryTimeline(blockNum, declared, graceSec) {
    const timeline = this.buildSummaryTimeline(declared, graceSec);
    if (!timeline) return;
    return this.mergeBlockSummary(blockNum, { timeline });
  }

  // claim / Stage 2 / Merkle 用の lean ブロックサマリーを構築（結果確定後）。
  // 表示専用フィールドは manifest 固定済みの groupG.json だけに置く（R15-F1）。
  // allGroupResults: calculateGroupResults()の結果配列
  // d1Groups: D1 game_groupsのSELECT結果（group_id, members JSON含む）
  async buildBlockSummaryWithResults(blockNum, allGroupResults, d1Groups, blockReward, depositorResults = []) {
    // 主要言語はグループ形成時のsummary.json（buildBlockSummaryForR2）から引き継ぐ
    const existingSummary = await this.getR2Object(`games/block${blockNum}/summary.json`);
    const majorLangs = existingSummary?.majorLangs || [];
    // 宣言タイムラインも同様に引き継ぐ（結果確定後にフロントが期間表示へ使う）
    const timeline = existingSummary?.timeline || null;

    // 採点結果はlangを持たない。グループ形成時に確定したD1名簿からのみ回復し、
    // schema v2には正規化済みlangを必須で書く（R22-F1）。
    const d1MembersByGroup = new Map((Array.isArray(d1Groups) ? d1Groups : []).map(row => {
      let roster;
      try { roster = typeof row?.members === 'string' ? JSON.parse(row.members) : row?.members; }
      catch { throw new Error(`SUMMARY_LANG_INVALID: block ${blockNum} group ${row?.group_id} D1 members JSONが不正`); }
      if (!Array.isArray(roster)) {
        throw new Error(`SUMMARY_LANG_INVALID: block ${blockNum} group ${row?.group_id} D1 membersが配列でない`);
      }
      return [Number(row.group_id), new Map(roster.map(m => [m?.uid, m]))];
    }));

    const summaryGroups = allGroupResults.map(g => {
      const roster = d1MembersByGroup.get(Number(g.groupId));
      if (!roster) throw new Error(`SUMMARY_LANG_INVALID: block ${blockNum} group ${g.groupId} D1名簿が無い`);
      const members = g.members.map(m => {
        const entry = roster.get(m.uid);
        if (!entry) throw new Error(`SUMMARY_LANG_INVALID: block ${blockNum} group ${g.groupId} uid ${m.uid} がD1名簿に無い`);
        return {
          userId: m.uid,
          address: m.addr || null,
          lang: canonicalSummaryLang(entry.lang, `block ${blockNum} group ${g.groupId} member ${m.uid}`),
          total_points: m.totalPoints,
          is_disqualified: m.isDisqualified ? 1 : 0,
          full_btcu_reward: m.fullReward || m.btcuReward
        };
      });

      // このグループの全デポジッター結果（自己デポジット含む）
      const groupDepositors = depositorResults
        .filter(d => d.groupId === g.groupId)
        .map(d => ({ playerUid: d.playerUid, depositId: d.depositId }));

      const totalPoints = members.reduce((sum, m) => sum + (m.total_points || 0), 0);
      return {
        group_id: g.groupId,
        member_count: members.length,
        status: 'completed',
        total_points: totalPoints,
        detailKey: `games/block${blockNum}/group${g.groupId}.json`,
        claimOverlayKey: `games/block${blockNum}/claim-status/group${g.groupId}.json`,
        members,
        depositor_results: groupDepositors
      };
    });

    // P-2026-0842（台帳 C-3）: 実行時刻（旧 `updatedAt`）は載せない（`mergeBlockSummary` の注記参照）
    return {
      schemaVersion: 3,
      blockNum,
      majorLangs,
      timeline,
      groups: summaryGroups,
      blockReward,
      resultLayout: 'group-artifacts-v1',
      claimStatusKey: `games/block${blockNum}/claim-status.json`,
      claimLayout: 'group-overlays-v1',
    };
  }

  buildInitialClaimStatus(allGroupResults, depositorResults = []) {
    let totalWei = 0n;
    let totalCount = 0;
    for (const group of (allGroupResults || [])) {
      for (const member of (group.members || [])) {
        let reward = 0n;
        try { reward = BigInt(String(member.btcuReward || '0')); } catch {}
        if (reward > 0n) { totalWei += reward; totalCount += 1; }
      }
    }
    for (const dep of (depositorResults || [])) {
      let reward = 0n;
      try { reward = BigInt(String(dep.btcuReward || '0')); } catch {}
      if (reward > 0n) { totalWei += reward; totalCount += 1; }
    }
    return { claimedCount: 0, totalCount, claimedWei: '0', totalWei: totalWei.toString() };
  }

  // グループサマリー作成
  createGroupSummary(blockNum, groups, selectionData) {
    return {
      blockNum,
      totalPlayers: selectionData.players.length,
      totalGroups: groups.length,
      randao: selectionData.randao,
      applicantHash: selectionData.applicantHash,
      groupSeed: deriveGroupSeed(selectionData.randao, selectionData.applicantHash),
      groupsByLang: this.countGroupsByLang(groups),
      mixedGroups: groups.filter(g => g.mixed).length,
      groupSizes: this.getGroupSizeDistribution(groups),
      groups: groups.map(g => ({
        groupId: g.groupId,
        lang: g.lang,
        mixed: g.mixed,
        memberCount: g.members.length,
        memberIds: g.members.map(m => m.data?.uid || m.globalIndex)
      })),
      // P-2026-0842（台帳 C-3）: 実行時刻は載せない（manifest の artifactKeys に載るため）
    };
  }

  // 言語別グループ数カウント
  countGroupsByLang(groups) {
    // P-2026-0823: `group.lang` は `normalizeLang` の出力（または 'mixed'）なので
    // `constructor` / `__proto__` になりうる。素の `{}` だと前者は文字列連結、後者は
    // 代入消失で件数が壊れる（この値は group_summary.json に載る）。
    // ⚠️ lib/grouping-integrity.js の同名ミラーも同時に直すこと。
    const counts = Object.create(null);
    for (const group of groups) {
      const lang = group.lang;
      counts[lang] = (counts[lang] || 0) + 1;
    }
    return counts;
  }

  // グループサイズ分布
  getGroupSizeDistribution(groups) {
    const distribution = {};
    for (const group of groups) {
      const size = group.members.length;
      distribution[size] = (distribution[size] || 0) + 1;
    }
    return distribution;
  }

  boundedObservationList(values, limit = GROUP_OBSERVATION_GROUP_LIMIT) {
    const list = [...new Set((values || []).map(Number).filter(Number.isSafeInteger))].sort((a, b) => a - b);
    return { values: list.slice(0, limit), omitted: Math.max(0, list.length - limit), total: list.length };
  }

  boundedTextObservationList(values, limit = MONITOR_ARTIFACT_LIMIT) {
    const list = [...new Set((values || []).filter((value) => typeof value === 'string'))].sort();
    return { values: list.slice(0, limit), omitted: Math.max(0, list.length - limit), total: list.length };
  }

  async inspectR2JsonArtifact(key, expectedSha256 = null) {
    const inspectedAt = Date.now();
    const notAttempted = (reason) => ({ state: 'not_attempted', reason });
    if (!this.env.R2_BUCKET) {
      return {
        key, inspectedAt, exists: null,
        head: notAttempted('r2_binding_missing'),
        read: notAttempted('r2_binding_missing'),
        parse: notAttempted('r2_binding_missing'),
        sha256: notAttempted('r2_binding_missing'),
        parsedValue: null,
        rawText: null,
      };
    }
    let headObject = null;
    let head;
    if (typeof this.env.R2_BUCKET.head === 'function') {
      try {
        headObject = await this.env.R2_BUCKET.head(key);
        head = this.observationResult('succeeded', {
          exists: !!headObject,
          size: Number.isFinite(Number(headObject?.size)) ? Number(headObject.size) : null,
          etag: headObject?.etag || null,
          uploadedAt: headObject?.uploaded instanceof Date ? headObject.uploaded.getTime() : null,
        });
      } catch (error) {
        head = this.observationFailure(error);
      }
    } else {
      head = notAttempted('head_unsupported');
    }

    let object = null;
    let text = null;
    let read;
    try {
      object = await this.env.R2_BUCKET.get(key);
      if (!object) {
        read = this.observationResult('succeeded', { exists: false });
      } else {
        text = await object.text();
        read = this.observationResult('succeeded', { exists: true, bytes: new TextEncoder().encode(text).byteLength });
      }
    } catch (error) {
      read = this.observationFailure(error);
    }
    const exists = read.state === 'succeeded' ? !!object : (head.state === 'succeeded' ? !!headObject : null);
    if (text == null) {
      const reason = read.state === 'failed' ? 'read_failed' : 'object_missing';
      return {
        key, inspectedAt, exists, head, read,
        parse: notAttempted(reason), sha256: notAttempted(reason), parsedValue: null, rawText: null,
      };
    }

    let parsedValue = null;
    let parse;
    try {
      parsedValue = JSON.parse(text);
      parse = this.observationResult('succeeded');
    } catch (error) {
      parse = this.observationFailure(error);
    }
    let sha256;
    try {
      const value = await this.sha256Hex(text);
      sha256 = this.observationResult('succeeded', {
        value,
        expected: expectedSha256 || null,
        matchesExpected: expectedSha256 ? value.toLowerCase() === String(expectedSha256).toLowerCase() : null,
      });
    } catch (error) {
      sha256 = this.observationFailure(error, { expected: expectedSha256 || null });
    }
    return { key, inspectedAt, exists, head, read, parse, sha256, parsedValue, rawText: text };
  }

  async inspectR2ArtifactHead(key) {
    const at = Date.now();
    if (!this.env.R2_BUCKET) return { key, state: 'not_attempted', at, reason: 'r2_binding_missing', exists: null };
    if (typeof this.env.R2_BUCKET.head !== 'function') {
      return { key, state: 'not_attempted', at, reason: 'head_unsupported', exists: null };
    }
    try {
      const object = await this.env.R2_BUCKET.head(key);
      return this.observationResult('succeeded', {
        key, exists: !!object,
        size: Number.isFinite(Number(object?.size)) ? Number(object.size) : null,
        etag: object?.etag || null,
      });
    } catch (error) {
      return this.observationFailure(error, { key, exists: null });
    }
  }

  async inspectDoneBlockArtifacts(blockNum, {
    progress = null,
    autoProgress = null,
    deep = false,
    chain = false,
    artifactCursor = 0,
  } = {}) {
    const done = progress?.stage === 'done' || autoProgress?.stage === 'done';
    if (!done) return { state: 'not_attempted', at: null, blockNum, reason: 'block_not_marked_done' };
    const at = Date.now();
    const rootOmitted = progress?.result?.rootOmittedReason === 'timeline_no_game_root_omitted'
      && progress?.zkProof?.status === 'timeline_no_game_root_omitted';
    const requiredBase = [
      `games/block${blockNum}/summary.json`,
      `merkle/block_${blockNum}.json`,
      `verification/block${blockNum}/manifest.json`,
      ...(rootOmitted ? [] : [`games/block${blockNum}/claim-timing.json`]),
    ];
    const optionalBase = [
      `merkle/block_${blockNum}_status.json`,
      `games/block${blockNum}/claim-status.json`,
      `verification/block${blockNum}/evidence-report.json`,
      `entries/block${blockNum}/game_selection.json`,
      `entries/block${blockNum}/game_groups.json`,
    ];

    if (!deep) {
      const required = await Promise.all(requiredBase.map((key) => this.inspectR2ArtifactHead(key)));
      const optional = await Promise.all(optionalBase.map((key) => this.inspectR2ArtifactHead(key)));
      const missingRequired = required.filter((item) => item.state === 'succeeded' && !item.exists).map((item) => item.key);
      const observationFailures = required.filter((item) => item.state === 'failed').map((item) => item.key);
      const notAttempted = required.filter((item) => item.state === 'not_attempted').map((item) => item.key);
      return {
        state: missingRequired.length > 0 || observationFailures.length > 0
          ? 'failed' : (notAttempted.length > 0 ? 'not_attempted' : 'succeeded'),
        at, blockNum, mode: 'head', required, optional,
        missingRequired: this.boundedTextObservationList(missingRequired),
        observationFailures: this.boundedTextObservationList(observationFailures),
        notAttempted: this.boundedTextObservationList(notAttempted),
      };
    }

    const manifestInspection = await this.inspectR2JsonArtifact(`verification/block${blockNum}/manifest.json`);
    const manifestValue = manifestInspection.parsedValue;
    const declaredFiles = manifestValue?.files && typeof manifestValue.files === 'object' ? manifestValue.files : {};
    const requiredSet = new Set(requiredBase);
    const optionalSet = new Set(optionalBase);
    const baseFileCount = new Set([...requiredBase, ...optionalBase]).size;
    const declaredEntries = Object.entries(declaredFiles);
    const manifestFileCount = declaredEntries.length;
    const declaredPageCapacity = Math.max(0, MONITOR_ARTIFACT_LIMIT - baseFileCount);
    const declaredPage = declaredEntries.slice(artifactCursor, artifactCursor + declaredPageCapacity);
    for (const [key, expected] of declaredPage) {
      (typeof expected === 'string' ? requiredSet : optionalSet).add(key);
    }
    const inspectedDeclaredFileCount = declaredPage.length;
    const nextCursorValue = artifactCursor + inspectedDeclaredFileCount;
    const hasMore = nextCursorValue < manifestFileCount;
    const uninspectedDeclaredFileCount = Math.max(0, manifestFileCount - inspectedDeclaredFileCount);
    const coverage = {
      complete: artifactCursor === 0 && !hasMore,
      truncated: uninspectedDeclaredFileCount > 0,
      cursor: artifactCursor,
      nextCursor: hasMore ? nextCursorValue : null,
      hasMore,
      limit: MONITOR_ARTIFACT_LIMIT,
      baseFileCount,
      declaredPageCapacity,
      declaredFileCount: manifestFileCount,
      inspectedDeclaredFileCount,
      remainingDeclaredFileCount: Math.max(0, manifestFileCount - nextCursorValue),
      uninspectedDeclaredFileCount,
    };
    const inspectedKeys = [...requiredSet, ...optionalSet];
    const inspections = [];
    for (let i = 0; i < inspectedKeys.length; i += 20) {
      inspections.push(...await Promise.all(inspectedKeys.slice(i, i + 20).map((key) => (
        key === `verification/block${blockNum}/manifest.json`
          ? Promise.resolve(manifestInspection)
          : this.inspectR2JsonArtifact(key, typeof declaredFiles[key] === 'string' ? declaredFiles[key] : null)
      ))));
    }
    const clean = inspections.map(({ parsedValue: _parsedValue, rawText: _rawText, ...item }) => item);
    const byKey = new Map(inspections.map((item) => [item.key, item]));
    const missingRequired = [...requiredSet].filter((key) => byKey.get(key)?.exists === false);
    const parseFailures = inspections.filter((item) => item.parse?.state === 'failed').map((item) => item.key);
    const hashMismatches = inspections.filter((item) => item.sha256?.matchesExpected === false).map((item) => item.key);
    const observationFailures = inspections.filter((item) => item.read?.state === 'failed' || item.sha256?.state === 'failed')
      .map((item) => item.key);

    let manifestIntegrity = { state: 'not_attempted', at: null, reason: 'manifest_unavailable' };
    if (manifestValue && typeof manifestValue === 'object') {
      try {
        const core = {
          blockNum: manifestValue.blockNum,
          algorithm: manifestValue.algorithm,
          rules: manifestValue.rules,
          files: manifestValue.files,
        };
        const recomputed = `0x${await this.sha256Hex(JSON.stringify(core))}`;
        manifestIntegrity = this.observationResult('succeeded', {
          declared: manifestValue.manifestHash || null,
          recomputed,
          matches: typeof manifestValue.manifestHash === 'string'
            && manifestValue.manifestHash.toLowerCase() === recomputed.toLowerCase(),
          fileCount: manifestFileCount,
          inspectedFileCount: inspectedDeclaredFileCount,
          omittedFileCount: uninspectedDeclaredFileCount,
          inspectionComplete: coverage.complete,
          inspectionCursor: artifactCursor,
          hashedFileCount: Object.values(declaredFiles).filter((value) => typeof value === 'string').length,
          optionalNullFileCount: Object.values(declaredFiles).filter((value) => value == null).length,
        });
      } catch (error) {
        manifestIntegrity = this.observationFailure(error);
      }
    }

    let merkleStatus;
    try {
      const value = await this.storage.get(`merkle_status_${blockNum}`);
      merkleStatus = value
        ? this.observationResult('succeeded', { value })
        : { state: 'not_attempted', at: null, reason: 'merkle_status_absent' };
    } catch (error) {
      merkleStatus = this.observationFailure(error);
    }
    let chainLifecycle = { state: 'not_attempted', at: null, reason: chain ? 'chain_unavailable' : 'chain_check_disabled' };
    if (chain) {
      const lifecycle = await this.readBlockLifecycle(blockNum);
      chainLifecycle = lifecycle.available
        ? this.observationResult('succeeded', { value: lifecycle })
        : (lifecycle.reason === 'no_contract' || lifecycle.reason === 'no_rpc'
          ? { state: 'not_attempted', at: Date.now(), reason: lifecycle.reason }
          : this.observationResult('failed', { error: 'chain_lifecycle_read_failed', reason: lifecycle.reason || 'read_error' }));
    }
    const merkleValue = byKey.get(`merkle/block_${blockNum}.json`)?.parsedValue || null;
    const timingValue = byKey.get(`games/block${blockNum}/claim-timing.json`)?.parsedValue || null;
    const rootSources = {
      r2Merkle: merkleValue?.root || null,
      storageMerkle: merkleStatus.value?.root || null,
      progress: progress?.result?.merkle?.root || progress?.merkle?.root || autoProgress?.merkle?.root || null,
      claimTiming: timingValue?.root || null,
      chain: chainLifecycle.value?.merkleRoot || null,
    };
    const roots = Object.values(rootSources).filter((value) => typeof value === 'string' && value);
    const normalizedRoots = new Set(roots.map((value) => value.toLowerCase()));
    const rootConsistency = roots.length < 2
      ? { state: 'not_attempted', at: null, reason: 'fewer_than_two_roots', sources: rootSources }
      : this.observationResult(normalizedRoots.size === 1 ? 'succeeded' : 'failed', {
          matches: normalizedRoots.size === 1, sources: rootSources,
        });
    const verificationStartedMs = Number(chainLifecycle.value?.verificationStartedAt || 0) * 1000;
    const submitEnd = Number(timingValue?.submitEnd);
    const claimTiming = rootOmitted
      ? { state: 'not_attempted', at: null, reason: 'timeline_no_game_root_omitted' }
      : timingValue
      ? this.observationResult('succeeded', {
          submitEnd: Number.isFinite(submitEnd) ? submitEnd : null,
          verificationStartedAt: verificationStartedMs || null,
          differenceMs: verificationStartedMs && Number.isFinite(submitEnd) ? submitEnd - verificationStartedMs : null,
          rootMatchesChain: rootSources.claimTiming && rootSources.chain
            ? rootSources.claimTiming.toLowerCase() === rootSources.chain.toLowerCase() : null,
        })
      : { state: 'not_attempted', at: null, reason: 'claim_timing_unavailable' };
    const failed = missingRequired.length > 0 || parseFailures.length > 0 || hashMismatches.length > 0
      || observationFailures.length > 0 || manifestIntegrity.matches === false || rootConsistency.state === 'failed';
    return {
      state: failed ? 'failed' : (coverage.complete ? 'succeeded' : 'truncated'),
      at, blockNum, mode: 'deep', coverage,
      required: this.boundedTextObservationList([...requiredSet]),
      optional: this.boundedTextObservationList([...optionalSet]),
      artifacts: clean,
      artifactsOmitted: uninspectedDeclaredFileCount,
      missingRequired: { ...this.boundedTextObservationList(missingRequired), complete: coverage.complete },
      parseFailures: { ...this.boundedTextObservationList(parseFailures), complete: coverage.complete },
      hashMismatches: { ...this.boundedTextObservationList(hashMismatches), complete: coverage.complete },
      observationFailures: { ...this.boundedTextObservationList(observationFailures), complete: coverage.complete },
      manifestIntegrity, merkleStatus, chainLifecycle, rootConsistency, claimTiming,
    };
  }

  async inspectCalcBootstrapWatchdog() {
    const at = Date.now();
    const db = this.env.BITCOINU_DATA;
    if (!db) return { state: 'not_attempted', at, reason: 'd1_binding_missing', blocks: [] };
    try {
      const { results } = await db.prepare(
        `SELECT block_num, COUNT(*) AS completed_count FROM game_groups
         WHERE status = 'completed' GROUP BY block_num ORDER BY block_num DESC LIMIT ${MONITOR_TASK_LIMIT + 1}`
      ).all();
      const all = Array.isArray(results) ? results : [];
      const blocks = [];
      for (const row of all.slice(0, MONITOR_TASK_LIMIT)) {
        const blockNum = Number(row.block_num);
        const [progress, legacyActiveMarker] = await Promise.all([
          this.storage.get(this.calcProgressKey(blockNum)),
          this.storage.get(`calc_active:${blockNum}`).catch(() => null),
        ]);
        blocks.push({
          blockNum,
          completedGroupCount: Number(row.completed_count || 0),
          progressPresent: !!progress,
          progressStage: progress?.stage || null,
          progressParked: !!progress?.parked,
          legacyActiveMarkerPresent: !!legacyActiveMarker,
        });
      }
      return this.observationResult('succeeded', {
        blocks,
        omitted: Math.max(0, all.length - MONITOR_TASK_LIMIT),
        missingProgress: this.boundedObservationList(blocks.filter((item) => !item.progressPresent).map((item) => item.blockNum)),
      });
    } catch (error) {
      return this.observationFailure(error, { blocks: [] });
    }
  }

  async inspectDoneArtifactWatchdog() {
    try {
      const [progressMap, autoMap] = await Promise.all([
        this.storage.list({ prefix: 'calc_block', limit: PUBLIC_STORAGE_LIST_LIMIT }),
        this.storage.list({ prefix: 'auto_distribute_block', limit: PUBLIC_STORAGE_LIST_LIMIT }),
      ]);
      const candidates = new Map();
      for (const [key, progress] of progressMap) {
        if (/^calc_block\d+_progress$/.test(key) && progress?.stage === 'done') {
          candidates.set(Number(progress.blockNum), { progress });
        }
      }
      for (const [, autoProgress] of autoMap) {
        if (autoProgress?.stage !== 'done') continue;
        const item = candidates.get(Number(autoProgress.blockNum)) || {};
        candidates.set(Number(autoProgress.blockNum), { ...item, autoProgress });
      }
      const sorted = [...candidates].sort((a, b) => b[0] - a[0]);
      const blocks = await Promise.all(sorted.slice(0, MONITOR_DONE_BLOCK_LIMIT).map(([blockNum, item]) => (
        this.inspectDoneBlockArtifacts(blockNum, { ...item, deep: false, chain: false })
      )));
      return this.observationResult('succeeded', {
        blocks,
        omitted: Math.max(0, sorted.length - MONITOR_DONE_BLOCK_LIMIT),
        failedBlocks: this.boundedObservationList(blocks.filter((item) => item.state === 'failed').map((item) => item.blockNum)),
      });
    } catch (error) {
      return this.observationFailure(error, { blocks: [] });
    }
  }

  async inspectChatGameDoStatus(blockNum, groupId) {
    if (!this.env.CHAT_GAME_DO) {
      return { state: 'not_attempted', at: Date.now(), reason: 'chat_game_do_binding_missing' };
    }
    try {
      const doId = this.env.CHAT_GAME_DO.idFromName(`${blockNum}-${groupId}`);
      // 🔴 生 Request を使わない（`chat-do-auth-test.mjs` の配線検査が禁じている）。
      //    `/status` 自体は secret 不要だが、**生 Request が1つでも残ると
      //    「付け忘れ」を機械が検出できなくなる**ので、必ずこのヘルパーを通す。
      const response = await this.env.CHAT_GAME_DO.get(doId).fetch(
        this.chatDoRequest('/status', { method: 'GET' }),
      );
      const body = await response.json().catch(() => null);
      if (!response.ok || !body) throw new Error(`status ${response.status}`);
      const metaMatches = Number(body.meta?.blockNum) === Number(blockNum)
        && Number(body.meta?.groupId) === Number(groupId);
      return this.observationResult('succeeded', {
        initialized: !!body.meta && body.phase !== 'init',
        metaMatches,
        phase: body.phase || null,
        memberCount: Number.isSafeInteger(Number(body.meta?.memberCount)) ? Number(body.meta.memberCount) : null,
      });
    } catch (error) {
      return this.observationFailure(error);
    }
  }

  configuredRuntimeValues() {
    const parseStart = (raw) => {
      if (raw == null || raw === '') return null;
      const numeric = Number(raw);
      const value = Number.isFinite(numeric) && numeric !== 0 ? numeric : Date.parse(raw);
      return Number.isFinite(value) ? value : null;
    };
    const integer = (raw) => {
      const value = Number.parseInt(raw, 10);
      return Number.isFinite(value) ? value : null;
    };
    return {
      evidence: {
        configured: !!this.env.EVIDENCE_CONTRACT_ADDRESS,
        address: this.env.EVIDENCE_CONTRACT_ADDRESS || null,
      },
      tokenMining: {
        configured: !!this.env.TOKEN_MINING_CONTRACT_ADDRESS,
        address: this.env.TOKEN_MINING_CONTRACT_ADDRESS || null,
      },
      rpc: describeRpcConfig(this.env),
      chainId: resolveEthChainId(this.env),
      timeline: {
        startTime: parseStart(this.env.START_TIME),
        blockTimeMs: integer(this.env.BLOCK_TIME),
        gamePeriodMs: this.gamePeriodMs,
        submitPeriodMs: this.submitPeriodMs,
        // RESULT_GRACE_SECONDS は単独宣言・配布しない。意図的に配布済みの RESULT_GRACE へフォールバックする。
        resultGraceSeconds: integer(this.env.RESULT_GRACE_SECONDS ?? this.env.RESULT_GRACE),
        confirmationBlocks: integer(this.env.CONFIRMATION_BLOCKS),
      },
      observedAt: Date.now(),
    };
  }

  slimPhaseTask(task, now = Date.now()) {
    if (!task) return null;
    const executeAt = Number.isFinite(Number(task.executeAt)) ? Number(task.executeAt) : null;
    const activeAt = Number.isFinite(Number(task.activeAt)) ? Number(task.activeAt) : null;
    return {
      type: task.type || null,
      blockNum: Number.isSafeInteger(Number(task.blockNum)) ? Number(task.blockNum) : null,
      targetPhase: task.targetPhase || null,
      executeAt,
      activeAt,
      attempts: task.attempts ?? 0,
      overdue: executeAt != null ? executeAt < now : null,
      overdueMs: executeAt != null && executeAt < now ? now - executeAt : 0,
      activeForMs: activeAt != null ? Math.max(0, now - activeAt) : null,
    };
  }

  async inspectPhaseShardStatus(blockNum) {
    const observed = await this.readGroupObservation(blockNum);
    const phases = {};
    for (const phase of ['chatting', 'submitting', 'completed']) {
      const cursorKey = `phase_shard_cursor_block${blockNum}:${phase}`;
      let cursorState;
      try {
        const cursor = await this.storage.get(cursorKey);
        cursorState = cursor == null
          ? { state: 'not_attempted', at: null, reason: 'cursor_absent' }
          : this.observationResult('succeeded', { value: Number(cursor) });
      } catch (error) {
        cursorState = this.observationFailure(error);
      }
      const recorded = observed.phaseShards?.[phase] || {};
      phases[phase] = {
        cursor: cursorState,
        retrying: !!recorded.retrying,
        totalChunks: recorded.totalChunks ?? null,
        failedShard: recorded.failedShard || null,
        attempt: recorded.attempt || { state: 'not_attempted', at: null },
        lastOutcome: recorded.lastOutcome || { state: 'not_attempted', at: null },
      };
    }
    return {
      state: observed.readFailure ? 'failed' : 'succeeded',
      at: Date.now(),
      phases,
      observationUpdatedAt: observed.updatedAt ?? null,
      observationWriteFailure: observed.writeFailure || observed.observationWriteFailures || null,
    };
  }

  async inspectAlarmState(queue) {
    const now = Date.now();
    const queueTimes = queue.map((task) => Number(task.executeAt)).filter(Number.isFinite);
    const queueEarliestAt = queueTimes.length > 0 ? Math.min(...queueTimes) : null;
    const overdueCount = queueTimes.filter((executeAt) => executeAt < now).length;
    if (typeof this.state?.storage?.getAlarm !== 'function') {
      return {
        state: 'not_attempted', at: now, reason: 'getAlarm_unsupported', queueEarliestAt,
        overdueCount, overdueMs: queueEarliestAt != null && queueEarliestAt < now ? now - queueEarliestAt : 0,
      };
    }
    try {
      const alarmAt = await this.state.storage.getAlarm();
      return this.observationResult('succeeded', {
        alarmAt: alarmAt ?? null,
        queueEarliestAt,
        differenceMs: alarmAt != null && queueEarliestAt != null ? Number(alarmAt) - queueEarliestAt : null,
        overdueCount,
        overdueMs: queueEarliestAt != null && queueEarliestAt < now ? now - queueEarliestAt : 0,
        alarmOverdue: alarmAt != null ? Number(alarmAt) < now : false,
        missingAlarm: queue.length > 0 && alarmAt == null,
        consistent: alarmAt == null ? queue.length === 0 : queueEarliestAt != null && Number(alarmAt) <= queueEarliestAt,
      });
    } catch (error) {
      return this.observationFailure(error, { queueEarliestAt, overdueCount });
    }
  }

  // グループ分け状況確認
  async getGroupStatus(blockNum, { deep = false } = {}) {
    try {
      const noGameState = await this.readTimelineNoGamePublicState(blockNum);
      if (noGameState?.status === 'completed') {
        return {
          blockNum,
          deep,
          status: 'completed',
          noGame: true,
          noGameReason: 'timeline_unverified',
          totalGroups: 0,
          phases: {},
          noGameCleanup: this.publicTimelineNoGameCleanup(noGameState.cleanup),
        };
      }
      if (noGameState?.status === 'pending') {
        return {
          blockNum,
          deep,
          status: 'no_game_finalizing',
          noGame: false,
          totalGroups: 0,
          phases: {},
          noGameCleanup: { status: 'pending' },
        };
      }
      const progressData = await this.storage.get(`grouping_block${blockNum}_progress`) || {};
      const observed = await this.readGroupObservation(blockNum);
      const observedGroups = new Map((observed.groups || []).map((group) => [Number(group.groupId), group]));

      const db = this.env.BITCOINU_DATA;
      if (!db) {
        return {
          ...progressData,
          deep,
          status: progressData.status || 'not_started',
          phases: null,
          observation: observed,
          error: 'BITCOINU_DATA binding not found'
        };
      }

      // D1期待集合をgroup_id単位で読み、その場でphase分布も作る。registry/実DOとの差分の権威。
      const { results: groupRows } = await db.prepare(
        'SELECT group_id, status FROM game_groups WHERE block_num = ? ORDER BY group_id'
      ).bind(blockNum).all();

      // cleanup の記録は先に永続化する設計だが、記録の欠損・移行途中でも
      // invalidated_no_game 行を通常ゲームとして monitor に露出させない。
      const invalidatedRows = (groupRows || []).filter(
        (row) => row.status === TIMELINE_NO_GAME_INVALIDATED_STATUS
      );
      if (invalidatedRows.length > 0) {
        if (invalidatedRows.length === groupRows.length) {
          return {
            blockNum,
            deep,
            status: 'completed',
            noGame: true,
            noGameReason: 'timeline_unverified',
            totalGroups: 0,
            phases: {},
          };
        }
        return {
          blockNum,
          deep,
          status: 'error',
          noGame: false,
          reason: 'timeline_no_game_d1_mixed',
          totalGroups: 0,
          phases: {},
        };
      }

      const phases = {};
      let totalGroups = 0;

      if (groupRows && groupRows.length > 0) {
        for (const row of groupRows) {
          phases[row.status] = (phases[row.status] || 0) + 1;
          totalGroups++;
        }
      }

      const d1GroupIds = (groupRows || []).map((row) => Number(row.group_id)).filter(Number.isSafeInteger);
      const d1PhaseById = new Map((groupRows || []).map((row) => [Number(row.group_id), row.status || null]));
      const registryRaw = await this.storage.get(`chatdo_registry_block${blockNum}`) || [];
      const registryIds = (Array.isArray(registryRaw) ? registryRaw : []).map(Number).filter(Number.isSafeInteger);
      const d1Set = new Set(d1GroupIds);
      const registrySet = new Set(registryIds);

      const [queue, activeTask, alarm, phaseShards, autoDistribute, rosterAnchor, rosterAnchorFailed] = await Promise.all([
        this.storage.get('phase_task_queue').then((value) => Array.isArray(value) ? value : []),
        this.storage.get('phase_task_active').catch(() => null),
        this.storage.get('phase_task_queue').then((value) => this.inspectAlarmState(Array.isArray(value) ? value : [])).catch((error) => this.observationFailure(error)),
        this.inspectPhaseShardStatus(blockNum),
        this.storage.get(`auto_distribute_block${blockNum}`),
        this.storage.get(`roster_anchor_block${blockNum}`),
        this.storage.get(`roster_anchor_failed_block${blockNum}`),
      ]);
      const phaseTasks = queue.filter((task) => task.type === 'phase_transition' && Number(task.blockNum) === Number(blockNum));
      const watchdogTasks = queue.filter((task) => task.type === 'grouping_watchdog' && Number(task.blockNum) === Number(blockNum));
      const expectedPhases = ['chatting', 'submitting', 'completed'];
      const phaseCounts = Object.fromEntries(expectedPhases.map((phase) => [
        phase, phaseTasks.filter((task) => task.targetPhase === phase).length,
      ]));

      // 最も進行しているフェーズ、または最も多いフェーズを代表フェーズとする
      // 優先順: auto_distributed > completed > submitting > chatting > waiting > formed
      let gamePhase = 'formed';
      if (phases['auto_distributed'] > 0) gamePhase = 'auto_distributed';
      else if (phases['completed'] > 0) gamePhase = 'completed';
      else if (phases['submitting'] > 0) gamePhase = 'submitting';
      else if (phases['chatting'] > 0) gamePhase = 'chatting';
      else if (phases['waiting'] > 0) gamePhase = 'waiting';

      const shallowAnchorObservation = rosterAnchor
        ? this.observationResult('succeeded', {
            anchoredAt: rosterAnchor.at ?? null,
            storedHash: rosterAnchor.hash || null,
            publishedManifestHash: null,
            matchesPublishedManifest: null,
          })
        : (rosterAnchorFailed
          ? this.observationResult('failed', {
              at: rosterAnchorFailed.at ?? null,
              error: rosterAnchorFailed.error ? this.observationErrorText(rosterAnchorFailed.error) : null,
            })
          : { state: 'not_attempted', at: null });

      if (!deep) {
        const disabled = () => ({ state: 'not_attempted', at: null, reason: 'deep_check_disabled' });
        return {
          ...progressData,
          deep: false,
          autoDistribute: autoDistribute || null,
          gamePhase,
          phases,
          totalGroups,
          expected: {
            d1GroupCount: totalGroups,
            progressGroupCount: progressData.totalGroups != null && Number.isSafeInteger(Number(progressData.totalGroups))
              ? Number(progressData.totalGroups) : null,
            d1MatchesProgress: progressData.totalGroups != null && Number.isSafeInteger(Number(progressData.totalGroups))
              ? totalGroups === Number(progressData.totalGroups)
              : null,
            d1GroupIds: this.boundedObservationList(d1GroupIds),
            gameGroupsArtifactCount: null,
            gameGroupsMatchesD1: null,
            summaryArtifactCount: null,
            summaryMatchesD1: null,
          },
          artifacts: {
            gameGroups: disabled(),
            summary: disabled(),
            rosterIndex: disabled(),
            rosterManifest: disabled(),
          },
          phaseConsistency: disabled(),
          phaseShards,
          groupingLease: {
            status: progressData.status || 'not_started',
            phase: progressData.phase || null,
            leaseUntil: progressData.leaseUntil ?? null,
            leaseExpired: progressData.status === 'started'
              ? Number(progressData.leaseUntil || 0) <= Date.now()
              : null,
            ...(Number.isFinite(Number(progressData.chatInitErrorCount))
              ? { chatInitErrorCount: Number(progressData.chatInitErrorCount) }
              : {}),
            ...(Number.isFinite(Number(progressData.rosterShaMissingCount))
              ? { rosterShaMissingCount: Number(progressData.rosterShaMissingCount) }
              : {}),
            observed: observed.groupingLease || { state: 'not_attempted', at: null },
          },
          watchdog: {
            queued: watchdogTasks.slice(0, 20),
            queuedOmitted: Math.max(0, watchdogTasks.length - 20),
            active: activeTask?.type === 'grouping_watchdog' && Number(activeTask.blockNum) === Number(blockNum)
              ? activeTask : null,
            alarm,
            consistency: progressData.status === 'started'
              ? this.observationResult('succeeded', {
                  watchdogPresent: watchdogTasks.length > 0
                    || (activeTask?.type === 'grouping_watchdog' && Number(activeTask.blockNum) === Number(blockNum)),
                  alarmConsistentWithGlobalQueue: alarm.state === 'succeeded' ? alarm.consistent : null,
                })
              : { state: 'not_attempted', at: null, reason: 'grouping_not_started' },
            observed: {
              enqueue: { state: 'not_attempted', at: null },
              run: { state: 'not_attempted', at: null },
              ...(observed.watchdog || {}),
            },
          },
          phaseSchedule: {
            tasks: phaseTasks.slice(0, 20),
            tasksOmitted: Math.max(0, phaseTasks.length - 20),
            counts: phaseCounts,
            missing: expectedPhases.filter((phase) => phaseCounts[phase] === 0),
            duplicates: expectedPhases.filter((phase) => phaseCounts[phase] > 1),
            active: activeTask?.type === 'phase_transition' && Number(activeTask.blockNum) === Number(blockNum)
              ? activeTask : null,
            alarm,
            observed: observed.phaseSchedule || { state: 'not_attempted', at: null },
            decision: observed.scheduleDecision || { state: 'not_attempted', at: null },
          },
          roster: {
            detailLimit: GROUP_OBSERVATION_GROUP_LIMIT,
            checkedGroupCount: 0,
            omittedGroupCount: null,
            registryGroupIds: this.boundedObservationList(registryIds),
            manifestGroupIds: disabled(),
            d1MissingFromRegistry: this.boundedObservationList(d1GroupIds.filter((id) => !registrySet.has(id))),
            registryMissingFromD1: this.boundedObservationList(registryIds.filter((id) => !d1Set.has(id))),
            d1MissingFromManifest: disabled(),
            manifestMissingFromD1: disabled(),
            chatDoUninitialized: disabled(),
            chatDoStatusUnavailable: disabled(),
            chatDoMetaMismatch: disabled(),
            fullyChecked: null,
            anchor: shallowAnchorObservation,
            chatDoInspection: disabled(),
            rosterArtifactInspection: disabled(),
            indexPublish: observed.roster?.indexPublish || { state: 'not_attempted', at: null },
            manifestPublish: observed.roster?.manifestPublish || { state: 'not_attempted', at: null },
            registrySave: observed.registrySave || { state: 'not_attempted', at: null },
            groups: [],
          },
          phaseTiming: {
            chatting: observed.phaseTiming?.chatting || { state: 'not_attempted', at: null },
            submitting: observed.phaseTiming?.submitting || { state: 'not_attempted', at: null },
            completed: observed.phaseTiming?.completed || { state: 'not_attempted', at: null },
          },
          operationalObservations: {
            watchdogInitNet: observed.operationalObservations?.watchdogInitNet
              || { state: 'not_attempted', at: null },
            phaseTaskResurrection: observed.operationalObservations?.phaseTaskResurrection
              || { state: 'not_attempted', at: null },
          },
          observation: {
            schemaVersion: observed.schemaVersion,
            updatedAt: observed.updatedAt ?? null,
            writeFailure: observed.writeFailure || null,
            persistedWriteFailures: observed.observationWriteFailures || null,
            observationWriteFailureBottom: observed.observationWriteFailureBottom || null,
            readFailure: observed.readFailure || null,
          },
        };
      }

      const [gameGroupsInspection, summaryInspection, rosterManifestInspection] = await Promise.all([
        this.inspectR2JsonArtifact(`entries/block${blockNum}/game_groups.json`),
        this.inspectR2JsonArtifact(`games/block${blockNum}/summary.json`),
        this.inspectR2JsonArtifact(`games/block${blockNum}/roster/manifest.json`),
      ]);
      const { parsedValue: gameGroupsValue, rawText: _gameGroupsText, ...gameGroupsArtifact } = gameGroupsInspection;
      const { parsedValue: summaryValue, rawText: _summaryText, ...summaryArtifact } = summaryInspection;
      const { parsedValue: rosterManifestValue, rawText: rosterManifestText, ...rosterManifestArtifact } = rosterManifestInspection;
      const manifestGroupSha = new Map(
        (Array.isArray(rosterManifestValue?.groups) ? rosterManifestValue.groups : [])
          .map((group) => [Number(group.groupId), group.sha256]),
      );
      const manifestIds = [...manifestGroupSha.keys()].filter(Number.isSafeInteger);
      const manifestSet = new Set(manifestIds);
      const summaryPhaseById = new Map(
        (Array.isArray(summaryValue?.groups) ? summaryValue.groups : [])
          .map((group) => [Number(group.group_id), group.status || null])
          .filter(([groupId]) => Number.isSafeInteger(groupId)),
      );
      const summaryIds = [...summaryPhaseById.keys()];
      // 実在DOは列挙APIを持たないため、D1・registry・manifestの和集合を候補集合として
      // statusを読む。いずれか一面だけに残ったgroupも差分から消さない。
      const detailSelection = this.boundedObservationList([...d1Set, ...registrySet, ...manifestSet, ...summaryIds]);
      const detailIds = detailSelection.values;
      const rosterIndexInspection = await this.inspectR2JsonArtifact(
        `games/block${blockNum}/roster/index.json`,
        typeof rosterManifestValue?.indexSha256 === 'string' ? rosterManifestValue.indexSha256 : null,
      );
      const { parsedValue: _rosterIndexValue, rawText: _rosterIndexText, ...rosterIndexArtifact } = rosterIndexInspection;
      let publishedManifestHash = null;
      if (rosterManifestArtifact.read?.state === 'succeeded' && rosterManifestText != null) {
        publishedManifestHash = keccak256(stringToHex(rosterManifestText));
      }
      const anchorObservation = rosterAnchor
        ? this.observationResult('succeeded', {
            anchoredAt: rosterAnchor.at ?? null,
            storedHash: rosterAnchor.hash || null,
            publishedManifestHash,
            // storedHash は C、publishedManifestHash は生 manifest の hash。
            // 異なる式の値を比べた false を監視に流さない。全量の C 判定は開始関門が担う。
            matchesPublishedManifest: null,
          })
        : (rosterAnchorFailed
          ? this.observationResult('failed', {
              at: rosterAnchorFailed.at ?? null,
              error: rosterAnchorFailed.error ? this.observationErrorText(rosterAnchorFailed.error) : null,
            })
          : { state: 'not_attempted', at: null });

      const groupDetails = await this.batchChatDoCalls(detailIds, async (groupId) => {
        const expectedSha = manifestGroupSha.get(groupId) || null;
        const [chatDo, rosterShaStored, rosterArtifactInspection] = await Promise.all([
          this.inspectChatGameDoStatus(blockNum, groupId),
          this.storage.get(`roster_group_sha_block${blockNum}_group${groupId}`).catch(() => null),
          this.inspectR2JsonArtifact(`games/block${blockNum}/roster/group${groupId}.json`, expectedSha),
        ]);
        const { parsedValue: _rosterValue, rawText: _rosterText, ...rosterArtifact } = rosterArtifactInspection;
        return {
          groupId,
          d1Expected: d1Set.has(groupId),
          d1Phase: d1PhaseById.get(groupId) ?? null,
          summaryPhase: summaryPhaseById.get(groupId) ?? null,
          registryStored: registrySet.has(groupId),
          chatDo,
          rosterShaStored: rosterShaStored
            ? this.observationResult('succeeded', { value: rosterShaStored })
            : { state: 'not_attempted', at: null, reason: 'sha_not_recorded' },
          manifestDeclaredSha256: expectedSha,
          rosterArtifact,
          rosterAnchor: anchorObservation,
          recorded: {
            chatDoInit: { state: 'not_attempted', at: null },
            rosterPublish: { state: 'not_attempted', at: null },
            registrySave: { state: 'not_attempted', at: null },
            ...(observedGroups.get(groupId) || {}),
          },
        };
      });

      const unavailableIds = groupDetails
        .filter((group) => group.chatDo.state === 'failed').map((group) => group.groupId);
      const uninitializedIds = groupDetails
        .filter((group) => group.d1Expected && group.chatDo.state === 'succeeded' && !group.chatDo.initialized)
        .map((group) => group.groupId);
      const metaMismatchIds = groupDetails
        .filter((group) => group.chatDo.state === 'succeeded' && group.chatDo.initialized && !group.chatDo.metaMatches)
        .map((group) => group.groupId);
      const d1SummaryPhaseMismatchIds = groupDetails
        .filter((group) => group.d1Phase != null && group.summaryPhase != null && group.d1Phase !== group.summaryPhase)
        .map((group) => group.groupId);
      const d1DoPhaseMismatchIds = groupDetails
        .filter((group) => group.d1Phase != null && group.chatDo.state === 'succeeded'
          && group.chatDo.phase != null && group.d1Phase !== group.chatDo.phase)
        .map((group) => group.groupId);
      const summaryDoPhaseMismatchIds = groupDetails
        .filter((group) => group.summaryPhase != null && group.chatDo.state === 'succeeded'
          && group.chatDo.phase != null && group.summaryPhase !== group.chatDo.phase)
        .map((group) => group.groupId);
      const artifactGroupCount = Array.isArray(gameGroupsValue?.groups) ? gameGroupsValue.groups.length : null;
      const summaryGroupCount = Array.isArray(summaryValue?.groups) ? summaryValue.groups.length : null;

      return {
        ...progressData,
        deep: true,
        autoDistribute: autoDistribute || null,
        gamePhase, // 下位互換用
        phases,    // フェーズ分布
        totalGroups,
        expected: {
          d1GroupCount: totalGroups,
          progressGroupCount: progressData.totalGroups != null && Number.isSafeInteger(Number(progressData.totalGroups))
            ? Number(progressData.totalGroups) : null,
          d1MatchesProgress: progressData.totalGroups != null && Number.isSafeInteger(Number(progressData.totalGroups))
            ? totalGroups === Number(progressData.totalGroups)
            : null,
          d1GroupIds: this.boundedObservationList(d1GroupIds),
          gameGroupsArtifactCount: artifactGroupCount,
          gameGroupsMatchesD1: artifactGroupCount == null ? null : artifactGroupCount === totalGroups,
          summaryArtifactCount: summaryGroupCount,
          summaryMatchesD1: summaryGroupCount == null ? null : summaryGroupCount === totalGroups,
        },
        artifacts: {
          gameGroups: gameGroupsArtifact,
          summary: summaryArtifact,
          rosterIndex: rosterIndexArtifact,
          rosterManifest: rosterManifestArtifact,
        },
        phaseConsistency: summaryArtifact.read?.state !== 'succeeded' || summaryArtifact.parse?.state !== 'succeeded'
          ? (summaryArtifact.read?.state === 'failed' || summaryArtifact.parse?.state === 'failed'
            ? this.observationResult('failed', {
                reason: summaryArtifact.read?.state === 'failed' ? 'summary_read_failed' : 'summary_parse_failed',
              })
            : { state: 'not_attempted', at: null, reason: 'summary_unavailable' })
          : this.observationResult('succeeded', {
              d1VsSummary: this.boundedObservationList(d1SummaryPhaseMismatchIds),
              d1VsChatDo: this.boundedObservationList(d1DoPhaseMismatchIds),
              summaryVsChatDo: this.boundedObservationList(summaryDoPhaseMismatchIds),
              checkedGroups: groupDetails.length,
              checkedGroupsOmitted: detailSelection.omitted,
            }),
        phaseShards,
        groupingLease: {
          status: progressData.status || 'not_started',
          phase: progressData.phase || null,
          leaseUntil: progressData.leaseUntil ?? null,
          leaseExpired: progressData.status === 'started'
            ? Number(progressData.leaseUntil || 0) <= Date.now()
            : null,
          ...(Number.isFinite(Number(progressData.chatInitErrorCount))
            ? { chatInitErrorCount: Number(progressData.chatInitErrorCount) }
            : {}),
          ...(Number.isFinite(Number(progressData.rosterShaMissingCount))
            ? { rosterShaMissingCount: Number(progressData.rosterShaMissingCount) }
            : {}),
          observed: observed.groupingLease || { state: 'not_attempted', at: null },
        },
        watchdog: {
          queued: watchdogTasks.slice(0, 20),
          queuedOmitted: Math.max(0, watchdogTasks.length - 20),
          active: activeTask?.type === 'grouping_watchdog' && Number(activeTask.blockNum) === Number(blockNum)
            ? activeTask : null,
          alarm,
          consistency: progressData.status === 'started'
            ? this.observationResult('succeeded', {
                watchdogPresent: watchdogTasks.length > 0
                  || (activeTask?.type === 'grouping_watchdog' && Number(activeTask.blockNum) === Number(blockNum)),
                alarmConsistentWithGlobalQueue: alarm.state === 'succeeded' ? alarm.consistent : null,
              })
            : { state: 'not_attempted', at: null, reason: 'grouping_not_started' },
          observed: {
            enqueue: { state: 'not_attempted', at: null },
            run: { state: 'not_attempted', at: null },
            ...(observed.watchdog || {}),
          },
        },
        phaseSchedule: {
          tasks: phaseTasks.slice(0, 20),
          tasksOmitted: Math.max(0, phaseTasks.length - 20),
          counts: phaseCounts,
          missing: expectedPhases.filter((phase) => phaseCounts[phase] === 0),
          duplicates: expectedPhases.filter((phase) => phaseCounts[phase] > 1),
          active: activeTask?.type === 'phase_transition' && Number(activeTask.blockNum) === Number(blockNum)
            ? activeTask : null,
          alarm,
          groupRosterSha: groupDetails.map((group) => ({ groupId: group.groupId, ...group.rosterShaStored })),
          observed: observed.phaseSchedule || { state: 'not_attempted', at: null },
          decision: observed.scheduleDecision || { state: 'not_attempted', at: null },
        },
        roster: {
          detailLimit: GROUP_OBSERVATION_GROUP_LIMIT,
          checkedGroupCount: groupDetails.length,
          omittedGroupCount: detailSelection.omitted,
          registryGroupIds: this.boundedObservationList(registryIds),
          manifestGroupIds: this.boundedObservationList(manifestIds),
          d1MissingFromRegistry: this.boundedObservationList(d1GroupIds.filter((id) => !registrySet.has(id))),
          registryMissingFromD1: this.boundedObservationList(registryIds.filter((id) => !d1Set.has(id))),
          d1MissingFromManifest: this.boundedObservationList(d1GroupIds.filter((id) => !manifestSet.has(id))),
          manifestMissingFromD1: this.boundedObservationList(manifestIds.filter((id) => !d1Set.has(id))),
          chatDoUninitialized: this.boundedObservationList(uninitializedIds),
          chatDoStatusUnavailable: this.boundedObservationList(unavailableIds),
          chatDoMetaMismatch: this.boundedObservationList(metaMismatchIds),
          fullyChecked: detailSelection.omitted === 0,
          anchor: anchorObservation,
          indexPublish: observed.roster?.indexPublish || { state: 'not_attempted', at: null },
          manifestPublish: observed.roster?.manifestPublish || { state: 'not_attempted', at: null },
          registrySave: observed.registrySave || { state: 'not_attempted', at: null },
          groups: groupDetails,
        },
        phaseTiming: {
          chatting: observed.phaseTiming?.chatting || { state: 'not_attempted', at: null },
          submitting: observed.phaseTiming?.submitting || { state: 'not_attempted', at: null },
          completed: observed.phaseTiming?.completed || { state: 'not_attempted', at: null },
        },
        // F12: blockers/degraded へは接続せず、運用画面が直接読む非停止の観測欄。
        operationalObservations: {
          watchdogInitNet: observed.operationalObservations?.watchdogInitNet
            || { state: 'not_attempted', at: null },
          phaseTaskResurrection: observed.operationalObservations?.phaseTaskResurrection
            || { state: 'not_attempted', at: null },
        },
        observation: {
          schemaVersion: observed.schemaVersion,
          updatedAt: observed.updatedAt ?? null,
          writeFailure: observed.writeFailure || null,
          persistedWriteFailures: observed.observationWriteFailures || null,
          observationWriteFailureBottom: observed.observationWriteFailureBottom || null,
          readFailure: observed.readFailure || null,
        },
      };

    } catch (error) {
      return {
        blockNum,
        status: 'error',
        error: error.message
      };
    }
  }

  // write-workersにゲームグループ情報を書き込み
  // 各メンバーのシャードDBのwin_blocksにgame情報を追加
  // C1是正（2026-07-18）: 行の正はD1（game_groups.members）。通常経路もA6乗っ取りresumeも
  // 同一コードパスでD1から決定論的に行を再構築するため、チャンクカーソルが実行を跨いで有効。
  // ・デポジッター通知はデポジット1件毎ではなく（支援者,プレイヤー）ペアで1件（dedup）
  // ・送信は buildShardWriteChunks（write-worker→ユーザー単位→100ユーザー毎）で分割し、
  //   失敗はthrow（呼び出し元のA6リース/watchdogが再実行・カーソルで続きから）＝無音欠落の根絶
  async writeGameGroupsToShards(blockNum) {
    const db = this.env.BITCOINU_DATA;
    if (!db) throw new Error('writeGameGroupsToShards: BITCOINU_DATA binding not found');

    const { results: groupRows } = await db.prepare(
      `SELECT group_id, lang, members FROM game_groups WHERE block_num = ? ORDER BY group_id`
    ).bind(blockNum).all();
    if (!groupRows || groupRows.length === 0) {
      throw new Error(`writeGameGroupsToShards: no groups in D1 for block ${blockNum}`);
    }

    const rows = [];
    for (const g of groupRows) {
      let members;
      try { members = JSON.parse(g.members || '[]'); } catch (e) { members = []; }
      for (const member of members) {
        const uid = member.uid;
        if (!uid) continue;
        rows.push({ uid: String(uid), groupId: g.group_id, lang: g.lang, phase: 'waiting' });

        // 外部デポジッター通知。同一（支援者,プレイヤー）ペアはdedup（レコードにdepositIdは
        // 含まれず「支援先プレイヤーの参加通知」の意味は1件で足りる。旧実装はデポジット毎に
        // 同一内容レコードを重複生成しwrite-worker側のCAS予算を浪費していた）。
        const depIds = member.depIds;
        if (!depIds) continue;
        try {
          const parsed = typeof depIds === 'string' ? JSON.parse(depIds) : depIds;
          const addedDepositors = new Set();
          for (const dep of (parsed?.deposits || [])) {
            if (!dep.idFrom || String(dep.idFrom) === String(uid)) continue; // 自己デポジットはスキップ
            const depIdFrom = String(dep.idFrom);
            if (addedDepositors.has(depIdFrom)) continue;
            addedDepositors.add(depIdFrom);
            rows.push({
              uid: depIdFrom,
              groupId: g.group_id,
              lang: g.lang,
              phase: 'waiting',
              role: 'depositor',
              playerUid: String(uid)
            });
          }
        } catch (e) {
          console.error(`writeGameGroupsToShards: depIds parse error for player ${uid}:`, e.message);
        }
      }
    }

    const chunks = this.buildShardWriteChunks(rows);
    const shardStats = { totalWritten: 0, totalErrors: 0 };
    const totalWritten = await this.sendShardWriteChunks('/write-game-groups', blockNum, chunks, {
      cursorKey: `grouping_shard_cursor_block${blockNum}`,
      stats: shardStats,
    });
    console.log(`writeGameGroupsToShards: ${totalWritten} written across ${chunks.length} chunks (${rows.length} rows)`);
    return { totalWritten, totalErrors: shardStats.totalErrors, totalChunks: chunks.length };
  }

  // C1是正: 行配列を「write-worker → ユーザー単位 → 100ユーザー毎チャンク」に決定論的に分割する。
  // 同一ユーザーの行は必ず同一チャンクに収まる（write-worker側で1ユーザー=1回のCASに束ねる前提）。
  // 入力順序が同じなら常に同じチャンク列になる＝カーソル再開の前提。
  buildShardWriteChunks(rows) {
    const INSTANCES_PER_WORKER = 250;
    const byWorker = new Map();
    for (const row of rows) {
      const shardNumber = parseInt(String(row.uid).slice(-4));
      const workerIndex = Math.floor(shardNumber / INSTANCES_PER_WORKER);
      if (!byWorker.has(workerIndex)) byWorker.set(workerIndex, new Map());
      const byUid = byWorker.get(workerIndex);
      const key = String(row.uid);
      if (!byUid.has(key)) byUid.set(key, []);
      byUid.get(key).push(row);
    }
    const chunks = [];
    for (const [workerIndex, byUid] of byWorker) {
      let current = null;
      for (const [, userRows] of byUid) {
        if (!current || current.users >= SHARD_WRITE_USERS_PER_REQUEST) {
          current = { workerIndex, users: 0, members: [] };
          chunks.push(current);
        }
        current.users++;
        current.members.push(...userRows);
      }
    }
    return chunks;
  }

  // C1是正: チャンク列を順次送信。HTTP失敗・error_count>0 はthrow（書き込みはwin_blocksへの
  // upsertで冪等＝再送安全。呼び出し元のリトライ機構（A6リース/A3タスク/A1ユニット）で再実行）。
  // cursorKey指定時は完了チャンク数と受信側が返したdeferred uidをDOストレージに
  // 永続する。deferredが空になるまでチャンクカーソルを進めず、再開後も未処理uidだけを送る。
  async sendShardWriteChunks(endpoint, blockNum, chunks, { cursorKey = null, extra = {}, stats = null } = {}) {
    const INSTANCES_PER_WORKER = 250;
    const DEFERRED_PROTOCOL_VERSION = 1;
    const MAX_CONTINUATIONS_PER_CHUNK = 10;
    const deferredCursorKey = cursorKey ? `${cursorKey}:deferred` : null;
    let start = 0;
    if (cursorKey) start = (await this.storage.get(cursorKey)) || 0;
    let resumedDeferred = deferredCursorKey ? await this.storage.get(deferredCursorKey) : null;
    if (resumedDeferred && Number(resumedDeferred.chunkIndex) !== Number(start)) {
      throw new Error(`${endpoint}: deferred cursor mismatch (${resumedDeferred.chunkIndex} != ${start})`);
    }
    let sentInThisCall = 0;
    let totalWritten = 0;
    let totalErrors = 0;
    for (let i = start; i < chunks.length; i++) {
      const chunk = chunks[i];
      const startRange = chunk.workerIndex * INSTANCES_PER_WORKER;
      const endRange = startRange + INSTANCES_PER_WORKER - 1;
      const workerName = `write-worker-${startRange.toString().padStart(4, '0')}_${endRange.toString().padStart(4, '0')}`;
      const binding = writeWorkerBinding(chunk.workerIndex);

      let pendingMembers = chunk.members;
      let continuationCount = 0;
      let isContinuation = false;
      if (i === start && resumedDeferred) {
        const persistedUids = Array.isArray(resumedDeferred.uids) ? resumedDeferred.uids.map(String) : [];
        const deferredUids = new Set(persistedUids);
        const chunkUids = new Set(chunk.members.map((member) => String(member?.uid)));
        pendingMembers = chunk.members.filter((member) => deferredUids.has(String(member?.uid)));
        continuationCount = Number(resumedDeferred.continuationsSent || 0);
        isContinuation = true;
        if (pendingMembers.length === 0 || deferredUids.size === 0
            || deferredUids.size !== persistedUids.length
            || [...deferredUids].some((uid) => !uid || !chunkUids.has(uid))
            || !Number.isSafeInteger(continuationCount) || continuationCount < 0) {
          throw new Error(`${endpoint}: persisted deferred uid set does not match chunk ${i}`);
        }
      }

      while (pendingMembers.length > 0) {
        if (isContinuation && continuationCount >= MAX_CONTINUATIONS_PER_CHUNK) {
          const error = new Error(
            `${endpoint} ${workerName}: deferred continuation limit exceeded (${continuationCount}/${MAX_CONTINUATIONS_PER_CHUNK})`
          );
          error.shardChunkIndex = i;
          error.shardCursor = i;
          error.shardTotalChunks = chunks.length;
          error.shardBinding = binding;
          error.shardWorker = workerName;
          error.shardEndpoint = endpoint;
          throw error;
        }
        if (sentInThisCall >= SHARD_WRITE_MAX_CHUNKS_PER_CALL) {
          // S3-007（2026-07-29）: 続行リクエストもService Binding予算に数える。
          // deferred uidは保存済みなので、次の実行はチャンク全体ではなく続きから再開する。
          const err = new Error(`${endpoint}: chunk budget exhausted (${i}/${chunks.length} done) — will resume from cursor`);
          err.resumable = true;
          err.shardChunkIndex = i;
          err.shardCursor = i;
          err.shardTotalChunks = chunks.length;
          err.shardEndpoint = endpoint;
          throw err;
        }
        if (isContinuation) continuationCount++;

        let data;
        let deferred;
        let nextMembers;
        const errorsBeforeRequest = totalErrors;
        try {
          // S3-003: 公開 workers.dev URL → Service Binding。片側配備での無音欠落を防ぐため、
          // deferred対応を版数付きで申告する（旧受信側は未知フィールドを無視して従来動作）。
          let response;
          try {
            response = await requireBinding(this.env, binding).fetch(
              internalJsonRequest(endpoint, {
                block_num: blockNum,
                members: pendingMembers,
                ...extra,
                deferred_protocol: DEFERRED_PROTOCOL_VERSION,
              }, this.env.API_SECRET)
            );
          } catch (transportError) {
            const wrapped = transportError instanceof Error
              ? transportError : new Error(String(transportError));
            wrapped.shardTransportFailure = true;
            if (endpoint === '/write-game-groups'
                && isTransientGroupingShardError(wrapped.message)) wrapped.resumable = true;
            throw wrapped;
          }
          if (!response.ok) {
            const transportError = new Error(`${endpoint} ${workerName} (${binding}): HTTP ${response.status}`);
            transportError.shardTransportFailure = true;
            if (endpoint === '/write-game-groups' && response.status >= 500 && response.status <= 599) {
              // outer catch の500は {success:false,error:message}。SQL制約等まで再開しない。
              let body;
              try { body = await response.text(); }
              catch (error) {
                if (isTransientGroupingShardError(error?.message)) error.resumable = true;
                error.shardTransportFailure = true;
                throw error;
              }
              let payload;
              try { payload = JSON.parse(body); } catch { /* gatewayの非JSON 5xxも一時失敗 */ }
              transportError.groupingShardFailureCause = groupingShardFailureCause(body);
              const detail = typeof payload?.error === 'string' ? payload.error : null;
              transportError.resumable = !isPermanentGroupingShardError(body)
                && (payload?.errors !== undefined
                  ? isTransientGroupingShardResponse(payload, Number(payload.error_count), pendingMembers)
                    && (detail === null || isTransientGroupingShardError(detail))
                  : detail !== null ? payload.success === false && isTransientGroupingShardError(detail)
                    : payload === undefined);
            }
            throw transportError;
          }
          try {
            data = await response.json();
          } catch (error) {
            if (endpoint === '/write-game-groups'
                && isTransientGroupingShardError(error?.message)) error.resumable = true;
            throw error;
          }
          const reportedErrors = Number(data?.error_count || 0);
          if (!Number.isSafeInteger(reportedErrors) || reportedErrors < 0) {
            throw new Error(`${endpoint} ${workerName}: invalid error_count`);
          }
          if (data?.success === false) {
            totalErrors += Math.max(1, reportedErrors);
            const sample = JSON.stringify((data.errors || []).slice(0, 3));
            const error = new Error(`${endpoint} ${workerName}: success:false (${reportedErrors} errors, sample: ${sample})`);
            error.groupingShardFailureCause = groupingShardFailureCause(JSON.stringify(data.errors || []));
            if (endpoint === '/write-game-groups'
                && isTransientGroupingShardResponse(data, reportedErrors, pendingMembers)) error.resumable = true;
            throw error;
          }
          if (reportedErrors > 0) {
            totalErrors += reportedErrors;
            const sample = JSON.stringify((data.errors || []).slice(0, 3));
            const error = new Error(`${endpoint} ${workerName}: ${reportedErrors} errors (sample: ${sample})`);
            error.groupingShardFailureCause = groupingShardFailureCause(JSON.stringify(data.errors || []));
            if (endpoint === '/write-game-groups'
                && isTransientGroupingShardResponse(data, reportedErrors, pendingMembers)) error.resumable = true;
            throw error;
          }

          const expectedCount = data?.expected_count === undefined ? null : Number(data.expected_count);
          if (expectedCount !== null
            && (!Number.isSafeInteger(expectedCount) || expectedCount !== pendingMembers.length)) {
            throw new Error(
              `${endpoint} ${workerName}: expected_count mismatch (${data?.expected_count} != ${pendingMembers.length})`
            );
          }
          if (data.deferred !== undefined && !Array.isArray(data.deferred)) {
            throw new Error(`${endpoint} ${workerName}: invalid deferred response`);
          }
          deferred = Array.isArray(data.deferred) ? data.deferred.map((uid) => String(uid)) : [];
          const deferredSet = new Set(deferred);
          const currentUids = new Set(pendingMembers.map((member) => String(member?.uid)));
          if (deferredSet.size !== deferred.length || [...deferredSet].some((uid) => !uid || !currentUids.has(uid))) {
            throw new Error(`${endpoint} ${workerName}: deferred response contains duplicate or unknown uid`);
          }
          nextMembers = pendingMembers.filter((member) => deferredSet.has(String(member?.uid)));

          const writtenCount = Number(data?.written_count);
          const expectedWritten = pendingMembers.length - nextMembers.length;
          if (!Number.isSafeInteger(writtenCount) || writtenCount !== expectedWritten) {
            throw new Error(
              `${endpoint} ${workerName}: written_count mismatch (${data?.written_count} != ${expectedWritten})`
            );
          }
          const deferredEntryCount = data?.deferred_entry_count === undefined
            ? null : Number(data.deferred_entry_count);
          if (deferredEntryCount !== null
            && (!Number.isSafeInteger(deferredEntryCount) || deferredEntryCount !== nextMembers.length)) {
            throw new Error(
              `${endpoint} ${workerName}: deferred_entry_count mismatch (${data?.deferred_entry_count} != ${nextMembers.length})`
            );
          }
        } catch (error) {
          // write-worker本文が申告した per-uid error だけでなく、binding欠損・fetch reject・
          // HTTP 401/5xx の輸送失敗も1件と数える。
          // reset-block はこの stats から success を作るため、0のまま再throwすると失敗を成功表示する。
          if (error.shardTransportFailure === true && totalErrors === errorsBeforeRequest) totalErrors += 1;
          error.shardChunkIndex = i;
          error.shardCursor = i;
          error.shardTotalChunks = chunks.length;
          error.shardBinding = binding;
          error.shardWorker = workerName;
          error.shardEndpoint = endpoint;
          error.shardTotalErrors = totalErrors;
          if (endpoint === '/write-game-groups' && error.resumable === true) {
            error.groupingShardTransient = true;
          }
          if (stats) {
            stats.totalWritten = totalWritten;
            stats.totalErrors = totalErrors;
          }
          throw error;
        }

        totalWritten += Number(data.written_count);
        sentInThisCall++;

        if (deferred.length === 0) {
          pendingMembers = [];
          if (deferredCursorKey) await this.storage.delete(deferredCursorKey);
          break;
        }

        if (nextMembers.length === pendingMembers.length) {
          throw new Error(`${endpoint} ${workerName}: deferred response made no progress`);
        }
        pendingMembers = nextMembers;
        isContinuation = true;
        if (deferredCursorKey) {
          await this.storage.put(deferredCursorKey, {
            chunkIndex: i,
            uids: deferred,
            continuationsSent: continuationCount,
          });
        }
      }

      resumedDeferred = null;
      if (cursorKey) await this.storage.put(cursorKey, i + 1);
    }
    if (cursorKey) {
      await this.storage.delete(cursorKey);
      await this.storage.delete(deferredCursorKey);
    }
    if (stats) {
      stats.totalWritten = totalWritten;
      stats.totalErrors = totalErrors;
    }
    return totalWritten;
  }

  // write-workersにゲームフェーズ更新を書き込み
  // 各メンバーのシャードDBのwin_blocks[blockNum].game.phaseを更新
  // C1是正（2026-07-18）: フェーズ更新はユーザー単位で全体適用（game＋全game_deposits）される
  // ため、行は全ブロックでuidをグローバルdedupして1件（プレイヤー/支援者の重複も1回のCASに集約）。
  // 送信はチャンク化＋失敗throw（呼び出し元advancePhase→A3タスクリトライで再実行・冪等）。
  async updateGamePhaseToShards(blockNum, targetPhase) {
    const db = this.env.BITCOINU_DATA;
    if (!db) {
      throw new Error('updateGamePhaseToShards: BITCOINU_DATA binding not found');
    }

    // D1から該当ブロックの全グループのメンバーを取得
    const { results: groups } = await db.prepare(
      `SELECT members FROM game_groups WHERE block_num = ? ORDER BY group_id`
    ).bind(blockNum).all();

    if (!groups || groups.length === 0) {
      console.warn(`updateGamePhaseToShards: No groups found for block ${blockNum}`);
      return { totalWritten: 0, totalErrors: 0 };
    }

    const rows = [];
    const seen = new Set();
    for (const group of groups) {
      let members;
      try { members = JSON.parse(group.members || '[]'); } catch (e) { members = []; }
      for (const member of members) {
        const uid = member.uid;
        if (!uid) continue;
        const uidStr = String(uid);
        if (!seen.has(uidStr)) {
          seen.add(uidStr);
          rows.push({ uid: uidStr });
        }

        // 外部デポジッターも追加（グローバルdedup: 複数プレイヤーを支援していても更新は1回）
        if (member.depIds) {
          try {
            const depIds = typeof member.depIds === 'string' ? JSON.parse(member.depIds) : member.depIds;
            for (const dep of (depIds?.deposits || [])) {
              if (!dep.idFrom || String(dep.idFrom) === String(uid)) continue;
              const depIdFrom = String(dep.idFrom);
              if (seen.has(depIdFrom)) continue;
              seen.add(depIdFrom);
              rows.push({ uid: depIdFrom, role: 'depositor' });
            }
          } catch (e) { /* depIds parse error, skip */ }
        }
      }
    }

    const chunks = this.buildShardWriteChunks(rows);
    const cursorKey = `phase_shard_cursor_block${blockNum}:${targetPhase}`;
    const startedAt = Date.now();
    const cursor = Number(await this.storage.get(cursorKey) || 0);
    this.deferGroupObservation(blockNum, {
      phaseShards: {
        [targetPhase]: {
          cursor, totalChunks: chunks.length,
          attempt: this.observationResult('succeeded', { startedAt }),
          lastOutcome: { state: 'not_attempted', at: null },
        },
      },
    });
    let totalWritten;
    const shardStats = { totalWritten: 0, totalErrors: 0 };
    try {
      totalWritten = await this.sendShardWriteChunks('/update-game-phase', blockNum, chunks, {
        cursorKey,
        extra: { phase: targetPhase },
        stats: shardStats,
      });
    } catch (error) {
      const failure = {
        cursor: Number(error.shardCursor ?? await this.storage.get(cursorKey) ?? cursor),
        totalChunks: Number(error.shardTotalChunks ?? chunks.length),
        retrying: !!error.resumable,
        failedShard: error.shardBinding || error.shardWorker
          ? {
              chunkIndex: error.shardChunkIndex ?? null,
              binding: error.shardBinding || null,
              worker: error.shardWorker || null,
            }
          : null,
      };
      this.deferGroupObservation(blockNum, {
        phaseShards: {
          [targetPhase]: {
            ...failure,
            lastOutcome: error.resumable
              ? this.observationResult('succeeded', { outcome: 'partial', ...failure })
              : this.observationFailure(error, { outcome: 'failed', ...failure }),
          },
        },
      });
      throw error;
    }
    this.deferGroupObservation(blockNum, {
      phaseShards: {
        [targetPhase]: {
          cursor: chunks.length, totalChunks: chunks.length, retrying: false, failedShard: null,
          lastOutcome: this.observationResult('succeeded', {
            outcome: 'completed', totalWritten, startedAt, completedAt: Date.now(),
          }),
        },
      },
    });
    console.log(`updateGamePhaseToShards: phase=${targetPhase}, ${totalWritten} written across ${chunks.length} chunks`);
    return { totalWritten, totalErrors: shardStats.totalErrors };
  }

  // write-workersにゲーム結果を書き込み
  // 各メンバーのシャードDBのwin_blocks[blockNum].game.resultに結果を追加
  // デポジッターのwin_blocks[blockNum].game_depositsにも結果を追加
  // C1/R4是正（2026-07-18）: 結果書き込み。プレイヤー結果＋デポジット報酬（depositId毎の正当な
  // 複数行）を buildShardWriteChunks でユーザー単位に束ね、100ユーザー毎にチャンク送信する。
  // 失敗はthrow（calcShardsUnitのユニットリトライ／autoDistribute経由はA6リトライで再実行）。
  // カーソル=calc:{N}:shards_cursor（calcCleanupKeys・/reset-blockのprefix掃除対象）。
  // 行の構築順は calcLoadResultsFromRecords の決定論的順序（group_id昇順）＝実行を跨いで同一チャンク列。
  async writeGameResultsToShards(blockNum, allGroupResults, depositorResults = [], opts = {}) {
    const rows = [];
    for (const group of allGroupResults) {
      for (const member of group.members) {
        const uid = member.uid;
        if (!uid) continue;
        rows.push({
          uid: String(uid),
          ...(opts.replace ? { replaceResults: true } : {}),
          groupId: group.groupId,
          autoDistributed: opts.autoDistributed === true,
          depositPoints: member.depositPoints,
          bonusPoints: member.bonusPoints,
          totalPoints: member.totalPoints,
          isDisqualified: member.isDisqualified,
          disqualifyReason: (member.disqualifyReasons?.length ? member.disqualifyReasons.join(',') : member.disqualifyReason) || null,
          btcuReward: member.btcuReward
        });
      }
    }

    // 全デポジッター行を追加（自己デポジット含む・depositId毎の報酬＝正当な複数行。
    // 同一ユーザーの複数行はwrite-worker側で1回のCASに束ねられる）
    for (const depResult of depositorResults) {
      const uid = depResult.depositorUid;
      if (!uid) continue;
      rows.push({
        uid: String(uid),
        ...(opts.replace ? { replaceResults: true } : {}),
        role: 'depositor',
        groupId: depResult.groupId,
        autoDistributed: opts.autoDistributed === true,
        depositId: depResult.depositId,
        playerUid: depResult.playerUid,
        btcuReward: depResult.btcuReward
      });
    }

    // R20-F1: 今回の正典集合から消えた旧depositor UIDにも置換通知を送り、
    // shardのgame_depositsにpositiveな旧行を残さない。
    if (opts.replace) {
      const present = new Set(rows.map(row => row.uid));
      for (const uid of (opts.replaceUids || []).map(String)) {
        if (!uid || present.has(uid)) continue;
        rows.push({ uid, role: 'replace_marker', replaceResults: true });
        present.add(uid);
      }
    }

    const chunks = this.buildShardWriteChunks(rows);
    const shardStats = { totalWritten: 0, totalErrors: 0 };
    const totalWritten = await this.sendShardWriteChunks('/write-game-results', blockNum, chunks, {
      cursorKey: this.calcKey(blockNum, 'shards_cursor'),
      stats: shardStats,
    });
    console.log(`writeGameResultsToShards: ${totalWritten} written across ${chunks.length} chunks (${rows.length} rows)`);
    return { totalWritten, totalErrors: shardStats.totalErrors, totalChunks: chunks.length };
  }

  // R2からファイルを取得
  // S3-012（2026-07-29）: ゲームのライフサイクル（グループ分け → チャット初期化 → フェーズ遷移）が
  // 止まっている要因を1箇所に集める。集計（calc_*）と anchor しか見ていなかった監視の穴を埋める。
  // 読み取り専用・軽量（park マーカーと progress の走査のみ）。
  autoDistributeRecoveryHint(blockNum, groupingProgress, autoProgress) {
    if (!autoProgress?.selectionHash) return null;
    if (autoProgress.stage === 'done' && groupingProgress?.status === 'completed') return null;
    // grouping 側の新しい選出不一致があれば、checkpoint の古い archive 障害を優先しない。
    const currentError = groupingProgress?.error || autoProgress.lastError;
    if (autoProgress.stage !== 'done'
        && /archive_rpc_required/.test(String(currentError || ''))) {
      return `POST /restart-auto-distribute {"block_num":${blockNum}}`;
    }
    if (groupingProgress?.status === 'parked') {
      return `POST /start-grouping {"block_num":${blockNum},"recover_park":true}`;
    }
    return `POST /start-grouping {"block_num":${blockNum}}`;
  }

  async collectLifecycleBlockers() {
    const blockers = [];
    const groupingRuntimeAll = [];

    // フェーズ遷移 / チャット初期化の park
    const parkedMap = await this.storage.list({ prefix: 'phase_task_parked:', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, v] of parkedMap) {
      blockers.push({
        kind: 'phase_task_parked',
        key,
        blockNum: v?.blockNum ?? null,
        target: v?.targetPhase ?? v?.type ?? null,
        attempts: v?.attempts ?? null,
        parkedAt: v?.parkedAt ?? null,
        lastError: v?.lastError ?? null,
        recover: v?.type === 'roster_anchor'
          ? `原因を直した後、API_SECRET付き POST /init-chat-games {"block_num":${v.blockNum}}（登録済みなら再判定のみ）`
          : 'POST /advance-phase または POST /init-chat-games',
      });
    }

    // グループ分けの failed / parked
    const groupingMap = await this.storage.list({ prefix: 'grouping_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, v] of groupingMap) {
      if (!key.endsWith('_progress')) continue;
      if (v?.status === 'started') {
        groupingRuntimeAll.push({
          key,
          blockNum: v?.blockNum ?? null,
          phase: v?.phase ?? null,
          leaseUntil: v?.leaseUntil ?? null,
          leaseExpired: Number(v?.leaseUntil || 0) <= Date.now(),
          attempts: v?.attempts ?? null,
        });
      }
      if (v?.status !== 'failed' && v?.status !== 'parked') continue;
      const dependencyCause = v?.timelineCause || this.groupingDependencyCause(v?.error);
      const autoCheckpoint = await this.storage.get(`auto_distribute_block${v?.blockNum}`);
      const autoRecover = this.autoDistributeRecoveryHint(v.blockNum, v, autoCheckpoint);
      const dependencyAutoResume = dependencyCause === 'previous_block_not_ready'
        || dependencyCause === 'previous_block_anchor_pending';
      const previousBlock = Number.isSafeInteger(Number(v?.blockNum))
        ? Math.max(0, Number(v.blockNum) - 1) : 'N-1';
      blockers.push({
        kind: `grouping_${v.status}`,
        key,
        blockNum: v?.blockNum ?? null,
        phase: v?.phase ?? null,
        // S3-007: resumable な failed は自動再開待ち（人手不要）
        autoResuming: v.status === 'failed' && (!!v.resumable || dependencyAutoResume),
        resumeAttempts: v?.resumeAttempts ?? 0,
        waiting: ['auto_distribution_proof_pending', 'evidence_window_pending'].includes(v.waitReason)
          ? { reason: v.waitReason, until: v.waitUntil, detail: v.waitDetail } : null,
        error: v?.error ?? null,
        recover: v.status === 'failed' && v.waitReason === 'evidence_window_pending'
          ? 'Evidenceの窓の確定待ち。チェーンを定期的に確認し、自動再開する'
          : v.status === 'failed' && v.waitReason === 'auto_distribution_proof_pending'
          ? '自動配布の証明待ち。controllerを定期的に確認し、自動再開する'
          : autoRecover || (v.status === 'parked'
          ? 'POST /start-grouping {"block_num":N,"recover_park":true}'
          : dependencyCause === 'previous_block_not_ready'
            ? `30秒ごとに自動再試行中。前ブロック${previousBlock}は chatCloseAt 後かつ結果窓終了+安全ブロック後に /advance-phase で chatting→submitting→completed まで進める。/calculate-results 単独は group archive 不足で scoring が park する。N+1 の開始窓が閉じる約1時間前までに完了させる`
            : dependencyCause === 'previous_block_anchor_pending'
              ? `30秒ごとに自動再試行中。前ブロック${previousBlock}のanchor完了を待つ／必要なら POST /anchor-result?block=${previousBlock}`
              : 'POST /start-grouping'),
      });
    }

    // S3-008: 照合待ち（ゲーム開始を止めている状態）も同じ画面に出す
    const waitMap = await this.storage.list({ prefix: 'timeline_wait_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, w] of waitMap) {
      blockers.push({
        kind: 'timeline_unverified',
        key,
        blockNum: w?.blockNum ?? null,
        cause: w?.cause ?? null,                       // chain_unreadable | env_chain_mismatch
        attempts: w?.attempts ?? 0,
        waitedMinutes: w?.firstSeenAt ? Math.round((Date.now() - w.firstSeenAt) / 60000) : null,
        canStartUntil: w?.deadlineMs ?? null,
        minutesLeft: w?.deadlineMs ? Math.round((w.deadlineMs - Date.now()) / 60000) : null,
        deadlineSource: w?.deadlineSource ?? null,
        rpcEndpoints: w?.rpcConfig?.count ?? null,
        rpcIndependentProviders: w?.rpcConfig?.independentProviders ?? null,
        rpcHosts: w?.rpcConfig?.hosts ?? null,
        recover: w?.origin === 'roster_gate'
          ? `ChatGameDO は初期化済み。関門から timeline no-game へは移さない。名簿履歴・RPC・env を確認し、開始窓が迫れば運営が期限内に grace を手動延長する。登録済みparkはAPI_SECRET付き POST /init-chat-gamesで解除`
          : w?.cause === 'chain_unreadable'
          ? `${RPC_LIST_ENV} に RPC を追加して再デプロイ（30分ごとに自動再試行中）`
          : w?.cause === 'previous_block_not_ready'
            ? `30秒ごとに自動再試行中。前ブロック${Math.max(0, Number(w?.blockNum || 0) - 1)}は結果窓終了+安全ブロック後に /advance-phase で chatting→submitting→completed まで進める。/calculate-results 単独は scoring が park する`
            : w?.cause === 'previous_block_anchor_pending'
              ? `30秒ごとに自動再試行中。前ブロック${Math.max(0, Number(w?.blockNum || 0) - 1)}のanchor完了を待つ／必要なら POST /anchor-result?block=${Math.max(0, Number(w?.blockNum || 0) - 1)}`
              : 'env の START_TIME/BLOCK_TIME/GAME_PERIOD/SUBMIT_PERIOD を契約値に合わせる（30分ごとに自動再試行中）',
      });
    }

    const rosterReadMap = await this.storage.list({ prefix: 'roster_submission_read_failed_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, value] of rosterReadMap) {
      blockers.push({
        kind: 'roster_submission_read_failed', key, blockNum: value?.blockNum ?? null,
        error: value?.error ?? null, at: value?.at ?? null,
        autoResuming: true,
        recover: '名簿履歴・currentGrace・チェーン時刻の読取を復旧する。集計は再試行し、復旧後に判定を再開する',
      });
    }

    const gateMap = await this.storage.list({ prefix: 'roster_gate_blocked_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, value] of gateMap) {
      blockers.push({
        kind: 'roster_gate_blocked', key, blockNum: value?.blockNum ?? null,
        cause: value?.reason ?? null, canStartUntil: value?.canStartUntil ?? null,
        recover: value?.reason === 'groups_incomplete'
          ? `D1 の全組と R2 entries/block${value?.blockNum}/game_groups.json の組 ID、完了印を照合して復旧。復旧後に POST /init-chat-games {"block_num":${value?.blockNum}}`
          : `チェーンの名簿鍵の最後の登録と R2 games/block${value?.blockNum}/roster/manifest.json の keccak を照合。GCPの保全物で確かめた正しい H を test_hashStorage.js メニュー4 から最後に登録。乗っ取りなら changeAdmin 後、新しい管理鍵を送信係へ渡す前（凍結中）に手元の Hardhat から送る。鍵を渡した後なら静穏な nonce 窓で送る。env 脱落は修正・再配備。宣言開始が迫れば BLOCK_TIME 以内で POST /extend-grace`,
      });
    }
    const rosterGasMap = await this.storage.list({ prefix: 'roster_gate_gas_wait_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, value] of rosterGasMap) {
      blockers.push({
        kind: 'roster_gate_gas_wait', key, blockNum: value?.blockNum ?? null,
        cause: value?.gasReason ?? null, operation: value?.operation ?? null,
        chatCloseAt: value?.chatCloseAt ?? null,
        recover: '名簿登録の確定後、chatCloseAt−30分の窓が応募終了+BLOCK_TIME−(64確認+関門周期)より前にある間に API_SECRET付き POST /extend-grace で grace=BLOCK_TIME。名簿確定前は遠い延長を送らない',
      });
    }
    const coordinatorStatus = await getAdminTxCoordinatorStatus(this.env);
    if (coordinatorStatus?.ok === true && coordinatorStatus?.adminFreeze?.active === true) {
      const freezeDeadlines = new Map();
      for (const held of coordinatorStatus.adminFreezeHeld || []) {
        if (!['setRosterManifestHash', 'extendGrace'].includes(held?.operation)) continue;
        const blockNum = Number(held.blockNum);
        if (!Number.isSafeInteger(blockNum) || blockNum < 0) continue;
        const declared = this.getDeclaredTimesMs(blockNum, 0);
        if (declared?.entryEndMs && Date.now() < declared.entryEndMs) continue;
        if (!this.env.BITCOINU_DATA) continue;
        let groups;
        try {
          ({ results: groups } = await this.env.BITCOINU_DATA.prepare(
            'SELECT group_id, status FROM game_groups WHERE block_num = ?'
          ).bind(blockNum).all());
        } catch (error) {
          console.error('[roster-gate] freeze status group read failed:', error?.message || error);
          continue;
        }
        const started = Array.isArray(groups) && groups.some((group) =>
          ['chatting', 'submitting', 'completed'].includes(group.status));
        if (started) continue;
        if (!freezeDeadlines.has(blockNum)) {
          const declaredDeadline = await this.startWindowDeadlineMs(blockNum);
          let chainDeadlineMs = null;
          let deadlineSource = 'chain_unavailable';
          let snapshotReadAt = null;
          if (this.env.EVIDENCE_CONTRACT_ADDRESS) {
            // D-07: 無認証の /status・/calc-status から届くので、使い回しつきの読み取りを通す（下の helper）。
            const closeSec = await this.readAdminFreezeChatCloseSec(blockNum);
            if (closeSec !== null) {
              chainDeadlineMs = closeSec * 1000;
              deadlineSource = 'chain_latest';
            }
          }
          if (chainDeadlineMs === null) {
            const snapshot = await this.storage.get(`evidence_tl_snapshot_block${blockNum}`);
            if (Number.isSafeInteger(snapshot?.chatCloseAt) && snapshot.chatCloseAt > 0) {
              chainDeadlineMs = snapshot.chatCloseAt * 1000;
              deadlineSource = 'chain_snapshot';
              snapshotReadAt = snapshot.readAt ?? null;
            }
          }
          freezeDeadlines.set(blockNum, {
            chainDeadlineMs, deadlineSource, snapshotReadAt,
            declaredChatCloseAt: declaredDeadline.deadlineMs,
            declaredDeadlineSource: declaredDeadline.source,
          });
        }
        const deadline = freezeDeadlines.get(blockNum);
        blockers.push({
          kind: 'roster_gate_admin_freeze', blockNum, operation: held.operation,
          intentId: held.intentId ?? null, chatCloseAt: deadline.chainDeadlineMs,
          minutesLeft: Number.isFinite(deadline.chainDeadlineMs)
            ? Math.round((deadline.chainDeadlineMs - Date.now()) / 60000) : null,
          deadlineSource: deadline.deadlineSource, snapshotReadAt: deadline.snapshotReadAt,
          declaredChatCloseAt: deadline.declaredChatCloseAt,
          declaredDeadlineSource: deadline.declaredDeadlineSource,
          recover: `block ${blockNum} の ${held.operation} は admin_freeze で保留。` +
            `test_evidence.js メニュー2 でチェーンの chatWindow(${blockNum}).chatCloseAt を確認。` +
            `鍵の引き渡し前に開始窓が閉じる見込みなら、新しい管理鍵で手元の Hardhat の test_evidence.js メニュー4 から、` +
            `chatCloseAt の前に BLOCK_TIME 以下で新しい開始（応募終了＋grace）が今より後になる Evidence.extendGrace を送って着地を確認する` +
            `（開始が START_PAST_TOLERANCE 以上過去になる値は Start in past で落ちる。メニュー4 が送る前に止める）。` +
            `名簿鍵は GCP の保全物で確かめた正しい H だけを、changeAdmin 後、新しい管理鍵を送信係へ渡す前（凍結中）に` +
            `test_hashStorage.js メニュー4 から最後に登録する。保留中の名簿積荷はそのまま送らない。` +
            `鍵を渡した後なら静穏な nonce 窓で手送信する。1組でも chatting のブロックは延長しない`,
        });
      }
    }

    const splitMap = await this.storage.list({ prefix: 'timeline_started_no_extend_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, value] of splitMap) {
      const expectedLateStart = value?.reason === 'started_with_roster';
      blockers.push({
        kind: expectedLateStart ? 'started_with_roster_late' : 'timeline_split_prevented', key,
        blockNum: value?.blockNum ?? null,
        groupIds: value?.groupIds ?? [],
        statuses: value?.statuses ?? [],
        detectedAt: value?.detectedAt ?? null,
        detail: value?.reason ?? null,
        recover: expectedLateStart
          ? '名簿つきで開始に達したため延長せず、既存graceのまま遅れて chatting へ進んだ（案 U・想定内）。'
            + 'submitting へ進むと消える。名簿の確認待ちなら次の再判定を待つ'
          : 'グループの実フェーズとEvidence窓を確認し、開始後にgraceを延長しない',
      });
    }

    const lateRosterMap = await this.storage.list({ prefix: 'roster_anchor_late_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, value] of lateRosterMap) {
      const terminal = await this.storage.get(`roster_shield_terminal_block${value?.blockNum}`);
      // 便 C32F2（検証役の指摘）: shield の終端印のうち、自動の延長では開始窓が戻らないものは手動終端を案内する。
      //   chat_window_closed／deadline_expired: チャット窓が閉じた（期限切れ）。
      //   start_in_past: 上限（BLOCK_TIME）で頭打ちの目標でも新しい開始が今から START_PAST_TOLERANCE 以上過去
      //     （shieldRosterStartWindow は頭打ちのときだけこの終端印を書く）。それより小さい grace の開始はさらに過去なので、
      //     どの延長も Evidence が "Start in past" で拒否する。
      //   grace_exceeds_block_time: 目標がチェーンの BLOCK_TIME を超えた（env の食い違い）。手の延長を先に案内する。
      const lostWindowRecover = `開始窓を失ったblock ${value?.blockNum} は chatCloseAt 後、結果窓終了と安全ブロックの確認後、N+1の開始可能期限の約1時間前までに API_SECRET付き POST /advance-phase で chatting→submitting→completed と順に手動終端する。開始前の正典名簿登録が無いブロックは手動3段で閉じても提出物は採られず配分0。/calculate-results 単独では group archive 不足で park する`;
      const terminalResult = terminal?.rpcAgreement >= 2
        ? terminal.result : null;
      const singleProvider = !this.createEvidenceReadClients();
      blockers.push({
        kind: 'roster_anchor_late', key,
        blockNum: value?.blockNum ?? null,
        updatedBlock: value?.updatedBlock ?? null,
        updatedTimestampMs: value?.updatedTimestampMs ?? null,
        chattingStart: value?.chattingStart ?? null,
        recover: ['chat_window_closed', 'deadline_expired', 'start_in_past'].includes(terminalResult)
          ? (terminalResult === 'start_in_past'
            ? `上限（BLOCK_TIME）の grace でも新しい開始が今から START_PAST_TOLERANCE 以上過去になり、Evidence.extendGrace が Start in past で拒否するので、延長では開始できない。${lostWindowRecover}`
            : lostWindowRecover)
          : terminalResult === 'grace_exceeds_block_time'
            ? `shield の目標がチェーンの BLOCK_TIME を超えて終端した（env の BLOCK_TIME の食い違い）。チェーンの BLOCK_TIME ちょうどで API_SECRET付き POST /extend-grace を試す（新しい開始が今から START_PAST_TOLERANCE 以上過去なら GM は送らずに start_in_past を返す）。延ばせなければ、${lostWindowRecover}`
            : singleProvider
              ? `終端の印は2業者の確定の読みでだけ書く。1業者の構成ではチェーンのchatCloseAt・grace・名簿を手で確かめる。${lostWindowRecover}`
              : 'grace延長のEvidence.currentGrace着地と名簿登録の確定を待つ。登録済みでもparkした場合はAPI_SECRET付き POST /init-chat-gamesで再判定を再開',
      });
    }

    // K-S5-002: ガス価格待ち（root 提出＝請求開始を止めている状態）。
    // park とは違い手動介入は要らない（下がれば自動で出る）が、見えないと
    // 「なぜ請求が始まらないのか」が分からないので必ず出す。
    const gasWaitMap = await this.storage.list({ prefix: 'gas_wait_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, w] of gasWaitMap) {
      const deadlineAt = w?.deadlineAt != null && Number.isSafeInteger(Number(w.deadlineAt))
        ? Number(w.deadlineAt) : null;
      const deadlineDaysLeft = deadlineAt === null ? null : (deadlineAt - Date.now()) / DAY_MS;
      const deadlineReason = deadlineDaysLeft === null
        ? 'root提出期限までの残り日数は不明'
        : `root提出期限まで残り${deadlineDaysLeft.toFixed(2)}日`;
      blockers.push({
        kind: 'gas_price_wait',
        key,
        blockNum: w?.blockNum ?? null,
        currentGwei: w?.currentGwei ?? null,
        limitGwei: w?.limitGwei ?? null,
        limitSource: w?.limitSource ?? null,
        attempts: w?.attempts ?? 0,
        waitedMinutes: w?.firstSeenAt ? Math.round((Date.now() - w.firstSeenAt) / 60000) : null,
        deadlineAt,
        deadlineDaysLeft,
        autoResuming: true,
        recover: `${deadlineReason}。${GameMasterDO.TIMELINE_RETRY_MS / 60000}分ごとに自動再試行（期限前に要確認）／`
          + `上限変更は test.js のメニュー／即時提出は POST /submit-merkle-root {"block_num":N,"force":true}`,
      });
    }

    // G2: 証明サービスの遅延・Batch失敗・cleanup失敗。初回の失敗から残し、
    // 20回後の park を待たず運用者が手動フォールバックに移れるようにする。
    const zkpIssueMap = await this.storage.list({ prefix: 'zkp_proof_issue_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, issue] of zkpIssueMap) {
      blockers.push({
        kind: issue?.kind || 'zkp_proof_issue',
        key,
        blockNum: issue?.blockNum ?? null,
        level: issue?.level ?? null,
        jobId: issue?.jobId ?? null,
        reason: issue?.reason ?? null,
        error: issue?.error ?? null,
        detail: issue?.detail ?? null,
        attempt: issue?.attempt ?? null,
        at: issue?.at ?? null,
        recover: issue?.recover || 'docs/OPS_TASKS.md G2 の切り分け・手動フォールバック',
      });
    }

    // R20-F8: root先行後のproof／job／cleanup状態。proof生成中は障害ではないが、
    // rootとは独立した費用と期限を持つためmonitorから常に見えるようにする。
    const postCommitMap = await this.storage.list({ prefix: 'post_commit_zkp_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, item] of postCommitMap) {
      if (item?.status === 'proof_attached'
        || (item?.status === 'proof_abandoned' && item?.cleanupStatus !== 'zkp_cleanup_pending')) continue;
      blockers.push({
        kind: item?.cleanupStatus === 'zkp_cleanup_pending' ? 'zkp_cleanup_pending' : 'post_commit_proving',
        key,
        blockNum: item?.blockNum ?? Number(String(key).replace('post_commit_zkp_block', '')),
        status: item?.status ?? null,
        jobId: item?.jobId ?? null,
        root: item?.root ?? null,
        deadlineAt: item?.deadlineAt ?? null,
        phase: item?.phase ?? null,
        attempt: item?.attempt ?? null,
        cleanupStatus: item?.cleanupStatus ?? null,
        cleanupError: item?.cleanupError ?? null,
        recover: item?.cleanupStatus === 'zkp_cleanup_pending'
          ? 'alarmが取り消し済みjobのcleanupを再試行中'
          : 'rootは確定済み。進行中のproofを追跡し、同一rootへのattachを継続中',
      });
    }

    // 🔴 ラウンド19 判断不要-4（2026-08-08）: チャット期間を飛ばしたグループ。
    //    park キーが立たないので旧 blockers は空のままだった（＝「静かな0点」）。
    // 🔴 R-2（2026-08-08・ラウンド20 回帰-2）: `chatting → completed`（提出期間の消滅）も
    //    ここに出る。ただし提出窓は既に閉じているので**復旧はできない**（事後アラート）。
    const skippedMap = await this.storage.list({ prefix: 'phase_skipped_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, v] of skippedMap) {
      const chatLost = (v?.lost ?? '').includes('chat window');
      blockers.push({
        kind: 'phase_skipped',
        key,
        blockNum: v?.blockNum ?? null,
        target: v?.targetPhase ?? null,
        groupIds: v?.skippedGroupIds ?? null,
        lost: v?.lost ?? null,
        at: v?.at ?? null,
        recover: (v?.lost === undefined || chatLost)
          ? `POST /advance-phase {"block_num":${v?.blockNum ?? 'N'},"phase":"chatting"}（チャット窓が開いていれば冪等に復旧）`
          : '復旧不可（宣言窓が既に閉じている）— park した phase タスク／手動 /advance-phase の調査へ',
      });
    }

    // 🔴 C-1 / ラウンド19 判断不要-3（2026-08-08）: manifest の公開・アンカー失敗。
    //    これが立っているブロックは「root は出ていないのに集計は終わったように見える」
    //    （ゲーム無し／自動配布経路）か「manifest 段で park している」のどちらか。
    //    どちらも block-verifier の Stage C を恒久 FAIL にするので必ず見えるところに出す。
    const verifyFailMap = await this.storage.list({ prefix: 'verification_publish_failed_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, v] of verifyFailMap) {
      blockers.push({
        kind: 'verification_publish_failed',
        key,
        blockNum: v?.blockNum ?? null,
        error: v?.error ?? null,
        reason: v?.reason ?? null,
        pending: v?.pending === true,
        firstSeenAt: v?.firstSeenAt ?? null,
        lastSeenAt: v?.lastSeenAt ?? null,
        notifiedAt: v?.notifiedAt ?? null,
        at: v?.at ?? null,
        recover: 'R2/RPC を復旧して POST /calculate-results（ゲーム無し・自動配布ブロックは POST /anchor-result → POST /submit-merkle-root）',
      });
    }

    const verifyFreezeMap = await this.storage.list({ prefix: 'verification_admin_freeze_block', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, v] of verifyFreezeMap) {
      blockers.push({
        kind: 'verification_admin_freeze',
        key,
        blockNum: v?.blockNum ?? null,
        source: v?.source ?? null,
        reason: 'admin_freeze',
        intentId: v?.intentId ?? null,
        at: v?.at ?? null,
        recover: '送信係の鍵を、検出された新しいオンチェーン管理鍵に更新する（一致後に自動解除）',
      });
    }

    const restartRejectedMap = await this.storage.list({ prefix: 'calc_restart_rejected_', limit: PUBLIC_STORAGE_LIST_LIMIT });
    for (const [key, value] of restartRejectedMap) {
      blockers.push({
        kind: 'calc_restart_rejected',
        key,
        blockNum: value?.blockNum ?? null,
        request: value?.request ?? null,
        errorCode: value?.errorCode ?? null,
        error: value?.error ?? null,
        rejectedAt: value?.rejectedAt ?? null,
        recover: 'errorCode の原因を解消して restart を明示的に再要求',
      });
    }

    const queue = await this.storage.get('phase_task_queue') || [];
    let activeTaskRead;
    try {
      activeTaskRead = {
        value: await this.storage.get('phase_task_active') || null,
        state: 'succeeded',
        error: null,
      };
    } catch (error) {
      activeTaskRead = {
        value: null,
        state: 'failed',
        error: this.observationErrorText(error),
      };
    }
    const activeTask = activeTaskRead.value;
    const alarm = await this.inspectAlarmState(Array.isArray(queue) ? queue : []);
    const now = Date.now();
    const taskDetailsAll = (Array.isArray(queue) ? queue : [])
      .map((task) => this.slimPhaseTask(task, now))
      .sort((a, b) => Number(a.executeAt ?? Number.MAX_SAFE_INTEGER) - Number(b.executeAt ?? Number.MAX_SAFE_INTEGER));
    const taskRuntime = {
      state: activeTaskRead.state, at: now,
      ...(activeTaskRead.error ? { error: activeTaskRead.error } : {}),
      queued: taskDetailsAll.slice(0, MONITOR_TASK_LIMIT),
      queuedOmitted: Math.max(0, taskDetailsAll.length - MONITOR_TASK_LIMIT),
      overdueCount: taskDetailsAll.filter((task) => task.overdue).length,
      active: this.slimPhaseTask(activeTask, now),
      alarm,
    };
    if (alarm.state === 'succeeded' && alarm.missingAlarm) {
      blockers.push({
        kind: 'phase_tasks_without_alarm', blockNum: null,
        overdueCount: taskRuntime.overdueCount,
        recover: 'DO alarm と phase_task_queue を確認し、必要なら対象操作を冪等に再実行',
      });
    }
    const [calcBootstrapWatchdog, doneArtifactWatchdog] = await Promise.all([
      this.inspectCalcBootstrapWatchdog(),
      this.inspectDoneArtifactWatchdog(),
    ]);
    for (const blockNum of calcBootstrapWatchdog.missingProgress?.values || []) {
      blockers.push({
        kind: 'completed_groups_without_calc_progress', blockNum,
        recover: `POST /calculate-results {"block_num":${blockNum}}`,
      });
    }
    for (const item of doneArtifactWatchdog.blocks || []) {
      if (item.state !== 'failed') continue;
      blockers.push({
        kind: 'done_block_missing_downstream_artifact', blockNum: item.blockNum,
        missingRequired: item.missingRequired,
        observationFailures: item.observationFailures,
        recover: `GET /calc-status?block=${item.blockNum} で深い検査後、R2/RPCを復旧して冪等に再実行`,
      });
    }
    const groupingRuntime = groupingRuntimeAll
      .sort((a, b) => Number(a.blockNum ?? 0) - Number(b.blockNum ?? 0))
      .slice(0, GROUP_OBSERVATION_GROUP_LIMIT)
      .map((runtime) => {
        const watchdogTasks = (Array.isArray(queue) ? queue : []).filter((task) => (
          task.type === 'grouping_watchdog' && Number(task.blockNum) === Number(runtime.blockNum)
        ));
        const watchdogActive = activeTask?.type === 'grouping_watchdog'
          && Number(activeTask.blockNum) === Number(runtime.blockNum);
        return {
          ...runtime,
          watchdogQueued: watchdogTasks.length,
          watchdogExecuteAt: watchdogTasks.length > 0
            ? Math.min(...watchdogTasks.map((task) => Number(task.executeAt)).filter(Number.isFinite))
            : null,
          watchdogActive,
          watchdogPresent: watchdogTasks.length > 0 || watchdogActive,
          alarm,
        };
      });
    for (const runtime of groupingRuntime) {
      if (!runtime.watchdogPresent) {
        blockers.push({
          kind: 'grouping_started_without_watchdog',
          key: runtime.key,
          blockNum: runtime.blockNum,
          phase: runtime.phase,
          leaseUntil: runtime.leaseUntil,
          recover: 'POST /start-grouping（期限内なら現処理を維持、期限切れならlease takeover）',
        });
      }
    }
    blockers.sort((a, b) => (a.blockNum ?? 0) - (b.blockNum ?? 0));
    return {
      blockers,
      queueLength: queue.length,
      queueOldestExecuteAt: queue.length > 0 ? Math.min(...queue.map(t => t.executeAt ?? 0)) : null,
      activeTask: activeTask || null,
      alarm,
      taskRuntime,
      calcBootstrapWatchdog,
      doneArtifactWatchdog,
      groupingRuntime,
      groupingRuntimeOmitted: Math.max(0, groupingRuntimeAll.length - GROUP_OBSERVATION_GROUP_LIMIT),
    };
  }

  // D-07（2026-09-26 ユーザー決定・便 S3C6）: 送信係の凍結中だけ collectLifecycleBlockers が読む
  // Evidence.chatWindow(N).chatCloseAt（秒）。呼び手は無認証の GET /status・/calc-status なので、
  // readBlockLifecycle と同じ型（ブロック番号を鍵にした isolate 内の使い回し・BLOCK_LIFECYCLE_CACHE_TTL_MS／
  // BLOCK_LIFECYCLE_CACHE_LIMIT）に入れ、同じブロックの eth_call を TTL 内で1回にする。読めない・RPC 未設定は
  // null（呼び手は保存済み snapshot へ回る）で、失敗も同じ TTL だけ使い回して RPC を連打しない。
  // 監視の表示専用（状態変更の判定には使わない）なので、最大 TTL 分古い値を許す。
  readAdminFreezeChatCloseSec(blockNum) {
    if (!this._adminFreezeChatWindowCache) this._adminFreezeChatWindowCache = new Map();
    const cache = this._adminFreezeChatWindowCache;
    const cacheKey = String(blockNum);
    const now = Date.now();
    const cached = cache.get(cacheKey);
    if (cached && cached.expiresAt > now) return cached.promise;
    const promise = (async () => {
      try {
        const client = this.createReadOnlyClient();
        if (!client) return null;
        const chatWindow = await client.readContract({
          address: this.env.EVIDENCE_CONTRACT_ADDRESS,
          abi: [{ name: 'chatWindow', type: 'function', stateMutability: 'view',
            inputs: [{ name: 'blockNum', type: 'uint256' }],
            outputs: [{ name: 'chatOpenAt', type: 'uint256' }, { name: 'chatCloseAt', type: 'uint256' }] }],
          functionName: 'chatWindow', args: [BigInt(blockNum)],
        });
        const closeSec = Number(chatWindow?.[1]);
        return Number.isSafeInteger(closeSec) && closeSec > 0 ? closeSec : null;
      } catch (error) {
        console.warn('[roster-gate] freeze chatWindow read failed:', error?.message || error);
        return null;
      }
    })();
    for (const [key, value] of cache) {
      if (value.expiresAt <= now) cache.delete(key);
    }
    while (cache.size >= BLOCK_LIFECYCLE_CACHE_LIMIT) {
      cache.delete(cache.keys().next().value);
    }
    cache.set(cacheKey, { expiresAt: now + BLOCK_LIFECYCLE_CACHE_TTL_MS, promise });
    return promise;
  }

  // Q44: 公開summaryのreason文字列だけでは除外しない。finalizeNoGameBlock が安全確定後に
  // 同じ処理内で保存する Evidence 0件記録と noGameFinality の両方が一致して初めて対象にする。
  async readFinalizedTimelineNoGame(blockNum) {
    const [summary, reconciled, cleanupBefore] = await Promise.all([
      this.getR2Object(`games/block${blockNum}/summary.json`),
      this.storage.get(`evidence_reconciled_block${blockNum}`),
      this.storage.get(this.timelineNoGameCleanupKey(blockNum)),
    ]);
    const finality = summary?.noGameFinality;
    const expectedEvidence = String(this.env.EVIDENCE_CONTRACT_ADDRESS || '').toLowerCase();
    const recordedEvidence = String(finality?.evidenceContract || '').toLowerCase();
    const baseValid = Number(summary?.blockNum) === Number(blockNum)
      && summary?.noGame === true
      && summary?.noGameReason === 'timeline_unverified'
      && Number.isSafeInteger(Number(summary?.totalPlayers)) && Number(summary.totalPlayers) >= 3
      && Number(summary?.totalGroups) === 0
      && Array.isArray(summary?.groups) && summary.groups.length === 0
      && finality?.schemaVersion === 1
      && finality?.resultCount === 0
      && Number.isSafeInteger(finality?.safeTimestamp)
      && Number.isSafeInteger(finality?.resultCloseAt)
      && finality.safeTimestamp >= finality.resultCloseAt
      && recordedEvidence.length > 0
      && (!expectedEvidence || recordedEvidence === expectedEvidence)
      && reconciled?.resultCount === 0
      && reconciled?.adoptedCount === 0;
    if (!baseValid) return null;

    // Q50 配備前に Q44 が確定したブロックも、proof除外へ進める前に同じ cleanup を
    // DO storage へ backfill する。公開済み summary は immutable として一切書き換えない。
    const cleanup = cleanupBefore?.status === 'completed'
      ? cleanupBefore
      : await this.cleanupTimelineNoGameBlock(blockNum);
    const cleanupValid = cleanup?.schemaVersion === 1
      && Number(cleanup?.blockNum) === Number(blockNum)
      && cleanup?.reason === 'timeline_unverified'
      && cleanup?.status === 'completed'
      && cleanup?.d1Status === TIMELINE_NO_GAME_INVALIDATED_STATUS
      && cleanup?.artifactsPreserved === true;
    return cleanupValid ? { summary, finality, reconciled, cleanup } : null;
  }

  async finishTimelineNoGameProofRoute(blockNum, progress, chainConfig, finalization) {
    if (chainConfig?.configUnavailable) {
      throw new Error(`[zkProof] proofRequired unavailable for finalized timeline no-game block ${blockNum}`);
    }
    const required = chainConfig?.required === true;
    const existingPostCommit = await this.storage.get(this.postCommitZkpKey(blockNum));
    const excludedJobId = progress.zkProof?.jobId || existingPostCommit?.jobId || null;
    const operatorFallbackRequestedAt = progress.zkProof?.operatorFallbackRequestedAt;
    const operatorFallbackReason = progress.zkProof?.operatorFallbackReason;
    progress.parked = false;
    progress.failures = 0;
    progress.lastError = null;
    delete progress.waitUntil; delete progress.waitReason; delete progress.waitDetail;
    await this.clearZkpProofIssue(blockNum);
    if (!required && operatorFallbackRequestedAt) {
      progress.stage = 'zkProof';
      let cleanup = null;
      if (excludedJobId) {
        cleanup = await this.cancelPostCommitZkp(blockNum, {
          ...(existingPostCommit || {}),
          blockNum,
          jobId: excludedJobId,
          root: progress.merkle?.root || existingPostCommit?.root || null,
        }, 'timeline_no_game_proof_excluded');
      }
      await this.finishShadowZkpFallback(blockNum, progress, {
        reason: 'operator_bypass',
        detail: operatorFallbackReason || 'operator_requested',
        cancelledState: cleanup,
      });
      if (excludedJobId) {
        progress.zkProof.excludedJobId = excludedJobId;
        progress.zkProof.cleanupStatus = cleanup.cleanupStatus;
        progress.zkProof.cleanupError = cleanup.cleanupError || null;
      }
      return progress;
    }
    let cleanup = null;
    if (excludedJobId) {
      cleanup = await this.cancelPostCommitZkp(blockNum, {
        ...(existingPostCommit || {}),
        blockNum,
        jobId: excludedJobId,
        root: progress.merkle?.root || existingPostCommit?.root || null,
      }, 'timeline_no_game_proof_excluded');
    }
    progress.zkProof = {
      required,
      status: required ? 'timeline_no_game_root_omitted' : 'timeline_no_game_manual_fallback',
      excludedReason: 'timeline_unverified',
      excludedJobId,
      cleanupStatus: cleanup?.cleanupStatus || (excludedJobId ? 'zkp_cleanup_pending' : 'not_needed'),
      cleanupError: cleanup?.cleanupError || null,
      finality: finalization.finality,
      decidedAt: Date.now(),
      ...(!required ? {
        fallbackReason: 'timeline_no_game_proof_excluded',
        fallbackDetail: '証明の対象外。POST /calculate-results {"block_num":N,"zkp_fallback":true} を待機',
      } : {}),
    };
    if (!required) {
      progress.stage = 'timelineNoGameManualFallback';
      return progress;
    }
    const merkle = {
      ...(progress.merkle || {}),
      submit: { submitted: false, omitted: true, reason: 'timeline_no_game_root_omitted' },
    };
    progress.merkle = merkle;
    progress.stage = 'done';
    progress.result = {
      success: true,
      blockNum,
      groupCount: progress.groupCount ?? 0,
      totalPoints: progress.totalPoints ?? '0',
      blockReward: progress.blockRewardWei ?? getBlockRewardWei(blockNum).toString(),
      merkle,
      verification: progress.verification,
      rootOmitted: true,
      rootOmittedReason: 'timeline_no_game_root_omitted',
    };
    return progress;
  }

  async refreshExistingTimelineNoGameProgress(blockNum, progress) {
    if (!((progress?.parked && progress.stage === 'zkProof') || progress?.stage === 'timelineNoGameManualFallback')) return progress;
    const finalization = await this.readFinalizedTimelineNoGame(blockNum);
    if (!finalization) return progress;
    const chainConfig = await this.readZkpProofConfig({ allowUnsupportedRequired: true });
    progress = await this.finishTimelineNoGameProofRoute(blockNum, progress, chainConfig, finalization);
    progress.updatedAt = Date.now();
    await this.storage.put(this.calcProgressKey(blockNum), progress);
    if (progress.stage === 'done') await this.storage.delete(`calc_active:${blockNum}`);
    return progress;
  }

  // P-2026-0822: `summary.json` だけは**正準JSON検査を通してから**オブジェクトにする。
  //
  // ⚠️ キーで判別する。他の公開 JSON（`game_groups.json` など）には**適用してはいけない**:
  //   それらは整数に見えるキーを持つオブジェクトを含み、`JSON.parse` が仕様どおり
  //   それらを昇順へ並べ替えるため、正しく `JSON.stringify` で書かれたファイルでも
  //   往復が一致しない＝偽陽性になる（R2 実物で確認・lib/canonical-json.js のコメント参照）。
  //
  // 🔴 非正準は**握り潰さない**。不存在だけは null、R2 読取エラーは一過性の印つき例外にする。
  //   JSON parse エラーと同様に null へ潰すと「非正準な summary」が静かに「summary が無い」へ化ける。
  //   `buildBlockSummaryWithResults` は majorLangs / timeline を黙って失い、
  //   `computeMajorLangs` は「前ブロック未確定」と誤診する。理由の見える例外で止める。
  async getR2Object(key) {
    let object;
    let text;
    try {
      object = await this.env.R2_BUCKET.get(key);
      if (!object) {
        return null;
      }
      text = await object.text();
    } catch (error) {
      // R2 の一過性障害を「不存在」の null に潰さない。呼出側が再試行へ分類できる印を付ける。
      const unavailable = new Error(
        `R2 object temporarily unavailable while reading ${key}: ${error?.message || error}`
      );
      unavailable.r2ReadUnavailable = true;
      unavailable.cause = error;
      throw unavailable;
    }
    try {
      if (isCanonicalJsonRequiredKey(key)) return parseCanonicalJson(text, key);
      return JSON.parse(text);
    } catch (error) {
      if (isCanonicalJsonError(error)) throw error;
      console.error(`Error reading R2 object ${key}:`, error);
      return null;
    }
  }

  // R2 の**生テキスト**を返す（不存在は null / 読取エラーは throw）。
  // P-2026-0816: manifest の sha256 照合は「公開されたバイト列」に対して行うので、
  // getR2Object（parse 済み＋エラーを null に潰す）では代用できない
  //   ・parse → 再 stringify はキー順・数値表現でバイトが変わりうる
  //   ・読取エラーを null（＝不存在）に潰すと「アンカー対象が無い」と誤判定する
  async getR2Text(key) {
    try {
      const object = await this.env.R2_BUCKET.get(key);
      if (!object) return null;
      return await object.text();
    } catch (error) {
      const unavailable = new Error(
        `R2 object temporarily unavailable while reading ${key}: ${error?.message || error}`
      );
      unavailable.r2ReadUnavailable = true;
      unavailable.cause = error;
      throw unavailable;
    }
  }

  // S3-001: コミット済みエントリー集合の実件数（N の権威）と、その素材である info ファイル群。
  // lottery-DO.js countCommittedEntries と同じ規則 — 全100 info ファイルを合算し、
  // 1つでも欠損/型不正なら throw する（無言スキップはインデックス対応をズラす＝別人当選）。
  // GameMasterDO 側でも数え直すのは、game_selection.json の申告 totalEntries を
  // そのまま信じると「N と players を同時に書き換える」差し替えが素通りするため。
  // P-2026-0815: 読んだ info ファイルそのものも返す。当選者行の再構築
  //（globalIndex → file / localIndex）には info の filename・number が要るので、
  // 数えるためだけに読んで捨てると同じ 100 ファイルを二度読むことになる。
  async readCommittedEntryInfos(blockNum, category = 'entries') {
    // LotteryDOと同じ100個のinfoを逐次GETすると、一時的なR2遅延時にDO turnが
    // 中断され得る。Workersの同時outgoing connection上限に合わせ、固定indexを6件ずつ
    // 並列読取し、検査・合算は従来どおりindex順で行う。
    // 欠損時のFirstも不変で、採点・Merkle・manifestの規則は一切変わらない。
    const infoCount = 100;
    const readConcurrency = 6;
    const infos = new Array(infoCount);
    const keys = Array.from({ length: infoCount }, (_, infoIndex) =>
      `entries/block${blockNum}/info/${infoIndex.toString().padStart(2, '0')}_info.json`);
    for (let start = 0; start < infoCount; start += readConcurrency) {
      const loaded = await Promise.all(keys.slice(start, start + readConcurrency).map(async (infoKey, offset) => ({
        infoIndex: start + offset,
        infoData: await this.getR2Object(infoKey),
      })));
      for (const { infoIndex, infoData } of loaded) infos[infoIndex] = infoData;
    }

    let total = 0;
    const missing = [];
    for (let infoIndex = 0; infoIndex < infoCount; infoIndex++) {
      const infoKey = keys[infoIndex];
      const infoData = infos[infoIndex];
      if (!infoData) {
        missing.push(infoKey);
        continue;
      }
      const categoryData = infoData[category];
      if (!Array.isArray(categoryData)) {
        missing.push(`${infoKey} (missing "${category}" field)`);
        continue;
      }
      for (const fileInfo of categoryData) {
        total += fileInfo.number;
      }
    }
    if (missing.length > 0) {
      throw new Error(`Committed entry set incomplete: ${missing.length} of 100 info files missing/invalid. First: ${missing[0]}`);
    }
    return { total, infos };
  }

  async countCommittedEntries(blockNum, category = 'entries') {
    const { total } = await this.readCommittedEntryInfos(blockNum, category);
    return total;
  }

  // R2にファイルを保存
  // 各グループのR2アーカイブJSONにgameResultsを追記
  // フロントエンドがリロード時にGameMasterDO /game-results APIを叩かずにR2データだけで結果表示できるようにする
  async appendGameResultsToR2Groups(blockNum, allGroupResults, depositorResults, groups) {
    // 🔴 P-2026-0842（2026-08-08・台帳 C-3）: **公開アーティファクトに実行時刻を入れない。**
    //    manifest は `files[key] = sha256(公開バイト列そのもの)` を宣言し、
    //    `manifestHash = sha256({blockNum, algorithm, rules, files})` をオンチェーンへ
    //    アンカーする（`block-verifier/src/stages/results.js:165-173` が同じ式で再計算）。
    //    つまり **アーティファクトのバイトが1バイトでも動けば manifestHash が動く**。
    //    実行時刻を埋めると同一入力の再集計でも必ず値が変わり、
    //      ・`registerResultHashOnChain` が毎回「別ハッシュ」として再登録し
    //      ・`HashStorage.resultRegistrationCount` が加算され
    //      ・block-verifier の `check.stageC.resultReregistration` が
    //        「結果差し替えの可能性」WARN を出す（`:185-190`）
    //    ＝ **無害な再実行と本物の差し替えが区別できなくなる**。
    //    `manifestCore` が `createdAt` を外しているのと同じ原則を、
    //    ハッシュ対象そのもの（＝公開バイト列）にも適用する。
    //    ⚠️ 生成時刻の情報はオンチェーン（`HashStorage` の `updatedAt`／登録 tx）と
    //       `games/block{N}/claim-timing.json` に残るので、失われる情報は無い。

    const failures = [];
    for (const group of allGroupResults) {
      const r2Key = `games/block${blockNum}/group${group.groupId}.json`;

      try {
        // D1 game_results テーブルと同じ形式で結果を構築
        const gameResults = [];

        // プレイヤー行（R2には詳細データも保持 — D1テーブルとは異なり表示用）
        for (const member of group.members) {
          gameResults.push({
            userId: member.uid,
            role: 'player',
            deposit_id: '',
            address: member.addr || null,
            btcu_reward: member.btcuReward,
            deposit_to: null,
            // 表示用詳細データ（D1には保存しないがR2アーカイブには保持）
            deposit_points: member.depositPoints,
            bonus_points: member.bonusPoints,
            total_points: member.totalPoints,
            is_disqualified: member.isDisqualified ? 1 : 0,
            disqualify_reason: (member.disqualifyReasons?.length ? member.disqualifyReasons.join(',') : member.disqualifyReason) || null,
            report_gain_points: member.reportGainPoints || 0,
            vote_target_uid: member.voteTargetUid || null,
            report_target_uids: member.reportTargetUids?.length ? JSON.stringify(member.reportTargetUids) : null,
            voted_by_uids: member.votedByUids?.length ? JSON.stringify(member.votedByUids) : null
          });
        }

        // デポジッター行（自己デポジット含む全デポジット）
        const groupDepositors = depositorResults.filter(d => d.groupId === group.groupId);
        for (const depResult of groupDepositors) {
          gameResults.push({
            userId: depResult.depositorUid,
            role: 'depositor',
            deposit_id: depResult.depositId,
            address: depResult.depositerAddress,
            btcu_reward: depResult.btcuReward,
            deposit_to: depResult.playerUid,
          });
        }

        // S4: listen-worker はこの manifest 固定ファイルを更新しない。CAS は archive の
        // 他フィールドを失わず gameResults だけを確定するために維持する。
        const res = await this.mutateR2ObjectWithCAS(r2Key, (archiveData) => {
          archiveData.gameResults = gameResults;
        }, { tag: 'results' });

        if (res.missing) {
          failures.push({ groupId: group.groupId, key: r2Key, reason: 'missing' });
          continue;
        }
        if (!res.ok) {
          failures.push({ groupId: group.groupId, key: r2Key, reason: res.error || 'unknown' });
          continue;
        }
        console.log(`Game results appended to R2: ${r2Key} (${gameResults.length} rows)`);
      } catch (error) {
        failures.push({ groupId: group.groupId, key: r2Key, reason: String(error?.message || error) });
      }
    }
    if (failures.length) {
      const error = new Error(
        `[writing] failed to publish ${failures.length} group result artifact(s): `
        + failures.map(f => `${f.groupId}:${f.reason}`).join(', ')
      );
      error.failures = failures;
      throw error;
    }
  }

  // =====================================================================
  // R2 の read-modify-write を楽観的ロック（etag CAS）で行う
  //
  // 書き込み競合の網羅調査（2026-07-31）§3:
  // 旧 schema v1/v2 の `games/block{N}/summary.json` と `group{N}.json` は
  // **書き手が2人いた**。schema v3 では listen-worker の行別更新先を manifest 外の
  // `claim-status/group{G}.json` へ移したため、封印対象は game-master-DO だけが書く。
  //
  // 「請求の点検 cron が D1 から復元するので自己修復する」という受容論があったが、
  // **成立しない場合がある**（2026-07-31 に実コードで確認）:
  // 点検 cron の巡回は `state.healFloor` から始まり、確定したブロックを追い越して前進する
  // （`listen_workers/src/index_new.js` の `healFloor` / `walked`）。
  // floor が越えたブロックは**二度と巡回されない**ので、確定後に `/calculate-results` を
  // 再実行して claimed を消すと、公開データからは恒久的に失われる。
  // → 自己修復に頼らず、DO 側の書き込みでも消さないようにする。
  // =====================================================================

  // etag 競合・一時エラー時の再試行回数（listen-worker / write-worker と同値）
  static get R2_CAS_MAX_RETRIES() { return 5; }

  // CAS 敗北後のバックオフ。衝突が無ければ待ちゼロ・続いても合計最悪 ~300ms
  // （正しさには影響しない。収束を助けるだけ）。
  //
  // ⚠️ 他のワーカー（write-to-D1 / listen-worker）の同種ヘルパーは `Math.random` のジッターを使っているが、**このファイルでは使わない**。
  //    game-master-DO は「グループ分けが運営にも選べない公開値だけから決まる」ことが
  //    最大の抑止力で、それをファイル全体の `Math.random` 禁止という単純な検査で守っている
  //    （`report-vote-equilibrium-test.mjs`）。バックオフのために例外を作ると、
  //    後から採点・グループ分けに乱数が紛れ込んでも検査が鳴らなくなる。
  //    ここの競合相手は listen-worker の1本だけで、一斉再試行の「お見合い」は起きないため、
  //    決定論的な線形バックオフで十分。
  r2CasBackoff(attempt) {
    return new Promise(r => setTimeout(r, Math.min(20 * (attempt + 1), 100)));
  }

  /**
   * R2 オブジェクトを「読む → 変える → 条件付きで書く」で更新する。
   * 読んだときの etag を条件にするので、読んだ後・書く前に誰かが書いていたら put が失敗し、
   * **読み直して差分を当て直す**。負けた側が組み立て済みの本文を書き直すと結局相手を消すので、
   * mutate は完成品ではなく**差分**として書くこと。
   *
   * @param {string} key
   * @param {Function} mutate - (data) => boolean|void  data をその場で書き換える。
   *                            `false` を返すと「変更不要」として書き込まない。
   * @returns {Promise<{ok:boolean, missing?:boolean, unchanged?:boolean, conflict?:boolean, error?:string}>}
   */
  async mutateR2ObjectWithCAS(key, mutate, { tag = 'r2' } = {}) {
    const MAX = GameMasterDO.R2_CAS_MAX_RETRIES;
    for (let attempt = 0; attempt < MAX; attempt++) {
      const object = await this.env.R2_BUCKET.get(key);
      if (!object) return { ok: false, missing: true };

      const etag = object.etag;
      let data;
      try {
        // P-2026-0822: `summary.json` は正準JSON検査を通してから読む。
        // ここは read-modify-write なので、書き戻しで `JSON.stringify` が正準化してしまい
        // 「非正準な公開物が黙って直った」ことになる。直る前に**気づけない**のが問題なので、
        // 既存の parse 失敗と同じ扱い（`{ok:false, error}` → 呼び出し元がエラーログ）にする。
        // ⚠️ 他のキーは素通し（偽陽性回避・lib/canonical-json.js の適用範囲コメント参照）。
        data = isCanonicalJsonRequiredKey(key)
          ? parseCanonicalJson(await object.text(), key)
          : await object.json();
      } catch (e) {
        return { ok: false, error: `parse error for ${key}: ${e.message}` };
      }

      if (mutate(data) === false) return { ok: true, unchanged: true };

      let res;
      try {
        res = await this.env.R2_BUCKET.put(key, JSON.stringify(data), {
          onlyIf: { etagMatches: etag },
          httpMetadata: { contentType: 'application/json' },
        });
      } catch (e) {
        // R2 の一時障害。ここは best-effort な部分更新に使われるので throw せず失敗を返す
        // （呼び出し元が「更新した」と誤ってログしないことが要点＝S3-011）。
        return { ok: false, error: `put failed for ${key}: ${e.message}` };
      }
      if (res !== null) return { ok: true };

      console.warn(`[${tag}] etag conflict on ${key}, retry ${attempt + 2}/${MAX}`);
      await this.r2CasBackoff(attempt);
    }
    return { ok: false, conflict: true, error: `CAS failed after ${MAX} retries: ${key}` };
  }

  /**
   * 集計結果で `summary.json` を公開する（**結果公開専用**）。
   *
   * 全体を差し替える書き込みなので、差分の当て直しでは済まない。
   * schema v1/v2 の再公開時だけ、既存オブジェクトに入っている `claimed` を
   * **新しい本文へ引き継いでから** etag 条件付きで書く。schema v3 は行別状態を
   * group overlay へ分離したため、封印対象 summary へ `claimed` を戻さない。
   *
   * ⚠️ グループ分け時・ゲームなし確定時の**新規作成**には使わない。
   *    あちらは「このブロックはこれから始まる」を宣言する権威的な作成で、
   *    リセット後の再実行では前回の claimed を**引き継いではいけない**（別世界の請求記録になる）。
   *    そちらは従来どおり `putR2ObjectOrThrow`。
   */
  async publishBlockSummaryPreservingClaims(blockNum, summary) {
    const key = `games/block${blockNum}/summary.json`;
    const MAX = GameMasterDO.R2_CAS_MAX_RETRIES;

    for (let attempt = 0; attempt < MAX; attempt++) {
      const object = await this.env.R2_BUCKET.get(key);

      // 既存が無ければ普通に作る（初回公開）。put-if-absent で同時作成の先客を消さない
      if (!object) {
        const res = await this.env.R2_BUCKET.put(key, JSON.stringify(summary), {
          onlyIf: { etagDoesNotMatch: '*' },
          httpMetadata: { contentType: 'application/json' },
        });
        if (res !== null) return true;
        continue; // 先客ができた → 読み直して引き継ぎ経路へ
      }

      let existing = null;
      try {
        // P-2026-0822: 既存 summary も正準JSON検査を通す。ここは `claimed` の引き継ぎ元に
        // するだけで、書き戻す本文は `JSON.stringify` なので出力は必ず正準になる。
        // 非正準な既存は「壊れた既存」と同じ扱い（引き継がず新しい本文で置き換える）。
        existing = parseCanonicalJson(await object.text(), key);
      } catch (e) {
        // 壊れた／非正準な既存は引き継ぎ元にしない（新しい本文で置き換える）。
        // ただし黙って落とさない: 請求済み表示が消えるので、理由をログに残す。
        console.error(`[r2] existing ${key} is unusable as a claim-carry-over source — replacing it: ${e.message}`);
        existing = null;
      }

      const legacyMutable = Number(summary?.schemaVersion || 1) < 3;
      const merged = existing && legacyMutable
        ? applyClaimsFromExistingSummary(summary, existing)
        : summary;

      const res = await this.env.R2_BUCKET.put(key, JSON.stringify(merged), {
        onlyIf: { etagMatches: object.etag },
        httpMetadata: { contentType: 'application/json' },
      });
      if (res !== null) return true;

      console.warn(`[r2] etag conflict on ${key}, retry ${attempt + 2}/${MAX}`);
      await this.r2CasBackoff(attempt);
    }

    // S3-011 と同じ思想: 権威的な公開アーティファクトが書けなかったら黙って進まない
    throw new Error(`[r2] failed to publish authoritative artifact ${key} after ${MAX} retries (etag conflict) — refusing to continue with missing public data`);
  }

  // R15-F1/S4: claimのたびにmanifest固定のlean summary全体を書き換えない。
  // 行別状態はグループ別overlay、ブロック集約はこの小さな可変overlayへ分離する。
  // root提出前の初期公開だけを担当し、既存overlay（請求後の値）は絶対に巻き戻さない。
  async publishInitialClaimStatus(blockNum, aggregate) {
    const key = `games/block${blockNum}/claim-status.json`;
    const existing = await this.env.R2_BUCKET.get(key);
    if (existing) return true;
    let res;
    try {
      res = await this.env.R2_BUCKET.put(key, JSON.stringify({
        schemaVersion: 1,
        blockNum,
        ...aggregate,
      }), {
        onlyIf: { etagDoesNotMatch: '*' },
        httpMetadata: { contentType: 'application/json' },
      });
    } catch (error) {
      throw new Error(`[r2] failed to publish claim status ${key}: ${error.message}`);
    }
    // null は並行作成の先客。存在を再確認し、無ければ権威的公開失敗として止める。
    if (res === null && !(await this.env.R2_BUCKET.get(key))) {
      throw new Error(`[r2] failed to publish claim status ${key} after conditional conflict`);
    }
    return true;
  }

  // S4: 行別 claimed の唯一のR2書込先。1グループ最大5人×各10 deposit＝最大55行に分割し、
  // manifest の artifactKeys には載せない。初期公開は create-only で、再集計が請求済み値を
  // 巻き戻さない。以後の双方向収束（0→1/1→0）は listen-worker が D1 から行う。
  async publishInitialClaimOverlays(blockNum, allGroupResults, depositorResults = [], opts = {}) {
    const groups = allGroupResults || [];
    const cursor = Number(opts.cursor ?? 0);
    const limit = Number(opts.limit ?? CALC_CLAIM_OVERLAYS_PER_UNIT);
    if (!Number.isSafeInteger(cursor) || cursor < 0 || cursor > groups.length) {
      throw new Error(`invalid claim overlay cursor: ${String(opts.cursor)}`);
    }
    if (!Number.isSafeInteger(limit) || limit < 1 || limit > CALC_CLAIM_OVERLAYS_PER_UNIT) {
      throw new Error(`invalid claim overlay unit limit: ${String(opts.limit)}`);
    }
    const end = Math.min(groups.length, cursor + limit);
    for (const group of groups.slice(cursor, end)) {
      const groupId = Number(group.groupId);
      const claims = [
        ...(group.members || []).map(member => ({
          role: 'player', id: String(member.uid), claimed: 0,
        })),
        ...(depositorResults || [])
          .filter(dep => Number(dep.groupId) === groupId)
          .map(dep => ({ role: 'depositor', id: String(dep.depositId), claimed: 0 })),
      ];
      await this.publishInitialGroupClaimOverlay(blockNum, groupId, claims);
    }
    return {
      processed: end - cursor,
      nextCursor: end,
      done: end >= groups.length,
      total: groups.length,
    };
  }

  async publishInitialGroupClaimOverlay(blockNum, groupId, claims) {
    const key = `games/block${blockNum}/claim-status/group${groupId}.json`;
    const existing = await this.env.R2_BUCKET.get(key);
    if (existing) return true;
    let res;
    try {
      res = await this.env.R2_BUCKET.put(key, JSON.stringify({
        schemaVersion: 1,
        blockNum,
        groupId,
        claims,
      }), {
        onlyIf: { etagDoesNotMatch: '*' },
        httpMetadata: { contentType: 'application/json' },
      });
    } catch (error) {
      throw new Error(`[r2] failed to publish group claim overlay ${key}: ${error.message}`);
    }
    if (res === null && !(await this.env.R2_BUCKET.get(key))) {
      throw new Error(`[r2] failed to publish group claim overlay ${key} after conditional conflict`);
    }
    return true;
  }

  async putR2Object(key, data) {
    try {
      await this.env.R2_BUCKET.put(key, JSON.stringify(data), {
        httpMetadata: {
          contentType: 'application/json'
        }
      });
      return true;
    } catch (error) {
      console.error(`Error writing R2 object ${key}:`, error);
      return false;
    }
  }

  // S3-011（2026-07-29）: **権威的な公開アーティファクト**用の書き込み。
  // putR2Object は例外を握って false を返すだけで、呼び出し側は戻り値を見ずに
  // 「書けた」とログしていた。第三者がグループ分けを再現・監査する中心データ
  // （game_groups.json / summary.json / game_results.json）が欠けたまま処理が進み、
  // block.js の締切表示だけが古いまま残る＝利用者が誤った残り時間を信じて
  // 発言・提出を逃す、という状態を作れてしまう。
  // ここは throw して、既存のリトライ機構（grouping の catch → failed → 再実行、
  // 集計ユニットのリトライ → park）に載せる。R2 put は冪等なので再実行は安全。
  //
  // 🔵 P-2026-0822（**書く側に正準JSON検査は要らない**）:
  //   本文は `putR2Object` の中で `JSON.stringify(data)` にして書く。`JSON.stringify` は
  //   `100.0` や `1e2` のような別表記を絶対に出さないので、**この経路の出力は定義上必ず正準**。
  //   だから読む側（`getR2Object` など）で「正準でない＝このパイプラインが書いたものではない
  //   （または公開後に編集された）」と断定できる。書く側で検査を足すと、同じ性質を
  //   二重に主張するだけで保証は1ミリも増えない。
  // B10-01: evidence-report.json は manifest の artifactKeys に載り、その sha256 が
  // manifestHash に入る。safeBlock は実行時のチェーン頭に依存するため、入力が同じ再集計でも
  // バイト列を動かす。初回公開は変えず、safeBlock 以外が完全一致する再公開だけを省略する。
  async publishEvidenceReportIdempotent(blockNum, report) {
    const key = `verification/block${blockNum}/evidence-report.json`;
    let existingText = null;
    try {
      existingText = await this.getR2Text(key);
    } catch (error) {
      // 読めないときは従来どおり無条件 put へフェイルオープンするが、冪等化の無効化を黙らせない。
      console.warn(`[evidence] idempotent re-publish disabled for ${key} (read failed): ${error?.message || error}`);
      existingText = null;
    }
    if (existingText != null) {
      try {
        const existing = JSON.parse(existingText);
        const withoutObservation = (value) => {
          const { safeBlock, ...rest } = value;
          return JSON.stringify(rest);
        };
        if (existing && typeof existing === 'object' && !Array.isArray(existing)
            && withoutObservation(existing) === withoutObservation(report)) {
          return true; // 観測高さ以外が完全一致＝既存バイト列を保つ
        }
      } catch { /* 壊れた既存は従来どおり上書きする */ }
    }
    return await this.putR2ObjectOrThrow(key, report);
  }

  async putR2ObjectOrThrow(key, data) {
    const ok = await this.putR2Object(key, data);
    if (!ok) {
      throw new Error(`[r2] failed to publish authoritative artifact ${key} — refusing to continue with missing public data`);
    }
    return true;
  }
  // 管理txの運転者用制御面。通常のintent委譲とは独立した固定経路。
  async handleAdminTxControl(request, path) {
    if (!this.verifyApiSecret(request)) return createCORSResponse({ error: 'Unauthorized' }, 401);
    if (!this.env.ADMIN_TX_COORDINATOR?.fetch) {
      return createCORSResponse({ error: 'coordinator_binding_missing' }, 503);
    }
    try {
      const response = await this.env.ADMIN_TX_COORDINATOR.fetch(new Request(
        `https://admin-tx-coordinator${path === '/reset-admin-tx' ? '/reset' : '/status'}`, {
          method: request.method, headers: { 'X-Api-Secret': this.env.API_SECRET },
        },
      ));
      return createCORSResponse(await response.json(), response.status);
    } catch {
      return createCORSResponse({ error: 'coordinator_unavailable' }, 503);
    }
  }

}

// formGroups Step 3b。非主要の i % G は維持し、主要だけを言語塊の順で連続配置する。
function dealMixedGroups(ordered, majorSet, groups, idRef) {
  const majors = ordered.filter(p => majorSet.has(normalizeLang(p.data?.lang)));
  const minors = ordered.filter(p => !majorSet.has(normalizeLang(p.data?.lang)));
  const P = ordered.length;
  const G = Math.max(Math.floor(P / GROUP_SIZE), Math.ceil(P / (GROUP_SIZE + 1)));
  const bins = Array.from({ length: G }, () => ({ majors: [], minors: [] }));
  for (let i = 0; i < minors.length; i++) bins[i % G].minors.push(minors[i]);
  let cursor = 0;
  for (let k = 0; k < G; k++) {
    const size = Math.floor(P / G) + (k < P % G ? 1 : 0);
    const q = size - bins[k].minors.length;
    if (q < 0) throw new Error(`formGroups: negative major quota for mixed group ${k}`);
    bins[k].majors = majors.slice(cursor, cursor + q);
    cursor += q;
  }
  if (cursor !== majors.length) throw new Error('formGroups: mixed major quotas do not sum to major count');
  for (const bin of bins) {
    groups.push({ groupId: idRef.v++, mixed: false, lang: null, members: [...bin.majors, ...bin.minors] });
  }
}
